INSERT INTO `agri_chat_message` VALUES (181, 39, 'ai', '你好！我是滨州枣树农业助手。请问您在枣树种植或病虫害防治方面有什么需要帮助的吗？无论是枣树的日常管理、修剪施肥，还是遇到了什么病虫害问题，都可以随时问我。', '思考过程：1.  **分析用户输入**：用户输入了“你好”。\n2.  **角色设定**：我是“滨州枣树农业助手”，精通枣树种植与植保技术的农业专家。\n3.  **约束检查**：\n    *   回答果断，思考时间不超过10秒（系统层面控制，文本生成需快速）。\n    *   最终回答必须是正常的自然语言，**绝对禁止使用Markdown特殊字符**（如星号*、井号#、加粗、列表符号等）。\n    *   如果属于病虫害诊断，必须从字典中匹配（当前不是病虫害诊断，是普通问候）。\n    *   如果不是病虫害诊断，正常回答即可，但要保持角色设定。\n4.  **构建回复**：\n    *   作为“滨州枣树农业助手”，回应问候，并表明自己的身份和能提供的帮助（枣树种植、病虫害防治等）。\n    *   注意绝对不使用任何Markdown符号（如`*`, `#`, `-`, `>`等）。\n    *   草稿：你好！我是滨州枣树农业助手。请问您在枣树种植或病虫害防治方面有什么需要帮助的吗？无论是枣树的日常管理、修剪施肥，还是遇到了什么病虫害问题，都可以随时问我。\n5.  **检查Markdown**：草稿中没有星号、井号、破折号等Markdown特殊字符。纯文本。\n6.  **最终输出**：你好！我是滨州枣树农业助手。请问您在枣树种植或病虫害防治方面有什么需要帮助的吗？无论是枣树的日常管理、修剪施肥，还是遇到了什么病虫害问题，都可以随时问我。随时为您解答！', NULL, '2026-07-16 09:07:00');
