INSERT INTO `ld_agri_weather_live` VALUES (46, '3', '2026-07-17 16:30:08', '2026-07-17 16:08:00', 23.00, 96, '东风', 11.00, 2, 1.00, 986.00, '104', '阴', 1, '{\"code\":\"200\",\"updateTime\":\"2026-07-17T16:18+08:00\",\"fxLink\":\"https://www.qweather.com/weather/tai\'an-101120801.html\",\"now\":{\"obsTime\":\"2026-07-17T16:08+08:00\",\"temp\":\"23\",\"feelsLike\":\"25\",\"icon\":\"104\",\"text\":\"阴\",\"wind360\":\"90\",\"windDir\":\"东风\",\"windScale\":\"2\",\"windSpeed\":\"11\",\"humidity\":\"96\",\"precip\":\"1.0\",\"pressure\":\"986\",\"vis\":\"27\",\"cloud\":\"91\",\"dew\":\"21\"},\"refer\":{\"sources\":[\"QWeather\"],\"license\":[\"QWeather Developers License\"]}}');
INSERT INTO `ld_crop_variety` VALUES (1, 1, '保麦1号', '苏审麦201006', '2010.1', 0, '江苏省农作物品种审定委员会', '江苏保丰集团公司', '烟辐188/徐州24', '适宜江苏省淮北麦区种植', '幼苗半匍匐，叶色深绿，抗寒性较好。分蘖力较强，成穗数较多，株型较松散，穗层整齐，株高适中，茎秆弹性较好，抗倒性较好。纺锤型穗，穗中等大小，结实性较好，长芒、白壳、白粒，籽粒半硬质。区试平均结果：全生育期230.0天，与对照淮麦18相当；株高82.8厘米，每亩有效穗41.7万，每穗33.0粒，千粒重38.6克。接种鉴定结果：感赤霉病、纹枯病、白粉病，高抗黄花叶病。经农业部谷物品质监督检验测试中心测定，2007-2009年度两年平均结果：容重822克/升，粗蛋白含量12.9%，湿面筋含量24.4%，稳定时间3.4分钟。产量和抗性表现：2007-2009年度参加江苏省区域试验，两年平均亩产520.2公斤，较对照淮麦18增产6.0%。2009-2010年度参加生产试验，平均亩产527.4公斤，较对照淮麦20增产6.6%。', '适期播种，合理密植，科学施肥，及时防治病虫害。注意防治纹枯病、赤霉病、白粉病等主要病害。', 1, '2025-07-22 09:09:49', '2025-08-06 16:45:37');
INSERT INTO `ld_crop_variety` VALUES (2, 1, '金丰麦1号', '苏审麦20190002', '2019.11', 0, '江苏省农作物品种审定委员会', '江苏金色农业股份有限公司', '小簇麦/扬麦158 //意大利（引5），参试名称\"金丰15-6\"', '江苏省淮南麦区', '春性中熟小麦品种，成熟期比对照扬麦20早2天。幼苗半直立，叶色中等，分蘖力中等。株型半紧凑，抗倒性较好。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒硬质。区试平均结果：全生育期199.9天，比对照扬麦20早熟2天。株高78.2厘米，每亩有效穗32.9万，每穗36粒，千粒重44.7克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（单花滴注鉴定抗赤霉病，严重度1.5、1.1；自然发病鉴定中抗赤霉病，病情指数0.1、3.57），高感纹枯病、白粉病，中感叶锈病，高抗条锈病、黄花叶病毒病。经江苏省农科院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重818g/L、792g/L，粗蛋白(干基)16.61%、15.69%，湿面筋35.1% 、32.5%，吸水率67.8%、64.5%，稳定时间9.5min、4.5min，最大拉伸阻力491E.U.、304E.U.，拉伸面积108cm2、80cm2，硬度指数66.7、62.1。2017年检测结果达中强筋小麦品种标准。产量和抗性表现：2016-2018年度参加江苏省淮南组小麦品种区域试验，两年平均亩产486.4公斤，较对照扬麦20增产4.64％，两年均达极显著水平。2018-2019年度参加生产试验，平均亩产523.9公斤，较对照扬麦20增产4.63％。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗16万左右，中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40％，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:09:49', '2025-07-22 09:09:49');
INSERT INTO `ld_crop_variety` VALUES (3, 1, '济麦22', '国审麦2006012', '2006', 0, '国家农作物品种审定委员会', '山东省农业科学院作物研究所', '济南17/济麦20', '适宜黄淮冬麦区北片种植', '幼苗半直立，叶片宽大，叶色浓绿。分蘖力强，成穗率高，抗寒性好。株型紧凑，株高适中，茎秆粗壮，抗倒伏能力强。穗纺锤型，结实性好，籽粒角质，饱满度好。全生育期240天，株高75-80厘米。中抗条纹花叶病毒，感纹枯病、白粉病。产量稳定，抗逆性强，适应性广。', '适期播种，合理密植，重视基肥施用，注意防治纹枯病和蚜虫等病虫害。', 1, '2025-07-22 09:09:49', '2025-07-22 09:09:49');
INSERT INTO `ld_crop_variety` VALUES (4, 1, '中研麦0709', '苏审麦20160006', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏苏乐种业科技有限公司', '西农979/郑麦9023', '江苏省沿淮麦区', '特征特性：弱春性中熟小麦品种，成熟期比对照郑麦9023晚近1天。幼苗半匍匐，旗叶较宽、上挺，叶色绿。分蘖力强，越冬抗寒性、抗倒春寒性中等。株型较紧凑，穗层整齐，抗倒性较好。抽穗期较早，灌浆速度较快，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒硬质。区试平均结果：全生育期215.6天，株高74.2厘米，每亩有效穗39.0万，每穗34.4粒，千粒重43.5克。经江苏省农科院植保所三年接种鉴定：中感赤霉病（严重度2.33-3.26），中感纹枯病，高感白粉病，高感黄花叶病毒病。经江苏省农科院粮作所鉴定：中抗穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：容重810克/升，粗蛋白含量12.8%，湿面筋含量25.6%，稳定时间5.0分钟，硬度指数71.2。产量和抗性表现：2013-2015年度参加江苏省淮北片晚播组小麦区域试验，两年平均亩产520.1公斤，较对照郑麦9023增产8.0%，两年均达极显著水平，较对照淮麦20增产2.0%，增产不显著。2015-2016年度参加生产试验，平均亩产534.4公斤，较对照郑麦9023增产10.0%，较对照淮麦20增产2.5%。', '1、适宜播期10月下旬。2、适期播种每亩基本苗17万左右，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯氮18公斤左右，配合施用磷钾肥及微肥。氮肥基苗肥占60%，拔节孕穗肥占40%。抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱，遇冬春降水不足时，应及时浇水。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (5, 1, '中研麦1号', '苏审麦201104', '2011.10', 0, '江苏省农作物品种审定委员会', '连云港市苏乐种业科技有限公司             北京分红科技发展有限公司', '豫麦54/周麦9号', '适宜江苏省沿淮麦区种植', '退出批次：特征特性：该品种表现幼苗半匍匐，叶色深绿，长势一般抗寒性和抗倒春寒能力较强分蘖力中等，春季返青起身早，抽穗扬花早，成穗数多株型较紧凑，茎秆韧性较好，抗倒能力较强穗层较整齐，熟相较好纺锤型穗，结实性一般长芒、白壳、白粒，籽粒半硬质区试平均结果：全生育期221.8天，与对照偃展4110 、郑麦9023相当；株高79.0厘米，每亩有效穗44.4万穗，每穗31.6粒，千粒重39.2克接种鉴定结果：感赤霉病、纹枯病、白粉病，抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2007-2010年度三年平均结果：容重814.3克/升，粗蛋白含量14.4%，湿面筋含量30.8%，稳定时间1.9分钟产量和抗性表现：2007-2010年度参加江苏省淮北迟播组试验，2007-2009年度两年平均亩产501.6公斤，较对照偃展4110增产2.1%，2008-2009年度增产达极显著水平2009-2010年度平均亩产478.4斤，较对照郑麦9023增产4.2%，增产达极显著水平2010-2011年度参加生产试验，平均亩产532.3公斤，较对照郑麦9023增产8.0%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (6, 1, '仪宁小麦', '苏种审字第182号', '1993', 0, '江苏省农作物品种审定委员会', '仪征市种子站,江都县植保所', '仪5-2Co60辐射', '江苏淮南麦区', '退出批次：特征特性：幼苗半直立，繁茂性较好。株高98厘米左右，株型略松散。茎杆较粗壮，叶片较长略披，叶色深绿。分蘖力中等偏强，成穗率较高，每亩穗数29.0万左右。长芒、白壳、红粒，穗纺缍形穗长码稀，每穗实粒数31粒左右，籽粒均匀、饱满，千粒重38克。容重801克/公斤。出粉率70.4%，粗蛋白含量12.6%，湿面筋含量34.8%，干面筋含量11.9%，面团形时间、稳定时间分别为2分、3.8分钟，衰减度132Bμ.综合评分38分，比扬麦5号高4分.全生育期210天左右，拔节后生长速度加快，抽穗前后叶色转浓绿.耐寒性、抗旱性、耐肥抗倒性均好于场麦5号。高抗梭条花叶病，并具广谱抗性，纹枯商较轻。感染赤霉病和白粉病，穗层整齐度稍差。产量和抗性表现：1990、1991年连续两年参加淮北片小麦品种区域试验，平均单产分别人274.9公斤和315.2公斤，比扬麦5号分别增产4.3%(不显著)7.9%(极显著)。1992年参加省生产试验平均单产348.5公斤，比杨麦5号增产17.7%(病区试验结果).', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (7, 1, '佳源麦1号', '苏审麦20190011', '2019.11', 0, '江苏省农作物品种审定委员会', '淮安银宇经济作物研究种中心', '苏麦3号//淮麦21/宁麦13，参试名称“康F”', '江苏省沿淮麦区', '特征特性：属偏春性中熟小麦品种，幼苗半匍匐，长势健壮，分蘖力较强，成穗数中等，抗寒性一般。株型较松散，叶色淡绿。穗层较整齐，抗倒性一般。熟相较好。穗纺锤形、黄绿色、小穗排列稀，长芒、白壳、红粒，籽粒半硬质，饱满度较好。区试平均结果：全生育期219.4天，比对照淮麦20晚熟1.2天。株高84.0厘米，每亩有穗数39.5万，每穗36粒，千粒重38.0克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（单花滴注鉴定抗赤霉病，严重度1.35、1.26；自然发病鉴定中抗赤霉病，病情指数0.3、5.47），高感白粉病、叶锈病，感纹枯病，抗黄花叶病，高抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重825g/L、824g/L，蛋质（干基）15.61%、15.01%，湿面筋29.7%、31.9%，吸水率54.3%、55.0%，稳定时间3.3min、3.6min，最大拉伸阻力433E.U.、195E.U.，拉伸面积87cm2、53cm2，硬度指数46.1、52.1。产量和抗性表现：2016-2018年度参加江苏省淮北组小麦区域试验，两年平均亩产481.34公斤，比对照淮麦20减产7.19%。2018-2019年度参加生产试验平均亩产569.20公斤，比对照淮麦20减产0.24%。', '1、适宜播期10月25日-11月5日。2、适期播种每亩基本苗16万左右，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮16公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治白粉病、纹枯病、赤霉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (8, 1, '保麦158', '苏审麦20190008', '2019.11', 0, '江苏省农作物品种审定委员会', '江苏保丰集团公司', '保丰048/徐麦7086，参试名称“保丰1581”', '江苏省淮北麦区', '特征特性：属半冬性中熟小麦品种。幼苗半匍匐，叶色青绿。分蘖力较强，抗寒性较好。株型较紧凑，穗层整齐，抗倒性好。拔节起身较早，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒长圆形，硬质。区试平均结果：全生育期219.4天，比对照淮麦20早熟0.5天。株高78厘米，每亩有效穗39.9万，每穗35粒，千粒重44.0克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：感赤霉病（单花滴注鉴定感赤霉病，严重度3.74、2.86；自然发病鉴定感赤霉病，病情指数13.4、40.4），高感白粉病、纹枯病、叶锈病，中抗条锈病，抗黄花叶病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业部谷物品质监督检验测试中心测定：容重816g/L、810g/L，蛋白质（干基）14.89%、15.18%，湿面筋26.6%、29.9%，吸水率53.3%、56.8%，稳定时间12.6min、5.3min，最大拉伸阻力666E.U.、281E.U.，拉伸面积102cm2、66cm2，硬度指数52.8、47.8。产量和抗性表现：2016-2018年度参加江苏省淮北组小麦品种区域试验，两年平均亩产561.29公斤，比对照淮麦20增产6.20%。2018-2019年度参加生产试验平均亩产592.56公斤，比对照淮麦20增产7.29%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗12万-16万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮18公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (9, 1, '保麦218', '苏审麦201503', '2015', 0, '江苏省农作物品种审定委员会', '江苏保丰集团公司', '淮麦20/周麦18', '江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶片宽长，叶色深绿分蘖力强，起身拔节早，抗寒性一般株型较紧凑，抗倒性中等，熟相好穗纺锤形，长芒、白壳、白粒，籽粒长圆形、半硬质区试平均结果：全生育期231.3天，比对照略早熟，株高83.2厘米，每亩有效穗42.7万，每穗32.7粒，千粒重44.6克抗病性经江苏省农科院植保所三年接种鉴定：感赤霉病、纹枯病，中感白粉病，感小麦黄花叶病毒病品质经农业部谷物品质监督检验测试中心测定，两年区试测定平均结果：容重794克/升，粗蛋白含量13.6%，湿面筋含量28.2%，稳定时间1.9分钟，硬度指数65.7产量和抗性表现：2012-2014年度参加江苏省淮北组小麦区域试验，两年平均亩产554.04公斤，较对照淮麦20增产4.67％，两年增产均达极显著水平2014-2015年度参加生产试验，平均亩产543.54公斤，较对照淮麦20增产3.96％', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (10, 1, '保麦2号', '苏审麦201205', '2012.11', 0, '江苏省农作物品种审定委员会', '江苏保丰集团公司', '保丰3-2-16/烟辐188', '江苏省淮北麦区种植', '退出批次：特征特性：该品种表现幼苗半匍匐，叶色深绿，长势一般抗寒性和抗倒春寒能力较强分蘖力中等，春季返青起身早，抽穗扬花早，成穗数多株型较紧凑，茎秆韧性较好，抗倒能力较好穗层较整齐，熟相较好纺锤型穗，结实性一般长芒、白壳、白粒，籽粒半硬质区试平均结果：全生育期240.4天，与对照相当，株高75.5厘米，每亩有效穗38.5万穗，每穗34.9粒，千粒重42.2克接种鉴定结果：感赤霉病、纹枯病、白粉病，高抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2009-2011年度两年平均结果：容重789.0克/升，粗蛋白含量14.2%，湿面筋含量32.0%，稳定时间6.4分钟产量和抗性表现：2009-2011年度参加江苏省淮北组小麦区域试验，两年平均亩产534.4公斤，较对照淮麦20增产6.3%，两年较对照增产均达极显著水平2010-2011年度参加生产试验，平均亩产544.5斤，较对照增产6.4%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (11, 1, '保麦330', '苏审麦20170006', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏保丰集团公司', '周98165/淮麦18，参试名称“保科麦1330”', '江苏省淮北麦区', '特征特性：半冬性中熟小麦品种。成熟期与对照淮麦20相当。幼苗半匍匐，叶片宽长，叶色深绿，分蘖力较强，抗寒性一般。株型较紧凑，穗层较整齐，抗倒性中等。熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒卵圆形，籽粒半硬质-硬质。区试平均结果：全生育期232.8天，株高87.5厘米，每亩有效穗40.7万，每穗35.2粒，千粒重45.4克。病害鉴定：中感赤霉病（严重度2.74-2.65），高感白粉病、纹枯病、黄花叶病。经江苏省农科院粮作所鉴定：中抗穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：粗蛋白（干基）15.4%，湿面筋30.0%，吸水量52.1ml/100g，稳定时间8.4 分钟，最大拉伸阻力368（Rm,135E.U），拉伸面积70 cm2。产量和抗性表现：2014-2016年度参加江苏省淮北组小麦区域试验，两年平均亩产574.7公斤，较对照淮麦20增产4.8%。2016-2017年度参加生产试验，平均亩产579.8公斤，较对照淮麦20增产6.5%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗13万-17万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮18公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (12, 1, '保麦5号', '苏审麦201403', '2014', 0, '江苏省农作物品种审定委员会', '江苏保丰集团公司', '周麦16//淮麦18/烟辐188', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶片宽厚，叶色深绿分蘖力强，起身拔节迟，抗寒性较好株型较紧凑，茎秆粗壮弹性较好，抗倒性较强，熟相较好穗纺锤形，长芒、白壳、白粒，籽粒长圆形、半硬质区试平均结果：全生育期235.0天，比对照长1-2天，株高80.1厘米，每亩有效穗42.0万，每穗32.7粒，千粒重40.6克抗病性经江苏省农科院植保所2011-2013年接种鉴定：感赤霉病，抗白粉病，中感纹枯病，中抗小麦黄花叶病毒病品质经农业部谷物品质监督检验测试中心测定，2011-2013年两年结果：容重835/779.0克/升，粗蛋白含量13.5/15.5%，湿面筋含量27.0/34.3%，稳定时间2.1/12.5分钟，硬度指数48.6/63.2产量和抗性表现：2011-2013年度参加江苏省淮北组小麦区域试验，两年平均亩产523.8公斤，较对照淮麦20增产5.2％，两年增产均达极显著水平2013-2014年度参加生产试验，平均亩产609.6公斤，较对照淮麦20增产6.4％', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (13, 1, '保麦6号', '苏审麦201505', '2015', 0, '江苏省农作物品种审定委员会', '江苏保丰集团公司', '周麦16／烟农19', '江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶片宽长，剑叶宽厚，叶色深绿分蘖力较强，抗寒性较好株型较紧凑，茎秆粗壮弹性较好，抗倒性较好，熟相较好穗纺锤形，长芒、白壳、白粒，籽粒长圆形、硬质区试平均结果：全生育期235.0天，比对照长1.7天，株高79.1厘米，每亩有效穗41.5万，每穗34.8粒，千粒重38.9克抗病性经江苏省农科院植保所三年接种鉴定：感赤霉病、纹枯病，高感白粉病，抗小麦黄花叶病毒病品质经农业部谷物品质监督检验测试中心测定，两年区试测定平均结果：容重824克/升，粗蛋白含量13.9%，湿面筋含量29.2%，稳定时间26.0分钟，硬度指数65.1产量和抗性表现：2011-2013年度参加江苏省淮北组小麦区域试验，两年平均亩产526.85公斤，较对照淮麦20增产5.77％，两年增产均达极显著水平2014-2015年度参加生产试验，平均亩产555.08公斤，较对照淮麦20增产6.18％', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (14, 1, '兴农麦9号', '苏审麦20220029', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏神农大丰种业科技有限公司、兴化市兴润种业有限公司', '扬麦20/镇麦168', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，叶色深绿，分蘖力较强。株型较紧凑，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒角质。联合体区域试验平均结果：全生育期201.4天，比对照扬麦20短1.0天，株高82.4厘米，每亩有效穗29.5万，每穗41.0粒，千粒重45.0克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.00、2.45；自然发病鉴定中抗赤霉病，病情指数0.48、7.28），高感白粉病、纹枯病、叶锈病，感黄花叶病毒病，中抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重812g/L、802g/L，粗蛋白质含量（干基）14.7%、15.2%，湿面筋含量34.7%、34.8%，吸水率67%、60%，稳定时间5.0min、5.4min，最大拉伸阻力211E.U.、295E.U.，拉伸面积56cm2、85cm2，硬度指数67.2、65.5。产量和抗性表现：2019-2021年度参加江苏省淮南小麦神农大丰企业联合体区域试验，两年平均亩产465.1公斤，比对照扬麦20增产4.9%。2021-2022年度参加生产试验，平均亩产548.0公斤，比对照扬麦20增产5.1%。', '1、适宜播期10月25日至11月5日。2、基本苗适期播种每亩16万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病、叶锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (15, 1, '冀84-5418', '苏种审字第143号', '1991', 0, '江苏省农作物品种审定委员会', '江苏省种子站,徐州市种子站引进', '78-3147/石4414', '江苏淮北麦区', '退出批次：特征特性：幼苗半匍匐，前期生长稳健越冬性尚好。株高85厘米左右，株型较紧凑，较耐肥抗倒。分蘖力中等偏强，成穗率较高，春发性较好，易争足穗。省中间试验平均每亩穗数为44.8万左右，比济南13低1.1万左右。穗纺锤形，中等大小，着粒稀，长芒，白壳，带微黄色。每穗实粒数25粒左右，籽粒饱满均匀，角质，容重804克/升，千粒重38克左右，粗蛋白含量14.7—15.13 %，赖氨酸含量0.435%，湿在筋含量33%左右，灰分0.49%，富强粉出粉率70%左右。全生育期324天左右，比济南13早熟45天。高抗秆锈病，抗条锈病。常年赤霉病、纹枯病发生较轻，白粉病、叶枯病中等，在多阴雨、大群体情况下病害加重。中后期对肥水较敏感。拔节偏早，春季耐寒性一般，过早播种遇倒春寒，会导致基、顶部小穗不实。后期有叶尖枯现象，熟色欠佳。产量和抗性表现：1989、1990年连续参加省淮北小麦品种区域试验平均亩产分别 412.25公斤、389.97公斤，分居第一、二位，分别比济南增产23.4%、22.3%，增产均达极显著标准。1990年省生产试验亩产425.87公斤，比济南13增产36.24%，居首位。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (16, 1, '农麦152', '苏审麦20180009', '2018.12', 0, '江苏省农作物品种审定委员会', '江苏神农大丰种业科技有限公司', '新麦18/莱州817', '江苏省淮北麦区', '特征特性：属半冬性中熟小麦品种。幼苗匍匐，叶片细长，叶色淡绿。分蘖力强，抗寒性较好。株型较紧凑，穗层较整齐，抗倒性较好。拔节抽穗较迟，熟相好。穗纺锤形，长芒、白壳、白粒，籽粒卵圆形，硬质。区试平均结果：全生育期219.5天，成熟期比对照淮麦20早0.4天。株高85.5厘米（生试株高81.8厘米），每亩有效穗41.0万，每穗35.5粒，千粒重41.0克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：感赤霉病（严重度3.9-3.33）、感纹枯病，高感白粉病，中抗条锈病，中感叶锈病，高抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业部谷物品质监督检验测试中心（哈尔滨）测定，两年平均结果：粗蛋白（干基）14.6%，湿面筋31.3%，吸水量59.5ml/100g，稳定时间11.1min，最大拉伸阻力435E.U.，拉伸面积84cm2，硬度指数65.4，两年检测指标均达中强筋小麦品种标准。产量和抗性表现：2016-2018年度参加江苏省淮北组小麦区域试验，两年平均亩产554.1公斤，较对照淮麦20增产4.9％。2017-2018年度参加生产试验，平均亩产536.4公斤，较对照淮麦20增产4.9％。', '1、播种期。适宜播期10月10日-25日。2、种植密度。适期播种每亩基本苗12万-16万，推迟播种或肥力水平偏低应适当增加基本苗。3、肥水管理。一般亩施纯氮18公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，拔节孕穗肥要适当晚施，以复合肥为主，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝防旱。4、病虫草害防治。冬前及早春及时防除田间杂草，中后期做好赤霉病、纹枯病、白粉病和蚜虫等病虫害的防治工作。5、收获。蜡熟末期抓紧收获，确保丰产丰收。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (17, 1, '农麦156', '苏审麦20190004', '2019.11', 0, '江苏省农作物品种审定委员会', '江苏神农大丰种业科技有限公司', '扬辐麦4号/扬麦16，参试名称“农麦156”', '江苏省淮南麦区', '特征特性：属春性中熟小麦品种。幼苗半匍匐，叶色淡绿。分蘖力较强，抗寒性较好。株型较紧凑，穗层整齐，抗倒性较好。拔节起身较迟，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒卵圆形，硬质。区试平均结果：全生育期202.4天，比对照扬麦20晚熟0.5天。株高83.9厘米，每亩有效穗31.4万，每穗38粒，千粒重43.3克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（单花滴注鉴定中抗赤霉病，严重度2.42、1.32；自然发病鉴定中抗赤霉病，病情指数4.0、1.95），高感白粉病、纹枯病、叶锈病，感黄花叶病，高抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重813g/L、781g/L，蛋白质（干基）14.51%、15.50%，湿面筋31.0%、31.8%，吸水率65.6%、64.0%，稳定时间3.7min、3.2min，最大拉伸阻力270E.U.、235E.U.，拉伸面积54cm2、59cm2，硬度指数69.8、66.4。产量和抗性表现：2016-2018年度参加江苏省淮南组小麦品种区域试验，两年平均亩产484.45公斤，比对照扬麦20增产4.22%。2018-2019年度参加生产试验平均亩产494.96公斤，比对照扬麦20增产4.36%。', '1、播种期。适宜播期10月25日至11月10日。2、种植密度。适期播种每亩基本苗18万左右，中低产田适当增加播量。3、肥水管理。一般亩施纯氮18公斤左右，其中基苗肥占65%、拔节孕穗肥占35％，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，注意防涝抗旱。4、病虫草害防治。冬前及早春及时防除田间杂草，做好纹枯病、赤霉病、白粉病和蚜虫等防治工作。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (18, 1, '农麦158', '苏审麦20180011', '2018.12', 0, '江苏省农作物品种审定委员会', '江苏神农大丰种业科技有限公司', '新麦18/莱州817，参试名称“农丰148”', '江苏省淮北及沿淮麦区', '特征特性：属半冬性中熟小麦品种。幼苗半匍匐，叶片细长，叶色淡绿。分蘖力强，抗寒性较好。株型较紧凑，穗层较整齐，抗倒性较好。拔节抽穗较迟，熟相好。穗纺锤形，长芒、白壳、白粒，籽粒卵圆形，硬质。区试平均结果：全生育期216.8天，成熟期比对照淮麦20晚0.6天。株高86.0厘米（生试株高82.9厘米），每亩有效穗42.7万，每穗34.7粒，千粒重41.1克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中感赤霉病（严重度2.0-3.45），感纹枯病，高感白粉病、条锈病和叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：中抗穗发芽。经农业部谷物品质监督检验测试中心（哈尔滨）测定，两年平均结果：粗蛋白（干基）14.3%，湿面筋30.3%，吸水量59.5ml/100g，稳定时间11.6min，最大拉伸阻力390E.U.，拉伸面积71cm2，硬度指数67.5。产量和抗性表现：2015-2016年度参加江苏省淮北迟播组小麦区域试验，平均亩产542.4公斤，比对照淮麦30增产12.7%。2016-2017年度参加江苏省淮北组小麦区域试验，平均亩产572.3公斤，较对照淮麦20增产4.3％。2017-2018年度参加生产试验，平均亩产518.5公斤，较对照淮麦20增产4.6％。', '1、播种期。适宜播期10月10日-31日。2、种植密度。适期播种每亩基本苗12万-16万，推迟播种或肥力水平偏低应适当增加基本苗。3、肥水管理。一般亩施纯氮18公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，拔节孕穗肥要适当晚施，以复合肥为主，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝防旱。4、病虫草害防治。冬前及早春及时防除田间杂草，中后期做好赤霉病、纹枯病、白粉病和蚜虫等病虫害的防治工作。5、收获。蜡熟末期抓紧收获，确保丰产丰收。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (19, 1, '农麦177', '苏审麦20210029', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏神农大丰种业科技有限公司', '淮麦28/SN415，参试名称“农麦177”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿，幼苗长势旺，抗寒性较好，拔节起身较早，分蘖力较强。株型紧凑，蜡质较重，茎秆粗壮，抗倒性较好，剑叶短宽、挺，穗层整齐，灌浆快，结实性较好，熟相好。穗纺锤形，长芒、白壳、白粒，籽粒粉质。区试平均结果：全生育期223.8天，比对照淮麦20短1.7天。株高84.2厘米，每亩有效穗38.8万，每穗39.1粒，千粒重46.4克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度3.29、1.60、2.89；自然发病鉴定中感赤霉病，病指0.56、5.72、6.67），中抗条锈病，感纹枯病、黄花叶病，高感白粉病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：感穗发芽。经农业部谷物品质监督检验测试中心测定：容重820g/L、826g/L，蛋白质（干基）14.3%、14.6%，湿面筋含量30.2%、30.1%，吸水率53.3%、58.9%，稳定时间4.4min、4.9min，最大拉伸阻力243E.U.、211E.U.，拉伸面积51cm2、46cm2，硬度指数51.2、49.9。产量和抗性表现：2018-2020年度参加江苏省淮北小麦神农大丰科企联合体区试，两年平均亩产562.2公斤，比对照淮麦20增产5.6%。2020-2021年度参加生产试验，平均亩产566.3公斤，比对照淮麦20增产6.5%。', '1、适宜播期10月20日-30日。2、适期播种每亩基本苗14万-18万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯氮15公斤左右，配合施用磷钾肥。其中氮肥基苗肥占40%，拔节肥占40%，孕穗肥占20%。注意化控控高、防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (20, 1, '农麦180', '苏审麦20210022', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏神农大丰种业科技有限公司', '镇麦168/华麦5号，参试名称“农麦180”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色深绿，分蘖力中等。株型较松散，抗倒性较好。穗层较整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒半角质。区试平均结果：全生育期202.9天，比对照扬麦20短0.3天。株高86.1厘米，每亩有效穗28.7万，每穗39.3粒，千粒重47.5克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.55、1.33、1.80；自然发病鉴定中抗赤霉病，病指0、2.11、5.80），抗白粉病，中抗黄花叶病毒病，高感纹枯病、条锈病、叶锈病。经江苏省农业科学院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重810g/L、780g/L，粗蛋白(干基)含量14.6%、16.9%，湿面筋含量32.4%、38.9%，吸水率60.9%、63.6%，稳定时间4.3min、4.9min，最大拉伸阻力343E.U.、229E.U.，拉伸面积81cm2、50cm2，硬度指数61.2、61.5。产量和抗性表现：2018-2020年度参加江苏省淮南小麦神农大丰企业联合体区试，两年平均亩产460.2公斤，比对照扬麦20增产4.2%。2020-2021年度参加生产试验，平均亩产459.5公斤，比对照扬麦20增产5.6%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗16万左右，中低产田适当增加播量。3、一般亩施纯氮18公斤左右，其中基苗肥占65%、拔节孕穗肥占35%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，中后期做好纹枯病、赤霉病、白粉病和蚜虫等防治工作。5、蜡熟末期抓紧收获，确保丰产丰收。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (21, 1, '农麦188', '苏审麦20200028', '2020.11', 0, '江苏省农作物品种审定委', '江苏神农大丰种业科技有限公司', '漯麦 9920/扬麦 11，参试名称“农麦 188”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗匍匐，叶色淡绿。分蘖力强，成穗数较高，抗寒性较好。株型较紧凑，穗层整齐，抗倒性较好。拔节抽 穗较迟，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒长圆形、角质。 区试平均结果:全生育期 224.3 天，比对照淮麦 20 短 1.2 天。株高 79.8 厘米，每亩有效穗 40.8 万，每穗 36.1 粒，千粒重 46.1 克。经江苏省农 业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定:中 感赤霉病(接种鉴定中抗赤霉病，严重度 2.3、2.1;自然发病鉴定中感 赤霉病，病指 1.0、3.90)，中抗条锈病，中感黄花叶病毒病，感纹枯病， 高感白粉病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所 鉴定:高感穗发芽。经农业部谷物品质监督检验测试中心测定:容重 832g/L、833g/L，蛋白质(干基)15.5%、16.1%，湿面筋 35.6%、36.6%， 吸水率 63%、67%，稳定时间 5.6min、7.8min，最大拉伸阻力 279E.U.、 334E.U.，拉伸面积 56cm2、62cm2，硬度指数 68.2、62.9。产量和抗性表现：2018-2020 年度参加江苏省淮北小麦神农大丰科企联合体 区试，两年平均亩产 558.1 公斤，比对照淮麦 20 增产 4.8%。2019-2020 年度参加生产试验，平均亩产 579.7 公斤，比对照淮麦 20 增产 5.3%。', '1、适宜播期 10 月 10 日-25 日。2、适期播种每亩基 本苗 12 万-16 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯 氮 16 公斤左右，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗肥占 40%，拔节孕穗肥要适当晚施，以复合肥为主，抽穗扬花后结合防治病 虫害喷施叶面肥。田间沟系配套，注意防涝防旱。4、冬前及早春及时防 除田间杂草。注意防治纹枯病、赤霉病、白粉病、叶锈和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (22, 1, '农麦1号', '苏审麦201504', '2015', 0, '江苏省农作物品种审定委员会', '江苏神农大丰种业科技有限公司', '鲁麦21/SN668（淮麦18/矮抗58）', '江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶片较宽大，叶色深绿分蘖力较强，冬前分蘖多，抗寒性中等株型较紧凑，穗层较整齐，茎杆弹性较好，抗倒性较好灌浆快，熟相好穗纺锤形，长芒、白壳、白粒，籽粒卵圆形，半硬质-硬质区试平均结果：全生育期233.1天，较对照迟熟1.4天，株高85.6厘米，每亩有效穗44.3万，每穗32.9粒，千粒重39.6克抗病性经江苏省农科院植保所三年接种鉴定：感赤霉病，高感白粉病，中感纹枯病、小麦黄花叶病毒病品质经农业部谷物品质监督检验测试中心测定，两年区试测定平均结果：容重802克/升，粗蛋白含量14.5%，湿面筋含量29.8%，稳定时间18.3分钟，硬度指数47.0产量和抗性表现：2012-2014年度参加江苏省淮北组小麦区域试验，两年平均亩产547.50公斤，较对照淮麦20增产3.43％，两年增产均达极显著水平2014-2015年度参加生产试验，平均亩产548.57公斤，较对照淮麦20增产4.96％', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (23, 1, '农麦330', '苏审麦20220039', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏神农大丰种业科技有限公司', '淮麦33/淮麦30', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色淡绿，分蘖力较强。株型紧凑，穗层整齐，熟相较好。穗长方形，长芒、白壳、白粒，籽粒角质。联合体区域试验平均结果：全生育期223.3天，比对照淮麦20短1.7天，株高80.8厘米，每亩有效穗40.4万，每穗38.7粒，千粒重42.9克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中抗赤霉病，严重度1.10、2.30；自然发病鉴定中感赤霉病，病情指数5.71、22.50），高感白粉病、叶锈病，感纹枯病，中感条锈病，抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重834g/L、844g/L，粗蛋白质含量（干基）14.2%、15.3%，湿面筋含量34.1%、34.7%，吸水率65%、64%，稳定时间4.6min、6.0min，最大拉伸阻力201E.U.、233E.U.，拉伸面积49cm2、47cm2，硬度指数63.3、65.2。产量和抗性表现：2019-2021年度参加江苏省淮北小麦神农大丰科企联合体区域试验，两年平均亩产571.5公斤，比对照淮麦20增产4.2%。2021-2022年度参加生产试验，平均亩产597.1公斤，比对照淮麦20增产5.0%。', '1、适宜播期10月15日至30日。2、基本苗适期播种每亩15-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮18公斤左右，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (24, 1, '农麦55', '苏审麦20200017', '2020.11', 0, '江苏省农作物品种审定委', '盐城神农大丰种业科技有限公司', '烟 2801/镇麦 8 号，参试名称“农麦 165”', '江苏省淮北麦区晚茬', '特征特性：弱春性小麦品种。幼苗半匍匐，叶色淡绿。分蘖力较强，成穗数中等，抗寒性较好。株型较松散，穗层整齐，抗倒性较好。拔节 抽穗较迟，熟相较好。穗长方形，长芒、白壳、红粒，籽粒卵圆形、半 角质-角质。区试平均结果:全生育期 226.4 天，比对照淮麦 20 短 0.5 天。 株高 86.2 厘米，每亩有效穗 38.0 万，每穗 37.7 粒，千粒重 43.3 克。经 江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定:感赤霉病(接种鉴定感赤霉病，严重度 3.7、3.6;自然发病鉴定 感赤霉病，病指 30.6、0.3)，中感条锈病、黄花叶病毒病，高感白粉病、 纹枯病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定: 抗穗发芽。经农业部谷物品质监督检验测试中心测定:容重 808g/L、 812g/L，蛋白质(干基)15.1%、13.6%，湿面筋 32.8%、32.7%，吸水率 65%、62%，稳定时间 4.9min、2.9min，最大拉伸阻力 249E.U.、178E.U.， 拉伸面积 58cm2、38cm2，硬度指数 69.2、64.3。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦 B 组区试，两年平均 亩产 552.4 公斤，比对照淮麦 20 增产 3.6%。2019-2020 年度参加生产试 验，平均亩产 600.2 公斤，比对照淮麦 20 增产 4.6%。', '1、适宜播期 10 月 25 日-11 月 5 日。2、适期播种每 亩基本苗 16 万左右，推迟播种或肥力水平偏低应适当增加。3、一般亩 施纯氮 15-18 公斤，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗 肥占 40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注 意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治赤霉病、白粉 病、纹枯病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (25, 1, '农麦88', '苏审麦20160001', '2016.12', 0, '江苏省农作物品种审定委员会', '江苏神农大丰种业科技有限公司', '镇麦168/扬麦10号，参试名称“农丰88”', '江苏省淮南麦区无黄花叶病毒病田块种植', '特征特性：春性中熟小麦品种，成熟期比对照扬麦11晚1天左右。幼苗直立，叶色较深，分蘖力中等。株型较松散，茎杆粗壮，抗倒性中等。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒半硬质-硬质。区试平均结果：全生育期208.0天，株高83.1厘米，每亩有效穗32.0万，每穗39.0粒，千粒重40.9克。经江苏省农科院植保所三年接种鉴定：中抗赤霉病（严重度1.41-2.13），感纹枯病、白粉病、黄花叶病毒病。经江苏省农科院粮作所鉴定：高抗穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：容重781克/升，粗蛋白含量16.1%，湿面筋含量33.6%，稳定时间17.2分钟，硬度指数68.4。产量和抗性表现：2013-2015年度参加江苏省淮南组小麦区域试验，两年平均亩产483.6公斤，较对照扬麦11增产6.3%，两年均达极显著水平。2015-2016年度参加生产试验，平均亩产459.6公斤，较对照扬麦20增产3.9%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗18万左右，中低产田适当增加。3、一般亩施纯氮15-18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (26, 1, '华麦11', '苏审麦20210006', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', '淮麦19/扬麦13，参试名称“华麦1092（华麦1403）”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗半直立，叶色中等，分蘖力强。株型较松散，抗倒性较好。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒半角质。区试平均结果：全生育期209.8天，比对照扬麦20短1.4天。株高88.5厘米，每亩有效穗31.9万，每穗38.1粒，千粒重45.2克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.65、1.30、1.77；自然发病鉴定抗赤霉病，病指0、0、3.69），抗白粉病，中感条锈病、黄花叶病毒病，感纹枯病，高感叶锈病。经江苏省农业科学院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重799g/L、806g/L，粗蛋白(干基)含量15.6%、14.0%，湿面筋含量32.8%、30.0%，吸水率62.6%、65.2%，稳定时间14.5min、5.6min，最大拉伸阻力553E.U.、427E.U.，拉伸面积101cm2、89cm2，硬度指数62.9、64.1。2018-2019年度品质指标达强筋小麦品种审定标准。产量和抗性表现：2018-2020年度参加江苏省淮南小麦B组区试，两年平均亩产517.4公斤，比对照扬麦20增产4.5%。2020-2021年度参加生产试验，平均亩产468.1公斤，比对照扬麦20增产5.1%。', '1、适宜播期10月25日至11月10日。2、适期播种每亩基本苗16万左右，中低产田或迟播应适当增加。3、一般亩施纯氮15-18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草。注意防治纹枯病、白粉病、赤霉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (27, 1, '华麦118', '苏审麦20180010', '2018.12', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'PH85-16/济南17，参试名称“华麦DF118”', '江苏省淮北麦区', '特征特性：属半冬性中晚熟小麦品种。幼苗半匍匐，叶片短宽，叶色深。分蘖力较强，抗寒性较好。株型较紧凑，穗层不整齐，抗倒性中等。起身拔节迟，熟相较好。穗纺锤形，无芒、白壳、白粒，籽粒椭圆形，硬质。区试平均结果：全生育期228.4天，成熟期比对照淮麦20晚2.3天。株高92.1厘米（生试株高83.8厘米），每亩有效穗41.1万，每穗35.3粒，千粒重42.2克。经江苏省农业科学院植物保护研究所、江苏省徐淮地区徐州农科所鉴定：中感赤霉病（严重度1.7-3.39），感纹枯病，高感白粉病、叶锈病，抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：感穗发芽。经农业部谷物品质监督检验测试中心测定，两年平均结果：粗蛋白（干基）13.3%，湿面筋28.4%，吸水量64.4ml/100g，稳定时间12.6min，最大拉伸阻力481 E.U.，拉伸面积88cm2，硬度指数67.6。2017年检测粗蛋白（干基）13.5%，湿面筋28.6%，吸水量64.5ml/100g，稳定时间20.2min，最大拉伸阻力641 E.U.，拉伸面积110cm2，硬度指数68.5，达中强筋小麦品种标准。产量和抗性表现：2015-2017年度参加江苏省淮北组小麦区域试验，两年平均亩产559.1公斤，较对照淮麦20减产0.2％。2017-2018年度参加生产试验，平均亩产533.6公斤，较对照淮麦20增产4.3％。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗12万-14万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮16公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (28, 1, '华麦13', '苏审麦20210010', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', '扬麦158/小偃8788，参试名称“华麦1430”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗半直立，叶色绿，分蘖力较强。株型半松散，抗倒性较好。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒半粉质。区试平均结果：全生育期209.8天，比对照扬麦20短0.6天。株高83.7厘米，每亩有效穗32.5万，每穗38.8粒，千粒重43.0克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.4、2.8；自然发病鉴定中抗赤霉病，病指3.05、0.35），中感纹枯病，感黄花叶病毒病，高感白粉病、叶锈病、条锈病。经江苏省农业科学院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重790g/L、813g/L，粗蛋白(干基)含量13.7%、14.0%，湿面筋含量28.0%、30.8%，吸水率58.3%、56.4%，稳定时间2.7min、2.1min，最大拉伸阻力152E.U.、163E.U.，拉伸面积39cm2、38cm2，硬度指数57.3、50.3。产量和抗性表现：2017-2019年度参加江苏省淮南小麦B组区试，两年平均亩产492.7公斤，比对照扬麦20增产5.3%。2019-2020年度参加生产试验，平均亩产511.0公斤，比对照扬麦20增产5.8%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗16万左右，中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (29, 1, '华麦14', '苏审麦20210015', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', '扬麦20/生选6号，参试名称“华麦1038”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色深绿，分蘖力较强。株型半松散，抗倒性一般。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒半角质。区试平均结果：全生育期208.7天，与对照扬麦20相当。株高83.0厘米，每亩有效穗33.0万，每穗39.3粒，千粒重42.1克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.50、2.70；自然发病鉴定中抗赤霉病，病指2.55、0），感纹枯病、黄花叶病毒病，高感白粉病、叶锈病、条锈病。经江苏省农业科学院种质资源与生物研究所鉴定：高抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重782g/L、800g/L，粗蛋白(干基)含量13.9%、14.0%，湿面筋含量30.2%、28.4%，吸水率58.0%、58.3%，稳定时间2.9min、2.1min，最大拉伸阻力173E.U.，拉伸面积41cm2。产量和抗性表现：2017-2019年度参加江苏省淮南小麦省农科院科企联合体区试，两年平均亩产477.5公斤，比对照扬麦20增产5.5%。2019-2020年度参加生产试验，平均亩产527.2公斤，比对照扬麦20增产6.4%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗16万左右，中低产田适当增加。3、一般亩施纯氮15-18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (30, 1, '华麦15', '苏审麦20210016', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', '华麦5号/镇麦168，参试名称“华麦1177”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色深绿，叶片较大、剑叶较挺，分蘖力较强。株型半松散，抗倒性一般。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒半角质至粉质。联合体区试平均结果：全生育期206.9天，比对照扬麦20短0.8天。株高89.6厘米，每亩有效穗33.6万，每穗38.7粒，千粒重44.7克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.55、1.15、1.60；自然发病鉴定中抗赤霉病，病指0、0.53、1.86），中感黄花叶病毒病，高感纹枯病、白粉病、叶锈病、条锈病。经江苏省农业科学院种质资源与生物研究所鉴定：高抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重810g/L、802g/L，粗蛋白(干基)含量13.3%、13.7%，湿面筋含量29.5%、30.5%，吸水率61.0%、62.5%，稳定时间2.8min、3.0min。产量和抗性表现：2018-2020年度参加江苏省淮南小麦省农科院科企联合体区试，两年平均亩产513.2公斤，比对照扬麦20增产5.4%。2020-2021年度参加生产试验，平均亩产503.3公斤，比对照扬麦20增产5.1%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗16万左右，中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (31, 1, '华麦16', '苏审麦20210027', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', '济麦22/淮麦20，参试名称“华麦15056”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿。分蘖力较强，成穗数较多，抗寒性较好。株型较紧凑，抗倒性较好，穗层较整齐，熟相好，穗纺锤形，长芒、白壳、白粒，半角质。区试平均结果：全生育期225.6天，比对照淮麦20短0.9天。株高85.0厘米，每亩有效穗40.9万，每穗39.3粒，千粒重41.3克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度3.33、1.70、2.80；自然发病鉴定中感赤霉病，病指0.62、4.04、3.46），中感条锈病、黄花叶病，高感纹枯病、白粉病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业部谷物品质监督检验测试中心测定：容重761.6g/L、807.0g/L，蛋白质（干基）14.7%、14.4%，湿面筋含量31.4%、32.9%，吸水率51.1%、58.6%，稳定时间14.6min、5.4min，最大拉伸阻力515E.U.、257E.U.，拉伸面积95cm2、63cm2，硬度指数36.9、49.0。产量和抗性表现：2018-2020年度参加江苏省淮北小麦大华种业科企联合体区试，两年平均亩产583.7公斤，比对照淮麦20增产4.4%。2020-2021年度参加生产试验，平均亩产599.3公斤，比对照淮麦20增产7.2%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗18万-20万，推迟播种或肥力水平偏低应适当增加基本苗。3、建议总施氮量为16-18公斤/亩（氮肥基追比6∶4），配合施用磷、钾肥。在施足基肥的基础上，严格控制冬前和返青肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、锈病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (32, 1, '华麦1号', '苏审麦200402', '2004.8', 0, '江苏省农作物品种审定委员会', '江苏省徐州农垦农科所\\江苏省大华种业集团有限公司', '豫麦54/鲁麦14', '江苏淮北麦区', '退出批次：特征特性：该品种长芒、白壳、纺缍型穗，籽粒白皮、半硬质。幼苗半匍伏，分蘖力较强，株型较紧凑。全生育期较陕229短2天左右，株高85厘米左右，耐肥抗倒性较好，抗寒性好。每亩有效穗40万左右，每穗31粒左右，千粒重40克左右。接种定感赤霉病、中感纹枯病，抗病性与陕229相当。品质分析三年平均结果为粗蛋白含量14.7%，湿面筋含量25.8%，稳定时间9.8分钟，属中筋品种。产量和抗性表现：2001-2003年度参加江苏省区域试验，两年平均亩产468.7公斤，较对照陕229增产13.95%，两年增产均达极显著； 2003-2004年度组织生产试验，平均亩产528.8公斤，较对照陕229增产10.8%。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (33, 1, '华麦20', '苏审麦20220016', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'H0801/周麦16', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿。分蘖力较强，株型较紧凑，穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒半角质。省区域试验平均结果：全生育期226.6天，比对照淮麦20短0.9天，株高94.3厘米，每亩有效穗40.0万，每穗35.5粒，千粒重45.8克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：感赤霉病（接种鉴定感赤霉病，严重度1.85、3.67；自然发病鉴定中感赤霉病，病指2.55、14.06），高感叶锈病、白粉病、纹枯病，中感黄花叶病毒病，中抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重831g/L、838g/L，粗粗蛋白质含量（干基）13.8%、15.7%，湿面筋含量28.6%、32.5%，吸水率58%、58%，稳定时间9.0min、6.6min，最大拉伸阻力386E.U.、364E.U.，拉伸面积71cm2、68cm2，硬度指数46.9、52.3。产量和抗性表现：2019-2021年度参加江苏省淮北B组小麦品种区域试验，两年平均亩产587.9公斤，比对照淮麦20增产6.0%。2021-2022年度参加生产试验，平均亩产624.0公斤，比对照淮麦20增产5.8%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩16万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮15公斤左右，其中基苗肥占50%、拔节肥占40%、孕穗肥占10%，同时配合施用磷钾肥，后期适当喷施叶面肥。注意化控控高、防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (34, 1, '华麦21', '苏审麦20220018', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'H0892/周麦18', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿。分蘖力较强，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒半角质。省区域试验平均结果：全生育期228.6天，比对照淮麦20长1.1天，株高92.0厘米，每亩有效穗42.0万，每穗35.8粒，千粒重46.5克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度2.95、3.50；自然发病鉴定中感赤霉病，病指1.57、21.63），高感白粉病、纹枯病，中感条锈病、叶锈病，抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重838g/L、836g/L，粗蛋白质含量（干基）12.8%、14.7%，湿面筋含量27.0%、33.1%，吸水率65%、60%，稳定时间3.9min、3.4min，最大拉伸阻力183E.U.、213E.U.，拉伸面积37cm2、54cm2，硬度指数53.7、55.2。产量和抗性表现：2019-2021年度参加江苏省淮北B组小麦品种区域试验，两年平均亩产591.0公斤，比对照淮麦20增产6.5%。2021-2022年度参加生产试验，平均亩产629.8公斤，比对照淮麦20增产6.8%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩14万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤左右，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (35, 1, '华麦22', '苏审麦20220033', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', '连麦4号/淮麦35', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半直立，叶色绿，分蘖力较强。株型半紧凑，穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒角质。联合体区域试验平均结果：全生育期225.5天，比对照淮麦20短0.4天，株高86.5厘米，每亩有效穗42.8万，每穗35.0粒，千粒重44.0克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度2.75、3.65；自然发病鉴定中感赤霉病，病指2.11、8.44），高感条锈病、叶锈病、白粉病，感纹枯病，中抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重820g/L、828g/L，粗蛋白质含量（干基）13.2%、14.4%，湿面筋含量28.5%、28.4%，吸水率57%、61%，稳定时间8.9min、5.8min，最大拉伸阻力290E.U.、180E.U.，拉伸面积52cm2、37cm2，硬度指数50.3、57。产量和抗性表现：2019-2021年度参加江苏省大华种业科企淮北小麦联合体，两年平均亩产584.6公斤，比对照淮麦20增产7.0%。2021-2022年度参加生产试验，平均亩产608.4公斤，比对照淮麦20增产4.7%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩18万-20万，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤-18公斤，基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治锈病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (36, 1, '华麦2号', '苏审麦200702', '2007.9', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', '95F88/徐麦21', '适宜江苏省淮南麦区种植', '退出批次：特征特性：长芒，白壳，红粒，纺锤型穗，籽粒半硬-软质幼苗直立，叶片宽长，叶色淡绿分蘖力较强，成穗和穗粒数较多，千粒重稍低株型较松散，株高84厘米左右，耐肥抗倒性较强生育期211天左右，比对照长1天亩有效穗32万左右，每穗38粒左右，千粒重39克左右接种鉴定结果：中抗赤霉病，感纹枯病，高感梭条花叶病，高抗穗发芽田间表现中感纹枯病、白粉病品质分析两年平均结果：粗蛋白含量12.8%，湿面筋含量27.0%，稳定时间3.5分钟，属中筋品种产量和抗性表现：2004-2006年度参加江苏省区域试验，2004-2005年度平均亩产459.9公斤, 较对照扬麦158增产5.4％，2005-2006年度平均亩产446.0公斤，与对照扬麦11号相当，两年平均亩产453.0公斤，较对照扬麦11号增产0.11％；2006-2007年度组织生产试验，平均亩产424.5公斤，较对照扬麦11号增产6.1%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (37, 1, '华麦3号', '苏审麦200705', '2007.9', 0, '江苏省农作物品种审定委员会', '江苏盐城农垦农业科学研究所', '冀麦5418/豫麦34', '适宜江苏省沿淮麦区种植', '退出批次：特征特性：长芒，白壳，白粒，纺锤型穗，籽粒半硬质幼苗半直立，叶色深绿，抗寒性、抗倒春寒能力一般，分蘖力一般株型较紧凑，穗层整齐，熟相较好株高82厘米左右，抗倒性较好全生育期223天左右，与对照相当亩有效穗36万左右，每穗30粒左右，千粒重46克左右接种鉴定结果：感赤霉病、纹枯病，高感梭条花叶病，中抗穗发芽田间表现中感白粉病、纹枯病、赤霉病品质分析两年平均结果：粗蛋白含量13.9%，湿面筋含量30.9%，稳定时间8.8分钟，属强筋品种产量和抗性表现：2004-2006年度参加江苏省区域试验，两年平均亩产475.7公斤，较对照豫麦18增产6.8%；2006-2007年度组织生产试验，平均亩产460.7公斤，较对照增产6.3%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (38, 1, '华麦4号', '苏审麦200804', '2008.9', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', '湖西9701/豫展1号', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶色较深，苗壮，抗寒性较好分蘖力较强，成穗数较多株型较松散，茎杆弹性一般，抗倒性一般穗层整齐，熟相较好长芒，白壳，白粒，纺锤型穗，籽粒硬质-半硬质省区试平均结果：全生育期235天，与对照淮麦18相当；株高87.6厘米，每亩有效穗38.2万穗，每穗32.9粒，千粒重45.2克接种鉴定结果：感赤霉病，中感纹枯病、梭条花叶病毒病高感穗发芽经农业部谷物品质监督检验测试中心测定，三年平均结果:容重795克/升，粗蛋白含量14.2%，湿面筋含量31.2%，稳定时间3.8分钟产量和抗性表现：2004-2007年度参加江苏省区域试验，三年平均亩产519.8公斤，较对照淮麦18增产2.5%；2007-2008年度参加生产试验，平均亩产532.5公斤，较对照淮麦18增产5.3%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (39, 1, '华麦5号', '苏审麦201002', '2010.1', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', '扬麦158/PH82-2-2', '江苏省淮南麦区无黄花叶病田块种植', '退出批次：特征特性：幼苗半直立，叶片宽长，叶色淡绿分蘖力较强，成穗数中等春发性强，返青快，抗倒春寒性一般株高适中，株型偏松散，抗倒性较强长方形穗，长芒、白壳、红粒，籽粒卵圆形、半硬质、饱满度较好区试平均结果：全生育期207.3天，较对照迟熟1天；株高86.2厘米，每亩有效穗29.8万穗，每穗38.6粒，千粒重44.5克接种鉴定结果：抗赤霉病，感白粉病、纹枯病，高感黄花叶病经农业部谷物品质监督检验测试中心测定，2007-2009年度两年平均结果：容重790克/升，粗蛋白含量12.6%，湿面筋含量24.0%，稳定时间2.4分钟产量和抗性表现：2007-2009年度参加江苏省区域试验，平均亩产506.3公斤，较对照扬麦11号增产4.9％2009-2010年度参加生产试验，平均亩产426.9公斤，较对照扬麦11号增产7.6%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (40, 1, '华麦6号', '苏审麦201304', '2013', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', '扬麦13/苏麦6号', '适宜江苏省淮南麦区种植', '退出批次：特征特性：幼苗直立，叶片适中，叶色绿分蘖力较强，抗寒性较好株型偏紧凑，耐肥抗倒性较好穗层较整齐，穗纺锤型，穗大粒多，长芒、白壳、红粒，籽粒卵圆形，半硬质，饱满度好区试平均结果：全生育期211.1天，较对照迟熟2天；株高79.6厘米，每亩有效穗32.9万穗，每穗40.4粒，千粒重37.7克接种鉴定结果：中抗赤霉病，感纹枯病，中感白粉病，中抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2010-2012年度两年平均结果：容重841.0克/升，粗蛋白含量13.6%，湿面筋含量28.9%，稳定时间3.9分钟产量和抗性表现：2010-2012年度参加江苏省淮南组小麦区域试验，平均亩产455.5公斤，较对照扬麦11号增产6.5％，2010-2011年度增产达极显著水平2012-2013年度参加生产试验，平均亩产428.6公斤，较对照扬麦11号增产4.2%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (41, 1, '华麦7号', '苏审麦201402', '2014', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', '扬麦158/小偃8788', '适宜江苏省淮南麦区种植', '退出批次：特征特性：幼苗直立，叶色绿分蘖力较强株型较紧凑，抗倒性较好穗层整齐，后期熟相一般穗纺锤形，长芒、白壳、红粒，籽粒半硬质区试平均结果：全生育期210.9天，较对照成熟迟1-2天；株高84.6厘米，每亩有效穗31.8万，每穗38.4粒，千粒重41.6克抗病性经江苏省农科院植保所3年接种鉴定：中感赤霉病，感纹枯病、白粉病，高感小麦黄花叶病毒病品质经农业部谷物品质监督检验测试中心测定，区试3年平均结果：容重793.7克/升，粗蛋白含量13.3%，湿面筋含量28.5%，稳定时间4.6分钟，硬度指数64.6产量和抗性表现：2008-2010年度和2012-2013年度参加江苏省淮南组小麦区域试验，三年平均亩产482.3公斤，较对照扬麦11号增产6.7％，其中1年增产显著，2年增产极显著2013-2014年度参加生产试验，平均亩产468.5公斤，较对照扬麦11号增产6.5%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (42, 1, '华麦8号', '苏审麦20160003', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', '扬麦158/小偃8788，参试名称“华麦鉴3”', '江苏省淮南麦区', '特征特性：春性中熟小麦品种，成熟期比对照扬麦11晚1-2天。幼苗直立，叶色绿，分蘖力较强。株型较紧凑，抗倒性一般。穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒半硬质。区试平均结果：全生育期210.7天，株高76.3厘米，每亩有效穗33.2万，每穗38.4粒，千粒重40.4克。经江苏省农科院植保所三年接种鉴定：中抗赤霉病（严重度1.76-2.33），中感纹枯病，感白粉病，高抗小麦黄花叶病毒病。经江苏省农科院粮作所鉴定：抗穗发芽。品质经农业部谷物品质监督检验测试中心测定，三年平均结果：容重817克/升，粗蛋白含量14.6%，湿面筋含量31.9%，稳定时间6.5分钟，最大拉伸阻力283.3 E.U.，延伸性216毫米，硬度指数65.1。产量和抗性表现：2012-2014年度参加江苏省淮南组小麦区域试验，两年平均亩产485.2公斤，较对照扬麦11增产7.6%，两年均达极显著水平。2014-2015年度参加生产试验，平均亩产448.6公斤，较对照扬麦11增产5.8%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗15万左右。3、一般亩施纯氮15公斤左右，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (43, 1, '南农9918', '苏审麦200204', '2002', 0, '江苏省农作物品种审定委员会', '南京农业大学', '扬麦158/92R137', '江苏淮南麦区', '退出批次：特征特性：该品种长芒、白壳、穗型近长方形，籽粒红皮、半硬质，分蘖成穗数一般，大穗大粒，每亩有效穗27万左右，每穗粒数37粒左右，千粒重高，为45克左右，容重760克左右。株高100厘米左右，耐肥抗倒性一般，成熟期较扬麦158迟1天。赤霉病较轻，高抗白粉病，纹枯病、梭条花叶病毒病与扬麦158相仿。据2002年6月南京农业大学送样品质分析(农业部谷物品质检测中心)，粗蛋白含量10.4%，湿面筋29.7％，干面筋9.8％，沉降值35.6ml，吸水率59.3%，面团形成时间2.0min，面团稳定时间7.2min，属中筋品种。产量和抗性表现：1999-2001年参加省区域试验，1999-2000年度平均亩产402.63公斤，较对照扬麦158减产0.47％，不显著，居第3位；2000-2001年度平均亩产405.76公斤，较对照扬麦158增产2.84％，达显著水平，居第5位；两年平均亩产404.24公斤，较对照增产1.17%，不显著，居第3位。2001-2002年度参加淮南小麦生产试验，平均亩产348.17公斤，较对照扬麦158增产2.20%，居第3位。该品种有一定产量水平，抗病性好、品质较好。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (44, 1, '博爱7422', '苏种审字第67号', '1986', 0, '江苏省农作物品种审定委员会', '金湖县宝应湖农科从河南引进', '阿夫系选', '江苏淮北麦区南部', '退出批次：特征特性：幼苗半匍伏，株高95厘米左右。茎杆中粗，偏高稍软。耐肥抗倒性中等。叶片略宽上半。剑叶倒挂。分蘖力、成穗率中等。穗、粒、重协调，每亩穗数省区域试验和生产试验（下同）分别为35.1万、33.3万分别比郑州741多1.12万、5.55万穗。穗长方形，长芒、白壳、白粒，每穗实粒数分别为33.35粒、35粒，与郑州741相仿，略少0.59粒、略多0.37粒。粒形中等，千粒重较稳定，省中间试验平均为35克左右，分别比郑州741略低0.4—0.9克。容重746克/升左右，籽粒粉质至半角质，品质较好，精粉较高76.3%，灰分1.14%，粉质白，湿面筋含量较高，达29.6—35.1%，面团延伸性较好，15.6—18.8厘米，拉伸阻力为90BΜ。拉力好，能做馒头、面包，更适于做面条、饺皮。成熟略晚，全生育期231天左右，比郑州741迟熟2—3天。较抗条锈病，感叶锈、白粉病，中感杆锈病。抽穗期若多阴雨，感染赤霉病。常年大田发病较轻。成熟后期迂边阴雨，稍有穗发芽。播期幅度较宽，较耐迟播，稳产性、适应性较好。产量和抗性表现：1984年—85年参加淮北小麦组区域试验，1984年平均亩产788.5斤，比郑州741增产2.45，不显著；1985年亩产733.9斤，比郑州741增产2.1%，不显著。198年省生产试验亩产682.8斤，比郑州741增产1.12 %。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (45, 1, '宁中麦1号', '苏审麦20200032', '2020.11', 0, '江苏省农作物品种审定委', '江苏中江种业股份有限公司、江苏省农业科学院粮食作物研究所', '华麦 9128/新麦 9 号，参试名称“宁中 16-23”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗长势较慢，叶色绿，抗寒性较好，分蘖力较强。株型较紧凑，茎秆较粗壮，茎秆弹性较好，剑叶细长挺， 蜡质重。穗层整齐，灌浆较快。穗长方型，长芒、白壳、白粒，籽粒角 质。区试平均结果:全生育期 225.7 天，与对照淮麦 20 相当。株高 85.6 厘米，每亩有效穗 38.6 万，每穗 35.0 粒，千粒重 45.9 克。经江苏省农 业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定:感 赤霉病(接种鉴定感赤霉病，严重度 2.4、3.6，自然发病鉴定感赤霉病， 病情指数 11.0、1.3)，中感白粉病、叶锈病、条锈病，感纹枯病、黄花 叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定:高感 穗发芽。经农业部谷物品质监督检验测试中心测定:容重 781g/L，粗蛋 白(干基)15.3%、15.1%，湿面筋 34.5% 、34.5%，吸水率 55%、54%，稳 定时间 2.8min、3.4min，硬度指数 41.1。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦徐州农科所科企联合 体区试，两年平均亩产 544.4 公斤，比对照淮麦 20 增产 4.0%。2019-2020 年度参加生产试验，平均亩产 548.6 公斤，比对照淮麦 20 增产 4.2%。', '1、适宜播期 10 月 10 日-25 日。2、适期播种每亩基 本苗 12 万-16 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯氮 18 公斤，氧化钾、五氧化磷各 9 公斤。氮肥基肥:分蘖肥:拔节孕穗肥: 穗肥的比例为 5:1:2:2，磷、钾肥基肥:拔节孕穗肥的比例为 1:1，抽穗扬 花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬 前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病、锈病 和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (46, 1, '宁中麦2号', '苏审麦20220038', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所、江苏中江种业股份有限公司', '徐麦1618/淮麦20', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，长势较慢，叶色深绿。分蘖力较强。株型较松散，穂层较整齐，熟相较好。穗纺锤形，中大穗，长芒、白壳、白粒，籽粒半角质。联合体区域试验平均结果：全生育期230.1天，比对照淮麦20长1.1天，株高91.2厘米，每亩有效穗42.4万，每穗35.7粒，千粒重45.6克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度3.00、3.55；自然发病鉴定中感赤霉病，病指2.73、8.57），高感白粉病、纹枯病，中感叶锈病，中抗条锈病、黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重842g/L、828g/L，粗蛋白质含量（干基）13.7%、14.2%，湿面筋含量30.2%、33.1%，吸水率58%、57%，稳定时间5.7min、4.5min，最大拉伸阻力237E.U，拉伸面积43cm2，硬度指数62.1、60.7。产量和抗性表现：2019-2021年度参加徐州农科所科企淮北小麦联合体区域试验，两年平均亩产560.6公斤，比对照淮麦20增产4.8%。2021-2022年度参加生产试验，平均亩产624.1公斤，比对照淮麦20增产5.0%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩15万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮18公斤左右，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (47, 1, '宁丰小麦', '苏种审字第12号', '1982', 0, '江苏省农作物品种审定委员会', '大丰县农科所', '由南农小麦室的高代材料选育', '江苏沿江、沿海地区', '退出批次：特征特性：该品种早熟丰产，矮杆叶挺，耐肥抗倒，穗粒重较协调，是稳产性，适应性较好的小麦良种。幼苗半直立。株高80—90厘米，株型较紧凑，茎杆中粗有蜡粉，弹性较好，叶片狭长较挺。前期生长偏慢，拔节后生长较快。分蘖力中等偏上，成穗率较高，每亩30万穗。穗长方形，长芒（黑色）、红壳，每穗35—40粒。籽粒长期椭圆形，折粒，千粒重36—39克，软质至半硬质，品质好。偏春性、早中熟。全生育期206天左右。比扬麦三号迟两天左右。耐寒性较好，白粉病、杆锈病较轻。缺点：中感条锈、叶锈病，不抗赤霉病，后期有叶枯现象，熟相较差。产量和抗性表现：1977年至79年连续三年参加淮南片小麦组区域试验，均表现增产，平均亩产分别为773.92斤、749.14斤、801.95斤，比扬麦3号增产15.0%、9.1%、15.74%。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (48, 1, '宁丰麦1号', '苏审麦20210003', '2021.12', 0, '江苏省农作物品种审定委员会', '兴化市种业有限公司、江苏浤源禾农业科技有限公司', '扬辐麦5242/镇05185，参试名称“浤麦1703”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，分蘖力及成穗数较好，株型较松散，抗倒性一般。穗纺锤形，长芒、白壳、红粒，籽粒半角质。区试平均结果：全生育期207.6天，比对照扬麦20短1.4天。株高89.8厘米，每亩有效穗31.2万，每穗38.8粒，千粒重48.7克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.58、1.87、1.95；自然发病鉴定中抗赤霉病，病指0、0.1、5.07），中抗白粉病，中感条锈病，感黄花叶病毒病，高感纹枯病、叶锈病。经江苏省农业科学院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重793g/L、790g/L，粗蛋白(干基)含量13.7%、14.2%，湿面筋含量28.8%、29.0%，吸水率66.9%、63.0%，稳定时间3.5min、5.3min，最大拉伸阻力249E.U.、327E.U.，拉伸面积55cm2、76cm2，硬度指数67.8、65.9。产量和抗性表现：2018-2020年度参加江苏省淮南小麦A组区试，两年平均亩产536.7公斤，比对照扬麦20增产5.0%。2020-2021年度参加生产试验，平均亩产487.5公斤，比对照扬麦20增产4.7%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗16万左右，缺肥迟播田块适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治赤霉病、纹枯病、叶锈病、条锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (49, 1, '宁洪麦237', '苏审麦20220037', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏洪泽湖农场种业有限公司、江苏省农业科学院粮食作物研究所', '淮1109/淮麦20', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。叶色淡绿，分蘖力较强，株型较松散。穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、白粒、中大穗，籽粒角质。联合体区域试验平均结果：全生育期229.6天，比对照淮麦20长0.6天，株高92.9厘米，每亩有效穗42.4万，每穗35.0粒，千粒重46.1克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度1.75、3.55；自然发病鉴定中感赤霉病，病指1.12、8.57），高感条锈病、白粉病，中感叶锈病、纹枯病，抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重852g/L、847g/L，粗蛋白质含量（干基）15.2%、14.8%，湿面筋含量35.8%、34.3%，吸水率64%、61%，稳定时间4.1min、4.2min，最大拉伸阻力256E.U.，拉伸面积57cm2，硬度指数63.1、64.6。产量和抗性表现：2019-2021年度参加徐州农科所科企淮北小麦联合体区域试验，两年平均亩产556.7公斤，比对照淮麦20增产4.1%。2021-2022年度参加生产试验，平均亩产620.3公斤，比对照淮麦20增产4.3%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩14万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤左右，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (50, 1, '宁洪麦452', '苏审麦20220019', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所、江苏洪泽湖农场种业有限公司', '连麦0809/淮麦20', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿，茎秆蜡质重。分蘖力较强，成穗数多，株型较松散，穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒角质。省区域试验平均结果：全生育期226.5天，比对照淮麦20短1.0天，株高91.1厘米，每亩有效穗40.9万，每穗34.2粒，千粒重45.1克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度2.80、2.57；自然发病鉴定中感赤霉病，病指2.24、18.57），高感叶锈病、白粉病、纹枯病，中感条锈病，中抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重830g/L、830g/L，粗粗蛋白质含量（干基）13.9%、14.8%，湿面筋含量29.5%、31.5%，吸水率64%、62%，稳定时间14.7min、8.9min，最大拉伸阻力453E.U.、371E.U.，拉伸面积80cm2、74cm2，硬度指数62.3、62.1。2020年品质检测结果达到中强筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮北B组小麦品种区域试验，两年平均亩产586.6公斤，比对照淮麦20增产5.7%。2021-2022年度参加生产试验，平均亩产613.2公斤，比对照淮麦20增产4.0%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩14万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤左右，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (51, 1, '宁盐1号', '苏审麦200205', '2002', 0, '江苏省农作物品种审定委员会', '江苏省农科院   沿海地区农科所   盐城种子站', '鄂引85-213系选', '江苏盐城及相同生态区', '退出批次：特征特性：该品种长芒、白壳、纺锤型穗，穗型较松散，籽粒白皮、角质，分蘖性较强，每亩有效穗28万左右，每穗粒数37粒左右，千粒重40克左右，容重780克左右。株高90-95厘米，耐肥抗倒性较强，成熟期较扬麦158早1-2天。中抗赤霉病，中感梭条花叶病毒病、白粉病，纹枯病较轻，穗发芽率22.3％。据2000年10月省区试统一送样品质分析(南京经济学院)，粗蛋白含量13.20%，湿面筋30.7％，干面筋11.0％，沉降值43ml，吸水率57.5%，面团形成时间2.0min，面团稳定时间4.0min，粉质评价值38分(同年对照扬麦158为45分)，属中筋品种。产量和抗性表现：1999-2001年参加省区域试验，1999-2000年度平均亩产372.81公斤，较对照扬麦158减产7.84％，极显著，居第10位；2000-2001年度平均亩产393.65公斤，较对照扬麦158减产0.01％，不显著，居第11位；两年平均亩产383.78公斤，较对照减产3.95%，极显著，居第9位。2001-2002年度委托盐城市组织生产试验，平均亩产418.6公斤，较对照扬麦158增产2.77%。该品种有一定的产量水平，抗病性较好。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (52, 1, '宁糯麦1号', '苏审麦200803', '2008.9', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'EH-5/扬麦158', '适宜江苏省淮南麦区种植', '退出批次：特征特性：幼苗直立，分蘖力及成穗数中等株型较紧凑，耐肥抗倒性一般长芒，白壳，红粒，纺锤型穗，籽粒半硬质胚乳糯质，支链淀粉含量98%，用于配制专用面条粉、馒头粉，其制品柔软度和韧性增加，做成的馒头包子等不易开裂，面条的适口性更好省区试平均结果：全生育期206.0天，与对照扬麦11号相当；株高92.9厘米，每亩有效穗30.3万穗，每穗40.1粒，千粒重37.9克接种鉴定结果：感赤霉病、纹枯病，高感梭条花叶病田间白粉病发生偏重抗穗发芽经农业部谷物品质监督检验测试中心测定，三年平均结果：容重786克/升，粗蛋白含量13.1%，湿面筋含量25.7%，稳定时间2.7分钟产量和抗性表现：2005-2007年度参加江苏省区域试验，两年平均亩产425.0公斤，较对照扬麦11号减产4.8％；2007-2008年度参加生产试验，平均亩产441.8公斤，较对照扬麦11号增产0.1%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (53, 1, '宁紫麦1号', '苏审麦20200008', '2020.11', 0, '江苏省农作物品种审定委', '江苏省农业科学院粮食作物研究所', '宁麦 8 号/宁 0726，参试名称“宁紫麦 1 号”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗半直立，叶色中等，分蘖力中等。株型较紧凑，抗倒性较好。穗层整齐，熟相较好。穗纺锤形，长芒、白 壳、紫粒，籽粒角质。区试平均结果:全生育期 208.6 天，比对照扬麦 20 短 1.8 天。株高 87.0 厘米，每亩有效穗 29.6 万，每穗 37.8 粒，千粒 重 44.0 克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农 业科学研究所鉴定:中抗赤霉病(接种鉴定中抗赤霉病，严重度 1.5、2.2;自然发病鉴定中抗赤霉病，病指 2.0、0.0)，中抗条锈病，中感黄花叶病 毒病，高感纹枯病、白粉病、叶锈病。经江苏省农业科学院种质资源与 生物技术研究所鉴定:抗穗发芽。经农业部谷物品质监督检验测试中心 测定:容重 794g/L、823g/L，粗蛋白(干基)16.7%、13.6%，湿面筋 30.0% 、 31.7%，吸水率 71%、66%，稳定时间 2.9min、3.8min，最大拉伸阻力 169E.U.、196E.U.，拉伸面积 43cm2、45cm2，硬度指数 70.5、68.2。产量和抗性表现：2017-2019 年度参加江苏省淮南小麦 B 组区试，两年平 均亩产 450.7 公斤，比对照扬麦 20 减产 3.7%。2019-2020 年度选育单位 自主开展生产试验，平均亩产 496.5 公斤，比对照扬麦 20 增产 3.9%。', '1、适宜播期 10 月下旬至 11 月初。2、适期播种每 亩基本苗 15 万左右，中低产田、迟播应适当增加。3、一般亩施纯氮 15 公斤，其中基苗肥占 60%、拔节孕穗肥占 40%，同时配合施用磷钾肥， 后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及 时防除田间杂草。注意防治纹枯病、赤霉病、白粉病、叶锈和蚜虫等病 虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (54, 1, '宁红麦1119', '苏审麦20210002', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏红旗种业股份有限公司、江苏省农业科学院粮食作物研究所', '宁0320/宁0076，参试名称“宁红1119”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色中等，分蘖力中等。株型较紧凑，抗倒性中等。穗层整齐，熟相好。穗长方形，长芒、白壳、红粒，籽粒粉质。区试平均结果：全生育期208.0天，比对照扬麦20短1天。株高88.1厘米，每亩有效穗31.1万，每穗40.6粒，千粒重43.7克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.33、1.25、1.25；自然发病鉴定中抗赤霉病，病指0、0、3.13），中抗黄花叶病毒病，高感纹枯病、白粉病、叶锈病、条锈病。经江苏省农业科学院种质资源与生物研究所鉴定：高抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重816g/L、804g/L，粗蛋白(干基)含量14.1%、14.1%，湿面筋含量31.1%、30.2%，吸水率57.9%、61.3%，稳定时间1.5min、2.6min，最大拉伸阻力84E.U.、147E.U.，拉伸面积22cm2、38cm2，硬度指数52.0、51.5。产量和抗性表现：2018-2020年度参加江苏省淮南小麦A组区试，两年平均亩产529.6公斤，比对照扬麦20增产3.6%。2020-2021年度参加生产试验，平均亩产491.4公斤，比对照扬麦20增产5.5%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗15万左右，中低产田适当增加。3、一般亩施纯氮16公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (55, 1, '宁红麦199', '苏审麦20220030', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏红旗种业股份有限公司、江苏省农业科学院粮食作物研究所', '扬06-164/宁麦13//扬9选系/镇05185', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗半直立，分蘖力较强。株型松散，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒半角质。联合体区域试验平均结果：全生育期203.1天，与对照扬麦20相当。株高85.1厘米，每亩有效穗31.5万，每穗39.4粒，千粒重46.6克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定抗赤霉病，严重度1.11、1.33；自然发病鉴定中抗赤霉病，病指0.27、0.48），高感纹枯病、白粉病、叶锈病、条锈病，中抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重790g/L、799g/L，粗蛋白质含量（干基）15.0%、13.8%，湿面筋含量33.6%、29.7%，吸水率58%、56%，稳定时间4.9min、8.8min，最大拉伸阻力236E.U.、724E.U.，拉伸面积67cm2、121cm2，硬度指数52.3、54.0。产量和抗性表现：2019-2020年度、2021-2022年度参加江苏省淮南神农大丰企业联合体区域试验，两年平均亩产520.6公斤，比对照扬麦20增产6.2%。2021-2022年度参加生产试验，平均亩产544.0公斤，比对照扬麦20增产4.4%。', '1、适宜播期10月25日至11月5日。2、基本苗适期播种每亩15万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤，其中基苗肥占70%、拔节孕穗肥占30%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (56, 1, '宁麦10号', '苏种审字第338号', '1999', 0, '江苏省农作物品种审定委员会', '江苏省农科院粮作所', '上海7号//PRL\"S\"/VEE6', '江苏淮南麦区', '退出批次：特征特性：幼苗直立，叶片较细狭长，叶色偏淡。株高95厘米左右，株型较松散，茎杆韧性较弱。分蘖力较强，成穗率较高。长芒、白壳、纺锤形穗，每穗平均35-37粒。籽粒饱满，红皮，半角质，千粒重40克左右。品质较好，粗蛋白含量13.5%，湿面筋含量39.6%，吸水率68.0%，面团形成时间3.0分钟，稳定时间3.3分钟，断裂时间5.6分钟，粉质评价值40分。生育期208天左右，比扬麦158迟2天。中抗梭条花叶病毒病与纹枯病，中抗-中感赤霉病与白粉病，抗寒性较强，抗倒性较弱。产量和抗性表现：1997至1999年连续两个年度参加江苏省淮南小麦品种区域试验，平均亩产分别为291.99公斤和377.94公斤，比对照扬麦158增产11.05%（极显著）和2.01%（不显著）。1998-1999年度在江苏省淮南小麦品种生产试验中亩产398.24公斤，比对照扬麦158增产3.56%。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (57, 1, '宁麦11号', '苏审麦200408', '2004.8', 0, '江苏省农作物品种审定委员会', '江苏省农科院粮食所', '宁麦8号变异株系选', '江苏盐城沿淮地区(包括大丰、盐都，东台、建湖北部，射阳、阜宁南部)', '退出批次：特征特性：该品种幼苗直立，叶色深绿，分蘖性较强，株型紧凑，穗层整齐，株高85厘米左右，穗椭圆形，长芒、白壳、白粒，结实性较好，籽粒角质，饱满度好。每亩穗数35万左右，每穗实粒数33粒左右，千粒重近40克。全生育期较豫麦18早熟2天。中感赤霉病，中感穗发芽，感梭条花叶病毒病，耐肥抗倒性较好。品质检测结果两年平均为粗蛋白14.91%，湿面筋33.2%，稳定时间6.6分钟，属中筋小麦品种。产量和抗性表现：2001-2003年度参加江苏省区域试验，两年平均亩产422.83公斤，较对照豫麦18增产7.39%。两年均达极显著水平，2002-2003年度在区试同时组织生产试验，平均亩产449.00公斤，较对照增产8.57%。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (58, 1, '宁麦12', '苏审麦200405', '2004', 0, '', '江苏省农科院粮食作物', '', '', '审定机构：品种来源：适宜种植区域：特征特性：产量和抗性表现：', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (59, 1, '宁麦12号', '苏审麦200405', '2004.8', 0, '江苏省农作物品种审定委员会', '江苏省农科院粮食作物所', '宁9170/扬麦158', '江苏省淮南麦区', '退出批次：特征特性：该品种长芒、白壳、纺缍型穗，籽粒红皮、半硬质；幼苗直立，株型松散，全生育期较扬麦158长2-3天，株高90厘米左右，耐肥抗倒性一般；每亩有效穗25万左右，每穗38粒左右，千粒重39克左右。接种鉴定中感赤霉病，感纹枯病，抗病性与扬麦158相当。品质分析三年平均结果为粗蛋白含量15.1%，湿面筋含量25.5%，稳定时间13.3分钟，属中筋品种。产量和抗性表现：001-2003年度参加江苏省区域试验，两年平均亩产345.1公斤，较对照扬麦158增产9.75%，两年增产均达极显著水平；2003-2004年度组织生产试验，平均亩产400.2公斤，较对照扬麦158增产9.15%。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (60, 1, '宁麦13', '苏审麦200503', '2005.9', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', '宁麦9号经系统选育', '江苏省淮南麦区种植', '退出批次：特征特性：该品种长芒、白壳、纺锤型穗，籽粒红皮，半硬-粉质。幼苗直立，分蘖力较强，株型较紧凑，株高82厘米左右，抗倒性一般。全生育期210天，比对照扬麦158迟1天。每亩有效穗33万左右，每穗37粒左右，千粒重36克左右。接种鉴定中感赤霉病、纹枯病，抗梭条花叶病毒病。田间白粉病发生较重。品质分析2001-2004年度三年平均结果：粗蛋白含量12.0%，湿面筋含量23.0%，稳定时间5.1分钟。2005年按照弱筋小麦栽培要求种植，品质分析结果为粗蛋白含量11.1%，湿面筋含量21.8%，稳定时间3.5分钟。产量和抗性表现：2001-2003年度参加江苏省区域试验，两年平均亩产379.0公斤，比对照扬麦158增产12.63％。2003-2004年度生产试验平均亩产423. 37公斤，较对照扬麦158增产9.14%。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (61, 1, '宁麦14', '苏审麦200601', '2006.9', 0, '江苏省农作物品种审定委员会', '省农科院粮食所', '宁9系选', '适宜江苏淮南麦区种植', '退出批次：特征特性：该品种长芒，白壳，穗近长方形，籽粒红皮，半硬-粉质。幼苗直立，叶色较淡。株型中等偏松散，株高83厘米左右，耐肥抗倒性一般。生育期211天左右，与对照相仿。分蘖及成穗数中等，穗大粒多，千粒重较高。亩有效穗33万左右，每穗38粒左右，千粒重41克左右。接种鉴定：中感赤霉病、白粉病，感纹枯病，高感梭条花叶病，高抗穗发芽。品质分析三年平均结果：粗蛋白含量14.3%，湿面筋含量31.1%，稳定时间2.6分钟。产量和抗性表现：2003-2005年度参加江苏省区域试验，两年平均亩产467.54公斤，比对照扬麦158增产13.69％，两年较对照增产均达极显著水平；2005-2006年度生产试验，平均亩产453.47公斤，较对照扬麦11号增产2.17%。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (62, 1, '宁麦16', '苏审麦200802', '2008.9', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院生物技术研究所', '宁麦8号/宁9312', '适宜江苏省淮南麦区种植', '退出批次：特征特性：幼苗直立，叶片宽长，叶色淡绿株型较松散，耐肥抗倒性一般分蘖力一般，成穗数中等，穗大粒多长芒，白壳，红粒，纺锤型穗，籽粒半硬质-软质省区试平均结果：全生育期208.0天，较对照照扬麦11号迟熟2天；株高86.0厘米，每亩有效穗29.9万穗，每穗41.6粒，千粒重39.7克接种鉴定结果：中抗赤霉病，中感纹枯病，中抗梭条花叶病田间白粉病发生偏重高抗穗发芽经农业部谷物品质监督检验测试中心测定，三年平均结果：容重814克/升，粗蛋白含量13.2%，湿面筋含量25.7%，稳定时间8.3分钟产量和抗性表现：2005-2007年度参加江苏省区域试验，两年平均亩产454.9公斤，较对照扬麦11号增产1.9％；2007-2008年度参加生产试验，平均亩产461.3公斤，较对照扬麦11号增产4.5%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (63, 1, '宁麦17', '苏审麦200902', '2009.9', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院生物技术研究所、泰州市种子公司', '宁9529/扬麦5号//宁9529', '适宜江苏省淮南麦区种植', '退出批次：特征特性：幼苗直立，叶片宽长，叶色淡绿。分蘖力和成穗数中等。株型较松散，耐肥抗倒性一般。长方型穗，长芒，白壳，红粒，籽粒半硬质-硬质，千粒重高。省区试平均结果：全生育期205.6天，与对照扬麦11号相当；株高92.5厘米，每亩有效穗28.9万，每穗39.8粒，千粒重46.0克。接种鉴定结果：中抗赤霉病、白粉病，中感纹枯病，高抗梭条花叶病。抗穗发芽。经农业部谷物品质监督检验测试中心测定，两年平均结果：容重817克/升，粗蛋白含量13.3%，湿面筋含量26.5%，稳定时间3.2分钟。产量和抗性表现：2006-2008年度参加江苏省区域试验，两年平均亩产484.6公斤，较对照扬麦11号增产4.6％。2008-2009年度参加生产试验，平均亩产473.5公斤，较对照扬麦11号增产7.1%。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (64, 1, '宁麦18', '苏审麦201101', '2011.10', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院农业生物技术研究所      江苏中江种业股份有限责任公司', '宁9312*3/扬93-111', '适宜江苏省淮南麦区种植', '退出批次：特征特性：该品种表现幼苗直立，叶片较窄，叶色淡绿抗寒性较强，分蘖力较强，成穗数较多，穗大粒多，千粒重偏低株型较松散，耐肥抗倒性一般长芒、白壳、红粒，纺锤型穗，籽粒半硬质区试平均结果：全生育期212.0天，较对照迟熟2天；株高92.2厘米，每亩有效穗33.1万穗，每穗43.2粒，千粒重36.3克接种鉴定结果：中抗赤霉病、白粉病，感纹枯病，高抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2008-2010年度两年平均结果：容重814克/升，粗蛋白含量12.3%，湿面筋含量25.7%，稳定时间4.1分钟产量和抗性表现：2008-2010年度参加江苏省淮南组小麦区域试验，平均亩产505.4公斤，较对照扬麦11号增产9.8％，两年较对照增产均达极显著水平2010-2011年度参加生产试验，平均亩产451.2公斤，较对照扬麦11号增产4.6%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (65, 1, '宁麦186', '苏审麦20200022', '2020.11', 0, '江苏省农作物品种审定委', '江苏省农业科学院粮食作物研究所', '宁麦 16/镇麦 9 号，参试名称“宁 15186”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗半直立，叶色淡绿，分蘖力较强。株型较松散，抗倒性较好。穗层整齐，熟相较好。穗纺锤形，长芒、白 壳、红粒，籽粒半角质。区试平均结果:全生育期 207.3 天，比对照扬 麦 20 短 1.5 天。株高 86.7 厘米，每亩有效穗 32.6 万，每穗 36.5 粒，千 粒重 44.9 克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州 农业科学研究所鉴定:中抗赤霉病(接种鉴定中抗赤霉病，严重度 1.8、 2.6;自然发病鉴定中抗赤霉病，病指 1.6、0.0)，中感条锈病、黄花叶病 毒病，高感纹枯病、白粉病、叶锈病。经江苏省农业科学院种质资源与 生物研究所鉴定:抗穗发芽。经农业部谷物品质监督检验测试中心测定:容重 784g/L、806g/L，粗蛋白(干基)15.1%、13.0%，湿面筋 29.1% 、27.9%， 吸水率 58%、58%，稳定时间 9.6min、6.6min，最大拉伸阻力 614E.U.， 拉伸面积 133cm2。2017-2018 年度品质指标达到中强筋小麦品种审定标 准。产量和抗性表现：2017-2019 年度参加江苏省淮南小麦省农科院科企联合体 区试，两年平均亩产 473.1 公斤，比对照扬麦 20 增产 4.5%。2019-2020 年度参加生产试验，平均亩产 511.1 公斤，比对照扬麦 20 增产 3.2%。', ':1、适宜播期 10 月 25 日至 11 月 5 日。2、适期播种 每亩基本苗 16 万左右，中低产田适当增加。3、一般亩施纯氮 18 公斤， 其中基苗肥占 60%、拔节孕穗肥占 40%，同时配合施用磷钾肥，后期适 当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除 田间杂草。注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (66, 1, '宁麦19', '苏审麦201201', '2012.11', 0, '江苏省农作物品种审定委员会', '江苏省农科院农业生物技术所、江苏红旗种业有限公司', '宁9144 / 扬麦158 // 扬麦158', '江苏省淮南麦区种植', '退出批次：特征特性：该品种表现幼苗直立，叶色淡绿，叶片较宽大抗寒性较强，分蘖力较强，成穗数较多株型偏松散，叶片大小适中，色泽较深，略披垂耐肥抗倒性一般穗近似长方型，长芒，白壳，多穗多粒，结实性较好籽粒红皮，半硬－硬质，椭圆、饱满，千粒重高区试平均结果：全生育期213.0天，与对照相当；株高86.9厘米，每亩有效穗28.8万穗，每穗39.7粒，千粒重44.9克接种鉴定结果：中感赤霉病、纹枯病，感白粉病，抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2009-2011年度两年平均结果：容重825.5克/升，粗蛋白含量13.1%，湿面筋含量28.3%，稳定时间4.7分钟产量和抗性表现：2009-2011年度参加江苏省淮南组小麦区域试验，平均亩产489.1公斤，较对照扬麦11号增产8.3％，两年较对照增产均达极显著水平2011-2012年度参加生产试验，平均亩产410.6公斤，较对照扬麦11号增产8.4%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (67, 1, '宁麦20', '苏审麦201202', '2012.11', 0, '江苏省农作物品种审定委员会', '江苏省农科院生物技术所', 'Y18//3E159（宁麦8号/宁麦9号）', '江苏省淮南麦区种植', '退出批次：特征特性：该品种表现幼苗半直立，叶片较宽，色较深分蘖力一般，成穗数中等，抗寒性一般株型偏紧凑，耐肥抗倒性一般穗层较整齐，纺锤型穗长芒、白壳、红粒，籽粒硬质、饱满度好，千粒重较高区试平均结果：全生育期216.4天，较对照迟熟3-4天；株高82.6厘米，每亩有效穗31.2万穗，每穗39.1粒，千粒重39.0克接种鉴定结果：抗赤霉病，中感纹枯病，感白粉病，抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2009-2011年度两年平均结果：容重798.5克/升，粗蛋白含量14.3%，湿面筋含量30.7%，稳定时间6.8分钟2010年容重778克/升，粗蛋白含量14.7%，湿面筋含量30.8%，稳定时间8.8分钟产量和抗性表现：2009-2011年度参加江苏省淮南组小麦区域试验，平均亩产459.8公斤，较对照扬麦11号增产1.8％，2009-2010年度较对照减产不显著，2010-2011年度较对照增产达显著水平2011-2012年度参加生产试验，平均亩产385.5公斤，较对照扬麦11号增产1.8%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (68, 1, '宁麦21', '苏审麦201303', '2013', 0, '江苏省农作物品种审定委员会', '江苏省农科院农业生物技术所', '宁9312/扬麦158//宁9312', '适宜江苏省淮南麦区种植', '退出批次：特征特性：幼苗直立，叶色淡绿分蘖力中等，抗寒性较强株型较紧凑，抗倒性一般灌浆速度较快，穗层整齐，转色正常，熟相较好穗纺锤型，长芒、白壳、红粒，籽粒椭圆形，半硬质－硬质，千粒重高区试平均结果：全生育期210.0天，比对照迟1天；株高86.6厘米，每亩有效穗30.0万穗，每穗38.7粒，千粒重43.6克接种鉴定结果：中抗赤霉病，中感纹枯病，感白粉病，高感黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2010-2012年度两年平均结果：容重794.0克/升，粗蛋白含量13.9%，湿面筋含量30.2%，稳定时间4.8分钟产量和抗性表现：2010-2012年度参加江苏省淮南组小麦区域试验，平均亩产447.4公斤，较对照扬麦11号增产4.6％，2010-2011年度增产达极显著水平2012-2013年度参加生产试验，平均亩产434.1公斤，较对照扬麦11号增产5.6%', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (69, 1, '宁麦26', '苏审麦20160004', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院农业生物技术研究所、江苏红旗种业股份有限公司', '宁9351/宁麦9号，参试名称“宁09-72”', '江苏省淮南麦区', '特征特性：春性中熟小麦品种，成熟期比对照扬麦11晚1-2天。幼苗直立，分蘖力中等偏强。株型较紧凑，抗倒性一般。穗层较整齐，熟相一般。穗纺锤形，长芒、白壳、红粒，籽粒半硬质至硬质。区试平均结果：全生育期210.7天，株高77.0厘米，每亩有效穗32.3万，每穗38.4粒，千粒重40.9克。经江苏省农科院植保所三年接种鉴定：中抗赤霉病（严重度1.47-1.75），中感纹枯病，感白粉病，高抗小麦黄花叶病毒病。经江苏省农科院粮作所鉴定：抗穗发芽。品质经农业部谷物品质监督检验测试中心测定，三年平均结果：容重824.0克/升，粗蛋白含量14.8%，湿面筋含量31.9%，稳定时间10.3分钟，最大拉伸阻力403.3 E.U.，延伸性202毫米，硬度指数64.6。产量和抗性表现：2012-2014年度参加江苏省淮南组小麦区域试验，两年平均亩产482.6公斤，较对照扬麦11增产7.1%，两年均达极显著水平。2014-2015年度参加生产试验，平均亩产452.9公斤，较对照扬麦11增产6.7%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗15万左右。3、一般亩施纯氮15公斤左右，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (70, 1, '宁麦28', '苏审麦20180005', '2018.12', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', '苏2037/淮麦17//Y18，参试名称“宁12188”', '江苏省淮南麦区', '特征特性：属春性中熟小麦品种。幼苗直立，叶色较深，分蘖力较强。株型松散，抗倒性中等。穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒半硬质。区试平均结果：全生育期203.8天，比对照扬麦20迟1天。株高85.3厘米，每亩有效穗32.1万，每穗39.1粒，千粒重41.2克。经江苏省农业科学院植物保护研究所接种鉴定：中抗赤霉病（严重度1.40-2.80），中感纹枯病，高感白粉病，中抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业部谷物品质监督检验测试中心（哈尔滨）测定，两年平均结果：粗蛋白（干基）14.0%，湿面筋29.9% ，吸水量57.6ml/100g，稳定时间4.3min，最大拉伸阻力258 E.U.，拉伸面积67cm2，硬度指数52.0。产量和抗性表现：2015-2017年度参加江苏省淮南组小麦区域试验，两年平均亩产505.7公斤，较对照扬麦20增产5.1％。2017-2018年度参加生产试验，平均亩产452.6公斤，较对照扬麦20增产4.3％。', '1、适宜播期10月25日至11月10日。2、适期播种每亩基本苗15万左右，中低产田或迟播应适当增加。3、一般亩施纯氮15-18公斤，其中基苗肥占60%、拔节孕穗肥占40％，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草。注意防治纹枯病、白粉病、赤霉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (71, 1, '宁麦33', '苏审麦20200003', '2020.11', 0, '江苏省农作物品种审定委', '江苏省农业科学院粮食作物研究所', '宁 0798/宁麦 14，参试名称“宁麦 1512”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗半直立，分蘖力较强。株型较松散，抗倒性一般。穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽 粒半角质。区试平均结果:全生育期 208.7 天，比对照扬麦 20 短 1.0 天。 株高 85.0 厘米，每亩有效穗 31.8 万，每穗 37 粒，千粒重 47.0 克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴 定:中抗赤霉病(接种鉴定中抗赤霉病，严重度 1.6、2.5;自然发病鉴 定抗赤霉病，病指 0.3、0.0)，高抗白粉病，中感纹枯病、条锈病、黄花 叶病毒病，高感叶锈病。经江苏省农业科学院种质资源与生物研究所鉴 定:抗穗发芽。经农业部谷物品质监督检验测试中心测定:容重 796g/L、 811g/L，粗蛋白(干基)13.5%、13.4%，湿面筋 30.0% 、29.4%，吸水率 56%、58%，稳定时间 2.8min、2.3min，最大拉伸阻力 177E.U.、137E.U.， 拉伸面积 53cm2、35cm2，硬度指数 50.4、50.6。产量和抗性表现：2017-2019 年度参加江苏省淮南小麦 A 组区试，两年平 均亩产 519.8 公斤，比对照扬麦 20 增产 8.1%。2019-2020 年度参加生产 试验，平均亩产 517.1 公斤，比对照扬麦 20 增产 5.6%。', '1、适宜播期 10 月 25 日至 11 月 5 日。2、适期播种 每亩基本苗 16 万左右，中低产田适当增加。3、一般亩施纯氮 18 公斤， 其中基苗肥占 60%、拔节孕穗肥占 40%，同时配合施用磷钾肥，后期适 当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除 田间杂草。注意防治纹枯病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (72, 1, '宁麦34', '苏审麦20210007', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', '镇麦9号/宁9-80，参试名称“宁麦1627”', '江苏省淮南麦区', '特征特性：春性早熟小麦品种。幼苗半直立，叶色中等，分蘖力较强。株型较松散，抗倒性一般。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒半角质。区试平均结果：全生育期208.5天，比对照扬麦20短2.6天。株高91.7厘米，每亩有效穗31.9万，每穗37.1粒，千粒重45.4克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度3.0、2.17、1.50；自然发病鉴定中抗赤霉病，病指0.58、1.88、4.19），中感黄花叶病毒病，高感纹枯病、白粉病、叶锈病、条锈病。经江苏省农业科学院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重809g/L、802g/L，粗蛋白(干基)含量14.7%、14.8%，湿面筋含量36.1%、34.9%，吸水率64.3%、64.2%，稳定时间3.0min、3.7min，最大拉伸阻力209E.U.、214E.U.，拉伸面积51cm2、49cm2，硬度指数63.8、63.0。产量和抗性表现：2018-2020年度参加江苏省淮南小麦B组区试，两年平均亩产499.0公斤，比对照扬麦20增产0.8%。2020-2021年度参加生产试验，平均亩产457.4公斤，比对照扬麦20增产2.7%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗16万左右，中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (73, 1, '宁麦36', '苏审麦20220027', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所、江苏中旗种业科技有限公司', '扬麦20/宁麦14', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，叶色深绿，分蘖力较强。株型较松散，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒粉质。联合体区域试验平均结果：全生育期205.9天，比对照扬麦20短0.8天，株高88.1厘米，每亩有效穗35.0万，每穗41.1粒，千粒重41.2克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.10、1.45；自然发病鉴定中抗赤霉病，病指0.22、4.48），高感白粉病、纹枯病、叶锈病，中感条锈病、黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重788g/L、797g/L，粗蛋白质含量（干基）9.4%、11.6%，湿面筋含量18.2%、25.9%，吸水率54%、53%，稳定时间0.7min、2.6min，最大拉伸阻力190 E.U.、217E.U.，拉伸面积39 cm2、50cm2，硬度指数43.3。2020年品质检测结果达到弱筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮南小麦江苏农科院科企联合体区域试验，两年平均亩产503.7公斤，比对照扬麦20增产4.8%。2021-2022年度参加生产试验，平均亩产581.2公斤，比对照扬麦20增产6.0%。', '1、适宜播期10月25日至11月5日。2、基本苗适期播种每亩15万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤左右，其中基苗肥占70%、拔节孕穗肥占30%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (74, 1, '宁麦37', '苏审麦20220002', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', '宁麦13//宁麦13/扬麦20', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，叶色深绿，分蘖力较强。株型较松散，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒半角质。省区域试验平均结果：全生育期208.2天，比对照扬麦20短0.9天，株高88.5厘米，每亩有效穗32.0万，每穗41.5粒，千粒重44.1克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.20、1.48；自然发病鉴定中抗赤霉病，病指0.20、3.31），高感白粉病、纹枯病、叶锈病，感黄花叶病毒病，中抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重809g/L、800g/L，粗蛋白质含量（干基）13.3%、14.1%，湿面筋含量28.7%、30.3%，吸水率57%、58%，稳定时间4.7min、4.1min，最大拉伸阻力249E.U.、261E.U.，拉伸面积58cm2、74cm2，硬度指数52.9、51.3。产量和抗性表现：2019-2021年度参加江苏省淮南A组小麦品种区域试验，两年平均亩产521.6公斤，比对照扬麦20增产5.4%。2021-2022年度参加生产试验，平均亩产530.5公斤，比对照扬麦20增产5.0%。', '1、适宜播期10月底至11月上旬。2、基本苗适期播种每亩16万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮18公斤左右，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，中后期做好纹枯病、赤霉病、白粉病和蚜虫等防治工作。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (75, 1, '宁麦38', '苏审麦20220011', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', '镇05185/生选6号', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，分蘖力一般。株型较松散，穗层整齐，熟相较好。穗长方形，长芒、白壳、红粒，籽粒半角质。省区域试验平均结果：全生育期207.7天，比对照扬麦20短1.4天，株高88.1厘米，每亩有效穗32.3万，每穗38.7粒，千粒重47.0克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.80、1.60；自然发病鉴定中抗赤霉病，病指1.28、6.01），感纹枯病，中感白粉病，中抗叶锈病、条锈病、黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重791g/L、790g/L，粗蛋白质含量（干基）15.7%、15.1%，湿面筋含量33.2%、33.1%，吸水率64%、64%，稳定时间16.2min、5.4min，最大拉伸阻力625E.U.、333E.U.，拉伸面积136cm2、99cm2，硬度指数66.9、65.4。2019年品质检测结果达到强筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮南A组小麦品种区域试验，两年平均亩产521.3公斤，比对照扬麦20增产5.4%。2020-2021年度参加生产试验，平均亩产487.7公斤，比对照扬麦20增产4.7%。', '1、适宜播期10月25日至11月5日。2、基本苗适期播种每亩15万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (76, 1, '宁麦6号', '苏种审字第11号', '1982', 0, '江苏省农作物品种审定委员会', '江苏省农科院', 'St2422/464和阿夫杂交', '江苏苏南地区', '退出批次：特征特性：该品种株型紧凑，矮杆大穗。分蘖力强，耐寒性较好适于早播，较抗条、杆锈病。幼苗半匍匐。株高80—90厘米，比扬麦三号矮10—15厘米。茎杆粗壮坚韧，叶片稍宽而挺举，叶色深绿。穗层整齐。每亩34万穗左右，高产田可达35—42万穗。穗长主形，穗略短着粒密，长芒、红壳、红粒。每穗33粒左右，高产35—44粒，千粒重33克上下，高产田达35—40克。半冬性，中晚熟，全生育期210天左右。缺点：中感白粉病，赤霉病偏重。对肥水要求较严，肥水不足退化小穗增多。耐湿性、抗干热风力略差于扬麦3号。成熟偏晚，熟相力差，后期稍有枯尖。产量和抗性表现：1975至77年连续三年参加省淮南片小麦组区域试验，平均亩产分别为650.6斤、404.4斤、731.9斤，比武麦一号、扬麦一号、扬麦3号增产7.6%、0.2%、12.2%。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (77, 1, '宁麦7号', '苏种审字第203号', '1993', 0, '江苏省农作物品种审定委员会', '江苏省农科院粮作所', '扬麦3号/SERI', '江苏淮南麦区', '退出批次：特征特性：幼苗半直立，叶窄短而挺，叶色较淡。株高85厘米左右，比扬麦5号10厘米左右。株型较紧凑，植株矮壮，耐肥抗倒性较好。前期生产较迟缓， 发苗稳，冬前苗比扬麦5号少3.5万，拔节后生长速率加快，春发性好，增蘖较快，最高茎蘖数成扬麦5号相仿，分蘖力较强，穗率较高，每亩有效穗34.1万，比扬麦5号高2.2。穗近长方形，长芒、白壳、白粒。每穗实粒数39.2粒，比杨麦5号多4.5粒，籽粒较短圆，饱满而有光泽，粉质至半角质，粒色淡黄，千粒重31.6克，比扬麦5号低4.4克。容重766克/公升，比杨麦5号高23克/公升。籽粒外观品质较好。经测定：粗蛋白含量11。23%，出粉率73%，湿面筋含量32.3%，面团稳定时间4.6分钟，五个指标均比对照扬麦5号高，粉质综合评价42分，比扬麦5号高4分。全生育期205.9天，比扬麦5号早熟一天，抗寒性较好.在两年的省中间试验中赤霉病较轻，白粉病和纹枯病亦较扬麦5号轻.经农科院植保所病圃及接种鉴定:局部地区抗小麦梭条花叶病毒病，多数试点属高抗，对赤霉病的抗性属中抗至中感，纹枯病稍重.粒型偏小，部分试点反映穗屋整齐度较差，后期叶枯现象偏重。产量和抗性表现：1991—1993年连续两年参加淮南小麦新品种区域试验，平均单产分别为401.2公斤和351.53公斤，分别比扬麦5号增4.26%和4.09%，达极显著和显著水准。两年平均亩产376.4公斤，比扬麦5号增产4.18%。1992—1993年度参加省生产试验，平均亩产390公斤，比扬麦5号增产6.86%。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (78, 1, '宁麦8号', '苏种审字第259号', '1996', 0, '江苏省农作物品种审定委员会', '江苏省农科院粮作所', '扬麦5号/扬麦6号', '江苏淮南麦区', '退出批次：特征特性：幼苗半直立，生长稳健，越冬性较好。株高80—85厘米。株型较紧凑，茎秆较粗壮，韧性好。耐肥抗性较好。叶片宽挺，叶色深绿。前中期生长稳健，拔节迟，拔节后生长发育苗明显加快。分蘖力、成穗率中等，平均亩有效穗28.3万，比扬麦158少0.48万。长芒、白壳、红粒，穗长方形，结实性较好，穗大粒多，平均每穗40.36粒，比扬麦158多3.29粒。籽粒椭圆形；饱满，半硬质；平均千粒重37.35克，比扬麦158低2.0克，容重774克/升，比扬麦158高14.5克/升。籽粒虽稍比扬麦158小，但粒色偏淡，商品性好。经测定：粗蛋白含量11.6%；出粉率68.1%，湿面筋含量34.8%，面团稳定时间2.5分钟，综合评价值36分。全生育期209天，比扬麦158晚1—2天，耐干热风，抗寒性比扬麦158好：中感梭条花叶病毒和纹枯病，但感纹条花叶病毒病后恢复较快；中抗赤霉病、白粉病，以上病害发病均较对照轻。产量和抗性表现：1993年至1995年连续两年度参加淮南小麦品种区域试验，平均单产分别为341.67公斤和364.64公斤，比扬麦158增产0.21%。1995年至1996年度在省生主试验中平均单产为425.52公斤，比扬麦158增产2.42%。', '', 1, '2025-07-22 09:41:25', '2025-07-22 09:41:25');
INSERT INTO `ld_crop_variety` VALUES (79, 1, '宁麦9号', '苏种审字第283号', '1997', 0, '江苏省农作物品种审定委员会', '江苏省农科院粮作所', '扬麦6号/西风', '江苏淮南麦区', '退出批次：特征特性：幼苗半直立，生长稳健，发苗较快，越冬抗寒性略好于对照。株高85厘米工作，比对照矮10厘米，株型紧凑，剑叶较窄挺，叶色深绿。分蘖力中等偏上，冬发性好，春发性较弱，成穗率较高。长芒、白壳、淡红粒、穗纺锤形，每亩31万穗左右，比对照多2—3万穗。抗倒春害寒，结实性好， 每穗实率数44.3粒，比对照多4.8粒。籽粒小，椭圆形，粉质至半角质，饱满度好，千粒重35.6粒，比对照低4.77克，容重783—805克/升，比对照高20—27克/升。品质分析结果：粗蛋白含量12.2%，湿面筋含量32.8%，沉降值347S，出粉率65.0%，吸水率58.5%，面团形民时间2.4分钟，稳定时间2.3分钟，断裂时间3.6分钟，评价值40分，品质较好。生育期200.3天，比对照略迟一天左右。高产稳定。高抗梭条花叶病毒病，中抗赤霉病。白粉病略重于对照，感染纹枯病，偏旱田出现叶锈病发病中心。抗倒性、熟相一般。产量和抗性表现：1995—1997年连续两年度参加江苏省淮南小麦品种区域试验，平均单产别为466.4公斤、421.5公斤，分别比扬麦158（对照）增产14.55%和17.09%，均达极显著水准。两年平均单产442.96公斤，比对照增产10.8%，达极显著水准。1996—1997年度在生产试验平均单产455.25公斤，比对照增产5.35%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (80, 1, '宁麦资119', '苏审麦20180002', '2018.12', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院种质资源与生物技术研究所、江苏焦点农业科技有限公司、扬州市扬子江种业有限公司', '意大利软质小麦/宁麦132，参试名称“资119”', '江苏省淮南麦区', '特征特性：属春性中熟小麦品种。幼苗直立，分蘖力较强。穗层整齐，株型较松散，抗倒性中等。穗纺锤形，长芒、白壳、红粒，籽粒硬质，籽粒较饱满。区试平均结果：全生育期201.2天，与对照扬麦20相当。株高77.3厘米，每亩有效穗32.5万，每穗38.9粒，千粒重39.8克。经江苏省农业科学院植物保护研究所接种鉴定：抗赤霉病（严重度1.05-1.26），感纹枯病，高感白粉病，抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业部谷物品质监督检验测试中心（哈尔滨）测定，两年平均结果：粗蛋白（干基）13.9%，湿面筋30.9%，吸水量65.1ml/100g，稳定时间6.5min，最大拉伸阻力272E.U.，拉伸面积71cm2，硬度指数67.0。产量和抗性表现：2015-2017年度参加江苏省淮南组小麦区域试验，两年平均亩产496.5公斤，较对照扬麦20增产5.3％。2017-2018年度参加生产试验，平均亩产458.3公斤，较对照扬麦20增产4.6％。', '1、适宜播期11月1日至11月10日。2、该品种分蘖性好，适期播种每亩基本苗12万左右，中低产田或迟播应适当增加。3、一般亩施纯氮16-18公斤。在肥料运筹上应采取氮肥前移，节氮增磷钾的原则，前期足肥促早发，中期严格控制氮肥使用量。采用基肥：壮蘖肥:拔节孕穗肥比例为5:1:4的氮肥运筹方式，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草。注意防治白粉病、叶锈病、纹枯病、赤霉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (81, 1, '宁麦资126', '苏审麦20170002', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院种质资源与生物技术研究所', '镇麦6号/（偃高1号/烟农15-9//优繁5号/农大糯麦1号/3/IDO580），参试名称“资12-6”', '江苏省淮南麦区', '特征特性：春性中熟小麦品种。成熟期比对照扬麦20早近1天。幼苗直立，叶色较深，分蘖力中等。株型较松散，茎杆粗壮，抗倒性中等。穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒硬质。区试平均结果：全生育期206.7天，株高85.9厘米，每亩有效穗30.9万，每穗36.6粒，千粒重45.0克。经江苏省农科院植保所两年接种鉴定：中抗赤霉病（严重度1.29-2.21），中感纹枯病，感白粉病，中抗黄花叶病毒病。经江苏省农科院粮作所鉴定：抗穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：粗蛋白（干基）17.3%，湿面筋34.0%，吸水量63.3 ml/100g，稳定时间8.1分钟，最大拉伸阻力551（Rm,135E.U），拉伸面积135cm2。两年检测结果均达国家级品种审定中强筋小麦标准。产量和抗性表现：2014-2016年度参加江苏省淮南组小麦区域试验，两年平均亩产475.1公斤，较对照扬麦20增产4.6%。2015-2016年度参加生产试验，平均亩产496.9公斤，较对照扬麦20增产4.2%。', '1、适宜播期10月25日至11月10日。2、适期播种每亩基本苗18万左右，中低产田或迟播应适当增加。3、一般亩施纯氮15-18公斤。氮肥基苗肥占60%，拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (82, 1, '宁麦资166', '苏审麦20200007', '2020.11', 0, '江苏省农作物品种审定委', '江苏神农大丰种业科技有限公司、江苏省农业科学院种 质资源与生物技术研究所', 'IDO580-22/宁麦 13//镇麦 6 号/3/偃高 1 号/烟农 159//优繁 5 号/农大糯麦 1 号，参试名称“宁麦资 166”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，分蘖力较强，抗寒性较好。 株型较紧凑，穗层较整齐，抗倒性较好，熟相好。穗纺锤形，长芒、白 壳、红粒，籽粒角质。区试平均结果:全生育期 201.0 天，比对照扬麦 20 短 1.4 天。株高 84.1 厘米，每亩有效穗 31.4 万，每穗 36.5 粒，千粒 重 47.1 克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农 业科学研究所鉴定:中抗赤霉病(接种鉴定抗赤霉病，严重度 1.4、1.3; 自然发病鉴定中抗赤霉病，病指 0.4、1.5)，抗白粉病、黄花叶病，中抗 条锈病，高感纹枯病、叶锈病。经江苏省农业科学院种质资源与生物技 术研究所鉴定:抗穗发芽。经农业部谷物品质监督检验测试中心测定: 容重 808 g/L、779g/L，粗蛋白质(干基)15.0%、14.0%，湿面筋 31.9%、 28.6 %，吸水率 65%、67 %，稳定时间 21.8 min、1.7 min，最大拉伸阻\n—9—\n力 798 E.U.、250 E.U.，拉伸面积 166 cm2、65 cm2，硬度指数 66.8、66.5。 2017-2018 年度品质指标达到强筋小麦品种审定标准。产量和抗性表现：2016-2018 年度参加江苏省淮南小麦 B 组区试，两年平均 亩产 492.9 公斤，比对照扬麦 20 增产 3.6%。2018-2019 年度参加生产试 验，平均亩产 491.0 公斤，比对照扬麦 20 增产 3.5%。', '1、适宜播期 10 月 25 日至 11 月 10 日。2、适期 播种每亩基本苗 16 万左右，中低产田或迟播适当增加。3、一般亩 施纯氮 15-18 公斤，其中基苗肥占 60%、拔节孕穗肥占 40%，同时 配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝 暗渍。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、 叶锈和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (83, 1, '宁麦资518', '苏审麦20200001', '2020.11', 0, '江苏省农作物品种审定委', '江苏省农业科学院种质资源与生物技术研究所、河南大学', '资 02-193/扬麦 15// Tabasco，参试名称“宁麦资 15318”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，分蘖力较强。株型较紧凑，穗层较整齐，抗倒性中等。穗纺锤形，长芒、白壳、红粒，籽粒半角质。 区试平均结果:全生育期 208.7 天，比对照扬麦 20 短 1.0 天。株高 80.7 厘米，每亩有效穗 32.0 万，每穗 36.1 粒，千粒重 48.4 克。经江苏省农 业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定:中 抗赤霉病(接种鉴定中抗赤霉病，严重度 1.0、2.2;自然发病鉴定中抗 赤霉病，病指 4.5、0.0)，感黄花叶病毒病，高感白粉病、纹枯病、条锈 病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定:抗 穗发芽。经农业部谷物品质监督检验测试中心测定:容重 794g/L、818g/L， 粗蛋白(干基)14.9%、14.0%，湿面筋 30.0% 、29.4%，吸水率 57%、59%， 稳定时间 4.2min、3.6min，最大拉伸阻力 236E.U.、215E.U.，拉伸面积 56cm2、47cm2，硬度指数 50.8、53.9。产量和抗性表现：2017-2019 年度参加江苏省淮南小麦 A 组区试，两年平 均亩产 508.4 公斤，比对照扬麦 20 增产 5.7%。2019-2020 年度参加生产 试验，平均亩产 517.6 公斤，比对照扬麦 20 增产 5.7%。', '1、适宜播期 10 月 25 日至 11 月 5 日。2、适期播种 每亩基本苗 16 万左右，中低产田适当增加。3、一般亩施纯氮 18 公斤， 其中基苗肥占 60%、拔节孕穗肥占 40%，同时配合施用磷钾肥，后期适 当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除 田间杂草。注意防治纹枯病、赤霉病、白粉病、锈病和蚜虫等病虫害。\n审定意见:通过审定，适宜在江苏省淮南麦区种植。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (84, 1, '宁麦资958', '苏审麦20210009', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院种质资源与生物技术研究所', 'OK101/资02-193//扬麦15/3/镇麦168，参试名称“宁麦资16500”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗半直立，叶色较深，分蘖性好。株型较紧凑，抗倒性强。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒角质。区试平均结果：全生育期209.3天，比对照扬麦20短1.9天。株高83.9厘米，每亩有效穗31.7万，每穗38.6粒，千粒重44.3克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.6、1.15、1.50；自然发病鉴定中抗赤霉病，病指0.63、0.83、8.10），中抗黄花叶病毒病，中感条锈病，高感纹枯病、白粉病、叶锈病。经江苏省农业科学院种质资源与生物研究所鉴定：高抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重820g/L、821g/L，粗蛋白(干基)含量14.8%、14.3%，湿面筋含量30.9%、30.6%，吸水率60.6%、63.1%，稳定时间14.0min、7.7min，最大拉伸阻力655E.U.、534E.U.，拉伸面积123cm2、100cm2，硬度指数61.1、61.5。2018-2019年度、2019-2020年度品质指标分别达强筋、中强筋小麦品种审定标准。产量和抗性表现：2018-2020年度参加江苏省淮南小麦B组区试，两年平均亩产508.0公斤，比对照扬麦20增产2.6%。2020-2021年度参加生产试验，平均亩产460.2公斤，比对照扬麦20增产3.3%。', '1、适宜播期10月25日至11月10日。2、适期播种每亩基本苗20万左右，中低产田适当增加。3、一般亩施纯氮15-18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治白粉病、纹枯病、赤霉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (85, 1, '宁麦资999', '苏审麦20220004', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院种质资源与生物技术研究所、江苏省高科种业科技有限公司', '宁麦资218/扬麦17//镇麦12号', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，分蘖力较强。株型紧凑，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒角质。省区域试验平均结果：全生育期211.2天，比对照扬麦20短0.5天，株高85.9厘米，每亩有效穗32.6万，每穗37.0粒，千粒重47.7克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.61、1.50；自然发病鉴定中抗赤霉病，病指0.68、0.29），高感白粉病，感纹枯病，中抗条锈病、黄花叶病毒病，高抗叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重810g/L、798g/L，粗蛋白质含量（干基）14.2%、15.1%，湿面筋含量31.8%、30.2%，吸水率64%、63%，稳定时间9.2min、9.3min，最大拉伸阻力479E.U.、458E.U.，拉伸面积93cm2、105cm2，硬度指数63.8、61.7。2020年、2021年品质检测结果均达到中强筋小麦品种标准。产量和抗性表现：2020-2021年度参加江苏省淮南B组小麦品种区域试验，两年平均亩产511.2公斤，比对照扬麦20增产4.6%。2021-2022年度参加生产试验，平均亩产527.5公斤，比对照扬麦20增产4.2%。', '2020-2021年度参加江苏省淮南B组小麦品种区域试验，两年平均亩产511.2公斤，比对照扬麦20增产4.6%。2021-2022年度参加生产试验，平均亩产527.5公斤，比对照扬麦20增产4.2%。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (86, 1, '建麦1号', '苏种审字第388号', '2000', 0, '江苏省农作物品种审定委员会', '建湖县农科所', '泗阳936系选', '江苏盐城以北及淮北沙壤土地区', '退出批次：特征特性：该品种幼苗半匍匐，抗寒性一般，叶片短窄，叶色较绿。分蘖性较强，成穗率中等。株高90厘米左右，株型较松散，剑叶宽大。茎秆粗壮，抗倒性较好。该品种亩有效穗33—38万，每穗粒数34—38粒，千粒重30— 40克。长芒、白壳、纺锤形穗，籽粒粉质、皮色深。该品种中感一中抗赤霉病，中抗纹枯病，高抗一抗梭条花叶病，中抗条锈病，中感白粉病。该品种蛋白质含量13.5％，湿面筋含量为28.9％，沉降值为40毫升，降落值为259秒，吸水率为54.5％，面团形成时间为l .5分钟，稳定时间为1. 6分钟，粉质评价值37分（南京经济学院，2000年），属于弱筋力小麦品种。全生育期为241天左右，熟期偏迟．后期熟相较好。产量和抗性表现：该品种1997—2000年度参加江苏省淮北小麦中间试验。1997—1998年度省区试平均亩产308 .15公斤，比对照陕229增产1.70％，增产不显著；1998—1999年度省区试平均亩产433 .96公斤，比对照减产0.10％，减产不显著；1999—2000年度参加省淮北小麦生产试验，平均亩产442.19公斤，比对照陕229增产6.10％。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (87, 1, '徐农029', '苏审麦20160007', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏徐农种业科技有限公司', '淮麦20/矮抗58，参试名称“徐农0029”', '江苏省沿淮麦区及淮北麦区晚茬口种植', '特征特性：半冬性中熟品种，成熟期与对照品种淮麦20相当。幼苗半匍匐，叶片短小，叶色深绿，前期长势慢，抗寒性较好。分蘖力较强，成穗数较多。株型较松散，剑叶适中、挺，叶色绿色，茎杆弹性一般。穗纺锤型，穗长码稀，长芒、白壳、白粒，籽粒角质。区试平均结果：全生育期217.0天，株高84.0厘米，每亩有效穗40.4万，每穗33.9粒，千粒重41.5克。落黄晚，后期叶功能期长，成熟中等，熟相好。经江苏省农科院植保所三年接种鉴定：中感~中抗赤霉病（严重度1.75-2.58），中感纹枯病，高感白粉病，中抗黄花叶病。经江苏省农科院粮作所鉴定：中抗穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：容重820克/升，粗蛋白含量13.1%，湿面筋含量28.5%，稳定时间7.1分钟，硬度指数68.1。产量和抗性表现：2013-2015年度参加江苏省淮北晚播组小麦区域试验，两年平均亩产527.9公斤，较对照郑麦9023增产9.6%，两年均达极显著水平，较对照淮麦20增产3.5%，2014年达显著水平，2015年达极显著水平。2015-2016年度参加生产试验，平均亩产536.65公斤，较对照淮麦20增产2.9%。', '1、播期弹性较大，最适播期为10月10-25日。2、一般每亩基本苗15-25万，肥力水平偏低或播期推迟，应适当增加。3、一般亩施纯氮14-16公斤，配合施用磷、钾肥。氮肥基苗肥占50%，拔节孕穗肥占50%。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (88, 1, '徐州20', '苏种审字第52号', '1985', 0, '江苏省农作物品种审定委员会', '徐州地区农科所', '徐州17/郑州741', '江苏淮北地区', '退出批次：特征特性：幼苗直立，繁茂性好。株高90厘米左右，茎杆较粗壮，弹怀较差，叶片较宽披，叶色销深。生长整齐清秀，成穗率较高，每亩37.8—44.46万，平均41.9万穗左右。穗长方形，长芒、白壳，结实性好。每穗实粒31.2—33.6，千粒重一般35.5—39克，头年同系32.66克。白皮、粉质，品质一般。粗蛋白含量偏低，约11.65%，赖氨酸含量0.36%，出粉率81%，吸水率68.4%，面筋拉力好，延伸度19.5厘米，拉伸阻力4.3厘米，降落值299秒，糊化温度较高，煮面条不易糊汤，拉力较好，较适于做面条、饺皮。但湿面筋含量偏低，为20—24%。熟期较适宜，全生育期230天左右，比济南13早熟4—5天，耐迟播。稳产性较好。高抗条锈、杆锈病。白粉病较轻。缺点：春寒冻害偏重。中感叶锈病。茎杆弹性稍差，不耐同肥，肥过多较易倒伏。成熟后迂雨有穗发芽现象。产量和抗性表现：1980—82年连续三年参加省淮北片高肥组小区域试验，平均亩产分别为856.8斤、877.3斤、850.7斤；比郑州761分别增产4.43%、减产0.9%，增产5.6%。1983年省生产试验，平均亩产755.9斤，比济南13号减产2.7%，不显著。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (89, 1, '徐州21', '苏种审字第66号', '1986', 0, '江苏省农作物品种审定委员会', '徐州地区农科所', '濮农3665/O.P301(印度)', '江苏淮北麦区北部', '退出批次：特征特性：幼苗半直立，生长茁壮，叶色深绿。株高85厘米左右，株型略松，茎杆矮壮，较耐肥抗倒。上部时片宽大略披，叶色深绿，生长较整齐、清秀。分蘖力较强，成穗较高，省区域试验和生产试验（下同）平均每亩28.4万、31.6万穗；分别比郑州741高2.68万、3.84万穗，穗层整齐，穗长方形，穗形中等偏大，着粒较密，每穗平均分别为29.5粒、35.18粒，分别比郑州741少4.5粒、增0.53粒。长芒、白壳、白粒，粒形较大，平均千粒重39.5克、39.72克分别比郑州741高3.6克。粒重较稳定，灌浆速度较快，籽粒饱满度较好，半角质，籽粒外观品质及营养加工品质较好，粗蛋白含量13.5%左右，湿面筋含量较高为31—35%，延伸度17.5厘米，拉伸阻力350BΜ做馒头、面包松软有弹性，做面条、较皮拉力较好，有咬劲。全生育期20天左右，比郑州741迟熟1—2天，略晚熟，成熟转色较好。高抗条锈、杆锈病，轻感叶锈病，较耐纹枯病。感赤霉病，1985年株发病率比郑州741高6.6%。白粉偏重，株发病率比郑州741高12.5%。春寒冻害偏重。株型略松，后期群体偏大时荫蔽较重；后期耐湿性中等，低湿试点发病较重。产量和抗性表现：1984—85年连续两年参加淮北片小麦组区域试验1984年平均亩产792.83斤，比郑州71增产3.4%，不显著；1985年亩产739.1斤，比郑州741增产3.3%，不显著。同年省生产试验（6点）平均亩产750.38斤，比郑州741增产12.8%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (90, 1, '徐州22', '苏种审字第145号', '1991', 0, '江苏省农作物品种审定委员会', '徐州市农科所', '徐州2962系选', '江苏淮北麦区', '退出批次：特征特性：幼苗半匐铺，叶色绿。株主85—90厘米，株型较松散，茎杆中粗，韧性较好，较耐肥抗倒。分蘖力中等，成穗率数较少，每亩有效穗平均36.5万左右，经济南13号少6.5万左右。穗纺锤形，长芒、红壳、白粒、着粒偏密。穗大粒多，每穗平均实粒31粒左右，千粒重38我左右，容重较高，804克/升左右。品质良好，粗蛋白含量14.79%，赖氯酸含量0.34%，灰分1.94%，付号粉出粉率77.7%，湿在筋含量达38.1%，同团延伸13.5厘米，拉伸阻力265Bμ。全生育期237天左右，比济南13早一天左右。较耐西南旱风。长相清秀，熟色较好。高抗杆锈病，常年赤霉病和穗发芽较轻。冻害略重于济南13，中感中锈病和白粉病，纹枯病偏重。产量和抗性表现：1988、1989年连续两年参加省淮北片小麦品种区域试验，平均亩产为414.57、392.33公斤，分别经济南13号增产5.25%、17.44%，分别达显著、极显著标准，均居参试品种第二位。1990年省生产试验单产400.07公斤，比济南13增产27.99%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (91, 1, '徐州23', '苏种审字第183号', '1993', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农科所', '徐州21/郑州761', '江苏淮北麦区', '退出批次：特征特性：幼苗直立，生长茁壮。打株高83厘米左右，株型略松散。茎秆较粗但壁稍薄。叶征宽大，叶色淡绿。春发性较好，分蘖力偏弱，每亩有效穗37万左右。长芒、白壳、白粒、多穗大粒，穗层整齐，穗近长方形，每穗实粒数30左右。灌浆速度快，籽粒大而饱满，半硬质，千粒重41左右，不易落粒。出粉率68.9%.蛋白质10.5%，湿面筋29.7%，干面筋10.5%，吸水率64.6%，衰减并140Bμ，综合评价36分，较适于作馒头面条。全生育期223天左右，比济南13、徐州都早熟4天左右，落黄正常熟相好。高抗秆锈病，中抗条锈病，赤霉病明显比济南13、徐州21轻，纹枯病较重，耐寒性、耐肥抗倒性产差。产量和抗性表现：1990、1991年连续两年参加省淮北小麦品种区域试验，平均单产分别为395.58公斤、335.4公斤，分别比济南13增产24.1%(极显著)和减产0.5%(不显著)。1992年参加省小麦生产试验，平均单产433.9公斤，比徐州2.6%，', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (92, 1, '徐州24号', '苏种审字第226号', '1994', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农科所', '徐州7904-13-2-3/矮孟牛', '江苏淮北麦区', '退出批次：特征特性：幼苗半匍状，叶片较宽大，叶色深绿，生长健壮。株高85厘米在左右，株型较紧凑，茎秆粗壮，弹性较好，较耐肥抗倒。上部叶片较宽，叶色稍淡。分蘖力、成穗率中等，亩有效穗37—42万，穗层整齐。穗纺锤形，穗长码稀，长芒、白壳、白粒，每穗实粒数28—32粒，灌浆快，千粒重高而稳定，常年在45克以上，省中间试验三年平均为46.6克。籽粒饱满均匀，白皮大粒，半角质或粉质，外观品质较好。粗蛋白含量11.2%，湿面筋含量33.7%，干而筋含量9.5%，面团形成时间2分钟，稳定时间1.9分钟，拉伸阴力250BΜ，延伸性14.5㎝，拉伸比数1.73，粉质曲线面积45.4，评价值35。生育期240天左右，比冀84—5418晚熟三天左右。高抗叶锈、秆锈病、中抗条锈病，白粉病较轻。较耐“倒春寒”，结实性好。耐旱，较耐干热风，中感纹枯病、赤霉病，中后期有叶尖枯、叶枯现象，但对灌浆影响大。罹蚜虫，种子休眠期稍短。苗期耐寒性稍差，忌早播。产量和抗性表现：1991—1993年连续两年参加省淮北小麦品种区域试验，平均单分别为453.20公斤、462.66公斤，比冀84_5418增产3.69%1994年参加淮北小麦生产试验，平均单产422.41公斤，比冀84_5418增产12.98%，三年试验产量均居第二位。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (93, 1, '徐州25号', '苏种审字第282号', '1997', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农科所', '徐7904-13-2-2/百泉792', '江苏淮北麦区', '退出批次：特征特性：幼苗匍匐，叶较窄，剑叶宽大，叶色深绿，抗寒性较好。株高80—85厘米，株型较紧凑，茎秆粗壮，弱性较好，基部节间较短、壁厚，充实度较好，较耐肥抗倒。分蘖力中等偏强，低位分蘖率及成穗率较高，亩穗数38万左右，比对照低3万穗左右。穗层整齐。长芒、白壳、白粒，穗长方形，穗短，着粒密，结实性好，每穗平均40.75粒，比对照增6.15粒。灌浆速度较快。千粒重较高而稳定，千粒重42.6克，比对照高8.3克。品质较好，粗蛋白含量11.2%，湿面筋含量31.2%，沉降值27秒，降落值394S，吸水率60%，面团形成时间2.2分钟，同团稳定时间3.3分钟，面团裂时间5.2分钟，衰减度10B·U，粉质评价值47分。生育期231.1天，比对照迟熟3天左右。耐倒春寒。叶征功能期限较长，后期干尖略轻。抗旱、抗干热风能力好于对照。中抗条锈病，中感白粉病、叶锈病，赤霉病。纹枯现较重，易出现干芒尖。产量和抗性表现：1993年至1995年连续两年度参加江苏省淮北小麦品种区域试验，平均每亩产别为556.92公斤和533.9公斤，比对照品种冀84—5418增产8.15%和19.85%，均达极显著水准。1996—1997年度在生产试验中亩产469.3公斤，比对照增产13.6%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (94, 1, '徐州26号', '苏种审字第385号', '2000', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农科所', '小偃6号/陕7859', '江苏淮北麦区', '退出批次：特征特性：该品种幼苗偏直立，叶片细长，叶色浅绿。分蘖性中等，成穗率较高。株高95厘米左右，茎秆偏高，抗倒性一般。株型紧凑，长相清秀，剑叶上冲，有干尖现象，穗层整齐度一般。该品种亩有效穗40—45万左右，每穗粒数25—30粒，千粒重40—50克。无芒、白壳、纺锤型穗，结实性一般。籽粒饱满、角质、白皮，外观商品性好。该品种轻感条锈病，中感白粉病，中感纹枯病，中感赤霉病。该品种容重780克/升，蛋白质含量15.5％，湿面箭含量45.6％，沉降值38毫升，降落值355秒，吸水率67.1％，面团形成时间3.8分钟，稳定时问4.3分钟，断裂时间6.7分钟，粉质评价值53分（南京经济学院，2000年），属于中筋力小麦品种。全生育期为237天左右，后期熟相佳。产量和抗性表现：该品种1998—2000年度参加江苏省淮北小麦中间试验。1998—1999年度省区试平均亩产454 .03公斤，比对照陕229增产4.52％，达极显著水平；1999—2000年度省区试平均亩产452.89公斤，比对照增产3.57％，达极显著水平；1999—2000年度参加省淮北小麦生产试验，平均亩产439 00公斤，比对照陕229增产3 05％。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (95, 1, '徐州2962', '苏种审字第51号', '1985', 0, '江苏省农作物品种审定委员会', '徐州地区农科所', '叶考拉/徐州32331', '江苏淮北中部、东部', '退出批次：特征特性：幼苗半匍伏，生长稳健，苗期较耐涝渍。株高75厘米左右，株型略松。矮杆抗倒，茎杆中粗弹性较好。叶片中宽稍挺，叶色深绿。分蘖力强，成穗率高，一般每亩49.1万穗左右。多穗大粒，穗纺锤形，穗长7—8厘米，长芒、红壳。每穗17—19排小穗，不实小穗2—3排，每穗实粒26.4—28.4粒左右。籽粒卵元形，饱满度中等，千粒重36.8—39.5克，腹沟较深，硬质白色略黄。品质较优，粗蛋白含量13.2—13.9%，赖氨酸含量0.36—0.37%；出粉率81%，吸永率高，为4.5%，面团形成时间9分钟，稳定时间10分钟，衰减度30Bμ，拉伸阻力6.3厘米。延伸度16.3厘米，比值较高0.38，降落值298秒，基本符合小麦指标，温面筋含量偏低为26%—29.5%。全生育期235天左右，比济南13号早熟2天左右。丰产性较好，越冬性较好，中期生长稳健，后期灌浆较快。高抗条锈、杆锈病。缺点是抗春霜冻害能务较弱，迂春霜顶部小穗不实，有“糖盖顶”现象。纹枯病、亦霉病较重，中感叶锈、白粉病。耐干旱、瘠、盐碱能力较差。后期叶片干尖、熟相较差。产量和抗性表现：1983—84年连续两年参加淮北片小麦组区域试验，平均亩产分别为782.66斤、880.25斤，分别比郑州761、济南13号增产18.5%、3.91%。1984年省生主试验，平均亩产909.8斤，比济南13号增产11.71。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (96, 1, '徐麦100', '苏审麦20210011', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏三好种业科技有限公司', '徐麦30/徐麦114427，参试名称“徐麦302”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色淡绿。分蘖力强，抗寒性较好。株型较紧凑，抗倒性较好。拔节起身早，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒圆形，角质。区试平均结果：全生育期229天，比对照淮麦20短1.1天。株高79.0厘米，每亩有效穗41.7万，每穗34.7粒，千粒重45.6克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.57、1.75；自然发病鉴定中抗赤霉病，病指2.84、1.39），高抗条锈病，中抗黄花叶病，高感纹枯病、白粉病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：感穗发芽。品质经农业部谷物品质监督检验测试中心两年测定：容重825g/L、824g/L，蛋白质（干基）含量14.0%、14.9%，湿面筋含量32.5%、33.7%，吸水率62%、63.2%，稳定时间11.4min、3.4min，最大拉伸阻力420E.U.、213E.U.，拉伸面积84cm2、43cm2，硬度指数65.0、65.0。2018-2019年度品质指标达中强筋小麦品种审定标准。产量和抗性表现：2018-2020年度参加江苏省淮北小麦A组区试，两年平均亩产619.3公斤，比对照淮麦20增产6.3%。2019-2020年度参加生产试验平均亩产583.0公斤，比对照淮麦20增产5.7%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗15万-18万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮18公斤左右，配合施用磷、钾肥。其中氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、白粉病、赤霉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (97, 1, '徐麦136', '苏审麦20220031', '2023.01', 0, '江苏省农作物品种审定委员会', '徐州佳禾农业科技有限公司', '中麦895/徐9098', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿，分蘖力较强，株型半紧凑，穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒角质。联合体区域试验平均结果：全生育期226.4天，比对照淮麦20长0.6天，株高77.9厘米，每亩有效穗41.8万，每穗36.9粒，千粒重46.2克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：感赤霉病（接种鉴定中感赤霉病，严重度2.25、3.50；自然发病鉴定感赤霉病，病指4.81、28.13），高感纹枯病、白粉病，中感条锈病、叶锈病、黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重821/L、825g/L，粗蛋白质含量（干基）14.0%、13.6%，湿面筋含量32.8%、32.8%，吸水率61%、62%，稳定时间3.3min、2.7min，最大拉伸阻力145E.U.、121E.U.，拉伸面积34cm2、27cm2，硬度指数62.9。产量和抗性表现：2019-2021年度参加江苏省大华科企淮北小麦联合体区域试验，两年平均亩产582.5公斤，比对照淮麦20增产6.6%。2020-2021年度参加生产试验，平均亩产605.3公斤，比对照淮麦20增产4.2%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩14万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮17公斤左右，其中基苗肥占60%、拔节肥占20%、孕穗肥占20%，同时配合施用磷钾肥，后期适当喷施叶面肥。注意化控控高、防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (98, 1, '徐麦185', '苏审麦20210028', '2021.12', 0, '江苏省农作物品种审定委员会', '徐州佳禾农业科技有限公司', '新麦26/徐麦32，参试名称“佳麦1805”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿。分蘖力较强，成穗数较多，抗寒性较好。株型较紧凑，抗倒性较好，穗层整齐，熟相好，穗纺锤形，长芒、白壳、白粒，籽粒角质。抗倒性较强，熟相好。区试平均结果：全生育期平均226.6天，与对照淮麦20相当。株高78.4厘米，每亩有效穗41.0万，穗粒数36.2粒，千粒重46.9克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度3.35、1.19、3.45，自然发病鉴定中感赤霉病，病指3.47、5.68、20.0），中感黄花叶病，高感纹枯病、白粉病、条锈病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业部谷物品质监督检验测试中心测定：容重787g/L、833g/L，蛋白质（干基）13.4%、13.2%，湿面筋含量27.6%、27.8%，吸水率60.4%、61.5%，稳定时间8.5min、5.6min，最大拉伸阻力469E.U.、217E.U.，拉伸面积70cm2、43cm2，硬度指数66.3、63.5。产量和抗性表现：2018-2020年度参加江苏省淮北小麦大华种业科企联合体区试，两年平均亩产586.4公斤，比对照淮麦20增产4.9%。2020-2021年度参加生产试验平均亩产597.4公斤，比淮麦20增产6.9%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗15万-20万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮16公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (99, 1, '徐麦27号', '苏审麦200302', '2003', 0, '江苏省农作物品种审定委员会', '江苏省徐淮地区徐州市农科所', '早丰1号/烟1934', '江苏淮北麦区', '退出批次：特征特性：该品种幼苗半匍匐，苗壮，叶片较宽大，叶色较绿，分蘖性较强，株型较松散，穗层较整齐，长相清秀，株高85厘米左右，穗纺缍形，长芒、白壳、白粒，结实性一般，籽粒角质。每亩穗数40万左右，每穗实粒数30粒左右，千粒重40克左右，较陕229高6-7克。全生育期230天左右，较陕229早熟4天左右。中感条锈病、叶锈病，纹枯病较轻，白粉病较重，赤霉病较陕229轻，耐肥抗倒性一般，熟相好。据2000年南京经济学院检测：容重775克/升，粗蛋白15.61%，湿面筋37.5%，形成时间4.3分钟，稳定时间7.4分钟，为强筋小麦，品质达到国标二级优质面包小麦标准。产量和抗性表现：2000-2002年度参加江苏省区域试验，2000-2001年度平均亩产490.81公斤，较对照陕229增产7.26%，达极显著水平；2001-2002年度平均亩产440.79公斤，较对照增产8.0%。两年平均亩产468.96公斤，较对照增产7.56%。2002-2003年度组织生产试验，平均亩产372.8公斤，较对照增产3.3%。该品种有一定产量水平，品质优，抗病性较好。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (100, 1, '徐麦30', '苏审麦200704', '2007.9', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农业科学研究所', '周91098/徐州25号', '适宜江苏省淮北麦区种植', '退出批次：特征特性：长芒，白壳，白粒，纺锤型穗，籽粒半硬质；幼苗半匍匐，叶色深绿，叶片宽，抗寒性较好分蘖力较强，成穗数较多株型较松散，长相清秀，株高85厘米左右，茎秆弹性较好全生育期239天左右，比对照长3-4天亩有效穗39万左右，每穗31粒左右，千粒重45克左右接种鉴定结果：感赤霉病，中感纹枯病，高感梭条花叶病毒病，感穗发芽田间表现中感白粉病、纹枯病，叶锈病发生轻；重感条锈病品质分析两年平均结果:蛋白含量12.4%，湿面筋含量26.7%，稳定时间2.5分钟产量和抗性表现：2004-2006年度参加江苏省区域试验，两年平均亩产517.4公斤，较对照淮麦18增产1.9%，其中2005-2006年度较对照增产达极显著水平；2006-2007年度组织生产试验，平均亩产517.8公斤，较对照增产4.6%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (101, 1, '徐麦31', '苏审麦200904', '2009.9', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农业科学研究所', '烟辐188/徐州26', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗偏匍匐，叶色淡绿，长势较旺，抗寒性一般。分蘖力中等，成穗数较多。株型较紧凑，茎杆弹性好，抗倒性较好，剑叶挺，有干尖。纺锤型穗，结实性较好。无芒，白壳，白粒，籽粒半硬质-硬质，千粒重高。省区试平均结果：全生育期231.4天，较对照淮麦18迟熟1天；株高87.1厘米，每亩有效穗38.9万，每穗31.7粒，千粒重43.7克。接种鉴定结果：感赤霉病，中抗纹枯病，中感白粉病，高抗梭条花叶病。经农业部谷物品质监督检验测试中心测定，两年平均结果：容重796克/升，粗蛋白含量16.0%，湿面筋含量36.1%，稳定时间6.5分钟；2008年容重821克/升，粗蛋白含量15.0%，湿面筋含量34.3%，稳定时间7.6分钟。产量和抗性表现：2006-2008年度参加江苏省区域试验，两年平均亩产526.1公斤，较对照淮麦18增产4.5%。2008-2009年度参加生产试验，平均亩产505.0公斤，较对照淮麦18增产4.2%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (102, 1, '徐麦32', '苏审麦201206', '2012.11', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农业科学研究所', '淮麦18/周麦16', '江苏省淮北麦区种植', '退出批次：特征特性：该品种表现幼苗半直立，叶色深绿，抗寒性较好分蘖力一般，成穗数中等株型较紧凑，茎秆弹性较好，抗倒性较好穗层较厚，熟相好，纺锤型穗，结实性较好长芒、白壳、白粒，籽粒半硬质区试平均结果：全生育期241.4天，比对照迟熟1-2天；株高73.9厘米，每亩有效穗42.5万穗，每穗32.7粒，千粒重40.4克接种鉴定结果：感赤霉病，中感纹枯病、白粉病，感黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2008-2010年度两年平均结果：容重819.5克/升，粗蛋白含量14.1%，湿面筋含量30.2%，稳定时间17.6分钟产量和抗性表现：2009-2011年度参加江苏省淮北组小麦区域试验，两年平均亩产528.9公斤，较对照淮麦20增产5.2%，两年增产均达极显著水平2011-2012年度参加生产试验，平均亩产535.7公斤，较对照增产4.6%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (103, 1, '徐麦35', '苏审麦201502', '2015', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农业科学研究所', '新麦93119/周麦16', '江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶片较宽大，叶色深绿分蘖力较强，越冬抗寒性较好，抗倒春寒性一般株型较紧凑，穗层整齐，茎秆弹性较好，抗倒性较强落黄晚，后期叶功能期长，熟相较好穗纺锤形，长芒、白壳、白粒，籽粒椭圆形，半硬质-硬质区试平均结果：全生育期232.4天，比对照晚0.7天，株高80.5厘米，每亩有效穗41.5万，每穗35.8粒，千粒重42.0克抗病性经江苏省农科院植保所三年接种鉴定：感赤霉病、白粉病，中感纹枯病，高感小麦黄花叶病毒病品质经农业部谷物品质监督检验测试中心测定，两年区试测定平均结果：容重808克/升，粗蛋白含量12.8%，湿面筋含量28.1%，稳定时间3.5分钟，硬度指数68.7产量和抗性表现：2012-2014年度参加江苏省淮北组小麦区域试验，两年平均亩产561.56公斤，较对照淮麦20增产6.09％，两年增产均达极显著水平2014-2015年度参加生产试验，平均亩产559.5公斤，较对照淮麦20增产7.07％', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (104, 1, '徐麦38', '苏审麦20200013', '2020.11', 0, '江苏省农作物品种审定委', '江苏徐淮地区徐州农业科学研究所', '淮麦 18/徐 7048，参试名称“徐麦 14123”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，抗寒性较好，拔节起身中等，分蘖力较强。株型较紧凑，蜡质重，抗倒性较好，剑叶挺，穗层 整齐，灌浆快、结实性较好，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒角质。区试平均结果:全生育期 227.0 天，比对照淮麦 20 长 0.5 天。 株高 79.8 厘米，每亩有效穗 42.4 万，每穗 34.0 粒，千粒重 43.3 克。经 江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所 鉴定:感赤霉病(接种鉴定感赤霉病，严重度 3.7、3.4;自然发病鉴定 感赤霉病，病指 27.8、3.1)，中抗黄花叶病，中感白粉病，高感纹枯病、 叶锈病、条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定: 高感穗发芽。经农业部谷物品质监督检验测试中心测定:容重 831g/L、 832g/L，蛋白质(干基)14.6%、13.2%，湿面筋 28.2%、29.6%，吸水率 59%、58%，稳定时间 9.8min、10.8min，最大拉伸阻力 338E.U.、521E.U.， 拉伸面积 66cm2、85cm2，硬度指数 59.4、54.4。2018-2019 年度品质指标 达到中强筋小麦品种审定标准。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦 A 组区试，两年平均 亩产 588.9 公斤，比对照淮麦 20 增产 6.9%。2019-2020 年度参加生产试 验，平均亩产 583.9 公斤，比对照淮麦 20 增产 5.9%。', '1、适宜播期 10 月 5 日-25 日。2、适期播种每亩基 本苗 14 万-18 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯 氮 15-18 公斤左右，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗 肥占 40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注 意防涝抗旱。4、冬前及早春及时防除田间杂草。及时防治纹枯病、赤霉 病、白粉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (105, 1, '徐麦39', '苏审麦20200030', '2020.11', 0, '江苏省农作物品种审定委', '江苏徐淮地区徐州农业科学研究所', '周麦 16/淮核 0615，参试名称“徐麦 135”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿，幼苗长势正常，抗寒性较好，拔节起身中等，分蘖力较强。株型较紧凑，蜡质重，茎秆 粗壮，抗倒性较好，剑叶细长、挺，穗层整齐，灌浆快，结实性较好， 熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒半角质。区试平均结果:全生育期 225.9 天，比对照淮麦 20 长 0.5 天。株高 77.9 厘米，每亩有效 穗 41.0 万，每穗 34.3 粒，千粒重 44.3 克。经江苏省农业科学院植物保 护研究所、江苏徐淮地区徐州农业科学研究所鉴定:感赤霉病(接种鉴 定 感 赤 霉 病 ，严 重 度 3 . 7 0 、3 . 6 ;自 然 发 病 鉴 定 感 赤 霉 病 ，病 指 2 1 . 7 、6 . 3 )， 抗条锈病，感纹枯病、黄花叶病，高感白粉病、叶锈病。经江苏省农业 科学院种质资源与生物技术研究所鉴定:高感穗发芽。经农业部谷物品 质监督检验测试中心测定:容重 788g/L、784.6g/L，蛋白质(干基)14.6%、 13.6%，湿面筋 27.1%、25.9%，吸水率 52%、51%，稳定时间 5.5min、 2.0min，硬度指数 34.3。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦徐州农科所科企联合 体区试，两年平均亩产 546.0 公斤，比对照淮麦 20 增产 4.3%。2019-2020 年度参加生产试验，平均亩产 559.2 公斤，比对照淮麦 20 增产 6.2%。', '1、适宜播期 10 月 5 日-25 日。2、适期播种每亩基 本苗 14 万-18 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯 氮 15-18 公斤，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗肥占 40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防 涝抗旱。4、冬前及早春及时防除田间杂草。及时防治纹枯病、赤霉病、 白粉病、叶锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (106, 1, '徐麦42', '苏审麦20210026', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农业科学研究所', '徐麦7048/淮麦0615，参试名称“徐麦021”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿，幼苗长势正常，抗寒性较好，拔节起身中等，分蘖力较强。株型较松散，蜡质重，茎秆粗壮，抗倒性中等，剑叶细长、挺，穗层整齐，灌浆快，结实性较好，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒半角质。区试平均结果：全生育期229.3天，比对照淮麦20短0.9天。株高83.5厘米，每亩有效穗41.3万，每穗36.0粒，千粒重44.0克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：感赤霉病（接种鉴定感赤霉病，严重度3.68、3.20、3.59；自然发病鉴定感赤霉病，病指6.91、9.64、34.0），中抗黄花叶病、中感条锈病，高感纹枯病、白粉病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业部谷物品质监督检验测试中心测定：容重840g/L，蛋白质（干基）14.9%、13.2%，湿面筋含量28.4%、26.9%，吸水率52.1%、56.4%，稳定时间12.1min、5.8min，最大拉伸阻力657E.U.，拉伸面积90cm2，硬度指数47.4、51.4。产量和抗性表现：2018-2020年度参加江苏省淮北小麦徐州农科所科企联合体区试，两年平均亩产583.4公斤，比对照淮麦20增产5.3%。2020-2021年度参加生产试验平均亩产576.7公斤，比对照淮麦20增产5.8%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗14万-18万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮15-18公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。及时防治纹枯病、赤霉病、白粉病、叶锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (107, 1, '徐麦46', '苏审麦20220036', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农业科学研究所', '徐7048/淮核0615', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿，分蘖力较强。株型较松散，穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒半角质。联合体区域试验平均结果：全生育期228.3天，比对照淮麦20短0.7天，株高87.1厘米，每亩有效穗42.2万，每穗36.9粒，千粒重44.6克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度1.55、3.30；自然发病鉴定中感赤霉病，病指4.67、7.81），高感白粉病、纹枯病，中感叶锈病，中抗条锈病、黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重821g/L、820g/L，粗蛋白质含量（干基）12.9%、14.8%，湿面筋含量26.3%、29.1%，吸水率56%、55%，稳定时间9.7min、10.7min，最大拉伸阻力456E.U.、417E.U.，拉伸面积70cm2、64cm2，硬度指数46.0、53.8。产量和抗性表现：2019-2021年度参加江苏省徐州农科所科企淮北小麦联合体区域试验，两年平均亩产566.8公斤，比对照淮麦20增产6.0%。2020-2021年度参加生产试验，平均亩产633.7公斤，比对照淮麦20增产6.6%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩14万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮15公斤-18公斤，其中基苗肥占40-50%，拔节孕穗肥占50-60%，同时配合施用磷钾肥，后期适当喷施叶面肥。注意田间沟系配套、防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (108, 1, '徐麦818', '苏审麦20180008', '2018.12', 0, '江苏省农作物品种审定委员会', '徐州佳禾农业科技有限公司', '烟农19/济麦22，参试名称“徐麦1412”', '江苏省淮北麦区', '特征特性：属半冬性中熟小麦品种。幼苗半匍匐，叶片适中，叶色浓绿。分蘖力较强，抗寒性较好。株型较紧凑，穗层较整齐，抗倒性中等。拔节抽穗适中，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒椭圆形，硬质。区试平均结果：全生育期226.2天，成熟期与对照淮麦20相当。株高84.9厘米（生试株高78.9厘米），每亩有效穗42.3万，每穗34.6粒，千粒重43.1克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：感赤霉病（严重度2.33-4.0，2017年自然发病鉴定中感），高感白粉病、叶锈病，感纹枯病，抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：感穗发芽。经农业部谷物品质监督检验测试中心测定，两年平均结果：粗蛋白（干基）14.7%，湿面筋30.0%，吸水量60.8ml/100g，稳定时间7.5min，最大拉伸阻力321E.U.，拉伸面积61cm2，硬度指数63.5。产量和抗性表现：2015-2017年度参加江苏省淮北组小麦区域试验，两年平均亩产583.5公斤，较对照淮麦20增产4.1％。2017-2018年度参加生产试验，平均亩产522.0公斤，较对照淮麦20增产5.3％。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗12万-16万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮18公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (109, 1, '徐麦856', '苏审麦200401', '2004.8', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农科所', '郑州8329/86195-14-4-4-1', '江苏淮北麦区', '退出批次：特征特性：该品种幼苗半直立，叶片细长，叶色浓绿，分蘖力强，株型紧凑，茎杆粗壮；株高近80厘米，耐肥抗倒性好，每亩穗数55万左右，每穗25粒左右，成穗率高，穗二棱，长方形，长芒有刺，穗大粒多，穗层整齐，籽粒色泽较淡、皮薄、腹沟浅，全生育期200天左右，与对照相当；在沿海地区千粒重40克左右，高抗大麦黄花叶病，品质据中国食品发酵工业研究院检测，达到啤用大麦标准。产量和抗性表现：2001-2003年度参加江苏省大麦品种区域试验，2001-2002年度平均亩产401.46公斤，较对照单二大麦增产14.24%，居第一位；2002-2003年度平均亩产342.75公斤，较对照增产6.38%，居第三位，均达极显著水平。两年平均亩产372.11公斤，较对照增产10.49%，居第一位。2002-2003年度在区试同时组织生产试验，平均亩产375.34公斤，较对照增产11.91%。该品种产量水平高，稳产性、抗病性较好，品质达到啤用标准', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (110, 1, '徐麦9158', '苏审麦201404', '2014', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农业科学研究所、江苏徐农种业科技有限公司', '周麦16/徐州24', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶片较宽大，叶色偏淡分蘖力较强，冬前分蘖多，越冬抗寒性较好，抗倒春寒性一般株型紧凑，穗层较整齐，茎杆弹性较好，抗倒性较好灌浆快，熟相好穗纺锤形，长芒、白壳、白粒，籽粒卵圆形，半硬质-硬质区试平均结果：全生育期233.4天，与对照相当，株高80.4厘米，每亩有效穗41.9万，每穗31.9粒，千粒重41.0克抗病性经江苏省农科院植保所2011-2013年接种鉴定：中感条锈病，感赤霉病、白粉病、纹枯病，高感小麦黄花叶病毒病品质经农业部谷物品质监督检验测试中心测定，2011-2013年度两年平均结果：容重816.0克/升，粗蛋白含量14.3%，湿面筋含量29.7%，稳定时间7.9分钟，硬度指数65.2；其中2012-2013年度容重798.0克/升，粗蛋白含量14.7%，湿面筋含量30.2%，稳定时间8.5分钟，硬度指数65.6产量和抗性表现：2011-2013年度参加江苏省淮北组小麦区域试验，两年平均亩产521.9公斤，较对照淮麦20增产4.8％，两年增产均达极显著水平2012-2013年度参加生产试验，平均亩产599.5公斤，较对照淮麦20增产4.6％', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (111, 1, '徐麦99', '苏审麦200805', '2008.9', 0, '江苏省农作物品种审定委员会', '徐州市种子站', '鲁麦14/ PH85-2//皖麦38', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗偏匍匐，叶色较深，抗寒性较好分蘖力强，成穗数较多株型较松散，茎杆弹性好，抗倒性较好穗层较厚，结实性好长芒，白壳，白粒，纺锤型穗，籽粒硬质-半硬质省区试平均结果：全生育期236.0天，较对照淮麦18迟熟2-3天;株高91.8厘米，每亩有效穗39.0万穗，每穗33.1粒，千粒重42.5克接种鉴定结果：中感赤霉病、纹枯病，高抗梭条花叶病高感穗发芽经农业部谷物品质监督检验测试中心测定，三年平均结果：容重808克/升，粗蛋白含量15.8%，湿面筋含量33.7%，稳定时间8.2分钟产量和抗性表现：2005-2007年度参加江苏省区域试验，两年平均亩产520.5公斤，较对照淮麦18增产2.4%；2007-2008年度参加生产试验，平均亩产534.5公斤，较对照淮麦18增产5.7%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (112, 1, '徐麦DH2', '苏审麦20220014', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农业科学研究所', 'H35/矮抗58 ∥矮抗58/／/徐麦2023', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色深绿。分蘖力较强，株型较紧凑，穗层较整齐，蜡质重。穗纺锤形，中大穗，长芒、白壳、白粒，籽粒角质。省区域试验平均结果：全生育期228.0天，比对照淮麦20长0.2天，株高82.0厘米，每亩有效穗42.1万，每穗33.0粒，千粒重45.7克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中抗赤霉病，严重度1.15、1.90；自然发病鉴定中感赤霉病，病指0.41、8.93），高感叶锈病、白粉病、纹枯病，中抗黄花叶病毒病，高抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重824g/L、833g/L，粗粗蛋白质含量（干基）13.2%、15.6%，湿面筋含量28.9%、34.4%，吸水率63%、62%，稳定时间3.4min、4.2min，最大拉伸阻力211E.U.、237E.U.，拉伸面积36cm2、41cm2，硬度指数65.5、64.8。产量和抗性表现：2019-2021年度参加江苏省淮北A组小麦品种区域试验，两年平均亩产599.4公斤，比对照淮麦20增产5.6%。2020-2021年度参加生产试验，平均亩产626.9公斤，比对照淮麦20增产6.3%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩14万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮15-18公斤，其中基苗肥占40%、拔节孕穗肥占60%，同时配合施用磷钾肥，后期适当喷施叶面肥。注意田间沟系配套、防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (113, 1, '徐麦DH9', '苏审麦20210023', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区徐州农业科学研究所', 'H35/矮抗58BC2F1//徐麦1108，参试名称“徐麦DH9”', '江苏省淮北麦区', '特征特性：半冬性早熟小麦品种。幼苗半匍匐，叶色绿，幼苗长势正常，抗寒性较好，拔节起身中等，分蘖力较强。株型较紧凑，蜡质重，茎秆粗壮，抗倒性较好，剑叶细长、挺，穗层整齐，灌浆快，结实性较好，熟相较好。穗长方型，长芒、白壳、白粒，籽粒角质。区试平均结果：全生育期228.1天，比对照淮麦20短2.1天。株高81.6厘米，每亩有效穗41.3万，每穗33.9粒，千粒重44.0克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中感赤霉病（接种鉴定中抗赤霉病，严重度2.53、1.22、2.25；自然发病鉴定中感赤霉病，病指0、1.86、13.33），中抗条锈病，中感黄花叶病，高感纹枯病、白粉病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：中抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重843g/L，蛋白质（干基）15.5%、13.8%，湿面筋含量35.0%、31.8%，吸水率58.6%、60.8%，稳定时间9.1min、6.3min，最大拉伸阻力402E.U.，拉伸面积67cm2，硬度指数66.0、63.4。产量和抗性表现：2018-2020年度参加江苏省淮北小麦徐州农科所科企联合体区试，两年平均亩产563.3公斤，比对照淮麦20增产1.6%。2020-2021年度参加生产试验平均亩产559.4公斤，比对照淮麦20增产2.6%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗14万-18万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮15-18公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。及时防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (114, 1, '扬富麦101', '苏审麦201401', '2014', 0, '江苏省农作物品种审定委员会', '扬州长富种业科技有限公司', '镇麦4号繁殖田选择变异株', '适宜江苏省淮南麦区种植', '退出批次：特征特性：幼苗直立，叶色较深分蘖力较强株型较紧凑，抗倒性较好穗层整齐，熟相较好穗纺锤形，长芒、白壳、红粒，籽粒半硬质区试平均结果：全生育期208.3天，与对照相当；株高79.6厘米，每亩有效穗31.5万，每穗40.4粒，千粒重38.9克抗病性经江苏省农科院植保所2011-2013年接种鉴定：中抗赤霉病，感纹枯病、白粉病，中感小麦黄花叶病毒病品质经农业部谷物品质监督检验测试中心测定，2011-2013年度两年平均结果：容重816.0克/升，粗蛋白含量14.2%，湿面筋含量31.3%，稳定时间6.6分钟，硬度指数66产量和抗性表现：2011-2013年度参加江苏省淮南组小麦区域试验，两年平均亩产453.0公斤，较对照扬麦11号增产8.5％，两年增产均达极显著水平2013-2014年度参加生产试验，平均亩产469.3公斤，较对照扬麦11号增产6.7%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (115, 1, '扬富麦106', '苏审麦20220006', '2023.01', 0, '江苏省农作物品种审定委员会', '扬州大学实验农牧场、扬州长富种业科技有限公司', '镇麦4号变异株', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗半直立，分蘖性较强。株型半松散，穗层整齐，熟相较好。纺锤型穗，长芒，白壳，红粒，籽粒半角质。省区域试验平均结果：全生育期210.3天，比对照扬麦20短1.4天，株高90.8厘米，每亩有效穗31.7万，每穗42.5粒，千粒重43.1克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.20、2.00；自然发病鉴定中抗赤霉病，病指0.35、5.30），高感纹枯病、白粉病，感黄花叶病毒病，中抗叶锈病、条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重803g/L、793g/L，粗蛋白质含量（干基）含量14.4%、14.9%，湿面筋含量含量36.5%、34.9%，吸水率65%、61%，稳定时间3.4min、3.2min，最大拉伸阻力236E.U.、152E.U.，拉伸面积59cm2、47cm2，硬度指数65.3、63.6。产量和抗性表现：2019-2021年度参加江苏省淮南B组小麦品种区域试验，两年平均亩产516.0公斤，比对照扬麦20增产5.6%。2021-2022年度参加生产试验，平均亩产553.1公斤，比对照扬麦20增产4.4%。', '1、适宜播期10月25日至11月5日。2、基本苗适期播种每亩16万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮16-18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治赤霉病、纹枯病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (116, 1, '扬江麦1820', '苏审麦20220009', '2023.01', 0, '江苏省农作物品种审定委员会', '扬州市扬子江种业有限公司、江苏千重浪农业科技发展有限公司', '宁麦9号/扬麦16', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗半直立，分蘖力一般。株型较松散，穗层整齐，熟相较好。纺锤形穗，长芒、白壳、红粒，籽粒角质。省区域试验平均结果：全生育期211.0天，比对照扬麦20短0.8天，株高93.8厘米，每亩有效穗32.4万，每穗37.6粒，千粒重47.4克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.00、1.87；自然发病鉴定中抗赤霉病，病情指数0.11、1.90），高感条锈病、叶锈病、纹枯病，中感黄花叶病毒病、白粉病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重794g/L、790g/L，粗蛋白质含量（干基）14.6%、14.9%，湿面筋含量32.0%、32.6%，吸水率63%、63%，稳定时间7.8min、7.8min，最大拉伸阻力686E.U.、427E.U.，拉伸面积135cm2、101cm2，硬度指数65.8、65.1。2020年、2021年品质检测结果均达到中强筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮南B组小麦品种区域试验，两年平均亩产506.4公斤，比对照扬麦20增产3.6%。2021-2022年度参加生产试验，平均亩产554.9公斤，比对照扬麦20增产4.8%。', '1、适宜播期10月25日至11月10日。2、基本苗适期播种每亩16万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮18公斤左右，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草。注意防治赤霉病、白粉病、叶锈病、纹枯病、条锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (117, 1, '扬江麦586', '苏审麦20190006', '2019.11', 0, '江苏省农作物品种审定委员会', '扬州市扬子江种业有限公司、河南大学', '生选3号变异株系选，参试名称“扬江麦580”', '江苏省淮南麦区', '特征特性：属春性中熟小麦品种。幼苗半直立，株型较松散，分蘖力及成穗数中等。长芒、白壳、红粒，穗纺锤形，籽粒硬质。区试平均结果：全生育期209.1天，比对照扬麦20早熟1.3天。平均株高77.4厘米。每亩有效穗33.1万，每穗39粒，千粒重40.8克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（单花滴注鉴定中抗赤霉病，严重度1.5、2.5；自然发病鉴定抗赤霉病，病情指数0.6、0.0），高感条锈病、叶锈病，感纹枯病，中抗黄花叶病，抗白粉病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重804g/L、814g/L，蛋白质（干基）14.1%、13.7%，湿面筋32.0%、33.8%，吸水率64.1%、63.3%，稳定时间4.6min、3.3min，最大拉伸阻力182E.U.、186E.U.，拉伸面积51cm2、46cm2，硬度指数62.4、63.0。产量和抗性表现：2017-2019年度参加江苏省淮南组小麦品种区域试验，两年平均亩产492.54公斤，比对照扬麦20增产5.25%。2018-2019年度参加生产试验，平均亩产490.90公斤，比对照扬麦20增产3.51%。', '1、适宜播期10月25日至11月10日。2、适期播种每亩基本苗15万-18万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮15公斤左右，配合施用磷、钾肥。抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治白粉病、赤霉病、纹枯病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (118, 1, '扬糯麦1号', '苏审麦201003', '2010.1', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农科所', '扬麦9号/CAW', '适宜江苏省淮南麦区无黄花叶病田块种植', '退出批次：特征特性：幼苗直立，叶片宽长，叶色绿分蘖力和成穗数中等春性强，抗寒性偏弱株型较松散，抗倒性较好纺锤型穗，穗大粒多，结实性较好长芒、白壳、红粒籽粒胚乳糯质，经农业部谷物品质监督检验测试中心测定，支链淀粉含量98.7%区试平均结果：全生育期208.8天，较对照迟熟2-3天；株高83.1厘米，每亩有效穗31.6万穗，每穗41.4粒，千粒重39.7克接种鉴定结果：中抗赤霉病，中感纹枯病，感白粉病，高感黄花叶病经农业部谷物品质监督检验测试中心测定，2007-2009年度两年平均结果：容重793克/升，粗蛋白含量12.5%，湿面筋含量22.9%，稳定时间3.3分钟产量和抗性表现：2007-2009年度参加江苏省区域试验，平均亩产507.1公斤，较对照扬麦11号增产5.0％2009-2010年度参加生产试验，平均亩产408.0公斤，较对照扬麦11号增产2.9%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (119, 1, '扬糯麦2号', '苏审麦20210020', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '镇麦9号2/4/扬麦18/3/宁麦142//IKE/白火麦，参试名称“扬17G76”', '江苏省淮南麦区', '特征特性：春性糯小麦品种。幼苗直立，叶色中等，分蘖力中等。株型半紧凑，抗倒性一般。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒半角质。区试平均结果：全生育期203.5天，比对照扬麦20短0.8天。株高89.6厘米，每亩有效穗31.3万，每穗37.4粒，千粒重46.4克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.9、1.2；自然发病鉴定中抗赤霉病，病指0、0），抗白粉病，中感条锈病，感黄花叶病毒病，高感纹枯病、叶锈病。经江苏省农业科学院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重773g/L、784g/L，粗蛋白(干基)含量14.2%、15.8%，湿面筋含量28.6%、25.7%，吸水率70.1%、63.5%，稳定时间4.3min、3.9min，最大拉伸阻力495E.U.、412E.U.，拉伸面积100cm2、100cm2，硬度指数70.0、65.1。支链淀粉含量99.5%。产量和抗性表现：2018-2020年度参加江苏省淮南小麦里下河农科所科企联合体区试，两年平均亩产501.7公斤，比对照扬麦20增产0.8%。2020-2021年度参加生产试验，平均亩产502.8公斤，比对照扬麦20增产5.4%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗16万左右，中低产田适当增加。3、一般亩施纯氮15-18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治赤霉病、纹枯病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (120, 1, '扬辐麦10号', '苏审麦20180001', '2018.12', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所、江苏农科种业研究院有限公司', '（扬辐麦4号/扬麦19）F1辐照，参试名称“扬辐麦2049”', '江苏省淮南麦区', '特征特性：属春性中熟小麦品种。幼苗直立，叶色深绿，分蘖性较强。株型半紧凑，抗倒性较好。穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒软质。区试平均结果：全生育期202.1天，比对照扬麦20迟0.5天。株高79.9厘米，每亩有效穗32.9万，每穗38.4粒，千粒重41.4克。经江苏省农业科学院植物保护研究所接种鉴定：中抗赤霉病（1.37-1.81），感纹枯病，感白粉病，中感黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业部谷物品质监督检验测试中心（哈尔滨）测定，两年平均结果：粗蛋白（干基）14.7%，湿面筋30.0%，吸水量55.0ml/100g，稳定时间10.6min，最大拉伸阻力531 E.U.，拉伸面积115cm2，硬度指数48.8。产量和抗性表现：2015-2017年度参加江苏省淮南组小麦区域试验，两年平均亩产499.3公斤，较对照扬麦20增产5.9％。2017-2018年度参加生产试验，平均亩产462.5公斤，较对照扬麦20增产5.6％。', '1、适宜播期10月25日至11月10日。2、适期播种每亩基本苗16万左右，中低产田或迟播应适当增加。3、一般亩施纯氮15-18公斤，其中基苗肥占60%、拔节孕穗肥占40％，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草。注意防治纹枯病、白粉病、赤霉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (121, 1, '扬辐麦13', '苏审麦20210005', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏金土地种业有限公司、江苏里下河地区农业科学研究所', '（扬辐麦4号/镇麦9号）F1辐照，参试名称“扬辐麦5145”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色中等，分蘖力较强。株型较紧凑，抗倒性较好。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒半角质。区试平均结果：全生育期209.3天，比对照扬麦20短0.4天。株高80.3厘米，每亩有效穗31.3万，每穗37.4粒，千粒重45.5克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.8、3.0；自然发病鉴定中抗赤霉病，病指4.03、1.74），高抗白粉病，中抗黄花叶病，中感条锈病，高感纹枯病、叶锈病。经江苏省农业科学院种质资源与生物研究所鉴定：高抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重787g/L、798g/L，粗蛋白(干基)含量15.0%、14.1%，湿面筋含量30.0%、30.9%，吸水率60.7%、59.0%，稳定时间7.3min、8.7min，最大拉伸阻力456E.U.、576E.U.，拉伸面积114cm2、121cm2，硬度指数62.1、61.8。2017-2018年度、2018-2019年度品质指标均达中强筋小麦品种审定标准。产量和抗性表现：2017-2019年度参加江苏省淮南小麦A组区试，两年平均亩产498.4公斤，比对照扬麦20增产3.6%。2019-2020年度参加生产试验，平均亩产515.9公斤，比对照扬麦20增产5.3%。', '1、适宜播种期10月25至11月5日。2、适期播种每亩基本苗16万左右，中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (122, 1, '扬辐麦15', '苏审麦20200024', '2020.11', 0, '江苏省农作物品种审定委', '江苏中江种业股份有限公司、江苏里下河地区农业科学研究所', '(镇麦 9 号/扬辐麦 7298)F1 辐照，参试名称“江麦 5122”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色淡绿，分蘖力中等。株 型较松散，抗倒性较好。穗层整齐，熟相好。穗纺锤形，长芒、白壳、 红粒，籽粒粉质-半角质。区试平均结果:全生育期 208.5 天，与对照扬 麦 20 相当。株高 86.6 厘米，每亩有效穗 28.8 万，每穗 40.0 粒，千粒重 46.6 克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业 科学研究所鉴定:中抗赤霉病(接种鉴定中抗赤霉病，严重度 2.4、2.8; 自然发病鉴定中抗赤霉病，病指 2.5、0.0)，高抗白粉病，中感条锈病、 黄花叶病毒病，高感纹枯病、叶锈病。经江苏省农业科学院种质资源与 生物研究所鉴定:抗穗发芽。经农业部谷物品质监督检验测试中心测定: 容重 774g/L、811g/L，粗蛋白(干基)15.2%、16.4%，湿面筋 31.9%、30.3%， 吸水率 62%、62%，稳定时间 3.8min、3.1min，最大拉伸阻力 248E.U.， 拉伸面积 59cm2。产量和抗性表现：2017-2019 年度参加江苏省淮南小麦省农科院科企联合体 区试，两年平均亩产 476.3 公斤，比对照扬麦 20 增产 5.2%。2019-2020 年度参加生产试验，平均亩产 508.8 公斤，比对照扬麦 20 增产 2.8%。', '1、适宜播期 10 月 25 日至 11 月 10 日。2、适期播 种每亩基本苗 15 万-18 万，中低产田适当增加。3、一般亩施纯氮 18 公 斤，其中基苗肥占 60%、拔节孕穗肥占 40%，同时配合施用磷钾肥，后 期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时 防除田间杂草。注意防治纹枯病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (123, 1, '扬辐麦19', '苏审麦20220025', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏金土地种业有限公司、江苏里下河地区农业科学研究所', '（扬麦22/扬辐麦9244）F1辐照', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，分蘖力较强。株型半紧凑，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒半角质。联合体区域试验平均结果：全生育期205.2天，比对照扬麦20短0.7天，株高84.2厘米，每亩有效穗31.9万，每穗42.3粒，千粒重41.9克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.22、1.00；自然发病鉴定中抗赤霉病，病指1.26、8.50），高感叶锈病，感纹枯病、黄花叶病毒病，中感条锈病，中抗白粉病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重790g/L、790g/L，粗蛋白质含量（干基）15.0%、14.9%，湿面筋含量30.0%、32.4%，吸水率56%、56%，稳定时间2.6min、2.8min，最大拉伸阻力196E.U.、239E.U.，拉伸面积53cm2、62cm2，硬度指数48.8、47.8。产量和抗性表现：2019-2021年度参加江苏省淮南小麦组里下河所科企联合体区域试验，两年平均亩产528.6公斤，比对照扬麦20增产8.3%。2021-2022年度参加生产试验平均亩产574.6公斤，比对照扬麦20增产6.2%。', '1、适宜播种期10月25至11月5日。2、基本苗适期播种每亩16万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (124, 1, '扬辐麦1号', '苏种审字第341号', '1999', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农科所', '1-3058/扬麦5号', '江苏淮南麦区', '退出批次：特征特性：幼苗半直立，叶片细狭，叶色较深。株高95厘米左右，株型紧凑，茎杆弹性好。分蘖力较强，成穗率较高。长芒、白壳、纺锤形穗，每穗平均35粒左右。红皮，皮色偏淡，粉质，千粒重35-40克。品质较好，粗蛋白含量10.5%，湿面筋含量26.7%，吸水率58.6%，面团形成时间1.7分钟，稳定时间2.8分钟，断裂时间3.8分钟，粉质评价值35分。生育期201天左右，比扬麦158迟2天。中抗梭条花叶病，对赤霉病与纹枯病为中感-感，感白粉病。产量和抗性表现：1995至1997年连续两个年度参加江苏省淮南小麦品种区域试验，平均亩产分别为424.05公斤和391.69公斤，比对照扬麦158增产4.14%（极显著）和减产0.49%（不显著）。1997-1998年度在江苏省淮南小麦品种生产试验中亩产316.87公斤，比对照扬麦158增产6.20%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (125, 1, '扬辐麦20', '苏审麦20220007', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '（扬麦22/镇麦9号）F2辐照', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗半直立，分蘖力较强。株型较松散，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒半角质至角质。省区域试验平均结果：全生育期210.0天，比对照扬麦20短1.8天，株高86.6厘米，每亩有效穗33.3万，每穗39.8粒，千粒重44.6克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.25、1.41；自然发病鉴定中抗赤霉病，病指0.42、6.50），高感纹枯病、白粉病，中感黄花叶病毒病，中抗叶锈病、条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重807g/L、804g/L，粗蛋白质含量（干基）15.9%、14.6%，湿面筋含量33.0%、31.3%，吸水率60%、60%，稳定时间4.9min、5.0min，最大拉伸阻力262E.U.、253E.U.，拉伸面积58cm2、67cm2，硬度指数55.7、55.7。产量和抗性表现：2019-2021年度参加江苏省淮南B组小麦品种区域试验，两年平均亩产512.2公斤，比对照扬麦20增产4.8%。2021-2022年度参加生产试验，平均亩产552.3公斤，比对照扬麦20增产4.3%。', '1、适宜播期10月25日至11月5日。2、基本苗适期播种每亩15万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (126, 1, '扬辐麦21', '苏审麦20220001', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '扬麦22/扬辐麦10-2559', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，分蘖力较强。株型半松散，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒粉质至半角质。省区域试验平均结果：全生育期208.1天，比对照扬麦20短1.0天，株高85.5厘米，每亩有效穗32.3万，每穗39.2粒，千粒重45.3克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.56、1.29；自然发病鉴定中抗赤霉病，病指0.66、5.67），高感纹枯病，感白粉病，中感黄花叶病毒病，中抗叶锈病、条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重798g/L、797g/L，粗蛋白质含量（干基）13.1%、14.2%，湿面筋含量28.5%、28.5%，吸水率58%、56%，稳定时间8.7min、7.2min，最大拉伸阻力534E.U.、518E.U.，拉伸面积100cm2、101cm2，硬度指数55.4、50.9。2020年品质检测结果达到中强筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮南A组小麦品种区域试验，两年平均亩产509.1公斤，比对照扬麦20增产2.9%。2021-2022年度参加生产试验，平均亩产531.7公斤，比对照扬麦20增产5.2%。', '1、适宜播期10月25日至11月5日。2、基本苗适期播种每亩15万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (127, 1, '扬辐麦2号', '苏审麦200209', '2002', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农科所', '（扬麦158/1-9012）经辐射诱变', '江苏淮南麦区', '退出批次：特征特性：该品种长芒、白壳、穗型近长方形，籽粒红皮、半硬质，分蘖成穗数一般，穗粒结构较协调，每亩有效穗29万左右，每穗粒数38粒左右，千粒重43.5克左右，容重770克左右。株高95厘米左右，耐肥抗倒性一般，成熟期较扬麦158迟2天。中感赤霉病，中感白粉病、纹枯病，梭条花叶病毒病较轻。据2002年8月省农技推广中心抽样品质分析(南京经济学院)，粗蛋白含量10.67%，湿面筋23.8％，干面筋7.96％，沉降值31ml，面团形成时间1.2min，面团稳定时间3.3min，粉质评价值38分，属弱筋品种。产量和抗性表现：1999-2001年参加省区域试验，1999-2000年度平均亩产413.75公斤，较对照扬麦158增产2.28％，极显著，居第1位；2000-2001年度平均亩产426.27公斤，较对照扬麦158增产8.02％，极显著，居第1位；两年平均亩产420.01公斤，较对照增产5.12%，极显著，居第1位。2001-2002年度参加淮南小麦生产试验，平均亩产362.1公斤，较对照扬麦158增产6.29%，居第2位。该品种高产稳产，抗病性一般。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (128, 1, '扬辐麦3号', '苏审麦200602', '2006.9', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '扬麦158/1-9012 F1代种子经辐照诱变选育', '适宜江苏淮南麦区种植', '退出批次：特征特性：该品种长芒、白壳、穗纺锤形，籽粒半硬质。幼苗直立，株型较松散，株高90厘米左右，抗倒性一般。全生育期213天左右，比对照扬麦158长2天。分蘖及成穗数中等。亩有效穗32万左右，每穗38粒左右，千粒重38克左右。接种鉴定：中抗赤霉病，中感纹枯病，高感梭条花叶病，抗穗发芽。品质分析三年平均结果：粗蛋白含量14.8%，湿面筋含量26.7%，稳定时间6.8分钟。产量和抗性表现：2003-2005年度参加江苏省区域试验，两年平均亩产430.46公斤，较对照扬麦158增产4.68%，两年增产均达极显著水平；2005-2006年度生产试验平均亩产450.16公斤，较对照扬麦11号增产1.42%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (129, 1, '扬辐麦4号', '苏审麦200801', '2008.9', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '宁麦8号/宁麦9号', '适宜江苏省淮南麦区种植', '退出批次：特征特性：幼苗直立，叶色深绿株型较紧凑，耐肥抗倒性较强分蘖性和成穗数中等，穗大粒多，千粒重较高长芒，白壳，红粒，纺锤型穗，籽粒半硬质-软质省区试平均结果：全生育期207.5天，较对照照扬麦11号迟熟1-2天；株高86.1厘米，每亩有效穗29.9万穗，每穗40.7粒，千粒重40.7克接种鉴定结果：中抗赤霉病，感纹枯病，高抗梭条花叶病田间白粉病发生较重高抗穗发芽经农业部谷物品质监督检验测试中心测定，三年平均结果：容重803克/升，粗蛋白含量12.9%，湿面筋含量26.4%，稳定时间2.6分钟产量和抗性表现：2005-2007年度参加江苏省区域试验，两年平均亩产461.2公斤，较对照扬麦11号增产3.3％2007-2008年度参加生产试验，平均亩产470.4公斤，较对照扬麦11号增产6.5%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (130, 1, '扬麦10号', '苏种审字第334号', '1999', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农科所', '85-85//Y.C/鉴21///扬麦158', '江苏淮南麦区', '退出批次：特征特性：幼苗半直立，叶片宽挺，叶色较深，生长稳健。株高95厘米左右，株型略松。分蘖成穗离中等，抽穗期、成熟期均与对照扬麦158相仿。长芒、白壳、纺缍形穗，每穗平均40粒左右。籽粒饱满，角质，红皮，皮色较扬麦158略淡，千粒重40克左右。品质较好，粗蛋白含量11.3%，湿面筋含量26.5%，出粉率68.2%，面团形成时间2.3分钟，稳定时间5.3分钟，断裂时间6.0分钟，粉质评价值49分钟。全生育期210天左右，与对照扬麦158相当。高抗白偻病，对赤霉病中抗－中感，中感纹枯病，抗寒性较强，抗倒性一般。后期熟相较好。产量和抗性表现：1995年至1997年连续两个年度参加江苏省淮南小麦品种区域试验，平均亩产分别为412.25公斤和401.99公斤，比对照扬麦158增产1.24%（不显著）和2.13%（显著）。1997－1998年度在江苏省淮南小麦品种生产试验中亩产300.73公斤，比对照扬麦158增产0.80%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (131, 1, '扬麦11号', '苏种审字第383号', '2000', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农科所', '873-158/[（y.c*/鉴2）/85-854]', '江苏淮南麦区', '退出批次：特征特性：该品种幼苗半直立，叶色较深，叶片较宽。分蘖性中等，成穗率较高。株高95厘米左右，株型略松。茎秆有一定韧性，耐肥、抗倒性一般。该品种亩有效穗30万左右，每穗粒数38粒左右，千粒重42—45克。长芒、白壳、纺锤型穗，籽粒红色。该品种中感—中抗赤霉病，抗白粉病，中感-中抗纹枯病，对梭条花叶病为中感一感，感叶锈。该品种容重723克／升，蛋白质含量12.9％，湿面筋含量为30.60％，沉降值为50毫升，降落值为360秒，吸水率为59.10％，面团形成时间为4.0分钟，稳定时间为5.2分钟，断裂时间为7.5分钟，粉质评价值48分（南京经济学院粮油检测中心，2000年）。属于中筋力小麦品种。该品种丰产、稳产性较好，全生育期为207天左右。产量和抗性表现：该品种1997—2000年度参加江苏省淮南小麦中间试验。1997—1998年度省区试平均亩产273.89公斤，比对照扬麦158增产4.17％，达极显著水平；1998—1999年度省区试平均亩产365.20公斤，比对照减产l.43％，减产不显著；1999—2000年度参加省淮南小麦生产试验，平均亩产433.74公斤，比对照扬麦158增产6.26％。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (132, 1, '扬麦14', '苏审麦200706', '2007.9', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '扬麦158/扬麦6号', '适宜江苏省沿淮及淮南麦区种植', '退出批次：特征特性：长芒，白壳，红粒，长方型穗，籽粒半硬质；幼苗直立，分蘖力较强，株型较紧凑株高84厘米左右，耐肥抗倒性较好；每亩有效穗29万左右，每穗35粒左右，千粒重43克左右产量和抗性表现：2006-2007年在淮南麦区组织生产试验，平均亩产409.8公斤，较对照扬麦11号增产4.9%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (133, 1, '扬麦14号', '苏审麦200404', '2004.8', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农科所', '扬158/扬麦6号', '江苏沿淮地区', '退出批次：特征特性：该品种长芒、白壳、长方型穗，籽粒红皮、半硬质；幼苗直立，分蘖力较强，株型较紧凑，全生育期较豫麦18早熟1天，株高87厘米左右，耐肥抗倒性较好，抗倒春寒能力一般；每亩有效穗35万左右，每穗30粒左右，千粒重43克左右。接种鉴定中抗赤霉病、中感纹枯病，抗病性好于对照豫麦18。品质分析三年平均结果为粗蛋白含量14.6%，湿面筋含量31.5%，稳定时间4.7分钟，属中筋品种。产量和抗性表现：2001-2003年度参加江苏省区域试验，两年平均亩产423.4公斤，较对照扬麦158增产6.99%，其中2001-2002年增产不显著，2002-2003年度增产达极显著；2003-2004年度组织生产试验，平均亩产457.5公斤，较对照豫麦18增产7.28%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (134, 1, '扬麦15', '苏审麦200502', '2005.9', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '扬89-40/川育21526', '江苏省淮南麦区种植。', '退出批次：特征特性：该品种长芒、白壳、长方型穗，籽粒红皮、粉质。幼苗直立，分蘖力较强，株型紧凑，株高80cm左右，耐肥抗倒性较好。成熟期中等，全生育期与对照扬麦158相当。每亩有效穗32万左右，每穗37粒左右，千粒重38克左右。接种鉴定感赤霉病、梭条花叶病毒病，中感纹枯病、白粉病。品质分析2001-2004年度三年平均结果：粗蛋白含量13.1%，湿面筋含量25.3%，稳定时间6.5分钟。2005年按弱筋小麦栽培要求种植，品质分析结果为粗蛋白含量9.4%，湿面筋含量17.2%，稳定时间1.9分钟,达弱筋标准。产量和抗性表现：2001-2003年度参加江苏省区域试验，两年平均亩产352.0公斤，比对照扬麦158增产4.61％。2003-2004年度生产试验平均亩产424.42公斤，较对照扬麦158增产9.41%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (135, 1, '扬麦158', '苏种审字第179号', '1993', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农科所', '扬麦4号/ST1472/506', '江苏淮南麦区', '退出批次：特征特性：幼苗偏直立，生长茁壮，发苗稳健。株型略松，株高93厘米左右，茎秆粗壮，韧性较好，叶片宽而较挺，叶色浓绿。分蘖力中等，成穗率较高。产量结构较协调`，每亩穗数27万左右。穗长方形，长芒、白壳、红粒，穗大粒多。穗长8.7厘米，每穗实粒数34粒左右，灌浆速度快，籽粒偏角质，饱满度、均匀较好。千粒重41.7克，容重793克/公升，出粉率70%左右，粗蛋白含量11.4%，湿面筋含量33.5%，干面筋11%，吸水率达64.5%，面团形成时间4分钟，稳定时间5.5分钟衰减度95Bμ，各项指标均好于杨麦5号。面粉品质综合评价傎为50分，比杨麦5号高18分，品质良好。全生育期208天左右，熟期与杨麦5号相仿。综合性状好，丰产性突出，白粉病、赤霉病的抗性属中抗。不抗梭条花叶病毒病，纹枯病较重，耐寒性略差于杨麦5号。收获前叶片枯黄较快。产量和抗性表现：1990、1991年连续两年参加省淮南片小麦品咱区域试验。平均单产分别为324.9公斤和377.16公斤.分别比扬麦5号增产13.1%和15.4%，达极显著水准。1992年度生产试验平均单产396。9公斤，比扬麦5号增产6.7%.', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (136, 1, '扬麦16号', '苏审麦200407', '2004.8', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农科所', '扬91F138/扬90-30', '江苏省淮南麦区', '退出批次：特征特性：该品种长芒、白壳、纺缍型穗，籽粒红皮、硬质；幼苗直立，株型较松散。全生育期与扬麦158相当，株高90厘米左右，耐肥抗倒性一般；每亩有效穗26万左右，每穗38粒左右，千粒重37克左右。接种鉴定中感赤霉病、纹枯病，抗病性与扬麦158相当。品质分析三年平均结果为粗蛋白含量14.2%，湿面筋含量32.2%，稳定时间4.3分钟，属中筋品种。产量和抗性表现：2001-2003年度参加江苏省区域试验，两年平均亩产336.1公斤，较对照扬麦158增产6.90%，两年增产均达极显著水平；2003-2004年度组织生产试验，平均亩产398.0公斤，较对照扬麦158增产8.55%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (137, 1, '扬麦18', '苏审麦200901', '2009.9', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '4﹡宁麦9号/3/6﹡扬麦158//88-128/南农P045', '适宜江苏省淮南麦区种植', '退出批次：特征特性：幼苗直立，叶片宽长，叶色深绿。分蘖力和成穗数中等。株型较松散，抗倒性一般。纺锤型穗，穗大粒多，结实性较好。长芒，白壳，红粒，籽粒软质。省区试平均结果：全生育期207.1天，较对照扬麦11号迟熟2天；株高86.8厘米，每亩有效穗28.9万，每穗44.4粒，千粒重38.8克。接种鉴定结果：中感赤霉病，感纹枯病，中抗白粉病，高抗梭条花叶病。中抗穗发芽。经农业部谷物品质监督检验测试中心测定，两年平均结果：容重815克/升，粗蛋白含量13.0%，湿面筋含量26.2%，稳定时间3.9分钟。产量和抗性表现：2006-2008年度参加江苏省区域试验，平均亩产479.5公斤，较对照扬麦11号增产3.5％。2008-2009年度参加生产试验，平均亩产467.1公斤，较对照扬麦11号增产5.7%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (138, 1, '扬麦20', '苏审麦201203', '2012.11', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '扬麦10号/扬麦9号', '江苏省淮南麦区无黄花叶病田块种植', '退出批次：特征特性：该品种表现幼苗半直立，叶片较宽，叶色淡绿分蘖力较强，株型较松散抗寒性一般，耐肥抗倒性较好穗层整齐，纺锤型穗，穗大粒多长芒、白壳、红粒，籽粒软质、饱满度好，千粒重较高区试平均结果：全生育期215.3天，较对照迟熟2-3天；株高84.8厘米，每亩有效穗30.4万穗，每穗40.0粒，千粒重41.1克接种鉴定结果：中感赤霉病，感纹枯病、白粉病，高感黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2009-2011年度两年平均结果：容重787.0克/升，粗蛋白含量13.3%，湿面筋含量28.1%，稳定时间2.2分钟产量和抗性表现：2009-2011年度参加江苏省淮南组小麦区域试验，平均亩产478.8公斤，较对照扬麦11号增产6.0％，两年分别较对照增产达显著、极显著水平2011-2012年度参加生产试验，平均亩产388.5公斤，较对照扬麦11号增产2.6%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (139, 1, '扬麦21', '苏审麦201102', '2011.10', 0, '江苏省农作物品种审定委员会', '江苏金土地种业有限公司', '宁麦9号/红蜷芒', '适宜江苏省淮南麦区种植', '退出批次：特征特性：该品种表现幼苗直立，叶片较宽，色较深分蘖力一般，成穗数中等，抗寒性较强株型稍松散，耐肥抗倒性一般穗层整齐，纺锤型穗长芒、白壳、红粒，籽粒软质、饱满度好，千粒重高区试平均结果：全生育期212.4天，较对照迟熟2-3天；株高89.6厘米，每亩有效穗29.2万穗，每穗42.3粒，千粒重43.1克接种鉴定结果：中抗赤霉病，抗白粉病，感纹枯病，抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2008-2010年度两年平均结果：容重792克/升，粗蛋白含量11.8%，湿面筋含量25.0%，稳定时间2.6分钟2009年容重786克/升，粗蛋白含量11.2%，湿面筋含量22.9%，稳定时间2.1分钟产量和抗性表现：2008-2010年度参加江苏省淮南组小麦区域试验，平均亩产499.9公斤，较对照扬麦11号增产8.6％，两年较对照增产均达极显著水平2010-2011年度参加生产试验，平均亩产450.1公斤，较对照扬麦11号增产4.4%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (140, 1, '扬麦27', '苏审麦20170003', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏金土地种业有限公司、江苏里下河地区农业科学研究所', '扬麦19/扬07纹5418，参试名称“扬11-125”', '江苏省淮南麦区', '特征特性：春性中熟小麦品种。成熟期比对照扬麦20相当。幼苗直立，叶色较淡，分蘖力中等。株型较松散，抗倒性中等。穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒半硬质。区试平均结果：全生育期207.3天，株高85.0厘米，每亩有效穗30.4万，每穗39.8粒，千粒重41.0克。经江苏省农科院植保所两年接种鉴定：中抗赤霉病（严重度1.25-1.94），中感纹枯病，高感白粉病，感黄花叶病毒病。经江苏省农科院粮作所鉴定：抗穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：粗蛋白（干基）16.4%，湿面筋33.8%，吸水量53.4ml/100g，稳定时间3.5分钟，最大拉伸阻力316（Rm,135E.U），拉伸面积89cm2。产量和抗性表现：2014-2016年度参加江苏省淮南组小麦区域试验，两年平均亩产473.6公斤，较对照扬麦20增产4.3%，两年均达显著水平。2016-2017年度参加生产试验，平均亩产494.0公斤，较对照扬麦20增产3.6%。', '1、适宜播期10月25日至11月10日。2、适期播种每亩基本苗16万左右，肥力水平偏低或晚播田适当增加基本苗。3、一般亩施纯氮15-18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，根据病虫测报及时防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。不宜在小麦黄花叶病毒病发生田块种植。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (141, 1, '扬麦29', '苏审麦20180004', '2018.12', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '镇麦9号//扬麦175/pm17，参试名称“扬12G16”', '江苏省淮南麦区', '特征特性：属春性中熟小麦品种。幼苗半直立，叶色较深，分蘖力强。株型半紧凑，抗倒性较好。穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒硬质。区试平均结果：全生育期202.3天，比对照扬麦20早近0.3天。株高84.5厘米，每亩有效穗31.1万，每穗37.5粒，千粒重43.7克。经江苏省农业科学院植物保护研究所接种鉴定：中抗赤霉病（严重度1.5-3.0），中感纹枯病，高感白粉病，高感黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心（哈尔滨）测定，两年平均结果：粗蛋白（干基）15.3%，湿面筋30.3%，吸水量65.0ml/100g，稳定时间21.8min，最大拉伸阻力636 E.U.，拉伸面积140cm2，硬度指数67.1。2016年检测粗蛋白（干基）16.8%，湿面筋33.7 %，吸水量65.5ml/100g，稳定时间17.3min，最大拉伸阻力488E.U.，拉伸面积123cm2，硬度指数67.7，达强筋小麦品种标准。产量和抗性表现：2015-2017年度参加江苏省淮南组小麦区域试验，两年平均亩产494.4公斤，较对照扬麦20增产2.8％。2017-2018年度参加生产试验，平均亩产457.6公斤，较对照扬麦20增产5.5％。', '1、适宜播期10月25日至11月10日。2、适期播种每亩基本苗15万左右，中低产田或迟播应适当增加。3、一般亩施纯氮15-18公斤，其中基苗肥占60%、拔节孕穗肥占40％，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草。注意防治纹枯病、白粉病、赤霉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (142, 1, '扬麦30', '苏审麦20190001', '2019.11', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '扬09纹1009/扬麦18，参试名称“扬12-145”', '江苏省淮南麦区', '特征特性：属春性中熟小麦品种。幼苗直立，分蘖力中等。株型松散，穗层整齐，耐肥抗倒性一般。熟相好。穗纺锤形，长芒、白壳、红粒，籽粒半硬质。区试平均结果：全生育期209.2天，比对照扬麦20早熟0.5天。株高82.9厘米，每亩有效穗29.9万，每穗43粒，千粒重39.4克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（单花滴注严重度1.43、2.2；自然发病鉴定抗赤霉病，2018年病情指数0.46），高感白粉病、叶锈病，中感纹枯病，中抗黄花叶病，高抗条锈病。经江苏省农科院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重800g/L、800g/L，蛋白质（干基）14.05%、13.86%，湿面筋30.0%、29.1%，吸水率51.5%、55.2%，稳定时间3.5分钟、4.3分钟，最大拉伸阻力160E.U.、258E.U.，拉伸面积43cm2、63cm2，硬度指数51.5、55.2。产量和抗性表现：2015-2016、2017-2018年度参加江苏省淮南组小麦品种区域试验，两年平均亩产475.95公斤，比对照扬麦20增产5.57%。2018~2019年度参加生产试验平均亩产524.87公斤，比对照扬麦20增产4.84%。', '1、适宜播期10月25日至11月10日。2、适期播种每亩基本苗15万-18万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮12-14公斤，配合施用磷、钾肥。抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治白粉病、赤霉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (143, 1, '扬麦34', '苏审麦20200027', '2020.11', 0, '江苏省农作物品种审定委', '江苏里下河地区农业科学研究所', '扬麦 18//扬麦 18/元友-2，参试名称“扬 15 纹复 4666”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗半直立，叶色深绿，分蘖力强。株型较紧凑，抗倒性较好。穗层整齐，熟相好。穗纺锤形，长芒、白壳、 红粒，籽粒粉质。区试平均结果:全生育期 203.1 天，与对照扬麦 20 相 当。株高 76.8 厘米，每亩有效穗 31.4 万，每穗 44 粒，千粒重 40.2 克。 经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究 所鉴定:中抗赤霉病(接种鉴定中抗赤霉病，严重度 2.5、2.9;自然发 病鉴定中抗赤霉病，病指 3.0、0.9)，高抗白粉病，中抗黄花叶病毒病， 高感纹枯病、叶锈病、条锈病。经江苏省农业科学院种质资源与生物研 究所鉴定:抗穗发芽。经农业部谷物品质监督检验测试中心测定:容重 802g/L、779g/L，粗蛋白(干基)14.9%、11.8%，湿面筋 30.6%、28.4%， 吸水率 60%、56%，稳定时间 4.3min、2.8min，最大拉伸阻力 317E.U.、 340E.U.，拉伸面积 67cm2、69cm2，硬度指数 51.0、45.0。产量和抗性表现：2017-2019 年度参加江苏省淮南小麦里下河农科所科企联 合体区试，两年平均亩产 517.6 公斤，比对照扬麦 20 增产 8.0%。2019-2020 年度参加生产试验，平均亩产 505.7 公斤，比对照扬麦 20 增产 4.2%。', '1、适宜播期 10 月 25 日至 11 月 5 日。2、适期播种 每亩基本苗 16 万左右，中低产田适当增加。3、一般亩施纯氮 18 公斤， 其中基苗肥占 60%、拔节孕穗肥占 40%，同时配合施用磷钾肥，后期适 当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除 田间杂草。注意防治纹枯病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (144, 1, '扬麦35', '苏审麦20210001', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '扬06G5//苏麦6号/97G59，参试名称“扬15-128”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色中等，分蘖力较强。株型松散，抗倒性较好。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒半角质。区试平均结果：全生育期207.7天，比对照扬麦20短1.3天。株高80.8厘米，每亩有效穗32.1万，每穗40.4粒，千粒重45.5克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.6、1.17、1.25；自然发病鉴定中抗赤霉病，病指0、0.18、5.21），中感白粉病、黄花叶病毒病，高感纹枯病、叶锈病、条锈病。经江苏省农业科学院种质资源与生物研究所鉴定：高抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重797g/L、790g/L，粗蛋白(干基)含量12.7%、13.2%，湿面筋含量28.7%、28.1%，吸水率59.3%、64.0%，稳定时间3.9min、5.6min，最大拉伸阻力223E.U.、360E.U.，拉伸面积51cm2、80cm2，硬度指数62.8、64.6。产量和抗性表现：2018-2020年度参加江苏省淮南小麦A组区试，两年平均亩产539.1公斤，比对照扬麦20增产5.4%。2020-2021年度参加生产试验，平均亩产492.8公斤，比对照扬麦20增产5.8%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗15万左右，中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (145, 1, '扬麦37', '苏审麦20200004', '2020.11', 0, '江苏省农作物品种审定委', '江苏金土地种业有限公司、江苏里下河地区农业科学研究所', '镇麦 9 号/邯 6172，参试名称“扬 14-122”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗半直立，分蘖力中等。株型较松散， 抗倒性中等。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒 半角质。区试平均结果:全生育期 208.4 天，比对照扬麦 20 短 2.0 天。 株高 86.9 厘米，每亩有效穗 31.0 万，每穗 38.8 粒，千粒重 44.2 克。经 江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所 鉴定:中抗赤霉病(接种鉴定中抗赤霉病，严重度 1.9、2.6;自然发病 鉴定中抗赤霉病，病指 2.9、0.0)，中感纹枯病、黄花叶病毒病，高感白 粉病、叶锈病、条锈病。经江苏省农业科学院种质资源与生物研究所鉴 定:抗穗发芽。经农业部谷物品质监督检验测试中心测定:容重 809g/L、 804g/L，粗蛋白(干基)14.6%、14.0%，湿面筋 32.0% 、32.3%，吸水率 65%、64%，稳定时间 2.6min、2.0min，最大拉伸阻力 108E.U.、125E.U.， 拉伸面积 28cm2、28cm2，硬度指数 59.4、62.6。产量和抗性表现：2017-2019 年度参加江苏省淮南小麦 B 组区试，两年平 均亩产 489.6 公斤，比对照扬麦 20 增产 4.5%。2019-2020 年度参加生产 试验，平均亩产 501.9 公斤，比对照扬麦 20 增产 3.9%。', '1、适宜播期 10 月 25 日至 11 月 10 日。2、适期播 种每亩基本苗 16 万左右，中低产田适当增加。3、一般亩施纯氮 15-18 公斤，其中基苗肥占 60%、拔节孕穗肥占 40%，同时配合施用磷钾肥， 后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及 时防除田间杂草。注意防治纹枯病、赤霉病、白粉病、锈病和蚜虫等病 虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (146, 1, '扬麦41', '苏审麦20220026', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '扬92F101/镇麦9号', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，叶色深绿，分蘖力一般。株型半紧凑，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒角质。联合体区域试验平均结果：全生育期204.7天，比对照扬麦20短1.2天，株高91.3厘米，每亩有效穗29.6万，每穗36.8粒，千粒重48.9克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.30、1.50；自然发病鉴定中抗赤霉病，病指0、6.94），高感条锈病、叶锈病，感纹枯病、黄花叶病毒病，中感白粉病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重762g/L、772g/L，粗蛋白质含量（干基）13.4%、15.2%，湿面筋含量30.8%、32.0%，吸水率65%、61%，稳定时间8.3min、7.1min，最大拉伸阻力549E.U.、600E.U.，拉伸面积137cm2、124cm2，硬度指数66.6、65.6。2020年、2021年品质检测结果均达中强筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮南小麦里下河农科所科企联合体区域试验，两年平均亩产495.1公斤，比对照扬麦20增产1.4%。2020-2021年度参加生产试验，平均亩产555.6公斤，比对照扬麦20增产2.7%。', '1、适宜播期10月25日至11月5日。2、基本苗适期播种每亩16万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮18公斤左右，注意磷钾肥配合使用，后期适当喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (147, 1, '扬麦42', '苏审麦20220003', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农业科学研究所', '镇麦9号///扬麦15//扬麦15/宁麦9号', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，分蘖力较强。株型松散，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒半角质。省区域试验平均结果：全生育期207.4天，比对照扬麦20短1.7天，株高88.6厘米，每亩有效穗32.8万，每穗36.3粒，千粒重47.8克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.15、1.45；自然发病鉴定中抗赤霉病，病指0.70、2.29），高感纹枯病，感白粉病，中感叶锈病、条锈病、黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重790g/L、780g/L，粗蛋白质含量（干基）12.8%、13.2%，湿面筋含量24.6%、24.9%，吸水率59%、56%，稳定时间1.7min、2.7min，最大拉伸阻力435E.U.、404E.U.，拉伸面积90cm2、96cm2，硬度指数49.3、45.2。产量和抗性表现：2019-2021年度参加江苏省淮南A组小麦品种区域试验，两年平均亩产517.6公斤，比对照扬麦20增产4.6%。2020-2021年度参加生产试验，平均亩产522.3公斤，比对照扬麦20增产3.4%。', '1、适宜播期10月25日至11月10日。2、基本苗适期播种每亩15万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮15-18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (148, 1, '扬麦4号', '苏种审字第13号', '1982', 0, '江苏省农作物品种审定委员会', '扬州地区农科所', '[(南大2419/胜利麦)]/阿选2号', '江苏淮南麦区', '退出批次：特征特性：该品种穗大粒重，长相清秀，熟色好。耐温性、抗倒性及抗病性略好于扬麦3号，是综合性状较好的小麦品种。幼苗直立，繁茂性好。株高100厘米左右，株型略松散，茎杆粗壮，但基部节间略胜一筹偏长。叶片较宽而披，叶色淡绿。分蘖力中等，成穗数偏少，每亩28万穗左右，穗长方形，长芒有锯齿、白壳、红粒。每穗32—40粒，籽粒长园形，千粒重40—43克，硬质。春性，中早熟，全生育期205天左右，比扬麦3号晚1—2天。较抗条锈、赤霉病。缺点：中感白粉病、叶锈病，比扬麦3号略轻。春性强，抗寒性较差，春发恢复力稍差，耐肥抗倒性中等，肥过多会倒状。产量和抗性表现：1978至79年连续两年参加省淮南片小麦组区域试验，分别扬麦3号增值1.83%、7.68%。1980年平均亩产为748斤。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (149, 1, '扬麦5号', '苏种审字第70号', '1986', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农科所', '[(南大241P/胜利)/阿夫]/(ST1472/506)', '江苏淮南麦区', '退出批次：特征特性：幼苗直立，繁茂性好。株高95到100厘米，比扬四略矮5.7厘米。茎杆略细，弱性尚好。前期叶片较挺。叶色偏淡，抽穗后叶色转深，上部叶略披。分蘖力、成穗率中等略强，每亩平均穗数32.85万成穗率比扬四高3—6%。穗型较大，穗长方形，长芒、白壳、淡红粒，粒色较淡。每穗平均31.29粒左右，籽粒较饱满，粒形较大，千粒重平均37.39克左右，与扬麦三号穗数、粒数相仿，千粒重高4.12克。与宁麦三号相比，穗数多0.875万，粒数少2.7粒，千粒重高6.75克。比扬麦四号多.47万穗。粒数多1.72粒，千粒重略少1.1克左右。穗、粒、重较协调，年度间变异较小。容重平均732.85克/升，与宁三相仿，分别经扬三、扬四低22.6克/升、11.3克/升。半角质。品质略好于扬麦四号。湿面筋含量26.5%，出粉率765左右，灰分略低于扬四，为1.85%，粉色较白，面团延伸拉力略好，做面条韧性较好，做馒头有咬劲，适口性好。全生育期204—210天，与扬四相仿可略迟两天左右，比宁三早4天左右。抗倒性、耐寒性及丰产性均略好于扬麦四号。抗病性相仿，轻感赤霉病，常年田间发病稍轻。白粉病中等偏重，纹枯病较重为其主要缺点，多阴雨年分少数试点苗期、拔节期下部黄叶偏重，但返青恢复较快。抗倒性虽略好于扬三、四，但仍属中等，肥多或用肥过迟仍会倒状。此外，面团稳定时间稍短，面团应随揉随做，不宜久放。产量和抗性表现：1983—84年连续参加省淮南片小麦组区域试验，平均亩产605.23斤，分别扬麦三号增产14.85%，比宁三增产9.3%，比扬四增产7.75%，均达圾显著标准。85年省小麦生产试验，平均单产509.69斤，仍比扬四增产。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (150, 1, '扬麦6号', '苏种审字第146号', '1991', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农科所', '大丰1087/早5', '江苏苏中北部', '退出批次：特征特性：幼苗直立，叶色深绿。株高80厘米左右，株型较紧凑，茎杆粗壮，抗倒性强。分蘖力中等，成穗率较高，每亩有效穗30万左右，与扬麦5号相仿。穗长方形、白壳大粒我，穗实粒数36粒左右，籽粒琥珀色，半角质，千粒重37克左右，粗蛋白含量10.79%。弱春性，全生育期206天左右，比扬麦5号迟2天左右，全生育期比博爱74—22短11天左右。对赤霉病表现中抗，叶锈病较轻，梭条花叶病属局部中抗。中感白粉病，纹枯病偏重，后期有叶尖枯现象，熟色欠佳。产量和抗性表现：1988、1989年连续参加淮南片小麦品种区域试验，平均亩产分别为40.02公斤、313.36公斤，比扬麦5号增产3.61%、4.58%，分别达显著、极显著，分别居第二、一位，1990年省生产试验单产337.58公斤，比扬麦5号增产8.12%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (151, 1, '扬麦9号', '苏种审字第258号', '1996', 0, '江苏省农作物品种审定委员会', '江苏里下河地区农科所', '', '江苏淮南麦区', '退出批次：品种来源：特征特性：幼苗半直立，生长健壮，分蘖出生早而快。株高80厘米左右，比对照矮18.75厘米。株型略疏朗。茎杆基部节间较短，耐肥抗倒性较强。叶片较宽，叶色绿，但略淡于扬麦158。区域试验结果，分蘖率、成穗率均较高，易争足穗，每穗有效穗数30.6万，比扬麦158多20.0万穗。穗锥形、穗短、着粒产密。长芒、白壳、粒色桔红；穗中等偏大，平均每穗实粒数37.44粒，比对照多0.4粒，籽粒饱满；千粒重平均38.32克，比扬麦158低1.08克，容重平均776.7克/升，比对照高20.56克/升。粗蛋白含量9.8%，湿面筋含量27.4%，干面筋含量9.5%，面团形成时间1.3分钟，稳定时间1.7分钟，衰减度135B.Μ，沉降值33.5ml，降落值34BS，粉质评价值33分。全生期218.8，略早于扬麦158。赤霉病中抗至抗，较耐干热风。该品种较扬麦158矮秆抗倒，多穗多粒，容重较高，丰产性好，有一定增产潜力，抗寒性较好。中感白粉病、纹枯病，与扬麦158相仿，不抗梭条花叶病毒病。植株整齐度稍差，后期有叶枯、叶尖枯，熟相略差。产量和抗性表现：1993年至1995年连续两个年度参加江苏省淮南小麦品种区域试验，平均单产分354.45公斤和360.64公斤，分别比扬麦158增产1.9%和1.6%，不显著。1995年至1996年度在省生产试验中单产425.53公斤，比扬麦158增产3.67%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (152, 1, '明麦13', '苏审麦20200023', '2020.11', 0, '江苏省农作物品种审定委', '江苏明天种业科技股份有限公司', '宁麦 13/扬麦 11，参试名称“明麦 9 号”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色深绿，分蘖力较强，成穗数较高。株型较松散，抗倒性较好。穗层整齐，熟相中等。穗纺锤形， 长芒、白壳、红粒，籽粒半角质。区试平均结果:全生育期 208.0 天， 比对照扬麦 20 短 0.9 天。株高 75.4 厘米，每亩有效穗 33.4 万，每穗 39.4 粒，千粒重 39.7 克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定:中抗赤霉病(接种鉴定中抗赤霉病，严重 度 2.5、2.8;自然发病鉴定中抗赤霉病，病指 1.9、0.0)，中抗黄花叶病 毒病，高感纹枯病、白粉病、叶锈病、条锈病。经江苏省农业科学院种 质资源与生物研究所鉴定:抗穗发芽。经农业部谷物品质监督检验测试 中心测定:容重 796g/L、835g/L，粗蛋白(干基)15.8%、13.4%，湿面筋 34.2% 、31.6%，吸水率 66%、62%，稳定时间 3.7min、2.8min，最大拉 伸阻力 166E.U.，拉伸面积 44cm2。产量和抗性表现：2017-2019 年度参加江苏省淮南小麦省农科院科企联合体 区试，两年平均亩产 470.5 公斤，比对照扬麦 20 增产 3.9%。2019-2020 年度参加生产试验，平均亩产 512.4 公斤，比对照扬麦 20 增产 3.4%。', '1、适宜播期 10 月 25 日至 11 月 5 日。2、适期播种 每亩基本苗 16 万左右，肥力偏低、播期推迟应适当增加播种量。3、一 般亩施纯氮 18 公斤，其中基肥占 40%、壮蘖肥 20-25%、穗肥 35-40%， 控制腊肥及返青肥，同时配合施用磷钾肥，后期适当喷施叶面肥。田间 沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草。注意防治 纹枯病、赤霉病、锈病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (153, 1, '明麦133', '苏审麦20170001', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏明天种业科技股份有限公司、江苏浤源禾农业科技有限公司', '郑麦9023/扬麦11，参试名称“东麦1301”', '江苏省淮南麦区', '特征特性：春性中熟小麦品种。成熟期比对照扬麦20早近2天。幼苗直立，叶色较深，分蘖力中等。株型松散，抗倒性中等。穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒半硬质。区试平均结果：全生育期205.7天，株高84.4厘米，每亩有效穗32.2万，每穗37.3粒，千粒重42.9克。经江苏省农科院植保所两年接种鉴定：中抗赤霉病（严重度1.92-2.47），中感纹枯病，高感白粉病，感黄花叶病毒病。经江苏省农科院粮作所鉴定：抗穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：粗蛋白（干基）15.7%，湿面筋33.3%，吸水量62.8ml/100g，稳定时间9.3分钟，最大拉伸阻力528（Rm,135E.U），拉伸面积133cm2。2015年检测粗蛋白（干基）15.6%，湿面筋34.8%，吸水量60.8ml/100g，稳定时间13.2分钟，最大拉伸阻力550Rm,135E.U，拉伸面积140cm2，达国家级品种审定强筋小麦标准。产量和抗性表现：2014-2016年度参加江苏省淮南组小麦区域试验，两年平均亩产476.2公斤，较对照扬麦20增产4.9%。2016-2017年度参加生产试验，平均亩产506.5公斤，较对照扬麦20增产6.2%。', '1、适宜播期10月25日至11月10日。2、适期播种每亩基本苗16万左右，中低产田或迟播应适当增加。3、一般亩施纯氮15-18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草。注意防治纹枯病、白粉病、赤霉病和蚜虫等病虫害。不宜在小麦黄花叶病毒病发生田块种植。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (154, 1, '明麦16', '苏审麦20160005', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏明天种业科技股份有限公司', '徐3-01/矮抗58', '江苏省淮北麦区', '特征特性：半冬性中熟小麦品种，成熟期比对照淮麦20晚近1天。幼苗半匍匐，叶片细长，叶色深绿。分蘖力较强，越冬抗寒性较好。株型较紧凑，穗层较整齐，抗倒性较强。落黄晚，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒椭圆形，半硬质-硬质。区试平均结果：全生育期232.6天，株高79.9厘米，每亩有效穗44.5万，每穗31.8粒，千粒重43.5克。经江苏省农科院植保所三年接种鉴定：中感赤霉病（严重度2.50-3.25），高感白粉病，感纹枯病，中感小麦黄花叶病毒病。经江苏省农科院粮作所鉴定：高感穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：容重834克/升，粗蛋白含量13.4%，湿面筋含量27.1%，稳定时间3.5分钟，硬度指数64.3。产量和抗性表现：2013-2015年度参加江苏省淮北组小麦区域试验，两年平均亩产553.2公斤，较对照淮麦20增产3.8%，两年均达极显著水平。2015-2016年度参加生产试验，平均亩产597.7公斤，较对照淮麦20增产4.2%。', '1、适宜播期10月上中旬。2、适期播种每亩基本苗12万-16万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮18公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (155, 1, '明麦1号', '苏审麦200905', '2009.9', 0, '江苏省农作物品种审定委员会', '江苏明天种业科技有限公司', '淮麦18号/扬麦158//淮麦20', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶色深绿，抗寒性较好。分蘖力强，成穗数较多。株型紧凑，剑叶挺，茎杆弹性较好，抗倒性较好。纺锤型穗，穗中等大小，结实性较好。长芒，白壳，白粒，籽粒半硬质。省区试平均结果：全生育期230.1天，与对照淮麦18相当；株高85.7厘米，每亩有效穗39.0万，每穗33.2粒，千粒重41.2克。接种鉴定结果：感赤霉病，中感纹枯病、白粉病，高抗梭条花叶病。经农业部谷物品质监督检验测试中心测定，两年平均结果：容重799克/升，粗蛋白含量14.6%，湿面筋含量28.2%，稳定时间6.8分钟。产量和抗性表现：2006-2008年度参加江苏省区域试验，两年平均亩产516.8公斤，较对照淮麦18增产2.7%。2008-2009年度参加生产试验，平均亩产526.8公斤，较对照淮麦18增产8.7%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (156, 1, '明麦2号', '苏审麦201105', '2011.10', 0, '江苏省农作物品种审定委员会', '江苏明天种业科技有限公司', '淮麦17/鲁麦14', '适宜江苏省沿淮麦区种植', '退出批次：特征特性：该品种表现幼苗半直立，叶色深绿，抗寒性较好分蘖力一般，成穗数中等株型较紧凑，茎秆弹性较好，抗倒性较好穗层较厚，熟相好，纺锤型穗，结实性较好长芒、白壳、白粒，籽粒半硬质区试平均结果：全生育期224.1天，比对照偃展4110、郑麦9023迟熟1-2天；株高88.5厘米，每亩有效穗37.4万穗，每穗35.1粒，千粒重39.2克接种鉴定结果：中感赤霉病，感纹枯病、白粉病，中抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2008-2010年度两年平均结果：容重818克/升，粗蛋白含量12.5%，湿面筋含量25.8%，稳定时间2.0分钟产量和抗性表现：2008-2010年度参加江苏省淮北迟播组区域试验，2008-2009年度平均亩产489.42公斤，较对照偃展4110增产2.6%，2009-2010年度平均亩产477.3公斤，较对照郑麦9023增产3.9%，两年增产均达极显著水平2010-2011年度参加生产试验，平均亩产519.1公斤，较对照郑麦9023增产5.3%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (157, 1, '楠丰麦186', '苏审麦20220021', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏神农大丰种业科技有限公司、江苏楠峰种业科技有限公司', '烟5286/漯麦9920', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色淡绿。分蘖力较强，株型紧凑，穗层整齐，熟相较好。穗长方形，长芒、白壳、白粒，籽粒角质。省区域试验平均结果：全生育期226.5天，比对照淮麦20短1.0天，株高92.4厘米，每亩有效穗40.0万，每穗36.3粒，千粒重46.0克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度2.50、3.15；自然发病鉴定中感赤霉病，病指3.09、13.68），高感白粉病、纹枯病，中感条锈病，高抗叶锈病、黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重829g/L、833g/L，粗蛋白质含量（干基）15.1%、14.9%，湿面筋含量含量33.7%、34.2%，吸水率65%、63%，稳定时间7.8min、7.4min，最大拉伸阻力284E.U.、423E.U.，拉伸面积52cm2、93cm2，硬度指数61.6、62.1。2021年品质检测结果达到中强筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮北B组小麦品种区域试验，两年平均亩产585.8公斤，比对照淮麦20增产5.6%。2021-2022年度参加生产试验，平均亩产623.7公斤，比对照淮麦20增产5.6%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩16万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮18公斤左右，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (158, 1, '江丰麦1号', '苏审麦20190003', '2019.11', 0, '江苏省农作物品种审定委员会', '江苏大丰华丰种业股份有限公司', '扬麦16/宁麦14，参试名称“丰麦1号”', '江苏省淮南麦区', '特征特性：属春性小麦品种。幼苗直立，叶色绿。分蘖力较强，抗寒性较好。株型半紧凑，穗层较整齐，抗倒性较好，后期熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒长圆形，半硬质。区试平均结果：全生育期202.3天，比对照扬麦20晚熟0.4天。株高83.8厘米，每亩有效穗30.9万，每穗41粒，千粒重41.0克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（单花滴注鉴定中抗赤霉病，严重度2.67、1.50；自然发病鉴定中抗赤霉病，病情指数0.4、4.76），高感白粉病、纹枯病，中感叶锈病、黄花叶病，中抗条锈病。经江苏省农科院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重812g/L、786g/L，蛋白质（干基）13.46%、14.91%，湿面筋27.7%、30.0%，吸水率55.4%、55.4%，稳定时间7.0min、3.0min，最大拉伸阻力427E.U.、296E.U.，拉伸面积83cm2、70cm2，硬度指数55.3、51.3。产量和抗性表现：2016-2018年度参加江苏省淮南组小麦品种区域试验，两年平均亩产483.01公斤，比对照扬麦20增产3.91%。2018-2019年度参加生产试验平均亩产521.82公斤，比对照扬麦20增产4.23%。', '1、适宜播期为10月下旬至11月上旬，最适播期为10月底至11月5日。2、适期播种每亩基本苗16万左右，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮18公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%-70%，拔节孕穗肥占30%-40%。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。5、及时收获，蜡熟末期抓紧收获，确保丰产丰收。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (159, 1, '江麦23', '苏审麦20170005', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏中江种业股份有限公司、江苏徐淮地区徐州农业科学研究所', '淮麦18/周麦16，参试名称“徐麦2233”', '江苏省淮北麦区', '特征特性：半冬性中熟小麦品种。成熟期比对照淮麦20晚1天。幼苗半匍匐，叶片细长，叶色深绿。分蘖力强，抗寒性一般。株型较紧凑，蜡质重，穗层较整齐，抗倒性较好。落黄较好，灌浆较快，熟相较好。穗纺锤形，长芒、白壳、白粒，穗型较大，结实性较好，籽粒椭圆形，硬质。区试平均结果：全生育期234.3天，株高80.8厘米，每亩有效穗41.3万，每穗33.0粒，千粒重44.5克。病害鉴定：感赤霉病（严重度2.56-3.56），感纹枯病，中感黄花叶病，高感白粉病、叶锈病。经江苏省农科院粮作所鉴定：高感穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：粗蛋白（干基）14.0%，湿面筋 28.65%，吸水量59.8ml/100g，稳定时间5.6分钟，最大拉伸阻力325（Rm,135 E.U)，拉伸面积60cm2。产量和抗性表现：2014-2016年度参加江苏省淮北组小麦区域试验，两年平均亩产568.8公斤，较对照淮麦20增产3.8%。2016-2017年度参加生产试验，平均亩产576.1公斤，较对照淮麦20增产5.8%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗12万-16万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮16-18公斤，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合病虫害防治喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (160, 1, '江麦816', '苏审麦201306', '2013', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司', '徐麦954/烟2801', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶片细长，叶色深绿分蘖力较强，冬前分蘖多，抗寒性较好株型较紧凑，茎秆弹性较好穗层较整齐，长相清秀，剑叶挺，后期叶片功能期长，蜡质较重，熟相较好穗纺锤型，穗大码稀，结实性较好长芒、白壳、白粒，籽粒硬质，千粒重高，外观品质好区试平均结果：全生育期235.8天，比对照迟1天，株高78.1厘米，每亩有效穗39.8万穗，每穗32.4粒，千粒重42.4克接种鉴定结果：感赤霉病、白粉病，中感纹枯病，抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2010-2012年度两年平均结果：容重855.0克/升，粗蛋白含量13.7%，湿面筋含量30.4%，稳定时间6.7分钟2011-2012年度容重865.0克/升，粗蛋白含量14.01%，湿面筋含量30.6%，稳定时间8.1分钟产量和抗性表现：2010-2012年度参加江苏省淮北组小麦区域试验，平均亩产531.8公斤，较对照淮麦20增产6.3％，两年增产均达极显著水平2012-2013年度参加生产试验，平均亩产524.0公斤，较对照淮麦20增产4.8％', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (161, 1, '江麦869', '苏审麦20200019', '2020.11', 0, '江苏省农作物品种审定委', '宿迁中江种业有限公司', '矮抗 58/淮 0607 ，参试名称“江麦 9131”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，分蘖力较强，成穗多，抗寒性较好。株型较紧凑，穗层整齐，抗倒性较好，熟相好。穗纺锤形， 长芒、白壳、白粒，籽粒角质、饱满。区试平均结果:全生育期 227.0 天，与对照淮麦 20 相当。株高 77.4 厘米，每亩有效穗 43.1 万，每穗 33.6 粒，千粒重 43.0 克。经江苏省农业科学院植物保护研究所、江苏徐淮地 区徐州农业科学研究所鉴定:感赤霉病(接种鉴定感赤霉病，严重度 3.1、 3.7;自然发病鉴定感赤霉病，病指 53.8、2.1)，中感条锈病，感黄花叶 病毒病，高感白粉病、纹枯病、叶锈病。经江苏省农业科学院种质资源 与生物技术研究所鉴定:感穗发芽。经农业部谷物品质监督检验测试中 心测定:容重 822g/L、836g/L，蛋白质(干基)14.36%、13.42%，湿面 筋 32.8%、32.8%，吸水率 65%、62%，稳定时间 4.1min、3.9min，最大 拉伸阻力 159E.U.、204E.U.，能量 34cm2、41cm2，硬度指数 65.0、63.7。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦 B 组区试，两年平均 亩产 558.7 公斤，比对照淮麦 20 增产 4.8%。2019-2020 年度参加生产试 验，平均亩产 603.7 公斤，比对照淮麦 20 增产 5.2%。', ':1、适宜播期 10 月 10 日-25 日。2、适期播种每亩基 本苗 12 万-16 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯 氮 18 公斤左右，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗肥占 40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防 涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、 白粉病、叶锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (162, 1, '江麦919', '苏审麦201308', '2013', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司', '中引179/皖麦38//郑麦9023', '适宜江苏省淮北麦区晚茬及沿淮麦区种植', '退出批次：特征特性：幼苗半匍匐，叶片细长，叶色深绿分蘖力较强，冬季抗寒性好，抗倒春寒能力一般株型较紧凑，茎杆弹性较好穗层较整齐，长相清秀，熟相较好穗纺锤型，穗型中等长芒、白壳、白粒，籽粒硬质，饱满度好，外观品质好区试平均结果：全生育期226.6天，较对照淮麦20早熟1天，株高82.6厘米，每亩有效穗39.0万穗，每穗32.7粒，千粒重42.3克接种鉴定结果：感赤霉病，中感纹枯病，感白粉病，高抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2009-2011年度两年平均结果：容重827.0克/升，粗蛋白含量13.6%，湿面筋含量30.7%，稳定时间6.3分钟产量和抗性表现：2009-2011年度参加江苏省淮北迟播组小麦区域试验，两年平均亩产500.6公斤，较对照郑麦9023增产6.0%，较对照淮麦20增产3.7%，2009-2010年增产达极显著水平2011-2012年度参加生产试验，平均亩产471.7公斤，较对照淮麦20增产4.4%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (163, 1, '沣和麦693', '苏审麦20220017', '2023.01', 0, '江苏省农作物品种审定委员会', '南京沣和种业科技有限公司', '烟农21/百农矮抗58', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿。分蘖力较强，株型松紧适中，穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒角质。省区域试验平均结果：全生育期229.2天，比对照淮麦20长1.7天，株高87.2厘米，每亩有效穗40.0万，每穗37.0粒，千粒重44.4克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度1.35、3.25；自然发病鉴定中抗赤霉病，病指1.23、5.20），高感叶锈病、白粉病，感纹枯病，中感条锈病、黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重825g/L、842g/L，粗蛋白质含量（干基）12.2%、14.4%，湿面筋含量28.4%、34.2%，吸水率63%、61%，稳定时间3.2min、3.3min，最大拉伸阻力100E.U.、158E.U.，拉伸面积21cm2、42cm2，硬度指数62.5、63.0。产量和抗性表现：2019-2021年度参加江苏省淮北B组小麦品种区域试验，两年平均亩产598.5公斤，比对照淮麦20增产7.9%。2021-2022年度参加生产试验，平均亩产632.4公斤，比对照淮麦20增产7.1%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩14万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮15公斤左右，其中基苗肥占40%、拔节肥占40%、孕穗肥占20%，同时配合施用磷钾肥，后期适当喷施叶面肥。注意化控控高、防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (164, 1, '泗阳936', '苏种审字第32号', '1984', 0, '江苏省农作物品种审定委员会', '泗阳棉花原种场', '郭引204/泗阳117', '江苏淮北东部地区', '退出批次：特征特性：该品种穗大粒多，中矮杆，丰产性较突出。中抗杆锈病，越冬性好。幼苗半铺伏生长壮，叶色深绿。株高82厘米左右，茎杆矮壮，耐肥抗倒。叶片较短宽、前期挺拔上举后期上部两叶略宽披。分蘖性中等，一般每亩数30—35万，穗长方形，穗长9厘米左右，小穗0排上下，长芒、白壳，每穗38粒左右，白皮大粒，卵园形，半角质，正常年份千粒重40克左右。全生育期230天左右。缺点：白粉病较重，中感条、叶锈病。后期对水份较敏感不耐湿，也不太耐旱。分蘖力中等，穗数不易上去，灌浆速度较慢，千粒重变幅30—44克。适收期较短，迟收杆脆易断穗，。成熟后遇连阴雨，有穗发芽现象。产量和抗性表现：1981—82年连续两年参加省淮北上麦组区域试验，平均亩产分别为960.48斤、885.3 斤，分别比郑州71增产8.47%、9.88%。1988年参加省淮北片小麦生产试验，平均亩产857.28斤，比对照增10.44%。三年中间试验居第一位，具有一定生产潜力。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (165, 1, '泗麦1108', '苏种审字第386号', '2000', 0, '江苏省农作物品种审定委员会', '泗阳棉花原种场', '烟农1604/泗阳279', '江苏淮北麦区', '退出批次：特征特性：该品种幼苗匍匐，叶片短窄，叶色绿。分蘖性较强，成穗率较高。株高80—87厘米，株型紧凑，叶片上举，剑叶宽大，长势较好，抗倒性较强。该品种亩有效穗38—42万，每穗粒数30粒左右，千粒重36 —40克。长芒、白壳、白粒、纺锤型穗。该品种中抗纹枯病，感赤霉病，高抗一抗条锈病，中感白粉病。该品种容重771克/升，蛋白质含量13.1％，湿面筋含量为31.1％，沉降值为44毫升，降落值为392秒，吸水率为64 9％，面团形成时间为4 0分钟，稳定时间为5 .7分钟，断裂时间为8.0分钟，粉质评价值52分（南京经济学院，1999年），属于中筋力小麦品种。全生育期为236天左右。易受倒春寒影响导致结实率降低，后期熟相一般。产量和抗性表现：该品种1997—2000年度参加江苏省淮北小麦中间试验。1997—1998年度省区试平均亩产338.43公斤，比对照陕229增产11.70％，达极显著水平；1998—1999年度省区试平均亩产465.21公斤，比对照增产7.10％，达极显著水平；1999—2000年度参加省淮北小麦生产试验，平均亩产434.20公斤，比对照陕229增产3.00％。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (166, 1, '泰麦601', '苏审麦20200009', '2020.11', 0, '江苏省农作物品种审定委', '江苏红旗种业股份有限公司', '淮 0454/周 98165，参试名称“泰麦 601”', '江苏省淮北麦区晚茬种植', '特征特性：弱春性小麦品种。幼苗半匍匐，叶色绿。分蘖力较强，抗寒性一般。株型较紧凑，穗层整齐，抗倒性较好。拔节起身较早，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒长圆形、半角质-角质。区 试平均结果:全生育期 225.3 天，比对照淮麦 20 短 1.3 天。株高 82.0 厘 米，每亩有效穗 41.3 万，每穗 34.3 粒，千粒重 42.5 克。经江苏省农业 科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定:中感 赤霉病(接种鉴定中感赤霉病，严重度 2.8、3.1;自然发病鉴定中感赤 霉病，病指 18.1、0.0)，中抗黄花叶病，中感条锈病，高感白粉病、纹 枯病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定: 感穗发芽。经农业部谷物品质监督检验测试中心测定:容重 816g/L、 800g/L，蛋白质(干基)15.5%、13.7%，湿面筋 32.6%、33.4%，吸水率 61%、60%，稳定时间 6.3min、8.7min，最大拉伸阻力 276E.U.、415E.U.， 拉伸面积 64cm2、80cm2，硬度指数 58.9、60.4。2018-2019 年度品质指标 达到中强筋小麦品种审定标准。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦 A 组区试，两年平均 亩产 570.7 公斤，比对照淮麦 20 增产 3.0%。2019-2020 年度参加生产试 验，平均亩产 578.2 公斤，比对照淮麦 20 增产 4.8%。', ':1、适宜播期 10 月 25 日-11 月 5 日。2、适期播种每 亩基本苗 16 万左右，推迟播种或肥力水平偏低应适当增加。3、一般亩 施纯氮 18 公斤左右，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗 肥占 40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注 意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉 病、白粉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (167, 1, '泰麦6号', '苏审麦20210004', '2021.12', 0, '江苏省农作物品种审定委员会', '兴化市种业有限公司、南京东宁农作物研究所', '镇麦9号/扬麦15，参试名称“宁1805”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，分蘖力及成穗数一般。株型较松散，抗倒性中等，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒角质。区试平均结果：全生育期207.9天，比对照扬麦20短1.2天。株高87.6厘米，每亩有效穗30.4万，每穗43.3粒，千粒重43.9克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.95、1.35、1.35；自然发病鉴定中抗赤霉病，病指0.80、7.30、4.85），中抗叶锈病，感纹枯病、黄花叶病毒病，高感白粉病、条锈病。经江苏省农业科学院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重823g/L、821g/L，粗蛋白(干基)含量15.6%、15.1%，湿面筋含量35.9%、31.5%，吸水率62.7%、63.9%，稳定时间9.1min、5.9min，最大拉伸阻力571E.U.、290E.U.，拉伸面积137cm2、79cm2，硬度指数66.6、66.6。2019-2020年度品质指标达中强筋小麦品种审定标准。产量和抗性表现：2019-2021年度参加江苏省淮南小麦A组区试，两年平均亩产518.8公斤，比对照扬麦20增产4.9%。2020-2021年度参加生产试验，平均亩产485.1公斤，比对照扬麦20增产4.2%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗16万左右，迟播适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治赤霉病、纹枯病、白粉病、条锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (168, 1, '泰麦901', '苏审麦20200002', '2020.11', 0, '江苏省农作物品种审定委', '江苏红旗种业股份有限公司、江苏省农业科学院粮食作物研究所', '镇麦 9 号/7408，参试名称“宁红 1479”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，分蘖力中等。株型较紧凑，抗倒性一般。穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽 粒半角质。区试平均结果:全生育期 209.4 天，与对照扬麦 20 相当。株 高 87.2 厘米，每亩有效穗 33.4 万，每穗 36.9 粒，千粒重 43.3 克。经江 苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴 定:中抗赤霉病(接种鉴定中抗赤霉病，严重度 1.1、2.5;自然发病鉴 定中抗赤霉病，病指 1.3、0.0)，中抗条锈病、黄花叶病毒病，高感纹枯病、白粉病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所 鉴定:高抗穗发芽。经农业部谷物品质监督检验测试中心测定:容重 808g/L、828g/L，粗蛋白(干基)14.3%、14.9%，湿面筋 31.0% 、35.1%， 吸水率 61%、64%，稳定时间 2.0min、6.6min，最大拉伸阻力 290E.U.、 401E.U.，拉伸面积 77cm2、80cm2，硬度指数 62.9、63.5。产量和抗性表现：2017-2019 年度参加江苏省淮南小麦 A 组区试，两年平 均亩产 502.8 公斤，比对照扬麦 20 增产 4.5%。2019-2020 年度参加生产 试验，平均亩产 506.4 公斤，比对照扬麦 20 增产 3.4%。', '1、适宜播期 10 月下旬至 11 月初。2、适期播种每 亩基本苗 15 万左右，迟播应适当增加。3、一般亩施纯氮 16 公斤，其中 基苗肥占 60%、拔节孕穗肥占 40%，同时配合施用磷钾肥，后期适当喷 施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间 杂草。注意防治纹枯病、赤霉病、白粉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (169, 1, '济麦21', '苏审麦200604', '2006.9', 0, '江苏省农作物品种审定委员会', '徐州市种子站', '鲁865168／川农大84-1109//冀84-5418', '适宜江苏淮北麦区种植', '退出批次：特征特性：该品种长芒，白壳，穗纺锤形，籽粒饱满，白皮、角质，商品性较好。幼苗半匍匐，分蘖力强，抗寒性较好。株型较紧凑，株高77厘米左右，茎杆弹性较好，抗倒伏。成穗多，穗层整齐，成熟期中等，综合性状较好。每亩有效穗45万左右，每穗结实30粒左右，千粒重41克左右。田间叶锈病发生轻。接种鉴定：感赤霉病、中感纹枯病、白粉病、棱条花叶病，抗穗发芽。品质分析三年平均结果：粗蛋白含量14.8%，湿面筋含量31.6%，稳定时间3.5分钟，属中筋品种。产量和抗性表现：2003-2005年度参加江苏省区域试验，两年平均亩产501.42公斤，产量与对照淮麦18相当；2005-2006年度生产试验平均亩产512.5公斤，较对照淮麦18增产2.38%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (170, 1, '润扬麦1号', '苏审麦20210018', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏润扬种业股份有限公司', '扬麦20/生抗2号，参试名称“润扬麦5145”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色深绿，叶片较大，剑叶较挺，株型较松散，分蘖力较强，成穗数较高，穗型较大，穗层整齐度好，熟相好，抗倒性一般。纺锤型穗，长芒，白壳，红粒，半角质。区试平均结果：全生育期208.1天，比对照扬麦20长0.4天。株高89.8厘米，每亩有效穗31.1万，每穗42.1粒，千粒重44.3克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.74、1.72、2.50；自然发病鉴定抗赤霉病，病指0、0.12、3.10），中感条锈病，感黄花叶病毒病，高感纹枯病、白粉病、叶锈病。经江苏省农业科学院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重822g/L、810g/L，粗蛋白(干基)含量12.6%、12.7%，湿面筋含量28.1%、28.1%，吸水率54.5%、59.1%，稳定时间1.7min、2.8min。产量和抗性表现：2018-2020年度参加江苏省淮南小麦省农科院科企联合体区试，两年平均亩产506.5公斤，比对照扬麦20增产4.0%。2020-2021年度参加生产试验，平均亩产497.3公斤，比对照扬麦20增产3.9%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗18万左右，中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (171, 1, '淮麦11号', '苏种审字第29号', '1983', 0, '江苏省农作物品种审定委员会', '淮阴地区农科所', '(意大利小麦st2734/525)/智利小麦rotofem', '江苏淮北地区', '退出批次：特征特性：幼苗半匍伏。株高85厘米左右，株型紧凑，茎杆矮壮、中粗较坚韧，表面有蜡粉。叶片较狭而上举，叶色深绿。生长较清秀、整齐。耐肥抗倒，分蘖力强，成穗率较高，每亩穗数49万穗左右。穗纺锤形，长芒，白壳，穗长8厘米左右，每穗26粒左右，籽粒椭园形，白色，千粒重34—35克左右。半硬质、品质较好（湿筋率24%）。全生育期230天左右。缺点：中感白粉病、杆锈病。穗型较小，粒重稍低。中后期肥水不足，基部小穗易退化。播种过迟或中后期肥太多，易发生白粉病。后期叶片有干尖、早枯现象，熟色稍差。该品种穗大粒多，中矮杆，丰产性较突出。中抗杆锈病，越冬性好。产量和抗性表现：1977至78年连续两年参加省淮北片小麦组区域试验，平均亩产分别为859.44斤、769.46斤，比对照太山四号分别增产6.57%、14.55%。两年参加试的共17个点，其中：8个点增产幅度9.9—26.1%，达显著标准；6个点增产幅度5.5—8.7%，不显著；一点平产；两点减产，分别为2.9—4.1%，不显著。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (172, 1, '淮麦12', '苏种审字第68号', '1986', 0, '江苏省农作物品种审定委员会', '江苏淮阴地区农科所', '南大8号/202', '江苏沿淮麦区', '退出批次：特征特性：幼苗半匍伏，繁茂性好，生长健壮。株高85厘米左右，半矮杆，株型略松。茎杆粗壮，较耐肥抗倒。前中期叶片较宽而挺，上部叶略披。分蘖力较台，成穗率中等到，省区域试验和省生产试验（下同）平均分别43.85万、43.03万穗 ，分别比济南13号少0.495万、5.12万穗。穗层较整齐，穗纺锤形，长芒、白壳，每穗平均28.3粒左右，分别经郑州761多2粒、比济南13号多6粒。籽粒白色，半硬质，千粒重平均37—40克，分别经郑州761高1.4克，比济南13呈低5.6克。穗、粒、重较协调，变幅较小。籽粒外观及加工品质较好。容重较高，770克/升左右，精粉率73%左右，灰分较低，为1.66%。粗蛋白含量12.47—13%。赖氨酸含量0.39%，湿面筋含量达33—36.5%。面团拉抻阻力320Bμ，延伸性较好，18.2厘米左右，能做面包、馒头，适于做面条、饺皮。全生育期平均230—244.5天，分别比郑州761早0.5天左右、比济南13号早熟2.5天左右。较耐湿性、耐寒性较好。高抗条锈病，较耐纹枯病，白粉病、叶锈病较轻。中感赤霉病，杆锈病，后期耐旱性较差，迂早有干尖、干芒现象。产量和抗性表现：1982—83年连续两年参加淮北小麦区域试验。1982年平均亩产861.8斤，比郑州761增产6.9%，达显著水准。1983年平均亩产780.7斤，比郑州761增产17.9%，达极显著水准。1984年参加省淮北生产试验，平均亩产843.5斤，比济南13号增3.1%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (173, 1, '淮麦136', '苏审麦20220020', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所', '淮麦28/淮麦25//淮麦52', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，分蘖力较强。株型半紧凑，穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒角质。省区域试验平均结果：全生育期227.6天，比对照淮麦20长0.1天，株高89.8厘米，每亩有效穗41.9万，每穗32.6粒，千粒重48.1克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：感赤霉病（接种鉴定中感赤霉病，严重度1.95、2.96；自然发病鉴定感赤霉病，病指0.86、23.04），高感纹枯病、白粉病、叶锈病，中感条锈病，中抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重822g/L、839g/L，粗蛋白质含量（干基）13.9%、14.3%，湿面筋含量含量29.8%、31.5%，吸水率64%、64%，稳定时间5.9min、5.0min，最大拉伸阻力211.0E.U.、228.0E.U.，拉伸面积43cm2、49cm2，硬度指数66.3、65.4。产量和抗性表现：2019-2021年度参加江苏省淮北B组小麦品种区域试验，两年平均亩产597.9公斤，比对照淮麦20增产7.8%。2021-2022年度参加生产试验，平均亩产630.4公斤，比对照淮麦20增产6.9%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩15万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。注意化控控高、防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (174, 1, '淮麦15号', '苏种审字第335号', '1999', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农科所', '郑州891/烟1604', '江苏淮北麦区', '退出批次：特征特性：幼苗半葡伏，叶片细长，叶色深绿。株高90厘米左右，株型紧凑。分蘖力强，成穗数多，平均每亩成穗40.80万。长芒、白壳，纺缍形穗，每穗平均34粒左右。籽粒饱满，半角质，白皮， 千粒重为40克左右。淮麦15号粗蛋白含量13.9%，湿面筋26.2%，出粉率67.0%，面团形成时间1.7分钟，稳定虹.5分钟，断裂时间4.7分钟，综合评价值38.0分。全生育期235天左右，比对照陕229早2－3天，综合抗性较好。抗寒性强，抗倒性一般，中抗白粉病、纹枯病、中感叶锈病、赤霉病。后期熟相较好。产量和抗性表现：1995年至1997年连续两个年度参加江苏省淮北小麦品种区域试验，两年平均单产分别为537.96公斤和501.67公斤，分别比对照冀5418增产4.47%和12.61%，均达极显著水平。1997－1998年度在江苏省淮北小麦品种生产试验中平均亩产302.30公斤，比对照陕229增产8.83%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (175, 1, '淮麦16号', '苏种审字第336号', '1999', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农科所', '轮回选择', '江苏淮北麦区', '退出批次：特征特性：幼苗半葡伏偏直立，剑叶宽挺，叶色翠绿，起身拔节时。株高90厘米左右，株型较紧凑。分蘖力中等，成穗率较高等，平均亩成穗 42万左右。籽粒商品性好，角质，白皮，千粒重为42克左右。淮麦16号粗蛋白含量15.4%，湿面筋含量35.8%，出粉率69.0%，面团形成时间3.5分钟，稳定时间4.0分钟，断裂时间6.0分钟，综合评价值47.0分。全生育期234天左右，比陕229早3天。抗倒性中等偏上，抗寒性中等，中抗白粉病，中感叶锈病、纹枯病、赤霉病，生长后期活性强，耐湿性好。淮麦16号易争足穗，综合性状较好。产量和抗性表现：1995年至1997年连续两年度参加江苏省淮北小麦品种区域试验，两年平均单产分别为548.27公斤和497.03公斤，分别比对照冀5418增产6.47%和11.57%，均达到极显著水平。1997－1998年度在江苏省淮北小麦品种生产试验中平均亩产318.70公斤，比对照陕229增产14.72%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (176, 1, '淮麦18号', '苏种审字第340号', '1999', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农科所', '郑891/烟1604', '江苏淮北麦区', '退出批次：特征特性：幼苗半匍匐，叶色浓绿，叶片细长，生长茁壮。株高85-90厘米，株型紧凑，叶片上冲，茎杆坚韧，长相清秀。分蘖力强，成穗率较高，穗层整齐。长芒、白壳、纺锤形穗，每穗平均35粒左右。白皮，半角质，千粒重为40克左右。品质较优，粗蛋白含量13.3%，湿面筋含量27.9%，吸水率59.5%，面团形成时间2.5分钟，稳定时间9.5分钟，断裂时间10.5分钟，粉质评价值为54分（南京经济学院1999年10月日测定，下同）。生育期235天左右，比对照陕229早2天。抗白粉病，中抗纹枯病、条锈病，感赤霉病和叶锈病。抗寒性较好，抗倒性强。熟相一般。产量和抗性表现：1997至1999年连续两个年度参加江苏省淮北小麦品种区域试验，平均亩产分别为358.48公斤和488.86公斤，比对照陕229增产18.30%和12.54%，增产均达极显著水平。1998至1999年度在江苏省淮北小麦品种生产试验中亩产460.04公斤，比对照陕229增产11.04%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (177, 1, '淮麦19号', '苏审麦200101', '2001', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农科所', '冬春性小麦轮回选择群体进行连续单株选择', '江苏淮北及淮南北部麦区', '退出批次：特征特性：该品种幼苗半匍匐，叶色较淡，叶片宽挺。分蘖性中等，成穗率较高。株高85厘米左右，株型紧凑，叶片上冲，长相清秀。茎秆弹性一般。该品种亩有效穗40-45万左右，每穗粒数30粒左右，千粒重43克。长芒、白壳、白皮、纺锤型穗，小穗排列较稀，结实性较好。该品种中抗赤霉病、白粉病，中抗-感纹枯病，中感叶锈。该品种容重803克/升，蛋白质含量13.95%，湿面筋含量38.00%，沉降值27毫升，降落值370秒，吸水率65%，面团稳定时间为2.0分钟，粉质评价值44分（南京经济学院粮油检测中心，2000年）。产量和抗性表现：该品种1999-2001年度参加江苏省淮北小麦中间试验。1999-2000年度省区试平均亩产488.15公斤，比对照陕229增产11.64%，比第二对照徐州25号增产9.95%，增产均达极显著水平；2000-2001年度省区试平均亩产522.65公斤，比对照陕229增产14.22%，增产达极显著水平；2000-2001年度参加省淮北小麦生产试验，平均亩产463.70公斤，比对照陕229增产3.04%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (178, 1, '淮麦20号', '苏审麦200201', '2002', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农科所', '豫麦13/鲁麦14杂交', '江苏淮北', '退出批次：特征特性：该品种纺锤型穗，籽粒白色、角质，幼苗半匍伏，叶色深，分蘖性较强，成穗数较多，株型较紧凑，茎杆强度较好，剑叶小且上举，前期生长较缓慢，拔节后生长速率加快，株高85厘米左右；每亩穗数38万左右，每穗粒数33粒左右，千粒重42克左右，容重800克左右，成熟期较陕229早1-2天。中抗白粉病，中感赤霉病和叶锈病，但严重度和普遍率均低于对照陕229，纹枯病轻，灌浆快，熟相一般。据2000年10月省区试统一送样品质分析（南京经济学院），粗蛋白含量13.70%，湿面筋28.80％，干面筋10.2％，沉降值30ml，吸水率56.9%，面团形成时间8.3min，面团稳定时间14.5min，粉质评价值74分(同年对照陕229为52分)，属强筋品种。产量和抗性表现：1999-2001年参加省区域试验，1999-2000年平均亩产473.69公斤，较对照陕229、徐州25号分别增产8.35％、6.71％，差异均达极显著，列第4位；2000-2001年平均亩产512.41公斤，较对照陕229增产11.98％，极显著。2001-2002年度参加生产试验，平均亩产433.7公斤，较对照陕229增产11.9%。该品种产量水平较高，综合抗性较好。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (179, 1, '淮麦21', '苏审麦200603', '2006.9', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所', '淮麦17/豫麦54', '适宜江苏沿淮及淮北麦区种植', '退出批次：特征特性：该品种长芒、白壳、穗近长方形，籽粒白皮、角质；幼苗半匍匐，叶色深绿，分蘖力强，抗寒性较好。株型较紧凑，株高82厘米左右，抗倒性好。穗层整齐，熟相好。全生育期223天左右。每亩有效穗37万左右，每穗36粒左右，千粒重36克左右。接种鉴定：抗白粉病，中抗赤霉病，中感纹枯病，高感梭条花叶病毒病，高感穗发芽。品质分析三年平均结果为粗蛋白含量12.3%，湿面筋含量26.2%，稳定时间5.9分钟，属中筋品种。产量和抗性表现：2004-2006年度参加江苏省区域试验，两年平均亩产493.62公斤，较对照豫麦18增产10.84%，分别较对照增产达显著、极显著水平；2005-2006年度组织生产试验，平均亩产481.6公斤，较对照豫麦18增产4.19%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (180, 1, '淮麦23', '苏审麦200607', '2006.9', 0, '江苏省农作物品种审定委员会', '徐淮地区淮阴农科所', '冬春小麦轮回群体经多代选择', '适宜江苏淮北麦区种植', '退出批次：特征特性：该品种长芒，白壳，穗纺锤形，籽粒饱满，白皮、半角质，商品性好。幼苗半匍匐，分蘖力较强，抗寒性较好。株型较松散，茎叶蜡质较重，剑叶短小，株高82厘米左右，茎杆弹性较好，抗倒伏。成穗数中等，穗层整齐，熟相好。每亩有效穗38万左右，每穗32粒左右，千粒重45克左右。田间叶锈病发生轻。接种鉴定：中抗梭条花叶病，中感纹枯病、白粉病，感赤霉病、穗发芽。品质分析三年平均结果：粗蛋白含量13.1%，湿面筋含量22.6%，稳定时间2.9分钟。产量和抗性表现：2003-2005年度参加江苏省区域试验，两年平均亩产505.74公斤，产量与对照淮麦18相当；2005-2006年度生产试验平均亩产520.2公斤，较对照淮麦18增产3.92%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (181, 1, '淮麦24', '苏审麦200703', '2007.9', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所', '太谷核不育小麦采用轮回选择', '适宜江苏省淮北麦区种植', '退出批次：特征特性：长芒，白壳，白粒，纺锤型穗，籽粒半硬质幼苗半匍匐，叶片细长，分蘖力较强，抗寒性一般株型较紧凑，长相清秀，株高85厘米左右，穗层整齐，茎秆弹性较好熟期适中，熟相较好，全生育期236天左右，比对照长1天亩有效穗40万左右，每穗34粒左右，千粒重41克左右接种鉴定结果：感赤霉病，中抗纹枯病、棱条花叶病，中感穗发芽田间表现中感白粉病、纹枯病、条锈病，叶锈病零星发生品质分析两年平均结果：粗蛋白含量12.8%，湿面筋含量25.2%，稳定时间2.1分钟产量和抗性表现：2004-2006年度参加江苏省区域试验，两年平均亩产527.0公斤，较对照淮麦18增产3.8%，两年分别较对照增产达显著、极显著水平；2006-2007年度组织生产试验，平均亩产528.4公斤，较对照增产6.7%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (182, 1, '淮麦26', '苏审麦200903', '2009.9', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所', '淮麦18号/百农9267', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶片细长，叶色深绿，前期长势较慢，抗寒性较好。分蘖力强，成穗数多。株型较紧凑，茎杆弹性较好，抗倒性较好。蜡质较重，剑叶适中，长相清秀，穗层整齐，熟相好。纺锤型穗，结实性好。长芒，白壳，白粒，籽粒半硬质-硬质。省区试平均结果：全生育期231天，较对照淮麦18迟熟1天；株高87.5厘米，每亩有效穗39.4万，每穗33.0粒，千粒重41.9克。接种鉴定结果：中感赤霉病，感纹枯病，中抗白粉病，中抗梭条花叶病毒病。经农业部谷物品质监督检验测试中心测定， 2005-2008年三年平均结果：容重807克/升，粗蛋白含量14.8%，湿面筋含量32.7%，稳定时间6.4分钟；2008年容重826克/升，粗蛋白含量14.7%，湿面筋含量32.2%，稳定时间9.1分钟。产量和抗性表现：2005-2008年度参加江苏省区域试验，三年平均亩产522.0公斤，较对照淮麦18增产3.2%。2008-2009年度参加生产试验，平均亩产514.1公斤，较对照淮麦18增产6.1%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (183, 1, '淮麦27', '苏审麦200906', '2009.9', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所', '冬春小麦轮回群体中选择可育株后代', '江苏省淮北南部及沿淮麦区种植。', '退出批次：特征特性：幼苗半匍匐，叶色深绿，长势健壮，抗寒性较好。分蘖力强，成穗数多。株型紧凑，抗倒性一般。穗层较整齐，纺锤型穗，穗中等大小，结实性较好。长芒，白壳，白粒，籽粒半硬质。省区试平均结果：全生育期220.6天，2009年生试成熟期较对照淮麦20迟1天；株高86.8厘米，每亩有效穗39.4万，每穗34.7粒，千粒重40.3克。接种鉴定结果：中感赤霉病，感纹枯病、白粉病，高抗梭条花叶病。经农业部谷物品质监督检验测试中心测定，三年平均结果：容重792克/升，粗蛋白含量11.6%，湿面筋含量21.1%，稳定时间3.7分钟。产量和抗性表现：2006-2008年度参加江苏省区域试验，2006-2007年平均亩产499.9公斤，较对照豫麦18增产16.5%，增产极显著；2007-2008年平均亩产494.0公斤，较对照偃展4110减产2.2%，减产不显著；2008-2009年平均亩产499.2公斤，较对照偃展4110增产4.6%，增产极显著。2008-2009年度参加生产试验，平均亩产523.2公斤，较对照偃展4110增产8.4%，较对照淮麦20增产7.0%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (184, 1, '淮麦30', '苏审麦201007', '2010.1', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农科所', '郑麦9023/淮86175', '适宜江苏省淮北麦区晚播及沿淮麦区种植', '退出批次：特征特性：幼苗半匍匐，叶色深绿，生长健壮，抗寒性较好分蘖力中等，成穗数较多株型紧凑，穗层整齐，熟相好茎秆弹性好，抗倒性较强纺锤型穗，穗中等大小，结实性一般长芒、白壳、白粒，籽粒硬质、饱满度好，千粒重高区试平均结果：全生育期217.7天，较对照偃展4110略早；株高81.3厘米，每亩有效穗40.5万穗，每穗29.1粒，千粒重48.3克接种鉴定结果：中抗赤霉病，中感纹枯病，感白粉病，抗黄花叶病中抗穗发芽经农业部谷物品质监督检验测试中心测定，2007-2009年度两年平均结果：容重822克/升，粗蛋白含量12.9%，湿面筋含量24.4%，稳定时间3.4分钟产量和抗性表现：2007-2009年度参加江苏省区域试验，两年平均亩产509.4公斤，较对照偃展4110增产3.71%，2008-2009年分别较对照偃展4110、淮麦20增产6.4%、3.1%2009-2010年度参加生产试验，平均亩产513.8公斤，较对照郑麦9023增产8.6%，较对照淮麦20增产4.5%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (185, 1, '淮麦31', '苏审麦201103', '2011.10', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所', '淮麦20/邯郸4564', '适宜江苏省淮北麦区种植', '退出批次：特征特性：该品种表现幼苗半匍匐，叶色深绿，前期长势较慢，抗寒性较好，拔节抽穗迟，抗倒春寒能力强分蘖力较强，成穗率中等株型较松散，株高中等，茎杆弹性较好，抗倒性较好剑叶挺，大小适中，长相清秀穗层整齐，灌浆速度快，后期熟相好纺锤型穗，结实性好长芒、白壳、白粒，籽粒硬质，千粒重较高区试平均结果：全生育期234.1天，较对照淮麦20早熟1天；株高83.7厘米，每亩有效穗36.4万穗，每穗38.5粒，千粒重39.3克接种鉴定结果：感赤霉病、纹枯病、白粉病，抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2007-2010年度三年平均结果：容重805克/升，粗蛋白含量13.2%，湿面筋含量26.9%，稳定时间7.2分钟；2008年容重827克/升，粗蛋白含量14.4%，湿面筋含量29.3%，稳定时间11.1分钟产量和抗性表现：2007-2010年度参加江苏省淮北组区域试验，2007-2008年度平均亩产519.5公斤，较淮麦18增产3.67%，增产不显著2008-2010年度两年平均亩产516.0公斤，较对照淮麦20增产5.8%，两年增产均达极显著水平2010-2011年度参加生产试验，平均亩产554.7公斤，较对照淮麦20增产4.2%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (186, 1, '淮麦32', '苏审麦201207', '2012.11', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所', '从太谷核不育基因组建的冬春性小麦轮回群体中选择', '江苏省淮北麦区种植', '退出批次：特征特性：该品种表现幼苗半直立，叶片细长，叶色深绿，抗寒性较好分蘖力强，成穗数高株型紧凑，茎秆弹性较好，抗倒性较好根系活力强，耐旱、耐渍性好穗层整齐，熟相好，纺锤型穗，结实性较好长芒、白壳、白粒，籽粒半硬质区试平均结果：全生育期238.5天，与对照相当；株高80.7厘米，每亩有效穗39.1万穗，每穗37.0粒，千粒重39.0克接种鉴定结果：感赤霉病，中感纹枯病，感白粉病，高感黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2008-2010年度两年平均结果：容重776.0克/升，粗蛋白含量12.3%，湿面筋含量23.3%，稳定时间1.6分钟产量和抗性表现：2008-2010年度参加江苏省淮北组小麦区域试验，两年平均亩产509.9公斤，较对照淮麦20增产4.6%，两年增产均达极显著水平2010-2011年度参加生产试验，平均亩产554.2公斤，较对照增产4.1%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (187, 1, '淮麦33', '苏审麦201305', '2013', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所', '烟农19/郑麦991', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶色深绿，前期长势较快分蘖力一般，抗寒性较强株型较紧凑，长相清秀，穗层整齐，剑叶挺，茎杆弹性好，抗倒性好穗近长方型，穗较大，结实性较好长芒、白壳、白粒，籽粒硬质，千粒重高区试平均结果：全生育期235.2天，与对照相当，株高80.9厘米，每亩有效穗39.0万穗，每穗35.6粒，千粒重40.5克接种鉴定结果：抗纹枯病，感赤霉病、白粉病，高感黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2010-2012年度两年平均结果：容重843.0克/升，粗蛋白含量12.9%，湿面筋含量27.7%，稳定时间5.7分钟产量和抗性表现：2010-2012年度参加江苏省淮北组小麦区域试验，平均亩产531.9公斤，较对照淮麦20增产6.3％，两年增产均达极显著水平2012-2013年度参加生产试验，平均亩产529.9公斤，较对照淮麦20增产6.0％', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (188, 1, '淮麦36', '苏审麦201408', '2014', 0, '江苏省农作物品种审定委员会', '江苏省金地种业科技有限公司、淮安市全新生物科技有限公司', '鲁麦14/淮894', '适宜江苏省沿淮麦区及淮北麦区晚茬口种植', '退出批次：特征特性：幼苗半匍匐，分蘖力较强，抗寒性较好株型紧凑，抗倒性较好穗纺锤形，长芒、白壳、白粒，籽粒硬质区试平均结果：全生育期220.5天，比淮麦20早熟1天，株高82.0厘米，每亩有效穗41.9万，每穗28.3粒，千粒重39.9克抗病性经江苏省农科院植保所2011-2013年接种鉴定：感赤霉病，中感纹枯病、白粉病，高感小麦黄花叶病毒病品质经农业部谷物品质监督检验测试中心测定，2011-2013年度两年平均结果：容重813.5克/升，粗蛋白含量15.2%，湿面筋含量32.9%，稳定时间10.4分钟，硬度指数65.3；其中2012-2013年度结果：容重804.0克/升，粗蛋白含量15.6%，湿面筋含量33.5%，稳定时间17.0分钟，硬度指数67.3产量和抗性表现：2011-2013年度参加江苏省淮北迟播组小麦区域试验，两年平均亩产469.4公斤，较对照郑麦9023增产6.9%，较对照淮麦20增产3.6%，2012-2013年增产达极显著水平2013-2014年度参加生产试验，平均亩产555.7公斤，较对照淮麦20增产5.2%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (189, 1, '淮麦38', '苏审麦201506', '2015', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所、江苏天丰种业有限公司', '太谷核不育基因组建的冬春性小麦轮回群体中系谱选择', '江苏省沿淮麦区种植', '退出批次：特征特性：幼苗半匐匍，叶片深绿，分蘖力强，抗寒性较好株型偏松散，长相清秀，穗层整齐，抗倒性较好后期熟相较好长芒，白壳，白粒，纺锤型穗，籽粒角质，饱满度好区试平均结果：全生育期216.5天，亩有效穗44.4万，每穗31.5粒，千粒重39.7克抗病性经江苏省农科院植保所三年接种鉴定：中感赤霉病，感纹枯病，高感粉病，高抗小麦黄花叶病毒病品质经农业部谷物品质监督检验测试中心测定，区试两年测定平均结果：容重813克/升，粗蛋白含量14.02%，湿面筋含量28.4%，稳定时间5.85分钟，硬度指数50.9产量和抗性表现：2012-2014年度参加江苏省淮北迟播组小麦区域试验，两年平均亩产512.65公斤，较对照郑麦9023增产9.2%，两年增产均达极显著水平；较对照淮麦20增产2.07%2013-2014年度参加生产试验，平均亩产517.91公斤，较对照淮麦20增产6.0%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (190, 1, '淮麦39', '苏审麦201507', '2015', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所、江苏天丰种业有限公司', '周麦13/豫麦69', '江苏省沿淮麦区及淮北麦区晚茬口种植', '退出批次：特征特性：幼苗半匍匐，分蘖力较强，抗寒性较好株型紧凑，抗倒性较好穗纺锤形，长芒、白壳、白粒，籽粒硬质区试平均结果：全生育期216.9天，与淮麦20相当，株高83.0厘米，每亩有效穗39.0万，每穗36.6粒，千粒重41.3克抗病性经江苏省农科院植保所三年接种鉴定：中感赤霉病、纹枯病，高感白粉病、小麦黄花叶病毒病品质经农业部谷物品质监督检验测试中心测定，两年区试测定平均结果：容重789克/升，粗蛋白含量13.7%，湿面筋含量28.05%，稳定时间12.2分钟，硬度指数65.6；其中2012-2013年度结果：容重803克/升，粗蛋白含量14.88%，湿面筋含量30.2%，稳定时间17.6分钟，硬度指数66.4产量和抗性表现：2012-2014年度参加江苏省淮北迟播组小麦区域试验，两年平均亩产528.55公斤，较对照郑麦9023增产12.59%，较对照淮麦20增产5.24%，两年增产均达极显著水平2014-2015年度参加生产试验，平均亩产527.17公斤，较对照淮麦20增产7.96%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (191, 1, '淮麦43', '苏审麦20170007', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农科所、江苏农科种业研究院有限公司', '太谷核不育基因组建的冬春性小麦轮回群体，参试名称“淮核130068”', '江苏省沿淮麦区及淮北麦区晚茬口', '特征特性：半冬性中熟品种。成熟期比对照品种淮麦20早1天，比淮麦30晚0.6天。幼苗半匍匐，叶片细长，叶色绿色，抗寒性较好。分蘖力强，成穗数多。株型松紧适宜，剑叶挺，叶色淡绿色，茎杆弹性好，抗倒性较好。穗层整齐，穗纺锤型，长芒、白壳、白粒，籽粒角质。区试平均结果：全生育期215.8天，株高82.1厘米，每亩有效穗42.6万，每穗33.0粒，千粒重41.1克。落黄好，成熟中早，熟相好。病害鉴定：中感赤霉病（严重度2.47 -3.0），高感纹枯病、白粉病、叶锈病，抗黄花叶病毒病。经江苏省农科院粮作所鉴定：高感穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：粗蛋白（干基）13.1%，湿面筋26.7%，吸水量60.3ml/100g，稳定时间9.5分钟，最大拉伸阻力408（Rm,135E.U），拉伸面积72cm2。产量和抗性表现：2014-2016年度参加江苏省淮北晚播组小麦区域试验，两年平均亩产527.9公斤，2014-2015年较对照淮麦20增产6.9%，增产达极显著水平，2015-2016年较对照淮麦30增产9.8%。2016-2017年度参加生产试验，平均亩产556.8公斤，较对照淮麦30增产6.6%。', '1、适宜播期为10月20日-11月5日。2、一般每亩基本苗15-20万，肥力水平偏低或播期推迟，应适当增加。3、一般亩施纯氮16-18公斤，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。5、沿淮小麦穗发芽多发地区慎重种植。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (192, 1, '淮麦44', '苏审麦20170010', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所', '百农9711/淮麦95079//淮麦9701，参试名称“淮麦302”', '江苏省沿淮麦区及淮北麦区晚茬口', '特征特性：半冬性中熟品种。成熟期比对照品种淮麦20早1-2天。幼苗半匍匐，叶片短小，叶色绿色，前期长势慢，抗寒性较好。分蘖力较强，成穗数多。株型较紧凑，剑叶挺，抗倒性较好。穗纺锤型，长芒、白壳、白粒，籽粒角质。区试平均结果：全生育期215.8天，株高79.4厘米，每亩有效穗42.4万，每穗33.3粒，千粒重44.1克。落黄较早，熟相较好。病害鉴定：中感赤霉病（严重度2.85-2.9），感纹枯病，高感白粉病、感叶锈病，抗黄花叶病。经江苏省农科院粮作所鉴定：感穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：粗蛋白（干基）13.4%，湿面筋28.9%，吸水量62.5ml/100g，稳定时间6.1分钟，最大拉伸阻力335（Rm,135E.U），拉伸面积64cm2。产量和抗性表现：2014-2016年度参加江苏省淮北晚播组小麦区域试验，两年平均亩产553.5公斤，2014-2015年较对照淮麦20增产10.9%，2015-2016年较对照淮麦30增产16.4%。2016-2017年度参加生产试验，平均亩产560.7公斤，较对照淮麦30增产7.3%。', '1、适宜播期为10月20日-11月5日。2、一般每亩基本苗18万-22万，肥力水平偏低或播期推迟，应适当增加。3、一般亩施纯氮16公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (193, 1, '淮麦45', '苏审麦20180007', '2018.12', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所', '淮麦28/淮麦25，参试名称“淮麦1403”', '江苏省淮北麦区', '特征特性：属半冬性中熟小麦品种。幼苗半匍匐，叶色较深。分蘖力较强，抗寒性较好。株型较紧凑，穗层整齐，抗倒性较好。拔节起身较早，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒长圆形，硬质。区试平均结果：全生育期225.7天，成熟期比对照淮麦20早0.4天。株高81.8厘米（生试株高77.4厘米），每亩有效穗42.8万，每穗32.9粒，千粒重44.2克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：感赤霉病（严重度2.75-4，2017年自然发病鉴定中感），高感白粉病、纹枯病和叶锈病，高抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：感穗发芽。经农业部谷物品质监督检验测试中心（哈尔滨）测定，两年平均结果：蛋白质（干基）13.8%，湿面筋28.7%，吸水率62.6%，稳定时间10.6 min，拉伸面积75cm2，最大拉伸阻力399E.U.，硬度指数66.6。2017年检测粗蛋白（干基）14.3%，湿面筋29.4% ，吸水量62.6ml/100g，稳定时间13.5min，最大拉伸阻力477E.U.，拉伸面积81cm2，硬度指数66.7，达中强筋小麦品种标准。产量和抗性表现：2015-2017年度参加江苏省淮北组小麦区域试验，两年平均亩产597.8kg，比对照淮麦20增产6.7%。2017-2018年度参加生产试验平均亩产523.1公斤，比对照淮麦20增产5.5%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗12万-16万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮18公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (194, 1, '淮麦47', '苏审麦20190009', '2019.11', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所、 江苏省粮食作物现代产业技术协同创新中心', '太谷核不育基因组建的冬春性小麦轮回群体，参试名称“淮核15173”', '江苏省淮北麦区', '特征特性：属半冬性中熟小麦品种。幼苗半匍匐，叶色绿。分蘖力较强，抗寒性较好。株型松紧适宜，穗层整齐，穗大穗匀。穗纺锤形，长芒、白壳、白粒，籽粒角质，饱满度较好。区试平均结果：全生育期220.2天，成熟期与对照淮麦20相当。株高87.4厘米，每亩有效穗39.9万，每穗34粒，千粒重43.0克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：感赤霉病（单花滴注鉴定感赤霉病，严重度3.95、3.75；自然发病鉴定感赤霉病，病情指数6.6、33.0），高感白粉病、纹枯病、叶锈病，中感条锈病，中抗黄花叶病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业部谷物品质监督检验测试中心测定：容重821g/L、810g/L，蛋白质（干基）14.70%、14.99%，湿面筋31.6%、31.6%，吸水率62.5%、65.2%，稳定时间9.4min、4.5min，最大拉伸阻力544E.U.、232E.U.，拉伸面积95cm2、51cm2，硬度指数68.7、65.2。2017年检测结果达中强筋小麦品种标准。产量和抗性表现：2016-2018年度参加江苏省淮北组小麦品种区域试验，两年平均亩产539.93公斤，比对照淮麦20增产2.16%。2018-2019年度参加生产试验平均亩产576.18公斤，比对照淮麦20增产4.32%。', '1、适宜播期10月10日-20日。2、适期播种每亩基本苗15万-18万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮18公斤左右，配合施用磷、钾肥。氮肥基苗肥占50%，拔节孕穗肥占50%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (195, 1, '淮麦48', '苏审麦20200010', '2020.11', 0, '江苏省农作物品种审定委', '江苏徐淮地区淮阴农业科学研究所', '太谷核不育基因组建的冬春性小麦轮回群体，参试名称\n“淮核 16174”', '江苏省淮北麦区种植', '特征特性：半冬性小麦品种。幼苗半匍匐，叶短卷，浓绿色。分蘖力较强。起身拔节中等，抗寒、抗倒春寒能力较好。株型半松紧，抗倒 性一般。长相清秀，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒长 圆形、角质。区试平均结果:全生育期 226.4 天，与对照淮麦 20 相当。 株高 91.5 厘米，每亩有效穗 41.2 万，每穗 33.8 粒，千粒重 43.8 克。经 江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所 鉴定:感赤霉病(接种鉴定中感赤霉病，严重度 3.0、3.6;自然发病鉴 定感赤霉病，病指 28.7、1.3)，高抗条锈病，中感黄花叶病毒病，高感 白粉病、纹枯病、叶锈病。经江苏省农业科学院种质资源与生物技术研 究所鉴定:感穗发芽。经农业部谷物品质监督检验测试中心测定:容重 828g/L、835g/L，蛋白质(干基)15.9%、14.5%，湿面筋 31.2%、32.5%， 吸水率 59%、60%，稳定时间 13.0min、13.5min，最大拉伸阻力 453E.U.、 684E.U.，拉伸面积 89cm2、107cm2，硬度指数 63.1、61.7。2017-2018 年 度、2018-2019 年度品质指标分别达到中强筋、强筋小麦品种审定标准。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦 A 组区试，两年平 均亩产 575.5 公斤，比对照淮麦 20 增产 3.9%。2019-2020 年度参加生产 试验，平均亩产 572.9 公斤，比对照淮麦 20 增产 3.9%。', '1、适宜播期 10 月 20 日-30 日。2、适期播种每亩 基本苗 14 万-18 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施 纯氮 15 公斤左右，配合施用磷钾肥。其中氮肥基苗肥占 40%，拔节肥占40%，孕穗肥占 20%。拔节期可结合施用多效唑或壮丰安控制株高提高 群体质量。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间 杂草。注意防治纹枯病、赤霉病、白粉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (196, 1, '淮麦49', '苏审麦20200015', '2020.11', 0, '江苏省农作物品种审定委', '江苏徐淮地区淮阴农业科学研究所', '太谷核不育基因组建的冬春性小麦轮回群体，参试名称\n“淮核 16132”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，苗势较壮，分蘖力较强，冬季冻害轻，抗寒性较好。起身拔节快，两极分化快。苗脚利索。株型 较紧凑，旗叶宽长，内卷，上冲，穗层整齐，落黄好。穗长方形，长芒、 白壳、白粒，籽粒角质，饱满度较好。区试平均结果:全生育期 227.6 天，比对照淮麦 20 长 0.7 天。株高 91.6 厘米，每亩有效穗 40.7 万，每 穗 33.4 粒，千粒重 44.8 克。经江苏省农业科学院植物保护研究所、江苏 徐淮地区徐州农业科学研究所鉴定:中感赤霉病(接种鉴定中感赤霉病， 严重度 3.4、3.3;自然发病鉴定中感赤霉病，病指 11.9、2.8)，中感叶锈 病、条锈病、黄花叶病毒病，高感白粉病、纹枯病。经江苏省农业科学 院种质资源与生物技术研究所鉴定:高感穗发芽。经农业部谷物品质监 督检验测试中心测定:容重 830g/L、846g/L，蛋白质(干基)15.8%、14.0%， 湿面筋 31.2%、30.5%，吸水率 65%、61%，稳定时间 6.5min、11.4min， 最大拉伸阻力 287E.U.、689E.U.，拉伸面积 64cm2、107cm2，硬度指数 64.7、61.4。2018-2019 年度品质指标达到强筋小麦品种审定标准。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦 B 组区试，平均亩 产 549.9 公斤，比对照淮麦 20 增产 3.1%。2019-2020 年度参加生产试验，平均亩产 604.1 公斤，比对照淮麦 20 增产 5.3%。', '1、适宜播期为 10 月 15 日-25 日。2、适期播种每亩基本苗 12 万-16 万，推迟播种或肥力水平偏低适当增加。3、一般亩施纯 氮 15 公斤左右，配合施用磷钾肥。氮肥基苗肥占 40%，拔节肥占 50%， 孕穗肥占 10%。拔节期可结合施用多效唑或壮丰安控制株高提高群体质 量。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。 注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (197, 1, '淮麦50', '苏审麦20200016', '2020.11', 0, '江苏省农作物品种审定委', '江苏徐淮地区淮阴农业科学研究所', '淮麦 02295//淮麦 30/浚 99-7，参试名称“淮麦 610”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色深绿。分蘖力较强，抗寒性较好。株型松紧适中，穗层较整齐，抗倒性较好。拔节起身早， 熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒卵圆形、半角质。区试 平均结果:全生育期 226.6 天，与对照淮麦 20 相当。株高 83.5 厘米，每 亩有效穗 41.3 万，每穗 35.9 粒，千粒重 42.2 克。经江苏省农业科学院 植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定:感赤霉病(接 种鉴定感赤霉病，严重度 2.6、3.7;自然发病鉴定中感赤霉病，病指 24.8、 4.5)，中感条锈病，感黄花叶病毒病，高感纹枯病、白粉病、叶锈病。 经江苏省农业科学院种质资源与生物技术研究所鉴定:中抗穗发芽。经 农业部谷物品质监督检验测试中心测定:容重 830g/L、827g/L，蛋白质(干基)14.1%、13.7%，湿面筋 30.0%、30.6%，吸水率 59%、56%，稳 定时间 3.7min、2.7min，最大拉伸阻力 175E.U.、194E.U.，拉伸面积 46cm2、 49cm2，硬度指数 50.7、46.0。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦 B 组区试，两年平均 亩产 568.2 公斤，比对照淮麦 20 增产 6.6%。2019-2020 年度参加生产试 验，平均亩产 612.6 公斤，比对照淮麦 20 增产 6.7%。', '1、适宜播期 10 月 15 日-30 日。2、适期播种每亩基 本苗 14 万-18 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯 氮 18 公斤左右，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗肥占 40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防 涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、 白粉病、叶锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (198, 1, '淮麦55', '苏审麦20200029', '2020.11', 0, '江苏省农作物品种审定委', '江苏天丰种业有限公司、江苏徐淮地区淮阴农业科学研 究所', '淮麦 22//西农 953//豫麦 13/淮麦 18，参试名称“淮麦 1558”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿，分蘖力强，抗 寒性好。株型较紧凑，穗层整齐，抗倒性较好，熟相好。穗纺锤型，长 芒、白壳、白粒，结实性好，籽粒半角质，饱满度好。区试平均结果: 全生育期 222 天，比对照淮麦 20 短 1.9 天。株高 80.4 厘米，每亩有效穗 40.5 万，每穗 38.3 粒，千粒重 42.2 克。经江苏省农业科学院植物保护研 究所、江苏徐淮地区徐州农业科学研究所鉴定:感赤霉病(接种鉴定中 感赤霉病，严重度 3.1、2.1;自然发病鉴定感赤霉病，病指 35.7、3.9)， 中感条锈病、黄花叶病毒病，高感白粉病、纹枯病、叶锈病。经江苏省 农业科学院种质资源与生物技术研究所鉴定:高感穗发芽。经农业部谷 物品质监督检验测试中心测定:容重 778.9g/L、763.8g/L，蛋白质(干基)14.7%、15.0%，湿面筋 30.5%、30.9%，吸水率 58%、52%，稳定时间 8.8min、11.2min，最大拉伸阻力 358E.U.、512E.U.，拉伸面 83cm2、88cm2， 硬度指数 40.5、40.5。2017-2018 年度品质指标达到中强筋小麦品种审定 标准。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦江苏大华科企联合体 区试，两年平均亩产 552.0 公斤，比对照淮麦 20 增产 3.7%。2019-2020 年度参加生产试验，平均亩产 604.4 公斤，比对照淮麦 20 增产 8.2%。', '1、适宜播期 10 月 15 日-25 日。2、适期播种每亩基 本苗 18 万-20 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯 氮 18 公斤左右，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗肥占 40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防 涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、 白粉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (199, 1, '淮麦60', '苏审麦20220032', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏天丰种业有限公司、江苏徐淮地区淮阴农业科学研究所', '淮麦304//洛麦23/淮麦510', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半直立，分蘖性较强，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒半角质。联合体区域试验平均结果：全生育期226.1天，比对照淮麦20短0.5天，株高90.8厘米，每亩有效穗42.2万，每穗34.8粒，千粒重45.6克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：感赤霉病（接种鉴定感赤霉病，严重度3.00、3.75；自然发病鉴定中感赤霉病，病指1.06、12.86），高感白粉病、叶锈病，感纹枯病，中感条锈病，抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重811g/L、826g/L，粗蛋白质含量（干基）13.8%、14.5%，湿面筋含量30.2%、31.9%，吸水率64%、62%，稳定时间5.0min、3.7min，最大拉伸阻力198E.U.、166E.U.，拉伸面积44cm2、36cm2，硬度指数63.9、67.0。产量和抗性表现：2019-2021年度参加江苏大华种业科企淮北小麦联合体区域试验，两年平均亩产566.6公斤，比对照淮麦20增产3.7%。2021-2022年度参加生产试验，平均亩产606.2公斤，比对照淮麦20增产4.4%。', '1、适宜播期10月15日至25日。2、基本苗适期播种每亩18万-20万，推迟播种或中低产田适当增加。3、一般亩施纯氮18公斤左右，其中基苗肥占65%、拔节孕穗肥占35%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (200, 1, '淮麦608', '苏审麦20200012', '2020.11', 0, '江苏省农作物品种审定委', '江苏徐淮地区淮阴农业科学研究所', '淮麦 28//淮麦 28/淮麦 18，参试名称“淮麦 608”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿。分蘖力较强，抗寒性较好。株型较紧凑，穗层不整齐，抗倒性较好。拔节起身慢，两 极分化快，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒卵圆形、角 质。区试平均结果:全生育期 226.1 天，与对照淮麦 20 相当。株高 85.1 厘米，每亩有效穗 40.4 万，每穗 36.5 粒，千粒重 42.6 克。经江苏省农 业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定:感 赤霉病(接种鉴定中感赤霉病，严重度 3.3、2.5;自然发病鉴定感赤霉 病，病指 25.4、8.2)，中感条锈病，感黄花叶病毒病，高感白粉病、纹枯病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定: 高感穗发芽。经农业部谷物品质监督检验测试中心测定:容重 820g/L、 821g/L，蛋白质(干基)15.5%、15.1%，湿面筋 31.9%、31.1%，吸水率 58%、57%，稳定时间 6.8min、6.4min，最大拉伸阻力 305E.U.、370E.U.， 拉伸面积 60cm2、75cm2，硬度指数 53.1、45.7。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦 A 组区试，两年平均 亩产 578.7 公斤，比对照淮麦 20 增产 4.5%。2019-2020 年度参加生产试 验，平均亩产 587.5 公斤，比对照淮麦 20 增产 6.5%。', '1、适宜播期 10 月 10 日-25 日。2、适期播种每亩基 本苗 14 万-18 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯 氮 18 公斤左右，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗肥占 40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防 涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、 白粉病、叶锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (201, 1, '淮麦66', '苏审麦20210024', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所、淮阴师范学院', '淮麦33//洛麦21/淮麦04520，参试名称“淮麦705”', '江苏省淮北麦区', '特征特性：半冬性早熟小麦品种。幼苗半匍匐，叶色深绿，抗寒性较好。春季起身拔节早，分蘖力较强，茎秆弹性好，抗倒性较好。株型较紧凑，穂层整齐，蜡质重，剑叶中等、挺，灌浆较快，结实性较好，熟相好。穗纺锤形，长芒、白壳、白粒，籽粒角质。区试平均结果：全生育期227.7天，比对照淮麦20短2.5天。株高86.2厘米，每亩有效穗42.8万，每穗34.0粒，千粒重43.9克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度3.23、1.6、3.05；自然发病鉴定中感赤霉病，病指4.08、3.8、8.46），中抗黄花叶病，中感条锈病，高感纹枯病、白粉病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：感穗发芽。经农业部谷物品质监督检验测试中心测定：容重846g/L，蛋白质（干基）15.6%、16.5%，湿面筋含量35.6%、33.5%，吸水率60.2%、63.7%，稳定时间18.9min、11.5min，最大拉伸阻力784E.U.、694E.U.，拉伸面积145cm2、134cm2，硬度指数64.2、61.5。2018-2019年度、2019-2020年度品质指标均达强筋小麦品种审定标准。产量和抗性表现：2018-2020年度参加江苏省淮北小麦徐州农科所科企联合体区试，两年平均亩产582.0公斤，比对照淮麦20增产5.0%。2020-2021年度参加生产试验，平均亩产568.1公斤，比对照淮麦20增产4.2%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗14万-18万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯氮15-18公斤，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。及时防治纹枯病、赤霉病、白粉病、叶锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (202, 1, '淮麦894', '苏种审字第227号', '1994', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农科所', 'C172//高38/黔丰1号', '江苏淮北麦区南部', '退出批次：特征特性：幼苗偏直立，繁茂性好。株型较松散，植株偏高，株高95厘米左右，茎秆较粗，弹性一般，抗倒性中等。叶片披垂，分蘖力中等成穗率较高，亩有效穗41万左右，比徐州21多3.9万穗.穗层整齐。长芒、白壳、白粒、穗长方形，每穗实粒29粒左右，籽粒角质饱满期，商品性好，粒重稳定，千粒重41克左右，在黄淮大区及省区试中，千粒重分别比徐州21高5克和1.1克。品质测试结果：粗蛋白含量15.5%，湿面筋含量46.7%，干面筋含量14.8%，面团形成时间、稳定时间分别为2.2、2分钟，拉伸阻力220BΜ，延伸性12.0cm，拉伸比值1.83，曲线面积38.2，粉质综合评价值为36分。粗蛋白及面筋含量较高。全生育期235天左右，比徐州21早熟3天以上。早熟稳定，耐干热风，熟相好。经省农科院植保所接种鉴定：对白粉病表现高抗至免疫（经接种鉴定：反应型0—1，严重度0—5，病级0—1），省区试中淮阴894仅一个试点轻微发病，严重度一级，徐州21发病2点，严重度3度，经省院植保所病毒室鉴定，高抗梭条花叶病毒病（以省内外18个病源分离物接种鉴定结果，对其中16个毒源表现高抗，发病率为0—5%，2个毒源表现中抗至抗，发病率为10—20%）。抗穗发芽。但植株偏高，抗倒性，抗寒性一般。产量和抗性表现：1991年至1993年连续两年参加省淮北小麦品种区域试验。平均单产分别为413.7公斤和424.1公斤，分别比冀84—5418（半冬性品种）减产11.3%和增产2%;两年平均单产为418.9公斤，比冀84—5418减产4.6%。减产原因主要是北部几个点播种早，冻害偏重，在黄淮大区春水组适期播种的情况下，两年平均单产为422.9公斤，比同类型品咱徐州21增产4.4%，1994年参加淮北水上麦生产试验，平均单产378.1公斤，比徐州21增产2.72%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (203, 1, '淮麦919', '苏审麦20220034', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏省金地种业科技有限公司、江苏黄淮种业有限公司', '西农2208/烟农19', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿。分蘖力较强，成穗数较多。株型半紧凑，穗层整齐，熟相较好。纺锤型穗，长芒、白壳、白粒，籽粒半角质。联合体区域试验平均结果：全生育期平均226.4天，与对照淮麦20相当。株高80.4厘米，每亩有效穗41.7万，穗粒数36.0粒，千粒重46.4克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度2.68、2.25；自然发病鉴定中感赤霉病，病指3.87、9.60），高感纹枯病、白粉病、叶锈病,中感黄花叶病毒病、条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重793/L、825g/L，粗蛋白质含量（干基）15.5%、14.05%，湿面筋含量42.2%、34.9%，吸水率63%、63%，稳定时间4.5min、3.4min，最大拉伸阻力233E.U.、132E.U.，拉伸面积60cm2、33cm2，硬度指数61.2、66.4。产量和抗性表现：2018-2020年度参加江苏大华种业科企淮北小麦联合体区域试验，两年平均亩产577.8公斤，比对照淮麦20增产3.3%。2020-2021年度参加生产试验，平均亩产588.4公斤，比对照淮麦20增产5.3%。', '1、适宜播期10月15日至25日。2、基本苗适期播种每亩15万-20万，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤左右，基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (204, 1, '淮麦920', '苏审麦20170009', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏省金地种业科技有限公司', '郑麦9023（选系）/ H1120，参试名称“金地1120”', '江苏省沿淮麦区及淮北麦区晚茬口', '特征特性：半冬性中熟品种。成熟期与对照淮麦20相当。幼苗半匍匐，叶色深绿，抗寒性较好。株型较紧凑，剑叶上举，茎秆弹性较好。分蘖力强，成穗数较多。穗纺锤型，长芒、白壳、白粒，籽粒角质，饱满度较好。区试平均结果：全生育期216.5天，株高81.7厘米，每亩有效穗41.6万，每穗34.1粒，千粒重41.6克。病害鉴定：中抗赤霉病（严重度2.2-2.42），高感纹枯病、白粉病、叶锈病。经江苏省农科院粮作所鉴定：高感穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：粗蛋白（干基）13.9%，湿面筋30.2%，吸水量61ml/100g，稳定时间7.0分钟，最大拉伸阻力320（Rm,135E.U），拉伸面积65cm2 。产量和抗性表现：2014-2016年度参加江苏省淮北晚播组小麦区域试验，两年平均亩产539.2公斤，2014-2015年较对照淮麦20增产7.3%， 2015-2016年较对照淮麦30增产14.0%。2016-2017年度参加生产试验，平均亩产540.5公斤，较对照淮麦30增产3.5%。', '1、适宜播期为10月20日-11月5日。2、一般每亩基本苗18万-22万，肥力水平偏低或播期推迟，应适当增加。3、一般亩施纯氮16公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病、叶锈和蚜虫等病虫害。5、沿淮小麦穗发芽多发地区慎重种植。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (205, 1, '烟85-722', '苏种审字第247号', '1996', 0, '江苏省农作物品种审定委员会', '江苏省种子站  盐城市种子站', '烟79214/烟791604', '江苏淮北麦区', '退出批次：特征特性：幼苗匍匐，叶细窄偏长，叶色深绿，越冬性好。幼苗生长稳健，发育进程偏缓。株高87.5厘米，株型紧凑，根系发达，活力强，活熟到老，茎杆和基部切间壁厚且充实度好，茎部节间短，茎杆附明显蜡粉，强熟好，耐肥抗倒。叶短挺上举，透光性好，叶色绿，春发性欠佳，拔节时起秆一致，苗脚利落，亩不效穗40—45万。穗纺锤形，长芒、白壳、白粒。穗稍短着粒较疏，结实性较好，每穗28粒左右。灌浆速度，籽粒卵圆形，偏角质，腹沟偏宽，千粒重42.0—44.2克，品质较好，测定结果；沉降值26ml，面团稳定时间达6.2分钟，衰减度85B.Μ，粉质评价值49分，面团拉伸阻力325B.Μ，延伸性117mm，曲线面积52.5平方厘米，拉伸比2.78B/Μmm，与冀84—5418相比，沉降值低3.0ml，面团稳定时间长3.2分钟，衰减度低35B/Μ，面团拉伸阴力高120B.Μ，延伸性长7mm，拉伸比高0.89B.Μ/mm。曲线面积大18.5平方厘米，面团弱性好，筋力较强，更适于蒸成烧烤，粉质评价值高2分，面筋质量和加工品质均好于冀84—5418。全生育期240天左右，比冀84—5418迟3天左右，丰产稳产，综合抗性较好，抗寒性、抗旱性较突出。耐十风，熟相好，参加省区域两年中，冬季偏暖，倒春性较重，后期干旱高温，不明显干热风的不利于气候条件下，该品种基本无冻害和青枯逼熟现象。经江苏、山东省农科院植保和徐州市农科所鉴定结果；高抗梭条花叶病毒病、土传花叶病和白粉病，中抗条锈病，但熟相偏晚。中感叶锈病，感赤霉病，不抗扩展，感纹枯病。籽粒腹沟较宽。产量和抗性表现：1994—1995年参加淮北片小麦新品种区域试验，两年平均单产分别为421.39公斤和465.08公斤，均居首位，分别经冀84—5418增产3.77%（不显著）和12.1%（极显著）。1994—1995年参加省生产试验，平均单产426.5公斤，经冀84—5418增产11.4%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (206, 1, '烟农19', '苏审麦200102', '2001', 0, '江苏省农作物品种审定委员会', '山东烟台市农科所', '连云港农科所引进', '江苏淮北麦区', '退出批次：特征特性：该品种幼苗半匍匐，叶色深绿，叶片窄长。分蘖性较强，成穗率较高。株高90 厘米左右，株型紧凑。茎秆弹性一般。该品种亩有效穗42万左右，每穗粒数32粒左右，千粒重43克。长芒、白壳、白皮、纺锤型穗，小穗排列较紧，结实性较好。该品种中感赤霉病、白粉病、纹枯病，感叶锈。该品种容重775克/升，蛋白质含量13.87 %，湿面筋含量为37.60 %，沉降值为36毫升，降落值为361秒，吸水率为61.80%，面团稳定时间为11.50分钟，粉质评价值59分（南京经济学院粮油检测中心，2000年）。产量和抗性表现：该品种1999-2001年度参加江苏省淮北小麦中间试验。1999-2000年度省区试平均亩产478.94公斤，比对照陕229增产9.53%，比第二对照徐州25号增产7.88%，增产均达极显著水平；2000-2001年度省区试平均亩产520.39公斤，比对照陕229增产13.70%，增产极显著；2000-2001年度参加省淮北小麦生产试验，平均亩产505.50公斤，比对照陕229增产12.30%。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (207, 1, '烟辐188', '苏审麦200202', '2002', 0, '江苏省农作物品种审定委员会', '山东烟台市农科所', '徐州种子站引进', '江苏徐州及相同生态区', '退出批次：特征特性：该品种籽粒白色、半角质，幼苗半葡伏，苗壮，分蘖性较强，成穗率低，茎杆粗壮，剑叶宽大，株高85厘米左右；每亩穗数23万左右，每穗粒数45粒左右，千粒重45克左右，容重800克左右，大穗大粒，籽粒商品性好，成熟期与陕229相当，中抗白粉病、叶锈病，中感条锈病，但严重度和普遍率均较低，中感纹枯病，抗倒性好，成熟时炸芒，熟相一般。据2000年10月省区试统一送样品质分析（南京经济学院），粗蛋白含量16.03%，湿面筋36.3％，干面筋12.6％，沉降值42ml，吸水率58.6%，面团形成时间3.9min，面团稳定时间8.0min，粉质评价值55分(同年对照陕229为52分)，属中强筋品种。产量和抗性表现：1999-2001年参加省区域试验，1999-2000年平均亩产434.82公斤，较对照陕229减产0.56％，不显著，较徐州25号减产2.06％，差异显著，列第12位；2000-2001年平均亩产434.82公斤，较对照陕229减产0.60％，不显著，居第11位。2001-2002年度委托徐州市组织生产试验，平均亩产462.3公斤，较对照陕229增产15.5%。该品种在徐州生态类型地区有较好的区域适应性。', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (208, 1, '瑞华麦506', '苏审麦20190010', '2019.11', 0, '江苏省农作物品种审定委员会', '江苏瑞华农业科技有限公司', '明麦2号/矮抗58，参试名称“瑞友1506”', '江苏省淮北麦区', '特征特性：属半冬性中熟小麦品种。幼苗半匍匐，叶色绿。分蘖力较强，抗寒性较好。株型较紧凑，穗层整齐，抗倒性较好。拔节起身中等，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒长圆形，硬质。区试平均结果：全生育期220.0天，成熟期与对照淮麦20相当。株高83.5厘米，每亩有效穗41.8万，每穗34粒，千粒重42.3克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：感赤霉病（单花滴注鉴定感赤霉病，严重度3.84、3.27；自然发病鉴定中感赤霉病，病情指数7.0、12.8），高感白粉病，中感纹枯病，中抗叶锈病，高抗条锈病、黄花叶病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。品质经农业部谷物品质监督检验测试中心测定：容重838g/L、817g/L，蛋白质（干基）14.93%、16.20%，湿面筋31.7%、33.4%，吸水率60.1%、60.7%，稳定时间17.9min、13.7min，最大拉伸阻力474E.U.、486E.U.，拉伸面积77cm2、90cm2，硬度指数64.1、60.0。2018年检测结果达中强筋小麦品种标准。产量和抗性表现：2016-2018年度参加江苏省淮北组小麦品种区域试验，两年平均亩产544.91公斤，比对照淮麦20增产3.10%。2018-2019年度参加生产试验平均亩产588.67公斤，比对照淮麦20增产6.58%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗12万-16万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮18公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (209, 1, '瑞华麦511', '苏审麦20220013', '2023.01', 0, '江苏省农作物品种审定委员会', '安徽科技学院、江苏瑞华农业科技有限公司', '瑞华麦520/西农511', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色深绿。分蘖力较强，株型较松散，穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒角质。省区域试验平均结果：全生育期227.3天，比对照淮麦20短0.5天，株高89.1厘米，每亩有效穗43.2万，每穗34.0粒，千粒重44.5克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度2.80、3.22；自然发病鉴定中感赤霉病，病指2.31、16.80），高感叶锈病、白粉病，感纹枯病，中感条锈病，中抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重825g/L、829g/L，粗蛋白质含量（干基）13.1%、14.2%，湿面筋含量27.1%、29.6%，吸水率57%、57%，稳定时间8.4min、6.5min，最大拉伸阻力364E.U.、350E.U.，拉伸面积57cm2、61cm2，硬度指数52.7、54.2。产量和抗性表现：2019-2021年度参加江苏省淮北A组小麦品种区域试验，两年平均亩产607.2公斤，比对照淮麦20增产7.0%。2021-2022年度参加生产试验，平均亩产626.5公斤，比对照淮麦20增产6.3%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩14万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮15公斤左右，其中氮肥基苗肥占40%、拔节肥占40%、孕穗肥占20%，同时配合施用磷钾肥，后期适当喷施叶面肥。注意化控控高、防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (210, 1, '瑞华麦520', '苏审麦201406', '2014', 0, '江苏省农作物品种审定委员会', '江苏瑞华农业科技有限公司', '郑州891/黔丰1号', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶色深绿，分蘖力强抗寒性中等株型较紧凑，抗倒性较好后期熟相较好穗纺锤形，长芒、白壳、白粒，籽粒椭圆形、硬质区试平均结果：全生育期233.4天，较对照淮麦20迟熟近1天；株高83.3厘米，每亩有效穗41.6万，每穗32.7粒，千粒重40.6克抗病性经江苏省农科院植保所2010-2012年接种鉴定：感赤霉病、白粉病，中感纹枯病，中抗小麦黄花叶病毒病品质经农业部谷物品质监督检验测试中心测定，2010-2012年度两年平均结果：容重838克/升，粗蛋白含量13.6%，湿面筋含量27.8%，稳定时间9.5分钟，硬度指数63.2产量和抗性表现：2010-2012年度参加江苏省淮北组小麦区域试验，两年平均亩产528.1公斤，较对照淮麦20增产5.5%，两年增产均达极显著水平2012-2013年度参加生产试验，平均亩产521.6公斤，较对照淮麦20增产4.3%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (211, 1, '瑞华麦521', '苏审麦20170008', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏瑞华农业科技有限公司', '郑麦9023/偃展4110，参试名称“瑞友315”', '江苏省沿淮麦区及淮北麦区晚茬口', '特征特性：半冬性中熟品种。成熟期与对照品种淮麦20相当。幼苗半匍匐，叶片细长，叶色深绿，前期长势慢，抗寒性较好。分蘖力强，成穗数较多。株型较松散，剑叶挺，茎杆弹性较好。穗纺锤型，穗长码稀，长芒、白壳、白粒，籽粒角质。区试平均结果：全生育期216.7天，株高83.8厘米，每亩有效穗41.0万，每穗35.5粒，千粒重40.5克。落黄晚，熟相较好。病害鉴定：中感赤霉病（2.35-2.94），感纹枯病，高感白粉病，高感叶锈病。经江苏省农科院粮作所鉴定：高感穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：粗蛋白（干基）13.7%，湿面筋29.3% ，吸水量59.0ml/100g，稳定时间9.1分钟，最大拉伸阻力335（Rm,135 E.U），拉伸面积66cm2。产量和抗性表现：2014-2016年度参加江苏省淮北晚播组小麦区域试验，两年平均亩产534.5公斤，2014-2015年较对照淮麦20增产9.0%，2015-2016年较对照淮麦30增产10.4%。2016-2017年度参加生产试验，平均亩产555.7公斤，较对照淮麦30增产6.4%。', '1、适宜播期为10月20日-11月5日。2、一般每亩基本苗18万-22万，肥力水平偏低或播期推迟，应适当增加。3、一般亩施纯氮16公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。5、沿淮小麦穗发芽多发地区慎重种植。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (212, 1, '瑞华麦523', '苏审麦201407', '2014', 0, '江苏省农作物品种审定委员会', '江苏瑞华农业科技有限公司', '郑麦9023/烟1604', '适宜江苏省沿淮麦区种植', '退出批次：特征特性：幼苗半匍匐，分蘖力较强冬季抗寒性一般，春季抗倒春寒能力一般株型较紧凑，抗倒性较好，熟相较好穗纺锤形，长芒、白壳、白粒，籽粒硬质区试平均结果：全生育期219.6天，较对照郑麦9023迟熟2天，比淮麦20早熟2天；株高79.0厘米，每亩有效穗41.7万，每穗29.2粒，千粒重41.0克抗病性经江苏省农科院植保所2011-2013年接种鉴定：感赤霉病，中感纹枯病、白粉病，感小麦黄花叶病毒病，感穗发芽品质经农业部谷物品质监督检验测试中心测定，2011-2013年度两年平均结果：容重803.0克/升，粗蛋白含量15.6%，湿面筋含量34.9%，稳定时间6.4分钟，硬度指数68.1产量和抗性表现：2011-2013年度参加江苏省淮北迟播组小麦区域试验，两年平均亩产475.3公斤，较对照郑麦9023增产8.2%，两年增产均达极水平；较对照淮麦20增产4.8%，其中1年增产极显著，1年增产显著2013-2014年度参加生产试验，平均亩产560.2公斤，较对照淮麦20增产6.0%', '', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (213, 1, '瑞华麦528', '苏审麦20200021', '2020.11', 0, '江苏省农作物品种审定委', '江苏瑞华农业科技有限公司', '周麦 18/烟农 19，参试名称“瑞华 14040”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶片较宽大，叶色深绿。分蘖力较强，抗寒性一般。株型较紧凑，穗层较整齐，抗倒性一般。拔 节抽穗早，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒椭圆形、半 角质-角质。区试平均结果:全生育期 225.7 天，比对照淮麦 20 短 0.5 天。 株高 91.4 厘米，每亩有效穗 40.1 万，每穗 38.1 粒，千粒重 42.4 克。经 江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所 鉴定:感赤霉病(接种鉴定感赤霉病，严重度 2.4、3.8;自然发病鉴定 中感赤霉病，2017 年病指 7.6)，高抗条锈病，高感白粉病、纹枯病、叶 锈病、黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所 鉴定:高感穗发芽。经农业部谷物品质监督检验测试中心测定:容重 830g/L、826g/L，蛋白质(干基)14.0%、14.0%，湿面筋 27.6%、23.9%， 吸水率 55%、54%，稳定时间 5.2min、12.8min，最大拉伸阻力 280E.U.、 507E.U.，拉伸面积 54cm2、77cm2，硬度指数 52.5、52.6。产量和抗性表现：2015-2017 年度参加江苏省淮北小麦 B 组区试，两年平均亩产 587.3 公斤，比对照淮麦 20 增产 4.8%。2017-2018 年度参加生产 试验，平均亩产 522.0 公斤，比对照淮麦 20 增产 5.3%。', '1、适宜播期 10 月 10 日-25 日。2、适期播种每亩基 本苗 12 万-16 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯 氮 18 公斤左右，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗肥占 40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防 涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、 白粉病、叶锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (214, 1, '瑞华麦549', '苏审麦20200018', '2020.11', 0, '江苏省农作物品种审定委', '江苏瑞华农业科技有限公司', '瑞华麦 520/周麦 16，参试名称“瑞华 549”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿。分蘖力强，抗寒性较好。株型较松散，穗层较整齐，抗倒性较好。熟相好。穗纺锤形， 长芒、白壳、白粒，籽粒长圆形、角质。区试平均结果:全生育期 227.6天，与对照淮麦 20 相当。株高 86.0 厘米，每亩有效穗 41.4 万，每穗 36.3 粒，千粒重 41.5 克。经江苏省农业科学院植物保护研究所、江苏徐淮地 区徐州农业科学研究所鉴定:中感赤霉病(接种鉴定中感赤霉病，严重 度 3.3、3.5;自然发病鉴定中感赤霉病，病指 10.1、0.8)，中抗黄花叶病， 中感条锈病，高感白粉病、纹枯病、叶锈病。经江苏省农业科学院种质 资源与生物技术研究所鉴定:感穗发芽。经农业部谷物品质监督检验测 试中心测定:容重 830g/L、832g/L，蛋白质(干基)14.1%、14.1%，湿 面筋 31.7%、33.8%，吸水率 63%、60%，稳定时间 3.5min、6.5min，最 大拉伸阻力 218E.U.、329E.U.，拉伸面积 49cm2、57cm2，硬度指数 64.2、 64.1。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦 B 组区试，两年平均 亩产 562.2 公斤，比对照淮麦 20 增产 5.5%。2019-2020 年度参加生产试 验，平均亩产 618.3 公斤，比对照淮麦 20 增产 7.7%。', '1、适宜播期 10 月 10 日-25 日。2、适期播种每亩基 本苗 12 万-16 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯 氮 18 公斤左右，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗肥占 40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防 涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、 白粉病、叶锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (215, 1, '瑞华麦563', '苏审麦20210025', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏瑞华农业科技有限公司', '淮麦36/周麦22，参试名称“瑞华563”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿，抗寒性较好，拔节起身较早，分蘖力中等。株型较紧凑，蜡质重，茎秆粗壮，抗倒性较好，剑叶细长、挺，穗层较整齐，灌浆快，结实性较好，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒半角质-角质。区试平均结果：全生育期228.6天，比对照淮麦20短1.6天。株高87.5厘米，每亩有效穗41.4万，每穗34.7粒，千粒重46.1克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度3.14、1.35、2.6；自然发病鉴定中感赤霉病，病指0、2.9、11.1），中感条锈病、黄花叶病毒病，高感纹枯病、白粉病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：感穗发芽。经农业部谷物品质监督检验测试中心测定：容重829g/L，蛋白质（干基）15.7%、15.0%，湿面筋含量31.7%、31.2%，吸水率53.3%、58.9%，稳定时间7.1min、3.9min，最大拉伸阻力467E.U.，拉伸面积77cm2，硬度指数45.0、46.7。产量和抗性表现：2018-2020年度参加江苏省淮北小麦徐州农科所科企联合体区试，两年平均亩产575.8公斤，比对照淮麦20增产3.9%。2020-2021年度参加生产试验，平均亩产569.3公斤，比对照淮麦20增产4.4%。', '1、适宜播期10月5日-25日。2、适期播种每亩基本苗14万-18万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯氮15-18公斤，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。及时防治纹枯病、赤霉病、白粉病、叶锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:26', '2025-07-22 09:41:26');
INSERT INTO `ld_crop_variety` VALUES (216, 1, '瑞华麦566', '苏审麦20200026', '2020.11', 0, '江苏省农作物品种审定委', '江苏瑞华农业科技有限公司', '扬麦 158/郑麦 9023，参试名称“瑞华 566”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色中等，分蘖力强。株型较松散，抗倒性一般。穗层整齐，熟相较好。穗纺锤形，长芒、白壳、 红粒，籽粒粉质-半角质。区试平均结果:全生育期 201.6 天，比对照扬 麦 20 短 1.5 天。株高 84.3 厘米，每亩有效穗 31.7 万，每穗 40.6 粒，千 粒重 42.2 克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州 农业科学研究所鉴定:中抗赤霉病(接种鉴定中抗赤霉病，严重度 1.5、 2.5;自然发病鉴定中抗赤霉病，病指 2.8、0.0)，中感黄花叶病毒病，高 感纹枯病、白粉病、条锈病、叶锈病。经江苏省农业科学院种质资源与 生物研究所鉴定:高抗穗发芽。经农业部谷物品质监督检验测试中心测 定:容重 802g/L、758g/L，粗蛋白(干基)16.4%、14.0%，湿面筋 33.9%、 32.8%，吸水率 61%、62%，稳定时间 3.1min、2.0min，最大拉伸阻力 170E.U.、108E.U.，拉伸面积 45cm2、29cm2，硬度指数 54.0、52.0。产量和抗性表现：2017-2019 年度参加江苏省淮南小麦里下河农科所科企联 合体区试，两年平均亩产 498.8 公斤，比对照扬麦 20 增产 4.0%。2019-2020 年度参加生产试验，平均亩产 496.4 公斤，比对照扬麦 20 增产 2.3%。', '1、适宜播期 10 月 25 日至 11 月 5 日。2、适期播种 每亩基本苗 16 万左右，中低产田适当增加。3、一般亩施纯氮 18 公斤， 其中基苗肥占 60%、拔节孕穗肥占 40%，同时配合施用磷钾肥，后期适 当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、锈病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (217, 1, '瑞华麦595', '苏审麦20220023', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏瑞华农业科技有限公司', '瑞华麦523/扬麦11', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，叶色深绿，分蘖力较强。株型较松散，穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒角质。联合体区域试验平均结果：全生育期205.0天，比对照扬麦20短0.9天，株高89.2厘米，每亩有效穗31.4万，每穗38.7粒，千粒重44.5克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.55、2.32；自然发病鉴定中抗赤霉病，病指1.51、6.65），高感白粉病、叶锈病，感纹枯病，中抗黄花叶病毒病，高抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重776g/L、790g/L，粗蛋白质含量（干基）14.6%、16.4%，湿面筋含量34.5%、35.0%，吸水率62%、65%，稳定时间11.8min、7.5min，最大拉伸阻力591E.U.、514E.U.，拉伸面积146cm2、115cm2，硬度指数65.2、64.9。2020年、2021年品质检测结果分别达到强筋、中强筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮南小麦里下河农科所科企联合体区域试验，两年平均亩产502.8公斤，比对照扬麦20增产3.0%。2021-2022年度参加生产试验，平均亩产563.7公斤，比对照扬麦20增产4.2%。', '1、适宜播期10月25日至11月5日。2、基本苗适期播种每亩16万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮18公斤左右，其中基苗肥占65%、拔节孕穗肥占35%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (218, 1, '瑞华麦596', '苏审麦20190005', '2019.11', 0, '江苏省农作物品种审定委员会', '江苏瑞华农业科技有限公司', '镇麦10号/扬麦20，参试名称“瑞华596”', '江苏省淮南麦区', '特征特性：属春性中早熟小麦品种。幼苗直立，叶色绿。分蘖力中等，抗寒性较好。株型较松散，穗层整齐，抗倒性较好。拔节起身早，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒长圆形，硬质。区试平均结果：全生育期200.1天，比对照扬麦20早熟2.3天。株高78.5厘米，每亩有效穗31.8万，每穗36粒，千粒重45.1克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（单花滴注鉴定中抗赤霉病，严重度2.65、2.35；自然发病鉴定中抗赤霉病，病情指数0.4、3.17），高感白粉病、纹枯病，中抗黄花叶病、叶锈病，高抗条锈病。经江苏省农科院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重808g/L、806g/L，蛋白质（干基）15.68%、15.52%，湿面筋34.8%、31.5%，吸水率67.2%、67.1%，稳定时间9.8min、3.7min，最大拉伸阻力512E.U.、271E.U.，拉伸面积108cm2、71cm2，硬度指数66.8、62.2。2017年检测结果达中强筋小麦品种标准。产量和抗性表现：2016-2018年度参加江苏省淮南组小麦品种区域试验，两年平均亩产476.10公斤，比对照扬麦20增产0.04%。2018-2019年度参加生产试验平均亩产519.27公斤，比对照扬麦20增产3.72%。', '1、适宜播期10月25日至11月10日。2、适期播种每亩基本苗15万左右，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮18公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (219, 1, '瑞华麦598', '苏审麦20210008', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏瑞华农业科技有限公司', '扬麦20/镇08178，参试名称“瑞华569”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗半直立，叶色中等，分蘖力较强。株型半紧凑，抗倒性好。穗层较整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒角质。区试平均结果：全生育期209.4天，比对照扬麦20短1.8天。株高85.2厘米，每亩有效穗32.0万，每穗37.2粒，千粒重47.6克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.67、2.20、2.43；自然发病鉴定中抗赤霉病，病指0.75、0.84、5.4），中感黄花叶病毒病，高感纹枯病、白粉病、叶锈病、条锈病。经江苏省农业科学院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重799g/L、784g/L，粗蛋白(干基)含量14.00%、14.94%，湿面筋含量31.5%、33.5%，吸水率65.3%、64.2%，稳定时间9.4min、15.8min，最大拉伸阻力562E.U.、690E.U.，拉伸面积102cm2、131cm2，硬度指数67.4、67.4。2018-2019年度、2019-2020年度品质指标分别达中强筋、强筋小麦品种审定标准。产量和抗性表现：2018-2020年度参加江苏省淮南小麦B组区试，两年平均亩产519.9公斤，比对照扬麦20增产5.0%。2020-2021年度参加生产试验，平均亩产470.6公斤，比对照扬麦20增产5.7%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗16万左右，中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (220, 1, '生抗2号', '苏种审字第382号', '2000', 0, '江苏省农作物品种审定委员会', '江苏省农科院遗传所', 'Alondra/凡60096', '江苏淮南麦区', '退出批次：特征特性：该品种幼苗半直立，叶色淡绿，叶片较宽。分蘖性强，成穗率较高。株高95厘米左右，株型紧凑，耐肥抗倒性一般。该品种亩有效穗30万左右，每穗粒数36粒左右，千粒重37克左右。长芒、白壳、纺锤型穗，穗形较大，籽粒红色。该品种中抗赤霉病，中感白粉病，中感—中抗纹枯病，中感一中抗梭条花叶病毒病。该品种容重748克/升，蛋白质含量14.6％，湿面筋含量35.60％，沉降值61毫升，降落值365秒，吸水率62.2％，面团形成时间3.0分钟，稳定时间4.7分钟，断裂时间6.0分钟，综合评价值48分（南京经济学院粮油质检中心，1999年），属中筋力小麦品种。该品种丰产、稳产性较好，全生育期为209天左右，后期熟相一般。产量和抗性表现：该品种1997-2000年度参加江苏省淮南小麦中间试验。1997—1998年度省区试平均亩产273.30公斤，比对照扬麦158增产3.94％，达极显著水平；1998—1999年度省区试平均亩产374.12公斤，比对照增产0.98％，增产不显著；1999—2000年度参加省淮南小麦生产试验，平均亩产425.57公斤，比对照扬麦158增产4.27％。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (221, 1, '生选3号', '苏审麦200206', '2002', 0, '江苏省农作物品种审定委员会', '江苏省农科院遗传所   里下河所', '扬麦158诱变', '江苏淮南麦区', '退出批次：特征特性：该品种于2001-2002年参加抗赤性鉴定试验，试验结果为农艺性状与扬麦158基本一致，对赤霉病的抗侵染能力略强于对照扬麦158，抗扩展能力优于扬麦158。产量和抗性表现：该品种于2001-2002年参加抗赤性鉴定试验，试验结果为农艺性状与扬麦158基本一致，对赤霉病的抗侵染能力略强于对照扬麦158，抗扩展能力优于扬麦158。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (222, 1, '生选4号', '苏审麦200606', '2006.9', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院农业生物遗传生理所', '宁麦8号/宁麦9号F1经花培', '适宜江苏沿淮麦区种植', '退出批次：特征特性：该品种长芒、白壳、穗纺缍形，籽粒白皮、半角质，饱满度较好。幼苗半直立，叶色深绿，分蘖力一般，抗寒性一般。株型较紧凑，穗层整齐，熟相佳。株高81厘米左右，抗倒性一般。全生育期222天，每亩有效穗35万左右，每穗39粒左右，千粒重38克左右。抗性接种鉴定，中抗赤霉病，中感纹枯病、穗发芽，感白粉病，高感梭条花叶病。品质分析三年平均结果为粗蛋白含量14.3%，湿面筋含量27.7%，稳定时间4.2分钟。产量和抗性表现：2003-2005年度参加江苏省区域试验，两年平均亩产464.1公斤，较对豫麦18增产6.13 %，两年增产均达极显著；2005-2005年度组织生产试验，平均亩产464.08公斤，较对豫麦18增产1.98%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (223, 1, '申河麦1号', '苏审麦200605', '2006.9', 0, '江苏省农作物品种审定委员会', '大丰上海农场种业有限公司', '468（重庆049/罗选5号）//川生068', '适宜江苏沿淮麦区种植', '退出批次：特征特性：该品种长芒、白壳、穗纺锤形，籽粒角质。幼苗直立，叶色深绿，叶片宽长披垂，分蘖力较弱，抗寒性一般。株型较松散，株高80厘米左右，抗倒性较好。穗层较整齐，熟相较好。全生育期221天左右。每亩有效穗31万左右，每穗34粒左右，千粒重44克左右。抗性接种鉴定，中抗赤霉病，中感白粉病，感纹枯病、穗发芽，高感梭条花叶病。品质分析四年平均结果为粗蛋白含量14.9%，湿面筋含量31.5%，稳定时间4.1分钟，属中筋品种。产量和抗性表现：2002-2005年度参加江苏省区域试验，三年平均亩产431.52公斤，较对照豫麦18增产4.37%；2005-2006年度组织生产试验，平均亩产479.9公斤，较对照豫麦18增产3.82%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (224, 1, '盐麦1903', '苏审麦20220028', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏沿海地区农业科学研究所、盐城市盐都区农业科学研究所', '生选6号/镇麦10号', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，叶色深绿，分蘖力一般。株型较紧凑，穗层整齐，熟相较好。穗纺锤型，长芒、白壳、红粒，籽粒角质。联合体区域试验平均结果：全生育期205.8天，比对照扬麦20短0.9天，株高91.8厘米，每亩有效穗32.4万，每穗37.4粒，千粒重48.7克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.00、2.40；自然发病鉴定中抗赤霉病，病指0.27、5.50），高感纹枯病、叶锈病，中抗白粉病、条锈病、黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重801g/L、804g/L，粗蛋白质含量（干基）13.3%、14.6%，湿面筋含量30.7%、30.5%，吸水率63%、64%，稳定时间7.5min、7.9min，最大拉伸阻力388E.U.、468E.U.，拉伸面积105cm2、97cm2，硬度指数60.0。2020年、2021年品质检测结果均达到中强筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮南小麦江苏农科院科企联合体区域试验，两年平均亩产496.4公斤，比对照扬麦20增产3.3%。2021-2022年度参加生产试验，平均亩产572.8公斤，比对照扬麦20增产4.5%。', '1、适宜播期10月25日至11月5日。2、基本苗适期播种每亩17万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (225, 1, '盐麦1号', '苏审麦20200005', '2020.11', 0, '江苏省农作物品种审定委', '盐城市盐都区农业科学研究所', '071T-159/镇麦 168，参试名称“盐麦 0730”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，分蘖力中等。株型较紧凑，抗倒性中等。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒 角质。区试平均结果:全生育期 208.8 天，比对照扬麦 20 短 1.6 天。株 高 85.7 厘米，每亩有效穗 31.4 万，每穗 39.2 粒，千粒重 43.3 克。经江 苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴 定:中抗赤霉病(接种鉴定中抗赤霉病，严重度 1.7、2.3;自然发病鉴 定中抗赤霉病，病指 1.6、1.6)，高抗白粉病，中感条锈病，感纹枯病、 黄花叶病毒病，高感叶锈病。经江苏省农业科学院种质资源与生物研究 所鉴定:抗穗发芽。经农业部谷物品质监督检验测试中心测定:容重 772g/L、782g/L，粗蛋白(干基)15.68%、13.03%，湿面筋 29.0% 、26.5%， 吸水率 64%、63%，稳定时间 4.4min、3.5min，最大拉伸阻力 292E.U.、 350E.U.，拉伸面积 79cm2、82cm2，硬度指数 59.2、67.0。产量和抗性表现：2017-2019 年度参加江苏省淮南小麦 B 组区试，两年平 均亩产 496.5 公斤，比对照扬麦 20 增产 6.1%。2019-2020 年度参加生产 试验，平均亩产 516.8 公斤，比对照扬麦 20 增产 6.5%。', '1、适宜播期 10 月 25 日至 11 月 5 日。2、适期播种 每亩基本苗 16 万-18 万，中低产田适当增加。3、一般亩施纯氮 18 公斤， 其中基苗肥占 60%、拔节孕穗肥占 40%，同时配合施用磷钾肥，后期适 当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除 田间杂草。注意防治纹枯病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (226, 1, '盐麦2号', '苏审麦20210019', '2021.12', 0, '江苏省农作物品种审定委员会', '盐城市盐都区农业科学研究所', '盐麦0221/镇02168，参试名称“盐麦0815”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色中等，分蘖力较好。株型较松散，抗倒性一般。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒角质。区试平均结果：全生育期202.4天，比对照扬麦20短1.8天。株高86.7厘米，每亩有效穗31.4万，每穗39.5粒，千粒重46.2克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.68、1.39；自然发病鉴定抗赤霉病，病指0、0），中感条锈病，感黄花叶病毒病，高感纹枯病、白粉病、叶锈病。经江苏省农业科学院种质资源与生物研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重773g/L、803g/L，粗蛋白(干基)含量14.8%、16.0%，湿面筋含量35.7%、32.6%，吸水率68.9%、64.2%，稳定时间3.4min、7.6min，最大拉伸阻力268E.U.、351E.U.，拉伸面积64cm2、97cm2，硬度指数68.0、68.5。2019-2020年度品质指标达中强筋小麦品种审定标准。产量和抗性表现：2018-2020年度参加江苏省淮南小麦里下河农科所科企联合体区试，两年平均亩产511.8公斤，比对照扬麦20增产2.8%。2020-2021年度参加生产试验，平均亩产501.7公斤，比对照扬麦20增产5.2%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗16万左右，中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (227, 1, '盐麦5号', '苏审麦20220012', '2023.01', 0, '江苏省农作物品种审定委员会', '盐城市盐都区农业科学研究所', '镇麦9号/镇麦168', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗半直立，分蘖力较强。株型较松散，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒角质。省区域试验平均结果：全生育期208.0天，比对照扬麦20短1.1天，株高90.2厘米，每亩有效穗31.5万，每穗38.7粒，千粒重47.5克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.35、1.93；自然发病鉴定中抗赤霉病，病指0.36、1.73），高感纹枯病，感黄花叶病毒病，中感白粉病、条锈病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重791g/L、776g/L，粗蛋白质含量（干基）14.1%、14.4%，湿面筋含量30.5%、28.7%，吸水率65%、63%，稳定时间11.8min、8.8min，最大拉伸阻力666E.U.、642E.U.，拉伸面积158cm2、157cm2，硬度指数68.1、67.5。2019年、2020年品质检测结果分别达到强筋、中强筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮南A组小麦品种区域试验，两年平均亩产519.2公斤，比对照扬麦20增产4.9%。2020-2021年度参加生产试验，平均亩产468.1公斤，比对照扬麦20增产5.1%。', '1、适宜播期10月25日至11月5日。2、基本苗适期播种每亩16万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (228, 1, '盐麦6号', '苏审麦20220040', '2023.01', 0, '江苏省农作物品种审定委员会', '盐城市盐都区农业科学研究所', '明麦1号/CP01-27-3-1-1', '通过审定，适宜在江苏省淮北麦区晚茬种植。', '特征特性：弱春性小麦品种。幼苗半匍匐，叶色深绿，分蘖力较强。株型较松散，穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒角质。联合体区域试验平均结果：全生育期224.0天，比对照淮麦20短0.9天，株高88.5厘米，每亩有效穗38.9万，每穗37.8粒，千粒重46.1克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中抗赤霉病，严重度1.85、2.37；自然发病鉴定中感赤霉病，病指1.48、8.57），高感纹枯病、白粉病，中感条锈病、叶锈病，中抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重824g/L、824g/L，粗蛋白质含量（干基）14.3%、14.8%，湿面筋含量31.7%、31.5%，吸水率66%、64%，稳定时间3.7min、4.2min，最大拉伸阻力194E.U.、186E.U.，拉伸面积37cm2、42cm2，硬度指数64.6、66.2。产量和抗性表现：2019-2021年度参加江苏省淮北小麦神农大丰科企联合体区域试验，两年平均亩产565.1公斤，比对照淮麦20增产3.0%。2021-2022年度参加生产试验，平均亩产606.1公斤，比对照淮麦20增产6.7%。', '1、适宜播期10月20日至11月5日。2、基本苗适期播种每亩14万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮15公斤左右，其中基苗肥占40%、拔节肥占40%、孕穗肥占20%，同时配合施用磷钾肥，后期适当喷施叶面肥。注意冻害防治、防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (229, 1, '苏垦麦18', '苏审麦20200020', '2020.11', 0, '江苏省农作物品种审定委', '江苏苏垦种业有限公司', '皖麦 38/淮麦 9720，参试名称“苏垦麦 1008”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色深绿，分蘖力强，抗寒性较好。株型紧凑，剑叶挺、穗层较整齐，抗倒性较好。拔节起身 慢，灌浆快，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒半角质-角 质，饱满度好。区试平均结果:全生育期 234.8 天，比对照淮麦 20 长 1.4 天。株高 90.9 厘米，每亩有效穗 42.3 万，每穗 36.9 粒，千粒重 41.9 克。 经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究 所鉴定:中感赤霉病(接种鉴定中感赤霉病，严重度 2.3、3.6;自然发 病鉴定 2019 年病指 3.3)，中抗黄花叶病，中感条锈病，感白粉病，高感 纹枯病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定: 中抗穗发芽。经农业部谷物品质监督检验测试中心测定:容重 840g/L、 808g/L，蛋白(干基)13.9%、16.5%，湿面筋 28.4%、31.3%，吸水率 55%、54%，稳定时间 3.1min、4.1min，最大拉伸阻力 218E.U.、282E.U.， 拉伸面积 47cm2、52cm2，硬度指数 50.1、52.6。产量和抗性表现：2015-2016 年度、2018-2019 年度参加江苏省淮北小麦 B 组区试，两年平均亩产 604.6 公斤，比对照淮麦 20 增产 4.4%。2019-2020 年度参加生产试验，平均亩产 612.3 公斤，比对照淮麦 20 增产 6.7%。', '1、适宜播期 10 月 10 日-25 日;2、适期播种每亩基 本苗 16 万左右，推迟播种或肥力中低田块应适当增加;3、一般亩施纯 氮 18 公斤左右，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗肥占40%。抽穗扬花后结合防治病虫害喷施叶面肥，田间沟系配套，注意防 涝抗旱。4、冬前几早春及时防除田间杂草。注意防治纹枯病、赤霉病、 白粉病、锈病及蚜虫芽病害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (230, 1, '苏徐1号', '苏种审字第387号', '2000', 0, '江苏省农作物品种审定委员会', '江苏省农科院现代化所', '烟农15系选', '江苏淮河以北、阜宁以西', '退出批次：特征特性：该品种幼苗匍匐，抗寒性较好，叶片窄小，叶色浓绿。分蘖性较强，成穗率较高。株高85厘米左右，株型紧凑，长相清秀，茎秆弹性较强，耐肥抗倒性较强，有一定的耐瘠性，但生长后期有叶枯现象。该品种亩有效穗49万左右，每穗粒数30粒左右，千粒重31克左右。无芒、白壳、纺锤型穗。籽粒饱满、角质、白皮。该品种中抗一中感条锈病，中感白粉病，中感纹枯病、赤霉病、叶锈病。该品种容重805克／升，蛋白质含量15.4％，湿面筋含量为37.3％，沉降值为61毫升，降落值为252秒，吸水率为55.10％，面团形成时间为3.5分钟，稳定时间为5.4分钟，断裂时间为6.3分钟，综合评价值48分（南京经济学院，1999年），属于中筋力小麦品种。全生育期为237天左右，后期熟相一般。产量和抗性表现：该品种1997—2000年度参加江苏省淮北小麦中间试验。1997—1998年度省区试平均亩产321.70公斤，比对照陕229增产6.30％，达极显著水平；1998 —1999年度省区试平均亩产435.80公斤，比对照增产0.32％，增产不显著；1999—2000年度参加省淮北小麦生产试验，平均亩产439.30公斤，比对照陕229增产3.10％。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (231, 1, '苏徐2号', '苏审麦200301', '2003', 0, '江苏省农作物品种审定委员会', '省农科院农业资源与环境研究中心', '烟农95-9系选', '江苏淮北麦区', '退出批次：特征特性：该品种幼苗半匍匐，生长健壮，叶片宽大，叶色浓绿，分蘖性较弱，株型紧凑，穗层较整齐，剑叶宽大上举，株高近90厘米，穗长方形，长芒、白壳、白粒，结实性好，籽粒角质。每亩穗数32万左右，每穗实粒数38粒左右，千粒重40克左右，较陕229高6-7克。全生育期235天左右，较陕229迟熟2-3天。抗白粉病，中感条锈病、叶锈病和纹枯病，赤霉病较陕229轻，耐肥抗倒性好，熟相一般，成熟后收获不及时会掉头。据2000年南京经济学院检测：容重773克/升，粗蛋白15.76%，湿面筋36.8%，形成时间10.9分钟，稳定时间14.0分钟，为强筋小麦品种，品质达到国标一级优质面包小麦标准。产量和抗性表现：2000-2002年度参加江苏省区域试验，2000-2001年度平均亩产431.09公斤，较对照陕229减产5.79%，达极显著水平；2001-2002年度平均亩产430.62公斤，较对照增产5.51%。两年平均亩产430.9公斤，与对照相当。2002-2003年度组织生产试验，平均亩产400.6公斤，较对照增产11.0%。该品种有一定产量水平，品质优。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (232, 1, '苏研麦611', '苏审麦20220041', '2023.01', 0, '江苏省农作物品种审定委员会', '南京苏乐种业科技有限公司、江苏苏乐种业科技有限公司', '秦农142/西农9718', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。分蘖力较强，株型较紧凑。穗层整齐，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒角质。联合体区域试验平均结果：全生育期224.6天，比对照淮麦20短0.4天，株高83.4厘米，每亩有效穗39.3万，每穗37.9粒，千粒重43.5克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度1.50、3.00；自然发病鉴定中感赤霉病，病指1.96、15.00），高感白粉病、叶锈病，感纹枯病，抗黄花叶病毒病，高抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重838g/L、834g/L，粗蛋白质含量（干基）14.6%、15.8%，湿面筋含量32.6%、35.1%，吸水率65%、69%，稳定时间4.8min、6.4min，最大拉伸阻力327E.U.、302E.U.，拉伸面积86cm2、98cm2，硬度指数66.0、67.3。产量和抗性表现：2019-2021年度参加江苏省淮北小麦神农大丰企业联合体区域试验，两年平均亩产567.3公斤，比对照淮麦20增产3.4%。2021-2022年度参加生产试验，平均亩产592.2公斤，比对照淮麦20增产4.1%。', '1、适宜播期10月15日至30日。2、基本苗适期播种每亩12万-16万，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤-18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，注意注意化控控高、防涝抗旱。4、冬前及早春及时防除田间杂草，做好赤霉病、纹枯病、白粉病及蚜虫等病虫害的防治。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (233, 1, '苏科麦1号', '苏审麦201204', '2012.11', 0, '江苏省农作物品种审定委员会', '杨安南、史净泉', '从扬麦11中选择变异株经系统选育', '江苏省淮南麦区种植', '退出批次：特征特性：该品种表现幼苗直立，叶片短而宽，叶色深绿分蘖力较强，抗寒性较好株型较紧凑，耐肥抗倒性较好穗层整齐，纺锤型穗长芒、白壳、红粒，籽粒硬质、饱满度好，千粒重高区试平均结果：全生育期215.6天，较对照迟熟2-3天；株高85.1厘米，每亩有效穗30.8万穗，每穗38.1粒，千粒重43.1克接种鉴定结果：中抗赤霉病，中感纹枯病，感白粉病，高抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2009-2011年度两年平均结果：容重820.5克/升，粗蛋白含量13.2%，湿面筋含量28.2%，稳定时间2.9分钟产量和抗性表现：2009-2011年度参加江苏省淮南组小麦区域试验，平均亩产485.3公斤，较对照扬麦11号增产7.4％，两年均较对照增产均达极显著水平2011-2012年度参加生产试验，平均亩产405.7公斤，较对照扬麦11号增产7.1%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (234, 1, '苏麦198', '苏审麦20210017', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏丰庆种业科技有限公司', '镇麦5号/镇麦168，参试名称“苏麦198”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色深绿，分蘖力较强。株型较松散，穗层较整齐，抗倒性一般。穗纺锤形，长芒、白壳、红粒，籽粒半角质。区试平均结果：全生育期207.5天，比对照扬麦20短0.3天。株高85.8厘米，每亩有效穗32.9万，每穗39.3粒，千粒重43.6克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.9、1.05、1.35；自然发病鉴定中抗赤霉病，病指0、0.13、6.25），感黄花叶病毒病，高感纹枯病、白粉病、叶锈病、条锈病。经江苏省农业科学院种质资源与生物研究所鉴定：高抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重826g/L、809g/L，粗蛋白(干基)含量13.2%、13.0%，湿面筋含量30.4%、28.4%，吸水率57.9%、59.7%，稳定时间3.3min、3.4min。产量和抗性表现：2018-2020年度参加江苏省淮南小麦省农科院科企联合体区试，两年平均亩产502.0公斤，比对照扬麦20增产3.1%。2020-2021年度参加生产试验，平均亩产487.2公斤，比对照扬麦20增产1.8%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗15万左右，中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (235, 1, '苏麦4号', '苏种审字第181号', '1993', 0, '江苏省农作物品种审定委员会', '江苏太湖地区农科所', '宁8176(263/反修5号//宁麦4号///7084/扬麦3', '江苏淮南麦区', '退出批次：特征特性：幼苗直立，发苗早，生长稳键.株高87厘米左右，株型紧凑挺拔，茎秆韧性较好，基部节间硬实.叶短窄挺，叶色偏淡，返青拔节期叶色落黄较快，中后期叶色由淡深绿.成穗率均较高，春发性良好.每亩穗数30.万.长芒、白壳、红粒，锥形穗，穗短粒密。每穗实粒数31粒左历。灌浆速度较快，籽粒短园饱满，偏角质，干粒重36克左右，容重达803克/公分。出粉率65.6%粗蛋白含量11%，湿面筋28.7%，干面筋9.0%面团形成时间1.7分钟，衰减度190Bμ，较适于做饼干专用粉。全生育期205天左右。早熟性突，比杨麦5号早熟3天。耐肥抗倒性，耐湿性较好。丰产性与杨五相仿。对梭条花叶病毒病具有局部抗性。中感赤霉病、纹枯病，白粉病较重。抗寒性略差。后期枯偏重，熟相欠佳。产量和抗性表现：1990、1991年连续两年参加淮北片小麦品种区域试验，平均单产分别人290.35公斤和302.4公斤，比扬麦5号分别增产1.1%、3。48%，增产不显著。1992年省生产试验，平均增产364.8公斤，比杨麦5号减产1.9%.', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (236, 1, '苏麦5号', '苏种审字第284号', '1997', 0, '江苏省农作物品种审定委员会', '江苏太湖地区农科所', '西风/扬麦4号', '江苏淮南麦区', '退出批次：特征特性：幼苗半直立，繁茂性好，分蘖早生快发，叶略宽、中披，叶色较淡。株高85厘米工作，比对照矮10厘米，茎杆较软，抗性一般。分蘖力、成穗率较高，冬发性、春发性均较好。易争足穗，每亩33万穗，比对照多4.4万穗。长芒、白壳、淡红粒、穗纺锤形，穗层整齐，穗短、着粒稍稀，平均每穗37.4粒，比对照少2.2粒，灌浆快，籽粒较均匀、饱满，偏角质，籽粒商品性较好，千粒重35—36克，比对照低3—4克。容重较高，780克/升—803克/升。苏麦5号粗蛋白含量10.6%，湿面筋含量27.8%，沉降值26.5秒，降落植422S，吸水率60%，面团形成时间2.0分钟，稳定时间.8分钟，衰减度160BU。粉质评价值35分，可作饼干、糕点专用粉。生育期200.2天，比对照略迟一天左右，但苏南相仿。耐湿性、耐干热风、熟相较好。高抗梭条花叶病毒病。白粉病中等发生，本区北部明显轻，对赤霉病抗性不及对照，感染纹枯病。在中须晚播条件下也能增产，具有较好丰产性。杆偏软。抗倒性、抗寒性差于对照。穗、粒型略小。产量和抗性表现：1995-1997年连续两年度参加江苏省淮南小麦品种区域试验，平均单产别为434.02公斤、399.46公斤，分别比对照增产6.59%、1.48%，分别达极显著不显著水准。两年平均单产415.99公斤，比对照增产3.97%，达极显著水准，居第二位。1996—1997年度在生产试验平均单产427.73公斤，比对照增产0.94%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (237, 1, '苏麦6号', '苏种审字第339号', '1999', 0, '江苏省农作物品种审定委员会', '江苏太湖地区农科所', '6698白/鉴2', '江苏淮南麦区', '退出批次：特征特性：幼苗半直立，叶片细窄，叶色淡绿。春性偏强。株高85-90厘米，株型紧凑。分蘖力较强，春发性较好，成穗率较高。长芒、白壳、纺锤形穗，每穗平均35粒左右。籽粒饱满，白皮，角质，籽粒商品性好，千粒重43克左右。品质较好，粗蛋白含量15.1%，湿面筋含量39.9%，吸水率65.8%，面团形成时间3.2分钟，稳定时间3.0分钟，断裂时间5.0分钟，粉质评价值49分。生育期204天左右，比扬麦158早熟1-2天。高抗梭条花叶病毒病，中感赤霉病、白粉病，中抗-中感纹枯病，抗寒性较弱，抗倒性较强。较耐穗发芽。产量和抗性表现：1997至1999年连续两个年度参加江苏省淮南小麦品种区域试验，平均亩产分别为287.59公斤和364.02公斤，比对照扬麦158增产9.38%和减产1.75%（不显著）。1998-1999年度在江苏省淮南小麦品种生产试验中亩产401.63公斤，比对照扬麦158增产4.44%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (238, 1, '苏麦8号', '苏审麦201302', '2013', 0, '江苏省农作物品种审定委员会', '江苏丰庆种业科技有限公司', '宁麦9号/扬麦11', '适宜江苏省淮南麦区种植', '退出批次：特征特性：幼苗半直立，叶色浓绿分蘖力较强，抗寒性较好株型偏松散，株高适中，抗倒性较好穗纺锤型，小穗排列紧凑，多穗多粒，结实率较高灌浆速度快，穗层整齐，后期清秀，熟相好长芒、白壳、红粒，籽粒椭圆形，半硬质，籽粒饱满，千粒重高区试平均结果：全生育期211.0天，较对照迟熟2天；株高80.8厘米，每亩有效穗32.5万穗，每穗37.4粒，千粒重43.6克接种鉴定结果：中感赤霉病，中感纹枯病，中感白粉病，中抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2010-2012年度两年平均结果：容重816.0克/升，粗蛋白含量13.8%，湿面筋含量30.0%，稳定时间2.6分钟产量和抗性表现：2010-2012年度参加江苏省淮南组小麦区域试验，平均亩产462.0公斤，较对照扬麦11号增产8.1％，2010-2011年度增产达极显著水平2012-2013年度参加生产试验，平均亩产435.6公斤，较对照扬麦11号增产5.9%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (239, 1, '西农977', '苏审麦20200014', '2020.11', 0, '江苏省农作物品种审定委', '西北农林科技大学、宿迁中江种业有限公司', '周麦 17/西农 979 ，参试名称“江麦 977”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿。分蘖力较强，成穗率较高，抗寒性一般。株型较紧凑，穗层整齐，抗倒性中等，熟相 较好。穗纺锤形，长芒、白壳、白粒，籽粒半角质，饱满度较好。区试 平均结果:全生育期 225.3 天，比对照淮麦 20 短 1.2 天。株高 79.6 厘米， 每亩有效穗 41.6 万，每穗 35.3 粒，千粒重 41.2 克。经江苏省农业科学 院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定:感赤霉病 (接种鉴定感赤霉病，严重度 3.7、3.7;自然发病鉴定感赤霉病，病指 45.6、4.9)，高抗条锈病，中感白粉病、黄花叶病毒病，高感纹枯病、叶 锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定:高感穗发 芽。经农业部谷物品质监督检验测试中心测定:容重 814g/L、820g/L， 蛋白质(干基)14.9%、13.4%，湿面筋 31.6%、29.3%，吸水率 55%、60%， 稳定时间 3.6min、2.4min，最大拉伸阻力 232E.U.、182E.U.，拉伸面积 59cm2、51cm2，硬度指数 40.3、32.1。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦 A 组区试，两年平均 亩产 574.8 公斤，比对照淮麦 20 增产 3.7%。2019-2020 年度参加生产试 验，平均亩产 581.2 公斤，比对照淮麦 20 增产 5.4%。', '1、适宜播期 10 月 10 日-25 日。2、适期播种每亩基 本苗 12 万-16 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯 氮 18 公斤左右，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗肥占 40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防 涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、 白粉病、叶锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (240, 1, '迁麦088', '苏审麦20170004', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院农业资源与环境研究所', '铜麦1号/百农矮抗58，参试名称“迁06225”', '江苏省淮北麦区', '特征特性：半冬性中熟小麦品种。成熟期比对照淮麦20早1.3天。幼苗半匍匐，叶片宽大，叶色绿。分蘖力较强，抗寒性一般。株型较紧凑，穗层较整齐，抗倒性中等。拔节抽穗早，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒椭圆形，半硬质-硬质。区试平均结果：全生育期231.9天，株高83.9厘米，每亩有效穗43.8万，每穗31.5粒，千粒重43.4克。病害鉴定：中感赤霉病（严重度2.42-2.74），高感白粉病、纹枯病和叶锈。经江苏省农科院粮作所鉴定：中抗穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：粗蛋白（干基）14.7%，湿面筋30.6%，吸水量53.0ml/100g，稳定时间6.2分钟，最大拉伸阻力414（Rm,135E.U），拉伸面积74cm2。产量和抗性表现：2014-2016年度参加江苏省淮北组小麦区域试验，两年平均亩产567.0公斤，较对照淮麦20增产3.4%。2016-2017年度参加生产试验，平均亩产569.3公斤，较对照淮麦20增产4.5%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗12万-16万，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮18公斤左右，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (241, 1, '迁麦188', '苏审麦20210013', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', '铜麦1号/连5105，参试名称“迁08207”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶细长，叶色绿。分蘖力强。起身拔节中等偏早，抗寒性较好。株型半紧凑，抗倒性中等。长相清秀，灌浆快，熟相较好。穗纺锤形，长芒、白壳、白粒，籽粒长圆形、角质。区试平均结果：全生育期228.4天，比对照淮麦20短1.7天。株高89.1厘米，每亩有效穗42.6万，每穗33.6粒，千粒重43.7克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度3.27、3.05、3.65；自然发病鉴定中感赤霉病，病指2.22、1.43、18.21），中抗黄花叶病，中感条锈病，高感白粉病、纹枯病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：感穗发芽。经农业部谷物品质监督检验测试中心测定：容重827g/L、841g/L，蛋白质（干基）含量15.0%、14.4%，湿面筋含量31.6%、29.9%，吸水率55.9%、58.2%，稳定时间12.3min、8.9min，最大拉伸阻力475E.U.、475E.U.，拉伸面积76cm2、80cm2，硬度指数46.1、50.8。2019-2020年度品质指标达中强筋小麦品种审定标准。产量和抗性表现：2018-2020年度参加江苏省淮北小麦A组区试，两年平均亩产605.8公斤，比对照淮麦20增产4.0%。2020-2021年度参加生产试验，平均亩产593.8公斤，比对照淮麦20增产4.7%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗12万-16万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯氮18公斤左右，配合施用磷钾肥。其中氮肥基苗肥占40%-50%，拔节肥占30%-40%，孕穗肥占20%。注意化控控高、防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (242, 1, '迁麦1号', '苏审麦200806', '2008.9', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院农业资源与环境研究所、江苏省农业科学院宿迁农科所', '烟84139/烟农15-9', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶窄色淡，抗寒性较好分蘖力中等，成穗率偏低株型紧凑，茎杆弹性好，耐肥抗倒性好穗层整齐，结实性好长芒，白壳，白粒，纺锤型穗，籽粒硬质-半硬质省区试平均结果：全生育期234.0天，较对照淮麦18迟熟1天；株高77.8厘米，每亩有效穗30.3万穗，每穗43.2粒，千粒重42.1克接种鉴定结果：中感赤霉病，感纹枯病，中抗梭条花叶病中感穗发芽经农业部谷物品质监督检验测试中心测定，三年平均结果：容重806克/升，粗蛋白含量16.1%，湿面筋含量36.2%，稳定时间2.7分钟产量和抗性表现：2005-2007年度参加江苏省区域试验，两年平均亩产513.7公斤，较对照淮麦18增产1.0%；2007-2008年度参加生产试验，平均亩产522.8公斤，较对照淮麦18增产3.4%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (243, 1, '迁麦2号', '苏审麦201005', '2010.1', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院宿迁农科所', '泗麦1108/淮麦9720', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，幼苗叶片细长，叶色偏淡冬季抗寒性较好，春季返青起身早，抗倒春寒性一般分蘖力强，成穗数多株型较紧凑，穗层较整齐，剑叶适中、挺，抗倒性一般纺锤型穗，结实性一般长芒、白壳、白粒，籽粒硬质区试平均结果：全生育期230.0天，与对照淮麦18相当；株高82.1厘米，每亩有效穗41.1万穗，每穗31.3粒，千粒重40.6克接种鉴定结果：中感赤霉病、纹枯病，感白粉病，高抗黄花叶病经农业部谷物品质监督检验测试中心测定， 2007-2009年度两年平均结果：容重789克/升，粗蛋白含量14.8%，湿面筋含量31.4%，稳定时间5.9分钟；2008年容重811克/升，粗蛋白含量16.4%，湿面筋含量34.7%，稳定时间7.2分钟产量和抗性表现：2007-2009年度参加江苏省区域试验，两年平均亩产500.6公斤，较对照淮麦18增产2.0%2009-2010年度参加生产试验，平均亩产510.4公斤，较对照淮麦20增产3.2%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (244, 1, '迁麦3号', '苏审麦20200011', '2020.11', 0, '江苏省农作物品种审定委', '江苏省农业科学院宿迁农科所', '汶农 14 号/藁优 9415，参试名称“泗 1516”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿。分蘖力较强，抗寒性较好。株型较紧凑，穗层整齐，抗倒性中等。拔节起身较晚，熟 相较好。穗纺锤形，长芒、白壳、白粒，籽粒椭圆形、角质。区试平均 结果:全生育期 228.1 天，比对照淮麦 20 长 1.6 天。株高 81.9 厘米，每 亩有效穗 40.0 万，每穗 36.7 粒，千粒重 42.8 克。经江苏省农业科学院 植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定:感赤霉病(接 种鉴定中感赤霉病，严重度 3.5、3.1;自然发病鉴定感赤霉病，病指 27.1、 7.8)，高抗条锈病，中感叶锈病、黄花叶病毒病，高感白粉病、纹枯病。 经江苏省农业科学院种质资源与生物技术研究所鉴定:高感穗发芽。经 农业部谷物品质监督检验测试中心测定:容重 827g/L、822g/L，蛋白质 (干基)14.7%、15.0%，湿面筋 32.1%、35.4%，吸水率 64%、60%，稳 定时间 2.9min、3.1min，最大拉伸阻力 145E.U.、188E.U.，拉伸面积 34cm2、 38cm2，硬度指数 66.3、65.9。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦 A 组区试，两年平均 亩产 580.5 公斤，比对照淮麦 20 增产 4.8%。2018-2019 年度参加生产试 验，平均亩产 580.0 公斤，比对照淮麦 20 增产 5.2%。', '1、适宜播期 10 月 20 日-30 日。2、适期播种每亩基 本苗 15 万-20 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯 氮 18 公斤左右，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗肥占 40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防 涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、 白粉病、叶锈和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (245, 1, '连麦10号', '苏审麦20200031', '2020.11', 0, '江苏省农作物品种审定委', '连云港市农业科学院', '连 0608/连 0709，参试名称“连 1509”', '江苏省淮北麦区', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色绿。分蘖力较强， 抗寒性较好。株型较紧凑，穗层整齐，抗倒性较好。灌浆快，熟相较好。 穗纺锤形，长芒、白壳、白粒，籽粒角质。区试平均结果:全生育期 226.1 天，比对照淮麦 20 长 0.8 天。株高 87.8 厘米，每亩有效穗 40.7 万，每 穗 36.5 粒，千粒重 40.1 克。经江苏省农业科学院植物保护研究所、江苏 徐淮地区徐州农业科学研究所鉴定:感赤霉病(人工接种鉴定感赤霉病， 严重度 3.9、3.6，自然发病鉴定中感赤霉病，病情指数 6.8、0.0)，高抗 条锈病，中抗黄花叶病毒病，中感纹枯病，高感叶锈病、白粉病。经江 苏省农业科学院种质资源与生物技术研究所鉴定:高感穗发芽。经农业 部谷物品质监督检验测试中心测定:容重 782g/L、777g/L，蛋白质(干 基)15.4%、15.6%，湿面筋 28.8%、31.9%，吸水率 59%、57%，稳定时 间 6.6min、16.4min，最大拉伸阻力 482E.U.，拉伸面积 72cm2，硬度指 数 63.3。产量和抗性表现：2017-2019 年度参加江苏省淮北小麦徐州农科所科企联合 体区试，两年平均亩产 538.8 公斤，比对照淮麦 20 增产 3.0%。2019-2020 年度参加生产试验，平均亩产 551.5 公斤，比对照淮麦 20 增产 4.8%。', '1、适宜播期 10 月 10 日-25 日。2、适期播种每亩基 本苗 13 万-16 万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯 氮 18 公斤左右，配合施用磷、钾肥。氮肥基苗肥占 60%，拔节孕穗肥占 40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防 涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、 白粉病、叶锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (246, 1, '连麦11', '苏审麦20210014', '2021.12', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院', '20005/冬A4，参试名称“连麦1701”', '江苏省淮北麦区', '特征特性：半冬性品种。幼苗半匍匐，长势好，分蘖力较强。株型较松散，穗层较整齐，成穗数较多。熟相较好。穗纺锤形，长芒、白壳、白粒、角质。区试平均结果：全生育期229.6天，比对照淮麦20短0.8天。株高90.0厘米，每亩有效穗43.8万，每穗34.6粒，千粒重40.7克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度1.60、3.39；自然发病鉴定中感赤霉病，病指0.64、19.46），中感条锈病、黄花叶病毒病，高感白粉病、纹枯病、叶锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业部谷物品质监督检验测试中心测定：容重822g/L、832g/L，蛋白质（干基）15.0%、13.5%，湿面筋含量27.0%、25.0%，吸水率53.3%、56.1%，稳定时间15.4min、7.9min，最大拉伸阻力703E.U.、594E.U.，拉伸面积119cm2、112cm2，硬度指数52.1、51.9。产量和抗性表现：2018-2020年参加江苏省淮北小麦B组区试，两年平均亩产596.9公斤，比对照淮麦20增产4.9%。2020-2021年参加生产试验平均亩产613.3公斤，比对照淮麦20增产5.8%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗14万-18万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯氮15公斤左右，配合施用磷钾肥。其中氮肥基苗肥占40%，拔节肥占40%，孕穗肥占20%。拔节期可结合施用多效唑或壮丰安控制株高提高群体质量。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (247, 1, '连麦12', '苏审麦20210012', '2021.12', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院', '刘虎98/西农4711//生选6号/漯38，参试名称“连麦抗1”', '江苏省淮北麦区', '特征特性：半冬性早熟小麦品种。幼苗半匍匐，叶色绿。分蘖力较强，抗寒性中等。株型较紧凑，穗层较整齐，抗倒性中等。长相清秀，起身较早，熟相较好。穗纺锤形，长芒、白壳、白粒、角质。区试平均结果：全生育期227.3天，比对照淮麦20短2.7天。株高88.6厘米，每亩有效穗41.9万，每穗36.5粒，千粒重40.1克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.33、1.4、2.35；自然发病鉴定中抗赤霉病，病指0、0.4、6.43），中抗条锈病、黄花叶病毒病，中感叶锈病，高感白粉病、纹枯病。经江苏省农业科学院种质资源与生物技术研究所鉴定：感穗发芽。经农业部谷物品质监督检验测试中心测定：容重816g/L、829g/L，蛋白质（干基）含量14.6%、14.6%，湿面筋含量34.9%、32.7%，吸水率61.6%、63.2%，稳定时间8.6min、5.4min，最大拉伸阻力413E.U.、323E.U.，拉伸面积93cm2、71cm2，硬度指数67.4、67.8。2018-2019年度品质指标达中强筋小麦品种审定标准。产量和抗性表现：2018-2020年参加江苏省淮北小麦A组区试，两年平均亩产608.2公斤，比对照淮麦20增产4.4%。2020-2021年度参加生产试验，平均亩产594.4公斤，比对照淮麦20增产4.8%。', '1、适宜播期10月10日-25日。2、适期播种每亩基本苗14万-18万，推迟播种或肥力水平偏低应适当增加。3、一般亩施纯氮15公斤左右，配合施用磷钾肥。其中氮肥基苗肥占40%，拔节肥占40%，孕穗肥占20%。注意化控控高、防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (248, 1, '连麦185', '苏审麦20220035', '2023.01', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院', '资07-76/连0809', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗长势正常，叶色绿，分蘖力较强。株型较紧凑，穂层较整齐，剑叶细长、挺，干尖。穗纺锤型，长芒、白壳、白粒、中大穗，籽粒角质。联合体区域试验平均结果：全生育期228.6天，比对照淮麦20短0.4天，株高91.4厘米，每亩有效穗43.2万，每穗34.0粒，千粒重45.6克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度2.75、3.30；自然发病鉴定中感赤霉病，病指4.13、16.80），高感叶锈病、白粉病，感纹枯病，中感条锈病，抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重844g/L、832g/L，粗蛋白质含量（干基）15.5%、14.3%，湿面筋含量32.6%、34.0%，吸水率63%、61%，稳定时间7.2min、6.0min，最大拉伸阻力421E.U.、326E.U.，拉伸面积82cm2、73cm2，硬度指数62.3。2020年品质检测结果达到中强筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮北小麦徐州农科所科企联合体区域试验，两年平均亩产551.0公斤，比对照淮麦20增产3.0%。2021-2022年度参加生产试验，平均亩产632.2公斤，比对照淮麦20增产6.3%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩14万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮18公斤左右，其中基苗肥占60%，拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套、注意防涝抗旱。4、冬前及早春及时防除田间杂草，及时防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (249, 1, '连麦186', '苏审麦20220022', '2023.01', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院', '烟0953/西农538', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，分蘖力较强。株型较紧凑，叶片上冲，穗层较整齐，熟相较好。穗纺锤形，蜡质重，长芒、白壳、白粒，籽粒角质。省区域试验平均结果：全生育期227.5天，与对照淮麦20相当，株高91.6厘米，每亩有效穗42.2万，每穗34.5粒，千粒重44.5克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度1.90、3.41；自然发病鉴定中感赤霉病，病指4.24、9.08），高感叶锈病、白粉病、纹枯病，中抗黄花叶病毒病，高抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重829g/L、824g/L，粗蛋白质含量（干基）15.4%、15.6%，湿面筋含量30.6%、32.0%，吸水率64%、59%，稳定时间16.0min、7.1min，最大拉伸阻力447E.U.、433E.U.，拉伸面积82cm2、82cm2，硬度指数62.7、61.5。2020年、2021年品质检测结果均达到中强筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮北B组小麦品种区域试验，两年平均亩产589.4公斤，比对照淮麦20增产6.2%。2020-2021年度同步参加生产试验，平均亩产604.7公斤，比对照淮麦20增产4.3%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩14万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮18公斤左右，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套、注意防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (250, 1, '连麦1号', '苏审麦200403', '2004.8', 0, '江苏省农作物品种审定委员会', '连云港市黄淮农作物育种研究所', '淮麦18系选', '江苏省淮北麦区', '退出批次：特征特性：该品种长芒、白壳、纺缍型穗，籽粒白皮、硬质；幼苗半匍伏，分蘖力较强，株型较紧凑，全生育期与陕229相当，株高85厘米左右，耐肥抗倒性较好，抗寒性好；每亩有效穗40万左右，每穗30粒左右，千粒重40克左右。接种鉴定中感赤霉病、纹枯病，抗梭条花叶病毒病，抗病性好于陕229。品质分析三年平均结果为粗蛋白含量14.2%，湿面筋含量29.2%，稳定时间10.7分钟，属中筋品种。产量和抗性表现：2001-2003年度参加江苏省区域试验，两年平均亩产446.9公斤，较对照陕229增产8.66%，两年增产均达极显著水平； 2003-2004年度组织生产试验，平均亩产506.1公斤，较对照陕229增产6.09%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (251, 1, '连麦2号', '苏审麦200504', '2005.9', 0, '江苏省农作物品种审定委员会', '连云港农业科学院', '鉴94（73）/鲁麦21号', '江苏省淮北麦区中上等肥力条件下种植。', '退出批次：特征特性：该品种长芒、白壳、纺锤型穗，籽粒白皮、角质。幼苗半匍匐，分蘖力强，叶色深绿，苗壮，抗倒、抗寒性较好。叶片上冲，株型紧凑，株高86厘米左右。前期长势长相较好，后期叶片易早枯，熟相一般。成熟期中早，全生育期235天左右，与对照淮麦18相当。每亩有效穗40万左右，每穗33粒左右，千粒重39克左右。接种鉴定中感条锈病、白粉病、赤霉病和纹枯病，感穗发芽,叶锈病发生轻。品质分析三年平均结果：粗蛋白含量14.8%，湿面筋含量29.7%，稳定时间10.9分钟，属中筋品种。产量和抗性表现：2002-2004年度参加江苏省区域试验，两年平均亩产481kg，比淮麦18减产1.95%，差异不显著。2004-2005年度生产试验平均亩产542.91公斤，较对照淮麦18增产4.18%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (252, 1, '连麦5号', '苏审麦201004', '2010.1', 0, '江苏省农作物品种审定委员会', '灌南县农业科学研究所', '陕229/小偃22', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶色深绿前期生长较慢，冬季抗寒性较好，抗倒春寒性一般分蘖力和成穗数中等株型较紧凑，抗倒性较好剑叶短挺，穗层整齐，熟相好纺锤型穗，结实性好长芒、白壳、白粒，籽粒硬质区试平均结果：全生育期232.5天，较对照淮麦18迟熟1天；株高84.8厘米，每亩有效穗37.2万穗，每穗35.0粒，千粒重40.5克接种鉴定结果：感赤霉病、纹枯病，中抗白粉病，抗黄花叶病经农业部谷物品质监督检验测试中心测定，2006-2009年度三年平均结果：容重812克/升，粗蛋白含量14.1%，湿面筋含量31.1%，稳定时间6.6分钟；2008年容重823克/升，粗蛋白含量14.0%，湿面筋含量31.0%，稳定时间7.8分钟产量和抗性表现：2006-2009年度参加江苏省区域试验，三年平均亩产498.1公斤，较对照淮麦18增产0.4%2009-2010年度参加生产试验，平均亩产512.1公斤，较对照淮麦20增产3.5%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (253, 1, '连麦6号', '苏审麦201208', '2012.11', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区连云港农业科学研究所', '郑9023/济南17//烟农19', '江苏省淮北麦区种植', '退出批次：特征特性：该品种表现幼苗半匍匐，叶色深绿，叶片细长，前期长势较慢，抗寒性较好，拔节抽穗迟，抗倒春寒能力强分蘖力较强，成穗率较高穗层较整齐，株型较松散，株高中等，茎杆弹性较好，抗倒性较好剑叶上冲，大小适中，长相清秀灌浆速度快，落黄好，后期熟相好纺锤型穗，结实性好长芒、白壳、白粒，籽粒硬质，千粒重较高区试平均结果：全生育期239.0天，与对照淮麦20相当；株高84.4厘米，每亩有效穗41.2万穗，每穗34.1粒，千粒重38.1克接种鉴定结果：感赤霉病，中感纹枯病、白粉病，高感黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2008-2010年度两年平均结果：容重775.5克/升，粗蛋白含量12.8%，湿面筋含量27.1%，稳定时间7.2分钟产量和抗性表现：2008-2010年度参加江苏省淮北组小麦区域试验，两年平均亩产501.1公斤，较对照淮麦20增产2.8%，两年较对照增产分别达显著、极显著水平2010-2011年度参加生产试验，平均亩产553.9公斤，较对照淮麦20增产4.0%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (254, 1, '连麦7号', '苏审麦201405', '2014', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院以陕229/灌8116', '陕229/灌8116', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶色深绿分蘖力较强，抗寒性较好株型较紧凑，穗层较整齐，茎叶穗蜡质多，茎杆弹性较好，后期熟相较好穗纺锤形，长芒、白壳、白粒，籽粒卵圆形、半硬质-硬质区试平均结果：全生育期233.4天，与对照相当，株高83.3厘米，每亩有效穗42.8万，每穗33.1粒，千粒重38.8克抗病性经江苏省农科院植保所2011-2013年接种鉴定：感赤霉病，中感纹枯病，中感白粉病，高抗小麦黄花叶病毒病品质经农业部谷物品质监督检验测试中心测定，2011-2013年度两年平均结果：容重831.0克/升，粗蛋白含量14.1%，湿面筋含量27.0%，稳定时间32.0分钟，硬度指数58.5产量和抗性表现：2011-2013年度参加江苏省淮北组小麦区域试验，两年平均亩产524.2公斤，较对照淮麦20增产5.2％，两年增产均达极显著水平2013-2014年度参加生产试验，平均亩产606.1公斤，较对照淮麦20增产5.8％', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (255, 1, '连麦8号', '苏审麦201307', '2013', 0, '江苏省农作物品种审定委员会', '江苏胜田农业科技发展有限公司', '烟农19/52-3', '适宜江苏省淮北麦区种植', '退出批次：特征特性：幼苗半匍匐，叶色深绿分蘖力较强，抗寒性好株型紧凑，茎杆弹性好穗层整齐，茎叶穗蜡质多，后期熟相好穗纺锤型，长芒、白壳、白粒，籽粒硬质区试平均结果：全生育期235.9天，比对照迟熟1天，株高83.3厘米，每亩有效穗43.3万穗，每穗30.5粒，千粒重42.7克接种鉴定结果：感赤霉病、纹枯病，中抗白粉病，高抗黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2010-2012年度两年平均结果：容重841.0克/升，粗蛋白含量12.3%，湿面筋含量26.6%，稳定时间3.2分钟产量和抗性表现：2010-2012年度参加江苏省淮北组小麦区域试验，平均亩产530.7公斤，较对照淮麦20增产6.0％，两年增产均达极显著水平2012-2013年度参加生产试验，平均亩产525.8公斤，较对照淮麦20增产5.1％', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (256, 1, '郑麦9023', '苏审麦200203', '2002', 0, '江苏省农作物品种审定委员会', '河南省农科院', '江苏农垦种子站、江苏省种子站引进', '江苏沿淮地区', '退出批次：特征特性：该品种长芒、白壳，纺锤型穗，籽粒白色、角质，幼苗偏直立，叶色深，叶片宽大，苗壮，分蘖力、成穗数中等，株型紧凑，通风透光性好，茎杆弹性较好，穗层整齐，结实性一般。每亩有效穗31万左右，每穗结实30粒左右，千粒重45-47克，籽粒饱满度好，高抗梭条花叶病毒病，中抗叶锈病，中感条锈和白粉病，纹枯病较轻，灌浆快，晚播早熟，成熟期较豫麦18早熟4天，熟相一般。据2000年10月省区试统一送样品质分析（南京经济学院），粗蛋白含量13.07%，湿面筋29.6％，干面筋11.0％，沉降值35ml，吸水率64.7%，面团形成时间2.3min，面团稳定时间5.6min，粉质评价值52分(同年对照陕229为52分)，属中筋品种。产量和抗性表现：1999-2001年参加省区试，1999-2000年度平均亩产457.32公斤，分别比陕229、徐州25号增产4.59％、3.01％，均达极显著水平，居第7位；2000-2001年度平均亩产470.91公斤，比陕229增产2.91％，达极显著，居第9位；2001-2002年组织苏中片生产试验，平均亩产464.3公斤，较对照豫麦18增产7.25%。该品种生育期短，有较高产量水平，抗病性、品质较好。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (257, 1, '金运麦5号', '苏审麦20220005', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏金运农业科技发展有限公司、江苏金土地种业有限公司', '宁麦11/宁麦14', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，叶色绿，分蘖力一般偏强。株型偏紧凑，穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒半角质至角质。省区域试验平均结果：全生育期211.3天，比对照扬麦20短0.4天，株高85.8厘米，每亩有效穗32.6万，每穗41.2粒，千粒重42.3克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.44、1.15；自然发病鉴定中抗赤霉病，病指0.83、7.28），高感白粉病、叶锈病、条锈病，中感黄花叶病毒病、纹枯病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重810g/L、799g/L，粗蛋白质含量（干基）含量13.8%、12.9%，湿面筋含量含量29.6%、30.3%，吸水率62%、64%，稳定时间4.9min、3.8min，最大拉伸阻力231E.U.、176E.U.，拉伸面积59cm2、51cm2，硬度指数64.5、61.6。产量和抗性表现：2019-2021年度参加江苏省淮南B组小麦品种区域试验，两年平均亩产508.5公斤，比对照扬麦20增产4.1%。2021-2022年度参加生产试验，平均亩产559.2公斤，比对照扬麦20增产5.6%。', '1、适宜播期10月25日至11月10日。2、基本苗适期播种每亩15万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮17公斤左右，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，中后期做好纹枯病、赤霉病、白粉病和蚜虫等防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (258, 1, '金陵1号', '苏种审字第69号', '1986', 0, '江苏省农作物品种审定委员会', '南京市农科所', '南大8号/202', '江苏淮南麦区及淮北南部麦区', '退出批次：特征特性：幼苗半直立，叶色较深，生长较稳健。株高85厘米左右，比扬麦四号矮13厘米左右。株型略松散，茎杆较细。弹性产好。较耐肥抗倒。中下部叶较窄挺，上部叶较平展，角度偏大，后期荫蔽略重。前中期长相较好，但个体生长量偏小，返青拔节后长长较迅速。分蘖力较强，成穗率中等，约45%左右，单株成穗约2.14个，平均比扬四多0.27个。每亩有效穗平均36万左右。穗层整齐度稍差。穗纺锤形，偏小略尖，着粒较密，穗长平均7.5厘米左右。长芒、白壳、红粒，每穗平均30.16—32.56粒，粒型偏小，千粒重较低但较稳定，变幅小，约32.2克左右。与扬麦三号相比：粒重相仿，穗数增3.6万，粒数少1.72粒。与宁麦三号相比，是二增一减，穗数增4.79万，粒重增1.8克粒数少3.9粒。与扬麦四号相比：穗数多7.7万在左右，粒数相仿，略少0.54粒左右，千粒重低5.5克左右。粒形较短圆，容重较高，为743.35—756.55克/升，与扬三、扬四相仿，分别略低5.55 克/升、3.5—7.01克/升：比宁三略低15.4克/升，籽粒半硬质，更适于做面条、饺皮，品质和适口性较好。粗蛋白但12.28—13.49%，赖氨酸含量0.38%，湿面筋含量30%以上，精粉率74.6%，灰分2.18%。全生育期207天左右。分别比扬三迟熟1.1天；比扬四迟 0.29—2.0天；但比宁三早熟3.5天。耐寒性、耐肥抗倒性较好。在适宜范围内，随肥力和环境改善，增产较为明显。高亢排期有黄叶，后期上部叶枯略重，熟相欠佳。产量和抗性表现：1982—1984年连续三年参加省淮南片小麦区域试验，1982年平均亩产738.34斤，比扬麦三号增产10.3%；1983年平均每亩产589.18斤，分别比扬麦三号增产26.4%，比宁麦三号增14.7%；1984年平均亩产650.13斤，分别比扬麦三号增产8.5%。比宁麦三号增产10.4%，比扬麦四号增产5.66%，三年中仅84年比扬麦四号增产达显著标准，其它均达极显著标准。1985年省生产试验亩产521.58斤，比扬麦四号略增。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (259, 1, '镇麦10号', '苏审麦201301', '2013', 0, '江苏省农作物品种审定委员会', '江苏丘陵地区镇江农科所', '苏麦6号/97G59', '适宜江苏省淮南麦区种植', '退出批次：特征特性：幼苗直立，叶色较深分蘖力中等偏弱，耐寒性较好株型较松散，抗倒性较好生长清秀，穗层整齐，熟相好穗纺锤型，小穗排列稍稀长芒、白壳、红粒，籽粒长卵形，硬质，籽粒饱满，千粒重高区试平均结果：全生育期210.9天，较对照迟熟2天；株高81.8厘米，每亩有效穗28.7万穗，每穗38.2粒，千粒重44.1克接种鉴定结果：中抗赤霉病，中感纹枯病，感白粉病、黄花叶病毒病经农业部谷物品质监督检验测试中心测定，2010-2012年度两年平均结果：容重815.0克/升，粗蛋白含量14.3%，湿面筋含量31.3%，稳定时间13.9分钟产量和抗性表现：2010-2012年度参加江苏省淮南组小麦区域试验，平均亩产442.2公斤，较对照扬麦11号增产3.4％，2011-2012年度增产达显著水平2012-2013年度参加生产试验，平均亩产435.9公斤，较对照扬麦11号增产6.0%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (260, 1, '镇麦12号', '苏审麦201501', '2015', 0, '江苏省农作物品种审定委员会', '江苏丘陵地区镇江农业科学研究所', '镇麦168穗系鉴定圃中发现剩余变异单株，经系谱法选育', '江苏省淮南麦区种植', '退出批次：特征特性：幼苗直立，叶色较深；分蘖力中等偏弱；株型偏松散，茎秆粗壮，抗倒性较好；穗近长方形，长芒、白壳、红粒，硬质区试平均结果：全生育期211.2天，较对照长1.6天；株高81.8厘米，每亩有效穗30.1万，每穗36.16粒，千粒重45.84克抗病性经江苏省农科院植保所三年接种鉴定：中抗赤霉病，中感白粉病和纹枯病，高抗黄化叶病，抗穗发芽品质经农业部谷物品质监督检验测试中心测定，两年区试测定平均结果：容重784克/升，粗蛋白含量15.24 %，湿面筋含量32.9%，稳定时间14.1分钟，硬度指数69.3产量和抗性表现：2012-2014年度参加江苏省淮南组小麦区域试验，两年平均亩产475.16公斤，较对照扬麦11号增产5.42％，两年增产均达极显著水平2014-2015年度参加生产试验，平均亩产456.21公斤，较对照扬麦11号增产7.58%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (261, 1, '镇麦13', '苏审麦20180003', '2018.12', 0, '江苏省农作物品种审定委员会', '江苏瑞华农业科技有限公司、江苏丘陵地区镇江农业科学研究所', '（宁04126/镇09196）F1//宁04126，参试名称“镇12096”', '江苏省淮南麦区', '特征特性：属春性中熟小麦品种。幼苗直立，叶色较深，分蘖力中等。株型较紧凑，抗倒性较好。穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒硬质。区试平均结果：全生育期201.7天，比对照扬麦20早近1天。株高81.1厘米，每亩有效穗31.7万，每穗38.8粒，千粒重41.4克。经江苏省农业科学院植物保护研究所接种鉴定：中抗赤霉病（严重度1.55-2.22），感纹枯病，高感白粉病，中感黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业部谷物品质监督检验测试中心（哈尔滨）测定，两年平均结果：粗蛋白（干基）15.7%，湿面筋34.3% ，吸水量66.9ml/100g，稳定时间6.7min，最大拉伸阻力411 E.U.，拉伸面积100m2，硬度指数65.5。2016年检测粗蛋白（干基）16.6%，湿面筋35.8%，吸水量65.6ml/100g，稳定时间8.0min，最大拉伸阻力362 E.U.， 拉伸面积98cm2，硬度指数63.6，达中强筋小麦品种标准。产量和抗性表现：2015-2017年度参加江苏省淮南组小麦区域试验，两年平均亩产492.3公斤，较对照扬麦20增产2.31％。2017-2018年度参加生产试验，平均亩产464.7公斤，较对照扬麦20增产6.1％。', '1、适宜播期10月25日至11月10日。2、适期播种每亩基本苗18万左右，中低产田或迟播应适当增加，播期延迟适当增加基本苗。3、一般亩施纯氮15-18公斤，其中基苗肥占60%、拔节孕穗肥占40％，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草。注意防治纹枯病、白粉病、赤霉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (262, 1, '镇麦15', '苏审麦20180006', '2018.12', 0, '江苏省农作物品种审定委员会', '江苏瑞华农业科技有限公司、江苏丘陵地区镇江农业科学研究所', '宁04126//（扬麦158/ok94p549-2e)2，参试名称“镇13056”', '江苏省淮南麦区', '特征特性：属春性中熟小麦品种。幼苗直立，叶色较深，分蘖力中等。株型松散，抗倒性较好。穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒硬质。区试平均结果：全生育期200.8天，比对照扬麦20早近1天。株高82.6厘米，每亩有效穗31.2万，每穗37.5粒，千粒重45.9克。经江苏省农业科学院植物保护研究所接种鉴定：中抗赤霉病（严重度2.55-2.84），感纹枯病，中感白粉病，抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业部谷物品质监督检验测试中心（哈尔滨）测定，两年平均结果：粗蛋白（干基）14.9%，湿面筋29.2% ，吸水量62.3ml/100g，稳定时间11.2min，最大拉伸阻力541E.U.，拉伸面积110cm2，硬度指数68.8。2017年检测粗蛋白（干基）14.9%，湿面筋29.2%，吸水量64.9ml/100g，稳定时间19.9min，最大拉伸阻力665E.U.，拉伸面积119cm2，硬度指数69.0，达中强筋小麦品种标准。产量和抗性表现：2016-2018年度参加江苏省淮南组小麦区域试验，两年平均亩产494.0公斤，较对照扬麦20增产6.3％。2017-2018年度参加生产试验，平均亩产457.4公斤，较对照扬麦20增产5.4％。', '1、适宜播期10月25日至11月10日。2、适期播种每亩基本苗18万左右，中低产田或迟播应适当增加。3、一般亩施纯氮15-18公斤，其中基苗肥占60%、拔节孕穗肥占40％，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草。注意防治纹枯病、白粉病、赤霉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (263, 1, '镇麦168', '苏审麦200701', '2007.9', 0, '江苏省农作物品种审定委员会', '江苏丘陵地区镇江农业科学研究所', '苏麦6号/97G59', '适宜江苏省淮南麦区种植', '退出批次：特征特性：长芒，白壳，红粒，纺锤型穗，籽粒硬质幼苗直立，叶色淡绿，株型较松散，株高83厘米左右，耐肥抗倒性较强生育期209天左右，与对照相当分蘖力较强，成穗数较多，千粒重高亩有效穗33万左右，每穗35粒左右，千粒重43克左右接种鉴定结果：中抗赤霉病，感纹枯病，高感梭条花叶病，高抗穗发芽田间表现中感白粉病品质分析两年平均结果：粗蛋白含量14.0%，湿面筋含量33.5%，稳定时间7.1分钟，属强筋品种产量和抗性表现：2004-2006年度参加江苏省区域试验，2004-2005年度平均亩产450.2公斤,较对照扬麦158增产3.2％，2005-2006年度平均亩产453.7公斤, 较对照扬麦11号增产1.1％，两年平均亩产452.0公斤，与对照扬麦11号相当；2006-2007年度组织生产试验，平均亩产425.3公斤，较对照扬麦11号增产6.3%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (264, 1, '镇麦18', '苏审麦20200006', '2020.11', 0, '江苏省农作物品种审定委', '江苏丘陵地区镇江农业科学研究所', '镇麦 168/扬麦 11，参试名称“镇 14125”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色中等，分蘖力较强。株型较紧凑，抗倒性较好。穗层整齐，熟相好。穗纺锤形，长芒、白壳、 红粒，籽粒角质。区试平均结果:全生育期 209.2 天，比对照扬麦 20 短 1.2 天。株高 84.4 厘米，每亩有效穗 32.2 万，每穗 36.8 粒，千粒重 45.9 克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学 研究所鉴定:中抗赤霉病(接种鉴定中抗赤霉病，严重度 2.0、2.7;自 然发病鉴定中抗赤霉病，病指 1.7、0.0)，中抗白粉病，中感条锈病、黄 花叶病毒病，高感纹枯病、叶锈病。经江苏省农业科学院种质资源与生 物研究所鉴定:抗穗发芽。经农业部谷物品质监督检验测试中心测定: 容重 800g/L、812g/L，粗蛋白(干基)15.9%、14.8%，湿面筋 31.0% 、32.4%， 吸水率 68%、63%，稳定时间 4.1min、14.6min，最大拉伸阻力 361E.U.、 643E.U.，拉伸面积 93cm2、107cm2，硬度指数 66.3、65.2。2018-2019 年 度品质指标达到强筋小麦品种审定标准。产量和抗性表现：2017-2019 年度参加江苏省淮南小麦 B 组区试，两年平 均亩产 495.6 公斤，比对照扬麦 20 增产 5.9%。2019-2020 年度参加生产 试验，平均亩产 507.2 公斤，比对照扬麦 20 增产 5.0%。', '1、适宜播期 10 月 25 日至 11 月 10 日。2、适期播 种每亩基本苗 18 万左右，中低产田适当增加。3、一般亩施纯氮 18 公斤，其中基苗肥占 60%、拔节孕穗肥占 40%，同时配合施用磷钾肥，后期适 当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除 田间杂草。注意防治纹枯病、赤霉病、锈病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (265, 1, '镇麦19', '苏审麦20200025', '2020.11', 0, '江苏省农作物品种审定委', '江苏丘陵地区镇江农业科学研究所', '镇 9759/豫麦 29I 系，参试名称“镇 15085”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗直立，叶色中等，分蘖力较强。株型较紧凑，抗倒性较好。穗层整齐，熟相好。穗纺锤形，长芒、白壳、 红粒，籽粒粉质-半角质。区试平均结果:全生育期 201.6 天，比对照扬 麦 20 短 1.5 天。株高 75.9 厘米，每亩有效穗 30.8 万，每穗 37.9 粒，千 粒重 48.5 克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州 农业科学研究所鉴定:中抗赤霉病(接种鉴定中抗赤霉病，严重度 2.0、 2.5;自然发病鉴定中抗赤霉病，病指 4.0、0.0)，中感黄花叶病毒病，高 感纹枯病、白粉病、叶锈病、条锈病。经江苏省农业科学院种质资源与 生物研究所鉴定:高抗穗发芽。经农业部谷物品质监督检验测试中心测 定:容重 789g/L、777g/L，粗蛋白(干基)15.1%、12.9%，湿面筋 33.6% 、 36.2%，吸水率 62%、62%，稳定时间 2.2min、2.0min，最大拉伸阻力 116E.U.、108E.U.，拉伸面积 30cm2、28cm2，硬度指数 50、55。产量和抗性表现：2017-2019 年度参加江苏省淮南小麦里下河农科所科企联 合体区试，两年平均亩产 499.0 公斤，比对照扬麦 20 增产 4.1%。2019-2020 年度参加生产试验，平均亩产 492.1 公斤，比对照扬麦 20 增产 1.4%。', '1、适宜播期 10 月 30 日至 11 月 10 日。2、适期播 种每亩基本苗 18 万左右，中低产田适当增加。3、一般亩施纯氮 18 公斤， 其中基苗肥占 60%、拔节孕穗肥占 40%，同时配合施用磷钾肥，后期适 当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除 田间杂草。注意防治纹枯病、赤霉病、白粉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (266, 1, '镇麦1号', '苏种审字第180号', '1993', 0, '江苏省农作物品种审定委员会', '镇江地区农科所', '镇7853/苏麦1号', '江苏淮南麦区', '退出批次：特征特性：幼苗直立， 发苗快，每茂性好。株型较松，株高92厘米左右，茎秆较细稍软。叶狭长叶色偏淡，返青拔节期叶色落黄较快。中、后期叶色由谈转深绿。分蘖率、成穗率均较高，穗数较多，每亩31万穗左右，穗长方形，长芒、白壳、橙黄粒，每穗33.0粒左右.籽粒椭圆形，半硬质，千粒重37克左右，籽粒饱满，容重766克/公升.经测试，出粉率69.6%，湿面筋含量37.5%，干面筋11.3%、粗蛋白含量达14。5%，吸水率60%，面团稳定时间表2.3分钟，面粉综合评分34分，稍高于扬麦5号，适于作饼干专用粉.全生育期209天，抗白粉病，中抗赤霉病.抗寒性较好。不抗梭条花叶病毒病，抗现性欠佳，后期易；罹蚜虫。产量和抗性表现：1990、1991年连续两年参加省淮南片小麦品种区域试验。平均单产分别为316.1公斤和292.8公斤，比扬麦5号分别增产10.0%(达极显著)和0.26%(不显著).1992年省生产试验平均单产382.7公斤，比杨麦5号增产2.9%，', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (267, 1, '镇麦21', '苏审麦20220010', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏丘陵地区镇江农业科学研究所', '镇麦9号/镇麦8号', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，分蘖力一般。株型较紧凑，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒角质。省区域试验平均结果：全生育期207.7天，比对照扬麦20短1.4天，株高82.6厘米，每亩有效穗33.3万，每穗37.4粒，千粒重45.6克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.30、2.20；自然发病鉴定中抗赤霉病，病指0.26、3.32），高感纹枯病、白粉病，中感黄花叶病毒病，中抗叶锈病、条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重816g/L、803g/L，粗蛋白质含量（干基）15.39%、15.24%，湿面筋含量32.9%、31.3%，吸水率64%、63%，稳定时间11.0min、5.7min，最大拉伸阻力424E.U.、285E.U.，拉伸面积94cm2、78cm2，硬度指数68.3、67.2。2020年品质检测结果达到中强筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮南A组小麦品种区域试验，两年平均亩产516.1公斤，比对照扬麦20增产4.3%。2020-2021年度参加生产试验，平均亩产486.9公斤，比对照扬麦20增产4.5%。', '1、适宜播期10月25日至11月10日。2、基本苗适期播种每亩18万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (268, 1, '镇麦25', '苏审麦20220008', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏丘陵地区镇江农业科学研究所', '扬辐麦8004/保计0601', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗半直立，分蘖力较强。株型较紧凑，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒角质。省区域试验平均结果：全生育期210.2天，比对照扬麦20短1.6天，株高90.3厘米，每亩有效穗32.2万，每穗39.8粒，千粒重45.5克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.16、2.05；自然发病鉴定中抗赤霉病，病指0.11、3.75），高感纹枯病、白粉病，感黄花叶病毒病，中感叶锈病，中抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重810g/L、802g/L，粗蛋白质含量（干基）13.7%、15.4%，湿面筋含量32.7%、32.2%，吸水率63%、63%，稳定时间5.2min、10.2min，最大拉伸阻力306E.U.、506E.U.，拉伸面积73cm2、120cm2，硬度指数67.7、66.5。2021年品质检测结果达到强筋小麦品种标准。产量和抗性表现：2019-2021年度参加江苏省淮南B组小麦品种区域试验，两年平均亩产514.0公斤，比对照扬麦20增产5.2%。2021-2022年度参加生产试验，平均亩产548.1公斤，比对照扬麦20增产3.5%。', '1、适宜播期10月25日至11月10日。2、基本苗适期播种每亩18万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (269, 1, '镇麦26', '苏审麦20220024', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏丘陵地区镇江农业科学研究所', '扬辐麦8004/保计0601', '通过审定，适宜在江苏省淮南麦区种植。', '特征特性：春性小麦品种。幼苗直立，分蘖力较好。株型半紧凑，穗层整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒半角质。联合体区域试验平均结果：全生育期203.2天，比对照扬麦20短2.7天，株高86.3厘米，每亩有效穗31.6万，每穗37.8粒，千粒重46.1克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度1.30、1.20；自然发病鉴定中抗赤霉病，病指1.39、8.33），高感白粉病、叶锈病，感纹枯病，中感黄花叶病毒病，中抗条锈病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高抗穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重796g/L、795g/L，粗蛋白质含量（干基）14.6%、15.4%，湿面筋含量32.8%、33.0%，吸水率57%、58%，稳定时间4.3min、3.9min，最大拉伸阻力311E.U.、299E.U.，拉伸面积79cm2、71cm2，硬度指数49.5、49.1。产量和抗性表现：2019-2021年度参加江苏里下河科企联合体淮南小麦品种区域试验，两年平均亩产516.4公斤，比对照扬麦20增产5.8%。2021-2022年度参加生产试验，平均亩产571.2公斤，比对照扬麦20增产5.6%。', '1、适宜播期10月25日至11月10日。2、基本苗适期播种每亩18万左右，推迟播种或中低产田适当增加。3、一般亩施纯氮16公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (270, 1, '镇麦3号', '苏种审字第384号', '2000', 0, '江苏省农作物品种审定委员会', '江苏丘陵地区镇江农科所', '“K28”群体系选', '江苏淮南麦区', '退出批次：特征特性：该品种幼苗直立，叶片短宽，春性较强，抗寒性较弱。分蘖性及成穗率一般。株高85厘米左右，株型紧凑。茎秆粗壮，耐肥抗倒性较强。该品种亩有效穗30万左右，每穗粒数36粒左右，千粒重37克左右。长芒、白壳、长方型穗，穗形较大，籽粒白色，较耐穗发芽。该品种中感一中抗赤霉病，中感一感白粉病，中感纹枯病，感梭条花叶病，中抗叶锈病。该品种容重777克/升，蛋自质含量13.9％，湿面筋含量37.2％，沉降值47毫升，降落值343秒，吸水率57.7％，面团形成时间为2.3分钟，稳定时间为3.1分钟，断裂时间为3.5分钟，粉质评价值44分（南京经济学院，1999），属中筋力小麦品种。产量和抗性表现：该品种1997—2000年度参加江苏省淮南小麦中间试验。1997—1998年度省区试平均亩产248.78公斤，比对照扬麦158减产5.38％，达极显著水平；1998—1999年度省区试平均亩产352.15公斤，比对照减产4.95％，达极显著水平；1999—2000年度参加省准南小麦生产试验，平均亩产403.24公斤，比对照扬麦158增产5.11％。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (271, 1, '镇麦4号', '苏审麦200305', '2003', 0, '江苏省农作物品种审定委员会', '江苏省丘陵地区镇江农科所', '扬麦158/镇麦1号', '江苏省淮南麦区', '退出批次：特征特性：该品种长芒、白壳、纺锤型穗，籽粒红皮、半硬到硬质，分蘖成穗数一般，穗粒结构较协调，每亩有效穗28万左右，每穗粒数近40粒，千粒重40克左右，容重795克左右。株高90厘米左右，较耐肥抗倒，成熟期较扬麦158迟1天。中抗赤霉病、白粉病中等偏重，纹枯病较重，高抗梭条花叶病毒病。据2002年南京经济学院检测：粗蛋白含量12.92%，湿面筋33.8％，形成时间2.2分钟，稳定时间3.8分钟，属中筋品种。产量和抗性表现：1999-2001年参加省区域试验，1999-2000年度平均亩产401.30公斤，较对照扬麦158减产0.8％，不显著，居第4位；2000-2001年度平均亩产409.11公斤，较对照扬麦158增产3.68％，极显著，居第3位；两年平均亩产405.38公斤，较对照增产1.46%，不显著，居第2位。2001-2002年度参加淮南红皮小麦生产试验，平均亩产378.43公斤，较对照扬麦158增产11.09%，居第1位。该品种有一定产量水平，抗病性较好，品质优。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (272, 1, '镇麦5号', '苏审麦200406', '2004.8', 0, '江苏省农作物品种审定委员会', '江苏丘陵地区镇江农科所', '扬麦158/宁麦9号', '江苏省淮南麦区', '退出批次：特征特性：该品种长芒、白壳、纺缍型穗，籽粒红皮、硬质；幼苗直立，株型较紧凑；全生育期较扬麦158长1天，株高93厘米左右，耐肥抗倒性一般；每亩有效穗30万左右，每穗33粒左右，千粒重38克左右。接种鉴定中抗赤霉病，感纹枯病，抗梭条花叶病毒病，抗病性好于扬麦158。品质分析三年平均结果为粗蛋白含量14.3%，湿面筋含量30.6%，稳定时间3.4分钟，属中筋品种。产量和抗性表现：2001-2003年度参加江苏省区域试验，两年平均亩产337.4公斤，较对照扬麦158增产7.30%，两年增产均达极显著水平；2003-2004年度组织生产试验，平均亩产400.7公斤，较对照扬麦158增产9.28%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (273, 1, '镇麦6号', '苏审麦200501', '2005.9', 0, '江苏省农作物品种审定委员会', '江苏丘陵地区镇江农业科学研究所', '扬麦158/镇麦1号', '江苏省淮南麦区中上等肥力条件下种植。', '退出批次：特征特性：该品种长芒、白壳、纺锤型穗，籽粒红皮、粉质。幼苗直立，分蘖力中等，株型较紧凑，株高88厘米左右，耐肥抗倒性较好。全生育期212天左右,较扬麦158长2天。每亩有效穗29万左右，每穗39粒左右，千粒重38克左右。接种鉴定中感赤霉病、纹枯病、白粉病，感梭条花叶病毒病。品质分析三年平均结果：粗蛋白含量15.1%，湿面筋含量30.6%，稳定时间3.9分钟，属中筋品种。产量和抗性表现：2002-2004年度参加江苏省区域试验，两年平均亩产378.57公斤，比对照扬麦158增产5.60％。2004-2005年度生产试验平均亩产418.03公斤，较对照扬麦158增产8.58%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (274, 1, '镇麦7859', '苏种审字第71号', '1986', 0, '江苏省农作物品种审定委员会', '镇江市农科所', '河南6729/扬麦3号', '江苏淮南麦区', '退出批次：特征特性：幼苗半直立，叶色青绿，生长繁茂健壮。株高约80.9厘米左右。比扬麦四号矮15.6厘米左右。株型较紧凑，茎杆粗壮稍脆，较耐肥抗倒。叶片较宽较挺。叶色青绿。分蘖力中等略强，成穗率较高。省中间试验亩穗数平均32万左右，成穗率50.7%，比扬麦四号高5%左右。穗型中等偏大，穗短粒密，长芒、白壳、红粒，每穗平均32.28—33.4粒。籽粒短圆略小，千粒重32克左右，虽偏低但变幅较小。与扬麦三号相比穗数（略少0.48万）、粒重相仿。但粒数增加1.78粒。与扬麦四号相比为两增一减，穗数增3~4万，省区域试粒数增2.2粒（省生产试验相仿），仅粒重低4—5克。容重700克/升左右，分别比杨麦三号、四号低35克/升左右；比宁麦三号高10.1克/升左右。籽粒半硬质品质尚好粗蛋白含量12.07—12.24%，赖氮酸含量达0.39%，精粉率74.7%，灰分2.18%，湿面筋含量32%左右，较适宜做面条、饺皮。全生育期207.2天，省区试与扬麦三号、四号相仿，省生产试验比扬四略迟熟2天左右。但明显比宁麦三号早熟5天左右。冬前生长较快，冬后长势稍弱。后期灌浆速度较快。穗、粒、重较协调而稳定。在中高肥水平的早中茬有拉产潜力，间套作能明显。中后期对肥水较敏感，较易感病为其主要缺点。白粉病、纹枯病、赤霉病均较重，中感条锈、叶锈病。产量和抗性表现：1983年—84年连续两年参加淮南片小麦区域试验，1983年单产548.05斤分别比扬麦三号增产18.39%，比宁麦一号增产品6.56%。1984年单产694.2斤，分别比扬麦三号增产14.31%，比宁麦三号增产16.08%，比扬副麦四号增产11.36%，均达极显著标准。1985年省生产试验亩产514.2斤，比扬麦四号略增。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (275, 1, '镇麦9号', '苏审麦201001', '2010.1', 0, '江苏省农作物品种审定委员会', '江苏丘陵地区镇江农科所', '苏麦6号/97G59', '适宜江苏省淮南麦区种植', '退出批次：特征特性：幼苗直立，叶片宽挺，色深分蘖力较强，成穗数中等，抗寒性较强株型稍松散，耐肥抗倒性强穗层整齐，后期熟相好纺锤型穗，小穗排列稍稀长芒、白壳、红粒，籽粒长卵形、硬质、饱满度好，千粒重高区试平均结果：全生育期208.8天，较对照迟熟2-3天；株高85.8厘米，每亩有效穗30.3万穗，每穗37.0粒，千粒重45.9克接种鉴定结果：中抗赤霉病、白粉病，中感纹枯病，中抗黄花叶病经农业部谷物品质监督检验测试中心测定，2007-2009年度两年平均结果：容重783克/升，粗蛋白含量13.63%，湿面筋含量27.5%，稳定时间16.8分钟产量和抗性表现：2007-2009年度参加江苏省区域试验，平均亩产509.9公斤，较对照扬麦11号增产5.6％2009-2010年度参加生产试验，平均亩产432.6公斤，较对照扬麦11号增产9.1%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (276, 1, '陕229', '苏种审字第225号', '1994', 0, '江苏省农作物品种审定委员会', '引自陕西', '陕7853/80356', '江苏淮北麦区', '退出批次：特征特性：幼苗匍匐，叶细窄、色深绿。株高85—90厘米，株型较松，根系发达，茎秆稍高，较细软，弹性尚好，叶片上短窄上举，叶黄绿色。分蘖力强，成穗率较高，亩有效穗达42—47万穗。前期地上部生长稳健，发育较迟缓。拔节较迟，比冀84—5418迟7—8天，而拔节后生长发育速率加快。穗层整齐。长芒、白壳、穗纺锤形，穗短粒密，结实性好，每穗实粒32—36粒。足穗多粒，灌浆速度较快，籽粒较短，尖椭圆形，较饱满期，色泽白亮，偏角质。腹沟浅，粒重偏低，千粒重36—38克，容重较高，780—800克/公升。粗蛋白含量14.25%，湿面筋含量35%，干面筋含量19.5，评价值46，面积量多质量较好，属中强力粉。生育期238天左右（省区试）比冀84—5418迟1.7天左右。抗旱性好，耐干热风，连续干旱叶片不易干枯，无逼熟现象，成熟落黄正常，熟相好，抗寒性好，越冬性良好，遇“倒春寒仍结实性良好，经陕西、江苏两小植保所鉴定：高抗条锈病，中抗雪霉叶枯病、根腐病，抗纹枯病（病指2.8，在参试品种中最低，属R级）对白粉病属慢粉性，常年田间发病较迟缓，对灌浆影响不大，中感叶锈病、赤露病、茎秆较细软，抗倒性一般。种子休眠期较短，产量和抗性表现：1991—1993年连续两年参加淮北小麦新品种区域试验，平均单产分别为447.98公斤、436.0公斤，比冀84—5418减产4.6%(不显著)、增产5.57%(极显著).两年平均单产441.39公斤，比冀84—5418增产0.89%。1994年度参加省生产试验，平均单产437.6公斤，较冀84—5418增产19.03%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (277, 1, '陕7859', '苏种审字第144号', '1991', 0, '江苏省农作物品种审定委员会', '陕西省农科院作物所', '7576/327/68811(2)-2', '江苏淮北麦区', '退出批次：特征特性：幼苗半直立，叶色偏深。株高90厘米左右，株型较紧凑，茎杆弹性较好。分蘖力、成穗率均为中等，省中间试验平均每亩穗数为38.40万穗，比济南13少5.30万穗。长芒、白壳、穗长纺锤形，穗中等偏大，穗大码稀，每穗实粒数平均27.0粒，半角质，籽粒大而饱满，外观商品性好。千粒重高，平均41.9克左右。品质良好，粗蛋白含量达13.1—15.7%，赖氨酸含量0.36%，干面筋含量11.25。弱冬性，全生育期236天左右，比济南13早熟三天左右，熟相好。抗寒性、抗倒性中等，较抗西南早风（干热风）。抗条锈、秆锈病。中感叶锈、纹枯、赤霉病，白粉病较重。较易遭蚜虫危害，受倒春寒影响，易导致结实率下降。产量和抗性表现：1988、1980年连续两年参加省准北不麦品种区试，平均亩产分别为370.83公斤、352.75公斤，分别比济南13减产5.8%、增产5.6%，均达极显著标准，两年平均亩产361.79公斤，比济南13减0.1%，不显著。1990年省生产试验平均亩产366.9公斤，比济南13号增产10.25%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (278, 1, '隆麦28', '苏审麦20160002', '2017.11', 0, '江苏省农作物品种审定委员会', '江苏天隆科技有限公司', '扬辐麦2号/宁麦8号', '江苏省淮南麦区无黄花叶病毒病田块种植', '特征特性：春性中熟小麦品种，成熟期比对照扬麦11晚近1天。幼苗直立，叶色较深，分蘖力中等。株型半紧凑，抗倒性中等。穗层整齐，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒半硬质。区试平均结果：全生育期207.5天，株高83.0厘米，每亩有效穗33.0万，每穗37.3粒，千粒重41.9克。经江苏省农科院植保所三年接种鉴定：中抗赤霉病（严重度1.76-2.11），感纹枯病、白粉病，高感黄花叶病。经江苏省农科院粮作所鉴定：中抗穗发芽。品质经农业部谷物品质监督检验测试中心测定，两年平均结果：容重795克/升，粗蛋白含量14.68%，湿面筋含量31.7%，稳定时间9分钟，硬度指数65.7。产量和抗性表现：2013-2015年度参加江苏省淮南组小麦区域试验，两年平均亩产483.9公斤，较对照扬麦11增产6.3%，两年均达极显著水平。2015-2016年度参加生产试验，平均亩产464.7公斤，较对照扬麦20增产5.1%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗15万左右，中低产田适当增加。3、一般亩施纯氮15公斤左右，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (279, 1, '隆麦30', '苏审麦20210021', '2021.12', 0, '江苏省农作物品种审定委员会', '江苏天隆科技有限公司', '镇麦168/华麦5号，参试名称“隆麦30”', '江苏省淮南麦区', '特征特性：春性小麦品种。幼苗半直立，叶色中等，分蘖力中等。株型较松散，抗倒性较好。穗层较整齐，熟相较好。穗纺锤形，长芒、白壳、红粒，籽粒半角质。区试平均结果：全生育期202.5天，比对照扬麦20短0.6天。株高81.5厘米，每亩有效穗30.2万，每穗41.2粒，千粒重43.9克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（接种鉴定中抗赤霉病，严重度2.57、1.90、1.70；自然发病鉴定中抗赤霉病，病指0.60、1.05、5.68），中感条锈病、黄花叶病毒病，高感纹枯病、叶锈病，感白粉病。经江苏省农业科学院种质资源与生物研究所鉴定：高抗穗发芽。经农业部谷物品质监督检验测试中心测定：容重796g/L、790g/L，粗蛋白(干基)含量13.5%、14.9%，湿面筋含量29.5%、33.6%，吸水率54.6%、55.9%，稳定时间2.8min、8.7min，最大拉伸阻力289E.U.、518E.U.，拉伸面积68cm2、112cm2，硬度指数47.7、51.9。产量和抗性表现：2018-2020年度参加江苏省淮南小麦神农大丰企业联合体区试，两年平均亩产460.7公斤，比对照扬麦20增产4.3%。2020-2021年度参加生产试验，平均亩产460.5公斤，比对照扬麦20增产5.8%。', '1、适宜播期10月25日至11月5日。2、适期播种每亩基本苗16万左右，中低产田适当增加。3、一般亩施纯氮18公斤，其中基苗肥占60%、拔节孕穗肥占40%，同时配合施用磷钾肥，后期适当喷施叶面肥。田间沟系配套，防止明涝暗渍。4、冬前及早春及时防除田间杂草，注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (280, 1, '隆麦39', '苏审麦20190007', '2019.11', 0, '江苏省农作物品种审定委员会', '江苏天隆科技有限公司、江苏里下河地区农业科学研究所', '内麦9号/扬辐麦5号F1辐照，参试名称“隆麦39”', '江苏省淮南麦区', '特征特性：属春性中熟小麦品种。幼苗直立，叶色绿。分蘖力中等，抗寒性较好。株型松散，穗层较整齐，抗倒性较好，熟相好。穗纺锤形，长芒、白壳、红粒，籽粒半硬质。区试平均结果：全生育期201.3天，比对照扬麦20早熟1.1天。株高83.6厘米，每亩有效穗31.8万，每穗41粒，千粒重41.9克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所鉴定：中抗赤霉病（单花滴注鉴定中抗赤霉病，严重度2.0、1.9；自然发病鉴定中抗赤霉病，病情指数0.2、4.94），高感白粉病、纹枯病、叶锈病，中抗条锈病，抗黄花叶病。经江苏省农业科学院种质资源与生物技术研究所鉴定：抗穗发芽。品质经农业部谷物品质监督检验测试中心测定：容重770g/L、794g/L，蛋白质（干基）13.94%、14.34%，湿面筋29.2%、28.1%，吸水率54.0%、56.1%，稳定时间7.4min、5.4min，最大拉伸阻力680E.U.、335E.U.，拉伸面积128cm2、86cm2，硬度指数50.8、50.9。产量和抗性表现：2016-2018年度参加江苏省淮南组小麦品种区域试验，两年平均亩产495.89公斤，比对照扬麦20增产4.19%。2018-2019年度参加生产试验平均亩产494.79公斤，比对照扬麦20增产4.33%。', '1、适宜播期10月25日-11月10日。2、适期播种每亩基本苗18万左右，推迟播种或肥力水平偏低应适当增加基本苗。3、一般亩施纯氮15-18公斤，配合施用磷、钾肥。氮肥基苗肥占60%，拔节孕穗肥占40%，抽穗扬花后结合防治病虫害喷施叶面肥。田间沟系配套，注意防涝抗旱。4、冬前及早春及时防除田间杂草。注意防治纹枯病、赤霉病、白粉病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (281, 1, '鲁麦15', '苏种审字第248号', '1996', 0, '江苏省农作物品种审定委员会', '江苏省种子站、徐淮连站引进', 'T9(扬1B1/7573318)F1/101-14', '江苏淮北麦区', '退出批次：特征特性：幼苗半匍匐，繁茂性好，生长势较强。株高83—88厘米，株型较紧凑，茎秆弹性一般，穗下节较长，抗倒性秒差，叶片回头宽挺，色偏淡，剑叶较窄挺，透光性良好。分蘖力较强，成穗率较高，春发性好，两极分化较早，亩有效穗38万左右。穗层整齐度较好。穗近长方形，疏长穗，结实性好，平均每穗8.8粒，长芒、白壳、白粒，籽粒椭圆形，半角质，均匀白亮，大而饱满，商品性好，千粒重41克左右，容重771—780克/左升，品质较好，经测定，粗蛋白含量13.15，湿面筋含量44.25，干面筋含量14.7%，分别比冀84—5418高3.0、1.4和4.6个百分点，面粉白度产。该品种属半冬偏春性，中熟类型。全生育期237天，比冀84—5418迟熟1.5天，后期叶片功能期长，耐干热风，灌浆快，熟相好。经省农科院植保所和徐州所鉴定，高抗土传花叶病毒病，抗条锈病，田间赤霉病较轻。其产量三要素较协调，纹枯病偏重，抗寒性中等，遇到春寒有冻害。忌高肥、早播、密播。产量和抗性表现：1993—1995年连续两年参加省准北小麦品种区域试验，因省区试系冬水组，播期早8—10天，该品种冻害偏重而减产，两年平均单产分别为383.09公斤和401.2公斤，分别经冀84-5418减产5.47%（不显著）和3.3%（不显著）；1994年—1995年同时参加省生产试验，在播期适宜的条件下，平均单产443.0公斤，比对照增产6.3%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (282, 1, '鲁麦7号', '苏种审字第119号', '1989', 0, '江苏省农作物品种审定委员会', '烟台地区农科所', '洛夫林/维尔//如罗///蚰包', '江苏淮北麦区北部', '退出批次：特征特性：幼苗半匐伏，生长势较弱，越冬性了，叶色深绿。株高80厘米左右，株型松散，茎杆粗硬，耐肥抗倒性明显好于济南13号。叶片较宽大，分蘖力中等偏强，成穗率较高，平均每亩有效穗43万左右，经济南13号略低2.5万左右。穗纺锤形、短芒、白壳、白粒，穗型中等稍短，着粒较密，每穗平均28.65粒在工，比济南13号多4.6粒。千粒重较高，且较稳定；一般在42.15克左右，与济南13号相仿。容重786克/升（高的达810克/升）。半硬质，品质较好。半冬性，全生育期236.5天，比济南13号迟一天左右。耐寒性好，较耐西南旱风，迂干旱叶片有干尖现象。苗期耐湿性较差。高抗杆绣病，耐花叶病毒病，感条绣、叶绣和白粉病。但常年田间发病较迟而轻，晚播、高肥情况下则病害加重。颖枯病略重，中感赤霉病。收获有及时有断穗现象，口紧脱粒困难。丰产性、稳产性较突出，增产潜力较大。但后期对肥反应较敏感，肥水不足时，穗数减少，穗形变小，穗顶部、基部小穗退化，难以发挥其增产潜力。产量和抗性表现：1986、1987年连续两年参加省区域试验。平均亩产分别为376.1公斤和428.9公斤，比济南13增产6.13%、4.36%，均达极显著水准。1988年参加省小麦生产试验，平均亩产453.34公斤，比济南13号增产12.2%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (283, 1, '黄淮麦998', '苏审麦20220015', '2023.01', 0, '江苏省农作物品种审定委员会', '江苏黄淮种业有限公司', '淮麦33/HA68', '通过审定，适宜在江苏省淮北麦区种植。', '特征特性：半冬性小麦品种。幼苗半匍匐，叶色深绿。分蘖力较强，株型较紧凑，蜡质重，穗层整齐，剑叶挺，熟相较好。穗纺锤型，长芒、白壳、白粒，籽粒角质。省区域试验平均结果：全生育期228天，比对照淮麦20长0.2天，株高86.5厘米，每亩有效穗39.4万，每穗35.4粒，千粒重45.5克。经江苏省农业科学院植物保护研究所、江苏徐淮地区徐州农业科学研究所、江苏里下河地区农业科学研究所鉴定：中感赤霉病（接种鉴定中感赤霉病，严重度2.39、2.65；自然发病鉴定中感赤霉病，病指9.26、14.86），高感白粉病、叶锈病，感纹枯病，中感条锈病，抗黄花叶病毒病。经江苏省农业科学院种质资源与生物技术研究所鉴定：高感穗发芽。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）测定：容重829g/L、824g/L，粗蛋白质含量（干基）13.89%、14.13%，湿面筋含量35.2%、34.4%，吸水率63%、61%，稳定时间4.1min、3.4min，最大拉伸阻力165E.U.、169E.U.，拉伸面积36cm2、44cm2，硬度指数64.9、60.1。产量和抗性表现：2019-2021年度参加江苏省淮北A组小麦品种区域试验，两年平均亩产602.0公斤，比对照淮麦20增产6.1%。2021-2022年度参加生产试验，平均亩产630.6公斤，比对照淮麦20增产7.0%。', '1、适宜播期10月10日至25日。2、基本苗适期播种每亩14万-18万，推迟播种或中低产田适当增加。3、一般亩施纯氮15公斤左右，其中基苗肥占60%、拔节肥占20%、孕穗肥占20%，同时配合施用磷钾肥，后期适当喷施叶面肥。注意化控控高、防涝抗旱。4、冬前及早春及时防除田间杂草，注意防治纹枯病、白粉病、赤霉病、锈病和蚜虫等病虫害。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (284, 2, '东单98', '苏审玉200601', '2006.1', 0, '江苏省农作物品种审定委员会', '南京东宁农作物研究所', 'L4�834', '适宜江苏春夏播地区种植', '退出批次：特征特性：全生育期春播114天左右，夏播96天左右。出苗较齐，苗势较强，幼苗叶鞘紫色，叶片绿色，叶缘绿色。株型半紧凑，株高245厘米左右，穗位99厘米左右，成株叶片数20片左右。花药黄色，颖壳绿色，花丝绿色，穗长20.3厘米左右，穗粗4.5厘米左右，秃顶1.8厘米左右，每穗14行左右，每行34粒左右，籽粒黄色，粒型硬粒型，千粒重319.0克左右，出籽率84.4%左右，果穗有露尖现象。田间观察病害发生较轻，抗倒性较强。中国农业科学院作物科学研究所接种鉴定，抗大斑病、小斑病、纹枯病，高感矮花叶病。农业部谷物品质监督检验测试中心（北京）检测，容重713g/L，粗蛋白10.03%，粗脂肪4.04%，粗淀粉71.38%，赖氨酸0.37%。产量和抗性表现：2004-2005年参加江苏省区试，两年区试春播平均亩产498.0公斤，2004年较对照苏玉9号增产23.3%，极显著；2005年较对照苏玉19增产2.2%，显著。两年区试夏播平均亩产516.7公斤，2004年较对照苏玉9号增产26.4%，2005年较对照苏玉19增产12.7%，两年增产均极显著。2005年生产试验春播亩产513.2公斤，较对照苏玉19增产3.0%；夏播亩产432.7公斤，较对照苏玉19增产9.5%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (285, 2, '东甜玉1226', '苏审玉20190019', '2019.04', 0, '江苏省农作物品种审定委员会', '东台市农业科学研究所', 'H85×S56，参试名称“东甜1号”', '江苏各地', '特征特性：中熟半紧凑型超甜玉米。出苗整齐，叶鞘绿色，叶片绿色，叶缘绿色，株型半紧凑，花药黄色，颖壳绿色，花丝青色，果穗筒型，籽粒黄色，甜质型，穗轴白色。省区试平均结果：株高230厘米，穗位91厘米，成株叶片数19-20片，穗长20.2厘米，穗粗4.6厘米，每穗14.5行，每行35.4粒，千粒鲜重329克，鲜穗出籽率65.5%。春季播种至采收鲜穗约88天。倒伏倒折率0.5%。中国农科院作物研究所及江苏省农科院植保所接种鉴定：中抗大斑病，感小斑病，中抗茎腐病，高感纹枯病、粗缩病。江苏省鲜食玉米区域试验品种品尝鉴定：外观品质和蒸煮品质达到部颁鲜食甜玉米二级标准。扬州大学农学院检测：水溶性糖含量17.8%，还原糖含量10.0%，达到甜玉米标准（NY/T 523-2002）。产量和抗性表现：2016~2017年参加江苏省甜玉米区试，两年区试平均亩产鲜穗870.1公斤，平均比对照晶甜3号增产8.9%；2018年参加江苏省甜玉米生产试验，平均亩产鲜穗825.6公斤，比对照晶甜3号增产3.2%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500株左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量纯氮15公斤、五氧化二磷4~5公斤、氧化钾7.5~10公斤。基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕，做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。用高效低毒低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、纹枯病等。5、适时采收。一般在授粉后22~25天采收青穗。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (286, 2, '中农甜414', '苏审玉201305', '2013', 0, '江苏省农作物品种审定委员会', '中国农业大学', 'BS641W譈S638', '适宜江苏省各地种植', '退出批次：特征特性：出苗整齐，叶鞘绿色，叶片绿色，株型半紧凑，花药青色，颖壳青色，花丝青色，果穗筒形，籽粒黄白相间（约3/4黄粒、1/4白粒），超甜硬粒型，穗轴白色两年省区试平均结果：全生育期春播约87天，株高169厘米，穗位高65厘米，成株叶片数17片，穗长16.1厘米，穗粗4.5厘米，每穗14-16行，每行28粒，千粒鲜重292克，鲜出籽率67.7%，田间倒伏率10.0%中国农科院作物研究所接种鉴定：中抗大斑病，高感纹枯病、茎腐病、粗缩病省鲜食玉米区域试验品种品尝鉴定：外观品质和蒸煮品质达到部颁鲜食甜玉米一级标准；扬州大学农学院检测：水溶性糖含量18.7%，还原糖含量7.2%，达到甜玉米标准（NY/T 523-2002）产量和抗性表现：2010-2011年参加江苏省甜玉米区域试验，两年区试平均亩产鲜穗619.5公斤，比对照晶甜3号减产4.7%，减产不显著2012年生产试验平均亩产鲜穗639.2公斤，比对照晶甜3号减产2.0%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (287, 2, '中江玉1501', '苏审玉20190001', '2019.04', 0, '江苏省农作物品种审定委员会', '江苏中江种业股份有限公司', 'A241×F516，参试名称“ZJ1501”', '江苏淮南地区春播', '特征特性：中熟半紧凑型普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势较强。株型半紧凑，茎秆粗壮，成株叶色绿色，花药红色，颖壳紫色，花丝红色；果穗筒形，穗轴红色；籽粒黄色，半硬粒型。省区试平均结果：株高263厘米，穗位高102厘米；穗长17.2厘米，穗粗4.5厘米，秃尖长1.4厘米，每穗16.2行，每行33.3粒。千粒重273克，出籽率86.0%。全生育期120天。倒伏倒折率1.2%。中国农业科学院作物研究所及江苏省农科院植保所接种鉴定：中抗大斑病、南方锈病，感小斑病、茎腐病，高感纹枯病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重756克/升，粗蛋白10.42%，粗脂肪3.41%，粗淀粉76.85%，赖氨酸0.30%。产量和抗性表现：2016~2017年参加江苏省淮南普通玉米区试，两年区试平均亩产545.6公斤，比对照苏玉29增产5.2%，2018年参加江苏省淮南普通玉米生产试验，平均亩产594.2公斤，比对照苏玉29增产7.8%。', '1、适期播种。一般4月初播种。2、合理密植。适宜密度每亩4500株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (288, 2, '中江玉1601', '苏审玉20200001', '2020.06', 0, '江苏省农作物品种审定委员会', '江苏中江种业股份有限公司、江苏农林职业技术学院', 'M85×F518，参试名称“ZJ1601”', '江苏省淮南地区春播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势较强。株型半紧凑，总叶片数19片，茎秆粗壮，成株叶色绿色；花药黄色，颖壳绿色，花丝黄色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期119天，比对照苏玉29短2天。株高255厘米，穗位高113厘米；穗长16.3厘米，穗粗5.1厘米，秃尖长0.7厘米，每穗16.2行，每行36.5粒，千粒重305克，出籽率87.1%；空秆率2.1%，倒伏倒折率3.4%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：抗大斑病、小斑病；中抗腐霉茎腐病；感纹枯病、南方锈病；高感瘤黑粉病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重753克/升，粗蛋白10.7%，粗脂肪4.0%，粗淀粉73.3%，赖氨酸0.29%。产量和抗性表现：2017~2018年参加江苏省普通玉米淮南春播区试，两年平均亩产617.9公斤，比对照苏玉29增产14.5%。2019年参加生产试验，平均亩产748.4公斤，比对照苏玉29增产12.9%。', '1、适期播种。一般4月初播种。2、合理密植。适宜密度每亩3800株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、瘤黑粉病、南方锈病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (289, 2, '中江玉1701', '苏审玉20210002', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏农林职业技术学院、江苏中江种业股份有限公司', 'M88×F516', '江苏省淮南地区春播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势较强。株型半紧凑，茎秆粗壮，成株叶色绿色；花药红色，颖壳花绿色，花丝红色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期119.6天，比对照苏玉29短2.8天。株高268厘米，穗位高103厘米；穗长18.4厘米，穗粗4.7厘米，秃尖长1.9厘米，每穗15.8行，每行34.6粒；千粒重309克，出籽率86.5%；空秆率1.3%，倒伏倒折率2.6%。经江苏省农业科学院植保所接种鉴定：高抗腐霉茎腐病；抗大斑病、小斑病；中抗纹枯病；感南方锈病；高感瘤黑粉病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重748克/升，粗蛋白9.31%，粗脂肪3.72%，粗淀粉73.15%，赖氨酸0.30%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮南春播区试，两年平均亩产642.4公斤，比对照苏玉29增产10.3%。2020年参加生产试验，平均亩产597.8公斤，比对照苏玉29增产13.4%。', '1、适期播种。一般4月初播种。2、合理密植。适宜密度每亩4200株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (290, 2, '中江玉1号', '苏审玉200603', '2006.1', 0, '江苏省农作物品种审定委员会', '南京六合种子公司', 'P138�3372', '适宜江苏春夏播地区种植', '退出批次：特征特性：全生育期春播115天左右，夏播98天左右。出苗较齐，苗势较强，幼苗叶鞘紫红色，叶片绿色，叶缘紫色。株型半紧凑，株高219厘米左右，穗位88厘米左右，成株叶片数20片左右。花药紫色，颖壳紫色，花丝红色，穗长17.5厘米左右，穗粗4.8厘米左右，秃顶1.9厘米左右，每穗14行左右，每行33粒左右，籽粒黄色，粒型半马齿型，千粒重301.3克左右，出籽率84.4%左右。田间观察病害发生较轻，抗倒性较强。中国农业科学院作物科学研究所接种鉴定，中抗大斑病、矮花叶病、纹枯病，抗小斑病。农业部谷物品质监督检验测试中心（北京）检测，容重760g/L，粗蛋白11.28%，粗脂肪3.52%，粗淀粉70.47%，赖氨酸0.36%。产量和抗性表现：2004-2005年参加江苏省区试，两年区试春播平均亩产495.1公斤，2004年较对照农大108增产9.1%，极显著；2005年较对照郑单958增产4.6%，不显著。两年区试夏播平均亩产422.4公斤，2004年较对照农大108增产4.0%，显著；2005年较对照郑单958增产8.1%，极显著。2005年生产试验春播亩产500.0公斤，较对照郑单958增产3.6%；夏播亩产423.6公斤，较对照郑单958增产6.6%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (291, 2, '中江玉2号', '苏审玉200604', '2006.1', 0, '江苏省农作物品种审定委员会', '江苏中江种业股份有限公司', 'L4譑12', '适宜江苏春夏播地区种植', '退出批次：特征特性：全生育期春播111天左右，夏播93天左右。出苗较齐，苗势较强，幼苗叶鞘浅棕色，叶片绿色，叶缘紫色。株型半紧凑，株高232厘米左右，穗位99厘米左右，成株叶片数20片左右。花药浅红色，颖壳绿色，花丝浅红色，穗长18.5厘米左右，穗粗4.8厘米左右，秃顶2.5厘米左右，每穗14行左右，每行32粒左右，籽粒黄色，粒型硬粒型，千粒重334.4克左右，出籽率81.5%左右，果穗有露尖现象。田间观察病害发生较轻，抗倒性较强。中国农业科学院作物科学研究所接种鉴定，抗大斑病、小斑病、纹枯病，感矮花叶病。农业部谷物品质监督检验测试中心（北京）检测，容重740g/L，粗蛋白10.87%，粗脂肪4%，粗淀粉68.64%，赖氨酸0.39%。产量和抗性表现：2004-2005年参加江苏省区试，两年区试春播平均亩产488.7公斤，2004年较对照农大108增产6.9%，极显著；2005年较对照郑单958增产4.0%，不显著。两年区试夏播平均亩产470.6公斤，2004年较对照农大108增产21.3%，2005年较对照郑单958增产12.0%，两年增产均极显著。2005年生产试验春播亩产509.9公斤，较对照郑单958增产5.7%；夏播亩产429.2公斤，较对照郑单958增产8.1%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (292, 2, '中江玉6号', '苏审玉200801', '2008.1', 0, '江苏省农作物品种审定委员会', '江苏中江种业股份有限公司', '99102-1-2�78319', '适宜江苏省作春玉米种植', '退出批次：特征特性：出苗快而齐，苗势强，苗期叶鞘浅棕色，叶色绿，生长势较强，株型半紧凑，花药红色，颖片绿带紫色，花丝绿色，穗筒形，籽粒淡黄色，半马齿型，穗轴白色省区试平均结果：株高224厘米，成株叶片18片，穗位100厘米，穗长15.9厘米，穗粗4.7厘米，每穗14-16行，每行33粒，千粒重282.0克，全生育期114天田间观察，抗倒性一般中国农业科学院作物研究所接种鉴定，抗大斑病、小斑病、中抗纹枯病，江苏省农科院植保所接种鉴定感粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测，容重778g/L，粗蛋白9.40%，粗脂肪4.61%，粗淀粉73.34%，赖氨酸0.23%产量和抗性表现：2005-2007年参加江苏省春播玉米区试，三年平均亩产451.5公斤，比对照苏玉19增产2.3%；2005年减产显著，2006年增产显著，2007年增产极显著2007年生产试验平均亩产434.5公斤，比对照增产1.6%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (293, 2, '中江玉703', '苏审玉201102', '2011.3', 0, '江苏省农作物品种审定委员会', '江苏中江种业股份有限公司', 'A489譇20', '适宜在江苏省春播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，生长势较强，幼苗叶鞘浅棕色，叶片绿色，叶缘紫色株型半紧凑花药红色，颖片绿带紫色，花丝粉红色果穗圆筒形，籽粒黄色，半硬粒型，穗轴红色省区试平均结果：株高225厘米，成株叶片18片，穗位88厘米，穗长16.0厘米，穗粗4.7厘米，每穗16-18行，每行31粒，千粒重299.0克，出籽率85.7%，全生育期约118天，倒伏率9.9%中国农业科学院作物研究所接种鉴定：抗大、小斑病，中抗纹枯病，高感茎腐病及粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重761克/升，粗蛋白9.20%，粗脂肪3.87%，粗淀粉72.99%，赖氨酸0.31%产量和抗性表现：2008-2009年参加江苏省春播玉米区域试验，两年区试平均亩产485.3公斤，比对照苏玉19增产9.0%，2008年增产不显著，2009年增产极显著2010年生产试验平均亩产459.9公斤，比对照苏玉19增产5.0%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (294, 2, '中江玉99', '苏审玉 201501', '2015', 0, '江苏省农作物品种审定委员会', '江苏中江种业股份有限公司', 'A241譇533', '适宜江苏淮南地区春播种植', '退出批次：特征特性：幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强株型半紧凑成株叶色深绿；颖片青夹紫色，花药红色，花丝紫红色；果穗筒形，穗轴红色；籽粒黄色，半硬粒型省区试平均结果：株高249厘米，成株叶片19片，穗位高95厘米；穗长17.3厘米，穗粗5.0厘米，秃尖长0.7厘米，每穗16.1行，每行33粒千粒重326克，出籽率84.8%全生育期115天倒伏率4.3%病害经中国农业科学院作物研究所接种鉴定：中抗大斑病、茎腐病，高感纹枯病、粗缩病品质经农业部谷物品质监督检验测试中心（哈尔滨）检测：容重742克/升，粗蛋白9.91%，粗脂肪4.13%，粗淀粉75.00%，赖氨酸0.30%产量和抗性表现：2012-2013年参加江苏省普通玉米春播区域试验，两年区试平均亩产567.6公斤，2012年比对照苏玉20增产17.1%，2013年比对照苏玉29增产14.2%，两年增产均极显著2014年生产试验平均亩产547.6公斤，比对照苏玉29增产8.0%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (295, 2, '中种甜1号', '苏审玉200301', '2003', 0, '江苏省农作物品种审定委员会', '中种集团', 'CTIFX證TIM', '江苏省各地', '退出批次：特征特性：出苗快而齐，苗势强，幼苗叶片浓绿色。株型半紧凑，株高210厘米左右，穗位80厘米左右，花丝粉红，总叶片数20片，叶片深绿，后期熟相好。果穗长锥形，穗长17厘米，穗粗4.5厘米，无或少秃顶，每穗14-16行，每行33粒左右，鲜穗黄色，外观美。鲜粒黄色，甜度高，口味佳。全生育期春播108天左右，夏播92天左右，播种到吐丝76天左右。抗病抗逆性较强。产量和抗性表现：2000-2002年参加江苏省甜玉米中间试验。2000年平均亩产680.4公斤，比对照增产5.9%；2001年平均亩产656.3 公斤，比对照增产3.84%；2002年平均亩产656.0公斤，比对照减产0.5%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (296, 2, '中糯2号', '苏审玉200505', '2005.2', 0, '江苏省农作物品种审定委员会', '苏州市种子管理站', '中玉01×中玉05', '适宜江苏省各地种植', '退出批次：特征特性：春播播种至采收88天左右。出苗整齐，苗势强，幼苗叶鞘紫红色，叶片绿色，叶缘绿色。株型半紧凑，整齐度较好，株高201.4cm左右，穗位87.8cm左右，双穗率1.3%左右，空杆率2.8%左右，成株叶片数16-17片。花药黄色，颖壳绿色，花丝粉红色，果穗柱形，穗轴白色，穗长16.9cm左右，穗粗4.6cm左右，秃顶1.6cm左右，每穗14-15行左右，每行32粒左右，籽粒白色，千粒鲜重277g左右，鲜出籽率65.8%左右。田间表现，轻感玉米大、小斑病、病毒病、茎腐病，抗倒性较强。经省鲜食糯玉米品种区域试验组织的专家品尝鉴定，达到部颁鲜食糯玉米三级标准。经扬州大学农学院检测，支链淀粉占淀粉总量的98.43%，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2002-2003年参加江苏省区试，两年区试平均亩产鲜果穗746.8kg，比对照苏玉糯1号增产0.8%；2004年生产试验亩产824.9kg，比对照苏玉糯1号减产3.6%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (297, 2, '佳华909', '苏审玉20170004', '2017.04', 0, '江苏省农作物品种审定委员会', '淮安市金色天华种业科技有限公司', 'N3878×H2102，参试名称“JSTH7872”', '江苏省淮北地区夏播', '特征特性：中熟紧凑型普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强。成株株型紧凑，总叶片数19片左右；花药浅紫色，花丝绿色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：株高285厘米，穗位高113厘米；穗长16.9厘米，穗粗5.0厘米，每穗16.1行，每行32.9粒。千粒重310克，出籽率86.3%。全生育期103天。倒伏率0.3%。中国农业科学院作物研究所接种鉴定：抗大斑病，中抗茎腐病，感小斑病、纹枯病、南方锈病，高感瘤黑粉病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重778克/升，粗蛋白10.31%，粗脂肪3.65%，粗淀粉71.79%，赖氨酸0.30%。产量和抗性表现：2014-2015年参加江苏省普通玉米夏播区域试验，两年区试平均亩产590.1公斤，比对照郑单958增产4.8%。2016年生产试验平均亩产657.2公斤，比对照郑单958增产7.3%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000-4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20-25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、南方锈病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (298, 2, '保玉176', '苏审玉20200006', '2020.06', 0, '江苏省农作物品种审定委员会', '江苏保丰集团公司', 'G10-176×LH1802，参试名称“保玉1501”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘浅紫色，生长势较强。株型半紧凑，总叶片数21片左右；花药浅紫色，颖壳绿色，花丝浅紫色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期105天，比对照郑单958长1天。株高265厘米，穗位高89厘米；穗长17.1厘米，穗粗4.9厘米，秃尖长1.0厘米，每穗17.2行，每行31.2粒，千粒重330克，出籽率85.4%；空秆率0.9%，倒伏倒折率1.0%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：抗大斑病、小斑病、腐霉茎腐病；中抗南方锈病、瘤黑粉病；感纹枯病；高感粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重791克/升，粗蛋白11.4%，粗脂肪3.4%，粗淀粉72.7%，赖氨酸0.30%。产量和抗性表现：2017~2018年参加江苏省普通玉米淮北夏播区试，两年平均亩产611.1公斤，比对照郑单958增产7.9%。2019年参加生产试验，平均亩产618.7公斤，比对照郑单958增产5.1%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥40%，穗粒肥60%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (299, 2, '保玉18', '苏审玉20180001', '2018.05', 0, '江苏省农作物品种审定委员会', '江苏保丰集团公司', '99A671×LH1805，参试名称：保玉13309', '江苏省淮北地区夏播', '特征特性：中熟半紧凑型普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘暗紫色，生长势强。成株株型半紧凑，总叶片数19片左右；花药黄色，花丝绿色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：株高287厘米，穗位高129厘米；穗长17.3厘米，穗粗5.3厘米，每穗17.7行，每行35粒。千粒重299克，出籽率86.7%。全生育期105天。倒伏率12.2%。中国农业科学院作物研究所接种鉴定：中抗大斑病，感小斑病、纹枯病，高感腐霉茎腐病，抗南方锈病，高感瘤黑粉病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重730克/升，粗蛋白7.56%，粗脂肪4.75%，粗淀粉76.46%，赖氨酸0.26%。产量和抗性表现：2015~2016年参加江苏省普通玉米夏播区域试验，两年区试平均亩产672公斤，比对照郑单958增产8.9%。2017年生产试验平均亩产631.5公斤，比对照郑单958增产6.8%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20~25公斤，其中基苗肥40%，穗粒肥60%。做到田间沟系配套，注意防涝防旱防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、腐霉腐霉茎腐病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (300, 2, '保玉1号', '苏审玉201104', '2011.3', 0, '江苏省农作物品种审定委员会', '江苏保丰集团有限公司', '保夏70×齐319', '适宜在江苏省夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，叶鞘紫红色，生长势强，叶片深绿株型半紧凑花药浅绿色，颖片绿略带红边，花丝淡绿色果穗筒形，籽粒黄色，半硬粒型，穗轴白色省区试平均结果：株高238厘米，成株叶片19片，穗位94厘米，穗长18.3厘米左右，穗粗4.9厘米，每穗14-16行，每行37粒，千粒重307克，出籽率85.0%全生育期约98天，倒伏率3.3%中国农业科学院作物研究所接种鉴定：抗小斑病，高感纹枯病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重722克/升，粗蛋白9.86%，粗脂肪3.76%，粗淀粉73.07%，赖氨酸0.28%产量和抗性表现：2007-2009年参加江苏省夏播玉米区域试验，三年区试平均亩产511.1公斤，比对照郑单958增产3.1%，2007年和2009年增产均达极显著，2008年增产不显著2010年生产试验平均亩产495.8公斤，比对照郑单958增产9.4%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (301, 2, '元玉161', '苏审玉20200004', '2020.06', 0, '江苏省农作物品种审定委员会', '南通瑞德农业科技有限公司', 'TM065×RD153P', '江苏省淮南地区春播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，生长势强。株型紧凑，总叶片数18片；成株叶色深绿，花药紫色，颖壳淡紫色，花丝红色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期118天，比对照苏玉29短3天。株高253厘米，穗位高84厘米；穗长17.8厘米，穗粗4.8厘米，秃尖长1.4厘米，每穗15.6行，每行32.9粒，千粒重335克，出籽率85.8%；空秆率3.2%，倒伏倒折率3.6%。经中国农业科学院作物研究所（2017年）、江苏省农科植保所（2018年）接种鉴定：高抗大斑病；抗小斑病；中抗腐霉茎腐病；感纹枯病、瘤黑粉病、南方锈病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重752克/升，粗蛋白9.2%，粗脂肪3.9%，粗淀粉73.0%，赖氨酸0.26%。产量和抗性表现：2017~2018年参加江苏省普通玉米淮南春播区试，两年平均亩产583.0公斤，比对照苏玉29增产8.2%。2019年参加生产试验，平均亩产724.6公斤，比对照苏玉29增产9.3%。', '1、适期播种。一般4月初播种。2、合理密植。适宜密度每亩5000株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、瘤黑粉病、南方锈病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (302, 2, '先玉1980', '苏审玉20230002', '2023.06', 0, '江苏省农作物品种审定委员会', '铁岭先锋种子研究有限公司', 'PH43D5�1PGEZ69', '江苏省淮南地区春播', '特征特性：普通玉米品种。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势较强。株型半紧凑，茎秆粗壮，总叶片数20~21片，成株叶色绿色；花药浅紫色，花丝紫色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期118.7天，比对照苏玉29短2.0天。株高259.8厘米，穗位高105.6厘米；穗长18.2厘米，穗粗4.6厘米，秃尖长0.8厘米；每穗15.0行，每行36.2粒；千粒重333.2克，出籽率87.8%；空秆率0.9%，倒伏倒折率2.1%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病、纹枯病，中抗腐霉茎腐病、南方锈病、穗腐病，感弯孢菌叶斑病、瘤黑粉病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重754克/升，粗蛋白10.65 %，粗脂肪3.54 %，粗淀粉70.76 %，赖氨酸0.36 %。产量和抗性表现：2020~2021年参加江苏省普通玉米淮南春播区试，两年平均亩产669.0公斤，比对照苏玉29增产16.6%。2022年参加生产试验，平均亩产638.9公斤，比对照苏玉29增产6.7%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4200株左右。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、瘤黑粉病、弯孢菌叶斑病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (303, 2, '农单117', '苏审玉20230007', '2023.06', 0, '江苏省农作物品种审定委员会', '扬州大学', 'Y40×DK-7，参试名称“YH1110”', '江苏省淮北地区夏播', '特征特性：普通玉米品种。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数20~21片，成株叶色绿色；花药淡紫色，花丝红色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：全生育期101.1天，比对照郑单958长0.1天。株高224.0厘米，穗位高92.2厘米；穗长17.3厘米，穗粗4.6厘米，秃尖长0.6厘米；每穗16.0行，每行34.2粒；千粒重307.0克，出籽率86.2%；无空秆，无倒伏倒折。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病、弯孢菌叶斑病、穗腐病，中抗纹枯病，感腐霉茎腐病、瘤黑粉病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重800克/升，粗蛋白9.68%，粗脂肪4.00%，粗淀粉72.87%，赖氨酸0.31%。产量和抗性表现：2020~2021年参加江苏省普通玉米淮北夏播区试，两年平均亩产531.3公斤，比对照郑单958增产14.1%。2022年参加生产试验，平均亩产542.0公斤，比对照郑单958增产9.4%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4500~5000株左右。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好腐霉茎腐病、瘤黑粉病、南方锈病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (304, 2, '农科玉368', '苏审玉 201504', '2015', 0, '江苏省农作物品种审定委员会', '北京华奥农科玉育种开发有限责任公司', '京糯6×D6644', '适宜江苏各地种植', '退出批次：特征特性：出苗整齐，苗势强，叶鞘淡紫色，叶片绿色，株型半紧凑花药紫色，颖壳淡紫色，花丝淡紫色果穗锥形，籽粒白色，果穗甜糯籽粒分离为1∶3，穗轴白色江苏省区试平均结果：株高205厘米，穗位高84厘米，成株叶片数19片，穗长17.4厘米，穗粗4.8厘米，每穗13.8行，每行33粒，千粒鲜重331克，鲜穗出籽率65.7%，春季播种至鲜穗采收约88天田间倒伏率3.4%病害经中国农科院作物研究所接种鉴定：高抗茎腐病、中抗纹枯病、感大斑病、高感粗缩病江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到部颁鲜食糯玉米二级标准扬州大学农学院检测：支链淀粉占总淀粉的97.6％，达到糯玉米标准（NY/T524-2002）产量和抗性表现：2012-2013年参加江苏省糯玉米区试，两年区试平均亩产鲜穗804.4公斤，比对照苏玉糯5号增产7.2%；2014年参加江苏省糯玉米生产试验，平均亩产鲜穗805.2公斤，比对照苏玉糯5号增产8.5%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (305, 2, '农科甜1805', '苏审玉20210035', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏农科种业研究院有限公司', 'T4×J5', '江苏省各地', '特征特性：鲜食甜玉米。幼苗叶鞘绿色，叶片绿色，叶缘绿色，生长势强。株型半紧凑，成株叶色深绿；花药黄色，颖壳绿色，花丝青色；果穗锥形，籽粒黄色。省区试平均结果：出苗至采收鲜穗81.8天，比对照晶甜3号短0.3天。株高231厘米，穗位高90厘米；穗长19.3厘米，穗粗4.8厘米，秃尖长0.5厘米，每穗14.7行，每行37.8粒；千粒鲜重378克，鲜穗出籽率69.6%；空杆率0.4%，倒伏倒折率0.7%。经江苏省农业科学院植保所接种鉴定：中抗大斑病、瘤黑粉病；感小斑病；高感腐霉茎腐病、纹枯病、南方锈病。江苏省糯玉米联合体品种区域试验品尝鉴定：外观品质和蒸煮品质85.1分。扬州大学农学院检测：水溶性糖含量15.9%，还原总糖含量8.8%。产量和抗性表现：2018~2019年参加江苏省甜玉米区试，两年平均亩产鲜穗955.2公斤，比对照晶甜3号增产16.6%。2020年参加生产试验，平均亩产鲜穗839.0公斤，比对照晶甜3号增产13.8%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合施肥及时中耕，做好雍根培土以防倒伏。4、病虫害防治。用高效低毒残留农药及时防治地下害虫，食叶害虫、玉米螟、粗缩病、纹枯病等。5、适时采收。一般在授粉后18~25天采收青穗。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (306, 2, '农科花甜糯98', '苏审玉20200009', '2020.06', 0, '江苏省农作物品种审定委员会', '江苏农科种业研究院有限公司', 'W36×W62，参试名称“农科花糯98”', '江苏省各地', '特征特性：甜加糯型糯玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强。株型半紧凑，总叶片数19片，成株叶色深绿；花药黄色，颖壳紫色，花丝青色；果穗长锥形，籽粒花色。省区试平均结果：播种至采收鲜穗84天，比对照苏玉糯5号长2天。株高241厘米，穗位高111厘米；穗长20.0厘米，穗粗4.5厘米，秃尖长1.9厘米，平均每穗14.2行，每行37.0粒，千粒鲜重313克，鲜穗出籽率67.3%；空杆率0.7%。倒伏倒折率2.8%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：抗大斑病、瘤黑粉病；中抗小斑病、中抗腐霉茎腐病；感纹枯病；高感南方锈病、粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质85.6分。扬州大学农学院检测：支链淀粉占总淀粉的98.7%。产量和抗性表现：2017~2018年参加江苏省糯玉米区试，两年平均鲜穗亩产839.8公斤，比对照苏玉糯5号增产8.8%。2019年参加生产试验，平均鲜穗亩产834.6公斤，比对照苏玉糯5号增产6.8%。', '1、适期播种，根据上市时间和不同的栽培方式，合理安排播期。2、合理密植，适宜密度每亩4000株左右。3、加强肥水管理，有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合施肥及时中耕，做好壅根培土以防倒伏。4、病虫害防治。用高效低毒残留农药及时防治地下害虫、食叶害虫、小斑病、玉米螟等。5、适时采收。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (307, 2, '创玉115', '苏审玉20200003', '2020.06', 0, '江苏省农作物品种审定委员会', '创世纪种业有限公司', 'H35-2×王选4号', '江苏省淮南地区春播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强。株型紧凑，总叶片数18片左右；成株叶色深绿，花药绿色，颖壳浅紫色，花丝浅紫色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期119天，比对照苏玉29短2天。株高267厘米，穗位高100厘米；穗长17.3厘米，穗粗4.8厘米，秃尖长1.3厘米，每穗14.5行，每行31.2粒，千粒重353克，出籽率85.4%，空秆率1.7%，倒伏倒折率8.5%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：高抗大斑病；抗小斑病、瘤黑粉病；感腐霉茎腐病、纹枯病、南方锈病；高感粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重712克/升，粗蛋白10.2%，粗脂肪3.2%，粗淀粉75.0%，赖氨酸0.30%。产量和抗性表现：2017~2018年参加江苏省普通玉米淮南春播区试，两年平均亩产574.0公斤，比对照苏玉29增产6.5%。2019年参加生产试验，平均亩产735.3公斤，比对照苏玉29增产10.9%。', '1、适期播种。一般在4月初播种。2、合理密植。适宜种植密度每亩4000株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，一般每亩施纯氮20~25公斤、五氧化二磷10公斤、氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%。结合施肥及时中耕，做好培土壅根以防倒伏；做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、南方锈病、腐霉茎腐病、纹枯病等，注意倒伏倒折风险防范。5、适时收获，尽量在完熟期收获。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (308, 2, '华单1号', '苏审玉200205', '2002', 0, '江苏省农作物品种审定委员会', '省大华种子集团', '9014×齐319', '江苏作春、夏玉米种植', '退出批次：特征特性：该品种出苗较齐，苗势较强，生长稳健。株型半紧凑。株高242厘米，穗位高98厘米，穗位适中；果穗中等较大，筒型，穗长17厘米，穗粗4.6厘米；每穗平均14.4行，行粒数33.3粒，千粒重311.4克，出籽率85.7%；籽粒黄色偏硬粒型；春播全生育期111天，夏播94天。该品种抗倒性一般，抗病性较强，长相清秀，丰产稳产性较强。产量和抗性表现：2000-2001年参加江苏省春、夏播组玉米新品种区域试验。春播组两年平均亩产分别为566.30公斤和542.00公斤，比对照苏玉9号增产9.60%（极显著）和10.70%（极显著），分别居第1位及第4位；夏播组两年平均亩分别为498.30公斤和586.40公斤，比对照苏玉9号增产6.80%（极显著）和10.60%（极显著），均居第1位。2000年省玉米春、夏播组生产试验，平均亩产547.80公斤和608.70公斤，比对照苏玉9号增产12.50%和9.29%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (309, 2, '华太529', '苏审玉20190007', '2019.04', 0, '江苏省农作物品种审定委员会', '江苏润扬种业股份有限公司、莱州市太丰种业有限公司', 'T342B×T290', '江苏省淮北地区夏播', '特征特性：中熟紧凑型普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强。成株株型紧凑，总叶片数19片左右；花药浅紫色，花丝绿色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：株高239厘米，穗位高100厘米；穗长18.8厘米，穗粗5.1厘米，每穗16行，每行32.9粒。千粒重338克，出籽率86.9%。全生育期104天。倒伏倒折率1.1%。中国农业科学院作物研究所和江苏省农科院植保所接种鉴定：中抗大斑病、茎腐病、南方锈病，感小斑病、瘤黑粉病，高感纹枯病、高感粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重774克/升，粗蛋白10.01%，粗脂肪3.65%，粗淀粉74.44%，赖氨酸0.29%。产量和抗性表现：2016~2017年参加江苏省普通玉米夏播区域试验，两年区试平均亩产659.8公斤，比对照郑单958增产8.4%。2018年生产试验平均亩产590.1公斤，比对照郑单958增产9.2%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~-25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (310, 2, '华太736', '苏审玉20220013', '2022.08', 0, '江苏省农作物品种审定委员会', '山东太丰种业有限公司', 'T67×T436，参试名称“HT736”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。第一叶顶端形状为椭圆形，叶鞘黄色，叶色深绿，生长势强。株型紧凑，总叶片数19片左右；花药黄色，花丝黄色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期104.2天，比对照郑单958长0.3天。株高257.4厘米，穗位高104.3厘米；穗长17.8厘米，穗粗5.1厘米，秃尖长0.9厘米，每穗17.0行，每行33.2粒；千粒重347.8克，出籽率84.9%；空秆率0.8%，倒折倒伏率1.7%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病，中抗腐霉茎腐病、南方锈病，感纹枯病、瘤黑粉病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重778克/升，粗蛋白10.48%，粗脂肪3.75%，粗淀粉74.88%，赖氨酸0.27%。产量和抗性表现：2019~2020年参加江苏省普通玉米淮北夏播区试，两年平均亩产611.6公斤，比对照郑单958增产11.2%。2021年参加生产试验，平均亩产566.4公斤，比对照郑单958增产12.6%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、瘤黑粉病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (311, 2, '华太801', '苏审玉20220009', '2022.08', 0, '江苏省农作物品种审定委员会', '山东太丰种业有限公司', 'T67×T539，参试名称“HT801”', '江苏省淮北地区夏播', '特征特性：中早熟普通玉米。第一叶顶端形状为圆形，叶鞘黄色，叶色深绿，生长势强。株型紧凑，总叶片数19片左右；花药黄色，花丝黄色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期102.3天，比对照郑单958短1.0天。株高238.7厘米，穗位高100.4厘米；穗长18.5厘米，穗粗5.0厘米，秃尖长1.2厘米，每穗16.1行，每行36.2粒；千粒重321.6克，出籽率85.2%；空秆率0.1%，倒折倒伏率1.2%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病，中抗瘤黑粉病，感腐霉茎腐病、纹枯病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重752克/升，粗蛋白9.20%，粗脂肪3.31%，粗淀粉74.88%，赖氨酸0.25%。产量和抗性表现：2019~2020年参加江苏省普通玉米淮北夏播区试，两年平均亩产573.0公斤，比对照郑单958增产9.2%。2021年参加生产试验，平均亩产498.3公斤，比对照郑单958增产18.3%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、锈病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (312, 2, '华太903', '苏审玉20230003', '2023.06', 0, '江苏省农作物品种审定委员会', '山东太丰种业有限公司', 'T285×H3356，参试名称“T903”', '江苏省淮南地区春播', '特征特性：普通玉米品种。幼苗叶鞘浅紫色，叶色深绿，叶缘紫色 ，生长势较强。株型紧凑，茎秆粗壮，总叶片数19片左右，成株叶色绿色；花药浅紫色，花丝黄色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期117.5天，比对照苏玉29短3.2天。株高233.7厘米，穗位高91.1厘米；穗长19.1厘米，穗粗4.9厘米，秃尖长1.2厘米，每穗16.7行，每行35.0粒；千粒重316.0克，出籽率86.5%；空杆率0.5%，倒伏倒折率2.2%。经江苏省农业科学院植物保护研究所接种鉴定：高抗大斑病、小斑病、弯孢菌叶斑病，抗纹枯病、穗腐病，中抗腐霉茎腐病、瘤黑粉病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重764克/升，粗蛋白11.06%，粗脂肪3.58%，粗淀粉71.93%，赖氨酸0.35%。产量和抗性表现：2020~2021年参加江苏省普通玉米淮南春播区试，两年平均亩产635.2公斤，比对照苏玉29增产10.7%。2022年参加生产试验，平均亩产652.7公斤，比对照苏玉29增产9.1%。', '1、适期播种。春播一般4月15~30日。2、合理密植。适宜密度为4500株/亩左右。3、科学施肥。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥占60%，穗肥40%，肥力差的田块可适当施粒肥，中后期注意防涝防旱。4、病虫害防治。对种子进行药剂处理，注意防治地下害虫，做好玉米螟的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (313, 2, '华甜（玉）1号', '苏审玉200407', '2004', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', '355�3133', '适宜江苏各地种植', '退出批次：特征特性：出苗较慢，苗期长势中等，幼苗叶片深绿色，株型松散，总叶片数18张左右，株高230.3cm左右，穗位88.2cm左右，果穗筒型，大穗，穗长19.4cm左右，穗粗4.5cm左右，花丝绿色，有少量秃顶，秃顶长1.0cm左右，每穗14行左右，每行36粒左右，百粒鲜重46.7g左右，鲜穗黄色，外观美，籽粒黄色，半透明，甜度高，口味较好，色泽较好。全生育期春播100天左右。田间观察抗病性强，抗倒性一般。产量和抗性表现：该品种两年区试平均亩产鲜果穗765.9公斤，比对照淮甜8号增产18.7%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (314, 2, '华糯（玉）1号', '苏审玉200404', '2004', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'W589譈N6', '适宜江苏各地种植', '退出批次：特征特性：株型半紧凑，总叶片数19张左右，株高225.5cm左右，穗位95.5cm左右，双穗率4.4%左右，空杆率0.7%左右，植株田间整齐度较好。穗长18.6cm左右，穗粗4.6cm左右，秃顶1.6cm左右，每穗14行左右，每行35粒左右，百粒鲜重32.8g左右，鲜出籽率67.4%左右，硬粒型糯玉米。鲜穗白色，籽粒排列整齐；花丝紫红色，穗型为锥形，果穗适中，有秃顶，综合外观印象一般，糯性好，接近苏玉糯1号，略带甜味，籽粒不透明，口感较好，色泽好。春播鲜果穗成熟期108天左右，比对照苏玉糯1号迟1天。田间观察，抗病性强，抗倒性较强。产量和抗性表现：该品种两年区试平均亩产鲜果穗864公斤，比对照苏玉糯1号增产12.4%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (315, 2, '南农紫玉糯1号', '苏审玉200202', '2002', 0, '江苏省农作物品种审定委员会', '南农大农学院', '甜糯质群体自交', '江苏省各地', '退出批次：特征特性：该品种鲜果穗为淡紫红色，籽粒排列整齐；穗型为锥型，果穗偏细，有秃顶，综合外观印象较优；糯性较好，接近苏玉糯1号，甜度一般；该品种籽粒皮层较薄，果轴较细，风味浓郁，口感绵软，香味突出。春播鲜果穗成熟期为109天，对照苏玉糯1号迟2天。    该组合前期生长势一般，分蘖较多，耐旱性、抗倒性一般。该品种株高为205厘米，穗位88厘米，植株田间整齐度一般，株型半紧凑。穗长16.6厘米，穗粗4.0厘米，秃顶0.7厘米，每穗12.9行，每行35.4粒，锥型果穗，硬粒型糯玉米。产量和抗性表现：1999-2001年参加江苏省特种玉米新品种中间试验。1999-2000年两年区试平均亩产鲜果穗分别为710.40公斤和644.30公斤，比对照苏玉糯1号减产12.70%和9.50%，分别居第5位和第9位。2001年参加江苏省特种玉米生产试验，平均亩产鲜果穗787.50公斤，比对照苏玉糯1号减产6.76%。审定通过，适宜我省各地种植。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (316, 2, '南农紫黑糯', '苏审玉20170005', '2017.04', 0, '江苏省农作物品种审定委员会', '南京神州种业研究院有限公司', '黑3303×95-5', '江苏各地', '特征特性：半紧凑型糯玉米。出苗整齐，苗势强，叶片绿色，株型半紧凑；果穗锥形，籽粒紫色，糯质型。省区试平均结果：株高224厘米，穗位高109厘米；穗长16.8厘米，穗粗4.3厘米，每穗14.1行，每行33粒。千粒重273克。全生育期92天，比对照晚1天。鲜穗出籽率68.4%。倒伏率0.1%。中国农科院作物研究所接种鉴定：高抗纹枯病和茎腐病，抗小斑病，感大斑病，高感粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到鲜食糯玉米二级标准。扬州大学农学院检测：支链淀粉占总淀粉的97.4%，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2014-2015年参加江苏省糯玉米区域试验，两年区试平均亩产鲜穗733.8公斤，平均比对照苏玉糯5号减产1.6%。2016年生产试验平均亩产鲜穗735.3公斤，比对照苏玉糯5号增产1.1%。', '1、适期播种，根据上市时间和不同的栽培方式，合理安排播期。2、合理密植，适宜密度每亩4000株左右。3、加强肥水管理，有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合肥料及时中耕，做好雍根培土以防倒伏。4、病虫害防治。用高效低毒残留农药及时防治地下害虫，食叶害虫、玉米螟、粗缩病、纹枯病等。5、适时采收，一般在授粉后20-25天采收青穗。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (317, 2, '双萃2750', '苏审玉20190016', '2019.04', 0, '江苏省农作物品种审定委员会', '福州金苗种业有限公司', 'JMT-215 / AC-802W', '江苏各地', '特征特性：早熟半紧凑超甜玉米。出苗整齐，叶鞘绿色，叶片绿色，叶缘绿色，株型半紧凑，花药黄色，颖壳绿色，花丝青色，果穗筒型，籽粒黄白色，硬粒型，穗轴白色。省区试平均结果：株高147厘米，穗位39厘米，成株叶片数12~14片，穗长17.6厘米，穗粗4.2厘米，每穗15行，每行31.4粒，千粒鲜重346克，鲜穗出籽率66.6%。春季播种至采收鲜穗约84天。倒伏倒折率2.9%。中国农科院作物研究所及江苏省农科院植保所接种鉴定：感大斑病、小斑病，高感茎腐病、纹枯病、粗缩病。江苏省鲜食玉米区域试验品种品尝鉴定：外观品质和蒸煮品质达到部颁鲜食甜玉米一级标准。扬州大学农学院检测：水溶性糖含量21.1%，还原糖含量8.7%，达到甜玉米标准（NY/T 523-2002）。产量和抗性表现：2016~2017年参加江苏省甜玉米区试，两年区试平均亩产鲜穗570公斤，平均比对照晶甜3号减产28.6%；2018年参加江苏省甜玉米生产试验，平均亩产鲜穗650.1公斤，比对照晶甜3号减产18.7%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500株左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量纯氮17公斤、五氧化二磷4~5公斤、氧化钾7.5~10公斤。基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕，做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。用高效低毒低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、纹枯病等。5、适时采收。一般在授粉后20~22天采收青穗。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (318, 2, '大华1146', '苏审玉201601', '2016.04', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D1160×D1153，原名“DJ1146”', '江苏省淮北地区夏播', '特征特性：属中熟紧凑型普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强。成株株型紧凑，总叶片数19片左右；花药浅紫色，花丝绿色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：株高251厘米，穗位高102厘米；穗长18.2厘米，穗粗5.0厘米，每穗16.8行，每行32粒。千粒重317克，出籽率87.2%。全生育期100天。倒伏率0.0%。中国农业科学院作物研究所接种鉴定：抗大斑病、茎腐病，抗小斑病，感纹枯病，高感粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重749克/升，粗蛋白9.32%，粗脂肪3.84%，粗淀粉74.55%，赖氨酸0.28%。产量和抗性表现：2013-2014年参加江苏省淮北普通玉米区域试验，两年区试平均亩产580.7公斤，2013年比对照郑单958增产7.3%，2014年比对照郑单958增产8.2%，两年增产均极显著。2015年生产试验平均亩产651.9公斤，比对照郑单958增产15.4%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度约4500株/亩。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20-25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (319, 2, '大华1409', '苏审玉20190010', '2019.04', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D1263/D207，参试名称“DJ1409”', '江苏省淮北地区夏播', '特征特性：中熟紧凑型普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强。成株株型紧凑，总叶片数19片左右；花药浅紫色，花丝绿色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：株高265厘米，穗位高99厘米；穗长18.9厘米，穗粗4.9厘米，每穗15.1行，每行33.2粒。千粒重338克，出籽率85.7%。全生育期104天。倒伏倒折率0.3%。中国农业科学院作物研究所江苏省农科院植保所接种鉴定：抗大斑病，中抗茎腐病、南方锈病，感小斑病、瘤黑粉病，高感纹枯病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重776克/升，粗蛋白10.13%，粗脂肪3.45%，粗淀粉74.75%，赖氨酸0.29%。产量和抗性表现：2016~2017年参加江苏省淮北普通玉米区域试验，两年区试平均亩产668.3公斤，比对照郑单958增产9.8%。2018年生产试验平均亩产588.8公斤，比对照郑单958增产8.9%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (320, 2, '大华1533', '苏审玉20210004', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'PH615×D625，参试名称“DJ1533”', '江苏省淮南地区春播', '特征特性：中熟普通玉米。第一叶顶端形状为圆到匙形，叶鞘紫色，叶色绿色，生长势强。株型半紧凑，总叶片数20片左右；花药绿色，花丝绿色；果穗筒形，穗轴红色；籽粒黄色，硬粒型。省区试平均结果：全生育期118.8天，比对照苏玉29短1.8天。株高281厘米，穗位高104厘米；穗长18.2厘米，穗粗4.6厘米，秃尖长1.7厘米，每穗15.3行，每行33.4粒；千粒重319克，出籽率84.0%；空秆率2.2%，倒伏倒折率7.8%。经中国农业科学院作物科学研究所、江苏省农业科学院植保所接种鉴定：抗大斑病、小斑病；中抗腐霉茎腐病；感纹枯病、南方锈病；高感瘤黑粉病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2019年检测：容重770克/升，粗蛋白8.93%，粗脂肪3.35%，粗淀粉74.44%，赖氨酸0.27%。产量和抗性表现：2017~2018年参加江苏省普通玉米淮南春播区试，两年平均亩产573.7公斤，比对照苏玉29增产6.4%。2019年参加生产试验，平均亩产692.0公斤，比对照苏玉29增产4.4%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (321, 2, '大华1601', '苏审玉20210005', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D1367×D1335，参试名称“X1601”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。第一叶顶端形状为圆形，叶鞘紫色，叶色绿，生长势强。株型紧凑，总叶片数19片左右；花药深紫色，花丝浅紫色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期104.1天，比对照郑单958长0.2天。株高239厘米，穗位高94厘米；穗长18.0厘米，穗粗5.0厘米，秃尖长0.8厘米，每穗16.6行，每行32.4粒；千粒重360克，出籽率86.2%；空秆率0.6%，倒伏倒折率0.3%。经江苏省农业科学院植保所接种鉴定：高抗大斑病；抗腐霉茎腐病；中抗小斑病、纹枯病；感瘤黑粉病；高感南方锈病。经农业农村部谷物品质监督检验测试中心（哈尔滨）2020年检测：容重754克/升，粗蛋白8.55%，粗脂肪3.15%，粗淀粉77.17%，赖氨酸0.25%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播区试，两年平均亩产603.0公斤，比对照郑单958增产9.7%。2020年参加生产试验，平均亩产538.8公斤，比对照郑单958增产7.1%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (322, 2, '大华1623', '苏审玉20210001', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D1337×D1316', '江苏省淮南地区春播', '特征特性：中熟普通玉米。第一叶顶端形状为圆到匙形，叶鞘紫色，叶色绿，生长势强。株型紧凑，总叶片数19片左右；花药绿色，花丝浅紫色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：全生育期120.2天，比对照苏玉29短2.2天。株高237厘米，穗位高98厘米；穗长17.1厘米，穗粗5.0厘米，秃尖长0.8厘米，每穗15.0行，每行34.0粒；千粒重346克，出籽率87.3%；空秆率0.6%，倒伏倒折率6.7%。经江苏省农业科学院植保所接种鉴定：高抗大斑病；抗小斑病；中抗纹枯病、瘤黑粉病；感腐霉茎腐病；高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重736克/升，粗蛋白10.24%，粗脂肪3.49%，粗淀粉73.98%，赖氨酸0.28%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮南春播区试，两年平均亩产650.6公斤，比对照苏玉29增产11.7%。2020年参加生产试验，平均亩产601.9公斤，比对照苏玉29增产14.2%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (323, 2, '大华1713', '苏审玉20220002', '2022.08', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D1332×D6453，参试名称“DJ1713”', '江苏省淮南地区春播', '特征特性：中熟普通玉米。第一叶顶端形状为圆形，叶鞘紫色，叶色绿色，生长势强。株型半紧凑，总叶片数19片左右；花药浅紫色，花丝绿色；果穗筒形，穗轴粉红色；籽粒黄色，马齿型。省区试平均结果：全生育期121.9天，比对照苏玉29短1.0天。株高242.1厘米，穗位高107.2厘米；穗长16.4厘米，穗粗5.4厘米，秃尖长0.6厘米，每穗17.9行，每行33.3粒；千粒重324.2克，出籽率87.3%；空秆率0.6%，倒折倒伏率0.5%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病，中抗小斑病，感腐霉茎腐病、纹枯病、瘤黑粉病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重720克/升，粗蛋白10.50%，粗脂肪3.36%，粗淀粉73.36%，赖氨酸0.28%。产量和抗性表现：2019~2020年参加江苏省普通玉米淮南春播区试，两年平均亩产672.9公斤，比对照苏玉29增产9.3%。2021年参加生产试验，平均亩产605.3公斤，比对照苏玉29增产9.6%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (324, 2, '大华1801', '苏审玉20210013', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D1335×D6424，参试名称“DJ1801”', '江苏省淮南地区春播', '特征特性：中熟普通玉米。第一叶顶端形状为圆形，叶鞘深紫色，叶色绿，生长势强。株型半紧凑，总叶片数19片左右；花药绿色，花丝绿色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期120.9天，比对照苏玉29短1.6天。株高247厘米，穗位高102厘米；穗长18.1厘米，穗粗4.9厘米，秃尖长0.7厘米，每穗16.8行，每行35.2粒；千粒重297克，出籽率86.8%；空秆率1.7%，倒伏倒折率1.6%。经江苏省农业科学院植保所接种鉴定：高抗大斑病；抗小斑病；中抗腐霉茎腐病、瘤黑粉病；感纹枯病、南方锈病。经农业农村部谷物品质监督检验测试中心（哈尔滨）2020年检测：容重744克/升，粗蛋白9.42%，粗脂肪3.24%，粗淀粉74.42%，赖氨酸0.27%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮南春播省农科院联合体区试，两年平均亩产627.8公斤，比对照苏玉29增产5.5%。2020年参加生产试验，平均亩产562.2公斤，比对照苏玉29增产8.1%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (325, 2, '大华1802', '苏审玉20210021', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D1335×D6446，参试名称“DJ1802”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。第一叶顶端形状为圆形，叶鞘紫色，叶色绿，生长势强。株型半紧凑，总叶片数19片左右；花药绿色，花丝绿色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期102.9天，比对照郑单958短0.7天。株高236厘米，穗位高96厘米；穗长17.7厘米，穗粗4.8厘米，秃尖长0.5厘米，每穗15.6行，每行34.1粒；千粒重360克，出籽率86.4%；空秆率0.3%，倒伏倒折率4.7%。经江苏省农业科学院植保所接种鉴定：抗大斑病、小斑病；中抗腐霉茎腐病、纹枯病、瘤黑粉病；高感南方锈病。经农业农村部谷物品质监督检验测试中心（哈尔滨）2020年检测：容重742克/升，粗蛋白9.30%，粗脂肪4.54%，粗淀粉73.39%，赖氨酸0.30%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播大华联合体区试，两年平均亩产631.5公斤，比对照郑单958增产9.3%。2020年参加生产试验，平均亩产531.8公斤，比对照郑单958增产5.7%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (326, 2, '大华1805', '苏审玉20230005', '2023.06', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D1305×D2035，参试名称“DJ1805”', '江苏省淮北地区', '特征特性：普通玉米品种。幼苗叶鞘紫色，叶片绿色，生长势较强。株型半紧凑，茎秆粗壮，总叶片数20~21片，成株叶色绿色；花药黄色，花丝绿色；果穗筒形，穗轴粉红色；籽粒黄色，半马齿型。省区试平均结果：全生育期101.5天，比对照郑单958长0.5天。株高245.5厘米，穗位高103.6厘米；穗长18.4厘米，穗粗5.0厘米，秃尖长0.7厘米；每穗16.2行，每行33.8粒；千粒重355.1克，出籽率86.0%；无空秆，倒伏倒折率3.5%。经江苏省农业科学院植物保护研究所接种鉴定：高抗大斑病，抗小斑病、弯孢菌叶斑病、纹枯病、南方锈病、穗腐病，感腐霉茎腐病、瘤黑粉病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重770克/升，粗蛋白9.36%，粗脂肪3.43%，粗淀粉74.63%，赖氨酸0.29%。产量和抗性表现：2020~2021年参加江苏省普通玉米淮北夏播区试，两年平均亩产558.5公斤，比对照郑单958增产20.1%。2022年参加生产试验，平均亩产533.7公斤，比对照郑单958增产7.7%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (327, 2, '大华1898', '苏审玉20220008', '2022.08', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D1366×D1356，参试名称“DJ1898”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。第一叶顶端形状为圆形，叶鞘紫色，叶色绿色，生长势强。株型半紧凑，总叶片数19片左右；花药黄色，花丝绿色；果穗筒形，穗轴粉红色；籽粒黄色，半马齿型。省区试平均结果：全生育期103.5天，与对照郑单958相当。株高258.6厘米，穗位高108.3厘米，穗长19.0厘米，穗粗4.9厘米，秃尖长0.5厘米。每穗14.7行，每行36.3粒；千粒重358.4克，出籽率84.6%；空秆率0.3%，倒折倒伏率4.7%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病，中抗纹枯病，感腐霉茎腐病、瘤黑粉病，高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重746克/升，粗蛋白8.31%，粗脂肪3.46%，粗淀粉74.94%，赖氨酸0.25%。产量和抗性表现：2019~2020年参加江苏省普通玉米淮北夏播区试，两年平均亩产583.3公斤，比对照郑单958增产11.2%。2021年参加生产试验，平均亩产508.4公斤，比对照郑单958增产20.7%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (328, 2, '大华玉2号', '苏审玉200503', '2005.2', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D101譊138', '适宜江苏省春夏播地区种植', '退出批次：特征特性：全生育期春播118天左右，夏播100天左右。出苗较齐，苗势较强，幼苗叶鞘紫色，叶片绿色，叶缘紫色。株型半紧凑，长相清秀，整齐度好，株高242cm左右，穗位102cm左右，成株叶片数19片左右，叶色较深。花药黄色，颖壳黄色，花丝红色，果穗筒型，穗长17.4cm左右，穗粗5cm左右，秃顶1.6cm左右，每穗14-16行，每行29粒左右，籽粒黄色，粒型硬粒型，千粒重339.5g左右，出籽率82%左右。田间表现，春播轻感玉米大斑病、病毒病，中感小斑病、纹枯病，抗倒性一般；夏播轻感玉米小斑病、病毒病，中感大斑病、纹枯病，抗倒性一般。经农业部谷物品质监督检验测试中心（北京）检测，容重758g/L，粗蛋白9.2%，粗脂肪3.5%，粗淀粉73.26%，赖氨酸0.3%。产量和抗性表现：2002-2003年参加江苏省区试，两年区试春播平均亩产506kg，比对照苏玉9号增产极显著，夏播平均亩产424kg，比对照苏玉9号增产极显著；2004年生产试验春播亩产543kg，夏播亩产594kg。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (329, 2, '天华玉001', '苏审玉 201402', '2014', 0, '江苏省农作物品种审定委员会', '淮安市金色天华种业科技有限公司', 'H3356譎2597', '适宜江苏淮北夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，幼苗叶鞘紫色，叶片绿色株型紧凑颖片紫色，花丝浅红色果穗筒形，籽粒黄色、半马齿型省区试平均结果：株高268厘米，成株叶片20片；穗位107厘米，穗长18.5厘米左右，穗粗4.9厘米；每穗16行，每行34粒，千粒重333.0克，出籽率85.8%全生育期约100天倒伏率1.1%中国农业科学院作物研究所接种鉴定：抗大斑病、小斑病，中抗茎腐病，感纹枯病，高感粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重731克/升，粗蛋白8.92%，粗脂肪4.32%，粗淀粉72.72%，赖氨酸0.30%产量和抗性表现：2010~2012年参加江苏省夏播玉米区域试验，三年区试平均亩产532.2公斤，比对照郑单958增产7.7%，三年增产均达极显著2013年生产试验平均亩产559.4公斤，比对照郑单958增产7.0%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (330, 2, '天玉1619', '苏审玉20210022', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏天丰种业有限公司、江苏徐淮地区淮阴农业科学研究所', 'H3058×Y272', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势较强。株型紧凑，茎秆粗壮，总叶片数19~20片，成株叶色绿色，颖壳紫色；花药淡红色，花丝紫色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期104.4天，比对照郑单958长0.8天。株高234厘米，穗位高97厘米；穗长17.3厘米，穗粗4.7厘米，秃尖长0.7厘米，每穗14.6行，每行33.5粒；千粒重353克，出籽率85.2%；空秆率1.6%，倒伏倒折率2.7%。经江苏省农业科学院植保所接种鉴定：高抗小斑病；抗腐霉茎腐病；中抗大斑病、纹枯病；感瘤黑粉病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重788克/升，粗蛋白9.16%，粗脂肪4.56%，粗淀粉73.32%，赖氨酸0.27%。产量和抗性表现：2018~2019年度参加江苏省普通玉米淮北夏播大华联合体区试，两年平均亩产608.7公斤，比对照郑单958增产5.4%。2020年参加生产试验，平均亩产541.4公斤，比对照郑单958增产7.6%。', '1、适期播种。夏播一般6月20日左右。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕，做好壅土培根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好腐霉茎腐病、瘤黑粉病、玉米螟等的防治工作。5、适期采收。最佳收获期为玉米籽粒乳线消失。适当推迟收获，有利于增加干物质积累量从而提高产量。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (331, 2, '天玉88', '苏审玉201603', '2016.04', 0, '江苏省农作物品种审定委员会', '扬州大学、江苏天丰种业有限公司', 'LDC-1×YS501，原名“YH1108”', '江苏省淮北地区夏播', '特征特性：属中熟半紧凑型普通玉米。幼苗叶鞘紫色，叶片绿色，生长势强。株型紧凑，成株叶色深绿；花药紫色，花丝紫色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：株高269厘米，穗位高116厘米；穗长20.2厘米，穗粗4.7厘米，秃尖长1.6厘米，每穗15.4行，每行36粒。千粒重302克，出籽率84.0%。全生育期100天。倒伏率0.8%。中国农业科学院作物研究所接种鉴定：高抗茎腐病，抗小斑病，中抗大斑病，高感粗缩病、纹枯病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重804克/升，粗蛋白9.88%，粗脂肪4.07%，粗淀粉73.59%，赖氨酸0.27%。产量和抗性表现：2013-2014年参加江苏省淮北普通玉米区域试验，两年区试平均亩产573.9公斤，2013年比对照郑单958增产6.5%，两年增产均极显著。2015年参加江苏省淮北普通玉米生产试验，平均亩产634.0公斤，比对照郑单958增产12.2%。', '1、适期播种：一般6月中下旬播种。2、合理密植：适宜密度约4500株/亩。3、加强肥水管理：氮、磷、钾配合使用，纯氮一般30公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕，做好培土壅根。4、病虫害防治：对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (332, 2, '宁玉614', '苏审玉201005', '2010.2', 0, '江苏省农作物品种审定委员会', '南京春曦种子研究中心', '宁晨68×宁晨47', '适宜在江苏夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，叶鞘浅绿色，生长势强，叶片深绿株型半紧凑花药浅紫色，花丝浅紫色果穗筒形，籽粒黄色，马齿型，穗轴红色省区试平均结果：株高253厘米，成株叶片19片，穗位107厘米，穗长18.7厘米，穗粗4.9厘米，每穗14-16行，每行35粒，千粒重325.0克，出籽率84.7%，全生育期约102天，倒伏率0.3%中国农业科学院作物研究所2009年接种鉴定：抗小斑病，感纹枯病农业部谷物品质监督检验测试中心（哈尔滨）2009年检测：容重747克/升，粗蛋白9.43%，粗脂肪4.62%，粗淀粉74.71%，赖氨酸0.26%产量和抗性表现：2007-2008年参加江苏省夏播玉米区域试验，两年区试平均亩产492.7公斤，比对照郑单958增产3.3%，两年增产均达极显著2009年生产试验平均亩产540.7公斤，比对照郑单958增产4.7%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (333, 2, '密甜糯1号', '苏审玉20210031', '2021.03', 0, '江苏省农作物品种审定委员会', '北京中农斯达农业科技开发有限公司', 'S300M-1×D2-300，参试名称“加甜糯2008”', '江苏省各地', '特征特性：早中熟鲜食甜糯玉米。幼苗叶鞘紫色，叶片浅绿色。株型半紧凑，总叶片数21片；花药浅紫色，颖壳绿色，花丝淡紫色；果穗锥形，穗轴白色；籽粒白色，籽粒甜糯比例1:3。联合体区试平均结果：出苗至采收鲜穗81.9天，比对照苏玉糯5号长1.1天。株高223厘米，穗位高91厘米；穗长18.2厘米，穗粗4.8厘米，秃尖长0.4厘米，每穗14.1行，每行38.6粒；千粒鲜重343克，鲜穗出籽率70.5%；空秆率0.6%，倒伏倒折率0.3%。经江苏省农业科学院植保所接种鉴定：抗大斑病；中抗小斑病、瘤黑粉病；感纹枯病；高感腐霉茎腐病、南方锈病。江苏省糯玉米联合体品种区域试验品尝鉴定：外观品质和蒸煮品质85.8分。扬州大学农学院检测：支链淀粉占总淀粉的96.5%。产量和抗性表现：2018~2019年参加江苏省糯玉米省农科院联合体区试，两年平均亩产鲜穗871.0公斤，比对照苏玉糯5号增产10.7%。2020年参加生产试验，平均亩产鲜穗769.3公斤，比对照苏玉糯5号增产13.4%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期，播种须保证土壤温度稳定在12摄氏度以上。2、合理密植。适宜密度每亩4000~4500株。注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮磷钾合理搭配，每亩施肥量一般不低于纯氮20公斤，五氧化二磷10公斤，氯化钾15公斤。肥料分配一般为基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕。做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效低毒低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、南方锈病等。5、适时采收。一般授粉后22~24天采收鲜穗。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (334, 2, '康源青贮玉1号', '苏审玉20220028', '2022.08', 0, '江苏省农作物品种审定委员会', '扬州大学、扬州市扬大康源乳业有限公司', 'Q6×Y915-1，参试名称“康源青贮01”', '江苏省各地', '特征特性：青贮玉米。幼苗叶鞘紫色，第一叶顶端形状圆形，叶片绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数21片左右，成株叶色深绿；花药淡红色，花丝青色；果穗筒形，穗轴红色；籽粒黄色，马齿型。自主区试平均结果：全生育期106.0天，比对照雅玉青贮8号短2.0天。株高287.0厘米，穗位高116.0厘米；穗长17.7厘米，穗粗4.8厘米，秃尖长0.8厘米，每穗16.1行，每行34.4粒，千粒重284克；空秆率1.3%，倒伏倒折率1.2%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病、纹枯病，中抗腐霉茎腐病、南方锈病，感瘤黑粉病、弯孢菌叶斑病。经扬州大学动物营养与饲料工程技术研究中心检测：全株粗蛋白含量7.50%，中性洗涤纤维含量39.75%，酸性洗涤纤维含量20.15%，淀粉含量30.12%。产量和抗性表现：2020~2021年经特殊类型品种自主区试，两年平均亩产（干重）1246.5公斤，比对照雅玉青贮8号增产8.1%。2021年参加生产试验，平均亩产（干重）1262.9公斤，比对照雅玉青贮8号增产7.3%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4500~5000株。3、加强肥水管理。注意氮、磷、钾肥配合使用，亩施纯氮20公斤左右，其中基肥40%，其余苗肥和穗肥使用。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕、做好壅土培根以防倒伏。4、病虫害绿色防控。用高效、低毒、低残留农药，对种子进行药剂处理，及时防治地下害虫、食叶害虫、玉米螟、南方锈病等。5、适时采收。在乳线1/2时，帯穗全株收获。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (335, 2, '彩甜糯818', '苏审玉20210032', '2021.03', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院、扬州大学', 'YZT-14×NA67-2，参试名称“糯YH1107”', '江苏省各地', '特征特性：中早熟鲜食糯玉米。幼苗叶鞘紫色，叶片深绿色。株型半紧凑，总叶片数17片左右；花药黄色，颖壳淡绿色，花丝紫色；果穗锥形，穗轴白色；籽粒紫白相间。联合体区试平均结果：出苗至采收鲜穗80.3天，比对照苏玉糯5号短0.5天。株高212厘米，穗位高97厘米；穗长19.4厘米，穗粗4.7厘米，秃尖长1.8厘米，每穗12.9行，每行35.3粒；千粒鲜重382克，鲜穗出籽率67.8%；空秆率0.2%，倒伏倒折率1.3%。经江苏省农业科学院植保所接种鉴定：抗大斑病；中抗小斑病；高感腐霉茎腐病、纹枯病、瘤黑粉病、南方锈病。江苏省糯玉米联合体品种区域试验品尝鉴定：外观品质和蒸煮品质87.3分。扬州大学农学院检测：支链淀粉占总淀粉的94.8%。产量和抗性表现：2018~2019年参加江苏省糯玉米省农科院联合体区试，两年平均亩产鲜穗934.6公斤，比对照苏玉糯5号增产18.8%。2020年参加生产试验，平均亩产鲜穗830.5公斤，比对照苏玉糯5号增产22.5%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期，播种须保证土壤温度稳定在12摄氏度以上。2、合理密植。适宜密度每亩4000~4500株，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量一般不低于纯氮20公斤、五氧化二磷10公斤、氧化钾15公斤。肥料分配一般为基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕，做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效低毒低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、大斑病等。5、适时采收。一般在授粉后20~24天采收青穗。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (336, 2, '徐单2号', '苏审玉200402', '2004', 0, '江苏省农作物品种审定委员会', '徐州市种子站', '徐98(齐319×478) ×徐黄4(C502×黄早4)', '江苏春夏播地区', '退出批次：特征特性：出苗较齐，苗势较强，幼苗叶色较深，植株整齐度好，生长势较强，株型半紧凑，株高230cm左右，穗位102cm左右，总叶片数20张左右，叶色较深，后期熟相较好，果穗中等，穗长16cm左右，穗粗5cm左右，秃顶1.1cm左右，每穗14-15行，每行31粒左右，籽粒黄白相间，半马偏硬，千粒重298g左右。全生育期春播118天左右，夏播100天左右。田间观察，抗玉米大、小斑病，轻感纹枯病，抗倒性较强。产量和抗性表现：该品种两年区试春播平均亩产494公斤，比对照苏玉9号增产3.1%，夏播平均亩产480公斤。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (337, 2, '徐甜糯019', '苏审玉20210029', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏徐农种业科技有限公司、江苏徐淮地区徐州农业科学研究所', 'W259×W364', '江苏省各地', '特征特性：中熟鲜食甜糯玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色。株型半紧凑，叶片较稀疏、叶上挺，总叶片数20片；雄花分枝10~14个，花药黄色，颖壳绿色，花丝浅红色；果穗锥形；籽粒白色，籽粒甜糯比例1:3。省区试平均结果：出苗至采收鲜穗82.2天，比对照苏玉糯5号短0.2天。株高230厘米，穗位高98厘米；穗长19.4厘米，穗粗4.4厘米，秃尖长1.2厘米，穗行数13.6行，每行37.7粒；千粒鲜重326克，鲜穗出籽率70.3%；空秆率0.2%，倒伏倒折率0.2%。经中国农业科学院作物科学研究所、江苏省农业科学院植保所接种鉴定：抗大斑病；中抗小斑病；感纹枯病、瘤黑粉病、南方锈病；高感腐霉茎腐病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质86.0分。扬州大学农学院检测：支链淀粉占总淀粉的99.0%。产量和抗性表现：2017~2018年参加江苏省糯玉米区试，两年平均亩产鲜穗829.4公斤，比对照苏玉糯5号增产7.5%。2019年参加生产试验，平均亩产鲜穗854.0公斤，比对照苏玉糯5号增产9.3%。', '1、适期播种。淮北地区春播在4月下旬播种；夏播在6月15日之前播种。2、适宜密度。60000株/公顷，行距60厘米。3、肥水管理。三元复合肥40公斤/亩做基肥，15~20公斤/亩尿素做追肥；干旱时在抽穗前和散粉后应灌透水。4、病虫害防治。需用高效低毒的药剂防治蚜虫和玉米螟。5、适时采收。授粉后23~26天采收为宜。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (338, 2, '扬大糯1604', '苏审玉20200012', '2020.06', 0, '江苏省农作物品种审定委员会', '扬州大学', 'B5×YZT-14，参试名称“糯YH1604”', '江苏省各地', '特征特性：糯玉米。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势强。株型紧凑，总叶片数18片，成株叶色绿色；花药黄色，颖壳青色，花丝红色；果穗长锥形，籽粒白色，穗轴白色。省区试平均结果：种至采收鲜穗82天，比对照苏玉糯5号短1天。株高206厘米，穗位高97厘米；穗长17.1厘米，穗粗4.4厘米，秃尖长0.9厘米，每穗13.2行，每行33.0粒；千粒鲜重320克，鲜穗出籽率67.2%；空秆率0.3%，倒伏倒折率0.3%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：抗瘤黑粉病；中抗大斑病、小斑病；感纹枯病；高感腐霉茎腐病、南方锈病、粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质85.8分。扬州大学农学院检测：支链淀粉占总淀粉的98.4%。产量和抗性表现：2017~2018年参加江苏省糯玉米区试，两年平均鲜穗亩产774.3公斤，比对照苏玉糯5号增产2.2%。2019年参加生产试验，平均鲜穗亩产810.4公斤，比对照苏玉糯5号增产3.7%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理，有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤、氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，注意防涝防旱。4、注意病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、小斑病、玉米螟等。5、适时采收。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (339, 2, '扬甜糯104', '苏审玉20200008', '2020.06', 0, '江苏省农作物品种审定委员会', '扬州大学', '白甜糯106×21/16，参试名称“甜糯104”', '江苏省各地', '特征特性：甜加糯型糯玉米。幼苗叶鞘淡紫色，叶片绿色，叶缘绿色，生长势强。株型半紧凑，总叶片数19片，成株叶色绿色；花药黄色，颖壳青色，花丝红色；果穗长锥形，籽粒白色，穗轴白色。省区试平均结果：播种至采收鲜穗84天，比对照苏玉糯5号长2天。株高206厘米，穗位高86厘米；穗长20.0厘米，穗粗4.8厘米，秃尖长2.4厘米，每穗14.0行，每行35.0粒。千粒鲜重357克，鲜穗出籽率64.2%；空秆率0.2%，倒伏倒折率0.5%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：抗大斑病、瘤黑粉病；中抗小斑病、纹枯病；高感腐霉茎腐病、南方锈病、粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质85.8分。扬州大学农学院检测：支链淀粉占总淀粉的98.7%。产量和抗性表现：2017~2018年参加江苏省糯玉米区试，两年平均鲜穗亩产876.8公斤，比对照苏玉糯5号增产13.6%。2019年参加生产试验，平均鲜穗亩产862.9公斤，比对照苏玉糯5号增产10.4%。', '1、适期播种，根据上市时间和不同的栽培方式，合理安排播期。2、合理密植，适宜密度每亩4000株左右。3、加强肥水管理，有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤、氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%；注意防涝防旱。4、注意病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、小斑病、玉米螟等。5、适时采收。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (340, 2, '扬白糯527', '苏审玉20230009', '2023.06', 0, '江苏省农作物品种审定委员会', '扬州大学', 'N5×YZT14，参试名称“糯YH1113”', '江苏省各地', '特征特性：鲜食糯玉米品种。幼苗叶鞘淡紫色，叶片绿色，生长势强。株型半紧凑；花药淡紫色，花丝红色；果穗长锥形，籽粒白色；穗轴白色。省区试平均结果：出苗至采收鲜穗81.2天，比对照苏玉糯5号长0.3天。株高243.0厘米，穗位高101.0厘米；穗长17.3厘米，穗粗4.7厘米，秃尖长1.2厘米，每穗15.4行，每行34.1粒。千粒鲜重310.3克，鲜穗出籽率69.6%。空秆率0.2%，倒伏倒折率0.5%。经江苏省农业科学院植物保护研究所接种鉴定：中抗大斑病、小斑病、纹枯病、南方锈病、弯孢菌叶斑病，感腐霉茎腐病、瘤黑粉病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质88.6分。扬州大学农学院检测：支链淀粉占总淀粉的98.4%。产量和抗性表现：2020~2021年参加江苏省糯玉米区试，两年平均亩产鲜穗861.5公斤，比对照苏玉糯5号增产11.5%。2022年参加生产试验，平均亩产鲜穗865.4公斤，比对照苏玉糯5号增产11.4%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500~4000株。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，亩施纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，注意防涝防旱。4、注意病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、腐霉茎腐病、瘤黑粉病等。5、适时采收。一般在授粉后21~23天采收青穗。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (341, 2, '扬青贮玉1号', '苏审玉20220029', '2022.08', 0, '江苏省农作物品种审定委员会', '扬州大学、扬州大学试验农牧场', 'Q10×NIL，参试名称“场青贮06”', '江苏省淮南地区春播', '特征特性：青贮玉米。幼苗叶鞘淡紫色，第一叶顶端形状圆到匙形，叶片绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数22片左右；花药黄色，花丝淡红色；果穗筒锥形，穗轴白色；籽粒黄色，半马齿型。自主区试平均结果：全生育期103.0天，比对照雅玉青贮8号短2.0天。株高298.0厘米，穗位高109.0厘米；穗长16.5厘米，穗粗4.5厘米，秃尖长0.2厘米，每穗15.5行，每行36.6粒；千粒重296.0克；空秆率3.0%，倒伏倒折率3.1%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、纹枯病，中抗小斑病、腐霉茎腐病、瘤黑粉病、弯孢菌叶斑病，感南方锈病。经扬州大学动物营养与饲料工程技术研究中心检测：全株粗蛋白含量7.52%，中性洗涤纤维含量39.95%，酸性洗涤纤维20.54%，淀粉含量30.03%。产量和抗性表现：2019~2020年经特殊类型品种自主区试，两年平均亩产（干重）1205.5公斤，比对照雅玉青贮8号增产15.2%。2021年参加生产试验，平均亩产（干重）1278.7公斤，比对照雅玉青贮8号增产8.7%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4500~5000株。3、加强肥水管理。注意氮、磷、钾肥配合使用，亩施纯氮20~25公斤，其中基肥40%，苗肥30%，穗肥30%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕、做好壅土培根以防倒伏。4、注意病虫害防治。用高效、低毒、低残留农药，对种子进行药剂处理，及时防治地下害虫、食叶害虫、南方锈病等。5、适时收获。在乳线1/2时，帯穗全株收获。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (342, 2, '掖单12', '苏种审字第216号', '1994', 0, '江苏省农作物品种审定委员会', '省种子站引进', '478×515单交种', '江苏作春、夏玉米种植', '退出批次：特征特性：该品种出苗快，苗势强，株型紧凑、叶片上冲而挺立，植株生长清秀，活棵成熟。株高227厘米左右，穗位90.5厘米左右，每穗15.5行，每行28粒，千粒重282克左右，果穗秃顶小，出籽率87%左右，籽粒黄色、马齿型、籽粒组蛋白含量9.51%，赖氨酸含量0.33%，粗脂肪含量4.11%，粗淀粉含量67.68%。抗玉米大小斑病，感青枯病，抗倒性强。全生育期春播124天左右，夏播96天左右。产量和抗性表现：1991年至1992年两年分别参加省玉米品种春、夏播组区域试验。春播组，两年亩产分别为385.7和583.3公斤，比对照苏玉3号分别增产17.2和18.4%，达显著和极显著水平。夏播组，两年亩产分别为577.2和479.2公斤，比对照掖单4号分别增产3.5%和2.0%，均未达显著.1993年参加春播组生产试验，三个点平均亩产524.9公斤，比对照苏玉3号增产4.9%。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (343, 2, '掖单12号', '苏种审字第216号', '1994', 0, '', '江苏省种子站引进', '', '', '审定机构：品种来源：适宜种植区域：特征特性：产量和抗性表现：', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (344, 2, '掖单13', '苏种审字第185号', '1993', 0, '江苏省农作物品种审定委员会', '山东省莱州市农所,省站引进', '478�340', '江苏作春、夏玉米种植', '退出批次：特征特性：株高230厘米左右，穗位高84厘米，叶片较宽，穗上位叶与主基夹角较小适宜密植，活棵成熟。果穗大，穗长17.6厘米，穗粗5.1厘米，秃顶长2.7厘米，平均每穗17.7行，每行31.0粒左右，出率87%，籽粒黄色，半马齿型、干粒重280左右。产量和抗性表现：1991年和1992年连续两年参加省区域试验。两年单产分别为412.7和602.8公斤，较好照苏玉3号分别增产25.4%和22.4%，达极显著水平，均居参试品种首位;1992年春播生产试验平均亩产599.81公斤，较好照增产30.8%，居参试品种一位。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (345, 2, '掖单13号', '苏种审字第185号', '1993', 0, '', '江苏省种子站引进', '', '', '审定机构：品种来源：适宜种植区域：特征特性：产量和抗性表现：', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (346, 2, '掖单4号', '苏种审字第121号', '1989', 0, '江苏省农作物品种审定委员会', '徐州市种子站引进', '8112-3×黄早四', '江苏作春、夏玉米种植', '退出批次：特征特性：该品种出苗快、苗势较强，株型紧凑，叶上冲而挺立（上位叶与茎秆之间夹角为18—20度），植株生长清秀，叶片浓绿，株高230—250厘米，穗位高100厘米左右，茎杆坚实而韧，根系发达，穗园柱型、穗长17—18厘米，穗组4.6厘米左右，每穗12—14行，每行33—35粒，籽粒黄色马齿形，品质和商品性较好，千粒重300克左右，果穗秃顶小，穗轴白色较细，出籽率86%左右，耐高度密种植，耐肥、抗倒性强、抗旱性较好，抗大小斑病，灌浆至成熟期多雨或土壤全生育期，春播110在左右，夏播95在左右。产量和抗性表现：1987、88年两年参加省玉米区域试验，春、夏播两组两年平均亩产均居首位。1987年平均亩产443公斤，比对照苏玉一号增产11%，达极显著。其中春播组平均亩产399公斤，经对增产9.8%，夏播组平均亩产479公斤，比对照增产11.8%。1988年平均亩产474公斤，比对苏玉1号增产8.5%，达显著。其中春播组平均亩产432公斤，比对照增产11%，夏播组平均亩产507公斤，比对照增产6.5%。1988年玉米生产试验，全省9个试点亩产经对照苏玉一号增产12.9%，其中春播组个试点平均亩产470.5公斤，双对照增产18%，夏播组4个试点平均亩产488公斤，比对照增产8.4%。经稳产性分析，回归系数为0.8724，表现为良好的稳产性。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (347, 2, '春风886', '苏审玉20190002', '2019.04', 0, '江苏省农作物品种审定委员会', '盐城神农大丰种业科技有限公司', 'ZH179×ZH03，参试名称“春风886”', '江苏淮北地区夏播及淮南地区', '特征特性：中熟半紧凑型普通玉米。幼苗叶鞘紫色，子叶椭圆形，叶色绿色，叶缘浅绿色，生长势强。株型半紧凑，茎秆粗壮。颖片淡紫色，花药紫色，花丝红色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：（淮南）株高269厘米，成株叶片19片，穗位高107厘米，穗长17.1厘米，穗粗5.0厘米，秃尖长1.4厘米，每穗15.6行，每行30.2粒。千粒重355克，出籽率84.9%。全生育期121天。倒伏倒折率2.3%。（淮北）株高278厘米，成株叶片19片，穗位高101厘米；穗长18.7厘米，穗粗5.0厘米，秃尖长0.7厘米，每穗14.9行，每行32.3粒。千粒重370克，出籽率86.4%。全生育期105天。倒伏倒折率1.0%。中国农业科学院作物研究所和江苏省农科院植保所接种鉴定：(淮南)抗大斑病、感小斑病、纹枯病、茎腐病，中抗瘤黑粉病，中抗南方锈病、高感粗缩病。（淮北）中抗大斑病、感小斑病，感纹枯病、中抗茎腐病，中抗瘤黑粉病，中抗南方锈病、高感粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：（淮南）容重739克/升，粗蛋白11.19%，粗脂肪3.23%，粗淀粉73.00%，赖氨酸0.32%；（淮北）容重772克/升，粗蛋白10.59%，粗脂肪3.67%，粗淀粉74.10%，赖氨酸0.29%。产量和抗性表现：2016~2017年参加江苏省普通玉米区域试验：淮南地区两年区试平均亩产584.6公斤，比对照苏玉29增产12.9%；淮北地区两年区试平均亩产671.5公斤，比对照郑单958增产10.3%。2018年参加生产试验：淮南平均亩产620.5公斤，比对照苏玉29增产12.6%；淮北平均亩产590.9公斤，比对照郑单958增产9.3%。', '1、适期播种。一般春播4月初、夏播6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕、做好壅土培根以防倒伏。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好玉米螟、粗缩病、茎腐病、南方锈病、纹枯病等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (348, 2, '晶彩甜糯', '苏审玉20190012', '2019.04', 0, '江苏省农作物品种审定委员会', '江苏润扬种业股份有限公司、南京市蔬菜科学研究所', 'QN-51×F06-1', '江苏各地', '特征特性：半紧凑型糯玉米。出苗整齐，苗势强，叶片绿色，株型半紧凑；果穗锥形，籽粒红白相间，甜糯型。省区试平均结果：株高227厘米，穗位高112厘米；穗长18.1厘米，穗粗4.7厘米，每穗14.3行，每行31.6粒。千粒鲜重313克。春季播种至采收鲜穗约89天。鲜穗出籽率63.1%。倒伏倒折率2.5%。中国农科院作物研究所及江苏省农科院植保所接种鉴定：中抗大斑病、茎腐病，感小斑病、纹枯病，高感粗缩病、南方锈病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到鲜食糯玉米二级标准。扬州大学农学院检测：支链淀粉占总淀粉的98.1％，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2016~2017年参加江苏省糯玉米区域试验，两年区试平均亩产鲜穗794.3公斤，平均比对照苏玉糯5号增产4.3%。2018年生产试验平均亩产鲜穗843.8公斤，比对照苏玉糯5号增产6.7%。', '1、适期播种，根据上市时间和不同的栽培方式，合理安排播期。2、合理密植，适宜密度每亩4000-4500株左右。3、加强肥水管理，有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮15公斤、五氧化二磷5公斤，氧化钾7.5~10公斤，基肥占40%，苗肥占20%，穗肥占40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合肥料及时中耕，做好雍根培土以防倒伏。4、病虫害绿色防控。用高效低毒低残留农药及时防治地下害虫，食叶害虫、玉米螟、粗缩病、纹枯病等。5、适时采收，一般在授粉后22~24天采收青穗。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (349, 2, '晶彩甜糯2号', '苏审玉20220018', '2022.08', 0, '江苏省农作物品种审定委员会', '江苏润扬种业股份有限公司、南京市蔬菜科学研究所', 'QN51譐59HT14', '江苏省各地', '特征特性：中早熟鲜食糯玉米。出苗整齐，苗势强，叶片绿色。株型半紧凑；果穗长锥形；籽粒红白色，甜糯型。省区试平均结果：出苗至采收鲜穗83.3天，比对照苏玉糯5号长0.2天。株高243.9厘米，穗位高117.3厘米；穗长20.2厘米，穗粗5.2厘米，秃尖长3.3厘米，每穗16.8行，每行34.3粒；千粒鲜重308.7克，鲜穗出籽率60.5%；空秆率0.1%，倒伏倒折率1.1%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、纹枯病，中抗小斑病，感腐霉茎腐病、瘤黑粉病，高感南方锈病。江苏省鲜食玉米品种区试品尝鉴定：外观品质和蒸煮品质89.0分。扬州大学农学院检测：支链淀粉占总淀粉的96.7%。产量和抗性表现：2019~2020年参加江苏省糯玉米区试，两年平均亩产鲜穗961.8公斤，比对照苏玉糯5号增产19.1%。2021年参加生产试验，平均亩产鲜穗899.7公斤，比对照苏玉糯5号增产18.4%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，亩施纯氮15公斤、五氧化二磷5公斤，氧化钾7.5~10公斤，其中基肥40%，苗肥20%，穗肥40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合肥料及时中耕，做好雍根培土以防倒伏。4、病虫害防治。用高效、低毒、残留农药及时防治地下害虫，食叶害虫、玉米螟、粗缩病、纹枯病等。5、适时采收。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (350, 2, '晶彩糯', '苏审玉20180006', '2018.05', 0, '江苏省农作物品种审定委员会', '江苏润扬种业股份有限公司、南京市蔬菜科学研究所', 'QN-51×ZN-01', '江苏各地', '特征特性：半紧凑型糯玉米。幼苗叶鞘淡紫色，叶片绿色，叶缘绿色，生长势强；株型半紧凑，全株叶片数19片左右，花药绿色，花丝绿白色，果穗长锥形，籽粒红、白色，糯质型，穗轴白色。省区试平均结果：株高229厘米，穗位高110厘米；穗长18.5厘米，穗粗4.6厘米，每穗14.0行，每行31.6粒，千粒鲜重321克。春季播种至采收鲜穗约89天，比对照晚1天。鲜穗出籽率63.1%。倒伏率3.5%。中国农科院作物研究所接种鉴定：感大斑病、小斑病，中抗纹枯病、腐霉茎腐病，高感粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到鲜食糯玉米二级标准。扬州大学农学院检测：支链淀粉占总淀粉的97.4%，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2015~2016年参加江苏省糯玉米区域试验，两年区试平均亩产鲜穗814.9公斤，平均比对照苏玉糯5号增产6.6%。2017年生产试验平均亩产鲜穗801.6公斤，比对照苏玉糯5号增产2.3%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮15公斤、五氧化二磷4~5公斤，氧化钾7.5~10公斤，基肥占40%，苗肥占20%，穗肥占40%，结合施肥及时中耕，做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效低毒低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、小斑病等。5、适时采收，一般在授粉后20~25天采收鲜穗。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (351, 2, '晶甜10号', '苏审玉20190017', '2019.04', 0, '江苏省农作物品种审定委员会', '江苏润扬种业股份有限公司、南京市蔬菜科学研究所', '甜-01×403-11C，参试名称“晶甜0518”', '江苏各地', '特征特性：中熟半紧凑型超甜玉米。出苗整齐，叶鞘绿色，叶片绿色，叶缘绿色，株型半紧凑，花药黄色，颖壳绿色，花丝青色，果穗筒型，籽粒黄色，硬粒型，穗轴白色。江苏省区试平均结果：株高236厘米，穗位98厘米，成株叶片数19-20片，穗长19.4厘米，穗粗5.0厘米，每穗13.6行，每行34.2粒，千粒鲜重351克，鲜穗出籽率62.5%。春季播种至采收鲜穗约90天。田间倒伏率3.6%。中国农科院作物研究所及江苏省农科院植保所接种鉴定：中抗大斑病、茎腐病，感小斑病，高感纹枯病、粗缩病。省鲜食玉米区域试验品种品尝鉴定：外观品质和蒸煮品质达到部颁鲜食甜玉米二级标准。扬州大学农学院检测：水溶性糖含量15.5%，还原糖含量9.0%，达到甜玉米标准（NY/T523-2002）。产量和抗性表现：2016~2017年参加江苏省甜玉米区试，两年区试平均亩产鲜穗839.4公斤，平均比对照晶甜3号增产5.1%；2018年参加江苏省甜玉米生产试验，平均亩产鲜穗869.8公斤，比对照晶甜3号增产8.7%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500株左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量纯氮15公斤、五氧化二磷4~5公斤、氧化钾7.5~10公斤。基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕，做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。用高效低毒低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、纹枯病等。5、适时采收。一般在授粉后20~24天采收青穗。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (352, 2, '晶甜12号', '苏审玉20200014', '2020.06', 0, '江苏省农作物品种审定委员会', '南京市蔬菜科学研究所、江苏润扬种业股份有限公司', 'T1205-11-14×403-11A，参试名称“晶甜0618”', '江苏省各地', '特征特性：中熟甜玉米。出苗整齐，幼苗叶鞘绿色，叶片绿色，叶缘绿色。株型半紧凑，总叶片数19~20片，成株叶片绿色，花药黄色，颖壳绿色，花丝绿色；果穗筒形，籽粒黄色，穗轴白色。省区试平均结果：播种至采收鲜穗85天，比对照晶甜3号长1天。株高225厘米，穗位高100厘米；穗长17.0厘米，穗粗4.6厘米，秃尖长0.9厘米，每穗12.6行，每行34.0粒；千粒鲜重337克，鲜穗出籽率69.0%；空秆率0.4%，倒伏倒折率2.7%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：中抗大斑病、腐霉茎腐病、纹枯病；抗小斑病；感瘤黑粉病；高感南方锈病、粗缩病。江苏省鲜食玉米区域试验品种品尝鉴定：外观品质和蒸煮品质85.7分。扬州大学农学院检测：水溶性糖含量15.7%，还原糖含量8.3%。产量和抗性表现：2017~2018年参加江苏省甜玉米区试，两年平均鲜穗亩产713.9公斤，比对照晶甜3号减产8.5%。2019年参加生产试验，平均鲜穗亩产818.7公斤，与对照晶甜3号相当。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500株左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量纯氮15公斤、五氧化二磷4~5公斤、氧化钾7.5~10公斤。基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕，做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、小斑病、玉米螟等。5、适时采收。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (353, 2, '晶甜15', '苏审玉20220025', '2022.08', 0, '江苏省农作物品种审定委员会', '南京市蔬菜科学研究所', 'H1477A譝T001', '江苏省各地', '特征特性：中熟超甜玉米。出苗整齐，叶鞘绿色，叶片绿色，叶缘绿色。株型半紧凑，总叶片数19~20片；花药黄色，颖壳绿色，花丝青色；果穗筒形，穗轴白色；籽粒黄色，甜质型。省区试平均结果：出苗至采收鲜穗85.1天，比对照晶甜3号短1.5天。株高219.8厘米，穗位高77.2厘米；穗长18.8厘米，穗粗4.8厘米，秃尖长0.8厘米，每穗16.8行，每行37.0粒；千粒鲜重319.9克，鲜穗出籽率69.0%；空秆率0.9%，倒伏倒折率1.2%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病，中抗小斑病，感腐霉茎腐病、纹枯病、瘤黑粉病，高感南方锈病。江苏省鲜食玉米区试品尝鉴定：外观品质和蒸煮品质87.3分。扬州大学农学院检测：水溶性糖含量24.0%，还原糖含量11.0%。产量和抗性表现：2019~2020年参加江苏省鲜食甜玉米区试，两年平均亩产鲜穗874.0公斤，比对照晶甜3号增产2.5%。2021年参加生产试验，平均亩产鲜穗807.1公斤，比对照晶甜3号增产5.0%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500株左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，亩施纯氮15公斤、五氧化二磷4~5公斤、氧化钾7.5~10公斤。基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕，做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、小斑病等。5、适时采收。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (354, 2, '晶甜17', '苏审玉20230013', '2023.06', 0, '江苏省农作物品种审定委员会', '南京市蔬菜科学研究所', 'H1627B譝T006', '江苏省各地', '特征特性：甜玉米品种。出苗整齐，叶鞘绿色，叶片绿色，叶缘绿色。株型半紧凑，总叶片数19~20片；花药黄色，颖壳绿色，花丝青色；果穗筒形，穗轴白色；籽粒黄色。省区试平均结果：出苗至采收鲜穗86.3天，比对照晶甜3号长1.4天。株高250.7厘米，穗位高94.8厘米；穗长17.8厘米，穗粗5.0厘米，秃尖长0.5厘米，每穗14.8行，每行37.8粒；千粒鲜重349.8克，鲜穗出籽率69.2%；空秆率0.2%，倒伏倒折率1.7%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病，中抗腐霉茎腐病、纹枯病，感瘤黑粉病、南方锈病。江苏省鲜食玉米区试品尝鉴定：外观品质和蒸煮品质88.4分。扬州大学农学院检测：水溶性糖含量20.5%，还原糖含量11.8%。产量和抗性表现：2020~2021年参加江苏省甜玉米区试，两年平均亩产鲜穗880.6公斤，平均比对照晶甜3号增产7.9%。2022年参加生产试验，平均亩产鲜穗868.3公斤，比对照晶甜3号增产5.9%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500株左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量纯氮15公斤、五氧化二磷4~5公斤、氧化钾7.5~10公斤。基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕，做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、小斑病等。5、适时采收。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (355, 2, '晶甜5号', '苏审玉201007', '2010.2', 0, '江苏省农作物品种审定委员会', '南京市蔬菜科学研究所', '403325-4�326B452-2', '适宜在江苏各地种植', '退出批次：特征特性：出苗快而齐，苗势强株型半紧凑花药、颖片均为绿色，花丝淡绿色果穗筒形，鲜粒黄色、半马齿型穗轴白色省区试平均结果：株高181厘米，穗位84厘米成株叶片19-20片，穗长15.9厘米，穗粗4.6厘米，每穗14-16行，每行30粒，全生育期春播89天，倒伏率为0中国农业科学院作物研究所2009年接种鉴定：中抗大斑病及茎腐病，抗小斑病，感纹枯病，高感粗缩病省鲜食玉米品种区域试验组织专家品尝鉴定，外观品质和蒸煮品质达到部颁鲜食甜玉米二级标准扬州大学农学院检测：水溶性糖含量14.3%，还原糖含量6.9%，达到甜玉米标准（NY/T523-2002）产量和抗性表现：2007-2008年参加江苏省甜玉米区域试验，两年区试鲜穗平均亩产745.6公斤，比对照晶甜3号增产10.6%，2007年增产显著，2008年增产极显著2009年生产试验平均亩产722.0公斤，比对照晶甜3号增产9.5%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (356, 2, '晶甜6号', '苏审玉201306', '2013', 0, '江苏省农作物品种审定委员会', '南京市蔬菜研究所', 'H403-12譚458-06', '适宜江苏省各地种植', '退出批次：特征特性：出苗整齐，叶鞘绿色，叶片绿色，叶缘绿色，株型半紧凑，花药黄色，颖壳绿色，花丝青色，果穗筒型，籽粒黄白相间（约3/4黄粒、1/4白粒），硬粒型，穗轴白色两年省区试平均结果：全生育期春播约90天，株高200厘米，穗位82厘米，成株叶片数19片，穗长19.0厘米，穗粗4.4厘米，每穗12-14行，每行34粒，千粒鲜重322克，鲜出籽率69.7%，田间倒伏率8.3%中国农科院作物研究所接种鉴定：感大斑病，抗小斑病，中抗茎腐病，高感纹枯病、粗缩病省鲜食玉米区域试验品种品尝鉴定：外观品质和蒸煮品质达到部颁鲜食甜玉米二级标准；扬州大学农学院检测：水溶性糖含量14.9%，还原糖含量5.0%，达到甜玉米标准（NY/T 523-2002）产量和抗性表现：2009-2011年参加江苏省甜玉米区域试验，三年区试平均亩产鲜穗725.1公斤，比对照晶甜3号增产11.3%，极显著2012年生产试验平均亩产鲜穗676.9公斤，比对照晶甜3号增产3.8%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (357, 2, '晶甜7号', '苏审玉20170007', '2017.04', 0, '江苏省农作物品种审定委员会', '江苏润扬种业股份有限公司、南京市蔬菜科学研究所', '403-11×1041-11，参试名称 “晶甜1301”', '江苏各地', '特征特性：中熟半紧凑型超甜玉米。出苗整齐，叶鞘绿色，叶片绿色，叶缘绿色，株型半紧凑，花药黄色，颖壳绿色，花丝青色，果穗筒型，籽粒黄色，硬粒型，穗轴白色。江苏省区试平均结果：株高244厘米，穗位104厘米，成株叶片数19-20片，穗长19.5厘米，穗粗4.8厘米，每穗14.3行，每行38.5粒，千粒鲜重326克，鲜穗出籽率68.1%。春季播种至采收鲜穗约87天。田间倒伏率0.2%。中国农科院作物研究所接种鉴定：中抗大斑病，抗小斑病，中抗茎腐病，感纹枯病，高感粗缩病。江苏省鲜食玉米区域试验品种品尝鉴定：外观品质和蒸煮品质达到部颁鲜食甜玉米二级标准。扬州大学农学院检测：水溶性糖含量21.8%，还原糖含量9.8%，达到甜玉米标准（NY/T 523-2002）。产量和抗性表现：2014-2015年参加江苏省甜玉米区试，两年区试平均亩产鲜穗817.8公斤，平均比对照晶甜3号增产9.0%；2016年参加江苏省甜玉米生产试验，平均亩产鲜穗802.4公斤，比对照晶甜3号增产3.8%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500株左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量纯氮15公斤、五氧化二磷4-5公斤、氧化钾7.5-10公斤。基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕，做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效低毒低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、纹枯病等。5、适时采收。一般在授粉后20-25天采收青穗。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (358, 2, '晶白甜糯', '苏审玉20190013', '2019.04', 0, '江苏省农作物品种审定委员会', '江苏润扬种业股份有限公司、南京市蔬菜科学研究所', 'QN-51×TN-12', '江苏各地', '特征特性：半紧凑型糯玉米。出苗整齐，苗势强，叶片绿色，株型半紧凑；果穗锥形，籽粒纯白色，甜糯型。省区试平均结果：株高227厘米，穗位高104厘米；穗长20.2厘米，穗粗4.6厘米，每穗13.6行，每行34.5粒。千粒鲜重345克。春季播种至采收鲜穗约88天。鲜穗出籽率67.5%。倒伏倒折率1.0%。中国农科院作物研究所接种及江苏省农科院植保所鉴定：中抗大斑病，感小斑病、茎腐病、纹枯病、南方锈病，高感粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到鲜食糯玉米二级标准。扬州大学农学院检测：支链淀粉占总淀粉的98.4％，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2016-2017年参加江苏省糯玉米区域试验，两年区试平均亩产鲜穗876.8公斤，平均比对照苏玉糯5号增产15.1%。2018年生产试验平均亩产鲜穗882.4 公斤，比对照苏玉糯5号增产11.5%。', '1、适期播种，根据上市时间和不同的栽培方式，合理安排播期。2、合理密植，适宜密度每亩3500-4000株左右。3、加强肥水管理，有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮10公斤、五氧化二磷5公斤，氧化钾7.5~10公斤，基肥占40%，苗肥占20%，穗肥占40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合肥料及时中耕，做好雍根培土以防倒伏。4、病虫害绿色防控。用高效低毒低残留农药及时防治地下害虫，食叶害虫、玉米螟、粗缩病、纹枯病等。5、适时采收，一般在授粉后22~24天采收青穗。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (359, 2, '江南紫糯', '苏审玉200703', '2007.1', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮作所', '574/96408', '适合江苏各地种植', '退出批次：特征特性：出苗整齐，苗势强，幼苗叶鞘绿色，叶缘绿色株型半紧凑，株高194厘米左右，穗位91厘米左右，成株叶片数约19张花药绿色，花丝绿色，果穗长筒形，穗长17.8厘米左右，穗粗4.3厘米左右，每穗14-16行，每行36粒左右籽粒紫色，硬粒型，千粒重262.0克左右全生育期春播90天左右田间调查，抗病抗倒性较强中国农业科学院作物研究所接种鉴定，中抗大斑病、抗小斑病、高感矮花叶病、高感纹枯病江苏省鲜食玉米品种区域试验组织的专家品尝鉴定，外观品质和蒸煮品质达到部颁鲜食糯玉米二级标准扬州大学农学院检测，支链淀粉占淀粉总量的98.16%，达到糯玉米标准（NY/T524-2002）产量和抗性表现：2004-2005年参加江苏省区试，两年鲜果穗平均亩产804.6公斤，较对照苏玉糯1号增产0.9%，2004年减产显著，2005年增产显著；2006年生产试验鲜果穗平均亩产971.2公斤，较对照增产2.5%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (360, 2, '江南花糯', '苏审玉200201', '2002', 0, '江苏省农作物品种审定委员会', '省农科院', '96506�96408', '江苏省各地', '退出批次：特征特性：鲜果穗籽粒多为白色，其中间有淡紫红色，总体外观为花籽；籽粒排列整齐，大小适中，穗型为圆筒型，果穗中等，有秃顶，综合外观印象较优；糯性较好，接近苏玉糯1号，甜度突出；籽粒皮感一般。该品种风味浓郁，粘香绵软，有明显的甜味。春播熟期比对照苏玉糯1号迟2天，早熟性一般。该组合苗期长势较强，株型紧凑，株高为192厘米，穗位88厘米，株高穗位适中，植株田间整齐度好。穗长18.3厘米，穗粗4.4厘米，每穗13.7行，每行35.8粒左右，果穗圆筒型，硬粒型糯玉米。耐旱性、抗倒性较好，抗病性较强。产量和抗性表现：1999-2001年参加江苏省特种玉米新品种中间试验。1999-2000年两年区试平均亩产鲜果穗分别为823.70公斤和781.10公斤，比对照苏玉糯1号增产1.20%和9.70%，均居第3位。2001年参加江苏省特种玉米生产试验，平均亩产鲜果穗844.30公斤，与对照苏玉糯1号持平。', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (361, 2, '江玉1666', '苏审玉20220011', '2022.08', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司', 'D681×W5-1，参试名称“LY1666”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片深绿色，叶缘绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数19片左右；花药紫色，花丝粉红色；果穗筒形，穗型中大，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期103.6天，比对照郑单958短0.4天。株高261.0厘米，穗位高99.1厘米；穗长17.9厘米，穗粗4.9厘米，秃尖长1.1厘米，每穗17.7行，每行33.0粒；千粒重318.6克，出籽率85.3%；空秆率1.1%，倒伏倒折率3.4%。经江苏省农业科学院植物保护研究所接种鉴定：高抗大斑病，抗小斑病，中抗瘤黑粉病，感腐霉茎腐病、纹枯病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重768克/升，粗蛋白9.56%，粗脂肪3.17%，粗淀粉77.27%，赖氨酸0.26%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播区试，两年平均亩产604.8公斤，比对照郑单958增产10.0%。2020年参加生产试验，平均亩产537.3公斤，比对照郑单958增产6.8%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮20~25公斤，其中基苗肥30%~40%，穗肥50%~60%，粒肥10%。做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (362, 2, '江玉206', '苏审玉20190008', '2019.04', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司', '3D×G44，参试名称“DY206”', '江苏省淮北地区夏播', '特征特性：中熟半紧凑型普通玉米。幼苗叶鞘紫色，叶片深绿色，叶缘绿色，生长势强。成株株型半紧凑，茎秆粗壮，总叶片数19片左右；花药紫色，花丝粉红色；果穗筒形，穗型大，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：株高284厘米，穗位高98厘米；穗长19.1厘米，穗粗4.9厘米，秃尖长1.4厘米，每穗15.2行，每行31.5粒。千粒重352克，出籽率84.3%。全生育期104天。倒伏倒折率1.6%。中国农业科学院作物研究所及江苏省农科院植保所接种鉴定：中抗大斑病、南方锈病，感小斑病、茎腐病，高感纹枯病、瘤黑粉病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重796克/升，粗蛋白10.66%，粗脂肪4.44%，粗淀粉72.70%，赖氨酸0.31%。产量和抗性表现：2016~2017年参加江苏省普通玉米淮北区域试验，两年区试平均亩产639.8公斤，比对照郑单958增产5.2%。2018年生产试验平均亩产570.0公斤，比对照郑单958增产5.4%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩3500~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥30%~40%，穗肥50%~60%，粒肥10%。做到田间沟系配套，注意防涝防旱。建议拔节期采取化控措施，提高抗倒性。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (363, 2, '江玉272', '苏审玉20210020', '2021.03', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司', 'D681×W16-1，参试名称“LY272”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片深绿色，叶缘绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数19片左右；花药紫色，花丝粉红色；果穗筒形，穗型中大，穗轴红色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期104.1天，比对照郑单958长0.5天。株高259厘米，穗位高103厘米；穗长17.4厘米，穗粗4.7厘米，秃尖长1.1厘米，每穗16.3行，每行32.0粒；千粒重336克，出籽率85.6%；空秆率2.2%倒伏倒折率3.9%。经江苏省农业科学院植保所接种鉴定：抗大斑病；中抗小斑病、腐霉茎腐病、瘤黑粉病；感纹枯病；高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重778克/升，粗蛋白10.14%，粗脂肪3.37%，粗淀粉73.22%，赖氨酸0.29%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播大华联合体区试，两年平均亩产615.5公斤，比对照郑单958增产6.6%。2020年参加生产试验，平均亩产542.3公斤，比对照郑单958增产7.8%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥30%~40%，穗肥50%~60%，粒肥10%，做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (364, 2, '江玉403', '苏审玉200701', '2007.1', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司', 'S78/S78-1', '适合江苏省夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，叶色深绿，生长势较强株型紧凑，株高219厘米左右，成株叶片19片左右，穗位90厘米左右花药紫色，颖片紫色，花丝红色穗长17.8厘米左右，穗粗4.8厘米左右，每穗12-14行，每行30粒左右，属中大穗型品种籽粒黄色，半马齿型，千粒重323.0克左右全生育期98天左右田间调查，抗病抗倒性较强中国农业科学院作物研究所接种鉴定，抗大斑病、中抗小斑病、高抗矮花叶病、高感纹枯病农业部谷物品质监督检验测试中心（哈尔滨）检测，容重724g/L，粗蛋白9.62%，粗脂肪3.90%，粗淀粉75.05%，赖氨酸0.29%产量和抗性表现：2005-2006年参加江苏省区试，两年平均亩产407.6公斤，较对照郑单958增产12.6%，两年增产均达极显著水平；2006年生产试验平均亩产445.5公斤，较对照增产10.2%', '', 1, '2025-07-22 09:41:27', '2025-07-22 09:41:27');
INSERT INTO `ld_crop_variety` VALUES (365, 2, '江玉501', '苏审玉200903', '2009.2', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司', 'Y24-1譙78-1', '适宜江苏夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，叶鞘紫色，生长势强，叶片深绿。株型紧凑。花药紫色，颖片绿带紫色，花丝红色。果柄较短，果穗筒形，籽粒黄色，半硬粒型，穗轴白色。省区试平均结果：株高204厘米，成株叶片20片，穗位87厘米。穗长19.9厘米左右，穗粗4.7厘米，每穗12-14行，每行36粒。千粒重343.0克，全生育期约102天。抗倒性较强。中国农业科学院作物研究所接种鉴定，感大斑病，抗小斑病，高抗茎腐病，高感纹枯病；江苏省农科院植保所接种鉴定高感粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测，容重728克/升，粗蛋白8.6%，粗脂肪4.5%，粗淀粉74.0%，赖氨酸0.3%。产量和抗性表现：2006-2007年参加江苏省夏播玉米区域试验，两年区试平均亩产471.4公斤，比对照郑单958增产11.9%，两年增产均达极显著。2008年生产试验平均亩产537.1公斤，比对照郑单958增产7.0%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (366, 2, '江玉668', '苏审玉20220014', '2022.08', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司', 'S41×S红11，参试名称“LY1825”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片深绿色，叶缘绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数19片左右；花药紫色，花丝粉红色；果穗筒形，穗型中大，穗轴红色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期103.7天，比对照郑单958长0.5天。株高233.0厘米，穗位高96.1厘米；穗长19.5厘米，穗粗4.7厘米，秃尖长1.7厘米，每穗15.9行，每行35.6粒；千粒重336.1克，出籽率86.4%；空秆率0.6%，倒伏倒折率1.3%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病，中抗小斑病、纹枯病，感腐霉茎腐病、瘤黑粉病，高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重757克/升，粗蛋白8.92%，粗脂肪3.48%，粗淀粉76.82%，赖氨酸0.25%。产量和抗性表现：2019~2020年参加江苏省淮北（大华）普通玉米新品种联合体区试，两年平均亩产623.0公斤，比对照郑单958增产12.9%。2021年参加生产试验，平均亩产486.6公斤，比对照郑单958增产13.1%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮20~25公斤，其中基苗肥30%~40%，穗肥50%~60%，粒肥10%。做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好纹枯病、南方锈病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (367, 2, '江玉828', '苏审玉20230014', '2023.06', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司', 'S87譙2-1', '江苏省淮南地区春播', '特征特性：普通玉米品种。幼苗叶鞘紫色，叶片深绿色，叶缘绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数19片左右；花药紫色，颖壳浅紫色；果穗筒形，穗型中大，穗轴红色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期119.5天，比对照苏玉29短3.9天。株高245.3厘米，穗位高98.8厘米；穗长18.7厘米，穗粗5.0厘米，秃尖长1.3厘米，每穗15.4行，每行34.7粒。千粒重345.5克，出籽率87.5%。空秆率0.8%，倒伏倒折率4.1%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病、穗腐病、瘤黑粉病，中抗纹枯病，感腐霉茎腐病、弯孢菌叶斑病，高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重744克/升，粗蛋白10.18%，粗脂肪3.12%，粗淀粉71.04%，赖氨酸0.36%。产量和抗性表现：2019~2021年参加江苏省淮南普通玉米科企联合体区试，两年平均亩产663.6公斤，比对照苏玉29增产10.0%。2022年参加生产试验，平均亩产632.0公斤，比对照苏玉29增产8.7%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮20~25公斤，其中基苗肥30%~40%，穗肥50%~60%，粒肥10%。做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、南方锈病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (368, 2, '江玉877', '苏审玉 201502', '2015', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司', 'SD7證110-6', '适宜江苏淮北地区夏播种植', '退出批次：特征特性：幼苗叶鞘紫色，子叶椭圆形，叶色深绿，叶缘绿色，生长势强株型半紧凑，茎秆粗壮成株叶色深绿，颖片紫色，花药紫色，花丝紫红色；果穗筒形，穗轴红色；籽粒黄色，半马齿型省区试平均结果：株高246厘米，成株叶片19片，穗位高96厘米；穗长18.4厘米，穗粗5.0厘米，秃尖长1.5厘米，每穗15.5行，每行33粒千粒重324克，出籽率86.5%全生育期102天倒伏率0.3%病害经中国农业科学院作物研究所接种鉴定：中抗大斑病、小斑病、茎腐病，高感纹枯病、粗缩病品质经农业部谷物品质监督检验测试中心（哈尔滨）检测：容重736克/升，粗蛋白8.52%，粗脂肪3.74%，粗淀粉76.65%，赖氨酸0.29%产量和抗性表现：2012-2013年参加江苏省普通玉米夏播区域试验，两年区试平均亩产610.6公斤，比对照郑单958增产9.9%，两年增产均极显著2014年生产试验平均亩产587.6公斤，比对照郑单958增产7.2%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (369, 2, '江玉898', '苏审玉20180004', '2018.05', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司', 'G3×Y24-1S3，参试名称Ly1312', '江苏省淮北地区夏播', '特征特性：中熟紧凑型普通玉米。幼苗叶鞘紫色，叶片深绿色，叶缘紫色，生长势强。成株株型半紧凑，茎秆粗壮，总叶片数19片左右；花药紫色，花丝粉红色；果穗筒形，穗型大，穗轴白色；籽粒黄色，半硬粒型。省区试平均结果：株高272厘米，穗位高113厘米；穗长17.9厘米，穗粗4.9厘米，秃尖长0.4厘米，每穗14.6行，每行35粒。千粒重322克，出籽率87.0%。全生育期103天。倒伏率2.2%。中国农业科学院作物研究所接种鉴定：中抗大斑病，感小斑病，高感纹枯病，抗腐霉茎腐病，抗南方锈病，感瘤黑粉病，高感粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重762克/升，粗蛋白9.14%，粗脂肪4.32%，粗淀粉74.32%，赖氨酸0.26%。产量和抗性表现：2015~2016年参加江苏省普通玉米淮北区域试验，两年区试平均亩产652.2公斤，比对照郑单958增产5.7%。2017年生产试验平均亩产633.9公斤，比对照郑单958增产7.2%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20~25公斤，其中基苗肥30%~40%，穗肥50%~60%，粒肥10%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (370, 2, '江玉916', '苏审玉20190003', '2019.04', 0, '江苏省农作物品种审定委员会', '安徽源隆生态农业有限公司、宿迁中江种业有限公司', '3D×G23-2-2', '江苏省淮南地区', '特征特性：中熟半紧凑型普通玉米。幼苗叶鞘浅紫色，叶缘绿色，生长势强。成株株型半紧凑，茎秆粗壮，总叶片数19片左右；花药浅紫色，花丝浅红色；果穗筒形，穗型中等，穗轴白色；籽粒黄色，半硬粒型。省区试平均结果：株高257厘米，穗位高101厘米；穗长16.4厘米，穗粗5.0厘米，秃尖长1.2厘米，每穗15.8行，每行30.0粒。千粒重343克，出籽率82.6%。全生育期118天，比对照早4天。倒伏倒折率2.5%。中国农业科学院作物研究所及江苏省农科院植保所接种鉴定：中抗大斑病、茎腐病、瘤黑粉病、南方锈病，感小斑病，高感纹枯病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重764克/升，粗蛋白11.27%，粗脂肪3.99%，粗淀粉75.47%，赖氨酸0.31%。产量和抗性表现：2016~2017年参加江苏省普通玉米淮南区域试验，两年区试平均亩产564.5公斤，比对照苏玉29增产8.7%。2018年生产试验平均亩产598.8公斤，比对照苏玉29增产8.7%。', '1、适期播种。一般4月上中播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥30%~40%，穗肥50%~60%，粒肥10%。做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (371, 2, '江玉青贮277', '苏审玉20230017', '2023.06', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司', 'G318-1譙78-1-1', '江苏省淮北地区夏播', '特征特性：青贮玉米品种。幼苗叶鞘紫色，叶片深绿色，叶缘绿色，生长势较强。株型半紧凑，茎秆粗壮，总叶片数19片左右；花药紫色，花丝红色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：出苗至收获94.3天，与对照雅玉青贮8号相当。株高260.8厘米，穗位高104.4厘米；无空秆，无倒伏倒折。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病、腐霉茎腐病、纹枯病、弯孢菌叶斑病、穗腐病，感瘤黑粉病、南方锈病。经北京农学院植物科学技术学院品质检测：全株淀粉含量34.3%，中性洗涤纤维含量33.7%，酸性洗涤纤维含量18.0%，粗蛋白质含量8.7%。产量和抗性表现：2020~2021年自主区试两年平均亩产1261.3公斤，比对照雅玉青贮8号增产6.9%。2022年自主生产试验，平均亩产1281.8公斤，比对照雅玉青贮8号增产6.3%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩5000株左右。3、加强肥水管理。施足基肥，补施苗肥，早施重施穗肥，有机肥和复合肥基施。基肥和孕穗肥施氮比4:6或5:5。每亩施肥总量一般不低于纯氮25公斤、五氧化二磷12公斤、氧化钾15公斤。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、瘤黑粉病、南方锈病、玉米螟等的防治工作。5、适时收获。全株含水量60~70%时收获。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (372, 2, '泰玉十四号', '苏审玉200803', '2008.1', 0, '江苏省农作物品种审定委员会', '山东省泰安市农星种业有限公司', '泰039系×泰13系', '适宜江苏省作夏玉米种植', '退出批次：特征特性：出苗快而齐，苗势强，叶鞘紫色，生长势强，叶片深绿、上冲，叶缘紫色，株型紧凑，花药粉红色，颖片绿带紫色，花丝黄绿色，籽粒黄色，半马齿型，穗轴红色省区试平均结果：株高230厘米，成株叶片19片，穗位93厘米，穗长19.2厘米，穗粗4.7厘米，每穗12-14行，每行32粒，千粒重315.0克，全生育期97天抗倒性较强中国农业科学院作物研究所接种鉴定，高抗大斑病、抗小斑病、感纹枯病，江苏省农科院植保所接种鉴定感粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测，容重718g/L，粗蛋白9.14%，粗脂肪4.33%，粗淀粉73.56%，赖氨酸0.26%产量和抗性表现：2005-2006年参加江苏省夏播玉米区试，两年平均亩产401.2公斤，比对照郑单958增产10.3%，两年均增产极显著2007年生产试验平均亩产506.4公斤，比对照增产6.8%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (373, 2, '浙糯208', '苏审玉20230010', '2023.06', 0, '江苏省农作物品种审定委员会', '浙江省农业科学院玉米与特色旱粮研究所', 'LQ52譠2H4', '江苏省各地', '特征特性：鲜食糯玉米品种。幼苗叶鞘淡紫色，叶片绿色，生长势强。株型半紧凑；花药淡红色，花丝淡红色；果穗长锥形，籽粒白色；穗轴白色。省区试平均结果：出苗至采收鲜穗83.0天，比对照苏玉糯5号长2.1天。株高240.4厘米，穗位高107.9厘米；穗长19.2厘米，穗粗4.8厘米，秃尖长1.0厘米，每穗14.7行，每行37.2粒。千粒鲜重299.7克，鲜穗出籽率61.8%。空秆率0.2%，倒伏倒折率0.4%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病、纹枯病，中抗腐霉茎腐病，感瘤黑粉病、南方锈病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质87.7分。扬州大学农学院检测：支链淀粉占总淀粉的97.3%。产量和抗性表现：2020~2021年参加江苏省糯玉米区试，两年平均亩产鲜穗895.6公斤，比对照苏玉糯5号增产15.9%。2022年参加生产试验，平均亩产鲜穗891.2公斤，比对照苏玉糯5号增产14.8%。', '1、适期播种，根据上市时间和不同的栽培方式，合理安排播期。2、合理密植，适宜密度每亩3500株左右。3、加强肥水管理，有机肥及氮、磷、钾搭配合理，每亩施复合肥（N:P:K=15:15:15）40公斤，尿素10公斤，其中基肥占50%，苗肥占30%，穗肥占20%，注意防涝防旱。4、注意病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、小斑病、纹枯病等。5、适时采收，一般在授粉后22~24天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (374, 2, '海鲜玉1号', '苏审玉200704', '2007.1', 0, '江苏省农作物品种审定委员会', '海门农业科学研究所', '98B07/98A08', '适合江苏各地种植', '退出批次：特征特性：出苗快而齐，生长势较强，株型半紧凑，株高189厘米左右，穗位91厘米左右，成株叶片18-19片穗长15.9厘米左右，穗粗4.2厘米左右，每穗14-16行，每行33粒左右籽粒花色，马齿型，千粒重232.0克左右全生育期89天左右田间调查，抗病抗倒性较强中国农业科学院作物研究所接种鉴定，感大斑病、感小斑病、高感矮花叶病、高感纹枯病江苏省鲜食玉米品种区域试验组织的专家品尝鉴定，外观品质和蒸煮品质达到部颁鲜食糯玉米二级标准扬州大学农学院检测，支链淀粉占淀粉总量的98.09%，达到糯玉米标准（NY/T524-2002）产量和抗性表现：2004-2005年参加江苏省区试，两年鲜果穗平均亩产758.4公斤，较对照苏玉糯1号减产5.1%，2004年减产显著，2005年减产不显著；2006年生产试验鲜果穗平均亩产912.7公斤，较对照减产3.6%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (375, 2, '润扬玉702', '苏审玉20220006', '2022.08', 0, '江苏省农作物品种审定委员会', '江苏润扬种业股份有限公司、山东太丰种业有限公司', 'T260C×T51A，参试名称“润扬702”', '江苏省淮南地区春播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，第一叶椭圆形，叶色中绿，叶缘绿色，生长势较强。株型半紧凑，茎秆粗壮，成株叶色中绿；花药浅紫色，颖壳浅紫色，花丝淡黄色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期121.1天，比对照苏玉29短1.4天。株高260.4厘米，穗位高107.9厘米；穗长17.7厘米，穗粗5.2厘米，秃尖长1.1厘米，每穗16.2行，每行33.4粒；千粒重353.6克，出籽率84.3%；空秆率0.8%，倒伏倒折率11.3%。经江苏省农业科学院植物保护研究所接种鉴定：高抗大斑病、小斑病，中抗纹枯病、瘤黑粉病，感腐霉茎腐病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重763克/升，粗蛋白9.47%，粗脂肪3.80%，粗淀粉75.51%，赖氨酸0.27%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮南春播区试，两年平均亩产668.9公斤，比对照苏玉29增产14.9%。2020年参加生产试验，平均亩产609.8公斤，比对照苏玉29增产15.7%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4500株左右。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮20公斤左右，其中基苗肥60%，穗粒肥40%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好南方锈病、茎基腐病、玉米螟等病虫害的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (376, 2, '淮玉1420', '苏审玉20210011', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所', 'H027×Y090，参试名称“HY1420”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势较强。株型紧凑，茎秆粗壮，总叶片数19~20片，成株叶色绿色；花药淡红色，颖壳紫色，花丝淡红色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期104.9天，比对照郑单958长0.8天。株高232厘米，穗位高94厘米；穗长17.6厘米，穗粗5.0厘米，秃尖长0.7厘米，每穗16.5行，每行30.9粒；千粒重334克，出籽率85.1%；空秆率0.8%，倒伏倒折率0.5%。经中国农业科学院作物科学研究所、江苏省农业科学院植保所接种鉴定：抗大斑病、小斑病；中抗腐霉茎腐病；感纹枯病、瘤黑粉病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2019年检测：容重759克/升，粗蛋白10.45%，粗脂肪3.62%，粗淀粉72.61%，赖氨酸0.28%。产量和抗性表现：2017~2018年参加江苏省普通玉米淮北夏播区试，两年平均亩产601.5公斤，比对照郑单958增产6.2%。2019年参加生产试验，平均亩产629.1公斤，比对照郑单958增产6.8%。', '1、适期播种。夏播一般6月20日左右。2、合理密植。适宜密度每亩4200株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕，做好壅土培根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、瘤黑粉病、南方锈病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (377, 2, '淮玉1606', '苏审玉20210015', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所', 'T7916×F2406，参试名称“淮1606”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势较强。株型紧凑，茎秆粗壮，总叶片数19~20片，成株叶色绿色，颖壳紫色；花药淡红色，颖壳紫色，花丝紫色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期104.9天，比对照郑单958长0.2天。株高251厘米，穗位高100厘米；穗长18.8厘米，穗粗4.6厘米，秃尖长0.4厘米，每穗15.7行，每行35.8粒，千粒重323克，出籽率85.4%；空秆率1.3%，倒伏倒折率4.0%。经江苏省农业科学院植保所接种鉴定：高抗小斑病；抗大斑病；中抗纹枯病；感腐霉茎腐病、瘤黑粉病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重751克/升，粗蛋白9.19%，粗脂肪3.60%，粗淀粉74.87%，赖氨酸0.27%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播省农科院联合体区试，两年平均亩产621.7公斤，比对照郑单958增产10.2%。2020年参加生产试验，平均亩产578.5公斤，比对照郑单958增产9.9%。', '1、适期播种。夏播一般6月20日左右。2、合理密植。适宜密度每亩4200株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕，做好壅土培根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好腐霉茎腐病、瘤黑粉病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (378, 2, '淮玉7967', '苏审玉20220010', '2022.08', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农业科学研究所', 'T7958×F2467，参试名称“淮7967”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势较强。株型半紧凑，茎秆粗壮，总叶片数19~20片，成株叶色绿色；花药淡红色，颖壳绿色，花丝绿色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：全生育期102.8天，比对照郑单958短0.5天。株高241.6厘米，穗位高97.7厘米；穗长17.2厘米，穗粗5.0厘米，秃尖长0.5厘米，每穗14.8行，每行32.5粒；千粒重369.0克，出籽率84.0%；空秆率0.2%，倒伏倒折率1.9%。经江苏省农业科学院植物保护研究所接种鉴定：高抗大斑病，抗小斑病，中抗纹枯病，感腐霉茎腐病、瘤黑粉病，高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重720克/升，粗蛋白9.45%，粗脂肪3.24%，粗淀粉74.64%，赖氨酸0.26%。产量和抗性表现：2019~2020年参加江苏省普通玉米淮北夏播区试，两年平均亩产565.4公斤，比对照郑单958增产7.7%。2021年参加生产试验，平均亩产476.0公斤，比对照郑单958增产13.0%。', '1、适期播种。一般6月20日左右。2、合理密植。适宜密度每亩4200株左右。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕，做好壅土培根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好腐霉茎腐病、瘤黑粉病、南方锈病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (379, 2, '焦点玉1301', '苏审玉20180003', '2018.05', 0, '江苏省农作物品种审定委员会', '江苏焦点农业科技有限公司、江苏省农业科学院粮食作物研究所', 'PH6WC×JSPH730，参试名称“明玉1301”', '江苏省淮北地区夏播', '特征特性：中熟半紧凑型普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势强。株型半紧凑，全株叶片数18片左右 ，花药浅红色，花丝淡红色；果穗筒形，穗轴白色；籽粒黄色，半硬粒型。省区试平均结果：株高288厘米，穗位高112厘米；穗长20.2厘米，穗粗4.6厘米，每穗15.4行，每行34粒。千粒重329克，出籽率85.2%。全生育期104天。倒伏率2.9%。中国农业科学院作物研究所接种鉴定：中抗大斑病，感小斑病，高感纹枯病，感腐霉茎腐病，感瘤黑粉病，抗南方锈病，高感粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重773克/升，粗蛋白8.83%，粗脂肪3.19%，粗淀粉75.90%，赖氨酸0.25%。产量和抗性表现：2015~2016年参加江苏省普通玉米夏播区域试验，两年区试平均亩产641.4公斤，比对照郑单958增产3.9%。2017年生产试验平均亩产618.9公斤，比对照郑单958增产4.7%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (380, 2, '焦点玉1303', '苏审玉20170003', '2017.04', 0, '江苏省农作物品种审定委员会', '江苏焦点农业科技有限公司、江苏沿江地区农业科学研究所', 'TS44×T8735，参试名称 “P1303”', '江苏淮南地区春播', '特征特性：中熟半紧凑型普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强。株型半紧凑。成株叶色深绿；花药黄色，颖壳紫色，花丝粉红色；果穗锥形，籽粒黄色，半马齿型，穗轴白色。省区试平均结果：株高260厘米，穗位高95厘米，穗长16.9厘米，穗粗4.9厘米，平均每穗15行，每行32.5粒，千粒重313克，出籽率85.4%。倒伏率2.9%。中国农业科学院作物研究所接种鉴定：中抗大斑病、抗小斑病，感茎腐病、纹枯病、瘤黑粉病，抗粗缩病，中抗南方锈病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重728克/升，粗蛋白11.26%，粗脂肪4.06%，粗淀粉70.33%，赖氨酸0.35%。产量和抗性表现：2014-2015年参加江苏省普通玉米春播区域试验，两年区试平均亩产550.7公斤，比对照苏玉29增产4.8%。2016年生产试验平均亩产536.7公斤，比对照苏玉29增产9.5%。', '1、适期播种。一般4月初播种。2、合理密植。适宜密度每亩4200株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20-25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕、做好培土壅根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、茎腐病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (381, 2, '瑞华968', '苏审玉 201403', '2014', 0, '江苏省农作物品种审定委员会', '江苏瑞华农业科技有限公司', 'S007譞24-2', '适宜江苏淮北夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，叶鞘紫色，生长势强，叶片深绿株型紧凑花药紫色，颖片绿色，花丝红色果柄较短，果穗筒形，籽粒黄色，半马齿型，穗轴白色省区试平均结果：株高268厘米，成株叶片19片，穗位95厘米，穗长17.5厘米，穗粗4.9厘米，每穗16.1行，每行31粒，千粒重303.0克，出籽率85.7%全生育期约100天倒伏率1.4%中国农业科学院作物研究所接种鉴定：中抗大斑病、小斑病、茎腐病，高感纹枯病、粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重766克/升，粗蛋白8.70%，粗脂肪3.32%，粗淀粉75.11%，赖氨酸0.26%产量和抗性表现：2011~2012年参加江苏省夏播玉米区域试验，两年区试平均亩产550.1公斤，比对照郑单958增产6.8%，两年增产均达极显著2013年生产试验平均亩产542.0公斤，比对照郑单958增产3.7%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (382, 2, '瑞华玉288', '苏审玉20200005', '2020.06', 0, '江苏省农作物品种审定委员会', '江苏瑞华农业科技有限公司', '288-1×W5-4，参试名称“瑞友288”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，子叶卵圆形，叶色绿色，叶缘紫色，生长势强。株型紧凑，茎秆粗壮，总叶片数19片左右；成株叶色深绿，花药淡紫色，颖壳绿色，花丝绿色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期104天，与对照郑单958相当。株高240厘米，穗位高98厘米；穗长18.0厘米，穗粗5.0厘米，秃尖长0.9厘米，每穗15.3行，每行33.1粒，千粒重343克，出籽率84.5%；空秆率0.5%，倒伏倒折率1.6%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：抗大斑病、小斑病、南方锈病；感纹枯病、腐霉茎腐病、瘤黑粉病；高感粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重772克/升，粗蛋白10.0%，粗脂肪4.0%，粗淀粉73.3%，赖氨酸0.28%。产量和抗性表现：2017~2018年参加江苏省普通玉米淮北夏播区试，两年平均亩产620.0公斤，比对照郑单958增产9.6%。2019年参加生产试验，平均亩产637.3公斤，比对照郑单958增产8.2%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，五氧化二磷10公斤，氧化钾15公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、腐霉茎腐病、瘤黑粉病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (383, 2, '瑞华玉701', '苏审玉20210006', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏瑞华农业科技有限公司、莱州市太丰种业有限公司', 'ZH01×YG12', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，子叶卵圆形，叶色绿色，叶缘紫色，生长势强。株型半紧凑，叶片19片，成株叶色深绿，颖片绿色；花药淡紫色，花丝绿色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期104.2天，比对照郑单958长0.3天。株高254厘米，穗位高101厘米；穗长17.7厘米，穗粗4.8厘米，秃尖长0.5厘米，每穗17.0行，每行32.1粒；千粒重340克，出籽率85.8%；空秆率0.7%，倒伏倒折率1.3%。经江苏省农业科学院植保所接种鉴定：高抗大斑病、小斑病；中抗腐霉茎腐病、瘤黑粉病、南方锈病；感纹枯病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重752克/升，粗蛋白8.39%，粗脂肪3.84%，粗淀粉76.24%，赖氨酸0.25%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播区试，两年平均亩产597.3公斤，比对照郑单958增产8.7%。2020年参加生产试验，平均亩产545.3公斤，比对照郑单958增产8.4%。', '1、适期播种。夏播一般6月中下旬播种。2、合理密植。每亩留苗4200株左右。3、科学施肥。重施基肥，亩施氮磷钾复合肥（15-15-15）40千克左右；早追苗肥，展5~6叶期亩追施尿素8千克；重施穗肥，展10~12叶期亩追施尿素20千克左右。4、水分管理。做到田间沟系配套，注意防涝防旱，造墒或播后浇水以保证一播全苗，大喇叭口期和籽粒灌浆期遇旱应浇水，遇连阴雨或强降水时应及时排涝，防止积水。5、病虫害防治。及时防治病虫害，苗期主要防治地老虎等地下害虫，中期注意防治蚜虫控制病毒病的发生，大喇叭口期防治玉米螟，注意防治纹枯病等。6、适时收获。以苞叶发黄一周后收获为宜。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (384, 2, '白玉219', '苏种审字第378号', '2000', 0, '江苏省农作物品种审定委员会', '淮阴地区农科所', 'H69�219', '江苏作夏玉米种植', '退出批次：特征特性：苗势较强。株型紧凑，株高248厘米，穗位高107厘米，穗长15厘米，穗粗4.5厘米，穗行14.8行，行粒数33粒，千粒重278克，出籽率86%。籽粒白色，半硬粒型,商品性好。生育期104天。抗倒性较强，抗大、小斑病。品质分析结果：粗蛋白10.80%，粗脂肪3.40%，粗淀粉59.70%，赖氨酸0.32%（淮阴市农科所中心化验室，2000年2月）。产量和抗性表现：1997-1998年两年参加江苏省春、夏播组玉米新品种区域试验，春播组两年平均亩产分别为529.30公斤和571.90公斤，比对照苏玉9号减产6.30%（极显著）和增产1.10%（不显著），均居七位和第二位。夏播组两年平均亩分别为434.30公斤和484.20公斤，比对照苏玉9号减产2.50%（不显著）和增产3.60%（不显著），分别居第七位和第一位。1999年省玉米夏播组生产试验，平均亩产486.20公斤，比对照苏玉9号增产1.70%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (385, 2, '白甜糯209', '苏审玉20210028', '2021.03', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院、江苏金万禾农业科技有限公司', 'LN38×LN205，参试名称“连甜糯209”', '江苏省各地', '特征特性：中早熟鲜食甜糯玉米。幼苗叶鞘紫色，叶片淡绿色。株型半紧凑，总叶片数17片左右；花药黄色，颖壳淡绿色，花丝淡紫色；果穗锥形，穗轴白色；籽粒白色，籽粒甜糯比例1:3。省区试平均结果：出苗至采收鲜穗83.0天，比对照苏玉糯5号长0.6天。株高219厘米，穗位高104厘米；穗长19.1厘米，穗粗4.5厘米，秃尖长0.5厘米，每穗14.0行，每行32.8粒；千粒鲜重341克，鲜穗出籽率66.7%；空秆率0.2%，倒伏倒折率0.9%。经中国农业科学院作物科学研究所、江苏省农业科学院植保所接种鉴定：抗大斑病；中抗小斑病、纹枯病；感瘤黑粉病；高感腐霉茎腐病、南方锈病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质85.3分。扬州大学农学院检测：支链淀粉占总淀粉的98.5%。产量和抗性表现：2017~2018年参加江苏省糯玉米区试，两年平均亩产鲜穗841.4公斤，比对照苏玉糯5号增产9.1%。2019年参加生产试验，平均亩产鲜穗896.1公斤，比对照苏玉糯5号增产14.7%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期，播种须保证土壤温度稳定在12摄氏度以上。2、合理密植。适宜密度每亩4000~4500株左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量一般不低于纯氮20公斤、五氧化二磷10公斤、氧化钾15公斤。肥料分配一般为基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕，做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效低毒低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、大斑病等。5、适时采收。一般在授粉后20~24天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (386, 2, '皖垦玉125', '苏审玉20180005', '2018.05', 0, '江苏省农作物品种审定委员会', '安徽皖垦种业股份有限公司', '皖自8101×皖自4379，参试名称皖垦玉125', '江苏省淮北地区夏播', '特征特性：中熟紧凑型普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势强。成株株型紧凑，总叶片数19片左右；花药浅紫色，花丝紫青色，颖壳绿色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：株高296厘米，穗位高117厘米；穗长17.5厘米，穗粗5.2厘米，每穗16.1行，每行35.8粒。千粒重303克，出籽率86.1%。全生育期104天。倒伏率6.3%。中国农业科学院作物研究所接种鉴定：中抗大斑病、感小斑病，高感纹枯病，中抗腐霉茎腐病、南方锈病，高感瘤黑粉病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重713克/升，粗蛋白8.36%，粗脂肪4.02%，粗淀粉71.95%，赖氨酸0.30%。产量和抗性表现：2014~2015年参加江苏省普通玉米夏播区域试验，两年区试平均亩产596.0公斤，比对照郑单958增产5.4%。2016年生产试验平均亩产660.5公斤，比对照郑单958增产7.8%。', '1、适期早播。一般6月20日前播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，一般亩施纯氮20~25公斤，其中基肥60%，穗粒肥40%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (387, 2, '神农美玉16', '苏审玉20220016', '2022.08', 0, '江苏省农作物品种审定委员会', '江苏神农大丰种业科技有限公司', 'J14861M譐9692F', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势较强。株型半紧凑，茎秆粗壮，成株叶片绿色；花药黄色，颖壳淡绿色，花丝绿色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期103.2天，与对照郑单958相当。株高242.9厘米，穗位高100.2厘米；穗长18.3厘米，穗粗4.6厘米，秃尖长1.2厘米，每穗16.6行，每行34.9粒；千粒重302.4克，出籽率85.9%；空秆率0.9%，倒伏倒折率2.4%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、腐霉茎腐病、纹枯病，中抗小斑病，感瘤黑粉病，高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重751克/升，粗蛋白8.53%，粗脂肪3.39%，粗淀粉77.12%，赖氨酸0.25%。产量和抗性表现：2019~2020年参加江苏省淮北普通玉米大华种业科企联合体区试，两年平均亩产598.7公斤，比对照郑单958增产8.3%。2021年参加生产试验，平均亩产455.9公斤，比对照郑单958增产6.0%。', '1、适期播种。一般6月上中旬播种，每亩用种量2.0~2.5公斤左右。 2、合理密植。纯作、套作均可，密度每亩4500株左右。 3、科学施肥。氮、磷、钾配合使用，亩施纯氮20~25公斤，其中基苗肥60%，穗肥40%，肥力差的田块可适当施粒肥。4、精选地，避开靠近稻田的地势低洼地种植，中后期注意防涝防旱。结合施肥及时中耕、做好壅土培根以防倒伏。5、病虫害防治。播前种子药剂处理，苗期注意防治地下害虫；大喇叭口期用颗粒剂灌心防治玉米螟；做好南方锈病等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (388, 2, '神农美玉18', '苏审玉20170002', '2017.04', 0, '江苏省农作物品种审定委员会', '江苏神农大丰种业科技有限公司', 'ZH102×ZH14，参试名称“ZH918”', '江苏淮南地区春播', '特征特性：早熟半紧凑型普通玉米。幼苗叶鞘紫色，叶片淡绿色，叶缘绿色，生长势较强。株型半紧凑，茎秆粗壮，成株叶色淡绿，花药红色，颖壳淡紫色；花丝粉红色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：株高268厘米，穗位高98厘米；穗长15.7厘米，穗粗4.9厘米，秃尖长1.0厘米，每穗16.1行，每行32粒。千粒重312克，出籽率85.8%。全生育期116天。倒伏率1.5%。散粉期持续阴雨寡照易导致结实不良。中国农业科学院作物研究所接种鉴定：中抗茎腐病、大斑病、南方锈病，感小斑病，高感纹枯病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重706克/升，粗蛋白9.72%，粗脂肪4.80%，粗淀粉71.91%，赖氨酸0.35%。产量和抗性表现：2014-2015年参加江苏省淮南普通玉米区试，两年区试平均亩产568.8公斤，比对照苏玉29增产8.2%， 2016年参加江苏省淮南普通玉米生产试验，平均亩产499.5公斤，比对照苏玉29增产2.0%。', '1、适期播种。一般4月初播种。2、合理密植。适宜密度每亩4500株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20-25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (389, 2, '神农美玉78', '苏审玉20200007', '2020.06', 0, '江苏省农作物品种审定委员会', '江苏神农大丰种业科技有限公司、北京联丰良种技术有限公司', 'J0097×DH12-11- 33，参试名称“HA054”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势较强。株型半紧凑，茎秆粗壮，总叶片数19~21片，成株叶色淡绿；花药黄色，颖壳淡紫色，花丝浅红色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期103天，较对照郑单958短1天。株高259厘米，穗位高93厘米；穗长17.2厘米，穗粗4.7厘米，秃尖长0.4厘米，每穗15.3行，每行35.9粒，千粒重313克，出籽率87.3%；空秆率0.5%，倒伏倒折率0.3%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：高抗腐霉茎腐病；抗大斑病、小斑病；感纹枯病、瘤黑粉病、南方锈病；高感粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重772克/升，粗蛋白10.8%，粗脂肪3.9%，粗淀粉71.5%，赖氨酸0.28%。产量和抗性表现：2017~2018年参加江苏省普通玉米淮北夏播区试，两年平均亩产606.6公斤，比对照郑单958增产7.1%。2019年参加生产试验，平均亩产625.4公斤，比对照郑单958增产6.2%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4500株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好纹枯病、瘤黑粉病、南方锈病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (390, 2, '神玉2号', '苏审玉200602', '2006.1', 0, '江苏省农作物品种审定委员会', '南京神州种业有限公司', 'H87譎991', '适宜江苏夏播地区种植', '退出批次：特征特性：全生育期春播115天左右，夏播96天左右。出苗较齐，苗势较强，幼苗叶鞘紫色，叶片绿色，叶缘紫色。株型半紧凑，株高203厘米左右，穗位82厘米左右，成株叶片数19片左右。花药紫色，颖壳浅紫色，花丝青-浅红色，穗长17.3厘米左右，穗粗4.7厘米左右，秃顶1.1厘米左右，每穗14行左右，每行33粒左右，籽粒黄色，粒型半硬粒型，千粒重290.4克左右，出籽率86.8%左右。田间观察病害发生轻，抗倒性强。中国农业科学院作物科学研究所接种鉴定，抗大斑病、小斑病、纹枯病，感矮花叶病。农业部谷物品质监督检验测试中心（北京）检测，容重722g/L，粗蛋白10.51%，粗脂肪3.84%，粗淀粉69.84%，赖氨酸0.38%。产量和抗性表现：2004-2005年参加江苏省区试，两年区试春播平均亩产509.5公斤，2004年较对照苏玉9号增产34.0%，极显著；2005年较对照苏玉19减产2.2%，不显著。两年区试夏播平均亩产455.7公斤，2004年较对照苏玉9号增产4.6%，2005年较对照苏玉19增产8.6%，两年增产均极显著。2005年生产试验春播亩产494.8公斤，较对照苏玉19减产0.7%；夏播亩产430.1公斤，较对照苏玉19增产8.8%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (391, 2, '神玉3号', '苏审玉20210012', '2021.03', 0, '江苏省农作物品种审定委员会', '南京神州种业研究院有限公司', 'sz5135×sz5323，参试名称“神玉3523”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片深绿色，叶缘绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数19片左右；花药黄色，花丝粉红色；果穗筒形，穗型大，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：全生育期105.0天，比对照郑单958长0.9天。株高269厘米，穗位高89厘米；穗长17.9厘米，穗粗4.8厘米，秃尖长0.8厘米，每穗14.9行，每行33.7粒；千粒重337克，出籽率84.9%；空秆率0.8%，倒伏倒折率0.2%。经中国农业科学院作物科学研究所、江苏省农业科学院植保所接种鉴定：抗小斑病；中抗大斑病、腐霉茎腐病、瘤黑粉病；感南方锈病；高感纹枯病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2019年检测：容重752克/升，粗蛋白10.21%，粗脂肪3.35%，粗淀粉73.84%，赖氨酸0.28%。产量和抗性表现：2017~2018年参加江苏省普通玉米淮北夏播区试，两年平均亩产590.0公斤，比对照郑单958增产4.2%。2019年参加生产试验，平均亩产616.9公斤，比对照郑单958增产4.8%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩3500~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥30~40%，穗肥50~60%，粒肥10%。做到田间沟系配套，注意防涝防旱。建议拔节期采取化控措施，提高抗倒性。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (392, 2, '红旗1302', '苏审玉20190009', '2019.04', 0, '江苏省农作物品种审定委员会', '江苏红旗种业股份有限公司、安徽红旗种业科技有限公司', 'KRL002×KRL011，参试名称“红玉988”', '江苏省淮北地区夏播', '特征特性：中熟紧凑型普通玉米。幼苗叶鞘紫色，子叶椭圆形，叶色深绿，叶缘绿色，生长势强。株型紧凑，茎秆粗壮。成株叶色深绿，颖片淡紫色，花药黄色，花丝浅紫色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：株高263厘米，成株叶片19片，穗位高101厘米；穗长17.6厘米，穗粗5.1厘米，秃尖长0.5厘米，每穗14.7行，每行31.9粒。千粒重352克，出籽率83.8%。全生育期105天。倒伏倒折率1.2%。中国农业科学院作物研究所及江苏省农科院植保所接种鉴定：抗大斑病、南方锈病，中抗茎腐病，感小斑病，高感纹枯病、瘤黑粉病、粗缩病。农业部谷物品质监督检验测试中心检测：容重780克/升，粗蛋白10.65%，粗脂肪4.50%，粗淀粉73.04%，赖氨酸0.29%。产量和抗性表现：2016~2017年参加江苏淮北普通玉米区域试验：两年区试平均亩产627.3公斤，比对照郑单958增产3.1%。2018年参加江苏省淮北普通玉米生产试验：平均亩产554.9公斤，比对照郑单958增产2.6%。', '1、适期播种。一般夏播6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕、做好壅土培根以防倒伏。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好玉米螟、粗缩病、纹枯病等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (393, 2, '红旗968', '苏审玉20210010', '2021.03', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院', 'L055×L422，参试名称“连试14948”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色。株型紧凑，总叶片数18片左右；花药黄色，花丝红色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期105.5天，比对照郑单958长1.4天。株高266厘米，穗位高105厘米；穗长17.3厘米，穗粗4.9厘米，秃尖长0.8厘米，每穗16.7行，每行32.5粒；千粒重326克，出籽率84.1%；空秆率0.7%，倒伏倒折率3.6%。经中国农业科学院作物科学研究所、江苏省农业科学院植保所接种鉴定：抗大斑病、小斑病；感腐霉茎腐病、纹枯病、瘤黑粉病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2019年检测：容重789克/升，粗蛋白10.49%，粗脂肪3.89%，粗淀粉73.25%，赖氨酸0.28%。产量和抗性表现：2017~2018年参加江苏省普通玉米淮北夏播区试，两年平均亩产616.4公斤，比对照郑单958增产8.9%。2019年参加生产试验，平均亩产639.0公斤，比对照郑单958增产8.5%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (394, 2, '红花玉景', '苏审玉20210030', '2021.03', 0, '江苏省农作物品种审定委员会', '南京理想农业科技有限公司', 'LKN-053×LKTN-027', '江苏省各地', '特征特性：鲜食甜糯玉米。幼苗叶鞘紫色，叶片深绿色。株型半紧凑，总叶片数18~19片；花药绿色，颖壳淡绿色，花丝绿色；果穗锥形，穗轴白色；籽粒红白相间。联合体区试平均结果：出苗至采收鲜穗83.5天，比对照苏玉糯5号长2.7天。株高238厘米，穗位高123厘米；穗长18.2厘米，穗粗4.5厘米，秃尖长1.0厘米，每穗14.5行，每行34.8粒；千粒鲜重300克，鲜穗出籽率67.3%；空秆率0.9%，倒伏倒折率0.9%。经江苏省农业科学院植保所接种鉴定：抗小斑病；中抗大斑病、纹枯病；感瘤黑粉病；高感腐霉茎腐病、南方锈病。江苏省糯玉米联合体品种区域试验品尝鉴定：外观品质和蒸煮品质85.6分。扬州大学农学院检测：支链淀粉占总淀粉的98.0%。产量和抗性表现：2018~2019年参加江苏省糯玉米省农科院联合体区试，两年平均亩产鲜穗798.0公斤，比对照苏玉糯5号增产1.4%。2020年参加生产试验，平均亩产鲜穗719.2公斤，比对照苏玉糯5号增产6.0%。', '1、适时播种。春播3月10日至4月10日，秋播7月15日至8月10日播种。2、合理密植。亩播种量1.5~2.0公斤，种植密度每亩3000~3500株左右。3、加强管理。及时间苗，2~3片真叶时进行间苗，4~5叶时定苗，8~10叶时中耕培土。4、施足基肥。以有机肥为主，配合氮磷钾复合肥和部分氮肥，亩施尿素15~20公斤和氮磷钾复合肥20~30公斤，40%左右作底肥撒施，其余撒施于播种沟内作追肥使用。5、综合防治病虫害。适时采收，一般在授粉后22~25天即可采收。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (395, 2, '绿领甜1号', '苏审玉200705', '2007.1', 0, '江苏省农作物品种审定委员会', '江苏苏农种业科技有限公司', 'SK-01/SK-R02', '适合江苏各地种植', '退出批次：特征特性：出苗快而齐，苗势强，幼苗叶鞘绿色，叶片绿色，叶缘绿色株型半紧凑，株高206厘米左右，穗位74厘米左右成株叶片数18-19片花药黄绿色，颖壳黄绿色，花丝黄绿色，果穗长锥形，穗长19.5厘米，穗粗4.0厘米，每穗12-14行，每行35粒左右，千粒重288.0克左右，鲜粒淡黄间白色，马齿型，甜度高，口味佳春播出苗到采收鲜穗88天左右田间观察，抗病抗倒性较强中国农业科学院作物研究所接种鉴定，中抗大斑病、中抗小斑病、感矮花叶病、高感纹枯病江苏省鲜食玉米品种区域试验组织的专家品尝鉴定，外观品质和蒸煮品质达到部颁鲜食甜玉米二级标准扬州大学农学院检测，水溶性糖含量19.7%，还原糖含量6.2%，达到甜玉米标准（NY/T523-2002）产量和抗性表现：2004-2005年参加江苏省区试，两年鲜果穗平均亩产749.6公斤，较对照蜜玉8号增产12.0%，两年增产均达极显著水平；2006年生产试验鲜果穗平均亩产917.9公斤，较对照晶甜3号增产2.8%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (396, 2, '美玉3号', '苏审玉200605', '2006.1', 0, '江苏省农作物品种审定委员会', '海南绿川种苗有限公司', 'Mnt譌nct', '适宜江苏各地种植', '退出批次：特征特性：春播播种至采收95天左右。出苗整齐，苗势强，幼苗叶鞘紫色，叶片绿色，叶缘绿色。株型半紧凑，整齐度较好，株高194.2厘米左右，穗位90.5厘米左右，双穗率18.6%左右，空杆率3.7%左右，成株叶片数19片左右。花药黄色，颖壳绿色，花丝红色，穗轴白色，穗长16.8厘米左右，穗粗4.3厘米左右，秃顶0.8厘米左右，每穗14行左右，每行34粒左右，籽粒白色，千粒鲜重140.4克左右，鲜出籽率63.9%左右。田间观察病害发生较经，抗倒性较强。中国农业科学院作物科学研究所接种鉴定，感小斑病、矮花叶病、纹枯病。省鲜食糯玉米品种区域试验组织的专家品尝鉴定，外观品质和食味蒸煮品质达到部颁鲜食糯玉米二级标准。扬州大学农学院检测，支链淀粉占淀粉总量的98.68%，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2003-2004年参加江苏省区试，两年区试平均亩产鲜果穗746.4公斤，较对照苏玉糯1号减产5.7%，两年减产均极显著；2005年生产试验亩产692.3公斤，较对照苏玉糯1号减产4.6%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (397, 2, '苏彩甜糯908', '苏审玉20230008', '2023.06', 0, '江苏省农作物品种审定委员会', '江苏越千凡农业科技发展有限公司、江苏沿江地区农业科学研究所', 'T1032×SWJ，参试名称“苏玉糯908 ”', '江苏省各地', '特征特性：鲜食甜糯玉米品种。幼苗叶鞘紫色，叶片绿色，生长势强。株型半紧凑；果穗长锥形，籽粒紫白色；穗轴白色。省区试平均结果：出苗至采收鲜穗81.0天，与对照苏玉糯5号相当。株高242厘米，穗位高108厘米；穗长17.3厘米，穗粗4.7厘米，秃尖长7.6厘米，每穗15.0行，每行37.7粒。千粒鲜重278.5克，鲜穗出籽率66.2%。空秆率0.2%，倒伏倒折率0.7%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病，中抗纹枯病、腐霉茎腐病、南方锈病、弯孢菌叶斑病，感瘤黑粉病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质86.8分。扬州大学农学院检测：支链淀粉占总淀粉的98.5%。产量和抗性表现：2020~2021年参加江苏省糯玉米区试，两年平均亩产鲜穗815.3公斤，比对照苏玉糯5号增产5.5%。2022年参加生产试验，平均亩产鲜穗849.1公斤，比对照苏玉糯5号增产9.3%。', '1、适期播种。分期播种，均衡上市。播种期春玉米以3月初至4月底播种为宜，早春宜用地膜覆盖；秋玉米于7月10日至8月初播种为好。2、合理密植。一般纯作每亩保苗数4000株。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，亩施纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，注意防涝防旱。4、注意病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、瘤黑粉病等。5、适时采收。春播一般授粉后22~25天采收青果穗；秋播一般授粉后30~35天采收青果穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (398, 2, '苏玉(糯)5号', '苏审玉200405', '2004', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农科所', '通系5×通366', '适宜江苏各地种植', '退出批次：特征特性：株型较紧凑，株高219.0cm左右，穗位112.0cm左右，双穗率11.6%左右，空杆率0.2%左右，总叶片数19张左右，植株田间整齐度较好。穗长17.0cm左右，穗粗4.4cm左右，秃顶1.0cm左右，每穗14行左右，每行34粒左右，百粒鲜重29.1g左右，鲜出籽率76.9%左右，硬粒型糯玉米。鲜穗白色，籽粒排列整齐，花药淡黄色，颖壳青色，穗型为锥形，果穗适中，有少量秃顶，综合外观印象好，糯性好，甜度突出，籽粒不透明，口感好，色泽好，综合品质接近苏玉糯1号。春播鲜果穗成熟期108天左右，比对照苏玉糯1号迟1天。田间观察，抗病性强，抗倒性强。产量和抗性表现：该品种两年区试平均亩产鲜果穗845.1公斤，比对照苏玉糯1号增产10.1%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (399, 2, '苏玉10号', '苏种审字第303号', '1998', 0, '江苏省农作物品种审定委员会', '沿江地区农科所', '4A×75单交种', '江苏作春、夏玉米种植', '退出批次：特征特性：出苗快，苗势强，易获全苗、壮苗，株型紧凑，株高210—220厘米，穗位高80—85厘米，穗长17—18厘米，穗粗4.2厘米，穗轴白色；果穗呈园筒形。穗行14行左右，每行35—40粒，结实性好。粒型中间偏硬、黄色，胚乳角质成分我。千粒重280—300克，出籽率88%左右，据分析籽粒粗蛋白质含量、17种氨基酸含量均较高。生育期春播约115天，比掖单13早熟9—12天，夏播为94天，比掖单13早熟8—11天。抗倒、抗病性强，丰产性、稳产性均突出。产量和抗性表现：1995—1996年两年参加省玉米春、夏播组区域试验，春播组两年平均分别为489.4公斤和478.9公斤，比对照掖单13分别增产1.4%（未达到显著水平）和12.1%（达极显著水平），均居首位。夏播组两年平均亩产为495.5公斤和456.4公斤。比对照掖单13分别增产8.4%（未达显著水平）和22.7%（达极显著水平），均居首位。1997年，春夏播组生产试验平均亩产为564.2公斤和582.5公斤，双对照掖单13分别增产15.0%和10.3%（均达极显著水平），据1996至1997年参加全国玉米东南区区域试验，两年平均亩产436.5公斤，比对照掖单13增产13.3%，两年均居首位。20个点次试验汇总，其中12个点次试验亩产量居首位；5个点次居第二位。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (400, 2, '苏玉11号', '苏种审字第304号', '1998', 0, '江苏省农作物品种审定委员会', '淮阴地区农科所', '海91-16×89-11', '江苏作春、夏玉米种植', '退出批次：特征特性：出苗快，苗势强，易获全苗、壮苗，株型紧凑，株高210—220厘米，穗位高80—85厘米，穗长17—18厘米，穗粗4.2厘米，穗轴白色；果穗呈园筒形。穗行14行左右，每行35—40粒，结实性好。粒型中间偏硬、黄色，胚乳角质成分我。千粒重280—300克，出籽率88%左右，据分析籽粒粗蛋白质含量、17种氨基酸含量均较高。生育期春播约115天，比掖单13早熟9—12天，夏播为94天，比掖单13早熟8—11天。抗倒、抗病性强，丰产性、稳产性均突出。产量和抗性表现：1995—1996年两年参加省玉米春、夏播组区域试验，春播组两年平均分别为489.4公斤和478.9公斤，比对照掖单13分别增产1.4%（未达到显著水平）和12.1%（达极显著水平），均居首位。夏播组两年平均亩产为495.5公斤和456.4公斤。比对照掖单13分别增产8.4%（未达显著水平）和22.7%（达极显著水平），均居首位。1997年，春夏播组生产试验平均亩产为564.2公斤和582.5公斤，双对照掖单13分别增产15.0%和10.3%（均达极显著水平），据1996至1997年参加全国玉米东南区区域试验，两年平均亩产436.5公斤，比对照掖单13增产13.3%，两年均居首位。20个点次试验汇总，其中12个点次试验亩产量居首位；5个点次居第二位。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (401, 2, '苏玉12号', '苏种审字第305号', '1998', 0, '江苏省农作物品种审定委员会', '扬州大学农学院', 'J7-3�340', '江苏作夏玉米种植', '退出批次：特征特性：苗势强，易获全苗，株型号紧凑，株高201—215厘米，穗位高80—85厘米，穗长17—18厘米，穗粗4.5厘米，穗行14—16行，行粒数29—31粒，千粒重260—280克，出籽率83—85%。黄粒，马齿型。生育期春播120天。抗倒性较强，抗病性强，有一定的丰产潜力，母本为育系，免去人工去雄，不仅省工，保证杂交种的纯度，还可提高制种的产量。产量和抗性表现：1995—1996年两年参加江办省玉米省、夏播组区域试验，春播组两年平均亩产分别为470.2公斤和419.7公斤，比对照掖单13分别减产2.6%和1.8%（均未达显著）分别居第三位和第四位。夏播组两年平均亩产为480.7公斤和455.9公斤。比对照掖单13分别增5.2%（未达显著水平）和22.6%（达极显著水平）均居第二位。1997年生产试验，春夏播组生产试验平均亩产为460.7公斤和595.1公斤，比对照减产6%和增产13.2%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (402, 2, '苏玉13号', '苏种审字第376号', '2000', 0, '江苏省农作物品种审定委员会', '沿江地区农科所', '274×A6（414的姐妹系）', '江苏作春、夏玉米种植', '退出批次：特征特性：该品种苗势强，易获全苗。株型紧凑，株高210厘米，穗位高78 厘米，穗长15-18厘米，穗粗4.0-4.6厘米，每穗平均13行左右，行粒数35粒，千粒重250-270克，出籽率86%。籽粒黄色，偏硬粒型。生育期105-110天。抗倒性较强，抗大、小斑病，感纹枯病。品质分析结果：水分10.40%，粗蛋白8.74%，粗脂肪4.92%，粗淀粉73.00%，赖氨酸0.24% （农业部谷物品质监督检测中心，1999年12月）。产量和抗性表现：1997-1998年两年参加江苏省春、夏播组玉米新品种区域\n试验。春播组两年平均亩产分别为587.90公斤和593.30公斤，比对照苏玉9号增产4.10%（显著）和4.90%（极显著），均居第一位；夏播组两年平均亩分别为453.90公斤和451.90公斤，比对照苏玉9号增产1.90%（不显著）和减产3.30%（不显著），均居第四位。1999年省玉米春播组生产试验，平均亩产606.50  公斤，比对照苏玉9号增产7.60%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (403, 2, '苏玉14号', '苏种审字第377号', '2000', 0, '江苏省农作物品种审定委员会', '沿江地区农科所', '4A�249', '江苏作夏玉米种植', '退出批次：特征特性：该品种苗势较强。株型紧凑，株高240厘米，穗位高88-105厘米，穗长15厘米，穗粗4.6厘米，穗行14行，行粒数32粒，千粒重226克，出籽率84%。籽粒黄色，偏硬粒型。生育期95天。抗倒性较强，抗大、小斑病，感纹枯病。品质分析结果：水分10.00%，粗蛋白11.36%，粗脂肪4.71%，粗淀粉67.44%，赖氨酸0.28%（农业部谷物品质监督检测中心，1999年12月）。产量和抗性表现：1997-1998年两年参加江苏省春、夏播组玉米新品种区域试验，春播组两年平均亩产分别为561.90公斤和485.90公斤，比对照苏玉9号减产0.50%（不显著）和减产14.10%（极显著），分别居第五位和第十位；夏播组两年平均亩分别为475.30公斤和464.90公斤，比对照苏玉9号增产6.70%（极显著）和减产0.50%（不显著），分别居第一位和第三位。1999年省玉米夏播组生产试验，平均亩产506.70公斤，比对照苏玉9号增产6.00%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (404, 2, '苏玉15号', '苏审玉200101', '2001', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农科所', '568G�340', '江苏作春、夏玉米种植', '退出批次：特征特性：苏玉15号出苗快，苗势强。株型紧凑，茎秆粗壮，株高230厘米左右，穗位高90 厘米左右；果穗较大，长筒型，穗长17厘米，穗粗5厘米左右；每穗平均16行左右，行粒数32粒，千粒重280克左右，出籽率83%；籽粒黄色，半硬粒型；春播全生育期103天，夏播92天。该品种抗倒性较强，抗大、小斑病和青枯病。品质分析结果：粗蛋白8.62%，粗脂肪4.54%，粗淀粉72.36% （农业部谷物检测中心，2001年3月）。产量和抗性表现：苏玉15号1999-2000年参加江苏省春、夏播组玉米新品种区域试验。春播组两年平均亩产分别为603.30公斤和591.00公斤，比对照苏玉9号增产14.60%（极显著）和14.40%（极显著），均居第1位；夏播组两年平均亩分别为518.30公斤和510.60公斤，比对照苏玉9号增产5.10%（极显著）和9.50%（极显著），居第3位和第2位。2000年省玉米春、夏播组生产试验，平均亩产532.40公斤和400.30公斤，比对照苏玉9号增产19.90%和13.00%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (405, 2, '苏玉161', '苏审玉20200002', '2020.06', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所、江苏中禾种业有限公司', 'D44×D39，参试名称“DJ161”', '江苏省淮南地区春播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强。株型半紧凑，总叶片数19片，成株叶色深绿；花药紫色，颖壳紫色，花丝青色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：全生育期117天，比对照苏玉29短4天。株高242厘米，穗位高103厘米；穗长18.4厘米，穗粗4.6厘米，秃尖长1.4厘米，每穗14.4行，每行34.8粒，千粒重322克，出籽率85.0%；空秆率1.1%，倒伏倒折率12.2%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：抗大斑病、小斑病；中抗南方锈病；感腐霉茎腐病、纹枯病；高感瘤黑粉病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重758克/升，粗蛋白9.1%，粗脂肪3.8%，粗淀粉74.5%，赖氨酸0.27%。产量和抗性表现：2017~2018年参加江苏省普通玉米淮南春播区试，两年平均亩产567.9公斤，比对照苏玉29增产5.3%。2019年参加生产试验，平均亩产719.5公斤，比对照苏玉29增产8.5%。', '1、适期播种。一般4月初播种。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、腐霉茎腐病、瘤黑粉病、玉米螟等的防治工作，注意倒伏倒折风险防范。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (406, 2, '苏玉16号', '苏审玉200102', '2001', 0, '江苏省农作物品种审定委员会', '扬大农学院', 'J7-3B譟153', '江苏作春、夏玉米种植', '退出批次：特征特性：苏玉16号苗势较强，易获全苗。株型紧凑，茎秆粗壮，株高215厘米左右，穗位高90 厘米左右；果穗较大，长筒型，穗长16厘米，穗粗5厘米；每穗平均16行左右，行粒数32粒，千粒重280克左右，出籽率86%；籽粒黄色，半硬粒型；春播全生育期115天，夏播95天。该品种抗倒性较强，高抗茎腐病，抗大、小斑病和灰斑病。品质分析结果：粗蛋白9.72%，粗脂肪4.68%，粗淀粉70.30% （扬州大学，2000年12月）。产量和抗性表现：苏玉16号1999-2000年参加江苏省春、夏播组玉米新品种区域试验。春播组两年平均亩产分别为551.60公斤和567.30公斤，比对照苏玉9号增产4.90%（极显著）和9.80%（极显著），居第3位和第2位；夏播组两年平均亩分别为530.90公斤和514.90公斤，比对照苏玉9号增产7.70%（极显著）和10.40%（极显著），居第2位和第1位。2000年省玉米春、夏播组生产试验，平均亩产510.40公斤和401.30公斤，比对照苏玉9号增产14.90%和13.30%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (407, 2, '苏玉172', '苏审玉20210003', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所', 'T989×T415，参试名称“通玉1702”', '江苏省淮南地区春播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强。株型半紧凑，成株叶色深绿；花药紫色，颖壳紫色，花丝红色；果穗筒形，穗轴红色；籽粒黄色，硬粒型。省区试平均结果：全生育期119.6天，比对照苏玉29短2.8天。株高270厘米，穗位高111厘米；穗长17.6厘米，穗粗5.0厘米，秃尖长0.9厘米，每穗15.7行，每行34.0粒；千粒重339克，出籽率83.0%；空秆率1.5%，倒伏倒折率11.0%。经江苏省农业科学院植保所接种鉴定：高抗大斑病；抗小斑病；中抗腐霉茎腐病、纹枯病、瘤黑粉病；感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重790克/升，粗蛋白9.77%，粗脂肪3.69%，粗淀粉73.84%，赖氨酸0.29%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮南春播区试，两年平均亩产616.7公斤，比对照苏玉29增产6.0%。2020年参加生产试验，平均亩产576.6公斤，比对照苏玉29增产9.4%。', '1、适期播种。一般4月初播种。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好玉米螟的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (408, 2, '苏玉17号', '苏审玉200104', '2001', 0, '江苏省农作物品种审定委员会', '如皋市种子公司', '8112A�414', '江苏作春、夏玉米种植', '退出批次：特征特性：1999-2000年参加江苏省春、夏播组玉米新品种区域试验。1999年春播组两年平均亩产分别为551.90公斤和550.30公斤，比对照苏玉9号增产4.90%（极显著）和6.50%（极显著），居第2位和第5位；夏播组两年平均亩分别为536.90公斤和472.90公斤，比对照苏玉9号增产8.90%（极显著）和1.50%（不显著），居第1位和第6位。2000年省玉米春、夏播组生产试验，平均亩产490.40公斤和364.50公斤，比对照苏玉9号增产10.40%和2.90%。该品种适宜我省春夏播玉米区种植。产量和抗性表现：1999-2000年参加江苏省春、夏播组玉米新品种区域试验。1999年春播组两年平均亩产分别为551.90公斤和550.30公斤，比对照苏玉9号增产4.90%（极显著）和6.50%（极显著），居第2位和第5位；夏播组两年平均亩分别为536.90公斤和472.90公斤，比对照苏玉9号增产8.90%（极显著）和1.50%（不显著），居第1位和第6位。2000年省玉米春、夏播组生产试验，平均亩产490.40公斤和364.50公斤，比对照苏玉9号增产10.40%和2.90%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (409, 2, '苏玉18', '苏审玉200302', '2003', 0, '江苏省农作物品种审定委员会', '省农科院粮作所', '95-1×苏195', '江苏作春、夏玉米种植', '退出批次：特征特性：出苗快而齐，苗势强，幼苗叶色较深，生长势较强，株型半紧凑，株高220cm左右，穗位90cm左右，花丝淡绿色，黄色花药，总叶片数19-20张，叶色较深，后期熟相好，果穗较长，穗长20cm左右，穗粗4.5cm左右，每穗12-14行，每行38粒左右。籽粒黄色，中间粒型，千粒重300克左右。全生育期春播约116天，夏播约101天。田间观察，中抗玉米大、小斑病，抗倒性较强。产量和抗性表现：2001-2002年参加江苏省玉米中间试验。2001年春播平均亩产557.5公斤，比对照苏玉9号增产13.9%，极显著；夏播平均亩产553.7公斤，比对照增产4.5%，显著。2002年春播平均亩产600.0公斤，比对照增产9.2%，极显著；夏播平均亩产533.0公斤，比对照增产8.0%，极显著。2002年生产试验（春播）平均亩产592.0公斤，比对照增产7.0%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (410, 2, '苏玉19', '苏审玉200303', '2003', 0, '江苏省农作物品种审定委员会', '沿江地区农科所', '458�877', '江苏作春、夏玉米种植', '退出批次：特征特性：出苗整齐，苗势强。幼苗叶鞘紫色，叶绿色，叶缘紫色，植株整齐度好，生长势强，株型紧凑，株高240cm左右，穗位95cm左右，主茎叶片数19张左右，株型紧凑，后期熟相好。果穗圆筒型，穗长20cm左右，穗粗5cm左右，每穗14-16行左右，每行43粒左右。籽粒黄色，中间偏硬粒型，千粒重320g左右。全生育期春播约113天，夏播约94天。田间观察，抗玉米大、小斑病，轻感文枯病，抗倒性较强。产量和抗性表现：2001-2002年参加江苏省玉米中间试验。2001年春播平均亩产556.0公斤，比对照苏玉9号增产13.0%，极显著；夏播平均亩产558.7公斤，比对照增产5.3%，极显著。2002年春播平均亩产644.0公斤，比对照增产18.5%，极显著；夏播平均亩产530.0公斤，比对照增产7.6%，极显著。2002年生产试验春播平均亩产639.0公斤，比对照增产15.4%，夏播平均亩产559.0公斤，比对照增产22.2%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (411, 2, '苏玉1号', '苏种审字第26号', '1983', 0, '江苏省农作物品种审定委员会', '省农科院', '苏80-1×黄早4', '江苏作春、夏玉米种植', '退出批次：特征特性：株高200—220厘米，株型紧凑，单株叶片数20—21张，叶片稍宽。幼苗第一叶椭园形，叶鞘紫色，拔节前叶片绿色发亮，雄穗抽出后，果穗下部叶片平展，果穗上部叶片上冲。处理穗位82厘米左右，抽雄、吐丝快而整齐，灌浆速度快，熟相好。果穗长约16—18厘米，穗粗4.8厘米，每穗籽粒行数13—14行，每行26粒左右千粒重300克左右，果穗出籽率82.4%，穗轴白色。籽粒淡黄色，含17种氨基酸（9.76克/100克样品）。属中间偏硬粒型，品质较好。耐涝性较好，抗大、小斑病。全生育期春播105—115天，夏播85—90天（比鲁原单4号长3—5天）。产量和抗性表现：1981年至82连续两年参加省玉米品种区域试验，平均亩产分别为828.8斤和909.6斤，比对照鲁原单四号增产25.45%、20.78%，均表现极显著。1982年六个点的省生产试验，平均亩产808.2斤，比对照鲁单四号增产20.95%，增产幅度为14.67—36.67%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (412, 2, '苏玉20', '苏审玉200401', '2004', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', '苏951-2×651', '江苏春夏播地区', '退出批次：特征特性：出苗较齐，苗势较强，幼苗叶色较深，植株整齐，生长势较强，株型半紧凑，株高226cm左右，穗位101cm左右，总叶片数20张左右，叶色较深，后期熟相好，果穗中等，穗长18cm左右，穗粗5cm左右，秃顶1.2cm左右，每穗14-15行，每行33粒左右，籽粒黄色偏硬，中间粒型，千粒重308g左右，全生育期春播120天左右，夏播102天左右。田间观察，抗玉米大、小斑病，抗倒性较强。产量和抗性表现：该品种两年区试春播平均亩产510.5公斤，比对照苏玉9号增产7.4%，夏播平均亩产472公斤。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (413, 2, '苏玉22号', '苏审玉200502', '2005.2', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所', 'F2譌24', '适宜江苏省春夏播地区种植', '退出批次：特征特性：全生育期春播119天左右，夏播102天左右。出苗较齐，苗势较强，幼苗叶鞘紫色，叶片浅绿色，叶缘紫色。株型紧凑，整齐度较好，株高235cm左右，穗位101cm左右，成株叶片数19片左右。花药黄色，颖壳绿色，花丝青到粉红色，果穗圆柱形，穗长18.2cm左右，穗粗4.7cm左右，秃顶1.4cm左右，每穗13-15行，每行32粒左右，籽粒黄色，粒型半马齿型，千粒重298.3g左右，出籽率83.2%左右。田间表现，春播轻感玉米大、小斑病、病毒病、纹枯病，抗倒性较强；夏播轻感玉米大、小斑病、病毒病，中感纹枯病，抗倒性较强。经农业部谷物品质监督检验测试中心（北京）检测，容重730g/L，粗蛋白9.72%，粗脂肪4.02%，粗淀粉70.72%，赖氨酸0.32%。产量和抗性表现：2002-2003年参加江苏省区试，两年区试春播平均亩产542kg，比对照苏玉9号增产极显著，夏播平均亩产465kg，比对照苏玉9号增产极显著；2004年生产试验春播亩产570kg，夏播亩产533kg。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (414, 2, '苏玉23号', '苏审玉200702', '2007.1', 0, '江苏省农作物品种审定委员会', '黄炳生', 'H20/N38', '适合江苏省夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，生长势较强，幼苗叶鞘紫红色，叶片绿色，叶缘紫色株型半紧凑，株高220厘米左右，成株叶片19片左右花药紫色，颖片紫色，花丝红色穗位91厘米左右，穗长19.5厘米左右，穗粗4.7厘米左右，每穗12-14行，每行32粒左右籽粒黄色，中间偏硬粒型，千粒重307.0克左右全生育期98天左右田间调查，抗病抗倒性较强中国农业科学院作物研究所接种鉴定，中抗大斑病、抗小斑病、感矮花叶病、高感纹枯病农业部谷物品质监督检验测试中心（哈尔滨）检测，容重722g/L，粗蛋白9.67%，粗脂肪4.10%，粗淀粉74.83%，赖氨酸0.30%产量和抗性表现：2005-2006年参加江苏省区试，两年平均亩产401.6公斤，较对照郑单958增产11.2%，两年增产均达极显著水平；2006年生产试验平均亩产435.6公斤，较对照增产7.7%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (415, 2, '苏玉24', '苏审玉200802', '2008.1', 0, '江苏省农作物品种审定委员会', '南京神州种业有限公司', 'T4789譚999', '适宜江苏省作夏玉米种植', '退出批次：特征特性：出苗快而齐，苗势强，生长势强，幼苗叶鞘紫色，叶片绿色，叶缘紫色，株型半紧凑，花药紫色，颖片浅紫色，花丝黄绿色，果穗圆柱形，籽粒黄色，半硬粒型穗轴白色省区试平均结果：株高215厘米，成株叶片19片，穗位86厘米，穗长19.9厘米，穗粗4.7厘米，每穗12-14行，每行34粒，千粒重317.0克，全生育期97天抗倒性较强中国农业科学院作物研究所接种鉴定，抗大斑病、小斑病、感纹枯病，江苏省农科院植保所接种鉴定感粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测，容重727g/L，粗蛋白8.43%，粗脂肪4.29%，粗淀粉74.31%，赖氨酸0.27%产量和抗性表现：2005-2006年参加江苏省夏播玉米区试，两年平均亩产379.1公斤，比对照郑单958增产5.1%，2005年增产极显著，2006年增产不显著2007年生产试验平均亩产503.6公斤，比对照增产6.2%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (416, 2, '苏玉26', '苏审玉201001', '2010.2', 0, '江苏省农作物品种审定委员会', '山西强盛种业有限公司', 'ZH38譎36', '适宜在江苏春播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，苗期叶鞘浅紫色，叶色绿，叶缘绿色，生长势较强株型半紧凑花药黄色，颖片浅紫色，花丝淡黄色果穗圆锥形，籽粒黄色，半马齿型，穗轴红色省区试平均结果：株高218厘米，成株叶片21 片，穗位99厘米穗长14.8厘米，穗粗4.8厘米，每穗14-16行，每行29粒，千粒重304.0克，出籽率83.7%，全生育期约121天，倒伏率5.2%中国农业科学院作物研究所2009年接种鉴定：抗大、小斑病及纹枯病，高感茎腐病及粗缩病农业部谷物品质监督检验测试中心（哈尔滨）2009年检测：容重740克/升，粗蛋白10.35%，粗脂肪4.76%，粗淀粉70.07%，赖氨酸0.27%产量和抗性表现：2007-2008年参加江苏省春播玉米区域试验，两年区试平均亩产466.3公斤，比对照苏玉19增产8.1%；2007年增产极显著，2008年增产不显著2009年生产试验平均亩产439.4公斤，比对照苏玉19增产5.7%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (417, 2, '苏玉27', '苏审玉201002', '2010.2', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D108譊3139', '适宜在江苏春播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，生长势强，幼苗叶鞘紫色，叶片深绿，叶缘紫色株型半紧凑花药浅紫色，颖片浅紫色，花丝浅红色果穗圆筒形，籽粒黄色，半马齿型，穗轴白色省区试平均结果：株高208厘米，成株叶片20片，穗位96厘米，穗长15.6厘米，穗粗4.9厘米，每穗16行，每行30粒，千粒重271.0克，全生育期约119天，倒伏率12.2%中国农业科学院作物研究所2009年接种鉴定：抗大、小斑病，中抗纹枯病，高感茎腐病及粗缩病农业部谷物品质监督检验测试中心（哈尔滨）2009年检测：容重754克/升，粗蛋白9.11%，粗脂肪4.43%，粗淀粉70.67%，赖氨酸0.27%产量和抗性表现：2007-2008年参加江苏省春播玉米区域试验，两年区试平均亩产466.7公斤，比对照苏玉19增产8.0%，两年增产均达极显著2009年生产试验平均亩产429.9公斤，比对照苏玉19增产3.4%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (418, 2, '苏玉29', '苏审玉201304', '2013', 0, '江苏省农作物品种审定委员会', '江苏省农科院粮食作物研究所', '苏95-1×JS0451', '适宜江苏省淮北夏播地区种植', '退出批次：特征特性：出苗快，苗势强，生长势强，株型紧凑，叶色绿，幼苗叶鞘紫色，花药红色，花丝青到淡红色，叶缘红色，颖片红色，果穗筒形，籽粒黄色，半马齿型，穗轴白色省区试平均结果：全生育期约105天，株高238厘米，成株叶片19片，穗位97厘米，穗长19.0厘米，穗粗4.9厘米，平均每穗14-16行，每行35粒，千粒重316克，出籽率84.7%茎杆健壮，根系发达，田间倒伏率0中国农业科学院作物研究所2012年接种鉴定：高抗大斑病、茎腐病，抗小斑病，感纹枯病，高感粗缩病农业部谷物品质监督检验测试中心（北京）检测：容重724g/L、粗蛋白9.58%、粗脂肪3.17%、粗淀粉69.62%、赖氨酸0.31%产量和抗性表现：2012年参加江苏省普通玉米夏播区域试验，平均亩产598.0公斤，比对照郑单958增产8.7%，达极显著水平', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (419, 2, '苏玉2号', '苏种审字第34号', '1984', 0, '江苏省农作物品种审定委员会', '淮阴地区农科所', '获白×旅9宽', '江苏作春、夏玉米种植', '退出批次：特征特性：株高220—240厘米，株型较好，单侏叶片数20—21片，中部叶片宽大与茎杆成45度角向上斜生，上部叶片较小、上冲，叶色浓绿。大穗系数0.44—0.45，比较适中，呆穗长16—17厘米，穗粗4.84—4.95厘米，每穗籽粒行数16行，每行粒数30—35粒，千粒重262—287克，黄白粒，马齿型，食味较好，含17种氨基酸，品质较好。抗倒性好，搞旱耐涝抗大、小斑病，适应性广，制种方便。全生育期出苗到成熟105—115天，夏播8590天。产量和抗性表现：1981—83年连续三年参加省玉米品种区域和生产试验。1981年区试平均亩产874.3斤，较“丹玉6号”增产7.2%，1982年平均单产877.33斤，比“丹玉6号”增产18.44%，两年平均单产976斤，较“丹玉6号”增产13%。1983年生产试验，平均单产821.6斤（幅度689—1103.4斤）。较“丹玉6号”平均增产21.2%（幅度13—35%），生产潜力较大。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (420, 2, '苏玉30', '苏审玉 201406', '2014', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所', '自选系HL40×YJ7', '适宜江苏淮北夏播地区种植', '退出批次：特征特性：出苗快而齐，苗期叶鞘紫色，叶色绿，叶缘紫色，生长势强株型半紧凑花药黄色，颖壳紫色，花丝青色果穗筒形，籽粒黄色，半硬粒型，穗轴红色省区试平均结果：株高235厘米，穗位高103厘米，穗长18.4厘米，穗粗5.0厘米，每穗16行，每行31粒，千粒重334.0克，出籽率84.3%，全生育期约98天倒伏率0.2%中国农业科学院作物研究所接种鉴定：中抗大、小斑病，抗纹枯病，高抗茎腐病农业部谷物品质监督检验测试中心（北京）检测：容重728克/升，粗蛋白11.96%，粗脂肪3.69%，粗淀粉66.91%，赖氨酸0.38%产量和抗性表现：2013年参加江苏省普通玉米夏播区域试验，平均亩产580.6公斤，所有试点全部增产，比对照郑单958平均增产3.6%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (421, 2, '苏玉31', '苏审玉201105', '2011.3', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D4990譊3139', '适宜在江苏省夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，幼苗叶鞘紫色，生长势强，叶片绿色株型半紧凑颖片浅紫色，花药浅紫色，花丝浅红色果穗筒形，籽粒黄色，半马齿型，穗轴粉红色省区试平均结果：株高241厘米，成株叶片19片，穗位101厘米，穗长19.2厘米左右，穗粗4.7厘米，每穗14-16行，每行37粒，千粒重325.0克，出籽率85.3%，全生育期约98天，倒伏率0.1%中国农业科学院作物研究所接种鉴定：中抗小斑病，感纹枯病，高感茎腐病及粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重782克/升，粗蛋白9.38%，粗脂肪4.12%，粗淀粉72.54%，赖氨酸0.30%产量和抗性表现：2008-2009年参加江苏省夏播玉米区域试验，两年区试平均亩产565.2公斤，比对照郑单958增产6.5%，两年增产均达极显著2010年生产试验平均亩产480.0公斤，比对照郑单958增产6.0%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (422, 2, '苏玉33', '苏审玉201202', '2012.3', 0, '江苏省农作物品种审定委员会', '宿迁市种子管理站', 'ND81-2×本M', '适宜江苏夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，生长势强，株型紧凑，叶片上冲，叶尖下披，叶色深绿，花药紫色，花丝红色，果穗筒形，籽粒黄色，半马齿型，穗轴白色省区试平均结果：全生育期约96天，株高247厘米，成株叶片20片，穗位102厘米，穗长19.9厘米，穗粗4.6厘米，平均每穗12-14行，每行38粒，千粒重324克茎杆健壮，根系发达，田间倒伏率2.5%中国农业科学院作物研究所接种鉴定：抗大斑病、小斑病，中抗茎腐病，感纹枯病，高感粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重766克/升，粗蛋白8.71%，粗脂肪5.09%，粗淀粉73.47%，赖氨酸0.29%产量和抗性表现：2009年-2010年参加江苏省普通玉米夏播区域试验，两年区试平均亩产524.7公斤，比对照郑单958增产6.7%，两年增产均极显著2011年生产试验平均亩产496.4公斤，比对照郑单958增产6.6%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (423, 2, '苏玉34', '苏审玉201203', '2012.3', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D5835譊124', '适宜江苏夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，幼苗叶鞘紫色，叶片绿色，株型紧凑，颖片绿色，花药黄色，花丝绿色，果穗筒形，籽粒黄色、半马齿型，穗轴粉红色省区试平均结果：全生育期约96天，株高236厘米，成株叶片19片，穗位90厘米，穗长18.6厘米，穗粗5.0厘米，每穗14-16行，每行35粒，千粒重335.0克，出籽率85.8%，田间倒伏率3.6%中国农业科学院作物研究所接种鉴定：抗大斑病，中抗小斑病，中抗茎腐病，感纹枯病，高感粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重750克/升，粗蛋白8.67%，粗脂肪3.92%，粗淀粉74.30%，赖氨酸0.26%产量和抗性表现：2009-2010年参加江苏省普通玉米夏播区域试验，两年区试平均亩产527.6公斤，比对照郑单958增产7.0%，两年增产均达极显著2011年生产试验平均亩产494.7公斤，比对照郑单958增产6.3%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (424, 2, '苏玉35', '苏审玉201204', '2012.3', 0, '江苏省农作物品种审定委员会', '莱州市东星良种研究所', 'T24-1×昌7-2', '适宜江苏夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，叶鞘紫色，生长势强，叶片深绿，株型紧凑，花药紫色，颖壳紫色，花丝红色，果柄较短，果穗筒形，籽粒黄色，半马齿型，穗轴白色省区试平均结果：全生育期约96天，株高262厘米，成株叶片19片，穗位108厘米，穗长18.5厘米，穗粗5.1厘米，每穗16行，每行36粒，千粒重319.0克，出籽率86.7%，田间倒伏率4.8%中国农业科学院作物研究所接种鉴定：中抗大斑病，抗小斑病，高感茎腐病、纹枯病、粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重744克/升，粗蛋白8.32%，粗脂肪4.55%，粗淀粉75.08%，赖氨酸0.26%产量和抗性表现：2009-2010年参加江苏省普通玉米夏播区域试验，两年区试平均亩产548.1公斤，比对照郑单958增产11.2%，两年增产均达极显著2011年生产试验平均亩产503.6公斤，比对照郑单958增产8.2%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (425, 2, '苏玉37', '苏审玉201302', '2013', 0, '江苏省农作物品种审定委员会', '江苏省农科院粮食作物研究所', '苏95-1×JS0351', '适宜江苏省淮北夏播地区种植', '退出批次：特征特性：出苗快，苗势强，幼苗叶鞘淡紫色，叶片绿色，叶缘绿色，株型半紧凑，颖片绿带紫纹，花药绿到浅红色，花丝绿到浅红色，果穗筒形，籽粒黄色、半马齿型，穗轴浅红色省区试平均结果：全生育期约99天，株高242厘米，成株叶片19片，穗位102厘米，穗长19.0厘米，穗粗5.0厘米，每穗14-16行，每行35粒，千粒重323克，出籽率86.0%，田间倒伏率3.0%中国农业科学院作物研究所接种鉴定：抗大斑病，中抗小斑病，高感茎腐病，高感纹枯病，高感粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重728克/升，粗蛋白9.2%，粗脂肪4.0%，粗淀粉75.0%，赖氨酸0.3%产量和抗性表现：2009-2011年参加江苏省普通玉米夏播区域试验，三年区试平均亩产524.8公斤，比对照郑单958增产7.4%，三年增产均达极显著2012年生产试验平均亩产581.5公斤，比对照郑单958增产6.6%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (426, 2, '苏玉38', '苏审玉201303', '2013', 0, '江苏省农作物品种审定委员会', '南京东宁作物研究所', 'D83-2×昌7-2', '适宜江苏省淮北夏播地区种植', '退出批次：特征特性：出苗快，生长势强，株型紧凑，叶色深绿，花药紫色，颖片紫色，花丝红色，果穗筒形，籽粒黄色，半马齿型，穗轴白色省区试平均结果：全生育期约95天，株高252厘米，成株叶片19片，穗位101厘米，穗长17.3厘米，穗粗4.9厘米，平均每穗14-16行，每行34粒，千粒重286克，出籽率86.3%茎杆健壮，根系发达，田间倒伏率9.3%中国农业科学院作物研究所接种鉴定：高抗大斑病，抗小斑病，高感茎腐病、纹枯病、粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重739.0克/升，粗蛋白9.8%，粗脂肪4.2%，粗淀粉73.2%，赖氨酸0.3%产量和抗性表现：2010-2011年参加江苏省普通玉米夏播区域试验，两年区试平均亩产506.2公斤，比对照郑单958增产8.8%，两年增产均极显著2012年生产试验平均亩产562.4公斤，比对照郑单958增产3.1%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (427, 2, '苏玉39', '苏审玉20230015', '2023.06', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JS081194譐S06730', '江苏省淮北地区夏播', '特征特性：普通玉米品种。幼苗叶鞘紫色，叶片浓绿，叶缘紫色，生长势较强。株型紧凑，茎秆粗壮，总叶片数20~21片，成株叶色绿色；花药紫色，颖壳紫色，花丝紫色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期104.4天，比对照郑单958长1.5天。株高247.4厘米，穗位高105.2厘米；穗长18.0厘米，穗粗4.7厘米，秃尖长0.4厘米；每穗15.8行，每行34.1粒；千粒重302.5克，出籽率84.8%；空秆率0.6%，倒伏倒折率0.2%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病、纹枯病、弯孢菌叶斑病、穗腐病，中抗腐霉茎腐病、南方锈病，感瘤黑粉病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重769克/升，粗蛋白11.02%，粗脂肪3.57%，粗淀粉71.99%，赖氨酸0.30%。产量和抗性表现：：2020~2021年参加江苏省淮北普通玉米科企联合体区试，两年平均亩产549.6公斤，比对照郑单958增产10.3%。2022年参加生产试验，平均亩产535.7公斤，比对照郑单958增产7.2%。', '1、适期播种。一般6月中旬前后播种。2、合理密植。适宜密度每亩4500~5000株左右。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好瘤黑粉病、玉米螟等的防治工作 。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (428, 2, '苏玉3号', '苏种审字第91号', '1987', 0, '江苏省农作物品种审定委员会', '省农科院粮作所', '21087×旅华112', '江苏沿海、沿江地区作春玉米种植', '退出批次：特征特性：种子顶土力强，出苗快而整齐，苗期长势强，拔节前出生叶片平强，拔节后出生叶片与茎杆夹角逐变小，显得上冲。株高240厘米左右，总叶片数20叶，叶片较宽大，叶色较浅中等，穗位高100厘米左右，穗长17厘米，穗粗4.4厘米，每穗籽粒行数14，每行粒数32粒，籽粒中等大小，细长，千粒重260克左右，出籽粒高。产量和抗性表现：1985—86年参加省玉米品种区域试验，1985年十个试点平均亩产847.8斤，名列第一，经苏玉1号、苏玉2号分别增产0.13 %和25.9%。5个春播式点平均亩产892.4斤，名列第一，比苏玉1号、苏玉2号分别增产11.9%和34.8%，达极显著。1986年十个试点平均亩产943.8斤，名列第一；比苏玉1号、苏玉2号分别增产3.9%和11.2%。5个春播试点平均亩产928.6斤，名列第一，比苏玉1号、苏玉2号分别增12.3%和16.5%，达极显著。1986年省玉米生产试验，4个试点平均亩产814.4斤，均居第一，比对照品种苏玉2号增产16.6%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (429, 2, '苏玉40', '苏审玉 201405', '2014', 0, '江苏省农作物品种审定委员会', '江苏省大华种业集团有限公司', 'D606譊204', '适宜江苏夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，幼苗叶鞘紫色，叶片绿色株型紧凑颖片浅紫色，花药黄到紫色，花丝绿到浅红色果穗筒形，籽粒黄色、半马齿型省区试平均结果：株高263厘米，成株叶片20~21片，穗位105厘米，穗长18.5厘米左右，穗粗4.9厘米，每穗16行，每行34粒，千粒重320.0克，出籽率85.5%全生育期约101天倒伏率1.1%中国农业科学院作物研究所接种鉴定：中抗大斑病、小斑病，高抗茎腐病，感纹枯病，高感粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重735克/升，粗蛋白9.15%，粗脂肪4.13%，粗淀粉70.04%，赖氨酸0.30%产量和抗性表现：2011~2012年参加江苏省夏播玉米区域试验，两年区试平均亩产545.6公斤，比对照郑单958增产6.0%，两年增产均达极显著2013年生产试验平均亩产545.6公斤，比对照郑单958增产4.4%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (430, 2, '苏玉41', '苏审玉201602', '2016.04', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', '苏95-1×JS09306，原名“苏试51101”', '江苏省淮北地区夏播', '特征特性：属中熟半紧凑型普通玉米。幼苗叶鞘淡紫色，叶片绿色，叶缘绿色，生长势强。株型半紧凑，茎秆粗壮，成株叶色深绿，花药绿到淡紫色，颖壳淡紫色；花丝绿到淡紫色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：株高251厘米，穗位高106厘米；穗长17.8厘米，穗粗4.8厘米，秃尖长0.8厘米，每穗14.8行，每行33粒。千粒重340克，出籽率85.4%。全生育期103天。倒伏率0.1%。中国农业科学院作物研究所接种鉴定：高抗茎腐病，中抗小斑病，感大斑病、纹枯病，高感粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重774克/升，粗蛋白9.73%，粗脂肪4.62%，粗淀粉74.19%，赖氨酸0.29%。产量和抗性表现：2013-2014年参加江苏省淮北普通玉米区域试验，两年区试平均亩产580.0公斤，平均比对照郑单958增产7.7%，两年增产均极显著。2015年参加江苏省淮北普通玉米生产试验，平均亩产642.6公斤，比对照郑单958增产13.7%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度4000-4500株/亩。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20-25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (431, 2, '苏玉42', '苏审玉 201503', '2015', 0, '江苏省农作物品种审定委员会', '江苏徐淮地区淮阴农科所', 'Y079譌246', '适宜江苏淮北地区夏播种植', '退出批次：特征特性：幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强株型紧凑成株叶色深绿；花药紫色，花丝浅红色；果穗筒形，穗轴红色；籽粒黄色，半马齿型省区试平均结果：株高255厘米，成株叶片20-21片，穗位高98厘米；穗长19.7厘米，穗粗5.1厘米，秃尖长1.7厘米，每穗17.1行，每行32粒千粒重336克，出籽率86.1%全生育期100天倒伏率0.1%病害经中国农业科学院作物研究所接种鉴定：中抗大斑病、茎腐病，抗小斑病，感纹枯病，高感粗缩病品质经农业部谷物品质监督检验测试中心（哈尔滨）检测：容重684克/升，粗蛋白10.66%，粗脂肪3.78%，粗淀粉74.76%，赖氨酸0.34%产量和抗性表现：2012-2013年参加江苏省普通玉米夏播区域试验，两年区试平均亩产600.7公斤，比对照郑单958增产8.1%，两年增产均极显著2014年生产试验平均亩产584.8公斤，比对照郑单958增产6.8%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (432, 2, '苏玉44', '苏审玉20170001', '2017.04', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司', 'SY35×G44，参试名称“Ly1210”', '江苏淮北地区夏播及淮南地区', '特征特性：中熟紧凑型普通玉米。幼苗叶鞘紫色，子叶椭圆形，叶色深绿，叶缘绿色，生长势强。株型紧凑，茎秆粗壮。成株叶色深绿，颖片淡紫色，花药紫色，花丝粉红色；果穗筒形，穗轴白色；籽粒黄色，半硬粒型。省区试平均结果：（淮南）株高263厘米，成株叶片19片，穗位高107厘米，穗长15.9厘米，穗粗4.9厘米，秃尖长0.7厘米，每穗14.9行，每行29.1粒。千粒重343克，出籽率84.7%。全生育期116天。倒伏率1.2%。（淮北）株高282厘米，成株叶片19片，穗位高113厘米；穗长17.1厘米，穗粗4.9厘米，秃尖长0.9厘米，每穗15.1行，每行32.2粒。千粒重320克，出籽率85.3%。全生育期101天。倒伏率0.9%。中国农业科学院作物研究所接种鉴定：抗大斑病、小斑病，中抗茎腐病，高感纹枯病，感瘤黑粉病，高感南方锈病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：（淮南）容重721克/升，粗蛋白9.23%，粗脂肪3.88%，粗淀粉72.96%，赖氨酸0.33%；（淮北）容重758克/升，粗蛋白8.11%，粗脂肪4.01%，粗淀粉71.08%，赖氨酸0.27%。产量和抗性表现：2014-2015年参加江苏省普通玉米区域试验：淮南地区两年区试平均亩产554.7公斤，比对照苏玉29增产5.5%；淮北地区两年区试平均亩产585.7公斤，比对照郑单958增产4.1%。2016年参加生产试验：淮南平均亩产516.3公斤，比对照苏玉29增产5.4%；淮北平均亩产653.6公斤，比对照郑单958增产6.7%。', '1、适期播种。一般春播4月初、夏播6月中下旬播种。2、合理密植。适宜密度每亩4000-4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20-25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕、做好壅土培根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好玉米螟、粗缩病、南方锈病、纹枯病等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (433, 2, '苏玉45', '苏审玉20180002', '2018.05', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院', 'L583×L051，参试名称“连试12-76”', '江苏省淮北地区夏播', '特征特性：中熟半紧凑型普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强。成株株型半紧凑，总叶片数19片左右；花药黄色，花丝红色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：株高276厘米，穗位高117厘米；穗长18.0厘米，穗粗4.8厘米，每穗15.2行，每行37粒。千粒重311克，出籽率86.4%。全生育期104天。倒伏率2.5%。中国农业科学院作物研究所接种鉴定：中抗大斑病，感小斑病，中抗腐霉茎腐病，感纹枯病、瘤黑粉病，抗南方锈病，高感粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重763克/升，粗蛋白8.97%，粗脂肪4.21%，粗淀粉74.06%，赖氨酸0.26%。产量和抗性表现：2015~2016年参加江苏省普通玉米夏播区域试验，两年区试平均亩产648.6公斤，比对照郑单958增产5.1%。2017年生产试验平均亩产623.1公斤，比对照郑单958增产5.4%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (434, 2, '苏玉4号', '苏种审字第122号', '1989', 0, '江苏省农作物品种审定委员会', '省农科院粮作所', '苏80-1×集2-9-1', '江苏作春、夏玉米种植', '退出批次：特征特性：该品种种子出苗快而整齐，苗势较强，幼苗第一叶椭园形，叶鞘紫色。株型较紧凑，株高230—240厘米，穗位高90—100厘米，全株18—19叶，叶征较窄，果穗长筒形，穗长20厘米，穗组4.5厘米左右，每穗14行，每行32—36粒，秃顶小，籽粒纯黄色，硬粒型，商品性好，千粒重300克左右，出籽率83%，籽粒营养品质较好，17种基氨酸总量占供干重8.659%，其中赖氨酸含量为0.275%。产量和抗性表现：1987、88年参加省玉米品种区域试验。1987年平均亩产420公斤，比对照苏玉1号增产5.1%，其中春播组比对照增产1.1%，不显著，夏播组比对照组增产7.8%，达极显著。1988年平均亩产463公斤，比对照苏玉1号增产6%，其中春播组比对照增产11.1%，夏播组增产2.7%，不显著。1988年省玉米生产试验，7个试点平均亩产比对照苏玉1号增产11.8%，其中春播组三个试点平均亩产460.1公斤，比对照增产15.27%，夏播组四个点平均亩产516.8公斤，比对照增产9.6%。经稳定性分析，回归系数为0.8836，表现良好稳产性，该组合产量高，稳产性好，适应性强。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (435, 2, '苏玉5号', '苏种审字第186号', '1993', 0, '江苏省农作物品种审定委员会', '省农科院粮作所', '黄杂C-7×SL2166', '江苏作春、夏玉米种植', '退出批次：特征特性：全生育期：春播129天左右，夏播101天左右，抗倒性强，抗大、小斑病，纹枯病，成熟期易感青枯病。产量和抗性表现：1991年1992年连续两年分别参加省春、夏播组区域试验，其中春播组，平均亩产分别为404.4和575.0公斤，比对照苏玉3号分别增产222.8%和16.7，达极显著水平.夏播组，平均亩产分别为577.3和489.4公斤，分别比对照掖单4叫增产3.5%和0.4%，产量水平与掖单4号相当.1992年参加春播组生产试验，平均亩产574.8公斤，比对照增产25.4%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (436, 2, '苏玉6号', '苏种审字第187号', '1993', 0, '江苏省农作物品种审定委员会', '扬州大学农学院农学系', 'J7A×黄早四', '江苏作夏玉米种植', '退出批次：特征特性：株高245厘米左右，穗位高约102厘米，总叶片19—20张，穗长14.2厘米，穗粗4.6厘米，每穗14行，每行31粒，出籽31粒，出籽率84%，籽粒为马齿型，黄色有白顶，千粒重280克左右.全生育期，夏播为93在左右.抗大、小斑病、青枯病、黑穗病和纹枯病，抗倒性一般。产量和抗性表现：1990—1991年参加江苏省玉米区域试验，1990年全省春、夏播区试平均单产382.0公斤，较对照苏玉4号增产11.1%，1991年亩产426.4公斤，比对照苏玉4号增产8.7%，其中夏播比苏玉4号增19.3%，1992年参加夏播生产试验，平均亩产446公斤，比苏玉4号增产18.1%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (437, 2, '苏玉7号', '苏种审字第189号', '1993', 0, '江苏省农作物品种审定委员会', '淮阴市农科所', 'N27�168', '江苏作夏玉米种植', '退出批次：特征特性：株高240厘米左右，穗位高95厘米左右，株型较松散，叶色深绿，部叶数19—20张，果穗稍短粗，穗长14.6厘米，穗粗4.6厘米，每穗12—14行，每行粒数30粒左右，出籽率89.4%，籽粒纯黄色，半硬粒，千粒重280克以上。全生育期98天，抗大、小斑病、抗倒性好，耐青枯病。产量和抗性表现：1990—1991年参加省区试，1990年春夏播平均单产392.0公斤，1991年单产为426.7公斤，分别地对照增产13.9%和8.8%，其中1990年夏播平均单产345公斤，比苏玉4号增产8.8%，1991年夏墦平均单产533.6公斤，比苏玉4号增产19.6%。1992年夏播生产试验中平均单产为395.4公斤，比对照苏玉4号增产4.8%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (438, 2, '苏玉8号', '苏种审字第217号', '1994', 0, '江苏省农作物品种审定委员会', '沿江地区农科所', '4S譋28', '江苏作春玉米种植', '退出批次：特征特性：该品种出苗快，苗势强，株型较紧凑，株高220—230厘米，穗位80—90厘米，主茎18—19叶，果穗圆柱形，穗长17—19厘米，穗粗4.8_5.0厘米，穗行数14_16行，每行30粒左右，出籽率87_90%，结实性好.籽粒马齿型、黄色、粒大、角质胚乳多，千粒重280—290克，籽粒中17捉氮基酸含量占烘干重9.58%，其中赖氨酸含量为0.322%。抗倒性好，较抗大小斑病，轻感纹枯病。全生育期春播101—103天，夏播94天。产量和抗性表现：1991至1992年两年分别参加省玉米品种春、夏播组区域试验。春播组，两年亩产分别为385.0和575.0公斤，比对照苏玉3号增产17%和16.7%，达显著和极显著水平。夏播组，两年亩产分别为560.5和475.5公斤.比对照掖单4号分别增产0.5和减产2.5%，增减产未达显著。1993年参加春播组生产试验，三个点平均亩产577.3公斤，比对照苏玉3号增产15.30%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (439, 2, '苏玉902', '苏审玉20230004', '2023.06', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所、江苏中禾种业有限公司', 'P17438×14T1，参试名称“通玉1902”', '江苏省淮南地区春播', '特征特性：普通玉米品种。幼苗叶鞘紫色，叶片绿色，生长势较强。株型半紧凑，茎秆粗壮，总叶片数20~21片，成株叶色绿色；花药淡紫色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期118.6天，比对照苏玉29短2.1天。株高249.4厘米，穗位高100.3厘米；穗长17.9厘米，穗粗4.9厘米，秃尖长0.6厘米；每穗14.2行，每行39.6粒；千粒重324.7克，出籽率86.0%；空秆率0.7%，倒伏倒折率3.6%。经江苏省农业科学院植物保护研究所接种鉴定：高抗大斑病，抗小斑病、弯孢菌叶斑，中抗纹枯病、腐霉茎腐病、南方锈病，感瘤黑粉病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重754克/升，粗蛋白11.21%，粗脂肪3.88%，粗淀粉69.24%，赖氨酸0.37%。产量和抗性表现：2020~2021年参加江苏省普通玉米淮南春播区试，两年平均亩产611.5公斤，比对照苏玉29增产6.6%。2022年参加生产试验，平均亩产657.1公斤，比对照苏玉29增产9.8%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4500株左右。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好小斑病、纹枯病、南方锈病、玉米螟等的防治工作 。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (440, 2, '苏玉9号', '苏种审字第233号', '1995', 0, '江苏省农作物品种审定委员会', '沿江地区农科所', '414�812', '江苏作春、夏玉米种植', '退出批次：特征特性：该品种出苗快、苗势强，株型紧凑，株高220厘米，穗位90厘米，果穗圆柱型，穗长17—19厘米，穗粗4.5厘米，每穗13—14行，每行35—40粒，出籽率80%左右，结率性好。籽粒型中间偏硬，黄色、粒大、角质胚乳多，千粒重300—350克，籽粒中17种氨基酸含量占烘干重9.53%，其中赖氨酸含量为0.29%。抗倒性强，抗大小斑病，轻感纹枯病，后期熟相好，全生育期春播97—98天，夏播87—88天。产量和抗性表现：1993年至1994年参加省玉米品种区域试验，春播组两年分别比对照掖单13增产3.9%和21%，均居首：夏播组两年分别比对照掖单13增产14.1%和15.7%，均居首位，1994年春、夏播组生产试验，分别比对照掖单13增产34.9%t 11.2%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (441, 2, '苏玉糯10号', '苏审玉200504', '2005.2', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所', 'W150譝448', '适宜江苏省各地种植', '退出批次：特征特性：春播播种至采收94天左右。出苗整齐，苗势强，幼苗叶鞘紫色，叶片绿色，叶缘紫色。株型半紧凑，整齐度较好，株高207.6cm左右，穗位101.8cm左右，双穗率6.5%左右，空杆率2%左右，成株叶片数19片左右。花药淡红色，颖壳淡紫色，花丝红色，果穗圆锥形，穗轴白色，穗长16.6cm左右，穗粗4.5cm左右，秃顶1.9cm左右，每穗14-16行，每行32粒左右，籽粒白色，千粒鲜重263.5g左右，鲜出籽率70.7%左右。田间表现，轻感玉米大、小斑病、病毒病、茎腐病，抗倒性较强。经省鲜食糯玉米品种区域试验组织的专家品尝鉴定，达到部颁鲜食糯玉米二级标准。经扬州大学农学院检测，支链淀粉占淀粉总量的98.23%，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2002-2003年参加江苏省区试，两年区试平均亩产鲜果穗723.5kg，比对照苏玉糯1号减产2.3%；2004年生产试验亩产864.9kg，比对照苏玉糯1号增产1.1%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (442, 2, '苏玉糯11号', '苏审玉200606', '2006.1', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所', 'T354譌H2', '适宜江苏各地种植', '退出批次：特征特性：春播播种至采收92天左右。出苗整齐，苗势强，幼苗叶鞘紫色，叶片绿色，叶缘紫色。株型半紧凑，整齐度较好，株高194.8厘米左右，穗位78.4厘米左右，双穗率11.4%左右，空杆率0.9%左右，成株叶片数18片左右。花药紫红色，颖壳浅紫色，花丝红色，穗轴白色，穗长18.6厘米左右，穗粗4.3厘米左右，秃顶2.3厘米左右，每穗14行左右，每行36粒左右，籽粒紫白相间，千粒鲜重231.6克左右，鲜出籽率67.5%左右。田间观察病害发生较经，抗倒性较强。中国农业科学院作物科学研究所接种鉴定，中抗小斑病、纹枯病，高感矮花叶病。省鲜食糯玉米品种区域试验组织的专家品尝鉴定，外观品质和蒸煮品质达到部颁鲜食糯玉米二级标准。扬州大学农学院检测，支链淀粉占淀粉总量的98.13%，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2003-2004年参加江苏省区试，两年区试平均亩产鲜果穗801.1公斤，较对照苏玉糯1号增产1.3%，2003年增产极显著，2004年减产极显著；2005年生产试验亩产791.9公斤，较对照苏玉糯1号增产9.1%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (443, 2, '苏玉糯1704', '苏审玉20200010', '2020.06', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所', 'T813M×JN6', '江苏省各地', '特征特性：糯玉米。幼苗叶鞘浅紫色，叶片绿色，叶缘绿色，生长势强。株型半紧凑，总叶片数20片，成株叶色绿色；花药黄色，颖壳绿色，花丝浅紫色；果穗长锥形，籽粒紫白色，穗轴白色。省区试平均结果：播种至采收鲜穗82天，与对照苏玉糯5号相当。株高231厘米，穗位高109厘米；穗长17.3厘米，穗粗4.5厘米，秃尖长1.1厘米，每穗13.1行，每行34.0粒，千粒鲜重321克，鲜穗出籽率65.1%；空秆率0.5%，倒伏倒折率2.3%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）：高抗瘤黑粉病；抗大斑病；中抗小斑病；感纹枯病；高感腐霉茎腐病、南方锈病、粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质87.7分。扬州大学农学院检测：支链淀粉占总淀粉的98.0%。产量和抗性表现：2017~2018年参加江苏省糯玉米区试，两年平均鲜穗亩产799.1公斤，比对照苏玉糯5号增产3.6%。2019年参加生产试验，平均鲜穗亩产845.0公斤，比对照苏玉糯5号增产8.1%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合施肥及时中耕，做好壅根培土以防倒伏。4、病虫害防治。用高效低毒残留农药及时防治地下害虫、食叶害虫、小斑病、玉米螟等。5、适时采收。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (444, 2, '苏玉糯18', '苏审玉200804', '2008.1', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所', 'W333譝695', '适宜江苏省各地种植', '退出批次：特征特性：出苗整齐，苗势强，叶鞘紫色，叶片绿色，叶缘紫色，株型半紧凑，花药绿色，花丝绿色，果穗长锥形，籽粒花紫色，半马齿型，穗轴白色省区试平均结果：株高183厘米，穗位82厘米，成株叶片19片，穗长17.0厘米，穗粗4.5厘米，每穗14-16行，每行31粒，千粒重243.0克，全生育期春播91天抗倒性较强中国农科院作物所接种鉴定，高抗大斑病、中抗小斑病、中抗纹枯病江苏省农科院植保所接种鉴定感粗缩病省鲜食玉米品种区域试验组织的专家品尝鉴定，外观品质和蒸煮品质达到部颁鲜食糯玉米二级标准扬州大学农学院检测，支链淀粉占淀粉总量的98.5%，达到糯玉米标准（NY/T524-2002）产量和抗性表现：2005-2006参加江苏省糯玉米区试，两年平均亩产879.0公斤，比对照苏玉糯1号增产9.7 %；2005年增产极显著，2006年增产不显著2007年生产试验平均亩产784.3公斤，比对照增产10.3%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (445, 2, '苏玉糯19', '苏审玉200805', '2008.1', 0, '江苏省农作物品种审定委员会', '南京神州种业有限公司', '4009�4025', '适宜江苏省各地种植', '退出批次：特征特性：出苗快而齐，生长势较强，株型半紧凑，叶鞘、叶缘紫色，第一叶尖端呈圆到匙形，鲜穗长筒型，籽粒乳白色，半马齿型，穗轴白色省区试平均结果：株高200厘米左右，穗位95厘米左右，成株叶片18-19片，穗长16.1厘米左右，穗粗4.2厘米左右，每穗14-16行，每行31粒左右，千粒重233.0克左右，全生育期春播约90天抗倒性一般中国农科院作物所接种鉴定，高抗大斑病、中抗小斑病、中抗纹枯病，江苏省农科院植保所接种鉴定感粗缩病省鲜食玉米品种区域试验组织的专家品尝鉴定，外观品质和蒸煮品质达到部颁鲜食糯玉米二级标准扬州大学农学院检测，支链淀粉占淀粉总量的98.0%，达到糯玉米标准（NY/T524-2002）产量和抗性表现：2005-2007年参加江苏省糯玉米区试，两年平均亩产806.3公斤，比对照苏玉糯1号增产0.5%；2005年增产不显著，2006年减产不显著2007年生产试验平均亩产718.0公斤，比对照增产1.0%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (446, 2, '苏玉糯2号', '苏审玉200203', '2002', 0, '江苏省农作物品种审定委员会', '沿江地区农科所', '361�366', '江苏省各地', '退出批次：特征特性：该品种鲜果穗为白色，籽粒排列整齐，穗型为锥型，果穗中等，有秃顶，综合外观印象较优；糯性、甜度不及苏玉糯1号；该品种籽粒皮层较薄，风味、口感一般。综合品质不及苏玉糯1号。春播鲜果穗成熟期为105天，比对照苏玉糯1号早1天。该品种吐丝较早，生长势强，株型半紧凑，耐旱性、抗倒性一般。该品种株高在176厘米，穗位在75厘米，植株田间整齐度好。穗长17.0厘米，穗粗4.7厘米，秃顶1.4厘米，每穗13.3行，每行31.5粒，锥型果穗，硬粒型糯玉米。产量和抗性表现：1999-2001年参加江苏省特种玉米新品种中间试验。1999-2000年两年区试平均亩产鲜果穗分别为880.40公斤和808.40公斤，比对照苏玉糯1号增产8.20%和13.60%，均居第1位。2001年参加江苏省特种玉米生产试验，平均亩产鲜果穗920.27公斤，比对照苏玉糯1号增产8.96%。审定通过，适宜我省各地种植。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (447, 2, '苏玉糯4号', '苏审玉200204', '2002', 0, '江苏省农作物品种审定委员会', '沿江地区农科所', '354譎22', '江苏省各地', '退出批次：特征特性：该品种鲜果穗为白色，籽粒排列整齐，穗型为圆筒-锥型，果穗中等，有秃顶，综合外观印象较优；糯性较好，与苏玉糯1号相当，甜度一般；该品种籽粒皮层一般，风味较浓，口感绵软，综合品质与苏玉糯1号相似，但在糯性、香味等方面不及苏玉糯1号。春播鲜果穗成熟期为105天，比对照苏玉糯1号早1天。    该组合前期长势强，株型半紧凑，抗倒性较好。该品种株高185厘米，穗位82厘米，比对照略低,植株田间整齐度好。穗长18.7厘米，穗粗4.4厘米左右，秃顶1.8厘米，每穗13行，每行38粒，锥型果穗，硬粒型糯玉米。产量和抗性表现：1999-2001年参加江苏省特种玉米新品种中间试验。1999-2000年两年区试平均亩产鲜果穗分别为850.40公斤和791.70公斤，比对照苏玉糯1号增产4.50%和11.20%，均居第2位。2001年参加江苏省特种玉米生产试验，平均亩产鲜果穗946.60公斤，比对照苏玉糯1号增产12.08%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (448, 2, '苏玉糯606', '苏审玉20190014', '2019.04', 0, '江苏省农作物品种审定委员会', '宿迁中江种业有限公司、江苏沿江地区农业科学研究所', 'W18-1×JN5，参试名称“苏玉糯1603”', '江苏各地', '特征特性：半紧凑型糯玉米。出苗整齐，苗势强，叶片绿色，株型半紧凑；果穗锥形，籽粒紫白色，糯质型。省区试平均结果：株高220厘米，穗位高94厘米；穗长17.5厘米，穗粗4.8厘米，每穗14.6行，每行30粒。千粒鲜重333克。春季播种至采收鲜穗约87天。鲜穗出籽率65.3%。倒伏倒折率2.0%。中国农科院作物研究所及江苏省农科院植保所接种鉴定：中抗大斑病、茎腐病，感小斑病，高感纹枯病、粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到鲜食糯玉米二级标准。扬州大学农学院检测：支链淀粉占总淀粉的97.5％，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2016~2017年参加江苏省糯玉米区域试验，两年区试平均亩产鲜穗828.8公斤，平均比对照苏玉糯5号增产8.8%。2018年生产试验平均亩产鲜穗857.3公斤，比对照苏玉糯5号增产8.4%。', '1、适期播种，根据上市时间和不同的栽培方式，合理安排播期。2、合理密植，适宜密度每亩4000株左右。3、加强肥水管理，有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合施肥及时中耕，做好雍根培土以防倒伏。4、病虫害绿色防控。用高效低毒残留农药及时防治地下害虫，食叶害虫、玉米螟、粗缩病、小斑病等。5、适时采收，一般在授粉后20-25天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (449, 2, '苏玉糯6号', '苏审玉200406', '2004', 0, '江苏省农作物品种审定委员会', '泰州市旱地作物研究所', '白粘93-3×北亚白糯', '适宜江苏各地种植', '退出批次：特征特性：株型半紧凑，株高221.5cm左右，穗位99.5cm左右，双穗率4.5%左右，空杆率1.8%左右，总叶片数19张左右，植株田间整齐度较好。穗长18.2cm左右，穗粗4.4cm左右，秃顶1.3cm左右，每穗14行左右，每行33.6粒左右，百粒鲜重35.1g左右，出籽率75.4%左右，硬粒型糯玉米。鲜穗白色，籽粒排列整齐，穗型为锥形，果穗适中，有秃顶，综合外观印象一般，糯性好，接近苏玉糯1号，略带甜味，籽粒不透明，口感较好，色泽好。春播鲜果穗成熟期108天左右，比对照苏玉糯1号迟1天。田间观察，抗病性强，抗倒性较强。产量和抗性表现：该品种两年区试平均亩产鲜果穗768.2公斤，比对照苏玉糯1号增产0.4%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (450, 2, '苏玉紫糯706', '苏审玉20210034', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所', 'W813×W36，参试名称“苏玉糯1706”', '江苏省各地', '特征特性：中熟鲜食糯玉米。出苗整齐，苗势强，叶片绿色。株型半紧凑；果穗锥形；籽粒紫红色。联合体区试平均结果：出苗至采收鲜穗80.6天，比对照苏玉糯5号长0.2天。株高226厘米，穗位高101厘米；穗长15.6厘米，穗粗4.7厘米，秃尖长0.8厘米，每穗14.2行，每行30.5粒；千粒鲜重356克，鲜穗出籽率68.9%；空秆率0.3%，倒伏倒折率0.6%。经江苏省农业科学院植保所接种鉴定：中抗大斑病、小斑病；感腐霉茎腐病、纹枯病、瘤黑粉病；高感南方锈病。江苏省糯玉米联合体品种区域试验品尝鉴定：外观品质和蒸煮品质87.0分。扬州大学农学院检测：支链淀粉占总淀粉的97.9%。产量和抗性表现：2018~2019年参加江苏省糯玉米省农科院联合体区试，两年平均亩产鲜穗827.2公斤，比对照苏玉糯5号增产5.1%。2020年参加生产试验，平均亩产鲜穗761.1公斤，比对照苏玉糯5号增产12.2%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合施肥及时中耕，做好雍根培土以防倒伏。4、病虫害防治。用高效低毒残留农药及时防治地下害虫、食叶害虫、玉米螟、纹枯病等病虫害。5、适时采收。一般在授粉后20~25天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (451, 2, '苏玉紫糯903', '苏审玉20220020', '2022.08', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所', 'T813M×TH1，参试名称“苏玉糯1903”', '江苏省各地', '特征特性：中早熟鲜食糯玉米。出苗整齐，苗势强，叶片绿色。株型半紧凑；果穗长锥形；籽粒紫色，糯质型。省区试平均结果：出苗至采收鲜穗83.6天，比对照苏玉糯5号长0.6天。株高247.3厘米，穗位高124.4厘米；穗长16.5厘米，穗粗4.4厘米，秃尖长1.3厘米，每穗14.6行，每行30.7粒；千粒鲜重302.0克，鲜穗出籽率63.6%；空秆率0.4%，倒伏倒折率1.2%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病，中抗小斑病，感腐霉茎腐病、纹枯病、瘤黑粉病，高感南方锈病。江苏省鲜食玉米品种区试品尝鉴定：外观品质和蒸煮品质89.2分。扬州大学农学院检测：支链淀粉占总淀粉的97.2%。产量和抗性表现：2019~2020年参加江苏省糯玉米区试，两年平均亩产鲜穗797.2公斤，比对照苏玉糯5号减产1.4%。2021年参加生产试验，平均亩产鲜穗755.4公斤，比对照苏玉糯5号减产0.6%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，亩施纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，其中基肥40%，苗肥20%，穗肥40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合施肥及时中耕，做好雍根培土以防倒伏。4、病虫害防治。用高效低毒残留农药及时防治地下害虫，食叶害虫、玉米螟、粗缩病、纹枯病等。5、适时采收。一般在授粉后20~25天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (452, 2, '苏甜8号', '苏审玉200103', '2001', 0, '江苏省农作物品种审定委员会', '淮阴市农科所', 'M017×黄早四', '江苏作春、夏玉米种植', '退出批次：特征特性：苏甜8号株高200厘米左右，穗位高50-60厘米，穗长20厘米左右，每穗籽粒16-18排。籽粒为淡黄色，排列整齐。果穗长筒形，中等大小，百粒重30-35克。含糖量24.5%（包括可溶性多糖），果皮嫩软，鲜食口味好。亩种植密度为3500-4000株。亩产量一般在750-800公斤。适宜于我省春夏播玉米区种植。该品种鲜果穗采收期春播85天左右，夏播70天左右，早熟性较好。该品种高抗丝黑穗病，抗大小斑病及纹枯病，抗旱性一般。产量和抗性表现：苏甜8号株高200厘米左右，穗位高50-60厘米，穗长20厘米左右，每穗籽粒16-18排。籽粒为淡黄色，排列整齐。果穗长筒形，中等大小，百粒重30-35克。含糖量24.5%（包括可溶性多糖），果皮嫩软，鲜食口味好。亩种植密度为3500-4000株。亩产量一般在750-800公斤。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (453, 2, '苏甜糯818', '苏审玉20220019', '2022.08', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所', 'T161×TN3，参试名称“苏玉糯1803”', '江苏省各地', '特征特性：中早熟鲜食糯玉米。出苗整齐，苗势强，叶片绿色。株型半紧凑；果穗长锥形；籽粒白色，甜糯型。省区试平均结果：出苗至采收鲜穗81.4天，比对照苏玉糯5号短0.3天。株高213.6厘米，穗位高85.8厘米；穗长17.5厘米，穗粗4.6厘米，秃尖长1.1厘米，每穗16.0行，每行34.2粒；千粒鲜重280.8克，鲜穗出籽率63.8%；空秆率0.5%，倒伏倒折率0.4%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病，中抗小斑病、瘤黑粉病，感腐霉茎腐病、纹枯病，高感南方锈病。江苏省鲜食玉米品种区试品尝鉴定：外观品质和蒸煮品质85.0分。扬州大学农学院检测：支链淀粉占总淀粉的97.0%。产量和抗性表现：2018~2019年参加江苏省糯玉米区试，两年平均亩产鲜穗824.5公斤，比对照苏玉糯5号增产2.9%。2021年参加生产试验，平均亩产鲜穗835.6公斤，比对照苏玉糯5号增产10.0%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，亩施纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，其中基肥40%，苗肥20%，穗肥40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合施肥及时中耕，做好雍根培土以防倒伏。4、病虫害防治。用高效低毒残留农药及时防治地下害虫，食叶害虫、玉米螟、粗缩病、纹枯病等。5、适时采收。一般在授粉后20~25天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (454, 2, '苏科玉010', '苏审玉20210016', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JS151047×JS191215，参试名称“焦点玉010”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘绿色，子叶匙形，叶缘绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数19片左右，成株叶色深绿，颖片淡紫色；花药淡紫色，花丝红色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期103.8天，比对照郑单958短1.0天。株高248厘米，穗位高100厘米；穗长17.1厘米，穗粗4.7厘米，秃尖长0.6厘米，每穗16.0行，每行34.2粒；千粒重319克，出籽率84.9%；空秆率0.5%，倒伏倒折率2.9%。经江苏省农业科学院植保所接种鉴定：高抗大斑病；抗小斑病、腐霉茎腐病；中抗瘤黑粉病；感纹枯病；高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重775克/升，粗蛋白8.19%，粗脂肪3.93%，粗淀粉73.84%，赖氨酸0.26%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播省农科院联合体区试，两年平均亩产603.6公斤，比对照郑单958增产7.0%。2020年参加生产试验，平均亩产554.9公斤，比对照郑单958增产5.4%。', '1、适期播种。一般夏播6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕、做好壅土培根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好玉米螟、粗缩病、南方锈病等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (455, 2, '苏科玉022', '苏审玉20220003', '2022.08', 0, '江苏省农作物品种审定委员会', '江苏金色农业股份有限公司、江苏省农业科学院粮食作物研究所', 'JS131089×JS161022，参试名称“金玉022”', '江苏省淮南地区春播', '特征特性：中熟普通玉米。第一叶顶端形状为圆到匙形，叶鞘紫色，叶色绿色，生长势强。株型半紧凑，总叶片数19片左右；花药红色，花丝红色；果穗筒形，穗轴白色；籽粒黄色，半硬粒型。省区试平均结果：全生育期120.2天，比对照苏玉29短2.6天。株高271.4厘米，穗位高105.6厘米；穗长17.3厘米，穗粗4.8厘米，秃尖长0.5厘米，每穗16.5行，每行34.4粒；千粒重325.2克，出籽率86.9%；空秆率0.9%，倒伏倒折率5.6%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病，中抗腐霉茎腐病、纹枯病，感瘤黑粉病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重756克/升，粗蛋白10.55%，粗脂肪3.75%，粗淀粉71.20%，赖氨酸0.29%。产量和抗性表现：2019~2020年参加江苏省普通玉米淮南春播区试，两年平均亩产667.4公斤，比对照苏玉29增产8.4%。2021年参加生产试验，平均亩产576.9公斤，比对照苏玉29增产4.4%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (456, 2, '苏科玉024', '苏审玉20220004', '2022.08', 0, '江苏省农作物品种审定委员会', '江苏金色农业股份有限公司、江苏省农业科学院粮食作物研究所', 'JS131089×JS161024，参试名称“金玉024”', '江苏省淮南地区春播', '特征特性：中熟普通玉米。第一叶顶端形状为圆形，叶鞘紫色，叶色绿色，生长势强。株型半紧凑，总叶片数19片左右；花药绿色，花丝红色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：全生育期120.1天，比对照苏玉29短2.7天。株高262.5厘米，穗位高103.1厘米；穗长17.9厘米，穗粗4.8厘米，秃尖长0.8厘米，每穗16.2行，每行35.0粒；千粒重321.9克，出籽率86.4%；空秆率0.7%，倒伏倒折率1.5%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病，中抗小斑病、纹枯病，感腐霉茎腐病、瘤黑粉病，高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重724克/升，粗蛋白10.01%，粗脂肪3.62%，粗淀粉73.43%，赖氨酸0.29%。产量和抗性表现：2019~2020年参加江苏省淮南普通玉米春播区试，两年平均亩产679.5公斤，比对照苏玉29增产10.4%。2021年参加生产试验，平均亩产589.6公斤，比对照苏玉29增产6.7%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、南方锈病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (457, 2, '苏科玉1409', '苏审玉20190006', '2019.04', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', '黄572×JS121046，参试名称“金大丰1906”', '江苏省淮北地区夏播', '特征特性：中熟半紧凑型普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势较强。茎秆粗壮，成株叶色淡绿，花药浅红色，颖壳淡紫色；花丝浅红色；果穗筒形，穗轴白色；籽粒黄色，半硬粒型。省区试平均结果：株高272厘米，穗位高106厘米；穗长17.9厘米，穗粗4.9厘米，秃尖长0.6厘米，每穗15.5行，每行34.7粒。千粒重317克，出籽率86.2%。全生育期104天。倒伏倒折率1.3%。中国农科院作科所和江苏农科院植保所接种鉴定：抗大斑病，中抗南方锈病，感小斑病，高感茎腐病、纹枯病、瘤黑粉、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重788克/升，粗蛋白9.77%，粗脂肪4.40%，粗淀粉74.80%，赖氨酸0.27%。产量和抗性表现：2016~2017年参加江苏省淮北普通玉米区试，两年区试平均亩产647.2公斤，比对照郑单958增产6.4%，2018年参加江苏省淮北普通玉米生产试验，平均亩产561.0公斤，比对照郑单958增产3.8%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好瘤黑粉、纹枯病、粗缩病、茎腐病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (458, 2, '苏科玉1417', '苏审玉20190005', '2019.04', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所、江苏农科种业研究院有限公司', 'PH6WC×JS131089，参试名称“苏试51417”', '江苏省淮北地区夏播', '特征特性：中熟紧凑型普通玉米。幼苗叶鞘紫色，子叶匙形，叶缘绿色，生长势强。株型紧凑，茎秆粗壮。成株叶色深绿，颖片淡紫色，花药紫色，花丝浅红色；果穗筒形，穗轴白色；籽粒黄色，半硬粒型。省区试平均结果：株高282厘米，穗位高107厘米，穗长18.7厘米，穗粗4.8厘米，秃尖长1.0厘米，每穗15.2行，每行31.8粒。千粒重354克，出籽率85.6%。全生育期103天。倒伏倒折率1.2%。中国农科院作科所和江苏农科院植保所接种鉴定：中抗大斑病、南方锈病、茎腐病，感小斑病、瘤黑粉病，高感纹枯病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）2018年检测：（淮北）容重800克/升，粗蛋白10.28%，粗脂肪3.49%，粗淀粉76.04%，赖氨酸0.31%。产量和抗性表现：2016~2017年参加江苏省淮北普通玉米区域试验：两年区试平均亩产647.6公斤，比对照郑单958增产6.4%。2018年参加生产试验：平均亩产569.8公斤，比对照郑单958增产5.4%。', '1、适期播种。一般夏播6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕、做好壅土培根以防倒伏。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好玉米螟、粗缩病、瘤黑粉、纹枯病等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (459, 2, '苏科玉1601', '苏审玉20230001', '2023.06', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JS151040×JS131089，参试名称“焦点玉1601”', '江苏省淮南地区春播', '特征特性：普通玉米品种。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势较强。株型半紧凑，茎秆粗壮，总叶片数20~21片，成株叶色绿色；花药浅紫色，花丝浅紫色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期120.0天，比对照苏玉29短2.8天。株高264.7厘米，穗位高104.2厘米；穗长18.2厘米，穗粗4.9厘米，秃尖长0.8厘米；每穗15.3行，每行36.2粒；千粒重341.5克，出籽率88.1%；空秆率0.5%，倒伏倒折率1.3%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、穗腐病，中抗小斑病、腐霉茎腐病，感纹枯病、瘤黑粉病、弯孢菌叶斑病，高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重740克/升，粗蛋白11.49%，粗脂肪3.69%，粗淀粉70.43%，赖氨酸0.39%。产量和抗性表现：2019~2020年参加江苏省普通玉米淮南春播区试，两年平均亩产676.3公斤，比对照苏玉29增产9.9%。2021年参加生产试验，平均亩产609.2公斤，比对照苏玉29增产10.3%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4200株左右。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、瘤黑粉病、南方锈病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (460, 2, '苏科玉1602', '苏审玉20210008', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JS131287×JS131061', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，子叶匙形，叶缘绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数19片左右，成株叶色深绿，颖片淡紫色；花药浅紫色，花丝绿色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：全生育期103.5天，比对照郑单958短0.5天。株高248厘米，穗位高104厘米；穗长17.2厘米，穗粗4.9厘米，秃尖长1.0厘米，每穗17.7行，每行33.2粒；千粒重310克，出籽率84.0%；空秆率1.0%，倒伏倒折率2.7%。经江苏省农业科学院植保所接种鉴定：高抗大斑病；抗小斑病；中抗纹枯病；感腐霉茎腐病、瘤黑粉病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重793克/升，粗蛋白9.24%，粗脂肪3.74%，粗淀粉73.51%，赖氨酸0.27%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播区试，两年平均亩产589.4公斤，比对照郑单958增产7.2%。2020年参加生产试验，平均亩产542.8公斤，比对照郑单958增产7.9%。', '1、适期播种。一般夏播6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕、做好壅土培根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好玉米螟、粗缩病等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (461, 2, '苏科玉1704', '苏审玉20210019', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JS151241×JS141073', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，子叶匙形，叶缘绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数19片左右，成株叶色深绿，颖片淡紫色；花药红色，花丝绿色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期104.3天，比对照郑单958短0.5天。株高227厘米，穗位高94厘米；穗长18.0厘米，穗粗4.4厘米，秃尖长1.2厘米，每穗14.9行，每行33.8粒；千粒重318克，出籽率84.7%；空秆率0.5%，倒伏倒折率1.5%。经江苏省农业科学院植保所接种鉴定：高抗大斑病；中抗小斑病、腐霉茎腐病、纹枯病、瘤黑粉病；高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重768克/升，粗蛋白9.41%，粗脂肪3.87%，粗淀粉72.02%，赖氨酸0.28%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播省农科院联合体区试，两年平均亩产598.4公斤，比对照郑单958增产6.1%。2020年参加生产试验，平均亩产555.4公斤，比对照郑单958增产5.5%。', '1、适期播种。一般夏播6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕、做好壅土培根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好玉米螟、粗缩病、南方锈病等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (462, 2, '苏科玉1706', '苏审玉20220005', '2022.08', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JS161131譐S141730', '江苏省淮南地区春播', '特征特性：中熟普通玉米。第一叶顶端形状为圆到匙形，叶鞘紫色，叶色绿色，生长势强。株型半紧凑，总叶片数19片左右；花药绿色，花丝红色；果穗筒形，穗轴粉红色；籽粒黄色，马齿型。省区试平均结果：全生育期118.3天，比对照苏玉29短4.5天。株高265.9厘米，穗位高100.6厘米；穗长17.5厘米，穗粗4.8厘米，秃尖长0.6厘米，每穗17.1行，每行35.2粒；千粒重312.2克，出籽率88.9%；空秆率0.7%，倒伏倒折率3.7%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、瘤黑粉病，中抗小斑病，感腐霉茎腐病、纹枯病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重741克/升，粗蛋白10.47%，粗脂肪4.73%，粗淀粉73.88%，赖氨酸0.28%。产量和抗性表现：2019~2020年参加江苏省普通玉米淮南春播区试，两年平均亩产683.1公斤，比对照苏玉29增产11.0%。2021年参加生产试验，平均亩产619.5公斤，比对照苏玉29增产12.1%。', '1、适期播种。一般4月上中旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (463, 2, '苏科玉1707', '苏审玉20210007', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JS131160×JS141733', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘绿色，子叶匙形，叶缘绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数19片左右，成株叶色深绿，颖片淡紫色；花药淡黄色，花丝红色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：全生育期104.2天，比对照郑单958长0.2天。株高262厘米，穗位高94厘米；穗长18.6厘米，穗粗4.8厘米，秃尖长0.9厘米，每穗17.6行，每行33.7粒；千粒重328克，出籽率85.0%；空秆率0.9%，倒伏倒折率2.0%。经江苏省农业科学院植保所接种鉴定：高抗大斑病；抗腐霉茎腐病；中抗小斑病、瘤黑粉病；感纹枯病、南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重744克/升，粗蛋白8.30%，粗脂肪3.68%，粗淀粉74.61%，赖氨酸0.28%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播区试，两年平均亩产594.7公斤，比对照郑单958增产8.2%。2020年参加生产试验，平均亩产551.1公斤，比对照郑单958增产9.5%。', '1、适期播种。一般夏播6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕、做好壅土培根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好玉米螟、粗缩病等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (464, 2, '苏科玉206', '苏审玉20210018', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JS151241×JS161117，参试名称“瑞华117”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘绿色，子叶匙形，叶缘绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数19片左右，成株叶色深绿，颖片淡紫色；花药浅紫色，花丝红色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期104.2天，比对照郑单958短0.6天。株高245厘米，穗位高103厘米；穗长17.6厘米，穗粗4.6厘米，秃尖长0.9厘米，每穗14.9行，每行33.3粒；千粒重337克，出籽率85.0%；空秆率0.6%，倒伏倒折率3.8%。经江苏省农业科学院植保所接种鉴定：高抗大斑病；中抗小斑病、腐霉茎腐病、瘤黑粉病；感纹枯病；高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重761克/升，粗蛋白10.09%，粗脂肪4.00%，粗淀粉72.54%，赖氨酸0.29%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播省农科院联合体区试，两年平均亩产606.2公斤，比对照郑单958增产7.5%。2020年参加生产试验，平均亩产564.0公斤，比对照郑单958增产7.1%。', '1、适期播种。一般夏播6月中下旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕、做好壅土培根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好玉米螟、粗缩病、南方锈病等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (465, 2, '苏科玉208', '苏审玉20210014', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏金色农业股份有限公司、江苏省农业科学院粮食作物研究所', 'JS151241×JS161107，参试名称“金玉107”', '江苏省淮南地区春播', '特征特性：中熟普通玉米。幼苗叶鞘绿色，子叶匙形，叶缘绿色，生长势强。株型半紧凑，茎秆粗壮，总叶片数19片左右，成株叶色深绿，颖片绿色；花药浅紫色，花丝绿色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期119.2天，比对照苏玉29短3.2天。株高259厘米，穗位高101厘米；穗长18.8厘米，穗粗4.8厘米，秃尖长1.5厘米，每穗16.8行，每行36.1粒；千粒重285克，出籽率86.3%；空秆率1.9%，倒伏倒折率5.9%。经江苏省农业科学院植保所接种鉴定：高抗大斑病；抗腐霉茎腐病；中抗小斑病、瘤黑粉病；感纹枯病；高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重754克/升，粗蛋白8.49%，粗脂肪3.88%，粗淀粉73.93%，赖氨酸0.29%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮南春播省农科院联合体区试，两年平均亩产633.8公斤，比对照苏玉29增产6.4%。2020年参加生产试验，平均亩产546.9公斤，比对照苏玉29增产5.2%。', '1、适期播种。一般春播4月上中旬播种。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般每亩20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕、做好壅土培根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好玉米螟、粗缩病、南方锈病等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (466, 2, '苏科玉218', '苏审玉20230006', '2023.06', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JS151040×JS161133，参试名称“瑞华玉901”', '江苏省淮北地区夏播', '特征特性：普通玉米品种。幼苗叶鞘绿色，叶片绿色，叶缘绿色，生长势较强。株型半紧凑，茎秆粗壮，总叶片数20~21片，成株叶色绿色；花药浅紫色，花丝绿色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期102.2天，比对照郑单958长1.1天。株高262.3厘米，穗位高91.6厘米；穗长19.8厘米，穗粗4.7厘米，秃尖长1.0厘米；每穗14.5行，每行35.0粒；千粒重342.6克，出籽率86.5%；无空秆，倒伏倒折率0.3%。经江苏省农业科学院植物保护研究所接种鉴定：高抗弯孢菌叶斑病，抗大斑病、小斑病、穗腐病，中抗纹枯病、南方锈病，感腐霉茎腐病，高感瘤黑粉病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重759克/升，粗蛋白10.34%，粗脂肪4.06%，粗淀粉73.23%，赖氨酸0.32%。产量和抗性表现：2020~2021年参加江苏省普通玉米淮北夏播区试，两年平均亩产523.3公斤，比对照郑单958增产12.3%。2022年参加生产试验，平均亩产514.3公斤，比对照郑单958增产3.8%。', '1、适期播种。一般6月中旬前后播种。2、合理密植。适宜密度每亩4500~5000株左右。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、瘤黑粉病、南方锈病、玉米螟等的防治工作', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (467, 2, '苏科甜1506', '苏审玉20190018', '2019.04', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JST13719×HZ-3', '江苏各地', '特征特性：半紧凑型甜玉米。幼苗叶鞘淡紫色，叶片绿色，叶缘绿色，生长势强；株型半紧凑，花药绿色，花丝绿色；果穗筒形，籽粒黄色，穗轴白色，甜质型。省区试平均结果：株高237厘米，穗位高105厘米；穗长18.2厘米，穗粗5.0厘米，每穗16.1行，每行34.2粒。籽粒黄色，穗轴白色，甜质型。千粒鲜重338克，鲜穗出籽率64.8%。春季播种至采收鲜穗约88天。倒伏率0.6%。中国农业科学院作科所及江苏省农科院植保所接种鉴定：中抗大斑病、茎腐病、纹枯病，感小斑病，高感粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到鲜食甜玉米二级标准。扬州大学农学院检测：水溶性糖含量为16.2%，还原总糖含量6.7%，达到甜玉米标准（NY/T523-2002）。产量和抗性表现：2016~2017年参加江苏省甜玉米区域试验：两年区试平均亩产鲜穗897.9公斤，比对照晶甜3号增产12.4%。2018年参加江苏省甜玉米生产试验：平均亩产鲜穗930.1公斤，比对照晶甜3号增产16.3%。', '1、适期播种，根据上市时间和不同的栽培方式，合理安排播期。2、合理密植，适宜密度每亩3500株左右。3、加强肥水管理，有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，注意防涝防旱。4、注意病虫害绿色防控。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、小斑病等。5、适时采收，一般在授粉后20~24天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (468, 2, '苏科甜1601', '苏审玉20200015', '2020.06', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JST14380×HZ-3', '江苏省各地', '特征特性：中熟甜玉米。幼苗叶鞘绿色，叶片绿色，叶缘绿色，生长势强。株型半紧凑，总叶片数19片，成株叶色绿色；花药绿色，颖壳绿色，花丝绿色；果穗长锥形，籽粒黄色，穗轴白色。省区试平均结果：播种至采收鲜穗82天，比对照晶甜3号短2天。株高241厘米，穗位高101厘米；穗长17.3厘米，穗粗4.9厘米，秃尖长0.7厘米，每穗16.2行，每行34.0粒，千粒鲜重341克，鲜穗出籽率70.9%；空秆率0.4%，倒伏倒折率0.7%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：抗小斑病；中抗大斑病、纹枯病、瘤黑粉病；感腐霉茎腐病；高感南方锈病、粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质87.5分。扬州大学农学院检测：水溶性糖含量17.2％，还原总糖含量9.1%。产量和抗性表现：2017~2018年参加江苏省甜玉米区试，两年平均鲜穗亩产839.3公斤，比对照晶甜3号增产7.4%。2019年参加生产试验，平均鲜穗亩产871.5公斤，比对照晶甜3号增产6.4%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500~4000株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮15公斤、五氧化二磷3~5公斤，氧化钾7.5~10公斤，基肥占40%，苗肥占20%，穗肥占40%，注意防涝防旱。4、注意病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟等。5、适时采收。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (469, 2, '苏科糯12', '苏审玉20180007', '2018.05', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'W13881×JSW12475，参试名称苏试81406', '江苏各地', '特征特性：半紧凑型糯玉米。幼苗叶鞘淡紫色，叶片绿色，叶缘绿色，生长势强；株型半紧凑，全株叶片数18片左右 ，花药绿色，花丝红色；果穗长锥形，籽粒红、白色，糯质型，穗轴白色。省区试平均结果：株高216厘米，穗位高100厘米；穗长18.1厘米，穗粗4.2厘米，每穗13.2行，每行31粒。千粒鲜重298克，鲜穗出籽率64.1%。春季播种至采收鲜穗约87天，比对照早1天。倒伏率2.2%。中国农科院作物研究所接种鉴定：感大斑病、小斑病、纹枯病、腐霉茎腐病，高感粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到鲜食糯玉米二级标准。扬州大学农学院检测：支链淀粉占总淀粉的97.1%，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2015~2016年参加江苏省糯玉米区域试验，两年区试平均亩产鲜穗776.8公斤，平均比对照苏玉糯5号增产1.6%。2017年生产试验平均亩产鲜穗787.5公斤，比对照苏玉糯5号增产0.5%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理，有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤、氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合肥料及时中耕，做好壅根培土以防倒伏。4、病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、纹枯病等。5、适时采收。一般在授粉后20~23天采收鲜穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (470, 2, '苏科糯1505', '苏审玉20190015', '2019.04', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JSW13841×JS0686', '江苏各地', '特征特性：半紧凑型糯玉米。幼苗叶鞘淡紫色，叶片绿色，叶缘绿色，生长势强；株型半紧凑，花药红色，花丝绿色；果穗锥形，籽粒黑色，穗轴黑色，甜糯型。省区试平均结果：株高224厘米，穗位高102厘米；穗长18.9厘米，穗粗4.6厘米，每穗13.8行，每行32.6粒。千粒鲜重372克，鲜穗出籽率68.4%。春季播种至采收鲜穗约86天。倒伏倒折率2.2%。中国农业科学院作科所及江苏省农科院植保所接种鉴定：中抗大斑病，感小斑病、纹枯病，高感茎腐病、南方锈病、粗缩病。江苏省糯玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到鲜食糯玉米二级标准。扬州大学农学院检测：支链淀粉占总淀粉的98.2％，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2016~2017年参加江苏省糯玉米区域试验：两年区试平均亩产鲜穗869.3公斤，比对照苏玉糯5号增产14.1%。2018年参加生产试验：平均亩产鲜穗891.4公斤，比对照苏玉糯5号增产12.7%。', '1、适期播种，根据上市时间和不同的栽培方式，合理安排播期。2、合理密植，适宜密度每亩4000株左右。3、加强肥水管理，有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，注意防涝防旱。4、注意病虫害绿色防控。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、小斑病、纹枯病等。5、适时采收，一般在授粉后22~25天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (471, 2, '苏科糯1602', '苏审玉20200011', '2020.06', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JSW14553×T2', '江苏省各地', '特征特性：糯玉米。幼苗叶鞘淡紫色，叶片绿色，叶缘绿色，生长势强。株型半紧凑，总叶片数19片，成株叶色绿色；花药红色，颖壳绿色，花丝红色；果穗长锥形，籽粒花（紫白）色，穗轴白色。省区试平均结果：播种至采收鲜穗83天，与对照苏玉糯5号相当。株高247厘米，穗位高115厘米；穗长17.1厘米，穗粗4.5厘米，秃尖长2.2厘米，每穗13.9行，每行33.0粒。千粒鲜重332克，鲜穗出籽率69.0%；空秆率0.3%，倒伏倒折率2.0%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：抗大斑病、瘤黑粉病；中抗小斑病、纹枯病；感腐霉茎腐病、南方锈病；高感粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质87.8分。扬州大学农学院检测：支链淀粉占总淀粉的98.4%。产量和抗性表现：2017~2018年参加江苏省糯玉米区试，两年平均鲜穗亩产781.0公斤，比对照苏玉糯5号增产3.1%。2019年参加生产试验，平均鲜穗亩产807.6公斤，比对照苏玉糯5号增产3.3%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，注意防涝防旱。4、注意病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、小斑病、玉米螟等。5、适时采收。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (472, 2, '苏科糯1702', '苏审玉20210024', '2021.03', 0, '江苏省农作物品种审定委员会', '镇江富华农业科技有限公司', 'T2×JSW15525', '江苏省各地', '特征特性：中熟鲜食糯玉米。幼苗叶鞘淡紫色，叶片绿色，生长势强。株型半紧凑；花药红色，花丝红色；果穗锥形，穗轴白色，籽粒白色。省区试平均结果：出苗至采收鲜穗81.6天，比对照苏玉糯5号长0.1天。株高222厘米，穗位高97厘米；穗长18.8厘米，穗粗4.5厘米，秃尖长1.5厘米，每穗14.4行，每行35.0粒；千粒鲜重338克，鲜穗出籽率70.1%；空秆率0.3%，无倒伏倒折。经江苏省农业科学院植保所接种鉴定：高抗大斑病；中抗小斑病、纹枯病；高感腐霉茎腐病、瘤黑粉病、南方锈病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质87.3分。扬州大学农学院检测：支链淀粉占总淀粉的97.9%。产量和抗性表现：2018~2019年参加江苏省糯玉米区试，两年平均亩产鲜穗843.8公斤，比对照苏玉糯5号增产5.2%。2020年参加生产试验，平均亩产鲜穗739.1公斤，比对照苏玉糯5号增产4.1%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，注意防涝防旱。4、注意病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、小斑病、纹枯病等。5、适时采收。一般在授粉后21~23天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (473, 2, '苏科糯1705', '苏审玉20210033', '2021.03', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所、句容苏科鲜食玉米研究有限公司', 'W935×JSW15621', '江苏省各地', '特征特性：中熟鲜食糯玉米。幼苗叶鞘淡紫色，叶片绿色，生长势强。株型半紧凑；花药绿色，花丝绿色；果穗锥形，穗轴白色；籽粒紫红色。联合体区试平均结果：出苗至采收鲜穗81.6天，比对照苏玉糯5号长0.8天。株高204厘米，穗位高84厘米；穗长18.0厘米，穗粗4.5厘米，秃尖长1.6厘米，每穗14.6行，每行34.2粒；千粒鲜重308克，鲜穗出籽率68.8%；空秆率0.7%，倒伏倒折率0.5%。经中国农业科学院作物科学研究所、江苏省农业科学院植保所接种鉴定：抗大斑病；中抗小斑病、瘤黑粉病；感纹枯病；高感腐霉茎腐病、南方锈病。江苏省糯玉米联合体品种区域试验品尝鉴定：外观品质和蒸煮品质87.7分。扬州大学农学院检测：支链淀粉占总淀粉的97.1%。产量和抗性表现：2018~2019年参加江苏省糯玉米省农科院联合体区试，两年平均亩产鲜穗792.2公斤，比对照苏玉糯5号增产0.7%。2020年参加生产试验，平均亩产鲜穗723.2公斤，比对照苏玉糯5号增产6.6%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，注意防涝防旱。4、注意病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、小斑病、纹枯病等。5、适时采收。一般在授粉后21~23天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (474, 2, '苏科糯1804', '苏审玉20220017', '2022.08', 0, '江苏省农作物品种审定委员会', '句容苏科鲜食玉米研究有限公司、江苏省农业科学院粮食作物研究所', 'JSW170357譐SW171075', '江苏省各地', '特征特性：中熟鲜食糯玉米。幼苗叶鞘淡紫色，叶片绿色，生长势强。株型半紧凑；花药淡红色，花丝淡红色；果穗长锥形，穗轴白色；籽粒紫白色，甜糯型。省区试平均结果：出苗至采收鲜穗83.7天，比对照苏玉糯5号长0.7天。株高226.4厘米，穗位高97.8厘米；穗长18.3厘米，穗粗4.8厘米，秃尖长1.5厘米，每穗13.5行，每行33.6粒；千粒鲜重333.6克，鲜穗出籽率61.2%；空秆率0.3%，倒伏倒折率1.4%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病，中抗小斑病、纹枯病，高感腐霉茎腐病、瘤黑粉病、南方锈病。江苏省鲜食玉米品种区试品尝鉴定：外观品质和蒸煮品质86.3分。扬州大学农学院检测：支链淀粉占总淀粉的97.1%。产量和抗性表现：2019~2020年参加江苏省糯玉米区试，两年平均亩产鲜穗896.4公斤，比对照苏玉糯5号增产10.9%。2021年参加生产试验，平均亩产鲜穗855.7公斤，比对照苏玉糯5号增产12.6%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500~4000株。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，亩施纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，其中基肥40%，苗肥20%，穗肥40%，注意防涝防旱。4、注意病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、小斑病、纹枯病等。5、适时采收。一般在授粉后21~23天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (475, 2, '苏科糯2号', '苏审玉200904', '2009.2', 0, '江苏省农作物品种审定委员会', '江苏省农科院粮作所', 'JS0381譐S0382', '适宜江苏各地种植', '退出批次：特征特性：出苗整齐，苗势强，叶鞘绿色，叶片绿色，叶缘绿色。株型半紧凑。花药红色，花丝粉红色，果穗长筒形，籽粒白色，硬粒型，穗轴白色。省区试平均结果：株高198厘米，穗位91厘米，成株叶片数19片。穗长17.0厘米，穗粗4.5厘米，每穗14-16行，每行31粒。千粒重251.0克，全生育期春播约86天。抗倒性较强。中国农科院作物所接种鉴定，中抗大斑病、小斑病，高感茎腐病，感纹枯病；江苏省农科院植保所接种鉴定感粗缩病。省鲜食玉米品种区域试验组织的专家品尝鉴定，外观品质和蒸煮品质达到部颁鲜食糯玉米二级标准。扬州大学农学院检测，支链淀粉占淀粉总量的98.4%，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2006-2007参加江苏省糯玉米区域试验，两年区试鲜穗平均亩产817.1公斤，比对照苏玉糯1号增产5.3%，两年增产均达极显著。2008年生产试验平均亩产850.5公斤，比对照苏玉糯1号增产16.4%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (476, 2, '苏科糯3号', '苏审玉201006', '2010.2', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JS0581譐S0686', '适宜在江苏各地种植', '退出批次：特征特性：出苗整齐，苗势强，叶鞘紫红色，叶片绿色，叶缘绿色株型半紧凑花药红色，花丝粉红色，果穗长锥形，籽粒花（紫白）色，硬粒型，甜糯穗轴白色省区试平均结果：株高180厘米，穗位80厘米，成株叶片数20片，穗长16.3厘米，穗粗4.6厘米，每穗14-16行，每行31粒，全生育期春播约85天，倒伏率1.2%中国农科院作物所2009年接种鉴定：中抗大斑病，高抗小斑病，抗茎腐病，感纹枯病，高感粗缩病省鲜食玉米品种区域试验组织专家品尝鉴定，外观品质和蒸煮品质达到部颁鲜食糯玉米二级标准扬州大学农学院检测：支链淀粉占淀粉总量的98.17%，达到糯玉米标准（NY/T524-2002）产量和抗性表现：2007-2008年参加江苏省糯玉米区域试验，两年区试鲜穗平均亩产807.6公斤，比对照苏玉糯1号增产12.3%，两年增产均达极显著2009年生产试验平均亩产鲜穗857.3公斤，比对照苏玉糯5号增产11.7%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (477, 2, '苏科糯4号', '苏审玉201106', '2011.3', 0, '江苏省农作物品种审定委员会', '江苏省农业科学研究院粮食作物研究所', 'JS0581譐S0585', '适宜在江苏省玉米产区种植', '退出批次：特征特性：出苗整齐，苗势强，叶鞘紫色，叶片绿色，叶缘红色株型紧凑花药红色，颖壳红色，花丝红色，籽粒花（紫白）色，偏硬粒型果穗锥形，穗轴白色省区试平均结果：株高183厘米，穗位84厘米，成株叶片数20片，穗长16.2厘米，穗粗4.4厘米，每穗14-16行，每行30粒，从出苗到采收春播约87天，倒伏率9.5%中国农业科学院作物研究所接种鉴定：抗大斑病、小斑病，中抗茎腐病，感纹枯病，高感粗缩病省鲜食玉米品种区域试验组织的专家品尝鉴定，外观品质和蒸煮品质达到部颁鲜食糯玉米二级标准扬州大学农学院检测：支链淀粉占淀粉总量的98.37%，达到糯玉米标准（NY/T524-2002）产量和抗性表现：2008-2009参加江苏省糯玉米区域试验，两年区试鲜穗平均亩产791.9公斤，2008年比对照苏玉糯1号增产10.0%，达极显著；2009年与对照苏玉糯5号平产2010年生产试验平均亩产鲜穗822.4公斤，比对照苏玉糯5号增产7.2%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (478, 2, '苏科糯5号', '苏审玉201205', '2012.3', 0, '江苏省农作物品种审定委员会', '江苏省农业科学研究院粮食作物研究所', 'JS0581譐S0601', '适宜江苏各地种植', '退出批次：特征特性：出苗整齐，苗势强，叶鞘淡紫色，叶片绿色，株型半紧凑，花药红色，颖壳红色，花丝粉红色，果穗锥形，籽粒白色，甜糯型，穗轴白色两年省区试平均结果：全生育期春播约89天，株高190厘米，穗位高92厘米，成株叶片数19片，穗长17.3厘米，穗粗4.4厘米，每穗14行，每行31粒，千粒鲜重301克，鲜出籽率68.1%，田间倒伏率13.5%中国农科院作物研究所接种鉴定：中抗大斑病，抗小斑病，感纹枯病，高感茎腐病、粗缩病省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到部颁鲜食糯玉米二级标准扬州大学农学院检测：支链淀粉占总淀粉的97.93％，达到糯玉米标准（NY/T524-2002）产量和抗性表现：2009年-2010年参加江苏省糯玉米区域试验，两年区试平均亩产鲜穗832.5公斤，比对照苏玉糯5号增产7.3%，2011年生产试验平均亩产鲜穗729.8公斤，比对照苏玉糯5号增产4.7%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (479, 2, '苏科糯6号', '苏审玉 201407', '2014', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JS09116譐S04388', '适宜江苏各地种植', '退出批次：特征特性：出苗整齐，苗势强，叶鞘绿色，叶片绿色株型半紧凑花药绿色，颖壳绿色，花丝绿色果穗锥形，籽粒红、白色，糯型，穗轴白色省区试平均结果：株高217厘米，穗位高104厘米，成株叶片数19~20片，穗长17~18厘米，穗粗4.1厘米，每穗14行，每行34粒，千粒鲜重270克，鲜出籽率63.9%，全生育期春播约88天田间倒伏率13.6%中国农科院作物研究所接种鉴定：抗大斑病、纹枯病，高抗茎腐病，中抗粗缩病省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到部颁鲜食糯玉米二级标准扬州大学农学院检测：支链淀粉占总淀粉的97.5％，达到糯玉米标准产量和抗性表现：2011年~2012年参加江苏省糯玉米区试，两年区试平均亩产鲜穗745.6公斤，比对照苏玉糯5号减产1.9%；2013年参加江苏省糯玉米生产试验，平均亩产鲜穗744.0公斤，比对照苏玉糯5号增产7.9%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (480, 2, '苏科糯9号', '苏审玉201604', '2016.04', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院粮食作物研究所', 'JS0581×JSW1033，原名“苏试81202”', '江苏各地', '特征特性：属早熟半紧凑型糯玉米。出苗整齐，苗势强，叶鞘紫红色，叶片绿色，花药淡红色，花丝绿色。株型半紧凑，果穗锥形，籽粒白色，糯质型，穗轴白色。江苏省区试平均结果：株高215厘米，穗位高103厘米，穗长17.7厘米，穗粗4.6厘米，每穗14.7行，每行35粒，千粒鲜重290克，鲜穗出籽率65.5%。春季播种至鲜穗采收约86天。田间倒伏率0.8%。中国农科院作物研究所接种鉴定：抗小斑病和纹枯病，中抗大班病，感茎腐病，高感粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到部颁鲜食糯玉米二级标准。扬州大学农学院检测：支链淀粉占总淀粉的97.4%，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2013-2014年参加江苏省糯玉米区试，两年区试平均亩产鲜穗823.0公斤，平均比对照苏玉糯5号增产15.6%；2015年参加江苏省糯玉米生产试验，平均亩产鲜穗768.4公斤，比对照苏玉糯5号增产5.2%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期，露地栽培一般于4月上旬播种。播种须保证土壤温度稳定在12摄氏度以上。2、合理密植。适宜密度4500株/亩左右，每亩用种量2.5公斤左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量一般不低于纯氮20公斤、五氧化二磷10公斤、氧化钾15公斤。肥料分配一般为基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕，做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效低毒低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病等。5、适时采收。一般在授粉后20-23天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (481, 2, '苏蔬甜糯918', '苏审玉20210025', '2021.03', 0, '江苏省农作物品种审定委员会', '南京润祥种业有限公司、江苏沿江地区农业科学研究所', 'Y161×Y381，参试名称“江玉糯901”', '江苏省各地', '特征特性：鲜食甜糯玉米。出苗整齐，叶片绿色，生长势强，叶片绿色，株型半紧凑；果穗锥形；籽粒白色。省区试平均结果：出苗至采收鲜穗81.2天，比对照苏玉糯5号短0.3天。株高219厘米，穗位高96厘米；穗长18.0厘米，穗粗4.7厘米，秃尖长1.2厘米，每穗15.2行，每行33.3粒；千粒鲜重284克，鲜穗出籽率61.4%；空秆率0.5%，无倒伏倒折。经江苏省农业科学院植保所接种鉴定：抗大斑病；中抗小斑病；感腐霉茎腐病、纹枯病、瘤黑粉病；高感南方锈病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质87.0分。扬州大学农学院检测：支链淀粉占总淀粉的97.5%。产量和抗性表现：2018~2019年参加江苏省糯玉米区试，两年平均亩产鲜穗792.3公斤，比对照苏玉糯5号减产1.1%。2020年参加生产试验，平均亩产鲜穗770.7公斤，比对照苏玉糯5号增产8.6%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合施肥及时中耕，做好雍根培土以防倒伏。4、病虫害防治。用高效低毒残留农药及时防治地下害虫、食叶害虫、玉米螟、纹枯病等病虫害。5、适时采收。一般在授粉后20~25天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (482, 2, '萃甜216', '苏审玉20200013', '2020.06', 0, '江苏省农作物品种审定委员会', '南京绿领种业有限公司', 'LVT-41×LVH11-7', '江苏省各地', '特征特性：中熟甜玉米。幼苗叶鞘绿色，叶片绿色，叶缘绿色，生长势旺盛。株型半紧凑，总叶片数18~19片，成株叶色绿色；花药黄色，颖壳绿色，花丝绿色；果穗长锥形，籽粒黄白相间，穗轴白色。省区试平均结果：播种至采收鲜穗83天，比对照晶甜3号短1天。株高205厘米，穗位85厘米；穗长19.5厘米，穗粗4.9厘米，秃尖长2.3厘米；每穗17.3行，每行37.0粒；千粒鲜重296克，鲜穗出籽率67.4%；空秆率1.2%，倒伏倒折率1.5%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：中抗大斑病、小斑病、纹枯病；感腐霉茎腐病、瘤黑粉病；高感南方锈病、粗缩病。江苏省鲜食玉米区域试验品种品尝鉴定：外观品质和蒸煮品质87.2分。扬州大学农学院检测：水溶性糖含量13.2%，还原总糖含量5.9%。产量和抗性表现：2017~2018年参加江苏省甜玉米区试，两年平均鲜穗亩产828.1公斤，比对照晶甜3号增产6.1%。2019年参加生产试验，平均鲜穗亩产862.2公斤，比对照晶甜3号增产5.3%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期，春播3月中下旬至4月上中旬，秋播7月上中旬至8月初。2、合理密植。适宜密度每亩3000~3500株，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量纯氮15~20公斤、五氧化二磷3~5公斤、氧化钾7.5~10公斤。基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕培土。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、小斑病、玉米螟等。5、适时采收。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (483, 2, '萃甜626', '苏审玉20220027', '2022.08', 0, '江苏省农作物品种审定委员会', '南京绿领种业有限公司', 'Lv甜-001B×Lvf-01', '江苏省各地', '特征特性：中熟超甜玉米。出苗整齐，叶鞘绿色，叶片绿色，叶缘绿色。株型半紧凑；花药黄色，颖壳绿色，花丝绿色；果穗长锥形，穗轴白色；籽粒黄白色，甜质型。省区试平均结果：出苗至采收鲜穗82.1天，与对照晶甜3号相当。株高237.6厘米，穗位高79.9厘米；穗长20.1厘米，穗粗4.9厘米，秃尖长2.2厘米，每穗15.0行，每行41.1粒；千粒鲜重345.3克，鲜穗出籽率67.2%；空秆率0.2%，无倒伏倒折。经江苏省农业科学院植物保护研究所接种鉴定：高抗大斑病，中抗小斑病、腐霉茎腐病、纹枯病，感瘤黑粉病，高感南方锈病。省鲜食玉米区试品尝鉴定：外观品质和蒸煮品质87.3分。扬州大学农学院检测：水溶性糖含量12.3%，还原总糖含量3.3%。产量和抗性表现：2018~2019年参加江苏省甜玉米区试，两年平均亩产鲜穗937.1公斤，比对照晶甜3号增产14.4%。2020年参加生产试验，平均亩产鲜穗845.0公斤，比对照晶甜3号增产14.6%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期，春播3月中下旬至4月上中旬，秋播7月中下旬至8月初。2、合理密植。适宜密度每亩3000~3500株左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，亩施纯氮15公斤、五氧化二磷4~5公斤、氧化钾7.5~10公斤，其中基肥40%，苗肥20%，穗肥40%，结合施肥及时中耕培土。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效低毒低残留农药及时防治地下害虫、玉米螟、食叶害虫、纹枯病、南方锈病等。5、适时采收。一般在授粉后20~24天采收鲜穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (484, 2, '萃甜糯516', '苏审玉20210027', '2021.03', 0, '江苏省农作物品种审定委员会', '南京绿领种业有限公司', 'NJ-01-01×LVTN-102', '江苏省各地', '特征特性：中熟甜糯玉米。出苗整齐，叶鞘紫红色，叶片绿色，叶缘绿色。株型半紧凑；花药黄色，颖壳绿色，花丝浅紫色；果穗锥形，穗轴白色，籽粒白色。省区试平均结果：出苗至采收鲜穗82.9天，比对照苏玉糯5号长1.3天。株高204厘米，穗位高82厘米；穗长19.7厘米，穗粗4.5厘米，秃尖长1.3厘米，每穗13.9行，每行38.7粒；千粒鲜重304克，鲜穗出籽率65.3%；空杆率0.6%，倒伏倒折率0.2%。经江苏省农业科学院植保所接种鉴定：高抗大斑病；中抗小斑病、瘤黑粉病；感腐霉茎腐病；高感纹枯病、南方锈病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质88.2分。扬州大学农学院检测：支链淀粉占总淀粉的99.2%。产量和抗性表现：2018~2019年参加江苏省糯玉米区试，两年平均亩产鲜穗811.4公斤，比对照苏玉糯5号增产1.0%。2020年参加生产试验，平均亩产鲜穗737.3公斤，比对照苏玉糯5号增产3.9%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期，春播3月中下旬至4月上中旬，秋播7月上中旬至8月初。2、合理密植。适宜密度每亩3000~3500株左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量纯氮15公斤、五氧化二磷4~5公斤、氧化钾7.5~10公斤。基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕培土。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效低毒低残留农药及时防治地下害虫、玉米螟、食叶害虫、纹枯病、南方锈病等。5、适时采收。一般在授粉后20~24天采收鲜穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (485, 2, '萃甜糯526', '苏审玉20220021', '2022.08', 0, '江苏省农作物品种审定委员会', '南京绿领种业有限公司', 'LVTN18-02譒VTN-102', '江苏省各地', '特征特性：中熟鲜食甜加糯玉米。出苗整齐，叶鞘紫色，叶片绿色，叶缘绿色。株型半紧凑；花药黄色，颖壳绿色，花丝浅紫色；果穗长锥形，穗轴白色；籽粒白色，糯质型。省区试平均结果：出苗至采收鲜穗85.3天，比对照苏玉糯5号长2.2天。株高252.6厘米，穗位高117.1厘米；穗长20.1厘米，穗粗4.8厘米，秃尖长2.2厘米，每穗15.4行，每行36.7粒；千粒鲜重329.2克，鲜穗出籽率68.0%；空秆率0.6%，倒伏倒折率2.6%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病，中抗小斑病、腐霉茎腐病、纹枯病、瘤黑粉病，高感南方锈病。江苏省鲜食玉米区试品种品尝鉴定：外观品质和蒸煮品质评分86.0分。扬州大学农学院检测：支链淀粉占总淀粉96.9%。产量和抗性表现：2019~2020年参加江苏省糯玉米区试，两年平均亩产鲜穗909.0公斤，比对照苏玉糯5号增产12.4%。2021年参加生产试验，平均亩产鲜穗869.7公斤，比对照苏玉糯5号增产14.5%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期，春播3月中下旬至4月上中旬，秋播7月中下旬至8月初。2、合理密植。适宜密度每亩3500株左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，亩施纯氮15公斤、五氧化二磷4~5公斤、氧化钾7.5~10公斤，其中基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕培土。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效低毒低残留农药及时防治地下害虫、玉米螟、食叶害虫、纹枯病、南方锈病等。5、适时采收。一般在授粉后22~26天采收鲜穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (486, 2, '虞珑糯1612', '苏审玉20210026', '2021.03', 0, '江苏省农作物品种审定委员会', '常熟市农业科学研究所、常熟市农业科技发展有限公司', 'da11×wd11y', '江苏省各地', '特征特性：鲜食糯玉米。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势强。株型半紧凑，成株叶色深绿；花药黄色，颖壳绿色，花丝绿色转深红色；果穗锥形，穗轴白色；籽粒黄白色。省区试平均结果：出苗至采收鲜穗81.5天，比对照苏玉糯5号短0.1天。株高214厘米，穗位高89厘米；穗长17.9厘米，穗粗4.5厘米，秃尖长1.2厘米，每穗14.0行，每行34.9粒；千粒鲜重305克，鲜穗出籽率65.4%；空秆率0.4%，倒伏倒折率0.4%。经江苏省农业科学院植保所接种鉴定：抗大斑病；中抗小斑病；感纹枯病、瘤黑粉病；高感腐霉茎腐病、南方锈病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质88.8分。扬州大学农学院检测：支链淀粉占总淀粉的98.4%。产量和抗性表现：2018~2019年参加江苏省糯玉米区试，两年平均亩产鲜穗794.3公斤，比对照苏玉糯5号减产1.0%。2020年参加生产试验，平均亩产鲜穗743.0公斤，比对照苏玉糯5号增产4.7%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000~4200株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合肥料及时中耕，做好壅根培土以防倒伏。4、病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、腐霉茎腐病等。5、适时采收。一般在授粉后20~23天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (487, 2, '虞璘糯308', '苏审玉20230012', '2023.06', 0, '江苏省农作物品种审定委员会', '常熟市种业有限公司、常熟市农业科学研究所、常熟国家农业科技园区', 'Wb11a譪e39', '江苏省各地', '特征特性：鲜食糯玉米品种。幼苗叶鞘紫色，叶片绿色，生长势一般。株型半紧凑；花药紫色，花丝淡红色；果穗长锥形，籽粒白色（鲜果带红斑）；穗轴白色。省区试平均结果：出苗至采收鲜穗80.2天，比对照苏玉糯5号短0.7天。株高232.9厘米，穗位高85.7厘米；穗长18.6厘米，穗粗4.3厘米，秃尖长0.5厘米，每穗12.3行，每行37.0粒。千粒鲜重311.7克，鲜穗出籽率67.8%。空秆率0.1%，倒伏倒折率0.6%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病，中抗小斑病、纹枯病、弯孢菌叶斑病，感瘤黑粉病，高感腐霉茎腐病、高感南方锈病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质87.6分。扬州大学农学院检测：支链淀粉占总淀粉的99.1%。产量和抗性表现：2020~2021年参加江苏省糯玉米区试，两年平均亩产鲜穗822.4公斤，比对照苏玉糯5号增产6.4%。2022年参加生产试验，平均亩产鲜穗819.6公斤，比对照苏玉糯5号增产5.5%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000~4500株。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，亩施纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，注意防涝防旱。4、注意病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、腐霉茎腐病、南方锈病等。5、适时采收。一般在授粉后21~23天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (488, 2, '蜜玉1号', '苏审玉200607', '2006.1', 0, '江苏省农作物品种审定委员会', '淮安市农业科学研究院', 'Mo17(sh2/sh2)×金银束二环系(sh2/sh2)', '适宜江苏各地种植', '退出批次：特征特性：春播播种至采收89天左右。出苗整齐，苗势强，幼苗叶鞘绿色，叶片绿色，叶缘绿色。株型松散，整齐度较好，株高186.3厘米左右，穗位56.7厘米左右，双穗率19.5%左右，空杆率0.3%左右，成株叶片数19片左右。花药黄色，颖壳绿色，花丝白色，穗轴白色，穗长18.2厘米左右，穗粗4.5厘米左右，秃顶1.7厘米左右，每穗15行左右，每行36粒左右，籽粒黄色，千粒鲜重251.6克左右，鲜出籽率69.8 %左右。田间观察病害发生较经，抗倒性较强。中国农业科学院作物科学研究所接种鉴定，感小斑病，高感矮花叶病、纹枯病。省鲜食糯玉米品种区域试验组织的专家品尝鉴定，外观品质和蒸煮品质达到部颁鲜食甜玉米二级标准。扬州大学农学院检测，水溶性糖含量16.92%，还原糖含量6.98%，均达到甜玉米标准（NY/T523-2002）。产量和抗性表现：2004-2005年参加江苏省区试，两年区试平均亩产鲜果穗696.6公斤，较对照蜜玉8号增产4.1%，2004年增产极显著，2005年增产不显著；2005年生产试验亩产650.4公斤，较对照蜜玉8号增产5.1%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (489, 2, '螽玉16号', '苏审玉200902', '2009.2', 0, '江苏省农作物品种审定委员会', '北京奥瑞金种业股份有限公司', '953�91158', '适宜江苏夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，生长势强，幼苗叶鞘紫红色，叶片深绿。株型半紧凑。花药黄色，颖片紫绿色，花丝绿色。果穗圆筒形，籽粒黄色，半硬粒型，穗轴白色。省区试平均结果：株高221厘米，成株叶片22片，穗位90厘米。穗长18.1厘米，穗粗5.0厘米，每穗16行，每行32粒。千粒重311.0克，出籽率85.0%，全生育期约101天。抗倒性较好。中国农业科学院作物研究所接种鉴定，感大斑病，中抗小斑病，高抗茎腐病，高感纹枯病；江苏省农科院植保所接种鉴定高感粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测，容重712克/升，粗蛋白9.3%，粗脂肪4.1%，粗淀粉73.7%，赖氨酸0.3%。产量和抗性表现：2006-2007年参加江苏省夏播玉米区域试验，两年区试平均亩产452.7公斤，比对照郑单958增产7.4%，两年增产均达极显著。2008年生产试验平均亩产553.6公斤，比对照郑单958增产10.2%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (490, 2, '蠡玉31', '苏审玉20190004', '2019.04', 0, '江苏省农作物品种审定委员会', '石家庄蠡玉科技开发有限公司', 'nd5×L91158B，参试名称蠡玉31', '江苏淮南地区春播', '特征特性：中熟半紧凑型普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势较强。株型半紧凑，茎秆粗壮，成株叶色绿，花药浅紫色，颖壳浅紫色，花丝浅紫色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。省区试平均结果：株高238厘米，穗位高105厘米；穗长17.8厘米，穗粗5.2厘米，秃尖长1.8厘米，每穗17.2行，每行30.7粒。千粒重322克，出籽率84.1%。全生育期121天。倒伏倒折率2.8%。中国农业科学院作物研究所及江苏省农科院植保所接种鉴定：中抗瘤黑粉、大斑病、南方锈病，感小斑病、茎腐病，高感纹枯病、粗缩病。农业部谷物品质监督检验测试中心（哈尔滨）检测：容重731克/升，粗蛋白11.05%，粗脂肪3.67%，粗淀粉71.50%，赖氨酸0.31%。产量和抗性表现：2016~2017年参加江苏省淮南普通玉米区试，两年区试平均亩产547.9公斤，比对照苏玉29增产5.8%， 2018年参加江苏省淮南普通玉米生产试验，平均亩产581.8公斤，比对照苏玉29增产5.6%。', '1、适期播种。一般4月初播种。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害绿色防控。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (491, 2, '西玉3号', '苏种审字第249号', '1996', 0, '江苏省农作物品种审定委员会', '省站徐州站引进', '478-31�502-133-196', '江苏作春、夏玉米种植', '退出批次：特征特性：该品种了苗快、苗势强、矮杆、株型紧凑，株高215厘米，穗位高83厘米，穗长14厘米，穗粗4.5厘米，每穗13.3行，每行30.4行，每行3.0粒，千粒重281.1克，出籽率80.4%，籽粒黄色，马齿型，抗病性、抗倒性中等。夏播生育期95天左右，比掖单13早熟5天左右。产量和抗性表现：1993年至1994年参加省玉米品种区域试验，1993年亩产478.9公斤，居14个参试品种的第四位，较对照掖单13增产2.3%，增产不显著；1994年亩产497.2公斤，居第三位，较对照增产8.9%，增产显著。1995年生产试验，6个平均亩产484.2公斤，比对照掖单13增产11.2%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (492, 2, '迁玉180', '苏审玉20220015', '2022.08', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院宿迁农科所', 'SY-18譙Y-009', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势较强。株型半紧凑，茎秆粗壮，成株叶片绿色；花药黄色，颖片浅黄色，花丝浅红色；果穗筒形，穗轴浅红色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期105.1天，比对照郑单958长1.9天。株高239.2厘米，穗位高100.2厘米；穗长20.1厘米，穗粗4.7厘米，秃尖长0.8厘米，每穗14.8行，每行36.0粒；千粒重367.1克，出籽率84.4%；空秆率1.5%，倒伏倒折率3.1%。经江苏省农业科学院植物保护研究所接种鉴定：高抗小斑病，中抗大斑病、腐霉茎腐病，感纹枯病、瘤黑粉病，高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重754克/升，粗蛋白9.87%，粗脂肪4.28%，粗淀粉72.36%，赖氨酸0.26%。产量和抗性表现：2018~2019年参加江苏省淮北（大华）普通玉米新品种联合体区试，两年平均亩产636.2公斤，比对照郑单958增产10.2%。2020年参加生产试验，平均亩产565.7公斤，比对照郑单958增产12.5%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮25公斤左右，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕，做好壅土培根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、瘤黑粉病、南方锈病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (493, 2, '迁玉3050', '苏审玉20220012', '2022.08', 0, '江苏省农作物品种审定委员会', '江苏省农业科学院宿迁农科所', 'SY-1192×JF-6，参试名称“天玉3050”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘绿色，生长势较强。株型紧凑，茎秆粗壮，成株叶色绿色；花药黄色，颖片淡黄色，花丝淡红色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期103.7天，与对照郑单958相当。株高255.7厘米，穗位高94.8厘米；穗长17.7厘米，穗粗4.9厘米，秃尖长1.5厘米；每穗15.0行，每行33.1粒；千粒重363.2克，出籽率84.8%；空秆率0.7%，倒伏倒折率1.2%。经江苏省农业科学院植物保护研究所接种鉴定：高抗大斑病，抗小斑病，中抗腐霉茎腐病、纹枯病、瘤黑粉病，高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重760克/升，粗蛋白8.84%，粗脂肪3.03%，粗淀粉77.26%，赖氨酸0.25%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播区试，两年平均亩产596.7公斤，比对照郑单958增产8.5%。2020年参加生产试验，平均亩产549.0公斤，比对照郑单958增产9.1%。', '1、适期播种。夏播一般6月中下旬播种。2、合理密植。适宜密度每亩4500株左右。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。结合施肥及时中耕，做好壅土培根以防倒伏。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好南方锈病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (494, 2, '连单761', '苏审玉20210017', '2021.03', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院', 'L112×L904，参试名称“连试71161”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色。株型半紧凑，总叶片数18片左右；花药黄色，花丝红色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期105.0天，比对照郑单958长0.3天。株高261厘米，穗位高98厘米；穗长18.1厘米，穗粗4.8厘米，秃尖长4.8厘米，每穗16.4行，每行32.6粒，千粒重343克，出籽率83.7%；空秆率1.1%，倒伏倒折率3.6%。经江苏省农业科学院植保所接种鉴定：抗大斑病、小斑病、纹枯病；中抗腐霉茎腐病、瘤黑粉病；高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重758克/升，粗蛋白8.26%，粗脂肪3.99%，粗淀粉75.03%，赖氨酸0.26%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播省农科院联合体区试，两年平均亩产598.6公斤，比对照郑单958增产6.1%。2020年参加生产试验，平均亩产558.4公斤，比对照郑单958增产6.0%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4500~4700株。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (495, 2, '连彩糯1607', '苏审玉20210023', '2021.03', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院、江苏金万禾农业科技有限公司', 'LN207×LN199', '江苏省各地', '特征特性：中熟鲜食糯玉米。幼苗叶鞘绿色，叶片绿色。株型半紧凑，总叶片数17片左右；花药黄色，颖壳淡绿色，花丝淡绿色；果穗锥形，穗轴白色，籽粒花（紫白）色。省区试平均结果：出苗至采收鲜穗80.7天，比对照苏玉糯5号短0.9天。株高219厘米，穗位高92厘米；穗长17.5厘米，穗粗4.7厘米，秃尖长0.5厘米，每穗15.4行，每行33.2粒；千粒鲜重326克，鲜穗出籽率66.8%；空秆率0.3%，倒伏倒折率0.7%。经江苏省农业科学院植保所接种鉴定：高抗大斑病；中抗小斑病；感南方锈病；高感腐霉茎腐病、纹枯病、瘤黑粉病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质86.6分。扬州大学农学院检测：支链淀粉占总淀粉的97.0%。产量和抗性表现：2018~2019年参加江苏省糯玉米区试，两年平均亩产鲜穗906.8公斤，比对照苏玉糯5号增产13.0%。2020年参加生产试验，平均亩产鲜穗808.0公斤，比对照苏玉糯5号增产13.9%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期，播种须保证土壤温度稳定在12摄氏度以上。2、合理密植。适宜密度每亩4500株左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量一般不低于纯氮20公斤、五氧化二磷10公斤、氧化钾15公斤。肥料分配一般为基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕，做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效低毒低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、大斑病等。5、适时采收。一般在授粉后20~22天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (496, 2, '连玉糯28', '苏审玉20220024', '2022.08', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院、江苏保丰集团公司', 'LN9×WD976，参试名称“保玉糯28”', '江苏省各地', '特征特性：中早熟鲜食糯玉米。幼苗叶鞘浅紫色，叶片绿色，叶缘绿色，生长势较强。株型半紧凑，总叶片数20片左右；花药浅紫色，花丝浅紫色；果穗长锥形，穗轴白色；籽粒花白色，糯质型。自主区试平均结果：出苗至采收鲜穗79.8天，比对照苏玉糯5号短0.8天。株高245.3厘米，穗位高110.1厘米；穗长18.6厘米，穗粗4.7厘米，秃尖长0.7厘米，每穗15.0行，每行34.1粒；千粒鲜重340.4克，鲜穗出籽率63.5%；空秆率0.9%，倒伏倒折率2.5%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病，中抗小斑病、纹枯病，感瘤黑粉病，高感腐霉茎腐病、南方锈病。江苏省鲜食玉米品种区试品尝鉴定：外观品质和蒸煮品质88.5分。扬州大学农学院（扬州）检测：支链淀粉含量97.0%。产量和抗性表现：2019~2020年经鲜食糯玉米自主区试，两年平均亩产鲜穗920.2公斤，比对照苏玉糯5号增产6.3%。2021年参加生产试验，平均亩产鲜穗867.7公斤，比对照苏玉糯5号增产6.2%。', '1、适期播种。一般4月~6月均可播种。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮18~20公斤，其中基苗肥60%，穗粒肥40%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、南方锈病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (497, 2, '连甜糯931', '苏审玉20230011', '2023.06', 0, '江苏省农作物品种审定委员会', '河北利宏种业有限公司、连云港市农业科学院、江苏金万禾农业科技有限公司', 'LN199譒N299', '江苏省各地', '特征特性：鲜食糯玉米品种。幼苗叶鞘紫色，叶片绿色，生长势强。株型半紧凑；花药黄色，花丝浅绿色；果穗长锥形，籽粒白色；穗轴白色。省区试平均结果：出苗至采收鲜穗80.8天，比对照苏玉糯5号短0.1天。株高244.9厘米，穗位高109.2厘米；穗长19.0厘米，穗粗4.6厘米，秃尖长1.2厘米，每穗14.3行，每行37.2粒。千粒鲜重304.7克，鲜穗出籽率69.0%。空秆率0.3%，倒伏倒折率1.3%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、纹枯病，中抗小斑病、弯孢菌叶斑病，感瘤黑粉病，高感腐霉茎腐病、南方锈病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质85.7分。扬州大学农学院检测：支链淀粉占总淀粉的97.7%。产量和抗性表现：2020~2021年参加江苏省糯玉米区试，两年平均亩产鲜穗858.0公斤，比对照苏玉糯5号增产11.0%。2022年参加生产试验，平均亩产鲜穗876.0公斤，比对照苏玉糯5号增产12.8%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500~4000株。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，亩施纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，基肥占40%，苗肥占20%，穗肥占40%，注意防涝防旱。4、注意病虫害防治。用高效、低毒、低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、小斑病、纹枯病等。5、适时采收。一般在授粉后21~23天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (498, 2, '连花糯2号', '苏审玉20170006', '2017.04', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院', 'LN9×LN221，参试名称“连糯1108”', '江苏各地', '特征特性：中熟紧凑型鲜食花糯玉米。出苗整齐，苗势强，叶鞘淡紫色，叶片绿色，株型紧凑。花药绿色，颖壳淡绿色，花丝淡紫色。果穗锥形，籽粒紫白相间，穗轴白色。江苏省区试平均结果：株高212厘米，穗位高91厘米，成株叶片数19片，穗长20.6厘米，穗粗4.4厘米，每穗13.3行，每行36粒，千粒鲜重294克，鲜穗出籽率63.7%，春季播种至鲜穗采收约90天。田间倒伏率1.5%。中国农科院作物研究所接种鉴定：高抗茎腐病、抗纹枯病、中抗大斑病、高感粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到鲜食糯玉米二级标准。扬州大学农学院检测：支链淀粉占总淀粉的97.3%，达到糯玉米标准（NY/T524-2002）。产量和抗性表现：2013-2014年参加江苏省糯玉米区试，两年区试平均亩产鲜穗862.0公斤，平均比对照苏玉糯5号增产21.0%；2015年参加江苏省糯玉米生产试验，平均亩产鲜穗752.3公斤，比对照苏玉糯5号增产3.0%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000-4500株，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量纯氮20公斤、五氧化二磷10公斤、氧化钾15公斤。基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕，做好培土壅根以防倒伏。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效低毒低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病等。5、适时采收。一般在授粉后20-25天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (499, 2, '连青贮920', '苏审玉20230016', '2023.06', 0, '江苏省农作物品种审定委员会', '连云港市农业科学院、张掖市盛丰农业科技开发有限公司', 'L922譒1029', '江苏省淮北地区夏播', '特征特性：青贮玉米品种。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势较强。株型平展，茎秆粗壮，总叶片数20~21片，成株叶色绿色；花药紫色，花丝浅红色；果穗筒形，穗轴白色；籽粒黄色，硬粒型。自主区试平均结果：出苗至收获94.2天，与对照雅玉青贮8号相当。株高271.6厘米，穗位高118.2厘米；无空秆，无倒伏倒折。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病、纹枯病、穗腐病，中抗弯孢菌叶斑病，感腐霉茎腐病、瘤黑粉病，南方锈病。经北京农学院植物科学技术学院品质检测：全株淀粉含量31.1%，中性洗涤纤维含量38.8%，酸性洗涤纤维含量20.2%，粗蛋白质含量8.4%。产量和抗性表现：2020~2021年自主试验两年平均亩产1269.5公斤，比对照雅玉青贮8号增产7.7%。2022年自主生产试验，平均亩产1288.1公斤，比对照雅玉青贮8号增产6.8%。', '1、适期播种。一般6月中旬至7月上旬播种。2、合理密植。适宜密度每亩5000株左右。3、加强肥水管理。施足基肥，补施苗肥，早施重施穗肥，有机肥和复合肥基施。基肥和孕穗肥施氮比4:6或5:5。每亩施肥总量一般不低于纯氮25公斤、五氧化二磷12公斤、氧化钾15公斤。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、瘤黑粉病、南方锈病、玉米螟等的防治工作。5、适时收获。全株含水量60~70%时收获。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (500, 2, '通甜2号', '苏审玉20170008', '2017.04', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所', 'JS401×TNF，参试名称 “TS1401”', '江苏各地', '特征特性：中熟半紧凑型甜玉米。春播出苗至采收90天，出苗整齐，苗期叶鞘紫色，叶色绿，叶缘紫色，苗势强。花药黄色，颖壳青色，青花丝。果穗筒形，籽粒黄色，甜质型，穗轴白色。株型半紧凑，株高243厘米，穗位高95厘米，成株叶片数19片，穗长20.4厘米，穗粗4.6厘米，平均每穗13.8行，每行37.3粒，千粒鲜重329克，鲜出籽率62.4%。中国农科院作物研究所接种鉴定：中抗大、小斑病，高抗茎腐病，感纹枯病，高感粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到部颁鲜食甜玉米二级标准。扬州大学农学院检测：水溶性糖20%，还原总糖7.1%，达到甜玉米标准（NY/T523-2002）。产量和抗性表现：2014-2015年参加江苏省甜玉米区试，两年区试平均亩产鲜穗824.6公斤，平均比对照晶甜3号增产9.8%；2016年参加江苏省甜玉米生产试验，平均亩产鲜穗817.8公斤，比对照晶甜3号增产5.8%。', '1、适期播种。根据上市时间及不同栽培方式，合理安排播期。2、合理密植。适宜密度每亩3500株左右，注意与其它类型玉米隔离种植。3、加强肥水管理。有机肥与氮、磷、钾合理搭配，每亩施肥总量纯氮15公斤、五氧化二磷4-5公斤、氧化钾7.5-10公斤。基肥40%，苗肥20%，穗肥40%。结合施肥及时中耕，做好培土壅根。做到田间沟系配套，注意防涝防旱。4、病虫害防治。用高效低毒低残留农药及时防治地下害虫、食叶害虫、玉米螟、粗缩病、纹枯病等。5、适时采收。一般在授粉后20-25天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (501, 2, '通甜3号', '苏审玉20200016', '2020.06', 0, '江苏省农作物品种审定委员会', '江苏沿江地区农业科学研究所', 'TS-1×TY-1，参试名称“通甜1701”', '江苏省各地', '特征特性：中熟甜玉米。幼苗叶鞘绿色，叶片绿色，叶缘绿色，生长势强。株型半紧凑，总叶片数19片，成株叶色绿色；花药黄色，颖壳青色，花丝青色；果穗筒形，籽粒黄色，穗轴白色。省区试平均结果：播种至采收鲜穗86天，比对照晶甜3号长2天。株高238厘米，穗位高97厘米；穗长20.7厘米，穗粗4.5厘米，秃尖长1.5厘米，每穗13.7行，每行38.0粒，千粒鲜重321克，鲜穗出籽率64.7%；空秆率0.4%，倒伏倒折率0.6%。经中国农业科学院作物研究所（2017年）、江苏省农业科学院植保所（2018年）接种鉴定：中抗小斑病、纹枯病、瘤黑粉病、南方锈病；感大斑病、腐霉茎腐病；高感粗缩病。江苏省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质88.8分。扬州大学农学院检测：水溶性糖含量16.8%，还原总糖含量8.0%。产量和抗性表现：2017~2018年参加江苏省甜玉米区试，两年平均鲜穗亩产844.7公斤，比对照晶甜3号增产8.2%。2019年参加生产试验，平均鲜穗亩产894.4公斤，比对照晶甜3号增产9.2%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理，有机肥及氮、磷、钾搭配合理，每亩施肥总量纯氮20公斤、五氧化二磷10公斤，氧化钾7.5~10公斤，基肥占40%，苗肥占20%，穗肥占40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合施肥及时中耕，做好壅根培土以防倒伏。4、病虫害防治。用高效低毒低残留农药及时防治地下害虫、食叶害虫、玉米螟等。5、适时采收。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (502, 2, '金城花糯', '苏审玉200403', '2004', 0, '江苏省农作物品种审定委员会', '江苏省如皋市种子公司', '176�515', '适宜江苏各地种植', '退出批次：特征特性：株型较紧凑，株高214.5cm左右，穗位103.5cm左右，双穗率7.1%左右，空杆率0.3%左右，总叶片数18-19张，保绿性好，植株田间整齐度一般。穗长19.5cm左右，穗粗4.5cm左右，秃顶1.9cm左右，每穗13行左右，每行37粒左右，百粒鲜重35.7g左右，鲜出籽率74.5%左右，半硬粒型糯玉米。鲜果穗白、紫相间，籽粒排列整齐，穗型为圆筒形，果穗较长，有秃顶，综合外观印象较好，糯性较好，略带甜味，籽粒不透明，口感较好，色泽一般。春播鲜果穗成熟期110天左右，比对照苏玉糯1号迟3天。田间观察，抗病性强，抗倒性较强。产量和抗性表现：该品种两年区试平均亩产鲜果穗927.5公斤，比对照苏玉糯1号增产20.8%。', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (503, 2, '金来玉5号', '苏审玉201004', '2010.2', 0, '江苏省农作物品种审定委员会', '莱州市金来种业有限公司', 'JL3148譐L045', '适宜在江苏夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，叶鞘紫色，生长势强，叶片深绿、上冲株型紧凑花药紫色，颖片绿带紫色，花丝紫色果穗圆锥形，籽粒黄色，半硬粒型，穗轴白色省区试平均结果：株高230厘米，成株叶片19片，穗位93厘米，穗长17.8厘米，穗粗4.9厘米，每穗12-14行，每行37粒，千粒重317.0克，出籽率84.6%全生育期约99天，倒伏率1.3%中国农业科学院作物研究所2009年接种鉴定：抗小斑病，高感纹枯病农业部谷物品质监督检验测试中心（哈尔滨）2009年检测：容重774克/升，粗蛋白11.02%，粗脂肪4.93%，粗淀粉71.75%，赖氨酸0.29%产量和抗性表现：2007-2008年参加江苏省夏播玉米区域试验，两年区试平均亩产503.5公斤，比对照郑单958增产5.8%，两年增产均达极显著2009年生产试验平均亩产553.5公斤，比对照郑单958增产7.2%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (504, 2, '长江玉6号', '苏审玉201101', '2011.3', 0, '江苏省农作物品种审定委员会', '南通志飞玉米研究所', 'P28譖84', '适宜在江苏省春播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，苗期叶鞘紫色，叶色绿，叶缘紫色，生长势强株型半紧凑花药紫色，颖片浅紫色，花丝紫红色果穗圆锥形，籽粒黄色，半硬粒型，穗轴白色省区试平均结果：株高225厘米，成株叶片20 片，穗位99厘米穗长17.5厘米，穗粗4.9厘米，每穗14-16行，每行32粒，千粒重329.0克，出籽率85.0%，全生育期约120天，倒伏率2.0%中国农业科学院作物研究所接种鉴定：抗大、小斑病，感纹枯、茎腐病，高感粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重732克/升，粗蛋白9.81%，粗脂肪4.04%，粗淀粉73.96%，赖氨酸0.26%产量和抗性表现：2008-2009年参加江苏省春播玉米区域试验，两年区试平均亩产493.0公斤，比对照苏玉19增产10.8%；两年增产均极显著2010年生产试验平均亩产466.1公斤，比对照苏玉19增产6.4%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (505, 2, '长江玉8号', '苏审玉 201301', '2013', 0, '江苏省农作物品种审定委员会', '南通市长江种子公司', 'FP02 譌P46', '适宜江苏省淮南春播地区种植', '退出批次：特征特性：出苗快，苗期叶鞘紫色，叶色绿，叶缘白色，生长势强株型半紧凑，花药黄色，颖片绿色，花丝紫红色果穗长锥形，籽粒黄色，半硬粒型，穗轴白色省区试平均结果：全生育期约119天，株高227厘米，穗位90厘米，穗长15.7厘米，穗粗4.8厘米，每穗14-16行，每行28粒，千粒重291克，出籽率84.9%，田间倒伏率1.3%中国农业科学院作物研究所接种鉴定：高抗大斑病、茎腐病，感纹枯病，高感粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重714克/升，粗蛋白10.37%，粗脂肪4.99%，粗淀粉71.57%，赖氨酸0.36%产量和抗性表现：2010-2011年参加江苏省普通玉米春播区域试验，两年区试平均亩产460.4公斤，比对照苏玉19增产7.7%，两年增产均极显著2012年生产试验平均亩产466.3公斤，比对照苏玉19增产9.8%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (506, 2, '长江玉9号', '苏审玉 201401', '2014', 0, '江苏省农作物品种审定委员会', '南通市长江种子公司', 'P288譖62', '适宜江苏淮南春播地区种植', '退出批次：特征特性：幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强株型半紧凑成株叶色深绿；颖片浅紫色，花药紫色，花丝紫红色；果穗筒形，穗轴红色；籽粒黄色，半马齿型省区试平均结果：株高220厘米，成株叶片20片，穗位高88厘米；穗长15.1厘米，穗粗4.8厘米，秃尖长0.6厘米，每穗13.1行，每行31粒千粒重321克，出籽率85.7%全生育期约112天倒伏率1.0%中国农业科学院作物研究所接种鉴定：抗大斑病，高抗茎腐病，感纹枯病、粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重742克/升，粗蛋白10.43%，粗脂肪4.55%，粗淀粉70.41%，赖氨酸0.24%产量和抗性表现：2011~2012年参加江苏省普通玉米春播区域试验，两年区试平均亩产452.2公斤，2011年比对照苏玉19增产12.7%，2012年比对照苏玉20增产11.1%，两年增产均极显著2013年生产试验平均亩产543.7公斤，比对照苏玉20增产4.9%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (507, 2, '长江花糯', '苏审玉201206', '2012.3', 0, '江苏省农作物品种审定委员会', '南通志飞玉米研究所', 'FN05譌N01', '适宜江苏各地种植', '退出批次：特征特性：出苗整齐，苗势强，叶鞘淡紫色，叶片绿色，株型半紧凑，花药红色，花丝红色，果穗锥形，籽粒花色，穗轴白色两年省区试平均结果：全生育期春播约89天，株高220厘米，穗位高93厘米，成株叶片数20片，穗长18.7厘米，穗粗4.4厘米，每穗14行，每行35粒，千粒鲜重299克，鲜出籽率69.9%，田间倒伏率12.3%中国农科院作物研究所接种鉴定：抗大斑病，中抗小斑病、茎腐病，感纹枯病，高感粗缩病省鲜食玉米品种区域试验品尝鉴定：外观品质和蒸煮品质达到部颁鲜食糯玉米二级标准扬州大学农学院检测：支链淀粉占总淀粉的97.41％，达到糯玉米标准（NY/T524-2002）产量和抗性表现：2009年-2010年参加江苏省糯玉米区域试验，两年区试平均亩产鲜穗867.9公斤，比对照苏玉糯5号增产11.7%，2011年生产试验平均亩产鲜穗778.1公斤，比对照苏玉糯5号增产11.7%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (508, 2, '长玉66', '苏审玉20220007', '2022.08', 0, '江苏省农作物品种审定委员会', '南通市长江种子有限公司', 'T204譚114', '江苏省淮南地区春播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘紫色，生长势强。株型半紧凑，成株叶色深绿色；花药紫色，颖壳紫色，花丝红色；果穗筒形，穗轴白色；籽粒黄色，半马齿型。联合体区试平均结果：全生育期122.4天，比对照苏玉29短2.1天。株高235.8厘米，穗位高91.5厘米；穗长17.3厘米，穗粗4.7厘米，秃尖长1.0厘米，每穗15.4行，每行34.6粒；千粒重319.5克，出籽率86.4%；空秆率1.2%，倒折倒伏率0.5%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病，中抗小斑病、腐霉茎腐病、纹枯病，感瘤黑粉病，高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）检测：容重734克/升，粗蛋白10.32%，粗脂肪3.19%，粗淀粉73.12%，赖氨酸0.28%。产量和抗性表现：2019~2020年参加江苏省淮南春玉米省农科院科企联合体区试，两年平均亩产640.6公斤，比对照苏玉29增产3.7%。2021年参加生产试验，平均亩产598.1公斤，比对照苏玉29增产9.2%。', '1、适期播种。一般4月初播种。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。氮、磷、钾配合使用，亩施纯氮20~25公斤，其中基苗肥50%，穗粒肥50%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好南方锈病、玉米螟的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (509, 2, '长玉糯30', '苏审玉20220022', '2022.08', 0, '江苏省农作物品种审定委员会', '南通市长江种子有限公司', 'RW262識W265', '江苏省各地', '特征特性：中晚熟鲜食糯玉米。出苗整齐，苗势强，叶片绿色。株型半紧凑；果穗长锥形；籽粒白色，糯质型。省区试平均结果：出苗至采收鲜穗84.6天，比对照苏玉糯5号长2.1天。株高228.9厘米，穗位高98.9厘米；穗长18.8厘米，穗粗4.7厘米，秃尖长0.8厘米，每穗14.4行，每行36.2粒；千粒鲜重339.6克，鲜穗出籽率65.8%；空秆率0.2%，倒折倒伏率1.0%。经江苏省农业科学院植物保护研究所接种鉴定：抗小斑病、瘤黑粉病，中抗大斑病、纹枯病，感腐霉茎腐病，高感南方锈病。江苏省鲜食玉米品种区试品尝鉴定：外观品质和蒸煮品质84.6分。扬州大学农学院检测：支链淀粉占总淀粉的97.8%。产量和抗性表现：2017~2018年参加江苏省糯玉米区试，两年平均亩产鲜穗864.5公斤，比对照苏玉糯5号增产12.0%。2019年参加生产试验，平均亩产鲜穗907.2公斤，比对照苏玉糯5号增产16.1%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，亩施纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，其中基肥40%，苗肥20%，穗肥40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合施肥及时中耕，做好雍根培土以防倒伏。4、病虫害防治。用高效低毒残留农药及时防治地下害虫、食叶害虫、玉米螟、纹枯病等病虫害。5、适时采收。一般在授粉后20~25天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (510, 2, '长甜糯218', '苏审玉20220023', '2022.08', 0, '江苏省农作物品种审定委员会', '南通市长江种子有限公司', 'RW262譚398', '江苏省各地', '特征特性：中熟鲜食糯玉米。出苗整齐，苗势强，叶片绿色。株型半紧凑；果穗长锥形；籽粒白色，糯质型。联合体区试平均结果：出苗至采收鲜穗81.9天，比对照苏玉糯5号长1.1天。株高237.8厘米，穗位高99.1厘米；穗长18.3厘米，穗粗4.6厘米，秃尖长0.3厘米，每穗13.8行，每行33.7粒；千粒鲜重355.2克，鲜穗出籽率68.2%；空秆率0.4%，倒伏倒折率0.4%。经江苏省农业科学院植物保护研究所接种鉴定：抗大斑病、小斑病、瘤黑粉病，中抗腐霉茎腐病、纹枯病，高感南方锈病。江苏省鲜食玉米品种区试品尝鉴定：外观品质和蒸煮品质86.8分。扬州大学农学院检测：支链淀粉占总淀粉的97.4%。产量和抗性表现：2018~2019年参加江苏省鲜食糯玉米省农科院科企联合体区试，两年平均亩产鲜穗865.9公斤，比对照苏玉糯5号增产10.0%。2020年参加生产试验，平均亩产鲜穗742.2公斤，比对照苏玉糯5号增产9.4%。', '1、适期播种。根据上市时间和不同的栽培方式，合理安排播期。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。有机肥及氮、磷、钾搭配合理，亩施纯氮20公斤、五氧化二磷10公斤，氧化钾15公斤，其中基肥40%，苗肥20%，穗肥40%，开好田间一套沟，做到三沟配套，注意防涝防旱。结合施肥及时中耕，做好雍根培土以防倒伏。4、病虫害防治。用高效低毒残留农药及时防治地下害虫、食叶害虫、玉米螟、纹枯病等病虫害。5、适时采收。一般在授粉后20~25天采收青穗。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (511, 2, '陇硕218', '苏审玉20210009', '2021.03', 0, '江苏省农作物品种审定委员会', '甘肃六和农业有限公司', 'LS0999×LS8402，参试名称“保玉1601”', '江苏省淮北地区夏播', '特征特性：中熟普通玉米。幼苗叶鞘紫色，叶片绿色，叶缘浅紫色，生长势较强。株型紧凑，总叶片数20片左右；花药浅紫色，花丝浅紫色；果穗筒形，穗轴红色；籽粒黄色，半马齿型。省区试平均结果：全生育期104.7天，比对照郑单958长0.8天。株高265厘米，穗位高94厘米；穗长17.5厘米，穗粗4.9厘米，秃尖长1.0厘米，每穗17.1行，每行32.2粒；千粒重343克，出籽率84.2%；空秆率1.9%，倒伏倒折率3.2%。经江苏省农业科学院植保所接种鉴定：中抗大斑病、小斑病、腐霉茎腐病、纹枯病；感瘤黑粉病；高感南方锈病。经农业农村部谷物及制品质量监督检验测试中心（哈尔滨）2020年检测：容重776克/升，粗蛋白8.64%，粗脂肪3.23%，粗淀粉75.18%，赖氨酸0.28%。产量和抗性表现：2018~2019年参加江苏省普通玉米淮北夏播区试，两年平均亩产588.0公斤，比对照郑单958增产6.9%。2020年参加生产试验，平均亩产557.4公斤，比对照郑单958增产10.8%。', '1、适期播种。一般6月中下旬播种。2、合理密植。适宜密度每亩4000株左右。3、加强肥水管理。氮、磷、钾配合使用，纯氮一般20~25公斤/亩，其中基苗肥40%，穗粒肥60%。做到田间沟系配套，注意防涝防旱。4、病虫害防治。对种子进行药剂处理，防治地下害虫；做好纹枯病、粗缩病、南方锈病、玉米螟等的防治工作。', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
INSERT INTO `ld_crop_variety` VALUES (512, 2, '隆平206', '苏审玉 201404', '2014', 0, '江苏省农作物品种审定委员会', '安徽隆平高科种业有限公司', 'L239譒7221', '适宜江苏淮北夏播地区种植', '退出批次：特征特性：出苗快而齐，苗势强，幼苗叶鞘紫色，叶片绿色株型紧凑颖片绿色，花药黄色，花丝粉红色果穗筒形，籽粒黄色、马齿型省区试平均结果：株高244厘米，成株叶片约20片，穗位98厘米，穗长16.8厘米，穗粗5.0厘米，每穗15.1行，每行32粒，千粒重322.0克，出籽率86.4%，全生育期约98天倒伏率3.2%中国农业科学院作物研究所接种鉴定：中抗大斑病、小斑病、茎腐病，高感纹枯病、粗缩病农业部谷物品质监督检验测试中心（哈尔滨）检测：容重738克/升，粗蛋白9.43%，粗脂肪3.70%，粗淀粉75.03%，赖氨酸0.28%产量和抗性表现：2010 ~2012年参加江苏省夏播玉米区域试验，三年区试平均亩产523.5公斤，比对照郑单958增产6.0%，三年增产均达极显著；2013年生产试验平均亩产546.3公斤，比对照郑单958增产4.5%', '', 1, '2025-07-22 09:41:28', '2025-07-22 09:41:28');
