INSERT INTO `ld_disease_knowledge_nodes` VALUES (7, 'type_2_crop_2', '虫害', 'disease_type', 'crop_2', NULL, NULL, NULL, NULL, '2025-07-31 17:03:48');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (8, 'type_3_crop_2', '生理性病害', 'disease_type', 'crop_2', NULL, NULL, NULL, NULL, '2025-07-31 17:03:48');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (9, 'disease_1', '小麦秆黑粉病', 'disease', 'type_1_crop_1', '主要侵害叶片、叶鞘及茎秆，极少数发生在颖壳或种子上。发病初期，在茎、叶、叶鞘等部位出现与叶脉平行的黄白色条斑，后渐转变成银灰色，逐渐隆起，最后寄主表皮破裂，露出黑粉，即病菌的厚垣孢子。病株显著矮小，分蘖增多，病叶卷曲畸形，多数病株不能抽穗而卷曲在叶鞘内，或抽出畸形穗。轻病株只有部分分蘖发病，其余分蘖仍能正常抽穗结实。', '该病发生与小麦发芽期土壤温度有关，土温在9～26℃范围内均可侵染，最适温度20℃左右。一般干燥地块较潮湿地块发病重。品种间抗病性差异明显。', '(1)种子处理：播种前进行药剂拌种，是防治小麦秆黑粉病的有效措施。药剂可以选用2%戊唑醇可湿性粉剂，或2.5%适乐时悬浮种衣剂，或15%三唑酮可湿性粉剂，或12.5%烯唑醇乳油，用量为种子重量的0.2%。(2)农业防治：种植抗病品种。整地保墒，适度浅播，缩短出苗时间。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-10/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (10, 'disease_2', '小麦秆枯病', 'disease', 'type_1_crop_1', '(1)苗期。幼苗出土后1个月便可出现症状，最初在幼苗第1片叶与芽鞘之间有针尖大的小黑块，以后逐渐蔓延到叶片、叶鞘及叶鞘内，有黑色粪状物，四周有梭形的褐色白斑。(2)成株期。病株拔节后，在叶鞘上形成有明显边缘的褐色云斑，病斑中间有黑色或灰黑色的虫粪状物。叶鞘与茎秆间逐渐发生一层白色菌丝，将内外层紧紧粘贴在～起。由于叶鞘受损，有的叶片下垂卷缩，叶色变为紫色，后枯黄，茎秆内充满白色菌丝。病株略有矮化。', '(1)感病期。麦苗在三叶期前为病菌侵入适期，三叶期后抵抗力增强，分蘖后感病很轻。(2)农业防治：土壤中病菌数量越多，发病越重。土壤温度低、湿度大时，有利于病菌侵染。冬小麦晚播，病害发生重。施肥不足，土壤瘠薄，栽培不良，植株生长衰弱时，发病较重。', '(1)农业防治：选种抗病品种。重病田应与其他作物实行3年以上的轮作。适期播种，合理施肥，增强小麦抗病能力。麦秸、麦糠沤肥要充分腐熟后施用。开沟排渍，雨后及时排水，避免苗期土壤过湿。收获后，清除田间病残株，集中沤肥或烧毁，深翻土地。(2)种子处理：用种子重量0.5％的50％福美双可湿性粉剂或50％甲基硫菌灵可湿性粉剂拌种。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-08/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (11, 'disease_3', '小麦全蚀病', 'disease', 'type_1_crop_1', '小麦全蚀病是一种典型的根腐和基腐性病害，病菌侵染部位只限于小麦根部和茎基部15cm以下，地上部的症状如白穗，主要是由于根及茎基部受害引起的。小麦整个生期均可感病。(1)苗期。幼苗感病后，初生根部根茎变为黑褐色，次根上有很多病斑，严重时病斑连在～起，使整个根系变黑亡。发病轻者即使不死亡，也表现为地上部叶色变黄，植矮小，生长不良，类似干旱缺肥状。病株易从根茎部拔断。(2)分蘖期。地上部分无明显症状，仅重病植株表现稍矮基部黄叶多。拔出麦苗，用水冲洗麦根，可见种子根与地茎都变成了黑褐色。(3)拔节期。病株返青迟缓，黄叶多，拔节后期重病植株矮化、稀疏，叶片自下而上变黄，似干旱缺肥状。麦田出现矮发病中心，生长高低不平。(4)抽穗灌浆期。病株成簇或点片出现早枯白穗，并且在茎基部叶鞘内侧形成“黑膏药”状的黑色菌丝层，极易识别。', '(1)品种因素。凡分蘖力强、根系发达的小麦品种，均较耐病。(2)栽培因素：连作病重，与非寄主作物轮作或水旱轮作发病轻。碱性土壤、土质疏松、肥力低，发病较重。土壤潮湿有利于病害发生和扩展，水浇地较旱地，发病重。冬小麦早播，发病重，晚发播病轻。', '(1)检疫：禁止从病区引种，防止病害蔓延。(2)种子处理：用51～54℃温水浸种10分钟。也可用种子重量0.2％的2％烯唑醇湿拌种剂拌种或用种子重量0.3％的15％三唑醇可湿性粉剂拌种。(3)栽培因素。种植耐病品种。增施腐熟有机肥，实行稻麦轮作或与棉花、烟草、蔬菜等非寄主作物轮作，可明显降低发病。(4)药剂防治：小麦播种后20～30天，喷洒15％三唑酮可湿性粉剂400倍液，第二年返青期再喷1次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-12/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (12, 'disease_4', '小麦炭疽病', 'disease', 'type_1_crop_1', '主要为害叶鞘和叶片。叶鞘染病麦株基部叶鞘先发病，初生褐色病变，产生1～2cm长的椭圆形病斑，边缘暗褐色，中间灰褐色，后沿叶脉纵向扩展成长条形褐斑，致病部以上叶片发黄枯死；叶片染病 形成近圆形至椭圆形病斑。后期病部连成一片，致叶片早枯。以上病部均有小黑粒点，即病原菌的分生孢子盘。茎秆染病生出梭形褐色病斑。 [侵染]病菌以分生孢子盘和菌丝体在寄主病残体上越冬或越夏，也可附着在种子上传播。播种带菌的种子或幼苗根及极颈或基部的茎接触带菌的土壤，即可染病。侵染后10天病部就可出现分生孢子盘。', '(1)气候因素。在田间气温25℃左右，湿度大，有水膜的条件下有利于病菌侵染和孢子形成。(2)农业防治：杂草多的连作地，肥料不足、土壤碱性地块利于发病。(3)寄主抗性。小麦品种间抗病性差异明显。', '(1)选用抗炭疽病的小麦品种。(2)与非禾本科作物进行3年以上轮作。(3)收获后及时清除病残体或深翻。(4)发病重的地区或地块，可喷洒50%苯菌灵可湿性粉剂1500倍液或25%苯菌灵乳油800倍液，防治1次或15天后再防一次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-22/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (13, 'disease_5', '小麦黑节病', 'disease', 'type_1_crop_1', '主要为害茎节，病部呈深褐色，可扩展至节间，发病严重时，茎节变黑腐烂，病部以上枯死。叶片发病，呈初生水渍状条斑，随后病斑颜色逐渐加深，最后变为深褐色。病斑可扩展至叶鞘上，形成长条形病斑，病斑黑褐色。', '主要由麦种带菌传播。', '(1)农业防治：病重田块的麦秆要及时处理。(2)种子处理：参见小麦散黑穗病。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-26/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (14, 'disease_6', '小麦白粉病', 'disease', 'type_1_crop_1', '主要为害叶片，严重时也可为害叶鞘、茎秆和穗部。病部最初出现1～2mm大小的白色霉点，后逐渐扩大为近圆形至椭圆形白色霉斑，霉层的厚度可达2mm左右，霉斑表面有一层白色粉状物。发病重时病斑连成一片，形成一大片白色至灰色的霉层。后期，白粉状霉层逐渐变为灰白色至淡褐色，并散出许多黄褐色至黑褐色的小粒点。被害叶片霉层下的组织，在初期无明显变化。随着病情的发展，叶片发生褪绿、发黄乃至枯死。麦粒颖壳受害时，能引起枯死，使麦粒不饱满甚至腐烂。发病严重的病株矮而弱，不能抽穗或抽出的穗短小。一般叶正面的病斑比叶背面的多，下部叶片比上部叶片被害重。发病严重时，整个植株从下到上均被灰白色的霉层覆盖。', '(1)气候因素。发病适温15～20℃，相对湿度大于70％有可能造成病害流行。冬季温暖、雨雪较多，或土壤湿度较大，有利于病菌越冬。雨日、雨量过多，可冲刷掉表面分生孢子，从而减缓病害发生。(2)农业防治：偏施氮肥，造成植株贪青，发病重。植株生长衰弱、抗病力低易发病。', '(1)农业防治：因地制宜，种植抗病品种。多施堆肥或腐熟有机肥，增施磷钾肥，提高植株抗病力。及时浇水抗旱，雨后要及时排水，防止湿气滞留。自生麦苗越夏地区，冬小麦秋播前要及时清除掉自生麦，可大大减少秋苗菌源。(2)种子处理：用种子重量0.15％的25％三唑酮可湿性粉剂拌种可较好地预防白粉病的发生。(3)药剂防治：当田间病叶率达10％以上时，用25％三唑酮乳油1 000倍液，或40％福星乳油8 000倍液，或50％甲基硫菌灵可湿性粉剂1000倍液，或50％多菌灵可湿性粉剂1 000倍液，或波美0.5～0.8度石硫合剂，或50％硫磺胶悬剂100倍液喷雾，每隔7～10天喷1次，连续防治1～2次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-01/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (15, 'disease_7', '小麦条锈病', 'disease', 'type_1_crop_1', '主要发生在叶片上，叶鞘、茎秆、穗部、颖壳及芒上也可发生。(1)苗期。幼苗叶片上出现鲜黄色小点，呈多层轮状排列，即夏孢子堆。(2)成株期。叶片初生褪绿条斑，后逐渐隆起，转为鲜黄色，即夏孢子堆。夏孢子堆小，椭圆形，在叶片上沿叶脉纵向排列成整齐的虚线条状。后期表皮轻微破裂，散出鲜黄色的夏孢子。小麦近成熟时，在叶鞘和叶片上出现短线条状较扁平的黑色冬孢子堆，叶背较显著。冬孢子堆可数个联合，表皮不破裂。', '(1)农业防治：大面积长期种植具同一抗源的品种，往往造成病菌小种的改变，发病严重。(2)气候因素。早春持续低温多雨，发病重。越冬菌量多，发病严重。', '(1)农业防治：因地制宜地选用抗病品种，做到抗源布局合理及品种定期轮换。适期播种，适当晚播，不要过早，可减轻秋苗期条锈病发生。施足堆肥或腐熟有机肥，增施磷钾肥，搞好氮磷钾合理搭配，增强小麦抗病力。合理灌溉，雨后注意开沟排水，降低田间湿度。后期，发病重的需适当灌水，减少产量损失。清除自生麦。(2)种子处理：用种子重量0.2％的15％三唑酮可湿性粉剂，或12.5％烯唑醇乳油拌种，或用种子重量0.1％～0.15％的2％烯唑醇湿拌种剂拌种。(3)药剂防治：发病初期选用20％三唑酮乳油1 500倍液，或12.5％烯唑醇乳油1 500倍液，或25％敌力脱乳油2 000倍液喷雾。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-02/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (16, 'disease_8', '小麦秆锈病', 'disease', 'type_1_crop_1', '主要为害叶鞘、茎秆及叶片基部，严重时在麦穗的颖片和芒上面也有发生。病部初形成条斑，后逐渐形成隆起的疱疹斑，即夏孢子堆。夏孢子堆比条锈病和叶锈病的大，呈长椭圆形，深褐色，排列不规则，表皮很早破裂并外翻，大量的夏孢子向外扩散。小麦成熟前，在夏孢子堆中或其附近产生长椭圆形或长条形的黑色冬孢子堆，后期表皮破裂。发生在叶片上的秆锈病孢子堆可穿透叶片，在背面也出现相同的症状，且叶片背面的孢子堆都比正面的大。', '(1)气候因素。除大量外来菌源外，大面积感病品种、偏高气温和多雨水是造成流行的因素。(2)寄主抗性。小麦品种间抗病性差异明显。(3)环境因素。病菌侵入适温18～22℃。降雨、结露或有雾可造成病害流行。地势低洼，土质黏重，排水不良，可加重病害发生。(4)栽培因素。晚播迟熟小麦发病重。植株密茂、贪青有利于病害的发生。', '(1)农业防治：①因地制宜地选用抗病品种。注意品种塔配和轮换种植，避免长期单一种植某一品种。②适期播种，防止播种过早过晚，合理密植。③施足基肥，增施磷钾肥，巧施追肥，切忌氮肥偏多偏晚。小麦生育后期用4.5～7.5kg／hm?磷酸二氢钾加水750kg，叶面喷，可以防止叶片早衰，减轻锈病为害。多雨时注意排水降湿，发病后，应及时灌水。④消除自生麦苗有助减轻锈病为害。(2)化学防治：①用25%三唑酮可湿性粉剂75g，拌麦种100kg，拌匀后闷1～2小时播种。②病秆率1%～5%时喷药防治。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-03/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (17, 'disease_9', '小麦叶锈病', 'disease', 'type_1_crop_1', '叶片受害，产生圆形或近圆形桔红色疹状病斑，即夏孢子堆。夏孢子堆比秆锈病的小，较条锈病的大。夏孢子堆表皮破裂后，散出黄褐色粉末，即夏孢子。夏孢子堆较小，不规则散生，多发生在叶片正面。有时病菌可穿透叶片，在叶片两面同时形成夏孢子堆。后期在叶背面散生暗褐色至深褐色、椭圆形的冬孢子堆，成熟时不破裂。有时也为害叶鞘，但很少为害茎秆或穗。', '(1)气候因素。冬季气温高，雪层厚，覆雪时间长，土壤湿度大，发病重。春季旬均温度10℃时，若温度回升快且有雨露较多，病害发生严重。小麦抽穗前后，如降雨次数多，可造成叶锈病的流行。(2)农业防治：冬小麦播种早，出苗早，发病重。田间湿度大，也容易发病。', '(1)种子处理：用种子重量0.04％(有效成分)的叶锈特或三唑酮拌种。(2)农业防治：因地制宜地选用抗病品种，注意品种合理搭配及轮换，避免长期单一种植。适期播种，适当晚播，可减轻秋苗期条锈病发生。施足堆肥或腐熟有机肥，增施磷钾肥，搞好氮磷钾合理搭配，增强小麦抗病力。铲除自生麦苗和杂草。合理灌溉，雨后注意开沟排水，降低田间湿度。后期，发病重的需适当灌水，减少产量损失。(3)药剂防治：发病初期喷洒20％三唑酮乳油1 000倍液，或20%烯肟?戊唑悬浮剂2 500倍液，或25%戊唑醇可湿性粉剂4 000倍液。每隔10天喷1次，共喷2次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-04/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (18, 'disease_10', '小麦纹枯病', 'disease', 'type_1_crop_1', '主要发生在叶鞘及茎秆上。小麦出苗后，根茎、叶鞘即可受害。发病初期，在地表或近地表的叶鞘上先产生淡黄色小斑点，随后发展呈典型的黄褐色梭形或眼点状病斑。病部逐渐扩大，颜色变深，向内侧发展可延及茎秆，引起病株的基部茎节腐烂，幼苗猝倒、死亡。小麦生长中期至后期，叶鞘上的梭形病斑常相互连结，形成云纹状花纹，中间呈淡黄褐色，周围有较明显的棕褐色环圈。病斑可沿叶鞘向植株上部扩展，直至旗叶。常因品种不同，形成青褐色至黄褐色花秆，使叶鞘及叶片早枯。当麦株间空气湿度大时，病斑也可向内侧扩展深及茎秆，导致烂茎，形成枯孕穗或枯白穗。在病株中部或中下部叶鞘的病斑表面产生白色霉状物，并纠集成团，颜色由淡黄色至黄褐色，逐渐变深，最后形成许多散生的、圆形或近圆形的褐色小颗粒状物，即病菌的菌核，大小1～2mm。菌核由少数菌丝与叶鞘组织相连，较易脱落。病菌也可以侵害根部。受害幼苗根系遭受破坏，根部呈褐色赶赴。重病苗逐渐死亡，轻病苗尚可生出新根。病苗地上部矮小，叶片小而挺直，暗灰蓝色。', '(1)高峰期。该病有2个明显的发病高峰，即冬前期和第二年，小麦拔节至孕穗期。(2)气候因素。当日均温度在10℃以下时，病害发展缓慢，超过15℃时病情上升，20～25℃时病情发展迅速，30℃左右时，病害发展基本停止。春季多雨潮湿的天气，有利于病原菌的发生和发展。(3)栽培因素。冬麦播种过早，密度过大，偏施氮肥，麦苗生长过旺，发病重。常年连作、麦田草害严重、土壤或田间湿度过大，发病重。施用带病残株而未经腐熟的粪肥等，发病也重。', '(1)农业防治：选用抗病、耐病品种。适期播种，避免过早播种，减少冬前病菌侵染麦苗的机会。合理密植，加强田间排灌水系统的建设，勤中耕除草，降低田间湿度。避免过量施用氮肥，平衡施用磷、钾肥，特别是重病田要适当增施钾肥，增强麦株的抗病能力。带有病残株的粪肥要充分腐熟后再施用。(2)种子处理：用种子重量0.2％的33％纹霉净可湿性粉剂拌种，或用种子重量0.1％的25％三唑醇或25％三唑酮可湿性粉剂拌种。(3)药剂防治：麦苗返青期选用33％纹霉净可湿性粉剂300倍液，或5％井冈霉素水剂500倍液，或50％甲基立枯灵300倍液喷雾，重点喷洒麦株下方的发病部位。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-05/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (19, 'disease_11', '小麦霜霉病', 'disease', 'type_1_crop_1', '小麦霜霉病的典型症状是植株黄化萎缩，剑叶和穗部畸形，但在小麦不同生育期和不同条件下症状表现有所不同。(1)苗期。病株叶色淡绿并有轻微条纹状花叶。(2)拔节后。病株显著矮化，叶色淡绿并有较明显的黄白色条纹或斑纹，叶片变厚，皱缩扭曲，重病株常在抽穗前死亡或不抽穗。(3)穗期。穗期症状的特点是形成各种“疯顶症”，例如病株剑叶特别宽、长、厚，叶面发皱并弯曲下垂，穗茎曲屈或弯成弓形；穗型大或小，花不实；有时基部小穗轴长，呈分枝穗状，下部小穗的颖壳长成绿色小叶片；也有的穗头呈龙头状扭曲。', '(1)感病期。苗期是病菌的主要侵染时期，最易感病期为露白至至叶期。(2)气候因素。小麦播种后，雨水多、气温偏低，有利于该病发生。(3)栽培因素。地势低洼、稻麦轮作田易发病。播种后灌水不当，造成田间长期积水，也有利于发病。整地质量差，耕作粗放，发病亦重。', '(1)种子处理：播种前，用种子重量0.2％～0.3％的25％甲霜灵可湿性粉剂拌种。(2)农业防治：发病重的地区或田块，应与非禾谷类作物进行1年以上轮作。做好农田基本建设工作，平整土地，修建完好的排灌水系统。雨后及时排水防止湿气滞留，促进麦株的迅速生长。病害发生后，要及早拔除并销毁病株。(3)药剂防治：病害常发地区，可在播种后喷洒药剂预防。药剂可选用0.1％硫酸铜溶液800倍液，或58％甲霜灵?锰锌可湿性粉剂1 000倍液，或72％霜脲锰锌可湿性粉剂600倍液，或69％安克?锰锌可湿性粉剂1 000倍液，或72.2％普力克水剂800倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-06/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (20, 'disease_12', '小麦雪霉叶枯病', 'disease', 'type_1_crop_1', '从萌芽期到成熟期麦株均可受害，产生芽腐、苗枯、基腐、鞘腐、叶枯和穗腐等多种症状。以成株叶枯和鞘腐特征最鲜明，为害也最重。(1)芽腐和芽枯：种子萌发后，发病的胚根、胚根鞘以及胚芽鞘腐烂变色。根数减少，长度变短。胚芽鞘上产生长条形或长圆形黑褐色病斑，严重者胚芽鞘全部黑褐色腐烂，表面生白色菌丝。(2)基腐和鞘腐：麦株拔节后发病部位渐上移，抽穗前，多数病株基部1～2节的叶鞘褐变腐烂，叶鞘枯死后颜色渐淡化，由深褐色变为枯黄色。抽穗后植株上部叶鞘开始发病。(3)叶枯：成株叶片上生成典型的椭圆形，半圆形大斑，病斑污绿色水浸状或污褐色有轮纹，表面散生稀薄的霉状物。成株叶片上病斑初为水浸状，后扩大为近圆形或椭圆形大斑，发生在叶片边缘的多为半圆形。病斑直径1～4cm，多数为2～3cm，边缘灰绿色，中部污褐色，由于浸润性地向周围扩展，常形成数层不甚明显的轮纹。病菌的分生孢子座由叶片气孔外露，形成大量分生孢子，致使病斑敷生砖红色霉状物。潮湿时病斑边缘具白色菌丝薄层，迎着阳光观察尤为明显。后期病叶多数枯死。(4)穗腐：多数病穗仅个别小穗或少数小穗发病，颖壳上生黑褐色水渍状斑块，上生红色霉，小穗轴褐变腐烂。', '在春小麦栽培区，小麦灌浆至乳熟期是该病流行盛期。(1)寄主抗性：品种间抗病性差异明显。小麦拔节孕穗期间受冻害，抗病性降低，易发病。(2)环境因素。西北地区4～5月份降雨多的年份，低温湿度大，有利该病发生。青藏高原麦区，7～8月份多雨，气温偏低，除为害叶片外，还可引起穗腐。潮湿多雨和比较冷凉的阴湿山区和平原灌区易发病。(3)栽培因素：①春灌过量，浇水次数过多，生育后期大水漫灌。②土质黏重、地下水位高、田间湿度大的田块、施用氮肥过量、施用时期过晚易发病。③播种过早、密度过大、田间郁闭发病重。', '小麦雪霉叶枯病的防治，在流行区应以药剂防治和栽培防治为主，尽量选用抗、耐病品种。无病区需避免使用带菌种子。(1)农业防治：①选用抗病品种和无病种子。适时播种，合理密植，防止田间密度过大。②施用充分腐熟有机肥，避免偏施、过施氮肥，适当控制追肥。冬灌充足，春季尽量不灌或少灌。早春耙耱保墒，严禁连续灌水和大水漫灌。(2)化学防治：历年秋苗发病重的地区或田块及低湿、高肥、密植有可能发病的田块，于越冬前和返青后即使喷80%多菌灵 1 000倍液，或70%甲基硫菌灵可湿性粉剂1 000倍液，或25%三唑酮可湿性粉剂1 000倍液，或50%苯菌灵可湿性粉剂1 500倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-07/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (21, 'disease_13', '小麦白秆病', 'disease', 'type_1_crop_1', '小麦被侵染后大多在拔节期或孕穗期开始出现症状。病斑首先出现在下部叶鞘和叶上，其次由茎秆而穗部。(1)叶片：叶部受害，多在2、3叶症状表现显著，先在叶鞘再到叶片呈。病斑条状，多从叶基沿叶脉平行向叶尖延伸，初呈水渍状绿色，后变为边缘黄褐色至紫褐色，中央为枯黄色的病斑。宽3～4mm，每叶有病斑2～3个。最后，数个条斑可愈合成更大的条斑，引起叶片干枯。 (2)茎秆：茎秆受害，从第3、4节间起和穗颈节间向上下延伸，然后至穗轴。同一植株的所有分蘖往往都表现症状。病秆出现2～3条宽2～4mm,长达50～60cm的长条斑，发病轻的条斑也长达18cm。这是小麦白秆病极突出而又极明显的症状。病斑边缘深褐色至紫褐色，中央枯黄色。叶鞘包被的茎秆部的条斑呈灰色或灰白色。数个条斑愈合后则呈典型的白秆症状。(3)穗部：穗部罹病轻时尚显绿色，但多数因秆部受害而使小穗和芒早期变成干黄，引起种子发育停止而成皱缩瘪粒。严重者，麦穗不结实，呈灰褐色干枯，芒变弯曲，后期穗似成熟但直立田间而不下垂。', '(1)寄主抗性：品种间抗病性有差异。(2)环境因素。小麦拔节期后的温湿度高低，是决定病害能否流行的1个重要因素，低温多雨，田间湿度大，有利于病害的发生。(3)栽培因素：种子带菌率高，发病重。', '(1)检疫：加强检疫，严格防止病种子调入无病区域。(2)农业防治：因地制宜。选用抗病品种。建立无病留种田，繁育无病良种。重病田或病残体多田块，要实行轮作，以减少菌源。(3)物理防治：将种子在28～32℃水中预浸4小时后，再于52～53℃水中浸7～10分钟。浸种时要不断搅匀种子，浸后迅速将麦种放入冷水中散热，晾干后播种。(4)药剂防治：①用种子总量的0.2%的25%三唑酮可湿性粉剂拌种，拌后闷种20天。或用种子重量的0.05%～0.1%的40%拌种双可湿性粉剂拌种，拌后闷种20天。或用种子总量的0.2%的25%多菌灵可湿性粉剂拌种，拌后闷种20天。或用1%石灰水浸种6昼夜，或3%石灰水浸3昼夜。浸种时，不要弄破石灰水表面的薄膜。②田间出现病株后，喷50%甲基硫菌灵可湿性粉剂800倍液，或50%苯菌灵可湿性粉剂1 500倍液。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (23, 'disease_15', '小麦蠕孢叶斑根腐病', 'disease', 'type_1_crop_1', '各生育期均可发病，症状多样。近地面叶片产生椭圆形病斑，淡褐色至黄褐色，病斑连成大块斑时，引起叶片早枯。茎节及茎基部发病多变黑褐色坏死腐烂，终致全株枯死。穗部发病穗颈、穗轴、小穗梗或颖壳均呈褐至黑色病变，籽粒不饱，胚部变黑，发芽率明显降低。', '(1)寄主抗性：品种间抗病性有差异。(2)环境因素。该病潜育期短，菌量积累速度快，气温18～25℃，相对湿度100%，功能叶片和麦穗就大量发病或流行成灾。(3)栽培因素：①春麦迟播或冬春早播，苗期易发病。②田间病残体多，种植过密，发病重。', '穗期叶斑和穗腐是防治的关键。(1)农业防治：①选用抗病耐病品种。冬小麦抗(耐)病品种有豫麦21号、郑州8915、西农88号、西农881、秦麦12号、西农1376等。②实行与非寄主作物轮作，减少田间菌源积累。选用无病种子，适时播种，合理密植，提高播种质量，培育壮苗，减轻苗期发病。④增施充分腐熟的有机肥，提高土壤肥力。⑤秋翻灭茬，小麦收获后及时深耕，加快土壤中病残体分解，减少田间病菌数量。(2)化学防治：①用种子重量0.2%～0.3%的50%福美双可湿性粉剂，或0.2%的33%纹霉净可湿性粉剂，或0.1%～0.3%的20%三唑酮EC，或50%退菌特可湿性粉剂100倍液浸种24～36小时，或70%代森锰锌可湿性粉剂100倍液浸种24～36小时。②初穗期喷50%福美双可湿性粉剂500倍液，或20%三唑酮乳油2 000倍液，或70%代森锰锌可湿性粉剂500倍液，或15%三唑醇可湿性粉剂2 000倍液，或25%敌力脱乳油2 000～4 000倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-13/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (24, 'disease_16', '小麦赤霉病', 'disease', 'type_1_crop_1', '从苗期到穗期均可发生，引起苗腐、茎基腐、秆腐和穗腐，以穗腐危害最大。湿度大时，病部均可见粉红色霉层。(1)苗腐。由种子带菌或土壤中的病菌侵染所致。先是芽变褐，然后根冠腐烂。轻者病苗黄瘦，重者幼苗死亡。手拔病株易自腐烂处拉断，断口褐色，带有粘性的腐烂组织。(2)茎基腐。幼苗出土至成熟均可发生，麦株基部组织受害后变褐腐烂，致全株枯死。(3)秆腐。多发生在穗下第一、二节，初在叶鞘上出现水渍状褪绿斑，后扩展为淡褐色至红褐色不规则形斑，病斑也可向茎内扩展。病情严重时，造成病部以上枯黄，有时不能抽穗或抽出枯黄穗。(4)穗腐。发生初期，在小穗和颖片上出现小的水渍状淡褐色病斑，后逐渐扩大至整个小穗，小穗枯黄。湿度大时，病斑处产生粉红色胶状霉层。后期其上密生小黑点，即子囊壳。后扩展至穗轴，病部枯褐，使被害部以上小穗，形成枯白穗。', '(1)高峰期。小麦齐穗后20天内最容易感病，以扬花期感病率最高。(2)气候因素。高温高湿病情发生迅速。开花灌浆阶段闷热、连续降雨、潮湿多雾的天气，发病重。(3)栽培因素。迟熟、不耐肥的品种，发病重。田间病残体数量大，带菌量高的地块，发病重。地势低洼，排水不良，土质粘重，偏施氮肥，田间潮湿郁闭，发病重。', '(1)农业防治：选用抗病、耐病品种。适时早播，播种，使扬花期避开雨期。合理施肥，增施底肥，氮磷配合，追肥早施、少施，提高植株抗病力。雨后及时排水，降低田间湿度。深耕灭茬，秸秆过腹还田或堆沤后施用。小麦播种前，清除田间农作物残体。(2)种子处理：用种子重量0.2％的50％多菌灵可湿性粉剂浸种30分钟，晾干后播种。(3)药剂防治：最佳施药时间是扬花期，应于扬花10％～50％时施药。药剂可选用25%戊唑醇乳油1 000倍液，6%叶菌唑水剂700倍液，或50％多菌灵可湿性粉剂800倍液，或60％防霉宝可湿性粉剂1 000倍液，或50％甲基硫菌灵可湿性粉剂1 000倍液，或50％多?霉威可湿性粉剂800～1 000倍液，或60％甲霉灵可湿性粉剂1 000倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-14/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (25, 'disease_17', '小麦颖枯病', 'disease', 'type_1_crop_1', '主要为害小麦未成熟穗部和茎秆，也为害叶片和叶鞘。(1)穗部。部分小穗颖壳上产生深褐色斑点，后扩展到整个颖壳，病斑枯白色，其上散生小黑点，即病原菌分生孢子器。发病严重时，籽粒不结实。小麦乳熟阶段之前穗部症状明显，容易辨认，当颖壳全部转黄后，病斑不明显，但病部仍可见小黑点。(2)茎节。茎节发病，病斑褐色，能侵入导管并将其堵塞，使节部畸变、扭曲，上部茎秆折断而死。(3)叶片。叶片染害，初生椭圆形淡褐色小斑，后扩大成不规则形病斑，中央灰白色，边缘有淡黄晕圈，其上密生小黑点，剑叶被害扭曲枯死。', '(1)感病期。颖枯病菌仅能侵染未成熟的麦穗，随着麦穗成熟度的增高，感病程度也逐渐减弱。(2)气候因素。高温多雨气候有利于病害的发生和蔓延。(3)栽培因素。病残体和种子带菌的有无和多少是影响病害流行的重要因素，10％的种子带菌即可为病害大流行提供足够的菌源。麦田长期连作、土质贫瘠、施用未腐熟的有机肥，均易发病。春麦播种晚，生育期延迟，可加重病害发生。', '(1)种子处理：播种前50％多福合剂500倍液浸种48小时。也可用种子重量0.2％的50％多菌灵可湿性粉剂，或40％拌种双可湿性粉剂，或25％三唑酮可湿性粉剂，或15％三唑醇可湿性粉剂拌种。(2)农业防治：选用抗病品种。实行2年以上轮作。选用无病种子。春麦适时早播，施足基肥，增施磷、钾肥。麦收后深耕灭茬，清除病残体，消灭自生麦苗。(3)药剂防治：重病区，可在小麦分蘖前期喷洒70％代森锰锌可湿性粉剂600倍液，或75％百菌清可湿性粉剂800倍液，或25％苯菌灵乳油800倍液，或25％敌力脱乳油2 000倍液。每隔15～20天喷1次，连续1～3次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-15/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (26, 'disease_18', '小麦散黑穗病', 'disease', 'type_1_crop_1', '散黑穗病主要为害穗部，小穗畸形，偶尔也为害在茎和叶片。病株比健康植株稍矮，抽穗略早，带菌植株抽穗前不表现症状。所有小穗的子房、种皮及颖片均成为黑色粉末，被侵害的子房和颖片发育成冬孢子堆。病穗外面包有一层灰色薄膜，在抽穗前内部就已完全变成黑粉，所以俗称黑疸、乌麦、灰包。在病穗抽穗时，薄膜破裂，孢子随风飞散，病穗只残留穗轴，在穗轴的节部还可以见到残余的黑粉。后期的病穗仅残留曲折的穗轴。', '(1)菌源。种子带菌率是影响病害发生的重要因素，种子带菌率高发病就重。(2)气候因素。小麦扬花期，空气湿度大、多雾或经常下小雨，则有利于病害发生，当年种子带菌率就高，第二年发病就重。但大雨易将孢子淋落土壤中，从而减少病菌的传播。风有利于病菌孢子的飞散和传播。', '(1)建立无病种子田，选用无病种子。小麦抽穗前，加强种子田的检查，及早拔除残留的病穗，以保证种子不受病菌侵染。(2)种子处理：种子处理是防治小麦散黑穗病的关键。①变温浸种：先将麦种放在冷水中浸4～6小时，然后将麦种放到49℃的热水中浸1分钟，最后放到54℃的热水中浸10分钟，取出后迅速放入冷水中，冷却后捞出晾干。此法杀菌效果好，但要求严格掌握规定的浸种温度和时间，温度偏低效果不好，温度偏高或时间过长会损坏种子发芽。②温汤浸种：先将麦种放在冷水中浸4小时，随即投入55℃的温水中浸24小时，取出晒干后播种。③药剂拌种：药剂可选用15％三唑酮可湿性粉剂，或15％三唑醇可湿性粉剂，或50％多菌灵可湿性粉剂，或40％拌种双可湿性粉剂，或40％多?福可湿性粉剂，或75％萎锈灵可湿性粉剂拌种。也可以使用种子重量0.1％的2%戊唑醇种衣剂拌种。此外，还可以用1％石灰水浸种，气温在35℃时浸1天，30℃时浸1～2天，25℃时浸2天，20℃时浸3天，水面结成的石灰膜不要弄破，浸过的麦种摊开晒干后播种或贮藏。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-16/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (27, 'disease_19', '小麦红矮病', 'disease', 'type_1_crop_1', '麦苗发病以后，先在叶尖和基部出现紫褐色的斑点或短条纹。第2年小麦返青拔节阶段，叶色深绿，色调深浅不匀，接着从叶尖叶缘逐渐褪色，整个叶片变成紫红色，显得僵硬宽厚，表面光滑，病株生育迟缓停滞，重病株的心叶卷缩成黄白色针状，不能抽出而枯死；发病稍轻者虽能拔节，但节间缩短，叶鞘松驰，上下叶鞘重叠在～起，叶片聚拢成丛生状，逐渐枯死；发病更轻的虽能抽穗，但不形成花器或花器残缺不全，不能结实，有能结实者亦籽实秕瘦。', '(1)寄主抗性：品种抗病性有差异。(2)栽培因素：条沙叶蝉喜干燥气候条件，山地干旱麦田及阳坡背风麦田虫口密度大，发病重。早播麦田比晚播者严重。', '(1)农业防治：①选用抗病品种是～项最为经济有效的防治措施。②山地要搞好农田基本建设，做好水土保持工作，提高施肥质量，增强小麦抗病力。③适时播种，严防早播，减少叶蝉传毒机会。④麦苗越冬期间作好镇压耙耱，使麦苗安全越冬并压埋清除带越冬卵的残茬，减少春季虫口。⑤精耕细作，及时清除田间杂草。麦收后及时深翻灭茬。(2)化学防治：重点是杀虫防病，消灭田间叶蝉，喷10%吡虫啉可湿性粉剂2 000～2 500倍液，或40%乐果乳油1 000倍液。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (28, 'disease_20', '小麦斑枯病', 'disease', 'type_1_crop_1', '主要为害叶片、叶鞘，也为害茎部和穗部。为害时期以拔节至抽穗期为甚。叶片发病由下向上扩展，感病叶片初在叶脉间出现淡绿至黄色纺锤形病斑，后扩展连片形成褐白色大斑，上生黑色小粒点(分生孢子器)。有时病斑为黄色条纹状，叶脉色泽黄绿色，形似黄矮病，但其条纹边缘为波浪形，并贯通全叶，严重时黄色部分变为枯白色，上生黑色小粒点，即病原菌分生孢子器。有时病叶仅叶尖发病干枯，有时病叶很快变黄，下垂。病斑有时从叶鞘向茎秆扩展，并侵染穗部颖壳，使之变得干枯。', '(1)气候因素。该病在低温、高湿条件易发病。当夜温达8℃以上并有雨露存在时，发病较快。(2)栽培因素：连作，施用带菌未腐熟肥料发病重；土壤瘠薄、施氮过多易发病；冬麦播种过早，病害有加重发生的可能。', '(1)选用抗(耐)病品种 如扬麦1号，甘麦23，牛米特，合作2号、3号、4号等，各地可因地制宜地选择使用。(2)加强农业防治措施 清除病残体，深耕灭茬。消除田间自生苗，减少越冬(夏)菌源。冬麦适时晚播。使用充分腐熟有机肥，增施磷、钾肥，采用平衡施肥技术。重病田应实行3年以上轮作。(3)药剂防治 ①种子处理用种子量0.15%的三唑酮或噻菌灵、0.03%的三唑醇(有效成分)拌种、40%多?福合剂按种子量的0.2%拌种。②重病区，在小麦分蘖前期和扬花期用70%甲基硫菌灵(甲基托布津)可湿性粉剂800～1 000倍液或50%多菌灵可湿性粉剂600～800倍液、25%苯菌灵乳油800倍液、75%百菌清可湿性粉剂500～600倍液、70%代森锰锌可湿性粉剂400～600倍液，隔10～15天一次，共喷2～3次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-23/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (29, 'disease_21', '小麦黄斑叶枯病', 'disease', 'type_1_crop_1', '主要为害叶片。病斑初为黄褐色小斑点，后扩展为椭圆形至纺锤形大斑，长可达30mm，病健交界不明显，病斑中央颜色较深，外围有黄晕，且具不明显的轮纹。后期病斑相互融合，引起叶片变黄干枯。', '病菌随病残体在土壤或粪肥中越冬。翌年小麦生长期子囊孢子侵染，发病后病部产生分生孢子，借风雨传播进行再侵染，致病害不断扩展。', '(1)种子处理：用种子重量0.2％的50％福美双可湿性粉剂，或12.5％的烯唑醇可湿性粉剂，或20％三唑酮乳油拌种。(2)农业防治：实行与非寄主作物轮作，减少田间菌源积累。选用无病种子，适时播种，合理密植，提高播种质量，培育壮苗。小麦收获后及时深耕，加快土壤中病残体分解，减少田间病原菌数量。(3)药剂防治：发病初期可喷洒20％三唑酮乳油2 000倍液，或15％三唑醇可湿性粉剂2 000倍液，或12.5％的烯唑醇可湿性粉剂2 000倍液，或50％福美双可湿性粉剂500倍液，或70％代森锰锌500倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-24/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (30, 'disease_22', '小麦链格孢叶枯病', 'disease', 'type_1_crop_1', '主要为害叶片。发病初期，叶上出现近圆形褪绿斑点，逐渐扩展为长卵形或椭圆形病斑，病斑褐色，最后发展成长条形或不规则形病斑，大小为(1～5 )mm×(3～23)mm。病斑中心呈黑褐色眼点状，周围灰褐色至深褐色，病斑沿叶脉伸展，形成较长的坏死线。病斑周围有一圈狭窄的亮黄色晕圈。后期2个或多个病斑可汇合成为大型病斑，导致叶枯。病斑表面可生灰黑色霉状物。', '一般在接近成熟期发病，寄主抗性下降，该病扩展很快。低洼潮湿或地下水位高的麦田发生重。', '(1)农业防治：种植抗病、耐病品种。增施腐熟有机肥。开沟排渍，降低田间湿度，可减轻病害发生。(2)化学防治：发病初期可喷施75％百菌清可湿性粉剂600倍液，或70％代森锰锌可湿性粉剂500倍液，或50％异菌脲可湿性粉剂1 500倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-25/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (31, 'disease_23', '小麦腥黑穗病', 'disease', 'type_1_crop_1', '病株一般较健株稍矮，分蘖增多，病穗较短，直立，颜色较健穗深，开始为灰绿色，以后变为灰白色，颖壳略向外张开，露出部分病粒。小麦受害后，大多是全穗麦粒变成病粒，少部分穗为部分麦粒变成病粒。病粒较健粒短肥，初为暗绿色，最后变成灰白色，外面包有一层灰褐色薄膜，里面充满黑粉，并有鱼腥味，故称腥黑穗病。', '小麦幼苗出土前，病菌最易侵入。因此，凡是影响小麦幼苗出土快慢的因素均影响病害发生。冬小麦迟播或春小麦早播，土温低，发病较重。土壤含水量在40％左右的土壤有利于病菌孢子萌发和侵染。播种覆土过深，麦苗不易出土，发病重。', '(1)种子处理：播种前进行药剂拌种，药剂可选用33.5%喹啉铜悬乳剂，或25％三唑酮可湿性粉剂，或15％三唑醇可湿性粉剂，或50％拌种双可湿性粉剂，或50％萎锈灵可湿性粉剂，用量为种子重量的0.2％。也可用种子重量0.1％的2%戊唑醇可湿性粉剂拌种，或用种子重量0.3％的50％克菌丹可湿性粉剂，或70％敌克松可湿性粉剂拌种。此外，用种子重量用1％生石灰水浸种也有较好的防病效果，气温在35℃时浸种1天，25℃时浸种2天，20℃浸种3天，15℃时浸种6天，石灰水表面的薄膜切勿弄破，浸好以后摊开晒干后播种或贮藏待用。(2)农业防治：选用抗病种品种。建立无病留种田，选留无病种子。适时播种，冬麦区不宜过迟播种，春麦区不宜过早播种，播种不宜过深。播种时施用硫酸铵、氯化铵等氮素速效化肥作种肥，可促使幼苗早出土，减少病菌侵染。有机肥要充分腐熟后才可施用。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-17/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (32, 'disease_24', '小麦黑颖病', 'disease', 'type_1_crop_1', '主要为害穗部，也能侵染叶片、穗轴、茎秆等部位。(1)穗部。初在颖片上部产生水渍状细条纹，继而发展成黄褐或深褐色条斑，后来逐渐形成斑块；严重时，蔓延到全颖片和麦芒，在麦芒上形成褐色斑，使芒变成黑褐色枯死。一般全穗及颖片上的条斑或斑块分布多不规则。发病种子皱缩或不饱满。发病轻的种子颜色变深。(2)叶片。初呈现水渍状小点，后沿叶脉间上、下扩展，变成半透明条斑，最后呈现黄褐色或相互连结成大块黄褐色油渍状发亮的枯死斑。湿度大时，病部组织溢出黄白色菌脓，后干缩成白色薄膜状或呈黄色小胶粒。(3)茎秆、穗轴。在茎秆和穗轴上产生褐色或黑褐色长条状病斑。湿度大时，以上病部均可产生黄色菌脓。', '(1)气候因素。气温20～30℃，夜间连续结露，又遇降雨次数多的高湿条件，病害容易流行。小麦苗期或返青期，若遇上低温和霜冻，可加重病情。(2)农业防治：种植感病品种是该病发生流行的主要原因。偏施氮肥，播种密度过大，通风不良，有利于病害发生。小麦重茬，整地不平，大水慢灌，有利于发病。', '(1)农业防治：选用抗病品种。建立无病种子田，选留无病种子。合理轮作倒茬，收获后清除病残体并深耕。(2)种子处理：先将种子在28～32℃水中预浸4小时后，再于53℃水中浸种7分钟。也可用种子重量0.3％的15％噻枯唑-018胶悬剂浸种12小时，阴干后播种。或用0.3％的15％叶枯宁胶悬剂溶液浸种12小时后播种。(3)药剂防治：田间发病初期，喷洒15％噻枯唑胶悬剂500倍液，或25％叶枯宁可湿性粉剂500倍液，或新植霉素4 000倍液，每隔7～10天喷1次，连续喷2～3次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-18/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (33, 'disease_25', '小麦梭条斑花叶病', 'disease', 'type_1_crop_1', '病苗新生的叶片出现褪绿或扭曲现象。病苗过冬后，先从心叶叶尖或下一片叶中部开始褪绿，扭曲，在嫩叶上出现淡绿色至橙黄色梭形斑，不久后变成黄色或淡绿色不连续的短条状病斑，并逐渐扩大成黄绿相间的斑驳，或不规则条纹。病株株型松散矮小，穗短小，有的穗轴弯曲，形成畸形穗，子粒不饱满。', '(1)气候因素。春季气温5～15℃持续时间越长，发病越重。(2)农业防治：品种间抗病性差异明显。土温15℃左右，土壤湿度较大，有利于发病。高于20℃或干旱，很少发病。播种早，发病重，播种迟发病轻。土壤缺肥，重茬种植，发病较重。', '选用抗病、耐病品种。与非寄主作物进行多年轮作。冬麦适时迟播，避开传毒介体的最适侵染时期。增施基肥，合理密植。发病后适当追肥，可减少死苗，减轻黄化程度，减少损失。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-19/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (34, 'disease_26', '小麦土传花叶病毒病', 'disease', 'type_1_crop_1', '未展开的心叶上出现褪绿的短线条状斑，随着病情发展，条斑彼此联合成不规则的淡黄色短线条状斑驳，整个叶片呈现出花叶症状。病株株形松散、矮缩、穗短而小，有缩脖现象，成熟期明显推迟，籽粒秕瘦。与小麦梭条斑花叶病十分相似，不易区分。通过电镜观察病毒粒体或血清学方法如酶联免疫吸附法检测可区分两病。', '秋季小麦播种后土温和湿度及第2年小麦返青期的气温是影响此病发生的关键因素。(1)寄主抗性：品种间抗病性、耐病性差异显著。(2)环境因素。春季气温高、回升快不利病害发生，长期阴雨、低温天气则能加重病害的发生。(3)栽培因素：①早播麦发病重，适当迟播能避开传毒介体的最适侵染期，有减轻病害的作用。②病害主要发生在砂质土壤内，而粘土、黄土则很少发病。基肥足，施肥及时，麦苗长势好的发病程度轻，反之则重。', '防治土传小麦花叶病应以选育抗(耐)病丰产品种为主，结合栽培管理的综合防治措施。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-20/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (35, 'disease_27', '小麦蜜穗病', 'disease', 'type_1_crop_1', '病株心叶卷缩并在高温条件下有胶状溢脓，病秆弯曲，往往不能抽穗，即使抽穗，穗也瘦小，部分或全部小穗花器受害不能正常结实而满含细菌菌脓呈蜂蜜状或鸡蛋黄状的粘稠胶液透过颖片缝隙外溢欲滴，麦子成熟后，凝结硬化为亮黄色胶块小粒；整个麦穗凝结成胶质细棒状.', '该病是伴随小麦线虫而产生的细菌病。', '重点防治小麦线虫病，小麦线虫病防住以后，即无本病发生。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-27/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (36, 'disease_28', '小麦麦角病', 'disease', 'type_1_crop_1', '花器受浸染后出现黄色蜜状粘液(分生孢子和含糖液)，其后子房逐渐膨大变硬，形成紫黑色长角状菌核，突出穗外，即为麦角(菌核)。麦角长1～3cm或更长，直径0.8cm。', '病菌以菌核在土壤中或混杂于种子间存活传播。春季菌核萌发形成子实体，产生子囊孢子，借风雨、昆虫传播到寄主花器，造成为害。病部产生粘液内有大量分生孢子，再由雨水、昆虫或接触性传播为害。春季地面湿润，菌核易于萌发，小麦花期长，开花期多雨有利于病菌传播和浸染。', '①选择无病地留种，或汰除种子中菌核。②深耕将菌核埋入深土层，清除田间杂草和自生麦苗，减少菌源。③重病地块与非禾本科作物轮作1年以上。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (37, 'disease_29', '小麦灰霉病', 'disease', 'type_1_crop_1', '该病从苗期到成熟期均可发病。叶片染病 初在基部叶片上现不规则水浸斑，拔节后叶尖先变黄，且下部叶片先发病，后逐渐向上蔓延。病部现水渍状斑，褪绿变黄，后形成褐色小斑，最后变为黑褐色枯死，其上产生白色霉状物，即病菌孢子梗和分子孢子。春季长期低温多雨条件下，穗部发病，颖壳变褐，生长后期病部可长出灰色霉层。', '(1)气候因素。春季潮湿环境或连续阴雨季节易发病。(2)品种间抗病差异明显，阿勃波、川麦20等发病重。', '(1)选用抗灰霉病的品种。(2)加强田间管量，提高抗病力。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-29/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (38, 'disease_30', '小麦细菌性条斑病', 'disease', 'type_1_crop_1', '主要为害叶片，严重时也可为害叶鞘、茎秆、颖片和籽粒。发病初期，病部出现针尖大小的暗绿色小斑，后扩展为水浸状的半透明条斑，最后颜色变为深褐色。病部常出现露珠状的菌脓。', '(1)气候因素。在新疆5～7月大的暴风雨次数多，造成叶片产生大量伤口，致细菌多次侵染，易流行成灾。(2)农业防治：植株密集，枝叶繁茂，通风透光不良则，发病重。', '(1)种子处理：用45℃水恒温浸种3小时，或用1％生石灰水在30℃下浸种24小时，晾干后播种。也可用种子重量0.2％的40％拌种双可湿性粉剂拌种。(2)农业防治：选用抗病、耐病品种。春麦要种植生长期适中或偏长的品种。适时播种，冬麦不宜过早，采用配方施肥技术。(3)药剂防治：发病前或发病初期可用72％农用硫酸链霉素可溶性粉剂3 000倍液，或70％敌克松可湿性粉剂2 000倍液，或20%噻森铜乳油500倍液，每隔7～10天喷一次，共喷2～3次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-30/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (39, 'disease_31', '小麦黄矮病', 'disease', 'type_1_crop_1', '病株叶片尖端出现鲜明的黄色，逐渐向下扩展，呈现与叶脉平行但不受叶脉限制的黄绿相间条纹。病株有不同程度的矮化。叶色的变化随品种特性不同而不同，有的为黄色至橙黄色，有的为红色至紫红色。矮化程度与感病的早迟有关，一般苗期感病，植株明显矮化，分蘖少，长势差，后期不能抽穗或仅抽少量秕穗。中期发病植株较矮，新叶以下第一或第二叶变黄，能抽穗但穗小，结实率低。后期感病仅剑叶变黄，植株无明显矮化，能正常抽穗，但穗粒少，秕粒多。', '(1)气候因素。小麦拔节孕穗期遇低温，抗性降低易发生黄矮病。(2)农业防治：凡是冬前蚜虫基数大、早春虫口密度高的田块，发病重。冬麦播种早、发病重。阳坡地、干旱、土壤贫瘠、管理粗放，发病重。自生苗等病毒寄主量大，麦蚜虫口密度大易造成黄矮病大流行。', '及时防治蚜虫是预防黄矮病流行的有效措施。因地制宜地选用抗病、耐病品种。冬麦区适期迟播，春麦区适当早播，确定合理密度，加强肥水管理，提高植株抗病力。加强栽培管理，及时铲除田间及附近杂草。冬前镇压、冬灌、返青后耙耱都可有效减少蚜虫数量，减轻发病。有条件的地区，可以采用冬小麦地膜覆盖栽培。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-31/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (40, 'disease_32', '小麦蓝矮病毒病', 'disease', 'type_1_crop_1', '小麦冬前一般不表现症状，多在春季麦田返青后的拔节期，能见到明显症状。病株明显矮缩、畸形、节间越往上越矮缩，呈套叠状，造成叶片呈轮生状，基部叶片增生、变厚、呈暗绿色至绿蓝色，叶片挺直光滑，心叶多卷曲变黄后坏死。成株期，上部叶片形成黄色不规则的宽条带状，多不能正常拔节或抽穗，即使能抽穗，则穗呈塔状退化，穗短小，向上尖削。染病重的生长停滞，显症后1个月即枯死，根毛明显减少。', '(1)世代。一年发生3～4代。(2)越冬及虫源。秋季，条沙叶蝉从秋作物及杂草上迁飞至麦田传毒。深秋初冬叶蝉以卵在小麦或杂草上越冬，翌春孵化后再行获毒，然后开始传毒。 (3)发生因素。干燥气候条件，山地干旱麦田及阳坡背风麦田虫口密度大，发病重(4)品种抗病性有差异。', '(1)尽快组织力量选育抗蓝矮病的抗病小麦新品种。原来地方品种均感病。近年引进的钱交麦、2711则表现高度抗病。(2)其他方法参见小麦红矮病。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (41, 'disease_33', '小麦丛矮病', 'disease', 'type_1_crop_1', '染病植株上部叶片有黄绿相间条纹，分蘖增多，植株矮缩，呈丛矮状。冬小麦播后20天即可显症，最初症状心叶有黄白色相间断续的虚线条，后发展为不均匀黄绿条纹，分蘖明显增多。冬前染病株大部分不能越冬而死亡，轻病株返青后分蘖继续增多，生长细弱，叶部仍有黄绿相间条纹，病株矮化。一般不能拔节和抽穗。冬前未显症和早春感病的植株在返青期和拔节期陆续显症，心叶有条纹，与冬前显症病株比，叶色较浓绿，茎秆稍粗壮，拔节后染病植株只有上部叶片显条纹，能抽穗的籽粒秕瘦。', '(1)气候因素。夏秋多雨、冬暖春寒年份发病重。1～2龄若虫易得毒，而成虫传毒能力最强。最短获毒期12小时，最短传毒时间20分钟。获毒率及传毒率随吸食时间延长而提高。一旦获毒可终生带毒，但不经卵传递。病毒随带毒若虫且在其体内越冬。冬麦区灰飞虱秋季从带病毒的越夏寄主上大量迁飞至麦田为害，造成早播秋苗发病。越冬带毒若虫在杂草根际或土缝中越冬，是翌年毒源，次年迁回麦苗为害。小麦成熟后，灰飞虱迁飞至自生麦苗、水稻等禾本科植物上越夏。小麦、大麦等是病毒主要越冬寄主。套作麦田有利灰飞虱迁飞繁殖，发病重；冬麦早 病重；邻近草坡、杂草丛生麦田病重；夏秋多雨、冬暖春寒年份发病重。', '(1)清除杂草、消灭毒源。(2)小麦平作，合理安排套作，避免与禾本科植物套作。(3)精耕细作、消灭灰飞虱生存环境，压低毒源、虫源。适期连片中，避免早。麦田冬灌水保苗，减少灰飞虱越冬。小麦返青期早施肥水提高成穗率。(4)药剂防治 用种子量0.3%的60%甲拌磷拌种堆闷12小时，防效显著。出苗后喷药保护，包括田边杂草也要喷洒，压低虫源，可选用40%氧化乐果乳油、50%马拉硫磷乳油或50%对硫磷乳油1000～1500倍液，也可用25%扑虱灵(噻嗪酮优乐得)可湿性粉剂750～1000倍液。小麦返青盛期也要及时防治灰飞虱，压低虫源。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (42, 'disease_34', '小麦卷曲病', 'disease', 'type_1_crop_1', '苗期染病开始在第三、四叶片上产生浅绿色圆形至长圆形病斑，逐渐扩展为不规则形病变，心叶卷曲干枯，严重的幼苗扭曲畸形后枯死。拔节期、抽穗期染病叶片、叶鞘上产生淡黄色病斑，上生小黑点或漆黑色斑痣，旗叶紧抱的不能抽穗呈“一柱香”形，初期缠绕灰白色菌丝，后期部分小穗或全部呈黑色革质状，即菌核型分生孢子堆。', '病菌以菌丝体在病残体上或以分生孢子附着在种子上越冬或越夏，通过风雨传播。为害麦穗者，主要通过小麦粒线虫传播，病菌常附着在虫瘿里的线虫体外，经由线虫携带进入小麦体内。因此穗上有卷曲者，通常也有线虫为害，小麦卷曲病和线虫病呈混生状态。但在田间也常见到同一病株有线虫病而无卷曲病，有的卷曲病株而无线虫为害。', '(1)认真防治小麦线虫病。(2)与非小麦作物进行轮作。(3)选用无病种子。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-34/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (43, 'disease_35', '小麦粒线虫病', 'disease', 'type_1_crop_1', '小麦受害后,从苗期至成熟期均可表现症状，但以后期最为明显。受害幼苗叶片皱缩、扭曲，叶色浅而肥嫩，叶尖常被包于叶鞘内，严重的萎缩枯死。在抽穗前，病株茎、叶膨大而弯曲。病穗表现短小，颖片张开，子粒部分全部变为虫瘿。虫瘿比健粒短而粗，近球形，初为油绿色，后期变为黄褐色至黑褐色，顶部有小钩。不易压碎。剖开虫瘿，内含白色丝状的线虫。', '虫瘿内的幼虫抗不良环境能力极强，混于种子中的虫瘿是传播的主要来源，收获时落入土壤中的虫瘿不易存活。当小麦种子和虫瘿同时播入土中后，虫瘿吸水变软，幼虫钻出虫瘿，当幼苗出土后，幼虫用吻针刺破小麦，侵入组织，随幼苗生长，向上爬行为害叶片、幼穗，在种子子房内营寄生生活。冬麦秋播后，雨水较多有利于线虫侵染而发病较重。', '(1)加强植物检疫 通过植物检疫，防止病原线虫的传人传出。(2)选种。一是利用麦粒与虫瘿大小的差异，机械淘汰种子中的虫瘿；二是利用麦粒与虫瘿的比重差异，采用20％盐水或26％硫酸按液，或30％～40％胶泥水漂选出虫瘿，用清水洗净种子，然后晾干播种。同时将虫瘿集中烧毁。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmb-35/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (44, 'disease_36', '小麦禾谷胞囊线虫病', 'disease', 'type_1_crop_1', '受害小麦幼苗矮黄，根系短分叉，后期根系被寄生呈瘤状，露出白亮至暗褐色粉粒状胞囊，为该病的典型特征。胞囊老熟易脱落，胞囊仅在成虫期出现，故生产上常查不见胞囊而误诊。线虫为害后，病根常受次生性土壤真菌如立枯丝核菌等为害，致使根系腐烂。或与线虫共同为害，加重受害程度，致地上部矮小，发黄，似缺少营养或缺水状，应注意区别。 [侵染]年生一代。土温9℃以上时有利于线虫孵化和侵入寄主。以2龄幼虫侵入幼嫩根尖，头部插入后在维管束附近定居取食，刺激周围细胞成为巨形细胞，逐渐发育变为豆荚型，蜕皮形成长颈瓶形3龄幼虫，4龄为葫芦形，然后成为柠檬形成虫。雄成虫由定居型变为活动型，出根与雌虫交配后死亡，雌虫体内充满卵及胚胎卵变为褐色胞囊，然后死亡，使被侵染根部鼓起。卵在土中可保持1年或数年的活性。胞囊失去生命后脱落入土中越冬，可借水流、风，农机具等传播。', '春麦被侵入两个月可出现胞囊。秋麦则秋季侵入，以各发育虫态在根内越冬，翌年春季气温回升为害，于4-5月显露胞囊。也可孵化再次侵入寄主，造成苗期严重感染一般春麦较秋麦重，春麦早播较晚播重。冬麦晚播发病轻。连作麦田发病重；缺肥、干旱地较重；沙壤土较粘土重。苗期侵染对产量影响较大。', '(1)加强植物检疫，严禁随意调运种子，防止此病扩散蔓延。(2)因地制宜选用抗(耐)病品种。(3)改善耕作制度。与其他麦类及禾谷类作物隔年或3年轮作；春麦区适当晚播。(4)加强田间管理。要平衡施肥，提高植株抵抗力；施用土壤添加剂，控制根际微生态环境，使其不利于线虫生长和寄生。(5)种子处理。清水选 麦种倒入清水中迅速搅动，虫瘿上浮却捞出，可汰除95%虫瘿。整个操作争取在10分钟内完成，防止虫瘿吸水下沉。盐水选 用20%盐水汰除虫瘿较清水彻底，但事后要用清水洗种子。硫酸铵液选法 用26%硫酸铵液汰洗即可。药剂处理 用50%甲基对硫磷或甲基异柳磷，按种子量0.2%拌闷种子。每100kg种子用药200g对水20kg，混匀后，堆50cm厚，闷种4小时，即可播种。(6)药剂防治。每亩施用3%万强颗粒剂200g，也可用24%万强水剂600倍液在小麦返青时喷雾。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (45, 'disease_37', '小麦管蓟马', 'disease', 'type_2_crop_1', '成、若虫为害花器，重者造成白穗。灌浆乳熟时吸食籽拉的浆液，致籽粒空瘪。此外还为害小穗的护颖和外颖。受害颖片皱缩或枯萎，发黄或呈黑褐色，易遭病菌侵染，诱发霉烂或腐败。', '(1)世代：一年发生1代。(2)越冬及虫源：7月上旬冬麦收获时，部分若虫掉到地上，就此爬至土缝中或集中在麦捆或麦堆下，大部分爬至麦茬丛中或叶稍里，有的随麦捆运到麦场越夏或越冬。(3)发生因素：新垦麦地、春小麦及晚熟品种受害重。', '(1)农业防治：①合理轮作倒茬。②适时早播，躲过为害盛期。③秋季或麦收后及时进行深耕，清除麦场四周杂草，破坏其越冬场所，可压低越冬虫口基数。(2)药剂防治：①小麦孕穗期，大批蓟马成虫飞到麦田产卵时，及时喷洒20%丁硫克百威乳油，或10%吡虫啉可湿性粉剂，或1.8%爱比菌素乳油，或10%除尽乳油 2 000倍液，喷对好的药液1 125kg/hm2。②小麦扬花期可用2.5%保得乳油 2 500倍液，或10%大功臣可湿性粉剂，或44%多虫清乳油 450ml/hm2，对水900kg喷雾，防治初孵若虫。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-05/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (46, 'disease_38', '条沙叶蝉', 'disease', 'type_2_crop_1', '以成虫和若虫刺吸茎叶，受害幼苗生长受到抑制，并传播病毒病。', '(1)世代。长江流域一年发生5代北方冬麦区一年发生3～4代，春麦区3代(2)越冬及虫源。长江流域以成、若虫在麦田越冬北方麦区以卵在麦茬叶鞘内壁或枯枝落叶上越冬(3)发生特点。北方地区越冬卵在3月初开始孵化，4月在间田可见越冬代成虫4～5月份成、若虫混发，集中在麦田为害，后期向杂草滩或秋作物上迁移秋季麦苗出土后，成虫又迁回麦田为害并传播病毒病(4)发生因素。①气候因素以小麦为主1年～熟制地区，谷子、糜、黍种植面积大的地区或丘陵区适合该虫发生，早播麦田或向阳温暖地块虫口密度大②天敌主要有叶蝉缨小蜂、赤眼蜂', '(1)农业防治：①通过合理密植，增施基肥、种肥，合理灌溉，改变麦田小气候，增强小麦长势，抑制该虫发生②合理规划，实行农作物大区种植，科学安排禾谷类早秋谷糜地、小麦地块，及时清除禾本科杂草，控制越冬基地，减少虫源③对小播小麦田、向阳小气候优越的麦田，用直径33cm的捕虫网捕捉成、若虫。(2)药剂防治。喷撒1.5%乐果粉或1%对硫磷粉剂，或4%敌马粉剂，或4.5%甲敌粉剂，用药22.5～30kg/hm2。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (47, 'disease_39', '西北麦蝽', 'disease', 'type_2_crop_1', '成、若虫刺吸寄主叶片汁液，受害麦苗叶片出现白斑或枯心，变黄枯萎，有的卷曲严重受害时，麦叶如被牲畜吃去尖端一般了甚至成片死亡后期被害，可造成白穗、籽粒不饱满，减产30%～80%', '(1)世代。甘肃一年发生1代，宁夏2～3代(2)越冬及虫源：以成虫贺若虫在落叶、土块、墙缝和芨芨草基部越冬(3)发生因素：一般生长茂盛的麦田虫口密度大，阳坡地、麦茬地为害重', '(1)农业防治。越冬虫恢复活动以前，清除麦田附近的芨芨草深埋或烧毁，以减少虫源。 (2)药剂防治。①必要时，用2.5%敌百虫粉1kg，拌细砂20kg，撒入草丛②成虫为害高峰期，向麦苗或芨芨草上喷撒2.5%敌百虫粉，用22.5～30kg/hm210天后再喷1次，消灭初孵若虫③必要时可喷洒2.5%保得乳油 2 500倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-07/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (48, 'disease_40', '斑须蝽', 'disease', 'type_2_crop_1', '成虫和若虫刺吸嫩叶、嫩茎及果、穗汁液，造成落花。茎叶被害后，出现黄褐色斑点，严重时叶片卷曲，嫩茎凋萎。', '(1)世代。每年发生 2 代。(2)越冬。以成虫在杂草、枯枝落叶、植物根际、树皮下越冬。(3)时期。4 月初开始活动，4 月中旬交尾产卵，4 月底 5 月初幼虫孵化，第 1 代成虫 6月初羽化，6月中旬为产卵盛期。', '(1)农业防治：①小麦与油菜间作、玉米、棉花、大豆、花生等作物插花条带种植，每一条带10～15m，可优化生态环境，创造有利于天敌生存繁衍的条件，提高天敌对斑须蝽的自然控制能力②第1代成虫为害盛期，及时打顶、抹杈，减少其为害场所，从而降低虫口基数③结合田间管理，人工捕捉成虫，抹杀卵块，消灭未分散的低龄若虫，可减轻田间受害程度(2)物理防治。利用成虫趋光性，诱杀成虫在成虫发生期，特别是发生盛期，用黑光灯诱杀，灯下放一水盆，及时捞虫。(3)药剂防治。低龄若虫盛发期喷5%高效大功臣可湿性粉剂 1 000～1 500倍液，或10%氯氰菊酯乳油 2 000～3 000倍液，或2.5%敌杀死乳油 2 000～3 000倍液，或20%甲氰菊酯乳油 2 000倍液，若在成虫产卵前连片防治效果更好。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-08/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (49, 'disease_41', '麦根蝽', 'disease', 'type_2_crop_1', '成、若虫以口针刺吸寄主根部的营养为害小麦时，4月中下旬开始显症，5月上中旬叶黄、秆枯、炸芒为害高粱、玉米时，苗期出现苗青、株矮及青枯不结穗', '(1)发生世代。山东2年发生1代，个别3年1代，在土中交配，把卵散产在20～30cm潮湿土层里，产卵量数粒至百余粒(2)越冬及虫源。以成虫或若虫在土中30～60cm深处越冬。(3)发生因素。干旱年份发生为害重', '(1)农业防治。实行小麦与非禾本科作物轮作(2)药剂防治。雨后或灌水后于中午喷撒有机磷农药有效', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (50, 'disease_42', '麦圆蜘蛛', 'disease', 'type_2_crop_1', '以成、若虫吸食麦叶汁液，受害叶上出现细小白点，后麦叶变黄，麦株生育不良，植株矮小，严重的全株干枯 ', '(1)世代：一年发生2～3代，即春季繁殖1代，秋季1～2代，完成1个世代46～80天。(2)越冬及虫源：以成虫或卵及若虫越冬冬季几乎不休眠，耐寒力强。(3)发生因素。生长发育适温8～15℃，相对湿度高于70%，水浇地易发生气温超过20℃成虫大量死亡', '(1)农业防治：因地制宜进行轮作倒茬，麦收后及时浅耕灭茬；冬春进行灌溉，可破坏其适生环境，减轻为害。(2)药剂防治：选用6.78%爱诺螨清300ml/hm2加水750L，或40%氧化乐果1 000倍液，或0.3%阿维菌素乳油 1 500～2 000倍液，或30%蚜青灵1 000倍液，或20%复方浏阳霉素1 000倍液喷雾防治，可在防治麦蜘蛛的同时，兼治麦蚜等害虫使用机动弥雾机喷雾防效更佳', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-10/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (51, 'disease_43', '麦长腿蜘蛛', 'disease', 'type_2_crop_1', '以成、若虫吸食麦叶汁液，受害叶上出现细小白点，后麦叶变黄，麦株生育不良，植株矮小，严重的全株干枯。', '(1)世代。西藏一年发生1～2代，山西北部冬麦区一年发生2代，新疆3代，黄淮海地区3～4代(2)越冬及虫源：以成虫和卵在麦田越冬。(3)发生因素。主要发生在旱地麦田里对湿度敏感，遇露水较大或降小于，即躲于麦丛或土缝内。', '(1)农业防治。因地制宜进行轮作倒茬，麦收后及时浅耕灭茬；冬春进行灌溉，可破坏其适生环境，减轻为害。(2)药剂防治。选用6.78%爱诺螨清300ml/hm2加水750L，或40%氧化乐果1 000倍液，或0.3%阿维菌素乳油 1 500～2 000倍液，或30%蚜青灵1 000倍液，或20%复方浏阳霉素1 000倍液喷雾防治，可在防治麦蜘蛛的同时，兼治麦蚜等害虫使用机动弥雾机喷雾防效更佳', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (52, 'disease_44', '黏虫', 'disease', 'type_2_crop_1', '初孵幼虫有群集性，1、2龄幼虫多在麦株基部叶背或分蘖叶背光处为害，3龄后食量大增，5～6龄进入暴食阶段，食光叶片或把穗头咬断，其食量占整个幼虫期90%左右。', '(1)世代。一年发生世代数全国各地不～，东北、内蒙古一年发生2～3代，华北中南部3～4代，江苏淮河流域4～5代，长江流域5～6代，华南6～8代。海拔1 000m左右高原1年发生3代，海拔2 000m左右高原则发生2代，各省(区)由于地势不同，世代数亦有一些变化。(2)越冬及虫源。黏虫属迁飞性害虫，其越冬分界线在北纬33°～带，在33°以北地区任何虫态均不能越冬。在江西、浙江～带，以幼虫和蛹在稻桩、田埂杂草、绿肥田、麦田表土下等处越冬。在广东、福建南部终年繁殖，无越冬现象。北方春季出现的在大量成虫系由南方迁飞所至。(3)发生因素。①气候因素。气候因素对黏虫的发生量和发生期影响很大，其中温度和湿度关系尤为密切。春夏向北迁飞扩散时，主要受气流冷暖交锋的影响而造成黏虫的为害程度不同。总的来说，黏虫不耐0℃以下的低温和35℃以上的高温，各虫态适宜的温度在10～25℃之间，相对湿度在85%以上。黏虫是～种喜好潮湿而怕高温和干旱的害虫，高温低湿不利于成虫产卵、发育。但雨水多，湿度过大，也可控制黏虫发生。 ②栽培因素。凡密植、多雨、灌溉条件好、生长茂盛的水稻、小麦、谷子，或荒草多、大的玉米、高粱地，黏虫发生量就多。小麦、玉米套种，有利于黏虫的转移为害，黏虫发生较重。 [预测预报]黏虫是间歇性猖獗的害虫，发生时还有“暴发性”的特点，因此做好预测预报，掌握黏虫田间动态是主动消灭黏虫为害的重要措施。可通过调查成虫、卵、幼虫来预测当年的发生程度。', '(1)农业防治：①冬季和早春结合积肥，彻底铲除田埂、田边、沟边、塘边、地边的杂草，消灭部分在杂草中越冬的黏虫，减少虫源。②合理布局，实行同品种、同生产期的水稻连片栽种，避免不同品种的“插花”栽培。③合理用肥，施足基肥，及时追肥，避免偏施氮肥，防止贪青迟熟。④科学管水，浅水勤灌，避免深水漫灌，长期积水，适时晒田，可起到抑制黏虫为害、增加产量的作用。(2)生物防治：根据黏虫幼虫具有惊落假死性，在稻田中饲养鸭子可有效地控制黏虫的发生为害。(3)物理防治：①采用多佳频振式杀虫灯或黑光灯诱杀成虫。②根据成虫产卵喜产于枯黄老叶的特性，在田间每hm2设置150把草把，草把可稍大，适当高出作物，5天左右换草把1次，并集中烧毁，即可灭杀虫卵。(4)药剂防治：①根据黏虫成虫具有嗜食花蜜、糖类及甜酸气味的发酵水浆等特性，采用毒液诱杀成虫，其药液配比为糖∶酒∶醋∶水=1∶1∶3∶10，加总量10%的杀虫丹，可以作盆诱或把毒液喷在草把上诱集成虫。②用20%速毙50ml或600～1 000倍液或24%百虫光40～60ml，对水40～60kg，进行均匀喷雾，最后～次用药在收割水稻前10天进行。③或用25%本能1 500倍液，或40%九条虫1 500～2 000倍液，或20%凯杀1200～1600倍液，或25%杀虫双200～250倍液，或20%氰戊菊酯1 000～1 500倍液，或33%水灭氯乳油 1200倍液，或25%快杀灵乳油 800倍液，或90%晶体敌百虫1 000倍液，或20%除虫脲1 200倍液，或48%毒死蜱乳油 500倍液，或40%灭虫清乳油 2 000倍液，或50%辛硫磷乳油 1 000倍液，或20%抑食肼可湿性粉剂 1 000倍液，或0.3%苦参碱AS 100倍液，或2.5%氯氟氰菊酯乳油 1 000倍液，或25%杀虫双500倍液，或2.5%溴氰菊酯乳油 4 000倍液均匀喷雾，收割水稻前15天停药。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (53, 'disease_45', '秀夜蛾', 'disease', 'type_2_crop_1', '幼虫3龄前蛀茎为害，4龄后从麦秆的地下部咬烂入土，并吐丝与其分辩缀成薄茧，栖息在薄茧内继续为害附近麦株，致小麦呈现枯心或全株死亡，造成缺苗断垄。', '(1)发生世代。北方春麦区一年发生1代(2)越冬及虫源。以卵越冬', '(1)农业防治。①合理轮作，尤其是水旱轮作，可显著减少秀夜蛾的发生②深翻土地除茬灭卵，集中烧毁可减少虫源翻地深度超过15cm初孵幼虫大部分不能出土③小麦三叶期浇水，这时正值初孵幼虫为害盛期，浇水后可减轻为害。(2)物理防治。成虫盛发期，大面积设置黑光灯诱杀成虫在产卵之前。(3)药剂防治。发生严重地区或田块，随播种施4%辛硫磷GR 30～45kg/hm2，对初孵幼虫防效80%以上幼虫期可用80%晶体敌百虫1 000倍液灌根。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (54, 'disease_46', '麦穗夜蛾', 'disease', 'type_2_crop_1', '麦穗夜蛾以幼虫为害。初孵幼虫在麦穗的花器及子房内为害，2龄后在籽粒内取食，4龄后将小麦旗叶吐丝缀连卷成筒状，潜伏其中，日落后出来为害麦粒，仅残留种胚，致使小麦不能正常生长和结实。', '麦穗夜蛾每年发生～代，以老熟幼虫在田间和芨芨草墩下越冬。4月越冬幼虫开始活动，4月下至5月中旬幼虫在土表作茧化蛹。蛹期1．5～2个月，羽化盛期在6月中旬至7月上旬，成虫日伏夜出，取食小麦花粉。卵多产在小麦第一小颖内侧或子房上，一般卵以块状产下，用胶质物粘合在～起，每块有卵7～30余粒，卵期13天左右。幼虫7龄，初孵幼虫取食花器与子房，个别有为害颖壳内壁表皮层，一般l～2头或8～9头群集在-粒麦种为害，2龄后即在籽粒内食害， 4龄进入暴食期，将小麦旗叶吐丝缀连成筒状，白日潜伏其中，日落后出来取食麦粒，仅残留种胚，天亮前停食，每头幼虫可食害小麦30粒左右，幼虫为害期平均 2～2．5个月。小麦收获后，幼虫转移到土表层内，并可在麦捆下继续取食，9月中旬后陆续在土中作土室越冬。', '(1)黑光灯诱杀：在成虫产卵前用黑光灯诱杀(可结合其它害虫同时进行)。 (2)化学防治 用80％敌敌畏乳油，或90％晶体敌百虫1-000～2000倍液，或 50％辛硫磷乳油1000倍液，每亩用药液75公斤。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (55, 'disease_47', '小麦吸浆虫', 'disease', 'type_2_crop_1', '幼虫以口器锉破麦粒果皮，吸食麦粒浆液，出现瘪粒，严重时造成绝收。', '(1)世代。每年发生1代或多年完成1代。(2)越冬。以末龄幼虫在土壤中结圆茧越夏或越冬。(3)气候。吸浆虫发生与雨水、湿度关系密切，黄淮地区4月上旬降水量在20mm以上，发生量大。(4)栽培。麦红吸浆虫在20～25℃及20％～28％土壤含水量最适于发生。当土壤含水量达36％时，其死亡率达40％～45％。麦穗颖壳坚硬、扣和紧、种皮厚、籽粒灌浆迅速的品种受害轻。抽穗整齐，抽穗期与吸浆虫成虫发生盛期错开的品种，成虫产卵少或不产卵，可逃避其为害。天敌。主要天敌有宽腹姬小蜂、尖腹黑蜂、蚂蚁、蜘蛛等。', '(1)农业防治。选用抗虫小麦品种，调整作物布局改善农田环境，推广小麦－大豆－小麦或小麦－棉花～体化种植模式，优化组装综防技术。(2)药剂防治。播种前用50％辛硫磷乳油200毫升/亩，对水15千克，喷在20千克干土上，拌匀制成毒土撒施在地表，耙入或翻入土表层有效。南方麦区于3月下旬至4月上旬冬小麦拔节期；北方春麦区于5月进入拔节后，土内幼虫破茧上升土表时用50％辛硫磷乳油150毫升/亩，按上法制成毒土，均匀撒在地表后，进行锄地，把毒土混入表土层中。也可在小麦抽穗前3～5天，于露水落干后撒毒土，毒土制法同上，可有效地灭蛹和刚羽化在表土活动的成虫。小麦抽穗开花期喷撒甲敌粉或乙敌粉用2～3千克/亩，必要时喷洒40％乐果乳油，或50％辛硫磷乳油，或80％敌敌畏乳油2 000倍液，或2.5％溴氰菊酯乳油，或20％杀灭菊酯乳油4 000倍液，或36％克螨蝇乳油1 000倍液。水源不方便的地区或坡地，用80％敌敌畏乳油100毫升/亩，对水1～2千克，喷拌在20千克细土上制成毒土撒施在麦田中也有较好防效。该虫卵期较长，发生重的可连续防治2次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-15/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (56, 'disease_48', '麦秆蝇', 'disease', 'type_2_crop_1', '幼虫为害麦茎基部，造成心叶青枯，后黄枯死亡，致田间出现缺苗断垄或造成毁种。 ', '(1)发生世代。内蒙古等春麦区一年发生2代，冬麦区一年发生3～4代。(2)越冬及虫源：幼虫老熟后在为害处、寄主根茎部或土缝中或杂草上越冬。(3)发生因素。①气候因素。产卵和幼虫孵化需较高湿度。②栽培因素。小麦茎秆柔软、叶片较宽或毛少的品种，产卵率高，为害重。 [预测预报]冬麦区在3月中下旬，春麦区在5月中旬开始查虫，每隔2～3天于10时前后在麦苗顶端扫网200次，当200网有虫2～3头时，约在15天后即为越冬代成虫羽化盛期，是第1次药剂防治适期。冬麦区平均百网有虫25头，即需防治。', '(1)农业防治。①因地制宜选用适合当地的耐虫或早熟品种。②加强栽培管理，做到适期早播、合理密植。加强水肥管理，促进小麦生长整齐。加快小麦前期生长发育是控制该虫的根本措施。(2)药剂防治。①用50%辛硫磷乳油 1.5kg，对水2.5kg，混匀后喷拌在20kg干土上，制成毒土，撒施。②成虫发生期也可喷洒36%克螨蝇乳油 1 000～1 500倍液或50%敌敌畏乳油 1 000倍液，喷对好的药液1 125L/hm2。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-16/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (57, 'disease_49', '黑麦秆蝇', 'disease', 'type_2_crop_1', '幼虫钻入心叶或幼穗中为害，受害部枯萎或造成枯心。', '(1)发生世代。一年发生3～4代。(2)越冬及虫源。以老熟幼虫在冬作物或野生禾本科植物茎内越冬。', '(1)农业防治。①因地制宜选用适合当地的耐虫或早熟品种。②加强栽培管理，做到适期早播、合理密植。加强水肥管理，促进小麦生长整齐。加快小麦前期生长发育是控制该虫的根本措施。(2)药剂防治。①用50%辛硫磷乳油 1.5kg，对水2.5kg，混匀后喷拌在20kg干土上，制成毒土，撒施。②成虫发生期也可喷洒36%克螨蝇乳油 1 000～1 500倍液或50%敌敌畏乳油 1 000倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-17/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (58, 'disease_50', '麦黑斑潜叶蝇', 'disease', 'type_2_crop_1', '幼虫潜食叶肉，潜痕弯曲窄细。 ', '(1)世代。发生代数不详。(2)越冬。可能以蛹越冬', '以消灭成虫为主，于4月初春麦出苗、冬麦返青时，在田间喷撒2.5％敌百虫粉，消灭成虫，防其产卵。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-18/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (59, 'disease_51', '麦茎谷蛾', 'disease', 'type_2_crop_1', '低龄幼虫在心叶内为害，造成心叶残缺、卷心、矮缩或枯心，幼虫还可蛀食第1节茎基，造成白穗。 \r\n发生因素', '(1)发生世代。山东、河北一年发生1代。(2)越冬及虫源。以低龄幼虫在小麦心叶里越冬。(3)发生因素。一般抽穗早和靠近村庄的麦田受害重。', '(1)农业防治。成虫羽化期，屋檐下隔2～3m挂麻袋等有皱褶的物件，诱其钻入后，翌晨集中处理。(2)药剂防治。4月上中旬，幼虫爬出活动或转株为害时，喷洒2.5%敌百虫粉。必要时喷洒90%晶体敌百虫1 000倍液，或80%敌敌畏乳油 1 500倍液，或50%辛硫磷乳油 1 500～2 000倍液。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (60, 'disease_52', '粟凹胫跳甲', 'disease', 'type_2_crop_1', '幼虫由茎基部咬孔钻入茎秆，造成枯心当幼苗较高，表皮组织变硬时，便爬到顶心内部，取食嫩叶顶心被吃掉，不能正常生长，形成丛生成虫为害，则取食幼苗叶子的表皮组织，吃成白色纵条，使叶面破裂，甚至干枯死掉受害严重的地区常常造成缺苗断垄，甚至毁种', '(1)发生世代：吉林南部一年发生1代，少数2代。(2)越冬及虫源：以成虫在表土层中或杂草根际1.5cm处越冬。(3)发生因素：气候干旱少雨的年份、早播春谷、重茬谷子易受害', '(1)农业防治。适期晚播，躲过成虫盛发期可减轻受害间苗、定苗时注意拔除枯心苗，集中深埋或烧毁。(2)药剂防治。谷子出苗后4～5叶期或谷子定苗期，喷洒5%氯氰菊酯乳油 2 500倍液，或5%来福灵乳油 2 500倍液，或2.5%溴氰菊酯乳油 3 000倍液，喷对好的药液1 125L/hm2也可喷撒2.5%敌百虫粉剂或3%速灭威粉剂，22.5～30kg/hm2。\r\n(1)农业防治。适期晚播，躲过成虫盛发期可减轻受害间苗、定苗时注意拔除枯心苗，集中深埋或烧毁。(2)药剂防治。谷子出苗后4～5叶期或谷子定苗期，喷洒5%氯氰菊酯乳油 2 500倍液，或5%来福灵乳油 2 500倍液，或2.5%溴氰菊酯乳油 3 000倍液，喷对好的药液1 125L/hm2也可喷撒2.5%敌百虫粉剂或3%速灭威粉剂，22.5～30kg/hm2。\r\n(1)农业防治。适期晚播，躲过成虫盛发期可减轻受害间苗、定苗时注意拔除枯心苗，集中深埋或烧毁。(2)药剂防治。谷子出苗后4～5叶期或谷子定苗期，喷洒5%氯氰菊酯乳油 2 500倍液，或5%来福灵乳油 2 500倍液，或2.5%溴氰菊酯乳油 3 000倍液，喷对好的药液1 125L/hm2也可喷撒2.5%敌百虫粉剂或3%速灭威粉剂，22.5～30kg/hm2。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-21/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (61, 'disease_53', '麦叶蜂', 'disease', 'type_2_crop_1', '幼虫食叶成缺刻，为害严重的仅留叶脉。 ', '(1)世代。每年发生1代。(2)越冬。以蛹在土中20mm深处越冬。(3)气候。冬季气温高，土壤水分充足，翌春湿度大温度低，3月雨小，有利于该虫发生。', '(1)农业防治。小麦播种前深耕细耙，破坏其化蛹越冬场所，或将休眠蛹翻至土表机械杀死或冻死。有条件地方进行水旱轮作。老熟幼虫在土中时间长，麦收后及时深耕，能把土茧破坏，杀死幼虫。(2)药剂防治。一般应掌握在幼虫3龄前进行。喷粉用2．5％敌百虫粉剂，用量1.5～2千克/亩。喷雾可用90％晶体敌百虫900倍液，或50％辛硫磷乳油1 500倍液，或80％敌敌畏乳油1 000～1 500倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-22/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (62, 'disease_54', '棉铃虫', 'disease', 'type_2_crop_1', '幼虫孵出后，先取食卵壳，随后幼虫转移到顶部钻蛀嫩叶，低龄幼虫能吐丝缚住未张开的嫩叶在其中啃食叶肉，使叶片仅剩叶膜形成透明状；3龄后蚕食叶片，可将叶片食成缺刻或孔洞，一般损失叶片15%～20%，重者损失50%以上造成严重减产。', '(1)发生世代:在我国由北向南年发生3～7代，在辽宁、河北北部、内蒙古、新疆等地1年发生3代，华北4代，长江以南5～6代，华南地区一年发生6～8代，世代重叠。 (2)越冬及虫源:以蛹在寄主植物根际附近的土中越冬。当气温上升至15℃以上时，越冬蛹开始羽化。 (3)发生因素:①气候因素。高温多雨有利于棉铃虫的发生，干旱少雨对其发生不利。暴雨对卵的冲刷作用明显，另外，土壤湿度过高，绝对含水量占40%，或者相对含水量达60%以上时，将显著影响蛹的存活和成虫的正常羽化。各地主要发生期及主要为害世代有所不同。长江流域5～6月第1代、第2代是主要为害世代。华北地区6月下旬至7月第2代是主要为害世代。东北南部7月、8月上旬至9月上旬的第2代、第3代是主要为害世代。②栽培因素。干旱地区灌水及时或水肥条件好、长势旺盛的农田，前作是麦类或绿肥的农田及与玉米邻作的农田，均有利于棉铃虫发生。③天敌。天敌种类很多，对卵或幼虫有一定抑制作用。卵寄生天敌有拟澳洲赤跟蜂、玉米螟赤跟蜂等。寄生幼虫的天敌有齿唇姬蜂、方室姬蜂、瘦姬蜂、螟铃绒茧蜂、红尾寄生蝇等。捕食性天敌有草蛉、螳螂、长脚黄蜂、小花蝽、蜘蛛等。', '(1)农业防治:①深翻冬灌，减少虫源。通过深耕，把越冬蛹翻入土层，破坏其蛹室。结合冬灌，降低越冬蛹成活率。②麦收后及时中耕灭茬，消灭部分一代蛹，降低成虫羽化率。③种植玉米、高梁诱集带。④田间结合整枝及时打顶，摘除边心及无效花蕾，并携至田外集中处理。 (2)物理防治:用黑光灯或高压汞灯诱杀成虫。安装300W高压汞灯15只/hm2，灯下用大容器盛水，水面撒柴油，效果比黑光灯更好。 (3)生物防治:释放赤眼蜂防治。第1次放蜂时间要掌握在成虫始盛期开始1～2天，每1代先后共放3～5次，蜂卵比要掌握在25:1，放蜂适宜温度为25℃，空气相对湿度为60%～90%。如果温、湿度过高或过低，要适当加大放蜂量。 (4)药剂防治:掌握在卵孵盛期至2龄幼虫时期喷药防治，以卵孵盛期喷药效果最佳。每隔7～10天喷1次，共喷～3次。喷药时，药液应主要喷洒在棉株上部嫩叶、顶尖以及幼蕾上，须做到四周打透。并注意多种药剂交替使用或混合使用，以避免或延缓棉铃虫抗药性的产生。 提倡喷洒Bt乳剂(100亿活孢子/ml)200～300倍液，或棉铃虫核型多角体病毒悬浮剂 (20亿个多角体病毒/ml)1 000倍液。傍晚、雨后或阴天喷洒效果最佳。 此外，还可选用1.8%阿维菌素乳油 3 000倍液，10%吡虫啉可湿性粉剂 1 500倍液，或5%抑太保乳油 2 000倍液，或25%灭幼脲悬浮剂 600倍液，或10.8%凯撒乳油 4 000倍液，或44%速凯乳油 1 500倍液，或42%特力克乳油 1 000倍液，或35%赛丹乳油 500倍液，或40%辉丰1号乳油 1 000倍液，或50%来福灵乳油 3 000倍液，或用2.5%功夫菊酯乳油 2 000倍液，或2.5%溴氰菊酯2 000倍液，5%氯氰菊酯乳油 2 000倍液，或2.5%天王星乳油 3 000倍液，或32.8%保棉丹乳油 1 000倍液，或30%灭铃威乳油 1 500倍液，或40%灭抗铃乳油 1 000倍液，或20%灭多威乳油 1 500倍液，或35%顺丰2号乳油 1 000倍液，或20%农绿宝乳油 1 500倍液，或43%辛?氟氯氰乳油 1 500倍液(对棉铃虫卵和幼虫毒力较高)，或25%灭铃王乳油 2 000倍液，或26%抗铃净乳油 1 000倍液，或30%灭铃灵乳油 2 000～3 000倍液，或25%康克畏乳油 500～600倍液，或2.5保得乳油 2 000倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-23/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (63, 'disease_55', '绿翅脊萤叶甲', 'disease', 'type_2_crop_1', '以幼虫蛀入麦苗根部茎节内，取食嫩茎的内壁组织，致受害苗变为灰绿色，苗心枯死，基部叶片增厚 ', '(1)发生世代。四川白玉县一年发生1代。(2)越冬及虫源。以卵在土内越冬。', '(1)农业防治：及时清除田间杂草，并铲除地块边际直径50m内的蒿类、大蓟等杂草，切断成虫食源。(2)药剂防治。（1）成虫取食阶段尚未产卵时，喷洒2.5%敌杀死乳油 2 000倍液或5%甲氰菊酯乳油 2 000倍液、5%来福灵乳油 3 000倍液、20%菊马乳油 1 500倍液、21%灭杀毙乳油 3 000倍液②上年受害严重麦田的边际受害重的地方，喷撒4.5%甲敌DP，用药45kg/hm2，拌细土300～450kg，于播种前撒在土面上，随即耕翻或耙耱', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (64, 'disease_56', '华北蝼蛄', 'disease', 'type_2_crop_1', '成虫、若虫均在土中活动，取食播下的种子、幼芽或将幼苗咬断致死，受害的根部呈乱麻状。由于蝼蛄的活动将表土层窜成许多隧道，使苗根脱离土壤，致使幼苗因失水而枯死，严重时造成缺苗断垄。', '(1)世代。华北蝼蛄3年左右完成1代。(2)越冬。以成、若虫在土中越冬。', '(1)农业防治。冬春季节耕翻土地，毁坏蝼蛄窝室，冻死越冬蝼蛄。(2)物理防治。在成虫盛发期设置黑光灯诱杀，尤其在温度高、天气闷热、无风的夜晚诱杀效果好。(3)药剂防治。用57％辛硫磷0.25千克，麦麸1.5～2.5千克，加适量水(拌匀成团，撒出去又能散开)，每亩施用2千克，在无风闷热的傍晚施撒效果最佳。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-28/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (65, 'disease_57', '沟金针虫', 'disease', 'type_2_crop_1', '幼虫在土中取食播种下的种子、萌出的幼芽、菜苗的根部，致使作物枯萎致 死，造成缺苗断垄，甚至全田毁种。', '(1)世代。每年 2～3 年1代。(2)越冬。以幼虫和成虫在土中越冬。(3)时期。越冬成虫于 3月中旬至 4月中旬为活动盛期，', '(1)栽培。深翻改土，适时早播，在春季开始为害时浇水，可减轻为害。(2)药剂。每亩用 50%辛硫磷乳油 1～1.5 千克，或48%乐斯本乳油 0.3～0.5千克。当根部遭受为害时，用 48%乐斯本乳油 1 500 倍液，或 37%高氯?马乳油 1 000倍液，或 50%辛硫磷乳油 800倍液，或将喷雾器的喷头拧去旋水片，直接对着根部喷施。每 7～10天喷 1 次，连喷 2～3 次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-26/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (66, 'disease_58', '东方蝼蛄', 'disease', 'type_2_crop_1', '成虫、若虫均在土中活动，取食播下的种子、幼芽或将幼苗咬断致死，受害的根部呈乱麻状。由于蝼蛄的活动将表土层窜成许多隧道，使苗根脱离土壤，致使幼苗因失水而枯死，严重时造成缺苗断垄。', '(1)世代。在华中、长江流域及其以南地区1年发生1代，以北地区约2年发生1代。(2)越冬。以成、若虫在土中越冬。', '(1)农业防治。冬春季节耕翻土地，毁坏蝼蛄窝室，冻死越冬蝼蛄。(2)物理防治。在成虫盛发期设置黑光灯诱杀，尤其在温度高、天气闷热、无风的夜晚诱杀效果好。(3)药剂防治。用57％辛硫磷0.25千克，麦麸1.5～2.5千克，加适量水(拌匀成团，撒出去又能散开)，每亩施用2千克，在无风闷热的傍晚施撒效果最佳。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-27/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (67, 'disease_59', '麦长管蚜', 'disease', 'type_2_crop_1', '麦长管蚜前期集中在叶正面或背面，后期集中在穗上刺吸汁液，致受害株生长缓慢，分蘖减少，千粒重下降，是麦类作物重要害虫。也是麦蚜中的优势种。', '(1)越冬及虫源：长江以南以无翅胎生成蚜和若蚜于麦株心叶或叶鞘内侧及早熟禾、看麦娘、狗尾草等杂草上越冬。(2)发生因素：成虫无明显休眠现象，气温高时，仍见蚜虫在叶面上取食。', '(1)预测预报。当孕穗期有蚜株率达50％，百株平均蚜量200～250头或滔浆初期有蚜株率70％，百株平均蚜量500头时即应进行防治。(2)农业防治法 ①选用抗虫品种。如：“鲁麦23”。⑧合理布局。冬春麦混种区，尽量减少冬小麦面积或冬麦与春麦分别集中种植，这样可减少受害。⑧适时集中播种。冬麦适当晚播，春麦适时早播。④合理施肥浇水。(3)生物防治 减少或改进施药方法，避免杀伤麦田天敌。充分利用瓢虫、食蚜蝇、草蛉、蚜茧蜂等天敌，据测定七星瓢虫成虫，日食蚜100头以上，生产上利用麦蚜复合天敌当量系统，能统～多种天敌的标准食蚜单位和计算法，准确测定复合天敌发生时综合控蚜能力，是采用其它措施依据。测定天敌控蚜指标，把该指标与化防指标、当量系统结合起来，为充分发挥天敌作用提供保证。必要时可人工繁殖释放或助迁天敌；使其有效地控制蚜虫。当天敌不能控制麦蚜时再选用0，2％苦参碱(克蚜素)水剂400倍液或杀蚜霉素(孢子含量200万个／ml)250倍液、50％辟蚜雾或40％氧乐果2000倍液，杀蚜效果90％左右，且能保护天敌。(4)上述措施不能奏效的地区或田块可采用以下综防措施。①在小麦黄矮病流行区主要是苗期治蚜，用0.3％的75％3911乳油，加种子量7％左右的清水，喷洒在麦种上，边喷边搅拌。也可用50％灭蚜松乳油150ml，对水5kg，喷洒在50kg麦种上，堆闷6—12小时后播种。⑧用3％呋喃丹颗粒剂或5％涕灭威颗粒剂、5％3911颗粒剂，每667m21.5kg盖种，持效期可达1—1.5个月。②在非黄矮病流行期，重点防治穗期麦蚜，必要时田间喷洒2.5％扑虱蚜可湿性粉剂或10％吡虫啉(～遍净)可湿性粉剂2500倍液或2.5％高渗吡虫啉可湿性粉剂3000倍液、50％抗蚜威可湿性粉剂3500—4000倍液、18％高渗氧乐果乳油1500倍液、50％马拉硫磷乳油1000倍液、20％康福多浓可溶剂或90％快灵可溶性粉剂3000—4000倍液、50％杀螟松乳油2000倍液或2.5％溴氰菊酯乳油3000倍液。也可选用40％辉丰1号乳油，每667m2 30mL，对水40kg，防效99％，优于40％氧化乐果。④干旱地区每667m2可用40％乐果乳油50ml，对水1—2kg，拌细砂土15kg，或用80％敌敌畏乳油75ml，拌土25kg，于小麦穗期清晨或傍晚撤施。为了保护天敌，尽量选用对天敌杀伤力小的抗蚜威等农药。⑤麦蚜、白粉病混发时，喷洒11％氧乐?酮乳油100ml，对水50kg，防治麦蚜效果与氧乐果相同，防治白粉病效果与三唑酮相当。⑧试用20％敌敌畏重烟剂9—10.5kg／hm2，放烟0.5小时后，烟云逐渐沉降到作物上，防效80％左右。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-01/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (68, 'disease_60', '麦二叉蚜', 'disease', 'type_2_crop_1', '常大量聚集在叶片、茎秆和穗部，吸取汁液，影响小麦发育，严重的麦株不能正常抽穗，并能传播小麦黄矮病。 ', '(1)世代。一年发生20～30代。(2)越冬及虫源。在北纬36o以北较冷的麦区多以卵在麦苗枯叶上、土缝内或多年生禾本科杂草上越冬，在南方则以无翅成、若蚜在麦苗基部叶鞘、心叶内或附近土缝中越冬，天暖时仍能活动取食。(3)发生因素。喜干旱，大发生区都在年降雨量在500mm以下的地区。在5日平均温度5℃时开始活动，生长最适温度为13～18℃。故早春为害、繁殖早，秋苗受害时间长。', '(1)农业防治。注意清除田间、地边杂草，尤其夏秋两季除草，对减轻晚稻蚜虫为害具有重要作用。加强稻田管理，使水稻及时抽穗、扬花、灌浆，提早成熟，可减轻蚜害。(2)药剂防治。晚稻有蚜株率达 10％～15％，每株有蚜虫 5头以上时，及时喷 40％乐果乳油 1 000倍液，或 2.5％保得乳油 2 500 倍液，或 65％蚜螨虫威可湿性粉剂 600 倍液，或10％吡虫啉可湿性粉剂 2 000 倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-02/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (69, 'disease_61', '麦双尾蚜', 'disease', 'type_2_crop_1', '刺吸小麦汁液，并且可分泌毒素破坏叶绿体，降低光合作用，使叶片产生白、黄、或红色纵条，纵卷成筒。旗叶受害后，麦株常不能正常抽穗。', '(1)世代：一年发生11代，在寒冷麦区营全周期生活。(2)越冬及虫源：秋末冬初产生雌性蚜和雄蚜，交配后把卵产在麦类或禾本科杂草上，翌春卵孵化，向外迁飞或为害到麦收。(3)发生因素：①气候因素。在温暖地区营不全周期孤雌生殖。②天敌。天敌有无花果蚜小蜂、异足蚜小蜂、广鞘蚜茧蜂、食蚜瘿蚊、四斑毛瓢虫等。', '(1)农业防治：①选用二粒小麦、Mg4537、Mg7458、Mg8786、Mg8256等感虫率低的品种，可减轻受害。②种植毛大头、红佛尔、墨稻穗、勾毛白等感虫率高的小麦品种，它们可吸引大量虫源，然后集中消灭，不仅可减少施药，节省人力、物力，还可保护天敌，达到自然控制。③在种植当地优良品种时，间种上述感虫品种，把麦双尾蚜消灭在诱虫带中。④禁止从发生地调运禾本科草苗。外来禾本科草苗要注意检查和灭虫消毒。(2)药剂防治：必要时可喷洒10%扑虱蚜可湿性粉剂 2 500倍液，或2.5%保得乳油 2 000～3 000倍液，或35%赛丹乳油 3 000倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-03/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (70, 'disease_62', '麦茎蜂', 'disease', 'type_2_crop_1', '幼虫蛀茎为害，严重的整个茎秆被食空，使麦芒及麦颖变黄，干枯失色，后期全穗变白，茎节变黄或黑色。老熟幼虫钻入根茎部，从根茎部将茎秆咬断或仅留少量表皮连接，断面整齐，受害小麦很易折倒。', '(1)发生世代：一年发生1代。(2)越冬及虫源：以老熟幼虫在茎基部或根茬中结薄茧越冬。(3)发生因素：地势低洼的地块发生严重，靠近河边、沟边、路边耕作粗放的地块发生重。', '(1)农业防治：①麦收后进行深翻，收集麦茬沤肥或烧毁，有抑制成虫出土的作用。②尽可能实行大面积的轮作。③选育秆壁厚或坚硬的抗虫高产品种。(2)药剂防治：为害重的地区于5月下旬洋槐开花期，喷洒90%晶体敌百虫900倍液或80%敌敌畏乳油 1 000～1 200倍液，也可喷撒1.5%乐果粉或2.5%敌百虫粉，22.5～37.5kg/hm2。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (71, 'disease_63', '十四点负泥虫', 'disease', 'type_2_crop_1', '成、幼虫啃食小麦嫩茎或叶肉，影响小麦光合作用。 ', '(1)发生世代：在山东、华北一年发生3～4代，天津一年发生4～5代，陕西发生5代。(2)越冬及虫源：以成虫在麦株四周的土层下或残留在地下的麦茬里越冬。', '必要时，喷洒20%甲氰菊酯乳油 2 000倍液，或50%抗蚜威可湿性粉剂 2 000倍液，或40.7%毒死蜱乳油 1 500倍液，或50%辛硫磷乳油 1 500倍液，或2.5%保得乳油 2 500倍液。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (72, 'disease_64', '黍蚜', 'disease', 'type_2_crop_1', '以成、若虫吸食叶片、茎秆和嫩穗的汁液，不仅影响植株正常生长，还会传播病毒病。 \r\n发生因素', '(1)世代。一年发生 10～20 代。(2)越冬。北方寒冷地区禾谷缢管蚜产卵于稠李、桃、李、榆叶梅等李属植物上越冬， 翌春繁殖后迁飞到禾本科植物上。(3)发生因素。禾谷缢管蚜在 30℃左右发育最快，喜高湿，不耐干旱。', '该蚜发生重的地区，要在苗期或拔节期注意防治虫源基地的蚜虫，穗期防治要在小麦扬花灌浆初期百株蚜量达到防治指标，益害比小于1∶120，近日无大风大雨时及时进行防治。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-xmc-04/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (73, 'disease_65', '玉米大斑病', 'disease', 'type_1_crop_2', '主要为害叶片，严重时也为害叶鞘和苞叶。一般先从底部叶片开始发生，逐步向上扩展，严重时能遍及全株，但也有从中、上部叶片发病的情况。受侵染的叶片上形成大型核状病斑，在田间初为水渍状青灰色或灰绿色小斑点，扩展后为边缘暗褐色、中央淡褐色或者灰色的棱形或长纺锤形大斑，一般长5～10cm，宽1.0～1.5cm，潮湿时病斑上有明显的黑褐色霉层，严重时病斑联合纵裂，叶片枯死。', '(1)气候因素。气候条件是病害发生轻重的重要因素，温度20～25℃、相对湿度90％以上利于病害发展。从拔节到出穗期间，若降雨集中，田间湿度大，再加上气温适宜，可造成病害流行。在北方玉米产区，6～7月降雨量均超过80mm，雨日较多，加之8月份雨量适中，病情发展严重。(2)栽培因素。玉米孕穗、出穗期间氮肥不足，发病较重。单种玉米比套种玉米发病轻。连作地、排水不良的低洼地以及田间密度高、郁闭、通风不良的田块，发病重。品种抗病性是影响大斑病流行的重要因素。玉米连茬地及离村庄近的地块，由于越冬菌源量多，初侵染发生的早而多，再侵染频繁，易造成流行。', '(1)农业防治：选用抗病品种。玉米秸秆不要堆放田头。轮作倒茬，避免重茬。适当早播，培育壮苗，注意肥水管理，氮磷搭配使用。早期摘除下部病叶。玉米收获以后，彻底清除田内外病残组织。(2)化学防治：在心叶末期到抽雄期或发病初期喷药防治。药剂选用5%百菌清可湿性粉剂300倍液，或80%速克净可湿性粉剂1 000倍液，或50%多菌灵可湿性粉剂500倍液，或50%甲基硫菌灵可湿性粉剂600倍液，或75%达科宁可湿性粉剂500倍液，或25%苯菌灵乳油800倍液，或40%克瘟散乳油800～1 000倍液，或0.5%施特灵水剂2 500倍，或20%草酸青霉水剂稀释50倍液。每隔10天防1次，连续防治2～3次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-01/3.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (74, 'disease_66', '玉米小斑病', 'disease', 'type_1_crop_2', '玉米整个生育期内都可发生，但以抽雄、灌浆期，发病重。主要为害叶片，但叶鞘、苞叶和果穗也能受害。叶片上病斑小，但病斑数量多。初为水浸状，以后变为黄褐色或红褐色，边缘颜色较深，椭圆形、圆形或长圆形，大小(5～10)mm×(3～4)mm，病斑密集时常互相连接成片，形成较大型枯斑。多雨潮湿天气，有时在病斑上可看到黑褐色霉层。多从植株下部叶片先发病，向上蔓延、扩展。叶片病斑形状，因品种抗性不同，有3种类型：(1)不规则椭圆形病斑，或受叶脉限制表现为近长方形，有较明显的紫褐色或深褐色边缘。(2)椭圆形或纺锤形病斑，扩展不受叶脉限制，病斑较大，灰褐色或黄褐色，无明显、深色边缘，病斑上有时出现轮纹。(3)黄褐色坏死小斑点，基本不扩大，周围有明显的黄绿色晕圈，此为抗性病斑。高温潮湿天气，前两种病斑周围或两端可出现暗绿色浸润区，幼苗上尤其明显，病叶萎蔫枯死快，叫“萎蔫性病斑”；后一种病斑，当数量多时也连接成片，使病叶变黄枯死，但不表现萎蔫状，叫“坏死性病斑”。', '(1)品种因素。种植感病品种是小斑病大面积流行的重要因素。(2)气候因素。发病适宜温度26～29℃。遇充足水分或高湿条件，病情迅速扩展。玉米孕穗、抽穗期降水多、湿度高，容易造成小斑病的流行。(3)栽培因素。夏玉米比春玉米，发病重。低洼地、过于密植荫蔽地、连作田，发病较重。', '(1)农业防治：可因地制宜地选用抗病品种，注意合理布局和轮换，避免长期种植单一品种。适时播种，使抽穗期避开多雨天气。施足底肥，适期、适量合理追肥，促进植株生长健壮，特别是必须保证拔节至开花期的营养供应。发病制种基地实行大面积轮作，把病原基数压到最低限度，减少初侵染来源。集中清理底部病叶，带出田外处理。收获后，清除地面病株残体，把带菌残体充分腐熟，最好不用于玉米制种田。病田应实行秋翻，使病株残体埋入地下10cm以下。(2)化学防治：发病初期喷洒药剂防治，每隔7～10天防治1次，连防2～3次。药剂可选用50％好速净可湿性粉剂1 000倍液，或80％速克净可湿性粉剂1 000倍液，或75％百菌清可湿性粉剂800倍液，或70％甲基硫菌灵可湿性粉剂600倍液，或25％苯菌灵乳油800倍液，或50％多菌灵可湿性粉剂600倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-02/3.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (75, 'disease_67', '玉米弯孢霉叶斑病', 'disease', 'type_1_crop_2', '发生在玉米成株期，主要危害叶片，有时也危害叶鞘和苞叶。初生褪绿小斑点，逐渐扩展为圆形至椭圆形褪绿透明斑，中间枯白色至黄褐色，边缘暗褐色，周围有浅黄色晕圈，成熟病斑一般长2～5mm，宽1～2mm，大的可达7mm×3mm。湿度大时，病斑正反两面有灰黑色霉状物。该病症状变异较大，在一些自交系和杂交种上，有的只生一些白色或褐色小点。', '(1)气候因素。该病属高温高湿型病害，7～8月高温高湿或多雨的季节利于发病和流行。(2)农业防治：播种晚、土壤贫瘠，发病重。', '(1)农业防治：选用抗病品种，注意品种间的合理布局和轮换。秸秆还田或高温堆肥、垫家畜圈、做烧柴，避免用秸秆做篱笆，村边、地头不留玉米秸秆。适时早播、合理密植、增施有机肥、与中矮秆作物间作等均可减轻病害的发生程度。(2)化学防治：发病初期喷洒40%福星乳油8 000倍液，或50%速克灵可湿性粉剂2 000倍液，或12.5%烯唑酮可湿性粉剂3 000倍液，或25%敌力脱乳油1 000倍液，或80%大生可湿性粉剂1 000倍液，或50％退菌特可湿性粉剂1 000倍液，或50％速克灵可湿性粉剂2 000倍液，或50％多菌灵可湿性粉剂1 000倍液，或70％代森锰锌可湿性粉剂1 000倍液。每隔10天左右喷1次，连续2～3次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-03/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (76, 'disease_68', '玉米灰斑病', 'disease', 'type_1_crop_2', '主要危害叶片，也侵染叶鞘和苞叶。发病初期，病斑椭圆形至矩圆形，无明显边缘，灰色至浅褐色病斑。随后，病斑受叶脉限制逐渐扩展成矩形。后期病斑中间灰色，边缘褐色，大小(0.5～60)mm×(0.5～6)mm，严重时病斑相互融合连结成片，可使叶片枯死。潮湿时叶片两面生出灰色霉状物，以叶背居多，即分生孢子梗和分生孢子。', '(1)气候因素。降雨量大、相对湿度高、气温较低，有利于病害的发生和流行(2)栽培因素。轮作地，发病重；田间湿度大，发病也重。', '(1)农业防治：选用抗病品种。合理轮作倒茬，实行间作套种，合理密植，改善田间小气候。适期播种，加强田间管理，雨后及时排水，防止湿气滞留。施足底肥，适时增施磷钾肥，及时追肥，防止后期脱肥。收获后及时清除病株残体，带出田间集中焚烧处理。(2)化学防治：发病初期喷洒75％百菌清可湿性粉剂500倍液，或50％多菌灵可湿性粉剂600倍液，或40％克瘟散乳油800倍液，或50％苯菌灵可湿性粉剂1 500倍液，或20％三唑酮乳油1 000倍液。每隔7～10天喷1次，连续喷2～3次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-04/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (77, 'disease_69', '玉米镰刀菌苗枯病', 'disease', 'type_1_crop_2', '幼苗最先在种子根处褐变，逐渐扩展，造成整个根部发育不良，根毛减少，无次生根或很少次生根。初生根发病后坏死，根系变黑褐色，在基部节间形成坏死环，基部呈水渍状，在轻微外力作用下极易出现整齐断裂。地上部叶鞘褐色有撕裂状，叶片发黄，边缘呈焦枯状，心叶卷曲，以后叶片自下而上逐渐干枯。无次生根的形成死苗。有少量次生根的形成弱苗，在枯死病苗靠近地面部分产生白色粉霉，叶片出现火烧状枯死，心叶逐渐青枯萎蔫。', '(1)寄主抗性。①品种间其抗病性差异较大。②玉米苗势比较墩壮的品种发病轻，苗势瘦弱的发病重。③在同一品种中，果柄脱落的比不脱落的由于次生根生出慢而易发病。 (2)环境因素。低温高湿，利于发病。降水多，土壤板结，通透性差，土壤供氧不足，易发病。 (3)栽培因素。有机肥不足，偏施无机化肥，苗期田间管理不及时，雨后土壤板结，易发病。', '(1)物理防治。精选种子，播种前可先将种子晾晒1～2天，挑选籽粒饱满、无损伤的种子。可采用55℃温水浸种10分钟，晾干后播种。(1)农业防治：①施用的有机肥要充分腐熟，增施有机肥，氮、磷、钾肥合理搭配。②移栽后，及时中耕松土，雨后及时排水。③加强苗期田间管理，促苗早发，促使玉米苗期个体生长发育健壮。④遇阴雨天，雨后要及时划锄，打破土壤板结，增强土壤通气性，促进玉米根系的生长发生育。(3)化学防治：①用2%福尔马林溶液浸种3小时后用清水冲净，晾干即可播种。用种子重量0.2%的万家宝浸种24小时后用清水冲净，晾干即可播种。②零星发病时喷70%甲基硫菌灵可湿性粉剂 600倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-05/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (78, 'disease_70', '玉米纹枯病', 'disease', 'type_1_crop_2', '玉米纹枯病主要发生在玉米籽粒形成期至灌浆期，苗期和生长后期很少发生。该病主要危害叶鞘和果穗，也可危害茎秆和叶片。最初多由近地面的1～2节叶鞘发病，病斑初呈水渍状，椭圆形或不规则形，后病斑中央变为灰白色，边缘褐色，病斑扩大后常多个病斑汇合成云纹状大斑，包围整个叶鞘，致叶鞘腐败，叶片枯死。 受害果穗苞叶上也产生云纹状大斑，其内籽粒和穗轴腐烂。被害茎秆上的叶片呈褐色，不规则形，严重时根茎基部组织变为灰白色，次生根黄褐色或腐烂。多雨、高湿持续时间长时，病部长出稠密的白色菌丝体，菌丝进一步聚集成多个菌丝团，最后形成褐色不规则形的菌核。成熟的菌核极易脱离寄主，遗落田间。', '(1)品种因素。一般而言，生育期长的中晚熟品种发生时间长，病情较重。(2)气候因素。温度20～30℃，雨日多、雨量大、湿度高，病情发展快。(3)栽培因素。玉米连作、播种过密、施氮过多，发病重。玉米单作比间作，发病重。地势低洼、排水不良、土壤湿度大的田块，发病重。', '(1)种子处理。种前用种子重量0. 2%的25%粉锈宁可湿性粉剂或用种子重量0. 25%的33%的纹霉净可湿性粉剂拌种。(2)农业防治：实行轮作，合理密植，注意开沟排水，降低田间湿度，结合中耕消灭田间杂草。合理施用氮肥，增施磷、钾肥，提高植株的抗病力。结合中耕铲除田间除草，随手摘除基部老叶、病叶，带出田间集中处理，既可增加田间通风透光的.又可降低田间湿度，减轻发病。收获后，清除田间病残体，铲除田边杂草，消灭越冬菌源。(3)药剂防治：防治纹枯病造成的穗腐的最佳防治时期为抽雄期。田间病株率达到3%～5%时，喷洒5％井冈霉素水剂1500倍液，或50％甲基硫菌灵可湿性粉剂500倍液，或40％菌核净可湿性粉剂1 000倍液，或50％多菌灵可湿性粉剂600倍液，或50％农利灵可湿性粉剂1 000～2 000倍液，或50％苯菌灵可湿性粉剂1 500倍液，或50％速克灵可湿性粉剂1 000～2 000倍液，或50％退菌特可湿性粉剂800～1 000倍液。每隔5～7天喷1次，连续2～3次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-06/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (79, 'disease_71', '玉米锈病', 'disease', 'type_1_crop_2', '症状可分为普通型锈病和南方型锈病。(1)普通型锈病。发病初期，在叶片正面散生或聚生不明显的淡黄色小点，以后突起，并扩展为圆形至长圆形，黄褐色或褐色，周围表皮翻起，散出铁锈色粉末，即病原菌的夏孢子。后期病斑上生长圆形黑色突起，破裂后露出黑褐色粉末，即病原菌的冬孢子。(2)南方型锈病。病叶上产生夏孢子堆，常见于叶片正面，叶背面极少，稠密着生，金黄色到橙色，形状为圆形或椭圆形。初期为疱疹状隆起，表皮破裂后，散出金黄色到橙色粉状即夏孢子。严重时，叶片上布满了孢子堆，造成大量叶片干枯，植株早衰，甚至全株干枯。除台湾省有多堆柄锈菌冬孢子发生的报道外，我国其他玉米产区均未发现有多堆柄锈菌冬孢子形态存在。', '(1)品种因素。生产上早熟品种易发病，马齿型品种比较抗病。(2)气候因素。高温多湿，连阴雨、多雾或光照不足，发病重。(3)栽培因素。偏施氮肥，发病重。', '(1)种子处理：播种前用种子重量0.1%的287粉锈宁可湿性粉剂，或2％立克锈可湿性粉剂拌种，(2)农业防治：选用抗病品种。增施磷钾肥，避免偏施、过施氮肥，提高寄主抗病力。加强田间管理，清除酢浆草和病残体，集中深埋或烧毁，以减少侵染源。(3)药剂防治：田间发现发病中心，及时进行局部喷药控制，当田间病叶率达6％时应大面积施药防治。药剂可选用25％粉锈宁可湿性粉剂1 000倍液，或25％三唑酮可湿性粉剂1500倍液，或40％多?硫悬浮剂600倍液，或50％硫磺悬浮剂300倍液，或30％固体石硫合剂150倍液，或25％敌力脱乳油3 000倍液，或12.5％烯唑醇乳油4 000倍液。每隔10天左右1次，连续防治2～3次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-07/3.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (80, 'disease_72', '玉米褐斑病', 'disease', 'type_1_crop_2', '褐斑病主要为害叶片和叶鞘，田间症状有整株黄点型和局部褐斑型2种。(1)整株黄点型。一般是整株叶片发病，叶片上出现密集及大小分布较均匀的小黄点，使叶片和植株呈现失绿发黄，密集的小黄点老熟后变成褐色的孢子堆，内有休眠孢子。孢子堆不破裂。(2)局部褐斑型。主要发生在叶鞘、叶主脉上。病斑浅褐色，叶肉组织变为红黄色。主脉发病，病斑红褐色，发病后期，病斑表皮破裂，散出褐色粉末。', '(1)气候因素。高温高湿、阴雨日较多的天气条件，有利于病害发生。(2)栽培因素。一般连作地块和低洼潮湿地块发病较重，土壤瘠薄和缺肥地块较肥沃地块病害发生重。', '(1)种子处理：播种前用种子重量0.5％的34％卫福胶悬剂拌种。(2)农业防治：实行3年以上轮作。推广旱播与配方施肥技术。合理密植，施足底肥，适当追肥。始见病叶时及时摘除，收获后彻底清除病残体，及时深翻。(3)药剂防治：玉米4～5叶期喷洒20％三唑酮乳油3 000倍液，或12.5%烯唑醇乳油1 000倍液，或70%甲基托布津可湿性粉800倍液，或或50%多菌灵可湿性粉剂500倍液，或50％苯菌灵可湿性粉剂1 500倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-08/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (81, 'disease_73', '玉米轮纹斑病', 'disease', 'type_1_crop_2', '主要为害叶片。初在叶面上产生圆形至椭圆形的褐色至紫红色病斑，后期轮纹较明显。病斑汇合后很象豹纹，叶片枯死。湿度大时，叶背可见微细橙红色粘质物，即病菌的子实体。', '多在7月份发生。多雨年份扩展迅速，分布普遍。', '(1)种子处理：用种子重量0.5%的50%福美双可湿性粉剂，或0.5%的50%多菌灵可湿性粉剂拌种。（2）农业防治：①实行大面积轮作，施足充分腐熟的有机肥。②收获后及时处理病残体，进行深翻，把病残体翻入土壤深层。(3)药剂防治：孕穗期喷50%多菌灵可湿性粉剂 800倍液，或70%甲基硫菌灵可湿性粉剂 1 000倍液，或50%苯菌灵可湿性粉剂 1 500倍液，或25%溴菌清可湿性粉剂 500倍液，或80%大生M-45可湿性粉剂 600倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-09/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (82, 'disease_74', '玉米疯顶病', 'disease', 'type_1_crop_2', '土壤传播的系统侵染性病害，病菌侵染胚芽导致系统发病。疯顶病症状类型繁多，这与病菌侵染时间及在植株上定殖程度有关，在不同年份、不同地区、不同田块的主要症状也不尽相同。(1) 苗期。苗期症状不明显，抽雄后症状明显。表现植株矮缩，节间缩短，叶片浓绿、变厚；分蘖增多，一般3～5个，多者达10个；叶色浅绿，心叶黄化，上部叶片扭曲、皱缩或卷成筒状，心叶不展，重者枯死，造成田间缺苗断垄。 (2) 成株期。抽雄后表现雄穗叶化，局部雄穗异常增生，畸形生长，小花转变为变态小叶；小叶叶柄较长，簇生，使雄穗呈头状；雄穗上部正常，下部大量增生呈团状绣球，不能产生正常雄花；雌穗(果穗)受侵染后，粗长，不抽花丝，苞叶尖端变态为小叶并呈45度角丛生；严重时，雌穗内部全为苞叶；穗轴呈多茎节状伸长，不结实；发病较轻的雌穗可产生少量秕瘦的种子；植株不抽雄，上部叶呈对生，有的心叶紧卷，严重扭曲成不规则团状或牛尾巴状；病株疯长，头重脚轻，易倒伏、折断。雌雄穗症状同株发生的病株，在田间较常见，这是玉米疯顶病的典型症状。部分病株表现为雌穗感病雄穗正常或雄穗感病雌穗正常。 [侵染]玉米疯顶病是土壤传播、系统侵染的病害。病原菌以卵孢子在病残体或土壤中越冬，田间病株杂草也是该病的初侵染来源之一，病株种子带菌，可以远距离传播病原，成为新病区的初侵染源。玉米播种后，在饱和湿度的土壤中，卵孢子萌发产生孢子囊和游动孢子，游动孢子萌发侵入寄主，玉米芽期是适宜的侵染时期，病原菌通过玉米幼芽鞘侵入导致发病。因此保护幼芽期是防治的关键。 \r\n土壤传播的系统侵染性病害，病菌侵染胚芽导致系统发病。疯顶病症状类型繁多，这与病菌侵染时间及在植株上定殖程度有关，在不同年份、不同地区、不同田块的主要症状也不尽相同。(1) 苗期。苗期症状不明显，抽雄后症状明显。表现植株矮缩，节间缩短，叶片浓绿、变厚；分蘖增多，一般3～5个，多者达10个；叶色浅绿，心叶黄化，上部叶片扭曲、皱缩或卷成筒状，心叶不展，重者枯死，造成田间缺苗断垄。 (2) 成株期。抽雄后表现雄穗叶化，局部雄穗异常增生，畸形生长，小花转变为变态小叶；小叶叶柄较长，簇生，使雄穗呈头状；雄穗上部正常，下部大量增生呈团状绣球，不能产生正常雄花；雌穗(果穗)受侵染后，粗长，不抽花丝，苞叶尖端变态为小叶并呈45度角丛生；严重时，雌穗内部全为苞叶；穗轴呈多茎节状伸长，不结实；发病较轻的雌穗可产生少量秕瘦的种子；植株不抽雄，上部叶呈对生，有的心叶紧卷，严重扭曲成不规则团状或牛尾巴状；病株疯长，头重脚轻，易倒伏、折断。雌雄穗症状同株发生的病株，在田间较常见，这是玉米疯顶病的典型症状。部分病株表现为雌穗感病雄穗正常或雄穗感病雌穗正常。 [侵染]玉米疯顶病是土壤传播、系统侵染的病害。病原菌以卵孢子在病残体或土壤中越冬，田间病株杂草也是该病的初侵染来源之一，病株种子带菌，可以远距离传播病原，成为新病区的初侵染源。玉米播种后，在饱和湿度的土壤中，卵孢子萌发产生孢子囊和游动孢子，游动孢子萌发侵入寄主，玉米芽期是适宜的侵染时期，病原菌通过玉米幼芽鞘侵入导致发病。因此保护幼芽期是防治的关键。 \r\n土壤传播的系统侵染性病害，病菌侵染胚芽导致系统发病。疯顶病症状类型繁多，这与病菌侵染时间及在植株上定殖程度有关，在不同年份、不同地区、不同田块的主要症状也不尽相同。(1) 苗期。苗期症状不明显，抽雄后症状明显。表现植株矮缩，节间缩短，叶片浓绿、变厚；分蘖增多，一般3～5个，多者达10个；叶色浅绿，心叶黄化，上部叶片扭曲、皱缩或卷成筒状，心叶不展，重者枯死，造成田间缺苗断垄。 (2) 成株期。抽雄后表现雄穗叶化，局部雄穗异常增生，畸形生长，小花转变为变态小叶；小叶叶柄较长，簇生，使雄穗呈头状；雄穗上部正常，下部大量增生呈团状绣球，不能产生正常雄花；雌穗(果穗)受侵染后，粗长，不抽花丝，苞叶尖端变态为小叶并呈45度角丛生；严重时，雌穗内部全为苞叶；穗轴呈多茎节状伸长，不结实；发病较轻的雌穗可产生少量秕瘦的种子；植株不抽雄，上部叶呈对生，有的心叶紧卷，严重扭曲成不规则团状或牛尾巴状；病株疯长，头重脚轻，易倒伏、折断。雌雄穗症状同株发生的病株，在田间较常见，这是玉米疯顶病的典型症状。部分病株表现为雌穗感病雄穗正常或雄穗感病雌穗正常。 [侵染]玉米疯顶病是土壤传播、系统侵染的病害。病原菌以卵孢子在病残体或土壤中越冬，田间病株杂草也是该病的初侵染来源之一，病株种子带菌，可以远距离传播病原，成为新病区的初侵染源。玉米播种后，在饱和湿度的土壤中，卵孢子萌发产生孢子囊和游动孢子，游动孢子萌发侵入寄主，玉米芽期是适宜的侵染时期，病原菌通过玉米幼芽鞘侵入导致发病。因此保护幼芽期是防治的关键。', '一种系统侵染的土壤传播病害。病害的发生与环境条件密切相关。湿度是病害发生的重要因素。玉米苗期淹水是疯顶病发生的必要条件。当田间有病原菌存在时，播种后至3～4叶期，雨水过多或因灌溉而造成田间积水达一定时间则会诱使该病害严重发生。地势低洼，土壤湿度大或积水田发病都较严重；地势较高，排水良好，土壤湿度较低的田块，一般发病较轻。温度是该病害发生的另外1个重要因素，低温有利于病害的发生。', '(1)农业防治：①种子抗病品种，可有效控制病害的发生。②实行大面积轮作，减少病原积累。③病区在玉米3叶期以后浇水，有利于控制病害。④地势低洼地防止大水漫灌，及时排除田间积水，降低土壤湿度，能减轻发病。⑤玉米收获后及时清除田间病残体并集中销毁，可减轻此病为害。(2)化学防治：发病初期喷90%乙磷铝可湿性粉剂 400倍液，或64%杀毒矾可湿性粉剂 500倍液，或69%安克?锰锌可湿性粉剂 1 000倍液，或72%霜脲?锰锌可湿性粉剂 700倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-10/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (83, 'disease_75', '玉米茎腐病', 'disease', 'type_1_crop_2', '(1)根和茎基部。受害植株从茎基部发病处折断，根茎内部组织腐烂坏死，病株的果穗往往下垂，籽粒松瘪，造成玉米提前枯死、倒伏，千粒重、穗粒重、穗长和行粒数降低。(2)叶片。症状有青枯、黄枯和青黄枯3种。如在发病期遇到雨后高温，蒸腾作用较大，因根系及茎基受病害，使水分吸收运输功能减弱，从而导致植株叶片迅速枯死，全株呈青枯症状。如发病期没有明显雨后高温，蒸腾作用缓慢，在水分供应不足情况下叶片由下而上缓慢失水，逐步枯死，呈黄枯症状。如病程发展速度突然由慢转快则表现青黄枯。', '玉米茎腐病是由多种病原菌引起的土传病害，发病原因复杂。(1)品种因素。矮秆品种、早熟品种，易发病。(2)气候因素。玉米抽雄期至成熟期高温、高湿是茎腐病发生流行的重要条件，尤其是雨后骤晴，土壤湿度大，气温剧升，往往导致该病暴发成灾。(3)栽培因素。播种早，密度大，田间郁闭，通风透光不良，发病重。同一品种，一般春播发病轻，夏播发病重。', '(1)农业防治：选用抗病、耐病品种。适时播种，合理密植，有机肥要充分腐熟后施用，并适当增施钾肥。起垄种植，雨后及时排水，降低土壤湿度。防治地下害虫，减少根部伤口，也可减轻发病。实行与谷子、大豆、水稻等作物进行轮作。(2)种子处理：用种子重量0.2％的70%甲基硫菌灵可湿性粉剂，或25％三唑酮可湿性粉剂拌种。田间零星发病时，可用50％多菌灵可湿性粉剂500倍液灌根，每株用量500毫升。每隔7天灌一次，连续2～3次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-11/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (84, 'disease_76', '玉米圆斑病', 'disease', 'type_1_crop_2', '(1)叶片。病菌侵染叶片形成圆形、卵圆形病斑。病斑散生，初为水渍状淡绿至淡黄色小点，以后扩大为圆形或卵圆形斑点，有同心轮纹，中央淡褐色，边缘褐色，具黄绿色晕圈，大小(0.3～1.0)cm×(0.1～0.3)cm。有时数个病斑汇合，变成长条斑，导致叶片局部或全部枯死，表面亦生黑色霉层。(2)穗部。在玉米果穗冒尖期开始侵染穗顶部和穗基部的苞叶，以后病害由外层苞叶逐步向里扩展蔓延，侵害玉米籽粒和穗轴，病部变黑凹陷，导致果穗变形弯曲，籽粒和穗轴变黑，籽粒完全失去发芽能力，后期籽粒表面和苞叶上长满黑色霉层，即病原菌的分生孢子梗及分生孢子。苞叶病斑初为褐色斑点，以后扩展为圆形大斑，有同心轮纹，后期表面长满黑色霉层。(3)叶鞘。叶鞘发病后症状与苞叶相似，但形状不甚规则，表面也生黑色霉层。', '7～8月份雨水多、湿度大的年份，发病重。地势低洼，田间通风透光不良，容易发病。重茬地、早播地发病重。', '(1)种子处理：播种前用种子重量0.2％的25％三唑酮可湿性粉剂拌种。(2)农业防治：选用抗病品种。使用无病种子，适当晚播，合理密植，合理施肥，注意排水。秋收后彻底清除田间残株落叶。实行轮作倒茬。(3)药剂防治：玉米吐丝盛期向果穗上喷药，以减少穗期发病，隔7～10天防治1次，连续防治2次，减轻损失。药剂可选用25％三唑酮可湿性粉剂500倍液，或50％多菌灵可湿性粉剂500倍液，或70％代森锰锌可湿性粉剂500倍液，或40％福星乳油8 000倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-12/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (85, 'disease_77', '玉米干腐病', 'disease', 'type_1_crop_2', '(1)穗部。病穗一般成熟早，僵化变轻，病果穗和苞叶之间充满白色菌丝体，以致苞叶和果穗粘连，不易剥离。剥去苞叶，可见果穗下部或全穗籽粒皱缩，呈暗褐色或污浊状，失去光泽，粒间常有紧密的灰白色菌丝体，穗轴松软变轻，易于折断破裂。严重时，籽粒基部甚至全粒均有少量白色菌丝体，散生许多小黑点。穗轴和护颖上也常生许多小黑点，这些症状是识别该病的重要特征。(2)茎秆。茎秆上发病时，在基部4～5节处或果穗节的节部出现褐色、紫红色或黑褐色大形病斑，叶鞘和茎秆之间常有白色菌丝体，后期也生大量小黑点。小黑点一般先在节部出现，然后在下部的节间发生，严重时节间布满小黑点，但仍以节部为最多。有时气生根上也生小黑点，但叶鞘上则不能产生。(3)叶片。受害时，在叶背面生褐色不规则的长形病斑，大小5cm×(1～2)cm。一般很少产生小黑点。', '玉米生长前期遇有高温干旱，气温28～30℃，雌穗吐丝后半个月内遇有多雨天气利其发病。', '(1)检疫：病区的玉米种子、穗轴、茎秆和苞叶等严禁外运。无病区要加强检疫，防止该病传入。(2)种子处理：播前可选用福尔马林200倍液浸种1小时，也可用50％多菌灵或50％甲基硫菌灵可湿性粉剂100倍液浸种24小时，用清水冲洗晾干后播种。(3)栽培因素。病区要建立无病留种田，选留无病种子。重病区实行2～3年的大面积轮作。收获后及时清洁田园，及时烧毁，以减少菌源。发病秸秆在第二年雨季以前作燃料烧掉，秋季深翻土壤，以控制发病。(4)抽穗期发病即喷洒药剂防治，每隔7～10天防治1次，连续防治1～2次。药剂可选用50％多菌灵可湿性粉剂1 000倍液，或50％甲基硫菌灵可湿性粉剂1 000倍液，或25％苯菌灵乳油800倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-13/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (86, 'disease_78', '玉米丝黑穗病', 'disease', 'type_1_crop_2', '主要侵害玉米穗。(1)叶片。自种子萌动至五叶期都能感染玉米丝黑穗病，以三叶期前，特别是幼芽期侵染率最高，受侵染的玉米植株矮化，节间缩短，茎秆稍有弯曲，叶片密集，色浓绿叶片向上发直或叶片上有黄白条纹。(2)雄穗。雄穗发病后，部分或整个花器变形，基部膨大，内包黑粉。(3)雌穗。雌穗发病时，外观短粗，无花丝，除了苞叶外整个果穗变成1个大黑粉包，成熟时苞叶开裂散出黑粉，内混有许多丝状物，是残留的维管束组织，故称丝黑穗病。', '(1)高峰期。病菌的侵染高峰在玉米三叶期以前。(2)农业防治：玉米连作年限越长，发病越严重。套种或夏播的玉米一般很少发病。土温21℃、土壤含水量12％～20％，最适宜发病。高寒冷凉地块易发病，水浇地发病轻，坡地、山地或较干旱的田块，发病重。施用带菌粪肥、田间管理粗纺，均可加重发病', '(1)种子处理：播种前用10％烯唑醇乳油20克湿拌玉米种100千克，堆闷24小时后播种，也可用种子重量0.4％的25％三唑酮或15％三唑醇可湿性粉剂拌种。还可以选用种子重量0.2％的18.6%福?克?戊唑悬浮种衣剂，或16%福?克?唑醇悬浮种衣剂，或63%福?克?戊唑干粉种衣剂，或22%福?克?戊唑悬浮种衣剂，或7.5%克?戊唑悬浮种衣剂。(2)农业防治：选用抗病品种。春旱地区雨后抢墒播种，或坐水浅播，播前灌溉，保证土壤水分良好，都可以显著减轻发病。间苗定苗时选留大苗壮苗，剔除病弱苗和畸形苗。有机粪肥要充分腐熟后才可施用。结合种植结构调整，实行倒茬轮作。清洁田间，拔除病株，处理病残组织。发病重的田块，在玉米开花期后，一旦发现病株，一定要割除并进行深埋处理，以防止病菌扩散。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-14/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (87, 'disease_79', '玉米黑粉病', 'disease', 'type_1_crop_2', '苗期至成株期均可发生，叶片、茎秆、雄穗、雌穗以及气生根等都可以被侵染，形成大小形状不同的瘤状物。瘤状物是因病菌代谢产物的刺激而肿大形成的菌瘿，它外面包有由寄主表皮组织所形成的薄膜，初为白色或浅紫色，逐渐变成灰色，后期变成灰黑色。菌瘿成熟后，外膜破裂，散出大量黑粉。', '(1)品种因素。耐旱品种，以及果穗苞叶长的品种较抗病。甜玉米较感病，马齿型玉米较抗病。早熟种较晚熟种发病略轻。(2)气候因素。高温高湿利于后垣孢子萌发。玉米受旱，抗病力弱，遇微雨或多雾、多露的天气，发病重。前期干旱，后期多雨，或干湿交替，容易发病。(3)栽培因素。连作地或高肥密植地，发病重。植株伤口多，有利于病菌侵入，容易发病。', '(1)种子处理：播种前用种子重量0.5％～0.7％的50％多菌灵可湿性粉剂拌种，或种子重量0.4％的25％三唑酮可湿性粉剂拌种。(2)农业防治：选用抗病品种。不偏施氮肥，不施用含有病菌或未经充分腐熟的农家粪肥。及时防治害虫，减少耕作机械损伤。结合苗期田间管理，拔除病株，带出田外集中处理。加强水肥管理，玉米抽雄前后防止玉米受旱。拔节期至成熟期，将病瘤在成熟破裂前切除，并深埋。结合玉米收获剔除病株及病残体，玉米秸秆不要堆放在田间地头。重病区应实行2～3年的轮作。(3)药剂防治：在玉米即将抽穗时，用1％的波尔多液喷雾。在玉米抽穗前10天左右用50％福美双可湿性粉剂500～800倍喷雾。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-15/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (88, 'disease_80', '玉米条纹矮缩病', 'disease', 'type_1_crop_2', '玉米发病后最明显的特征是节间缩短、株形矮缩，沿叶脉产生褪绿条纹。(1)整株。早期受害，生长停滞，提早枯死。中期受害，植株显著矮化，顶叶丛生，雄花不易伸出，如伸出，籽粒亦多秕瘦，病株上部多向～侧倾斜。后期受害，矮缩不明显，对产量影响较小。(2)叶片。最初上部叶片稍硬、直立，沿叶脉出现淡黄色条纹，自叶基部向叶尖发展。后期，叶脉向上产生灰黄色或土红色坏死斑，病叶提前枯死。叶片上的条纹可分为密纹型和疏纹型两类。密纹型在病叶的两条明显叶脉之间，常产生1～5条连续的至断断续续的条纹，纹宽0.2～0.7mm。疏纹型条纹产生在明显叶脉上，在脉间极少出现，纹宽约0.4～0.9mm，条纹多断断续续。(3)其他部位。叶鞘、茎秆、髓、穗轴、雄花花序的小梗、苞叶及苞叶上的小叶均可受害，产生淡黄色条纹及褐色坏死斑，而苞叶及其顶端的小叶特别敏感，发病后易显症。', '凡有利于灰飞虱生长、繁殖的因素，均有利于病害扩展、蔓延。带毒虫口密度大，发病重。春玉米早播发病轻，晚播发病重；夏玉米早播发病重，晚播发病轻。', '选种抗病品种。适时播种，提倡大垅双种植，降低田间湿度。精细整地，增施磷钾肥。把好玉米第一次浇灌时间，争取在玉米出苗后40～45天浇头水。春季清洁田园，间苗时拔除病株。积极防治灰飞虱。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-16/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (89, 'disease_81', '玉米矮花叶病', 'disease', 'type_1_crop_2', '玉米整个生育期均可感染。受寄主抗病性及环境等因素的影响而症状多样。最初在幼苗心叶基部细脉间出现许多椭圆形褪绿小点，呈虚线状排列，以后发展成实线。病部继续呈不规则状扩大，不受叶脉限制，在粗脉间形成许多黄色的条纹，与健部相间形成花叶症状。病部可包围健部，形成许多大、小不同略呈圆形的绿斑，叶片变黄、棕、紫或干枯。重病株的苞叶、叶鞘、雄花穗有时出现褪绿斑，植株矮小，其高度有时只为健株的1/2～1/3，不能抽穗或迟抽穗而不结实。病株茎细，根部不发达或萎缩。', '(1)气候因素。冬暖春旱，有利于蚜虫越冬和繁殖，发病重。(2)栽培因素：蚜虫发生危害高峰期正与春玉米易感病的苗期相吻合，发病重。田间管理粗放，草荒重，易发病。偏施氮肥，少施微肥，可加重病情。', '选用无病区种子及抗病品种。调整玉米播期，避免蚜虫高峰期与玉米易感病生育期相吻合。加强苗期管理，培育壮苗。增施有机肥，增施锌、铁等微肥。在田间尽早拔除病株，是防治该病关键措施之一。及时中耕锄草，可减少传毒寄主。冬前或春季及时清除地头、田边以及田间的杂草，尤其多年生杂草，压低蚜虫虫口基数。及时防治蚜虫，减少初侵染源', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-17/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (90, 'disease_82', '玉米粗缩病', 'disease', 'type_1_crop_2', '病株茎节明显缩短变粗，严重矮化，仅为健株高的1/2～1/3。叶片浓绿对生，宽短硬直。顶叶簇生，心叶卷曲变小。叶背及叶鞘的叶脉上有粗细不一的蜡白色突起条斑。苗期得病，不能抽穗结实，往往提早枯死。拔节后发病，上部茎节缩短，虽能抽穗结实，但雄花轴短缩，穗小畸形，后期感病症状不明显，但千粒重有所下降。', '玉米出苗至五叶期，如与传毒昆虫迁飞高峰期相遇易发病。夏玉米以麦套玉米感病重，直播玉米发病轻。春玉米晚播，夏玉米早播，发病重。', '防治灰飞虱是玉米粗缩病的防治关键。(1)农业防治：选用病性较强的品种。提倡连片种植，避免单一抗病品种的大面积种植。适时播种，做到播种期基本一致。提倡营养钵育苗，薄膜覆盖，减少苗期感染。玉米播种前或出苗前大面积清除田间、地边杂草，减少毒源。合理施肥、灌水，加强田间管理，缩短玉米苗期时间，减少传毒机会。结合定苗拔除病苗。田间发现病株，及时清除，减少毒源。(2)化学防治：玉米苗期发病初期喷洒5％菌毒清可湿性粉剂500倍液，或5％病毒必克可湿性粉剂500倍液，或抗毒丰300倍液，可减轻危害。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-18/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (91, 'disease_83', '玉米霜霉病', 'disease', 'type_1_crop_2', '病株心叶出现黄白色条纹，后全株呈现淡绿色，重病苗提前枯死。也有的发病幼苗严重矮化，生长衰弱，叶色较浓，沿脉形成黄褐色条状枯死斑。成株期发病，叶片出现白色至黄色条斑，或淡绿、黄绿相间的条纹，有的有明显边界。病斑相互融合形成大斑，常引起叶片枯死。病株矮小，偶尔抽雄，一般不结苞，早枯。有的病叶背面着生白色霜状霉层。', '气候潮湿，雨水充沛，地势低洼利于发病。', '(1)检疫：加强引种管理，实施植物检疫。(2)种子处理：播种前用64％杀毒矾可湿性粉剂500倍液，或25％瑞毒毒可湿性粉剂500倍液，或58％瑞毒毒锰锌500倍液浸种24小时，捞出晾干后播种。栽培。平整土地，雨后排除田间积水，防止苗期淹水。及时拔除病株集中烧毁或深埋。(2)化学防治：发病初期喷洒90％乙磷铝可湿性粉剂400倍液，或64％杀毒矾可湿性粉剂500倍液，或69％安克锰锌可湿性粉剂1 000倍液，或72％霜脲?锰锌可湿性粉剂700倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-19/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (92, 'disease_84', '玉米眼斑病', 'disease', 'type_1_crop_2', '主要为害叶片，经常发生在接近成熟的上部叶片上。发病初期叶片上现小而透明的圆形至卵形水渍状病斑，中央乳白色至茶褐色，四周具褐色至紫色的环，并有具黄色晕圈的狭窄带，大小(1～2)mm×(0.5～1.5)mm。从外表看象一种“眼斑”，故称眼斑病。条件适宜时，病斑融合为大的坏死区，发病早的病斑扩展成带状或片状。叶鞘、苞叶也可产生类似的症状。该病与弯孢霉菌叶斑病特征相近，必要时需镜检病原确诊。我国北方时有发生，有些年份有的地块发生重，生产上现已引起注意。', '孢子萌发适温24℃，在冷湿的气候条件或冷凉、湿度大的山区或7～9月气温不高、降雨多的年份有利其流行。', '(1)种子处理：用种子重量0．5％的50％苯菌灵可湿性粉剂拌种。(2)农业防治：实行3年以上轮作，深翻土壤，及时中耕，提高地温。(3)药剂防治：必要时喷洒50％甲基硫菌灵可湿性粉剂800倍液，或50％苯菌灵可湿性粉剂1 500倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-20/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (93, 'disease_85', '玉米链格孢菌叶枯病', 'disease', 'type_1_crop_2', '主要危害叶片、叶鞘及苞叶。发病初期，病部出现水渍状小圆斑，后逐渐扩展成椭圆形至近圆形的病斑，中央灰白色，边缘红褐色，病健交界明显。病斑大小(4～8)mm×(6～13)mm。后期病部长出黑色霉层，严重时整株叶片病斑满布，呈撕裂状干枯坏死。', '(1)种植密度大，株、行间郁潎，通风透光不好，发病重，氮肥施用太多，生长过嫩，抗性降低易发病。(2)土壤黏重、偏酸；多年重茬地，土壤得不到深耕，耕作层浅缺少有机肥；田间病残体多；肥力不足、耕作粗放、杂草丛生的地块，植株衰弱，发病重。(3)种子带菌、肥料为充分腐熟、有机肥带菌或肥料种混有本科作物病残体的易发病。(4)地势低洼积水、排水不良、土壤潮湿易发病、高温、高湿或长期连阴雨的年份发病重。', '(1)培育、选择抗病品种。(2)按配方施肥要求，充分施足基肥，适时追肥。(3)喷洒75％百菌清可湿性粉剂600倍液或50％扑海因可湿性粉剂1000倍液、50％速克灵可湿性粉剂l500倍液、70％代森锰锌可湿性粉剂500倍液，隔7～15天1次，防治2～3次', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-21/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (94, 'disease_86', '玉米斑枯病', 'disease', 'type_1_crop_2', '玉蜀黍生壳针抱和玉蜀黍壳针抱引起的斑枯病主要为害叶片。初生病斑椭圆形，红褐色，后中央变为灰白色、边缘浅褐色的不规则形斑，致叶片局部枯死。两者常混合发生，较难区别。', '冷凉潮湿的环境利其发病。', '(1)农业防治：及时收集病残体烧毁。(2)化学防治：结合防治玉米其它叶斑病，及早喷洒75％百菌清可湿性粉剂1000倍液加70％甲基硫菌灵可湿性粉剂l000倍液或75％百菌清可湿性粉剂1000倍液加70％代森锰锌可湿性粉剂1000倍液、40％多?硫悬浮剂500倍液、50％复方硫菌灵可湿性粉剂800倍液，隔10天左右1次，连续防治l～2次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-22/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (95, 'disease_87', '玉米炭疽病', 'disease', 'type_1_crop_2', '主要为害叶片。病斑梭形至近梭形，中央浅褐色，四周深褐色，大小（2～4）mm×(1～2)mm，病部生有黑色小粒点，即病菌分生孢子盘，后期病斑融合，致叶片枯死。', '高温、高湿有利于发病。虽然幼苗也可被感染，但一般老叶病重。马齿型玉米比硬粒型的感病轻。', '（1）种子处理：用种子重量0．5％的50％苯菌灵可湿性粉剂拌种。（2）农业防治：用垦粘2号、渝糯1号、西玉7号、白粘早玉米、黄粘早玉米等优良品种。(2)实行3年以上轮作，深翻土壤，及时中耕，提高地温。(5)必要时喷洒50％甲基硫菌灵可湿性粉剂800倍液或50％苯菌灵可湿性粉剂1500倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-23/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (96, 'disease_88', '玉米叶鞘紫斑病', 'disease', 'type_1_crop_2', '玉米灌浆中后期，中上部叶鞘或苞叶上产生绿豆大小的黑褐色斑块，有的稍带紫色，后在叶鞘及苞被上产生不规则或近圆形紫斑。', '七、八月气温高，蚜虫发生猖撅有利于该病的发生和扩展。', '抽雄前防止蚜虫向叶鞘转移是防治鞘斑病的关键。具体方法参见粮食作物害虫', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-24/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (97, 'disease_89', '玉米立枯丝核菌根腐病', 'disease', 'type_1_crop_2', '主要为害玉米的根部或茎基部，苗期引起根系及茎基部染病部位变褐坏死，地上部叶片边缘出现黄褐色云纹状斑，可致田间大量死苗。', '土温低、湿度大、粘质土发病重，播种前整地粗放、种子质量不高、播种过深、土壤贫瘠易发病。', '(1)农业防治：实行大面积轮作。采用高垄或高畦栽培，认真平整土地，防止大水漫灌和雨后积水。苗期注意松土，增加土壤通透性。适期播种，不宜过早。(2)化学防治：发病初期喷洒或浇灌50％甲基硫菌灵(甲基托布津)可湿性粉剂500倍液或50％多菌灵可湿性粉剂500倍液，或配成药土撒在茎基部。也可用3.2％恶甲水剂300～400倍液或95％绿亨1号(恶霉灵)精品4000倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-25/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (98, 'disease_90', '玉米平脐蠕孢茎基腐病', 'disease', 'type_1_crop_2', '发病初期玉米茎基1～3节出现大小不等的浅褐色病斑，后逐渐扩展，颜色由褐色变为黑褐色，气生根变为黑褐色，后期病斑环茎基一周，病节髓组织呈黄褐色干腐状。发病重的植株从病部折断倒伏。', '(1)品种因素。矮秆品种、早熟品种，易发病。(2)气候因素。高温、高湿是发生流行的重要条件，尤其是雨后骤晴，土壤湿度大，气温剧升，往往导致该病暴发成灾。(3)栽培因素。播种早，密度大，田间郁闭，通风透光不良，发病重。同一品种，一般春播发病轻，夏播发病重。', '(1)种子处理：用种子重量0.2％的70%甲基硫菌灵可湿性粉剂，或25％三唑酮可湿性粉剂拌种。(2)农业防治：选用抗病、耐病品种。适时播种，合理密植，有机肥要充分腐熟后施用，并适当增施钾肥。起垄种植，雨后及时排水，降低土壤湿度。防治地下害虫，减少根部伤口，也可减轻发病。实行与谷子、大豆、水稻等作物进行轮作。(2)化学防治：田间零星发病时，可用50％多菌灵可湿性粉剂500倍液灌根，每株用量500毫升。每隔7天灌一次，连续2～3次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-26/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (99, 'disease_91', '玉米假黑粉病', 'disease', 'type_1_crop_2', '玉米雄花序上产生菌瘿或称菌核，代替雄花。一般仅少数花受侵染。在雄花上形成一个近椭圆形的墨绿色的菌瘤，外表看类似玉米黑粉病的椭圆形菌瘤，因此称为假黑粉病。', '潮湿的气候条件，有利于该病的发生和流行。', '防治玉米黑粉病时可兼治假黑粉病，一般不需单独用药。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-27/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (100, 'disease_92', '玉米赤霉病', 'disease', 'type_1_crop_2', '主要为害果穗，有时为害茎干和叶鞘。果穗染病端部变为紫红色，有时籽粒间生有粉红色至灰白色菌丝，病粒失去光泽，不饱满，发芽率降低，播后易烂种。轻的幼苗生长发育不正常，叶片变黄。有时现茎腐病症状，茎秆局部褐色，髓部变成紫红色，易倒折。叶鞘染病生有橙色点状粘分生孢子团。', '干旱、温暖的气候有利于该病的扩展和流行。当玉米产生生长裂伤或玉米穗虫玉米螟及其他害虫为害造成伤口易发病。此外，含赖氨酸高的一些玉米杂交种易感病。', '(1)农业防治：因地制宜选用抗病品种。改善耕作制度。轮作换茬；适当调节播种期，尽可能使该病发生的高峰期，即玉米孕穗至抽穗期，不要与雨季相遇。加强田间管理。于玉米拔节或孕穗期增施磷钾肥，配合氮肥，增强植株抗病力；发病后注意开沟排水，防止湿气滞留。(4)药剂防治：①必要时往穗部喷洒5％井冈霉素水剂，每亩用药50～75ml，对水75～100L或用50％甲基硫菌灵可湿性粉剂600倍液、50％多菌灵悬浮剂700～800倍液、50％苯菌灵可湿性粉剂1 500倍液、40％农利灵可湿性粉剂1 000倍液。视病情防治1次或2次。②在干旱缺水地区每亩用20％井冈霉素可湿性粉剂或40％多菌灵可湿性粉剂200g制成药土在玉米大喇叭口期点心叶，同时可混入杀螟丹粉剂等杀虫剂兼防螟虫。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-28/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (101, 'disease_93', '玉米种子霉烂', 'disease', 'type_1_crop_2', '初发病时幼苗叶色变黄，后萎蔫并枯死。扒开土壤见种子在发芽前组织呈水渍状；中胚轴处的茎组织软腐、烂坏，病部色暗。严重的叶片顶端开始变灰色，后迅速扩展到全叶，在24～48小时内幼苗死亡。侧根呈水浸状，后变褐色且脱落，可扩展到主根或幼苗的根颈组织，植株萎蔫或枯死。', '这类病害在排水不良、10～13℃低温及土壤湿度大条件下易发生，播种过深、土壤粘重发病重。甜玉米比马齿形玉米易染病。', '(1) 种子处理：播种前进行种子处理。用0.3～0.5mg/kg的芸苔素内酯溶液浸种12小时后播种，出苗早且齐，根系发达，增强抗逆力。（2）农业防治：顶凌耙地，及早搂盖，必要时浇底墒水。测定发芽率，发芽率低于90％要更换种子或加大播种量。采用地膜覆盖。土壤表层5～10cm地温稳定在10～12℃，土壤含水量在60％以上，即可播种。 (3)药剂防治：参见玉米镰刀菌苗枯病。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (102, 'disease_94', '玉米全蚀病', 'disease', 'type_1_crop_2', '主要危害玉米根部。苗期典型症状是根上出现栗褐色椭圆形病斑，皮层坏死腐烂。玉米收获前后，轻者根尖或部分根变黑褐色，重则须根和根毛大量减少，根皮变黑色，出现发亮条斑，呈现“黑脚”和“黑膏药”症状。地上部分，病株自抽穗开花叶片逐渐变黄，干枯，重病株茎秆松软，早衰倒伏。苗期虽根部发病，但由于玉米的次生根不断再生，地上植株表现症状不是很明显，只是表现为相对苗黄苗弱、生长较慢。', '有机质含量少、使用钾肥不足的地块，发生较重。高温、高湿利于该病的流行大发生', '玉米全蚀病是土传病害，因此必须采取以种植抗病品种、轮作、增施农家肥等农业技术为主，结合药剂处理种子，穴施颗粒剂或施用MB型玉米专用肥等综合防治技术。（1）农业防治：种植抗病耐病品种。增施肥，合理施用氮磷钾肥，每公顷至少施用3.8万千克农家肥，合理施用氮磷钾肥(三者之间比例为1∶0.5∶0.5)，尤其应多施钾肥。合理轮作，重病地块应与大豆及非禾本科作物轮作。深翻整地，消除病根茬，田间初侵染菌源量对病害发生起重要作用。立秋后及早深翻整地、清除病根茬是消灭越冬菌源的有效措施。(2)化学防治：可施用3%粉锈宁颗粒剂，每公顷穴施22.5千克，也可用25%粉锈宁、20羟锈宁可湿性粉剂，按种子重0.2%～0.3%拌种，或以玉米种衣剂17号，按1∶50拌种;0.01%～0.02%速保利颗粒剂，每公顷穴施45kg，或用速保利可湿粉剂按种子重量的0.2%～0.3%拌种，或施用MB型玉米专用肥，具有控制全蚀病发生和增产的双重作用。③20％的乙酸铜600-800倍液浇根或喷雾', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-30/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (103, 'disease_95', '玉米黑束病', 'disease', 'type_1_crop_2', '玉米生长后期发病。在玉米乳熟期出现大面积枯死，为害严重，从田间表现症状后，仅十几天发展到全田枯死。甘肃采用人工接菌诱发典型症状。发病初期叶片中脉变红，叶片出现淡紫色或紫红色不规则条斑，后扩展到整个叶片，茎皮变成紫红色或紫褐色。叶片逐渐失水，从叶尖、叶缘向叶基部扩展，形成黄白色或，紫褐色干枯，整株从顶部向下迅速干枯而死。剖开病茎可见茎部维管束组织变成浅褐色、黑褐色或黑色坏死，变色部位可长达几个节间，尤以果穗节上、下的3～4节变色最深。地下药部节和节间呈黑褐色坏死。出现大量不孕株或不孕穗，不结实或结实少。有的出现过度分蘖和果穗增长。', '该菌是否为致病力强的变种及其生理型侵染规律尚需进一步明确。该病品种间抗病性差异明显。', '(1)严格检疫，防止该病蔓延。(2)选用中单2号、户单1号等抗病品种，淘汰感病品种、品系，积极选育新的抗病品种。(3)实行轮作，在玉米地不施用玉米秸秆堆制的农家肥。(4)收获后及时清洁田园。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-31/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (104, 'disease_96', '玉米细菌性条纹病', 'disease', 'type_1_crop_2', '主要为害玉米叶片、叶鞘。初生褐色至暗褐色条斑或叶斑，沿叶脉纵向扩展逐渐融合，有的病斑呈长条状，致叶片呈暗褐色，干枯脱落。湿度大时，病部溢出很多菌脓，干燥后成褐色皮状物，易被雨水冲刷脱落。', '高温多雨季节、地势低洼、土壤板结易发病，伤口多，偏施氮肥发病重。', '(1)农业防治：因地制宜选用抗病品种。避免偏施氮肥，多施磷钾肥，培育壮苗。适时适量灌水，地势低洼多湿的田块雨后及时排水。玉米秋收后清除田间病残体，带出田外集中销毁，减少来年菌源。(2)药剂防治。在植株封行期、最迟于病害始见期开始，喷施30%氧氯化铜悬浮剂600倍液，或77%可杀得悬浮剂800倍液，或20%喹菌酮可湿性粉1000倍液，或25%叶双青可湿性粉600～800倍液，2～3次或更多，隔7～15天一次，交替喷施，喷匀喷足。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-32/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (105, 'disease_97', '玉米细菌萎蔫病', 'disease', 'type_1_crop_2', '最初的症状是萎蔫，叶片现灰绿色至黄色线状条斑，有不规则形或波浪形的边缘，与叶脉平行，严重的可延伸到全叶。这些条斑迅速变黄褐干枯，在近地面处茎的髓部变为中空。细菌通过维管束扩展，有时从维管束切口处流出黄色细菌脓液。有的还能进入籽粒。受害株变矮或雄花过早变白死亡', '施用过多铵态氮和磷肥可增加感病性，高温有利于该病流行。甜玉米不抗病，马齿型玉米发病较轻。', '(1)选用培育抗病品种。(2)及早喷洒杀虫剂控制玉米跳甲。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-34/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (106, 'disease_98', '玉米秃尖', 'disease', 'type_1_crop_2', '玉米果穗的顶部不结实。 ', '玉米雌小花分化、吐丝及籽粒形成开始于雌穗的中下部，以后则由此处开始向上或向下部同时进行，最后在顶部结束。因各种因素的影响，而导致玉米顶部的小花或受精胚发生败育，就会出现秃尖的症状。其主要因素有：(1)品种特性的影响。有些品种雄穗抽穗过早，散粉过快，雌穗吐丝时因缺少花粉受精而形成秃尖；有些品种雄穗生长势强，利用顶端优势大量吸收养分，雌穗因养分不足而引起顶部籽粒败育；有些品种雌穗苞叶较长，部分花丝不能完全吐出，或吐出太晚错过授粉机会，从而引起秃尖。(2)水分不足。玉米在雌穗吐丝、雄穗散粉期间，如遇高温干旱天气，水分供应不足，雌穗吐丝不仅偏晚而且吐丝速度慢，花丝容易枯萎，对花粉的接受能力减弱，造成秃尖。(3)栽植过密。肥料供不应求，或遭遇恶劣天气，叶片光合作用减弱，致果穗顶部的受精胚得不到足够的养料，不能发育成籽粒。', '(1)农业防治：选用适宜的品种，硬粒型品种秃尖发生轻，而马齿型则较重。增施有机肥，适当追肥，防止玉米脱肥，尤其要保证开花前后的肥水供应。(2)化学防治：必要时，在雌穗小花分化期喷洒惠满丰活性液肥或促丰宝、喷施宝、高效氨基酸液肥等。此外，喷洒万家宝500～600倍液，或玉米壮丰灵1000倍液也有较好的效果。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-35/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (107, 'disease_99', '玉米花期不协调', 'disease', 'type_1_crop_2', '空穗或部分结实。', '主要原因有两种。(1)遗传因素，由自交系本身遗传特性决定的。这种情况即使在正常条件下也表现花期不协调。(2)不良环境(如严重干旱、连续高温等)造成雌雄花期不相遇。一般是雄花提早散粉，导致雌花全部或局部不能授粉，出现空穗或部分结实。', '改善玉米田肥水条件，尤其是制种田，一定要选用肥水条件优良的土地。加强田间管理，防止干旱、涝淹及脱肥。制种田可将父本分两期或三期播种，也可在边行上增设父本采粉区，以应急需。有条件的可采用人工授粉方法，提高母本结实率。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymb-36/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (108, 'disease_100', '粟负泥甲', 'disease', 'type_2_crop_2', '以成虫和幼虫在粟苗期至心叶期为害叶片。成虫沿叶脉咬食叶肉，受害叶片形成白色条纹。幼虫多藏在心叶内取食嫩叶，使叶面出现白色条斑。受害严重时，造成枯心，烂叶或整株枯死。', '(1)世代。粟叶甲在华北、西北和东北一年发生1代。(2)越冬。成虫于9月上中旬随天气变冷而逐渐越冬。成虫潜于杂草根际、作物残株内、谷茬地土缝中或梯田地堰石块下越冬。华北和西北越冬成虫于翌年5月中旬开始活动，东北则在6月上旬开始活动。(3)发生因素。粟叶甲一般在山旱地、早播田、谷苗长势好的地块发生严重。而川水地、晚播田、谷苗长势差的地块发生较轻。5～6月份降雨偏多，丘陵地区发生比较严重。', '(1)农业防治。①清除杂草秋后或早春，结合耕地，清除田间农作物残株落叶和地头、地埂的杂草，集中烧毁，破坏成虫越冬场所，减少越冬虫源。②捕杀成虫掌握成虫盛发期，利用成虫的假死性，进行人工捕杀成虫。(2)物理防治：有计划地提前播种小面积的诱集田，将越冬成虫诱集于长势好的早播诱集田内，集中消灭，减少防治面积。(3)药剂防治。以消灭越冬代成虫为主，兼治幼虫。掌握成虫发生高峰期和卵孵化盛期。①用1.5%的甲基对硫磷粉剂 加细土375～450千克/公顷，充分搅拌均匀，顺谷垄撒在谷苗上。②喷用50%的辛硫磷乳油1500倍液，或40%的氧化乐果乳油1500倍液，或2.5%的溴氰菊酯乳油，或20%的氰戊菊酯乳油2000～2500倍液，或用2.5%的溴氰菊酯乳油、40%的乐果乳油、80%的敌敌畏乳油等量混合液。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (109, 'disease_101', '玉米异跗萤叶甲', 'disease', 'type_2_crop_2', '幼虫从靠近地面的茎部或地下茎基部钻入，造成幼苗枯萎或死亡成虫为害玉米，啃食叶肉，只留表皮，少量将叶片咬成孔洞 ', '(1)发生世代。山西一年发生1代。(2)越冬及虫源。以卵在土中越冬。', '(1)药剂防治。播前用50%辛硫磷乳油 以种子重量的0.3%的药剂拌种，晾干后再播种发现田间出现花叶和枯心苗后或发现幼虫为害时，用90%晶体敌百虫1 000倍液喷雾，或用2.5%敌百虫粉剂1～1.5kg，拌细土20kg，幼虫为害初期顺垄撒在玉米根部周围杀伤转移为害的幼虫当百株有虫30头以上，可在玉米心叶喷药进行化学防治，也可利用其假死性进行人工捕捉', '', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (110, 'disease_102', '柳蓝叶甲', 'disease', 'type_2_crop_2', '成、幼虫取食叶片成缺刻或孔洞', '(1)发生世代。河南一年发生4～5代，北京5～6代。(2)越冬及虫源：以成虫在土壤中、落叶和杂草丛中越冬。', '(1)药剂防治。喷洒20%菊杀乳油 2 000倍液或50%辛硫磷乳油 1 000倍液、50%马拉硫磷乳油 1 000～1 500倍液、20%虫死净可湿性粉剂 2 000倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-20/1.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (111, 'disease_103', '玉米铁甲', 'disease', 'type_2_crop_2', '成虫顺着玉米叶脉咬食叶肉，形成长短不～的白色线条，并将卵粒散产于嫩绿的心叶上端幼虫孵化后在叶片内咬食叶肉，留下叶片表皮，形成白色枯斑，严重地影响植株光合作用玉米被害后，轻者减产，重者颗粒无收', '(1)发生世代。一年发生1代，少数2代(2)越冬及虫源。以成虫在玉米田附近山坡、沟边杂草，宿根甘蔗及小麦叶片上越冬', '(1)农业防治。成虫高峰期且尚未大量产卵之前，利用其早晨、傍晚、阴天活动迟缓的习性进行人工捕捉，每天上午9时前、下午4时后，阴天全天，用玻璃瓶、塑料瓶、竹筒或其他容器，盛放一些煤油或石灰粉，捕虫丢入其中在玉米铁甲虫幼虫开始化蛹时，而成虫羽化前，用镰刀割下带有幼虫、蛹的叶片，保留绿色健叶，将割下的带虫叶片集中烧毁既减轻当代为害程度，又可减少翌年虫源基数。(2)药剂防治。产卵盛期及幼虫初孵化时，喷洒90%晶体敌百虫800倍液或50%敌敌畏乳油 1 500倍液', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (112, 'disease_104', '玉米蚜', 'disease', 'type_2_crop_2', '以成、若蚜刺吸植株汁液。苗期蚜虫群集于叶片背部和心叶造成为害。轻者造成玉米生长不良。严重受害时，植株生长停滞，甚至死苗。此外，春玉米蚜还会传播玉米矮花叶病毒病。玉米孕穗期，成、若蚜聚结在雄花花萼及穗梗上、雌穗苞叶花丝及其上下邻叶上为害。蚜量大时，形成“黑穗”，使玉米雄花不能发育成熟和难以散粉、授粉，造成玉米雌穗出现明显的少行缺粒和“秃顶”。蚜虫分泌的大量“蜜露”下滴污染叶片，形成霉污，使玉米整株变黑，严重影响玉米光合作用的正常进行。同时蚜虫大量吸取汁液，使玉米植株水分、养分供应失调，影响正常灌浆，导致秕粒增多，粒重下降，甚至造成无棒“空株”。', '(1)世代。长江流域每年发生20多代。(2)越冬。冬季以成、若蚜在大麦心叶或以孤雌成、若蚜在禾本科植物上越冬。(3)气候。高温干旱年份发生多。一般8、9月份玉米生长中后期，均温低于28℃，适其繁殖，此间如遇干旱、旬降雨量低于20mm，易造成猖獗为害。', '(1)农业防治。采用麦棵套种玉米栽培法比麦后播种的玉米提早10～15天，能避开蚜虫繁殖的盛期，可减轻为害。(2)药剂防治。用玉米种子重量0.1％的10％吡虫啉可湿性粉剂浸拌种，播后25天防治苗期蚜虫、蓟马、飞虱效果优异。玉米进入拔节期，发现中心蚜株可喷撒0.5％乐果粉剂或40％乐果乳油1 500倍液。当有蚜株率达30％～40％，出现“起油株”(指蜜露)时应进行全田普治，～是撒施乐果毒砂，用40％乐果乳油50克/亩，对水15千克稀释后喷在20千克细砂土上，边喷边拌，然后把拌匀的毒砂均匀地撒在植株上。或喷50％辛硫磷乳油1 000倍液，用药量50克/亩。在玉米大喇叭口末期喷洒40.64％加保扶悬浮剂800倍液或10％吡虫啉可湿性粉剂2 000倍液，或10％赛波凯乳油2 500倍液，或2.5％保得乳油2 000～3 000倍液，或20％康福多可溶性浓剂3 000～4 000倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-22/3.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (113, 'disease_105', '黍蚜', 'disease', 'type_2_crop_2', '以成、若虫吸食叶片、茎秆和嫩穗的汁液，不仅影响植株正常生长，还会传播病毒病。 ', '(1)发生世代。一年发生10～20代。(2)越冬及虫源。北方寒冷地区禾谷缢管蚜产卵于稠李、桃、李、榆叶梅等李属植物上越冬，翌春繁殖后迁飞到禾本科植物上。属异寄主全周期型。在温暖麦区则可以无翅孤雌成蚜和若蚜在冬麦田或禾本科杂草上越冬。营不全周期生活，冬季天暖仍在麦苗上活动。麦收后转移到黍子和自生麦苗上，北方秋后迁往草丛中越冬，在冬麦区或冬麦、春麦混种区，秋末小麦出土后，迁回麦田繁殖。(3)发生因素。禾谷缢管蚜在30℃左右发育最快，喜高湿，不耐干旱。天敌同麦长管蚜。', '该蚜发生重的地区，要在苗期或拔节期注意防治虫源基地的蚜虫，穗期防治要在小麦扬花灌浆初期百株蚜量达到防治指标，益害比小于1∶120，近日无大风大雨时及时进行防治。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-23/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (114, 'disease_106', '玉米黄呆蓟马', 'disease', 'type_2_crop_2', '以成虫、幼虫在叶背吸食汁液对植物造成严重为害，为害叶背致叶背面呈现断续的银白色条斑，伴随有小污点，叶正面与银白色相对的部分呈现黄色条斑，受害严重者叶背如涂～层银粉，端半部变黄枯干。', '(1)发生世代。年生代数不详。(2)越冬及虫源。成虫在禾本科杂草根基部和枯叶内越冬。(3)发生因素。①气候因素低洼窝风而干旱环境的玉米上发生多，为害重干旱年份发生多，为害重。②栽培因素小麦植株矮小而稀疏地块中的套种玉米上发生多，为害重沟、路、梁边的玉米上发生多，为害重缺水缺肥的玉米受害最重', '(1)农业防治。天气干旱时要注意灌溉并合理施肥，减轻为害。(2)药剂防治。大发生情况下用有25%抗螨23乳油 500～600倍液，或73%克螨特乳油 1 000～2 000倍液，或25%灭螨猛可湿性粉剂 1 000～1 500倍液，或20%甲氰菊酯乳油 2 000倍液，或2.5%天王星乳油 3 000倍液，或5%尼索朗乳油 2 000倍液，或20%双甲脒乳油 1 000～1 500倍液，或1.8%阿维菌素乳油，或10%吡虫啉可湿性粉剂 1 500倍液，或25%的辉丰快克乳油 等1 500～2 000倍，15%哒螨灵乳油 2 500倍液喷雾每隔10天左右1次，连续防治2～3次。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (115, 'disease_107', '禾蓟马', 'disease', 'type_2_crop_2', '多在寄主植物的心叶内活动为害，食害正在伸展的叶片时，多在叶正面取食，叶片呈现成片的银灰色斑。为害严重的可造成大批死苗。', '(1)发生世代。年生10代左右，贵州年约生13代。(2)越冬及虫源。成虫在禾本科杂草根基部和枯叶内越冬。(3)发生因素。①气候因素。空气相对湿度70%～85%较适，温度20～26.6℃，最适宜禾蓟马发生。多雨对它有明显抑制作用。②栽培因素。双季稻、单双混栽以及栽培品种繁多而扬花期不齐，可加重禾蓟马的发生。', '(1)农业防治。冬春期间结合积肥，铲除田边、沟边、塘边杂草，清除田埂地旁的枯枝落叶，特别要清除游草及其他禾本科杂草。(2)药剂防治。盛发期可喷洒10％吡虫啉可湿性粉剂2 500倍液，或10％除尽乳油2 000倍液，或2.5％保得乳油2 000～2 500倍液，或50％杀螟松乳油500倍液，或25％快杀灵乳油1 000倍液，或90％敌百虫晶体1 500倍液，或35％赛丹乳油2 000倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-25/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (116, 'disease_108', '粟缘蝽', 'disease', 'type_2_crop_2', '以成、若虫刺吸谷子、高粱、玉米穗部未成熟籽粒的汁液。 \r\n以成、若虫刺吸谷子、高粱、玉米穗部未成熟籽粒的汁液。 \r\n', '(1)发生世代。在北京、山西1年发生2～3代，在河北或山东发生3代。(2)越冬及虫源。以成虫在树皮下、墙缝和杂草丛中越冬。(3)发生因素：早熟品种能避过受害盛期，紧穗型品种，不利于成、若虫钻入隐蔽，而有利于天敌捕食，也不利于成虫隐蔽产卵，因此受害轻。', '(1)农业防治。①种植抗虫品种选用抗虫品种或适时早播，减轻虫害。②人工捕杀成虫盛发期，用网捕杀成虫。(2)药剂防治。药剂防治灌浆初期，喷40%氧化乐果乳油 2 000倍液，或50%杀螟丹可湿性粉剂 1 500倍液，或20%甲氰菊酯乳油 4 000～8 000倍液喷雾。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-26/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (117, 'disease_109', '斑须蝽', 'disease', 'type_2_crop_2', '成虫和若虫刺吸嫩叶、嫩茎等部位汁液，严重时致叶片卷曲，嫩茎凋萎。', '(1)世代。吉林每年发生1代，辽宁、内蒙古、宁夏每年发生2代，黄淮以南地区每年发生3～4代。(2)越冬。以成虫在田间杂草、枯枝落叶、植物根际、树皮及屋檐下越冬。(3)气候。冬季气温偏高，雨雪较少，利于成虫越冬。早春气温回升快，特别是4月中旬与5月上中旬气温偏高，降雨量偏少对其发生有利。气温24～26℃、相对湿度80％～85％利其发生。暴风雨对其有冲刷作用，使虫口下降。', '(1)农业防治。小麦与油菜间作、玉米、棉花、大豆、花生等作物插花条带种植，每一条带10～15m，可优化生态环境，创造有利于天敌生存繁衍的条件，提高天敌对斑须蝽的自然控制能力。烟田应及时打顶、抹杈，减少其为害场所，从而降低虫口基数。结合田间管理，人工捕捉成虫，抹杀卵块，消灭未分散的低龄若虫，可减轻田间受害程度。(2)物理防治。利用成虫趋光性，诱杀成虫。在成虫发生期，特别是发生盛期，用黑光灯诱杀，灯下放一水盆，及时捞虫。(3)药剂防治。低龄若虫盛发期喷5％高效大功臣可湿性粉剂1 000～1 500倍液，或10％氯氰菊酯乳油2 000～3 000倍液，或2.5％溴氰菊酯乳油2 000～3 000倍液，或20％甲氰菊酯乳油2 000倍液，若在成虫产卵前连片防治效果更好。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-27/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (118, 'disease_110', '赤须盲蝽', 'disease', 'type_2_crop_2', '赤须盲蝽成、若虫在玉米叶片上刺吸汁液，进入穗期还为害玉米雄穗和花丝，致叶片初呈淡黄色小点，稍后呈白色雪花斑布满叶片。严重时整个田块植株叶片上就象落了～层雪花，致叶片呈现失水状，且从顶端逐渐向内纵卷。心叶受害生长受阻，展开的叶片出现孔洞或破叶，全株生长缓慢，矮小或枯死。', '(1)发生世代。华北地区一年发生3代。(2)越冬及虫源。以卵越冬。', '(1)药剂防治。发生期喷洒16%顺丰3号(氯?灭)乳油 2 000～3 000倍液，或2.5%中保4号乳油 1 000倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-28/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (119, 'disease_111', '朱砂叶螨', 'disease', 'type_2_crop_2', '叶片出现针头大小的褪绿斑，严重时，整个叶片发黄、皱缩，直至干枯脱落。', '(1)世代。朱砂叶螨在北方1年发生12～15代，长江流域18～20代，华南地区每年发生20代以上。(2)越冬。以雌成螨在草根、枯叶及土缝或树皮裂缝内吐丝结网群集越冬，最多可达上千头聚在～起。(3)时期。4月下旬至5月上旬迁入花生田为害，6、7月份为发生盛期，对春花生可造成局部为害，6～8月份进入棉田盛发期。7月中旬雨季到来，叶螨发生量迅速减少，8月份若天气干旱可再次大发生。9月中下旬花生收获后迁往冬季寄生，10月下旬开始越冬。(4)气候。干旱少雨时发生严重。暴雨对朱砂叶螨的发生有明显的抑制作用(5)栽培。轮作田发生轻，邻作或间作瓜类和果树的田块发生较重。', '(1)农业防治。合理安排轮作的作物和间作、套种的作物，避免叶螨在寄主间相互转移为害。以水旱轮作效果最好。加强田间管理，保持田园清洁，及时铲除田边杂草及枯枝老叶并烧毁，减少虫源。干旱时应注意灌水，增加田间湿度，不利于其繁殖和发育。结合田间管理，发现叶螨时，顺手抹掉；若螨量多时，将叶片摘下处理。若整株上多时，可将其拔除，带到田外处理。收获后，及时清除田间残枝、落叶和杂草，集中烧毁。有条件的地方可进行深翻、冬灌，深翻要达30cm以上，冬灌保持田间水深16mm，可杀死～半以上虫口数量。(2)药剂防治。当棉田、花生田被害株率达20％或田间点片发生时，或玉米拔节期以后单株虫量达200头以上时，喷洒药剂防治。药剂可选用15％扫螨净乳油2 500～3 000倍液，或73％克螨特乳油2 000倍液，或20％甲氰菊酯乳油2 000倍液，或20％复方浏阳霉素乳油1 000倍液，或20％螨克乳油2 000倍液，或5％卡死克乳油2 000倍液，或2.5％功夫乳油4 000倍液，或2.5％天王星乳油3 000倍液，或5％尼索朗乳油2 000倍液，或1.8％阿维菌素乳油4 000倍液，或10％吡虫啉可湿性粉剂1 500倍液，或20％三氯杀螨醇乳油1 000～1 500倍液。隔7～10天左右喷1次，连续2～3次。药剂应轮换使用，以免产生抗药性。喷药要均匀，～定要喷到叶背面；另外，对田边的杂草等寄主植物也要喷药，防止其扩散。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-29/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (120, 'disease_112', '截形叶螨', 'disease', 'type_2_crop_2', '若螨和成螨群聚叶背吸取汁液，使叶片呈灰白色或枯黄色细斑，严重时叶片干枯脱落，影响生长，缩短结果期，造成减产。 ', '(1)发生世代。每年发生10～20代。(2)越冬。以雌螨在枯枝落叶或土缝中越冬，在华中地区以各虫态在杂草丛中或树皮缝越冬。(3)发生时期。早春气温达10℃以上，越冬成螨即开始大量繁殖，多于4月下旬至5月上中旬迁入菜田，先是点片发生，随即向四周迅速扩散。(4)环境因素。最适温湿度为29～31℃及相对湿度35%～55%。相对湿度超过70%时不利其繁殖。高温低湿则发生严重，所以以6～8月份为害严重。\r\n', '(1)农业防治。天气干旱时要注意灌溉并合理施肥，减轻为害。(2)药剂防治。大发生情况下喷25％抗螨23(N23)乳油500～600倍液，或73％克螨持乳油1 000～2 000倍液，或25％灭螨猛可湿性粉剂1 000～1 500倍液，或20％甲氰菊酯乳油2 000倍液，或2.5％天王星乳油3 000倍液，或5％尼索朗乳油2 000倍液，或20％双甲脒乳油1 000～1 500倍液，或1.8％阿维菌素乳油抗生素杀虫杀螨剂5 000倍液，或10％吡虫啉可湿性粉剂l 500倍液，或l5％哒螨灵乳油2 500倍液。隔10天左右1次，连续防治2～3次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-30/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (121, 'disease_113', '华北蝼蛄', 'disease', 'type_2_crop_2', '成虫、若虫均在土中活动，取食播下的种子、幼芽或将幼苗咬断致死，受害的根部呈乱麻状。由于蝼蛄的活动将表土层窜成许多隧道，使苗根脱离土壤，致使幼苗因失水而枯死，严重时造成缺苗断垄。', '(1)世代。华北蝼蛄3年左右完成1代。(2)越冬。以成、若虫在土中越冬。', '(1)农业防治。冬春季节耕翻土地，毁坏蝼蛄窝室，冻死越冬蝼蛄。(2)物理防治。在成虫盛发期设置黑光灯诱杀，尤其在温度高、天气闷热、无风的夜晚诱杀效果好。(3)药剂防治。用57％辛硫磷0.25千克，麦麸1.5～2.5千克，加适量水(拌匀成团，撒出去又能散开)，每亩施用2千克，在无风闷热的傍晚施撒效果最佳。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-32/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (122, 'disease_114', '白星花金龟', 'disease', 'type_2_crop_2', '以成虫取食玉米花丝，多在玉米吐丝授粉期至灌浆初期为害，也有的在玉米灌浆盛期成虫啃食玉米籽粒。白星花金龟成虫群集在玉米雌穗上，从穗轴顶花丝处开始，逐渐钻进苞叶内，取食正在灌浆的籽粒。被害玉米穗，花丝脱落，籽粒被食，排出的白色稀粥状粪便污染下部叶片，影响光合作用。被害玉米严重减产，被害穗遇雨水浇淋，易引发病害。', '(1)世代。每年发生1代。(2)越冬。以幼虫在土中越冬。(3)时期。5月上旬出现成虫，发生盛期为6～7月份，9月为末期。', '(1)农业防治。搞好环境卫生，将生活垃圾、农作物秸秆、树叶等有机质及时清理，将厩肥、人粪尿等农家肥及时入田或沤制，通过高温发酵腐熟，杀死虫卵和幼虫，减少成虫产卵繁殖和幼虫生存的场所。在将农家肥、烂柴草、树叶等碎烂有机质入田的过程中，及时捡拾幼虫。在肥水充足、种植大穗型品种的高产玉米田，特别是田块边行的玉米植株，要进行适当密植，促使玉米穗不过大，使玉米苞叶能够将玉米穗顶部完全包住，减少白星花金龟成虫的取食机会。利用白星花金龟成虫的假死性和群聚性，用透明网兜或塑料袋套住被害的玉米穗，人工捕杀成虫。(2)物理防治。利用白星花金龟成虫的趋化性，诱杀成虫。在6～8月成虫发生盛期，将白酒、红糖、食醋、水、90％晶体敌百虫按1:3:6:9:1的比例在盆内拌匀，配制成糖醋液，放置在腐烂有机质较多的场所或玉米田边，架起与玉米雌穗位置大致相同的高度诱杀成虫，其效果较好，同时还可兼诱其他害虫。也可用10mm长的瓶子、竹筒等小口容器，内盛腐熟的果实2～3个，加少许糖蜜，而后悬挂在玉米植株或树干上，诱集成虫，于每日午后3～4时收集成虫杀死。(3)药剂防治。于9月上中旬，玉米灌浆初期，可用80％敌敌畏乳油、50％辛硫磷乳油等药剂100倍液，在玉米穗顶部滴液，可防治白星花金龟成虫的为害，还可兼治棉铃虫、玉米螟等其他蛀穗害虫。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-33/3.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (123, 'disease_115', '亚洲玉米螟', 'disease', 'type_2_crop_2', '幼虫孵化后，一部分潜藏在雌穗着生节以上各叶片的叶腋间，取食积存的花粉和叶腋组织，至4龄后蛀茎为害；绝大部分初孵幼虫集中到雌穗顶端的花丝基部取食为害，在卵量大的年份，一个穗顶上常有数条、甚至十数条幼虫。生活在雌穗顶端的幼虫取食花丝及未成熟的嫩粒，使籽粒残缺不全，并引起霉烂，降低玉米籽粒的品质。至4～5龄时，这些幼虫有的自雌穗顶端蛀入穗轴，有的自雌穗基部蛀入雌穗柄，也有的蛀入雌穗着生节上下的茎秆。但此时玉米已进入灌浆中、后期，雌穗的大小已经定型，所以这～代幼虫主要影响千粒重和籽粒的品质。', '(1)世代。海拔愈高，温度愈低，代数愈少。从北到南该虫一年可发生1～7代。(2)越冬。以老熟幼虫在寄主植物的秸秆、穗轴或根茬中越冬，4龄以下幼虫不能越冬。(3)气候。越冬幼虫随春季气温的逐渐升高而复苏，但必须咬嚼潮湿的秸秆或直接吸食雨水、露滴，取得足够的水分后才能化蛹。成虫羽化后，也必须饮水才能正常产卵，产卵时又要求有较高的相对湿度。越冬幼虫醒眠时，特别是化蛹阶段，低湿可使越冬虫死亡率增高，有效越冬基数下降。(4)栽培。播期早、生长茂盛、叶色浓绿的植株着卵量往往超过一般玉米。不同生育期、品种和播期的玉米上，由于幼虫成活率高低不同，受害轻重也就不同。开花期最易吸引螟蛾产卵；在小花和嫩粒上，幼虫成活率显著较心叶期高。在相同的卵量或虫口密度下，感虫品种(系)受害重，玉米螟幼虫的存活率高。', '(1)农业防治。越冬幼虫羽化以前，处理玉米、高粱、棉花等越冬寄主的茎秆是消灭越冬幼虫、压低越冬虫源基数的有效措施。3代发生区，尽量扩大夏玉米播种面积，压缩玉米、高粱、谷子等寄主作物的春播面积，减少第1代玉米螟的食料来源和繁殖场所，以控制第2、3代发生量和减轻对夏玉米的为害。利用雌蛾喜在高大茂密、生长旺盛的寄主植株上产卵的习性，在春玉米正常播种前1个月左右选择邻近越冬场所的地块种植小面积的诱集带、诱集田，或对少数早播春玉米田块加强肥水管理，促其早发，诱集成虫产卵。种植抗螟品种是～种经济、有效、安全的治螟措施，推广种植丹玉13等抗虫杂交种。与一些作物的田间管理措施结合实施，尤其是间苗、定苗等措施可以直接除虫除卵，与玉米螟的防治关系更为密切。如第1代玉米螟在棉花苗期为害，可结合间苗、定苗去掉有虫株。 (2)物理防治。黑光灯诱杀法。高压诱虫汞灯，具体方法是：在越冬代成虫羽化期，将200或400瓦的高压汞灯安装在村庄内较开阔的地方，灯距150m(用400瓦的灯泡则为200m)。灯泡应装在防水灯头上，用铁丝固定好，灯下面修～直mm的圆形水池、砖结构和水泥结构均可；亦可在灯下挖～同样大小的土坑，坑内铺塑料布，但均以不漏水为准。水池边留～进水口，池内放水6cm深，并加入100克左右的洗衣粉，拌匀。一般每3天换水1次，并另加洗衣粉。如换水时间未到而池中水不足时，可随时添加。灯泡挂在水池中央距水面15cm处为宜。从越冬代成虫的羽化初期至末期，每天20时半开灯，翌日晨4时闭灯。由于诱蛾量通常很大，每天早晨都须将池中的蛾子捞出。(3)生物防治。每年4月中旬至5月初越冬幼虫化蛹前，用白僵菌孢子粉对烧剩的寄主作物秸秆、根茬进行喷粉封垛，菌粉用量为100克/立方米，垛面每平方米喷1个点，至垛面可见菌粉即可。或心叶中期将含菌量为100～500亿/克的白僵菌孢子粉0.5千克与5千克过筛的煤渣拌匀，制成1:10白僵菌颗粒剂，按每株2克施入玉米心叶丛。 用Bt乳剂15克/亩，同52.5千克细砂拌匀制成颗粒剂，在玉米心叶中期施用，防治效果可达80％以上。 采用夏玉米间作绿豆，增加自然界赤眼蜂等螟卵寄生蜂的种群数量，控制螟害的发生。或大量饲养繁殖释放寄生蜂治螟。 此外，还可利用玉米螟的性信息素诱杀雄虫或投放大量性信息素，使雄虫难以找到雌虫，无法交尾。(4)药剂防治。玉米上药剂防治通常掌握在心叶末期及穗期或幼虫低龄期。 施药期应对玉米田逐块检查，把握住心叶末期，药液灌注雄穗。常用药剂有25％杀虫双水剂500倍液，或50％敌敌畏乳油800倍液，或90％晶体敌百虫800～1 000倍液，或50％辛硫磷乳油800～1 000倍液，或50％乙硫磷乳油1 000倍液等。这些药液均按10毫升/株的用量灌注露雄期的玉米雄穗。 春玉米穗期将50％敌敌畏乳剂800倍液灌入小口瓶内，瓶口塞上带细塑料管的瓶塞。在玉米撒粉基本结束，而幼虫尚集中在花丝上为害时，将药液滴几滴在雌穗顶端花丝基部。药液即渗入花丝，熏杀在雌穗顶部为害的幼虫。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-01/3.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (124, 'disease_116', '桃蛀野螟', 'disease', 'type_2_crop_2', '在棉田中，幼虫主要蛀食棉铃，引起烂铃。为害高粱时，初孵幼虫钻入高粱幼嫩籽粒内，用粪便或食物残渣把口封住，在其内蛀害；长大后吐丝结网缀合小穗，藏匿其中蛀食籽粒，也可以蛀食茎杆。为害玉米时，主要蛀食雌穗，啃食玉米籽粒，也可以蛀茎为害。', '(1)世代。我国北方各省每年发生2～3代，南京4代，江西、湖北5代。(2)越冬。老熟幼虫化蛹在穗中或叶腋、叶鞘、枯叶等处越冬。玉米的秸秆里也有一少部分越冬幼虫。(3)气候。多雨高湿年份，发生严重。(4)栽培。紧穗品种重于半紧穗品种，散穗型品种受害最轻。晚播重于早播，夏播重于春播。', '(1)农业防治。冬前玉米要脱空粒，并及时处理玉米寄主的秸秆。(2)药剂防治。产卵盛期喷洒50％磷胺可溶剂1 000～2 000倍液，或50％辛硫磷乳油1 000倍液。提倡喷洒苏云金杆菌75～150倍液或青虫菌液100～200倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-02/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (125, 'disease_117', '棉铃虫', 'disease', 'type_2_crop_2', '低龄幼虫在顶部钻蛀嫩叶，能吐丝缚住未张开的嫩叶在其中啃食叶肉，使叶片仅剩叶膜形成透明状；3龄后蚕食叶片，可将叶片食成缺刻或孔洞，一般损失叶片15%～20%，重者损失50%以上造成严重减产', '(1)世代。由北向南年发生3～7代，在辽宁、河北北部、内蒙古、新疆等地每年发生3代，华北4代，长江以南5～6代，华南地区年生6～8代，世代重叠。(2)越冬。以蛹在寄主植物根际附近的土中越冬。(3)时期。当气温上升至15℃以上时，越冬蛹开始羽化。(3)时期。华北地区4月中下旬出现越冬代成虫，5月上中旬为发生盛期。第1代幼虫于5月下旬至6月下旬为害期，第1代成虫发生期6月中旬。长江流域5～6月份第1代、第2代是主要为害世代。', '(1)农业。不间作棉花、番茄等棉铃虫嗜好植物，以免招引成虫产卵。在棉铃虫发生严重的地区，在第1代成虫发生期，在田间内插杨枝把，诱集成虫，早晨予以捕杀。(2)物理。用黑光灯或高压汞灯诱杀成虫。每亩安300瓦高压汞灯1只，灯下用大容器盛水，水面撒柴油，效果比黑光灯更优。(3)药剂。在卵孵盛期或幼虫低龄期喷Bt菌剂(每克含活孢子100亿)200～300倍液，或1.8%阿维菌素乳油4 000倍液，或l0%吡虫啉可湿性粉剂1 500倍液，或5%抑太保乳油2 000倍液，或25%灭幼脲3号悬浮剂 600倍液，或50%来福灵乳油3 000倍液，或40%辉丰1号乳油1 000倍液喷雾。隔7～10天喷1次，共喷～3次。药剂应注意轮换使用。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-03/3.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (126, 'disease_118', '条螟', 'disease', 'type_2_crop_2', '幼虫咬食心叶叶肉，留下表皮，呈“窗户纸”状，稍大时咬成不规则的小孔。条螟在玉米上的蛀茎部位，多在节间的中部(玉米螟多在茎节附近)，作环状取食茎髓，被害植株遇风折断。', '(1)世代。条螟在辽宁南部、河北、山东、河南及江苏北部每年发生2代，江西发生4代，广东、台湾4～5代。(2)越冬。以老熟幼虫在玉米寄主叶鞘内侧结茧或在茎秆内越冬。(3)气候。生产上遇有越冬幼虫基数大，越冬死亡率低，春雨多，湿度大时，发生重。', '(1)农业防治。收获后及时清理残株、枯叶枯苗，沤制堆肥或烧毁。注意及时铲除地边杂草，定苗前捕杀幼虫。结合烧柴、沤肥、饲料等用途，将玉米等寄主植物的秸秆处理完毕，阻止越冬幼虫羽化。 (2)生物防治。释放赤眼蜂。释放方法和用量，参照玉米螟。此外，用白僵菌菌粉(以菌粉含孢子50亿/克为标准)与炉渣或土颗粒，按1:10的比例配制成颗粒剂，也有良好效果。(3)药剂防治。发现玉米苗受害时，用75％辛硫磷乳油0.5千克对少量水，喷拌120千克细土，也可用2.5％溴氰菊酯配成45～50毫克/千克毒砂，撒施拌匀的毒土或毒砂20～25千克/亩，顺垄低撒在幼苗根际处，使其形成6cm宽的药带。掌握在卵孵盛期喷洒90％晶体敌百虫800倍液，或25％毒死蜱乳油1 000倍液。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (127, 'disease_119', '斜纹夜蛾', 'disease', 'type_2_crop_2', '幼虫食叶为主，也咬食嫩茎、叶柄，大发生时，常把叶片和嫩茎吃光，造成严重损失。 ', '(1)世代。在我国华北地区每年发生4～5代，长江流域5～6代，福建6～9代。幼虫由于取食不同食料，发育参差不齐，造成世代重叠现象严重。(2)越冬。华北大部分地区以蛹越冬，少数以老熟幼虫入土作室越冬；在华南华南地区无滞育现象，终年繁殖；在长江流域以北的地区，越冬问题尚无结论。(3)气候。斜纹夜蛾是～种喜温性害虫，其生长发育最适宜温、湿度条件为温度28～30℃，相对湿度75％～85％。38℃以上高温和冬季低温，对卵、幼虫和蛹的发育都不利。当土壤湿度过低，含水量在20％以下时，不利于幼虫化蛹和成虫羽化。1～2龄幼虫如遇暴风雨则大量死亡。蛹期大雨，田间积水也不利于羽化。(4)栽培。田间水肥好，作物生长茂盛的田块，虫口密度往往较大。土壤含水量在20％以下，对化蛹、羽化均不利。', '(1)农业防治。及时翻犁空闲田，铲除田边杂草。在幼虫入土化蛹高峰期，结合农事操作进行中耕灭蛹，降低田间虫口基数。在斜纹夜蛾化蛹期，结合抗旱进行灌溉，可以淹死大部分虫蛹，降低基数。在斜纹夜蛾产卵高峰期至初孵期，采取人工摘除卵块和初孵幼虫为害叶片，带出田外集中销毁。合理安排种植茬口，避免斜纹夜蛾寄主作物连作。有条件的地方可与水稻轮作。(2)物理防治。成虫盛发期，采用黑光灯、糖醋酒液诱杀成虫。(3)药剂防治。掌握在卵块孵化到3龄幼虫前喷洒药剂防治，此期幼虫正群集叶背面为害，尚未分散且抗药性低，药剂防效高。用虫瘟～号斜纹夜蛾病毒杀虫剂1 000倍液，或1.8％阿维菌素乳油2 000倍液，或5％抑太保乳油2 000倍液，或10％吡虫啉可湿性粉剂1 500倍液，或18％施必得乳油1 000倍液，或20％米满悬浮剂2 000倍液，或52.25％农地乐乳油1 000倍液，或25％菜喜悬浮剂1 500倍液，或10％除尽悬浮剂1 500倍液，或2.5％天王星3 000倍液，或20％氰戊菊酯乳油1 500倍液，或2.5％功夫乳油2 000倍液，或4.5％高效氯氰菊酯乳油1 000倍液，或2.5％溴氰菊酯乳油1 000倍液，或5％氟氯氰菊酯乳油l 000～1 500倍液，或20％甲氰菊酯乳油3 000倍液，或20％菊马乳油2 000倍液，或5％来福灵乳油2 000倍液，或48％毒死蜱乳油1 000倍液，或10％联苯菊酯乳油1 000～1 500倍液，或90％杜邦万灵可湿性粉剂3 000～4 000倍液，或0.8％易福乳油2 000倍液，或15％安打悬浮剂4 000倍液，或35％顺丰2号乳油1 000倍液，或15％菜虫净乳油1 500倍液，或44％速凯乳油1 000～1 500倍液，或2.5％保得乳油2 000倍液，或24％万灵水剂1 000倍液。采取挑治与全田喷药相结合的办法，重点防治田间虫源中心。由于幼虫白天不出来活动，喷药宜在午后及傍晚进行。每隔7～10天喷施1次，连用2～3次。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-05/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (128, 'disease_120', '黏虫', 'disease', 'type_2_crop_2', '初孵幼虫有群集性，1、2龄幼虫多在麦株基部叶背或分蘖叶背光处为害，3龄后食量大增，5～6龄进入暴食阶段，食光叶片或把穗头咬断，其食量占整个幼虫期90%左右。', '(1)世代。一年发生世代数全国各地不～，东北、内蒙古一年发生2～3代，华北中南部3～4代，江苏淮河流域4～5代，长江流域5～6代，华南6～8代。海拔1 000m左右高原1年发生3代，海拔2 000m左右高原则发生2代，各省(区)由于地势不同，世代数亦有一些变化。(2)越冬及虫源。黏虫属迁飞性害虫，其越冬分界线在北纬33°～带，在33°以北地区任何虫态均不能越冬。在江西、浙江～带，以幼虫和蛹在稻桩、田埂杂草、绿肥田、麦田表土下等处越冬。在广东、福建南部终年繁殖，无越冬现象。北方春季出现的在大量成虫系由南方迁飞所至。(3)发生因素。①气候因素。气候因素对黏虫的发生量和发生期影响很大，其中温度和湿度关系尤为密切。春夏向北迁飞扩散时，主要受气流冷暖交锋的影响而造成黏虫的为害程度不同。总的来说，黏虫不耐0℃以下的低温和35℃以上的高温，各虫态适宜的温度在10～25℃之间，相对湿度在85%以上。黏虫是～种喜好潮湿而怕高温和干旱的害虫，高温低湿不利于成虫产卵、发育。但雨水多，湿度过大，也可控制黏虫发生。②栽培因素。凡密植、多雨、灌溉条件好、生长茂盛的水稻、小麦、谷子，或荒草多、大的玉米、高粱地，黏虫发生量就多。小麦、玉米套种，有利于黏虫的转移为害，黏虫发生较重。', '(1)农业防治。①冬季和早春结合积肥，彻底铲除田埂、田边、沟边、塘边、地边的杂草，消灭部分在杂草中越冬的黏虫，减少虫源。②合理布局，实行同品种、同生产期的水稻连片栽种，避免不同品种的“插花”栽培。③合理用肥，施足基肥，及时追肥，避免偏施氮肥，防止贪青迟熟。④科学管水，浅水勤灌，避免深水漫灌，长期积水，适时晒田，可起到抑制黏虫为害、增加产量的作用。(2)生物防治。根据黏虫幼虫具有惊落假死性，在稻田中饲养鸭子可有效地控制黏虫的发生为害。(3)物理防治。①采用多佳频振式杀虫灯或黑光灯诱杀成虫。②根据成虫产卵喜产于枯黄老叶的特性，在田间每hm2设置150把草把，草把可稍大，适当高出作物，5天左右换草把1次，并集中烧毁，即可灭杀虫卵。(4)药剂防治。①根据黏虫成虫具有嗜食花蜜、糖类及甜酸气味的发酵水浆等特性，采用毒液诱杀成虫，其药液配比为糖∶酒∶醋∶水=1∶1∶3∶10，加总量10%的杀虫丹，可以作盆诱或把毒液喷在草把上诱集成虫。②用20%速毙50ml或600～1 000倍液或24%百虫光40～60ml，对水40～60kg，进行均匀喷雾，最后～次用药在收割水稻前10天进行。③或用25%本能1 500倍液，或40%九条虫1 500～2 000倍液，或20%凯杀1200～1600倍液，或25%杀虫双200～250倍液，或20%氰戊菊酯1 000～1 500倍液，或33%水灭氯乳油 1200倍液，或25%快杀灵乳油 800倍液，或90%晶体敌百虫1 000倍液，或20%除虫脲1 200倍液，或48%毒死蜱乳油 500倍液，或40%灭虫清乳油 2 000倍液，或50%辛硫磷乳油 1 000倍液，或20%抑食肼可湿性粉剂 1 000倍液，或0.3%苦参碱水剂 100倍液，或2.5%氯氟氰菊酯乳油 1 000倍液，或25%杀虫双500倍液，或2.5%溴氰菊酯乳油 4 000倍液均匀喷雾，收割水稻前15天停药。(5)预测预报。黏虫是间歇性猖獗的害虫，发生时还有“暴发性”的特点，因此做好预测预报，掌握黏虫田间动态是主动消灭黏虫为害的重要措施。可通过调查成虫、卵、幼虫来预测当年的发生程度。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-06/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (129, 'disease_121', '草地螟', 'disease', 'type_2_crop_2', '初孵幼虫取食叶肉，残留表皮，长大后可将叶片吃成缺刻或仅留叶脉，使叶片呈网状。大发生时，也为害花和幼荚。 ', '(1)世代。年发生2～4代。(2)越冬。以老熟幼虫在土内吐丝作茧越冬。', '幼虫3龄之前喷洒5％的溴氰菊酯2 000～2 500倍液，或用2.5％功夫菊酯乳油1 800～2 000倍液，或用20％的氰戊菊酯乳油1 000～1 500倍液，或2.5％保得乳油2 000倍液，或50％辛硫磷乳油1 500倍液，或20％三唑磷乳油700倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-07/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (130, 'disease_122', '甜菜夜蛾', 'disease', 'type_2_crop_2', '幼虫食叶成缺刻或孔洞，严重的把叶片吃光，仅剩下叶柄、叶脉，对产量影响很大。', '(1)世代。甜菜夜蛾每年发生的代数由北向南逐渐增加。陕西4～5代，北京5代，山东5代，湖北5～6代，江西6～7代，福建8～10代，广东10～11代，世代重叠。(2)越冬。江苏、陕西以北地区，以蛹在土室中越冬；也可以成虫在北方地区温室中越冬；华南地区无越冬现象，可终年繁殖为害。(3)气候。蛹在-12℃以下经数日即死亡。初冬和越冬期死亡是影响春季成虫大发生重要因素。', '(1)农业防治。合理轮作避免与寄主植物轮作套种，清理田园、去除杂草落叶均可降低虫口密度。秋季深翻、冬季打冻水可杀灭大量越冬蛹。早春铲除田间地边杂草，消灭杂草上的初龄幼虫。在虫卵盛期结合田间管理，提倡早晨、傍晚人工捕捉大龄幼虫，挤抹卵块，这样能有效地降低虫口密度。在夏季干旱时灌水，增大土壤的湿度，恶化甜菜夜蛾的发生环境，也可减轻其发生。(2)物理防治。成虫始盛期，在大田设置黑光灯、高压汞灯及频振式杀虫灯诱杀成虫。各代成虫盛发期用杨柳枝把诱蛾，消灭成虫，减少落卵量。利用性诱剂诱杀成虫。(3)药剂防治。甜菜夜蛾低龄幼虫在网内为害，很难接触药液，3龄以后抗药性增强，因此药剂防治难度大，应掌握其卵孵盛期至2龄幼虫盛期开始喷药。药剂选用10％除尽悬浮剂1 000～1 500倍液，或20％米满悬浮剂1 000～1 500倍液，或2.5％悬浮剂1 000～1 500倍液，或5％抑太保乳油3 000～4 000倍液，或25％灭幼脲3号悬浮剂1 000倍液，或20％灭幼脲1号胶悬剂1 000倍液，或1.8％阿维菌素乳油2 000～3 000倍液，或每克含孢子100亿以上的杀螟杆菌粉500～700倍液，或每克含孢子100亿以上的青虫菌粉500～700倍液，或52.25％农地乐乳油750倍液，或20％甲氰菊酯乳油3 000倍液，或2.5％高效氟氯氰菊酯乳油1 000倍液，或10％氯氰菊酯乳油1 500倍液，或44％速凯乳油1 500倍液，或2.5％保得乳油2 000倍液，或25％辛?氰乳油1 500倍液，或50％辛硫磷乳油1 000倍液，或90％晶体敌百虫1 000倍液，或10％夜蛾净1 000～1 500倍液。防治甜菜夜蛾3龄幼虫时，将5％夜蛾必杀乳油和“菊酯伴侣”配套使用，分别稀释2 000倍及500倍液混合后喷雾；防治大龄幼虫，分别稀释1 000倍液和500倍液混合后喷雾，防效均达95％以上。注意喷雾时容易使幼虫假死落地，除注意喷洒到叶背外，还应注意地面。连续施用2～3次，隔5～7天1次。宜在清晨或傍晚幼虫外出取食活动时施药。注意不同作用机理的药剂轮换使用，以延缓抗药性的产生和发展。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-08/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (131, 'disease_123', '粟灰螟', 'disease', 'type_2_crop_2', '幼虫蛀入茎杆取食为害，蛀孔排有少量虫粪和嚼碎残屑。苗期可引起枯心苗。', '(1)世代。长城以北，年发生1～2代，黄淮地区3代，珠江流域4～5代，海南省6代。(2)越冬。以幼虫在谷子、糜、黍根茬里过冬。南方以幼虫或蛹在蔗茎地上部或地下部越冬。(3)气候。少雨干旱为害重。卵盛孵期遇高温干旱，蚁螟侵入率高，为害重。(4)栽培。谷苗株色浅、茎秆细硬、叶鞘茸毛浓密、分蘖力强和后期早熟等品种，在～定程度上能减轻受害。', '(1)农业防治。推广抗虫品种。秋耕时，拾净玉米秸秆，集中深埋或烧毁，以减少越冬虫源。播种期可因地制宜调节，设法使苗期避开成虫羽化产卵盛期，可减轻受害。结合间苗将枯心苗拔除，带出田外深埋。(2)药剂防治。在卵孵盛期至幼虫蛀茎前，喷洒21％灭杀毙1 500～2 000倍液、30％触倒1 500～2 000倍液，或2.5％溴氰菊酯乳油2 500倍液。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-09/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (132, 'disease_124', '东亚飞蝗', 'disease', 'type_2_crop_2', '成、若虫咬食植物的叶片和茎，大发生时成群迁飞，把成片的农作物吃成光秆。 ', '(1)世代。北京以北每年发生1代，渤海湾、黄河下游、长江流域每年发生2代，广西、广东、台湾每年发生3代，海南可发生4代。(2)越冬。各地均以卵在土中越冬。(3)气候。遇有干旱年份，荒地随天气干旱水面缩小而增大时，利于蝗虫生育，宜蝗面积增加，容易酿成蝗灾。', '(1)农业防治。注意兴修水利，疏通河道，排灌配套，做到旱、涝保丰收；提倡垦荒种植，大搞植树造林，创造不利于蝗虫发生的生态条件，使蝗虫失去产卵的适生场所。坚决贯彻执行“改治并举、根除蝗害”的方针，做到从根本上控制蝗灾。因地制宜飞蝗不喜食的作物，如甘薯、马铃薯、麻类等。(2)生物防治。使用蝗虫微孢子虫、绿僵菌等防治，效果较好，且对天敌安全。(3)药剂防治。药剂防治要根据发生的面积和密度，做好飞机防治与地面机械防治相结合，全面扫残与重点挑治相结合，夏蝗重治与秋蝗扫残相结合。于蝗蝻3龄以前，喷洒4.5％高效氯氰菊酯乳油1 500～2 000倍液、20％氰?马乳油1 500倍液、25％敌马乳油500倍液，或50％马拉硫磷乳油800倍液。大面积发作时，用25％快杀灵乳油1 200倍液采取飞机喷雾。最佳施药方法为飞机飞行高度为10m，有效喷幅100～150m。', 'https://bcch-1307281066.cos.ap-beijing.myqcloud.com/bcch.ahnw.cn/UploadFiles/ls-ymc-16/2.JPG', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (133, 'disease_125', '黄星蝗', 'disease', 'type_2_crop_2', '成虫和若虫食害寄主的叶片、嫩芽、花朵、小枝。为害逐渐加重。 ', '辽宁年生2代，以末龄幼虫在土下20～25cm处越冬，翌年5月化蛹、羽化为成虫，6月产卵，7月上旬至8月中旬进入幼虫活动期，8月中旬至下旬化蛹、羽化，进入9月初又产卵、孵化为幼虫，10月幼虫进入老熟状态，入土化蛹。', '(1)越冬幼虫开始为害时，在土表撒施2．5％辛硫磷粉剂或5％杀虫畏药土，后锄或耙入土中或灌水，使药液渗入土中。(2)必要时浇灌0．6％无名霸(苦参烟碱醇液)1000～1500倍液。(3)发现为害时，可在地面堆放拌有低毒农药的新鲜菜叶，诱集幼虫，集中消灭。', 'https://www.ldbeike.com/imgs/J/J07007/j07007.0127.7[41c89a48034e].jpg', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (134, 'disease_126', '小麦冻害', 'disease', 'type_3_crop_1', '轻度冻害表现为小麦叶尖发黄，主茎 2-3 片叶的叶尖受冻；中度冻害时小麦叶片一半以上面积发黄，主茎叶片枯黄，穗粒数减少；重度冻害则导致小麦田间全部发黄，主茎和分蘖基本冻死，茎秆部分冻裂，幼穗失水萎蔫。', '冬季寒潮降温、早春小麦返青期遇寒潮，或小麦孕穗期环境气温长时间维持在零度左右，均易引发冻害。', '选择抗寒能力较强的小麦品种。适时浇好越冬水，冬季冻害发生后可追施氮肥。早春对生长过旺的小麦做好镇压工作，起身期喷施助壮素。低温来临前及时灌溉，遭受冻害后及时浇水追肥。', 'http://nyncj.xiangyang.gov.cn/hdjl/hygq/202412/W020241230417207043059.jpg', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (135, 'disease_127', '小麦干热风害', 'disease', 'type_3_crop_1', '小麦叶子发黄、杆枯、结实不完全，灌浆期缩短，灌浆量减少，出现早期枯黄，千粒重下降，严重影响产量。', '在小麦灌浆到成熟阶段，遇到高温、干旱和强风力天气，持续 2-5 天温度维持在 32℃左右，田间相对湿度降低，风速在 3 级左右时易发生。', '适时灌溉，增加田间湿度。选择抗逆性强的小麦品种，适时早播，增施有机肥。从抽穗到乳熟期，喷施 1%-2% 的尿素溶液、2%-4% 的过磷酸钙溶液等叶面肥 2-3 次。', 'https://ts1.tc.mm.bing.net/th/id/R-C.c45b57d9f569c92378c9e9248b407975?rik=aHJ0MTTzMAeAiA&riu=http%3a%2f%2fimage.uczzd.cn%2f8019013051432776022.jpg%3fid%3d0%26from%3dexport&ehk=8KJq7N8nDJMSkE4UOFFxxMkZ1bKPDjrU3znnauGGBiQ%3d&risl=&pid=ImgRaw&r=0', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (136, 'disease_128', '小麦缺素症', 'disease', 'type_3_crop_1', '缺氮时，植株矮小瘦弱，叶片窄小直立，叶色淡黄绿色，老叶叶尖干枯；缺磷时，叶片呈现暗绿色，无光泽，严重时叶片、叶鞘发紫；缺钾时，麦苗下部老叶的叶尖、叶缘先变黄，而后逐渐变褐色，远看似火烧状；缺钙时，生长点及茎死亡，幼叶常不展开，叶片发黄；缺镁、缺铁等也会有相应的叶片发黄等症状。', '农民盲目施肥，不能根据田间肥力条件科学施肥，导致土壤中某些营养素过量，而某些元素不足。', '缺氮时，结合灌水或降雨追施尿素 8-10kg / 亩；缺磷时，追施磷酸二铵 8-10kg / 亩；缺钾时，追施氯化钾或硫酸钾 3-5kg / 亩；缺钙时，用 0.1% 氯化钙溶液进行叶面喷施；缺镁时，用 0.3-0.5% 硫酸镁溶液叶面喷施；缺铁时，用 0.2-0.3% 硫酸亚铁溶液叶面喷施。', 'https://so1.360tres.com/t01fd20dda1caee8b4a.jpg', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (137, 'disease_129', '小麦生理性发黄', 'disease', 'type_3_crop_1', '田间表现为整块田发黄不均匀，发黄成片发生且程度不均，苗期黄化瘦小，分蘖少而弱，幼苗叶片发黄，中后期叶色褪淡、叶片下垂，抽穗时间长，严重缺肥时植株不能正常抽穗，最后枯黄。', '施肥方法不正确，如 “一炮轰” 式施肥；小麦根系病变吸收能力减弱；叶面补施不及时；秸秆腐熟消耗营养等。', '合理施肥，根据小麦生长阶段按需追肥，注重叶面肥施用，改善土壤环境，促进根系生长，确保秸秆腐熟良好或控制还田量。', 'https://www.chinaseed114.com/file/upload/202205/07/084713821.png', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (138, 'disease_130', '小麦白穗病', 'disease', 'type_3_crop_1', '麦穗呈现白色，穗粒发育不良，严重时整穗枯死。', '穗分化期遇到倒春寒等低温天气；秸秆还田质量不好，秸秆腐解不完全或土壤中碳素物质过多、氮素相对缺乏；小麦生长后期遭遇干热风等气象灾害。', '选择抗寒、抗干热风品种，合理安排农事操作，避免在低温时段进行穗分化相关管理。确保秸秆还田质量，可添加适量氮肥加速秸秆腐熟。在干热风来临前，适时浇水，调节田间小气候，也可喷施叶面肥增强小麦抗逆性。', 'https://ts1.tc.mm.bing.net/th/id/R-C.0adab62e7f86b57d7cf82868e49d5858?rik=CkR3zmXwtldmzQ&riu=http%3a%2f%2fn.sinaimg.cn%2fsinakd20210505ac%2f40%2fw480h360%2f20210505%2f6a41-kppteat0152331.jpg&ehk=9s6Fsm5jZ%2fkbXFyeYnI0tCb4vzm8Bk%2b1Ly0ZwPg4tFY%3d&risl=&pid=ImgRaw&r=0', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (139, 'disease_131', '小麦药害', 'disease', 'type_3_crop_1', '叶片出现斑点、黄化、畸形、枯萎等，生长受到抑制，植株矮小，发育不良，严重时可能导致死苗。例如，喷施除草剂不当可能会使叶片出现不规则黄斑、皱缩卷曲。', '农药使用浓度过高、施药时间不当、施药方法错误，或前茬作物残留药剂影响后茬小麦等，都可能引发药害。如在小麦苗期喷施较强毒性的除草剂，且浓度过大，易造成药害。', '合理选择农药，严格按照说明书使用，避免在高温、低温等不良天气下施药。发生药害后，可及时喷施清水冲洗叶片，或根据药害情况喷施植物生长调节剂（如芸苔素内酯）和叶面肥，促进小麦恢复生长。', 'https://ts1.tc.mm.bing.net/th/id/R-C.422543dfc876430c994902e94f8fcc50?rik=TzIkC8O7jQcO%2fg&riu=http%3a%2f%2fatt.191.cn%2fattachment%2fthumb%2fMon_0804%2f63_12639_130622b5ac5e7d8.jpg%3f218&ehk=VL6Mop5gC8BTOt4zd9HmADfSee146iLPlworOtU9VhQ%3d&risl=&pid=ImgRaw&r=0', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (140, 'disease_132', '土壤酸碱度不适引起的病害', 'disease', 'type_3_crop_1', '小麦适宜在中性至微酸性的土壤中生长。土壤过酸或过碱时，会影响小麦对养分的吸收，导致叶片发黄等症状。在酸性土壤中，铁、铝等元素溶解度增加，可能对小麦产生毒害；碱性土壤中，磷、锌等元素有效性降低，小麦会因缺素发黄。例如在北方一些盐碱地，小麦常因碱性过重而叶片发黄，且可能伴有白色盐霜。', '长期不合理的耕作或过度使用化肥，可能导致土壤酸化或碱化。此外，本身处于酸性或碱性土壤地区，若未对土壤进行改良，也容易出现此类问题。', '对于酸性土壤，可撒施石灰调节酸碱度，一般每亩用量 50-100 公斤。碱性土壤可增施有机肥，如腐熟农家肥，每亩 2-3 立方米，既能改良土壤结构，又能缓冲土壤酸碱度，促进小麦根系对养分的吸收。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (141, 'disease_133', '小麦旺长', 'disease', 'type_3_crop_1', '植株生长过于繁茂，叶片宽大嫩绿，茎秆细弱，群体密度过大，容易发生倒伏，后期还可能影响结实率，导致产量降低。', '播种量过大、施肥过多（尤其是氮肥过量）、温度适宜且光照充足等情况下，小麦容易出现旺长现象。', '合理控制播种量，避免过度密植。科学施肥，控制氮肥施用量，增施磷钾肥。对于旺长麦田，可在冬前或早春进行镇压，抑制地上部分生长，也可喷施植物生长调节剂，如多效唑等，控制植株生长速度。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (142, 'disease_134', '小麦穗发芽', 'disease', 'type_3_crop_1', '小麦在收获前，遇到阴雨天气，穗部籽粒在穗上发芽，影响小麦的产量和品质，发芽的籽粒淀粉含量降低，蛋白质含量也可能发生变化，加工品质变差。', '小麦成熟期遭遇连续降雨，空气湿度大，温度适宜（一般 20℃左右），种子含水量达到一定程度（通常高于 30%）时，容易引发穗发芽。', '选择抗穗发芽能力强的品种。合理安排播种期，使小麦成熟期避开雨季。在小麦成熟前，注意清理田间沟渠，及时排水，降低田间湿度。收获后及时晾晒或烘干，降低籽粒含水量。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (143, 'disease_135', '缺氮症', 'disease', 'type_3_crop_2', '玉米生长缓慢，株型矮小，茎细弱。叶片由下而上失绿黄化，从叶尖沿叶脉向基部扩展，先黄后枯，呈 “V” 形，中下部茎秆常有红色或紫红色，果穗变小，缺粒严重，成熟提早，产量和品质下降。', '土壤有机质含量少，低温或淹水，特别是中期干旱或大雨后，易出现缺氮症。', '培肥地力，提高土壤供氮能力。大量施用碳氮比高的有机肥料时，注意配施速效氮肥。翻耕整地时，配施一定量的速效氮肥作基肥，对地力不均引起的缺氮症，要及时追施速效氮肥，必要时喷施叶面肥。\r\n培肥地力，提高土壤供氮能力。大量施用碳氮比高的有机肥料时，注意配施速效氮肥。翻耕整地时，配施一定量的速效氮肥作基肥，对地力不均引起的缺氮症，要及时追施速效氮肥，必要时喷施叶面肥。\r\n', 'https://www.dedemu.cn/upload/pdfImage/20220119/451a38e4d91140ff48b9a523180cdaf6.png', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (144, 'disease_136', '缺磷症', 'disease', 'type_3_crop_2', '幼苗期叶片呈暗绿色，随着缺磷程度加重，从叶尖开始逐渐变为紫红色，整个叶片颜色不均匀。成株期叶片会出现紫色条纹，尤其是叶尖和叶缘处更为明显，严重时叶片会变得干枯。植株生长缓慢，矮小瘦弱，根系发育不良，次生根少且细弱。', '土壤中磷元素含量不足，或者土壤酸碱度不适宜，影响玉米对磷的吸收，如酸性土壤中磷容易被固定。此外，施肥不当，长期大量施用氮肥而忽视磷肥的补充，也会导致土壤中磷元素缺乏。', '及时补充磷肥，可在基肥中施入过磷酸钙、钙镁磷肥等，也可在生长期间叶面喷施磷酸二氢钾等磷肥溶液。对于酸性土壤，可施用石灰等调节土壤酸碱度，提高磷的有效性。', 'https://www.dedemu.cn/upload/pdfImage/20220119/451a38e4d91140ff48b9a523180cdaf6.png', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (145, 'disease_137', '缺钾症', 'disease', 'type_3_crop_2', '玉米根系发育不良，植株生长缓慢，叶色淡绿且有黄绿色条纹，严重时叶缘和叶尖呈现紫色，随后干枯呈灼烧状，叶片中间部分仍可保持绿色，叶片逐渐变皱。植株表现为瘦弱、易感病、易倒折，果穗发育不良、秃顶严重、子粒中淀粉含量少。', '一般沙土含钾低，如前作为需钾量高的作物，易出现缺钾情况。此外，沙土、肥土、潮湿或板结土易发病。', '可在苗期将氧化钾与氮肥一起追施，补充钾元素。', 'https://www.dedemu.cn/upload/pdfImage/20220119/451a38e4d91140ff48b9a523180cdaf6.png', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (146, 'disease_138', '缺锌症', 'disease', 'type_3_crop_2', '玉米 3-5 叶期，白色幼苗开始显现，新生的幼叶呈淡黄色至白色，特别是叶基部 2/3 处更为明显。严重时幼苗老龄叶出现微小的白色斑点，并迅速扩大，形成局部的白色区域或坏死斑块，叶肉坏死，叶面半透明，似白绸或塑料膜，风吹易断。', '土壤或肥料中含磷过多，酸碱度高、低温、湿度大或有机肥少的土壤易发生缺锌症。', '基施硫酸锌，拌细土混匀，于播种前撒入播种沟或穴内；也可用硫酸锌溶液拌种。还可在苗期、拔节期喷施硫酸锌溶液。\r\n', 'https://www.dedemu.cn/upload/pdfImage/20220119/451a38e4d91140ff48b9a523180cdaf6.png', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (147, 'disease_139', '白化苗', 'disease', 'type_3_crop_2', '叶片上有白色条纹，严重时全株叶片发白。', '主要原因是土壤中缺锌，低温多雨、光照不足时易发生。', '播种时，将硫酸锌与细土混合均匀撒在种子旁边预防。发生白化苗时，可叶面喷施硫酸锌溶液，每隔 7 天喷 1 次，连喷 2-3 次。', 'https://ts1.tc.mm.bing.net/th/id/R-C.5697e738183c851c6cedb69f04f3af5e?rik=Cp6r6bwUJ77JSQ&riu=http%3a%2f%2fatt.191.cn%2fattachment%2fMon_1003%2f2_49630_265f54e2f41f6f6.jpg&ehk=ptsIGDN%2fj8tf5xkgmRx3Rp8pRK7y4A2NX4O7nuBekl4%3d&risl=&pid=ImgRaw&r=0', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (148, 'disease_140', '心叶卷曲', 'disease', 'type_3_crop_2', '玉米苗期开始出现症状，叶片卷曲呈桶状，新叶和穗雄抽不出来，玉米植株歪倒。卷曲症状随玉米生长逐渐恢复，但恢复的植株果穗变小，籽粒不饱满，减产明显。', '苗期低温受冻时间长，病株率越高。玉米播种越早病株越多，且不同品种间发病轻重有差异。', '适时播种，不要过早种植玉米。选种不发病或发病轻的品种。\r\n', 'https://ts2.tc.mm.bing.net/th/id/OIP-C.ZzYxLDPgKpS0fyLLJZJU6wHaNK?r=0&cb=thvnextc1&rs=1&pid=ImgDetMain&o=7&rm=3', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (149, 'disease_141', '空秆', 'disease', 'type_3_crop_2', '植株不结果穗或有果穗而无子粒。苗期基部为圆形，叶片发紫，顶端浓绿发紫，叶脉相间有白色透明的斑点或条痕，拔节期植株细弱矮小，叶片淡绿、窄长，与茎的夹角小。', '过度密植，植株之间生长不平衡，肥水供应不能满足玉米生育的需求，或不良气候条件（干旱、雨水过多）等，都会导致空秆率增加。', '合理密植，根据品种特性、地力等确定适宜种植密度。保证肥水供应，满足玉米生长需求。', NULL, '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (150, 'disease_142', '倒伏', 'disease', 'type_3_crop_2', '有茎倒、根倒和茎折 3 种类型。茎倒表现为茎秆倾斜或弯折；根倒是根系发育不良，遇雨水过多或大风而倒；茎折多发生在抽雄前，茎秆组织脆嫩或遭虫害，遇风折断。', '品种自身抗倒性弱，高秆品种易倒。密度不合理，田间通风透光不良，茎秆发育不良。此外，拔节期肥水过多，特别是氮肥过量，或播种过浅，中耕培土不及时，导致根系发育不良，也易引发倒伏。', '选择抗倒性强的品种，合理密植，科学施肥，避免拔节期氮肥过量，及时中耕培土，促进根系发育。', 'https://ts1.tc.mm.bing.net/th/id/R-C.e81dd73be737d0ab68261c1495afc943?rik=q%2fpPROhJTJoTYg&riu=http%3a%2f%2fpic.weather.com.cn%2fimages%2fguangxi%2fphoto%2f2019%2f05%2f20%2f20190520204325A017561D611E76D40E9603D5B763A5A1.jpg&ehk=UToiYTLOze8lL%2bQslXZnY02BSTRD7aIppFHi9SnLer4%3d&risl=&pid=ImgRaw&r=0', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (151, 'disease_143', '缺镁症', 'disease', 'type_3_crop_2', '幼苗上部叶片发黄，叶脉间出现黄白相间的褪绿条纹，下部老叶尖端和边缘呈紫红色，甚至枯死，全株叶脉间出现黄绿条纹或矮化。', '土壤酸度高或受到大雨淋洗后的沙土易缺镁，含钾量高或因施用石灰致含镁量减少的土壤易发病。', '可施用石灰等碱性物质调节土壤 pH 值，增施含镁肥料如硫酸镁，合理灌溉，控制土壤钾含量，改善土壤结构。', 'https://www.dedemu.cn/upload/pdfImage/20220119/451a38e4d91140ff48b9a523180cdaf6.png', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (152, 'disease_144', '缺铁症', 'disease', 'type_3_crop_2', '上部叶片脉间失绿，呈条纹花叶，心叶症状重，严重时心叶不出，生育延迟，甚至不能抽穗。', '碱性土壤中易缺铁。', '可施用硫酸亚铁等含铁肥料，或喷施含铁的叶面肥。', 'https://ts1.tc.mm.bing.net/th/id/R-C.5b54bfd61a13af32027579aef94a1862?rik=9GCCg8GdGgkGOA&riu=http%3a%2f%2fimg.mp.sohu.com%2fupload%2f20170617%2f3d3f5250e26b4e5f82bd764fe4bcfd71_th.png&ehk=7NzETc%2ff8Kq7P%2bQD2G2%2fTJPXGWBd0hiqOiWHrUBgSvk%3d&risl=&pid=ImgRaw&r=0', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (153, 'disease_145', '缺硫症', 'disease', 'type_3_crop_2', '植株矮化、叶丛发黄，成熟期延迟，叶片呈淡绿色或黄绿色，新叶重于老叶，叶片变薄。', '酸性沙质土、有机质含量少或寒冷潮湿的土壤易发病，长期不施或少施含硫肥料也会导致缺硫。', '施用含硫肥料，如石膏，每公顷施用量 150-225 千克，也可灌溉含硫而不超标的工业污水。\r\n', 'https://www.dedemu.cn/upload/pdfImage/20220120/1d34a7d44fc2e13db4aed9464f754582.png', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (154, 'disease_146', '僵叶苗', 'disease', 'type_3_crop_2', '主要出现在幼苗 3 叶期前，秧苗株形细小，叶片淡绿，黑根多，软绵萎缩。移栽后，老叶先枯死，除新叶绿色外叶发黄发僵，抗逆性差，容易死叶死苗。', '苗期肥料使用不当，如大量使用尿素作底肥，磷肥未沤制，土壤湿度过高或过低等。', '苗期肥料应以有机肥为主，少用或不用尿素作底肥，磷肥要经过沤制后施用，保持土壤适宜湿度。已出现僵苗的要加强水肥管理，严重的则应及时补苗。\r\n', 'https://www.ldbeike.com/imgs/K/K05016/k05016_tm.txt.578960.jpg', '2025-07-31 17:04:38');
INSERT INTO `ld_disease_knowledge_nodes` VALUES (155, 'disease_147', '死苗和弱苗', 'disease', 'type_3_crop_2', '玉米发芽受阻，幼苗不能正常生长，植株矮小，叶片衰弱黄瘦，生长停止，形成弱苗，甚至死苗。', '播种过深或过浅、土壤结构不良、播种过早、播量不当或地下害虫危害等。', '精细整地，适期播种，合理控制播量，防治地下害虫，提高播种质量。', 'https://ts1.tc.mm.bing.net/th/id/R-C.459fcaf09c46a3a6c36bebb712a14c67?rik=i3aIw6Arx3zCHw&riu=http%3a%2f%2fk.sinaimg.cn%2fn%2fsinacn20190625s%2f271%2fw640h431%2f20190625%2fb810-hyvnhqq8455299.jpg%2fw700d1q75cms.jpg&ehk=ElZp40BQTnx3w4yQJUrfxmAJ8nbveuso%2fN63uCOhhVU%3d&risl=&pid=ImgRaw&r=0', '2025-07-31 17:04:38');
