INSERT INTO `park` VALUES (3, '马庄园区2', '种植冬枣', '2026-02-03 15:35:59', '2026-07-09 09:32:00', 1, NULL, '泰安', '101120801');
INSERT INTO `peachbaike` VALUES ('中华寿桃', '中华寿桃是从中国北方冬桃自然芽变中选育出的新品种。此品种被誉为桃中极品，是发展绿色食品和出口创汇的优良品种，在各地该品种综合性状表现较好。该桃为我国特有，在发展我国特色优质水果，开拓国内外果品市场方面具有极其重要的意义。', '中华寿桃在山东莱西种植面积颇大，仍在扩繁种植，1987年在山东省各地有较大面积推广并定名。属北方桃品种群。', '该桃属极晚熟品种，在桃果市场淡季之际，于10月初陆续到11月收获，具有极大的市场潜力。', 'data:image/png;base64,', '中华寿桃抗寒性强。花芽冻死率低；抗旱，不耐涝，耐瘠薄，在山滩地上种植，只要注意土壤改良，排水畅通，仍可获得丰产。', 1);
INSERT INTO `peachbaike` VALUES ('中桃红玉', '中桃红玉果实近圆形，无果尖；缝合线宽深中等，两侧较对称，成熟度一致。平均单果质量186.3g，最大果267.0g。果皮底色乳白，茸毛中等，成熟时果面全红。果皮厚度中等，难剥离。果肉白色，硬溶质，汁液多，风味甜，有香气，可溶性固形物含量13.5%。鲜食品质极佳。果实耐贮运，着色早，采摘期较长。', '中桃红玉主要分布在中国的湖南、广西、江西、福建等地区。湖南省的道县、桃江县等地是中桃红玉的主要产地之一，其产量和质量在国内享有盛誉。', '在泰安地区露地栽培，中桃红玉3月中旬叶芽萌动，4月初开花，6月底果实成熟，11月中下旬落叶。果实发育期90天左右需冷量600小时，全年生育期约250天。', 'data:image/png;base64,', '中桃红玉在泰安表现出良好的抗逆性及适应性。对白粉病、细菌性穿孔病均具有较强抗性。根据连续多年观察，该品种具有良好的抗寒及耐旱能力，可抵御冬季低温，坐果率不受影响春旱时抗旱能力较突出，在连续多雨的年份未发现裂果现象在泰安地区表现出良好的栽培适应性', 2);
INSERT INTO `peachbaike` VALUES ('中油21', '中油21号油桃果实口感好、果肉饱满、汁水丰富，具有浓郁香味，甜度在20%左右。果形圆整，套袋后，果面金黄色，十分美观。单果重205-310克，可溶性固溶物18-20%，甜香味浓，品质上。离核。有花粉，丰产，深受消费者喜欢', '中油21号油桃的主要分布地区应该是中国的油桃产区，如山东、河北、河南、陕西等省份。这些地区气候适宜，土壤肥沃，适合油桃的生长。', '中油21号油桃是特晚熟油桃品种，成熟时间一般是在9月下旬，果肉金黄，单果的重量在205~310克之间，生长周期为170天。中油21号油桃可以在树上挂果20天以上。', 'data:image/png;base64,', '中油21号油桃做为一种市场前程较好的水果品种，具备着广阔的种植前程和市场前程。在农民朋友们的勤劳努力下，相信这类品种的产量和质量会持续获得提升，为消费者带来更加美味的味觉享受。', 3);
INSERT INTO `peachbaike` VALUES ('中油蟠7号', '油蟠桃品种中国农业科学院郑州果树研究所最新培育的大果浓甜型油蟠桃新品种。中油蟠7号，果个大，丰产性好。果形扁平，平均单果重300克，大果350克。果肉黄色，硬溶质、致密，风味浓甜，可溶性固形物16%，品质上。粘核。', '黄河流域。', '7 月中下旬果实成熟，果实扁平形，单果重220克；果面干净，亮红，基本不裂果；果肉橙黄色，肉质为硬溶质，果实风味浓甜，可溶性固形物含量最高达20%，铃型花，有花粉，自花结实，丰产。', 'data:image/png;base64,', '幼树偏旺，注意控制树势，以便获得好的早期产量；成龄树要保持较旺树势，避免阳光直射果面引起的果面粗糙；套袋栽培果实更为漂亮。', 4);
INSERT INTO `peachbaike` VALUES ('中秋蜜', '中秋蜜桃4月初开花结果, 果实中秋节前后成熟，果重450--650克，果实圆型，果型端正，果色全面着鲜红色，浓甜如蜜,时值中秋，市场售价高, 是供应中秋佳节市场的高档果品,有极高的发展前景。', '华东地区：山东、江苏、安徽、浙江、福建、上海市', '山东地区中秋节、国庆节成熟', 'data:image/png;base64,', '每亩种植66颗左右，成熟季节正值中秋、国庆佳节，市场潜力巨大', 5);
INSERT INTO `peachbaike` VALUES ('中蟠', '果实呈扁平形，两半部对称，果顶稍凹入，梗洼浅，缝合线浅而明显，果皮有短毛，不能剥离，底色为黄色，果面80%以上着鲜红色晕，十分美观。成熟状态一致；平均单果重250克，大果300克以上；果皮有毛，底色黄，果面80%以上着鲜红色晕（套袋果全黄），十分美观，皮不能剥离；果肉橙黄色，肉质为硬溶质，耐贮运；纤维中等；果实风味浓甜，有香味，可溶性固形物含量15%。粘核。该品种需冷量650h左右。6月底成熟；15天不软。', '该品种适宜在黄河流域露地栽培；也适宜在辽宁、新疆等地区保护地栽培；在南方多雨省份须使用套袋栽培技术。最好在城市近郊发展。', '通常在7月下旬到9月中旬时期成熟', 'data:image/png;base64,', '河南郑州地区果实7月中下旬成熟，需冷量800小时。平均单果重180 克，大果重240 克；果肉橙黄色，肉质为硬溶质，耐运输；果实风味浓甜，可溶性固形物含量14%，有香味，黏核。花为铃型，自花结实。', 6);
INSERT INTO `peachbaike` VALUES ('寿桃', '中华寿桃是从中国北方冬桃自然芽变中选育出的新品种。此品种被誉为桃中极品，是发展绿色食品和出口创汇的优良品种，在各地该品种综合性状表现较好。该桃为我国特有，在发展我国特色优质水果，开拓国内外果品市场方面具有极其重要的意义。', '中华寿桃在山东莱西种植面积颇大，仍在扩繁种植，1987年在山东省各地有较大面积推广并定名。属北方桃品种群。', '该桃属极晚熟品种，在桃果市场淡季之际，于10月初陆续到11月收获，具有极大的市场潜力。', 'data:image/png;base64,', '中华寿桃抗寒性强。花芽冻死率低；抗旱，不耐涝，耐瘠薄，在山滩地上种植，只要注意土壤改良，排水畅通，仍可获得丰产。', 7);
INSERT INTO `peachbaike` VALUES ('早红5号', '果扁圆形，果顶略凹，无柱突，纵横径2.5—4.5厘米×3.5—5.5厘米，重40—60克，深橙黄至橙红色，平滑，光亮，皮厚2—3毫米，瓢囊8—9瓣，汁少味甜，不甚化渣，回味微带苦；种子约15粒。果期10月上旬。属朱橘类。', '山东等地', '果实熟期在6月底至7月初，比一般的桃子提前了一个月左右。', 'data:image/png;base64,', '', 8);
INSERT INTO `peachbaike` VALUES ('晚9', '属于水蜜桃，鲜食，果实圆形，果顶平，缝合线明显，平均单果重205克，最大果重341克，果肉硬度11.1千克/平方厘米，果皮底色黄白，果面光洁，全面着色艳红至深红，果肉底色白，散生玫瑰红点，近核处红色，不溶质，浓甜，有香味，可溶性固形物12%～14%，可滴定酸含量0.22%，粘核，核小，贮运性强，抗逆性强。果肉质细脆甜，有香味。对流胶病和穿孔病抗性较强，抗寒抗冻。', '适宜在山东桃产区种植。', '八月下旬', 'data:image/png;base64,', '晚9号桃树品种自花结实，坐果率高，生产中要严格，疏花疏果、控制树体负载量。', 9);
INSERT INTO `peachbaike` VALUES ('油桃48', '新48油桃属于早熟黄肉鲜食桃新品种，果实圆整，果实的发育期为65-68天。其果实和果肉成熟后呈金黄色，形状较圆整，口感较脆，非常有韧劲，风味酸甜，有浓郁的香气。该品种风味较佳，品质上乘，丰产性好，非常受市场欢迎。', '主产区以山东、河北等北方地区为主', '山东地区6月初成熟', 'data:image/png;base64,', '新48油桃比早4号早熟3-5天，硬度比早4号大，口感好，成熟后挂树期20天没问题，釆收头茬果后树上果膨果快，去年同金铭一起采收完成，软果很少。', 10);
INSERT INTO `peachbaike` VALUES ('玉妃', '玉妃桃是美国选育的品种，它结果较早并且非常高产，果实的品质非常优异，抗疾病的能力很强。它的果实是大果型，果实呈扁平状，果面的颜色为鲜红色，果肉的颜色为白色，玉妃桃离核，有红色素的积累，果实的硬度较大，比较适合长途运输，易储藏。平均果实的重量在170g，表面的桃毛非常少。', '主要分布地区包括中国的河北、山东、河南、陕西等油桃产区', '成熟期在7月底。', 'data:image/png;base64,', '玉妃桃最大的优势在于抗寒性比较优秀，花期冻害极少，果实硬度高耐贮存运输，挂果时长40天左右，色泽艳丽，果面全红色，属于大果桃，均重可达一斤，在中熟桃品种中可谓比较优秀。而且硬质桃常见的裂果现象在玉妃的种植过程中尚未发现。', 11);
INSERT INTO `peachbaike` VALUES ('瑞光39', '瑞光39号’系‘华玉’×‘顶香’杂交育成的晚熟油桃新品种。果实发育期为132d;果实近圆形,平均单果质量202g,大果质量284g;果面近全红;果肉白色,硬溶质,风味浓甜,可溶性固形物含量13%。粘核。丰产。花蔷薇形,有花粉。', '适合在北京、河北、山东、河南、辽宁、山西、陕西等适宜桃栽培的生态区域种植。', '在北京地区8月下旬成熟', 'data:image/png;base64,', '树势中庸，树姿半开张。一年生枝阳面红褐色，背面绿色。叶长椭圆披针形，长16.98厘米，宽4.41厘米，叶柄长1.08厘米。叶面微向内凹，波状。叶尖渐尖，微向外卷。叶基楔形近直角。叶缘为钝锯齿。蜜腺肾形，3~4个。', 12);
INSERT INTO `peachbaike` VALUES ('瑞蟠', '亲本：幻想×蟠桃4号。果实扁平型，果个均匀，平均果重236克-300克，果面紫红色，50%-70%着色，果肉黄白色，属于硬溶质桃，多汁风味甜，黏核，可溶性固形物含量13.5%。', '北京、山东、河北、河南、山西、陕西、辽宁等地区', '9月中旬成熟', 'data:image/png;base64,', '瑞蟠21号由幻想和蟠桃4号杂交，早在1996年就已经得到极晚熟蟠桃新品种，在2006年正式审定命名，思赜农业提醒广大果农，经过严格审定的品种有着靠谱的果实表现性，以及良好的适应能力和抗病能力。', 13);
INSERT INTO `peachbaike` VALUES ('边河脆桃', '边河脆桃是具2009年选出的优良硬溶质桃新品种，果大色红平均单果重400克，最大680克；果面全红（套袋果更鲜艳），着色后挂树1个月不变软。脆甜离核含可溶性固形物13—18%，脆甜、清香、全离核。', '河北、山东、河南、陕西等省份', '成熟期8月中旬至9月中旬', 'data:image/png;base64,', '发展前景广阔成熟期市场鲜桃数量少，优良品种更少，又在中熟苹果成熟之前，中秋节前后，市场需求量大。', 14);
INSERT INTO `peachbaike` VALUES ('金霞油蟠', '“金霞油蟠”是以甜油桃品种灵光1号（曾用名霞光）为母本，油蟠桃品种NF为父本，杂交选育而得的油蟠桃品种，由上海市蟠桃研究所2018年从江苏省农业科学院引进。果实扁平，果肉黄色，纤维少，硬度中等，风味香甜', '适宜在江苏、浙江、山东、河南等桃适栽地区种植', '7月下旬果实成熟', 'data:image/png;base64,', '‘金霞油蟠’耐储运，与本地蟠桃主栽品种‘玉露’成熟期错峰，丰富了蟠桃品类，具有良好的市场前景。', 15);
INSERT INTO `peachbaike` VALUES ('锦春', '春是以锦绣为母本、沪油桃018 为父本杂交育成的优质早熟鲜食黄桃品种。果型非常端正，果顶稍凹，两边基本对称，缝合线较浅，果面的绒毛很短，套袋果面金黄色，无红色，这是錦香的一大特点，属于纯黄果，不套袋红色。果肉黄色，离核处无红色素。口感浓香浓甜，有黄桃特有的香气。', '山东、江苏、浙江、福建等地', '泰安地区成熟期在6月中下旬', 'data:image/png;base64,', '锦春黄桃果实成熟早，相对来讲，果树的管理周期短，省时省力又省心。', 16);
INSERT INTO `peachbaike` VALUES ('霞辉', '果实大型，平均果重130克，大果重210克。果实圆形或卵圆形果顶圆，两半部对称，缝合线浅。果皮乳黄色，顶部有玫瑰红晕，充分成熟后易剥离。果肉乳白色，肉质柔软多汁，略有纤维，风味甜，香气浓；可溶性固形物含量13%，可溶性糖含量7.87%，可滴定酸含量0.12%。黏核。', '山东、河北、河南、江苏等省份', '山东泰安6月中旬成熟', 'data:image/png;base64,', '树势健壮，树姿半开张。各类果枝均能结果，以中长果枝结果为主。复花芽多而饱满。花粉败育，需配置授粉品种。早果性好，定植后第二年见果，丰产稳产。适应性广，抗逆性强，无特殊病虫害。', 17);
INSERT INTO `peachbaike` VALUES ('风味天后', '风味天后蟠桃是大果型黄肉油蟠桃品种，果实发育期140天左右，果实圆平，较厚，果顶不裂，单果重210-38克，套袋后，果肉及外观均呈金黄色，十分美观，硬溶质，可溶性固形物15-17%，风味浓甜、浓香。有花粉，极丰产，特色高档果品，市场稀缺，效益可观。', '辽宁，新疆，陕西，山西，山东，河北，河南，安徽及江苏部分地区', '8月中下旬成熟', 'data:image/png;base64,', '种植风味天后油蟠桃树苗必须套袋栽培，含糖量高的品种都会有果锈，如果不套袋将很难生产中高档商品果！南方多雨地区不建议种植风味天后油蟠桃树苗！', 18);
INSERT INTO `peachbaike` VALUES ('鲁星1号', '杂交育种，秋雪（Yukon King）×曙光，2003年杂交，2007年选出。早熟油桃品种。果实圆形，平均单果重192.5克；果皮光滑无毛，全面着鲜艳红色；果肉白色，肉质硬脆，香味浓，可溶性固形物14.0%，总糖8.96%，可滴定酸0.43%；粘核。', '山东、河南、江苏、安徽等省份', '泰安地区6月下旬成熟', 'data:image/png;base64,', '适宜栽植密度一般为1.5～3米×4～5米；采用开心形或Y字形树形；选用春雪、中油4号、夏红等为授粉品种；花果及肥水管理、病虫害防治等技术与一般油桃品种相同。', 19);
INSERT INTO `peachbaike` VALUES ('鲁红618', '鲁红618为自花授粉品种，不用人工授粉，自然坐果率高，丰产性好；不用套袋，省工省力，适宜于省力化栽培；果实硬度好，甜度高，肉质细腻，口感好，有较好的玫瑰香味；果实商品率高，果实大，平均单果重300g以上，果形端正，色泽红艳；综合性状优良，发展前景广阔。', '山东、河北、河南、江苏等省份', '山东地区6月中旬左右', 'data:image/png;base64,', '综合性状在同时期蜜桃中表现极佳，无与伦比，发展前景十分广阔，市场潜力巨大，得到了各级权威果树专家的高度认可，全国多家媒体都进行了多次宣传报道，慕名前来参观学习的人员已超过两万人，是农民发家致富的首选蜜桃品种。', 20);
INSERT INTO `peachbaike` VALUES ('黄金蜜', '果实圆形，果顶圆平，果基端正；缝合线浅，两半 部较对称，成熟度较一致。果个中大，平均单果质量 182 g，大果 200 g 以上。果实表面茸毛中等，底色 黄，成熟时多数果面着深红色。果肉黄色，溶质，肉 质细，汁液中多，风味甜，近核处有红色素。可溶性 固 形 物 含 量 为 11.4% ~12.8% ，总 糖 10.4% ，总 酸 0.27%，品质优。黏核。', '山东、河北、河南、江苏等省份', '6月中旬成熟', 'data:image/png;base64,', '黄金蜜桃以其个大，汁多，色泽好享誉省内外。', 21);
