INSERT INTO `wr_warning_record` VALUES (1, 17, 49, 2, 1, 3, 'AIR_TEMP', -1.8000, '夜间空气温度持续低于0℃，冬枣花期霜冻风险较高。建议检查大棚密封情况，启动加温设备，对花期果树区域额外铺设保温布，清晨避免快速通风，防止温差骤变加重花器冻伤。', '{\"suggestion\": \"High priority\"}', '2026-04-12 03:15:22', '2026-04-12 03:15:22', '2026-04-12 03:15:22');
INSERT INTO `wr_warning_record` VALUES (2, 18, 49, 2, 2, 3, 'AIR_TEMP', 36.8000, '高温低湿形成干热风环境，冬枣蒸腾速率急剧上升，极易出现落花落果。立即开启雾化增湿、喷淋降温，正午严禁田间追肥，延长遮阳网覆盖时长。', '{\"suggestion\": \"High priority\"}', '2026-06-25 14:22:16', '2026-06-25 14:22:16', '2026-07-16 23:01:33');
INSERT INTO `wr_warning_record` VALUES (3, 17, 51, 2, 1, 3, 'SOIL_TEMP', 0.2000, '浅层地温接近冰点，冬枣根系存在冻害风险。傍晚提前关闭通风口，减少土壤热量散失，有条件可地表覆盖秸秆保温，保护果树浅层根系。', '{\"suggestion\": \"High priority\"}', '2026-04-15 01:08:45', '2026-04-15 01:08:45', '2026-04-15 01:08:45');
INSERT INTO `wr_warning_record` VALUES (4, 18, 51, 2, 2, 1, 'SOIL_HUM', 19.2000, '土壤湿度缓慢下降，暂未达到干旱阈值。持续跟踪日间气温变化，维持土壤基础墒情，预防持续高温引发冬枣缺水胁迫。', '{\"suggestion\": \"Low priority\"}', '2026-06-22 16:07:29', '2026-06-22 16:07:29', '2026-07-16 23:01:45');
INSERT INTO `wr_warning_record` VALUES (5, 17, 50, 2, 1, 2, 'AIR_TEMP', 0.4000, '气温临近冻害临界阈值，未来4小时温度仍存在继续下降可能。提前检查保温幕、热风设备，安排人员凌晨定点巡检温度变化，做好冬枣花期应急防寒准备。', '{\"suggestion\": \"Medium priority\"}', '2026-04-13 02:40:11', '2026-04-13 02:40:11', '2026-04-13 02:40:11');
INSERT INTO `wr_warning_record` VALUES (6, 18, 50, 2, 2, 3, 'AIR_TEMP', 34.2000, '持续高温，空气湿度不断下降，逐步达到干热风形成条件。上午提前完成灌溉补水，正午开启遮阳设施，降低冬枣植株水分消耗。', '{\"suggestion\": \"High priority\"}', '2026-06-26 15:10:33', '2026-06-26 15:10:33', '2026-07-16 23:01:27');
INSERT INTO `wr_warning_record` VALUES (7, 17, 52, 2, 1, 3, 'SOIL_TEMP', -0.7000, '地表土壤温度跌破冰点，极易造成冬枣浅层根系冻伤。夜间持续保温，次日上午延迟揭开覆盖物，待气温回升后再逐步通风。', '{\"suggestion\": \"High priority\"}', '2026-04-14 03:33:19', '2026-04-14 03:33:19', '2026-04-14 03:33:19');
INSERT INTO `wr_warning_record` VALUES (8, 18, 52, 2, 2, 3, 'SOIL_HUM', 14.6000, '干热风持续加剧土壤失水，冬枣根系供水不足风险上升。选择早晚时段少量多次补水，禁止正午大水漫灌，避免根系高温灼伤。', '{\"suggestion\": \"High priority\"}', '2026-06-27 13:31:47', '2026-06-27 13:31:47', '2026-07-16 23:01:21');
INSERT INTO `wr_warning_record` VALUES (9, 17, 53, 2, 1, 2, 'SOIL_TEMP', 1.2000, '地温缓慢下行，存在夜间结霜可能性。疏通地块排水沟降低土壤湿度，减少地表结霜概率，定时监测浅层土壤温度变化。', '{\"suggestion\": \"Medium priority\"}', '2026-04-16 02:16:50', '2026-04-16 02:16:50', '2026-04-16 02:16:50');
INSERT INTO `wr_warning_record` VALUES (10, 18, 53, 2, 2, 3, 'SOIL_HUM', 16.1000, '高温持续消耗土壤水分，干热风叠加干旱双重胁迫。开启分区滴灌补水，叶面喷施抗旱营养液缓解冬枣失水压力。', '{\"suggestion\": \"High priority\"}', '2026-06-24 14:52:05', '2026-06-24 14:52:05', '2026-07-16 23:01:40');
INSERT INTO `wr_warning_record` VALUES (11, 17, 54, 2, 1, 1, 'SOIL_TEMP', 2.8000, '土壤温度小幅回落，冻害风险偏低。保持日常监测，重点关注未来冷空气过境时段温度走势。', '{\"suggestion\": \"Low priority\"}', '2026-04-17 05:01:27', '2026-04-17 05:01:27', '2026-04-17 05:01:27');
INSERT INTO `wr_warning_record` VALUES (12, 18, 54, 2, 2, 2, 'SOIL_HUM', 21.3000, '土壤墒情尚可，但午后持续高温加剧蒸发。检查灌溉管路状态，做好随时补水准备，定期巡查冬枣叶片失水情况。', '{\"suggestion\": \"Medium priority\"}', '2026-06-28 15:36:12', '2026-06-28 15:36:12', '2026-07-16 23:01:16');
INSERT INTO `wr_warning_record` VALUES (13, 17, 9101, 2, 1, 1, 'AIR_TEMP', 2.1000, '短时低温，尚未达到冻害标准。持续跟踪夜间气象预报，维持常规巡检频次，暂不需要启动防寒应急方案。', '{\"suggestion\": \"Low priority\"}', '2026-04-18 04:22:36', '2026-04-18 04:22:36', '2026-04-18 04:22:36');
INSERT INTO `wr_warning_record` VALUES (14, 18, 49, 2, 2, 2, 'AIR_TEMP', 32.9000, '午后气温持续攀升，空气湿度同步走低，干热风趋势明显。持续观测温湿度联动变化，适时启动通风增湿操作。', '{\"suggestion\": \"Medium priority\"}', '2026-06-29 14:11:39', '2026-06-29 14:11:39', '2026-07-16 23:01:09');
INSERT INTO `wr_warning_record` VALUES (15, 18, 52, 2, 2, 3, 'AIR_TEMP', 34.7000, '连续多日高温，土壤含水量持续降低，干热风叠加干旱风险加大。优先保障根系层土壤水分供给，避免冬枣持续受胁迫。', '{\"suggestion\": \"High priority\"}', '2026-06-30 16:25:08', '2026-06-30 16:25:08', '2026-07-16 23:01:03');
INSERT INTO `wr_warning_record` VALUES (16, 18, 53, 2, 2, 1, 'SOIL_HUM', 24.5000, '土壤湿度充足，当前高温暂不会造成严重干旱。常态化巡查冬枣植株状态，持续预判未来高温天气走势。', '{\"suggestion\": \"Low priority\"}', '2026-07-01 13:55:21', '2026-07-01 13:55:21', '2026-07-16 23:00:41');
INSERT INTO `wr_warning_record` VALUES (17, 18, 51, 2, 2, 3, 'AIR_TEMP', 37.1000, '极端高温天气，干热风灾害风险极高。露天地块可临时增设遮阳设施，分次少量补水，最大程度缓解冬枣高温胁迫。', '{\"suggestion\": \"High priority\"}', '2026-07-02 15:42:37', '2026-07-02 15:42:37', '2026-07-16 23:00:38');
INSERT INTO `wr_warning_record` VALUES (18, 18, 49, 2, 2, 3, 'AIR_TEMP', 35.8000, '午后气温持续攀升至35度以上，干热风风险较高。建议立即开启雾化喷淋降温，正午暂停田间作业，延长遮阳设施覆盖时长，减少冬枣植株蒸腾失水。', '{\"suggestion\": \"High priority\"}', '2026-07-17 14:20:33', '2026-07-17 14:20:33', '2026-07-17 01:31:59');
INSERT INTO `wr_warning_record` VALUES (19, 18, 51, 2, 2, 2, 'SOIL_HUM', 17.2000, '高温天气土壤水分蒸发加快，表层湿度持续下降。建议傍晚启动滴灌补水，维持根系层土壤墒情，避免干热风叠加干旱造成胁迫。', '{\"suggestion\": \"Medium priority\"}', '2026-07-17 15:10:18', '2026-07-17 15:10:18', '2026-07-17 01:31:54');
INSERT INTO `wr_warning_record` VALUES (20, 18, 50, 2, 2, 2, 'AIR_TEMP', 33.5000, '午后气温稳步上升，空气湿度同步走低，存在干热风发展趋势。持续监测温湿度联动变化，提前检查喷淋管路供水状态，做好应急降温准备。', '{\"suggestion\": \"Medium priority\"}', '2026-07-17 13:45:42', '2026-07-17 13:45:42', '2026-07-17 01:32:03');
INSERT INTO `wr_warning_record` VALUES (21, 18, 52, 2, 2, 3, 'SOIL_HUM', 15.1000, '干热风持续消耗土壤水分，浅层土壤湿度已偏低，根系供水不足风险上升。选择早晚时段分次补水，禁止正午大水漫灌，避免高温灼伤根系。', '{\"suggestion\": \"High priority\"}', '2026-07-17 16:05:27', '2026-07-17 16:05:27', '2026-07-17 01:31:51');
INSERT INTO `wr_warning_record` VALUES (22, 18, 53, 2, 2, 1, 'SOIL_HUM', 20.3000, '土壤湿度尚可，但日间持续高温加速地表蒸发。常态化巡查植株叶片状态，预判未来高温走势，按需补充灌溉。', '{\"suggestion\": \"Low priority\"}', '2026-07-17 12:30:55', '2026-07-17 12:30:55', '2026-07-17 01:32:09');
