INSERT INTO `xwq_ai_disease` VALUES (9004, 9004, 9004, '玉米叶斑病', 'MAIZE_LEAF_SPOT', '玉米', 0.91730, '识别结果为玉米叶斑病，需加强田间巡查。', '叶片出现褐色或灰褐色椭圆形病斑，部分病斑边缘较清晰，存在扩大趋势。', '建议清除病残体，避免大水漫灌；发病初期可结合当地植保方案选择合适杀菌剂。', '/profile/upload/ai/result/maize_leaf_spot_001_result.jpg', 1, '轻度预警', 'affected_ratio=0.11', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_disease` VALUES (9005, 9005, 9005, '稻瘟病', 'RICE_BLAST', '水稻', 0.94680, '识别结果为水稻稻瘟病，建议及时处理。', '叶片上可见梭形或近椭圆形病斑，中心灰白，边缘褐色，符合稻瘟病典型视觉特征。', '建议控制氮肥用量，保持合理水层；发病初期根据当地植保建议选用登记药剂防治。', '/profile/upload/ai/result/rice_blast_001_result.jpg', 1, '中度预警', 'affected_ratio=0.21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_disease` VALUES (9018, 10001, 20001, '枣瘿蚊', 'JUJUBE_GALL_MIDGE', '冬枣', 0.96250, '检测到枣瘿蚊危害症状', '嫩叶出现卷曲、皱缩和褐变现象，疑似枣瘿蚊幼虫危害。', '及时摘除受害叶片，并结合虫情监测采取诱捕或针对性药剂防治。', '/profile/disease/result_001.jpg', 1, '高风险', '2026-07-01 17:24:16', 'admin', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_disease` VALUES (9019, 10002, 20002, '枣瘿蚊', 'JUJUBE_GALL_MIDGE', '冬枣', 0.93420, '检测到枣瘿蚊轻度危害', '叶缘轻微卷曲，叶片局部出现异常褐色斑点。', '加强田间巡查，及时清理受害叶片，防止虫害扩散。', '/profile/disease/result_002.jpg', 1, '中风险', '2026-06-30 17:24:16', 'admin', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
