INSERT INTO `xwq_ai_pest` VALUES (99048, 9198, 97330, '枣瘿蚊', 'JUJUBE_GALL_MIDGE', '冬枣', 0.94321, 18, 25, '检测到枣瘿蚊18头，嫩叶受害风险较高。', '加强嫩梢巡查，及时清除卷缩嫩叶，并在低龄幼虫期开展绿色防控。', '/profile/upload/2026/07/17/1280_20260717082420A025.jpg', '[{\"bbox\": [128, 96, 246, 214], \"label\": \"枣瘿蚊\", \"confidence\": 0.94321}]', 1, '中', '2026-06-20 08:15:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_pest` VALUES (99049, 9198, 97330, '绿盲蝽', 'GREEN_PLANT_BUG', '冬枣', 0.90136, 7, 25, '检测到绿盲蝽7头，当前虫口密度较低。', '清除园内及周边杂草，持续监测嫩叶和幼果受害情况。', '/profile/upload/2026/07/17/1277_20260717082355A023.jpg', '[{\"bbox\": [420, 185, 505, 276], \"label\": \"绿盲蝽\", \"confidence\": 0.90136}]', 0, '低', '2026-06-20 08:15:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_pest` VALUES (99050, 9199, 97331, '枣尺蠖', 'JUJUBE_GEOMETER', '冬枣', 0.92688, 11, 11, '检测到枣尺蠖11头，局部叶片存在缺刻。', '结合人工捕捉和诱杀措施，在幼虫低龄期及时防治。', '/profile/upload/2026/07/17/1280_20260717082345A022.jpg', '[{\"bbox\": [310, 140, 485, 355], \"label\": \"枣尺蠖\", \"confidence\": 0.92688}]', 1, '低', '2026-06-23 09:20:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_pest` VALUES (99051, 9200, 97332, '桃小食心虫', 'PEACH_FRUIT_MOTH', '冬枣', 0.91752, 6, 15, '检测到桃小食心虫6头，幼果存在蛀果风险。', '及时清理落果和虫果，结合性诱剂监测成虫发生高峰。', '/profile/upload/2026/07/17/1277_20260717082336A021.jpg', '[{\"bbox\": [180, 220, 290, 345], \"label\": \"桃小食心虫\", \"confidence\": 0.91752}]', 1, '中', '2026-06-27 07:55:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_pest` VALUES (99052, 9200, 97332, '龟蜡蚧', 'WAX_SCALE', '冬枣', 0.88975, 9, 15, '检测到龟蜡蚧9头，枝条局部聚集。', '剪除虫量大的枝条，保护天敌并控制蚧虫若虫期。', '/profile/upload/2026/07/17/1277_20260717082326A020.jpg', '[{\"bbox\": [530, 110, 690, 280], \"label\": \"龟蜡蚧\", \"confidence\": 0.88975}]', 1, '中', '2026-06-27 07:55:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_pest` VALUES (99053, 9201, 97333, '绿盲蝽', 'GREEN_PLANT_BUG', '冬枣', 0.95542, 22, 22, '检测到绿盲蝽22头，嫩叶及幼果受害风险较高。', '立即加强重点区域巡查，在若虫盛发初期采取综合防治措施。', '/profile/upload/2026/07/17/1832_20260717082318A019.jpg', '[{\"bbox\": [225, 128, 382, 316], \"label\": \"绿盲蝽\", \"confidence\": 0.95542}]', 1, '高', '2026-07-01 10:05:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_pest` VALUES (99054, 9202, 97334, '枣瘿蚊', 'JUJUBE_GALL_MIDGE', '冬枣', 0.93416, 8, 13, '检测到枣瘿蚊8头，嫩叶轻度卷缩。', '清除受害嫩叶，保持园内通风透光并继续跟踪虫口变化。', '/profile/upload/2026/07/17/1279_20260717082301A018.jpg', '[{\"bbox\": [105, 175, 228, 302], \"label\": \"枣瘿蚊\", \"confidence\": 0.93416}]', 1, '低', '2026-07-04 08:40:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_pest` VALUES (99055, 9202, 97334, '枣粘虫', 'JUJUBE_LEAFROLLER', '冬枣', 0.87324, 5, 13, '检测到枣粘虫5头，部分叶片出现卷叶。', '人工摘除卷叶虫苞，结合诱虫灯和生物药剂防治。', '/profile/upload/2026/07/17/1221_20260717082244A016.jpg', '[{\"bbox\": [460, 260, 590, 390], \"label\": \"枣粘虫\", \"confidence\": 0.87324}]', 0, '低', '2026-07-04 08:40:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_pest` VALUES (99056, 9203, 97335, '龟蜡蚧', 'WAX_SCALE', '冬枣', 0.96108, 32, 32, '检测到龟蜡蚧32头，枝条聚集明显。', '标记高密度枝条并及时剪除，若虫孵化盛期开展针对性防治。', '/profile/upload/2026/07/17/1832_20260717082253A017.jpg', '[{\"bbox\": [160, 90, 390, 420], \"label\": \"龟蜡蚧\", \"confidence\": 0.96108}]', 1, '高', '2026-07-08 09:10:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_pest` VALUES (99057, 9204, 97336, '枣尺蠖', 'JUJUBE_GEOMETER', '冬枣', 0.93951, 14, 18, '检测到枣尺蠖14头，叶片取食症状较明显。', '重点检查树冠中下部，在低龄幼虫期进行集中防治。', '/profile/upload/2026/07/17/1277_20260717082234A015.jpg', '[{\"bbox\": [190, 155, 385, 360], \"label\": \"枣尺蠖\", \"confidence\": 0.93951}]', 1, '中', '2026-07-12 07:45:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_pest` VALUES (99058, 9204, 97336, '桃小食心虫', 'PEACH_FRUIT_MOTH', '冬枣', 0.86245, 4, 18, '检测到桃小食心虫4头，当前数量较少。', '继续使用性诱剂监测，及时摘除并处理虫果和落果。', '/profile/upload/2026/07/17/1832_20260717082224A014.jpg', '[{\"bbox\": [520, 180, 620, 305], \"label\": \"桃小食心虫\", \"confidence\": 0.86245}]', 0, '低', '2026-07-12 07:45:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_pest` VALUES (99059, 9205, 97337, '枣粘虫', 'JUJUBE_LEAFROLLER', '冬枣', 0.92114, 12, 12, '检测到枣粘虫12头，局部卷叶较集中。', '摘除卷叶虫苞并带出园外处理，必要时使用生物制剂。', '/profile/upload/2026/07/17/1277_20260717082216A013.jpg', '[{\"bbox\": [270, 205, 445, 410], \"label\": \"枣粘虫\", \"confidence\": 0.92114}]', 1, '低', '2026-07-15 08:30:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_pest` VALUES (99060, 9218, 97354, '枣瘿蚊', NULL, '冬枣', 0.95279, 21, 54, '检测到枣瘿蚊虫体，当前虫口数量偏高。', '建议加强冬枣嫩叶和幼芽巡查，及时清除受害组织，并根据虫口密度采取绿色防控措施。', 'http://localhost:8080/profile/upload/2026/07/16/1221_20260716220131A026.jpg', '[{\"bbox\": [100, 120, 180, 200], \"label\": \"枣瘿蚊\", \"confidence\": 0.91}]', 0, '无', '2026-07-16 22:01:31', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_pest` VALUES (99061, 9219, 97355, '枣瘿蚊', NULL, '冬枣', 0.93049, 15, 66, '检测到枣瘿蚊虫体，当前虫口数量偏高。', '建议加强冬枣嫩叶和幼芽巡查，及时清除受害组织，并根据虫口密度采取绿色防控措施。', 'http://localhost:8080/profile/upload/2026/07/16/1277_20260716220131A027.jpg', '[{\"bbox\": [100, 120, 180, 200], \"label\": \"枣瘿蚊\", \"confidence\": 0.91}]', 0, '无', '2026-07-16 22:01:31', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_phenology` VALUES (98133, 9206, 97338, '萌芽期', 'BUD_BREAK', '冬枣', 0.93216, '当前冬枣处于萌芽期。', '芽体开始膨大并陆续萌动，树体由休眠状态进入春季生长。', '做好春季清园和萌芽水管理，关注倒春寒并及时补充树体营养。', '展叶期', '/profile/upload/2026/07/17/萌芽期_20260717081801A001.png', '2026-03-15 09:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'admin', '2026-03-15 09:00:00', 'admin', '2026-07-17 08:18:02', '冬枣虫情设备演示数据');
INSERT INTO `xwq_ai_phenology` VALUES (98134, 9207, 97339, '萌芽期', 'BUD_BREAK', '冬枣', 0.94782, '当前冬枣处于萌芽期。', '芽体开始膨大并陆续萌动，树体由休眠状态进入春季生长。', '做好春季清园和萌芽水管理，关注倒春寒并及时补充树体营养。', '展叶期', '/profile/upload/2026/07/17/萌芽期_20260717081810A002.png', '2026-03-18 08:40:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'admin', '2026-03-18 08:40:00', 'admin', '2026-07-17 08:18:12', '冬枣虫情设备演示数据');
INSERT INTO `xwq_ai_phenology` VALUES (98135, 9208, 97340, '展叶期', 'LEAF_EXPANSION', '冬枣', 0.94135, '当前冬枣处于展叶期。', '新叶逐渐展开，叶面积快速增加，枝梢进入旺盛生长期。', '加强水肥调控，保持适宜土壤墒情，并防治绿盲蝽等嫩梢害虫。', '蕾期', '/profile/upload/2026/07/17/展叶期_20260717081826A003.png', '2026-03-27 08:55:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'admin', '2026-03-27 08:55:00', 'admin', '2026-07-17 08:18:27', '冬枣虫情设备演示数据');
INSERT INTO `xwq_ai_phenology` VALUES (98136, 9209, 97341, '展叶期', 'LEAF_EXPANSION', '冬枣', 0.95364, '当前冬枣处于展叶期。', '新叶逐渐展开，叶面积快速增加，枝梢进入旺盛生长期。', '加强水肥调控，保持适宜土壤墒情，并防治绿盲蝽等嫩梢害虫。', '蕾期', '/profile/upload/2026/07/17/展叶期_20260717081836A004.png', '2026-03-31 09:15:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'admin', '2026-03-31 09:15:00', 'admin', '2026-07-17 08:18:37', '冬枣虫情设备演示数据');
INSERT INTO `xwq_ai_phenology` VALUES (98137, 9210, 97342, '蕾期', 'BUD_STAGE', '冬枣', 0.92847, '当前冬枣处于蕾期。', '花蕾逐渐形成并膨大，生殖生长明显增强。', '合理控制氮肥，补充磷钾和硼锌元素，避免树势过旺影响花芽质量。', '初花期', '/profile/upload/2026/07/17/蕾期_20260717081845A005.png', '2026-04-18 08:35:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'admin', '2026-04-18 08:35:00', 'admin', '2026-07-17 08:18:46', '冬枣虫情设备演示数据');
