-- ----------------------------
-- Table structure for camera_preset
-- ----------------------------
DROP TABLE IF EXISTS `camera_preset`;
CREATE TABLE `camera_preset`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `device_id` bigint NOT NULL COMMENT '设备ID',
  `point_index` int NOT NULL COMMENT '预置点索引 (通常1-12)',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注 (如: 大门口, 仓库左侧)',
  `creator_id` int NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `device_point_unique`(`device_id` ASC, `point_index` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '摄像头预置点表' ROW_FORMAT = DYNAMIC;

