-- ----------------------------
-- Table structure for camera_task
-- ----------------------------
DROP TABLE IF EXISTS `camera_task`;
CREATE TABLE `camera_task`  (
  `task_id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务主键ID',
  `task_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '任务名称 (例如: 1号大棚每日晨检)',
  `preset_id` int NOT NULL COMMENT '预置点ID ',
  `job_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'ONCE' COMMENT '任务类型 (ONCE=单次执行, CRON=周期循环)',
  `execute_time` datetime NULL DEFAULT NULL COMMENT '执行时间 (仅当 job_type=ONCE 时有效)',
  `cron_expression` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT 'Cron执行表达式 (仅当 job_type=CRON 时有效，如 \"0 0 8 * * ?\")',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '任务状态 (0=正常/启动, 1=暂停/停止, 2=已完成, 3=执行失败)',
  `creator_id` int NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注信息',
  `count` smallint NOT NULL DEFAULT 1 COMMENT '执行次数',
  PRIMARY KEY (`task_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '摄像头定时抓拍任务表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of camera_task
-- ----------------------------

-- ----------------------------
-- Table structure for dxx_geojson_archive
-- ----------------------------
DROP TABLE IF EXISTS `dxx_geojson_archive`;
CREATE TABLE `dxx_geojson_archive`  (
  `archive_id` bigint NOT NULL AUTO_INCREMENT COMMENT '存档ID',
  `dataset_id` bigint NOT NULL COMMENT '所属图层ID',
  `archive_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '存档名称',
  `version_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本号',
  `original_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '原始文件名',
  `file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '服务器文件路径',
  `file_size` bigint NULL DEFAULT 0 COMMENT '文件大小（字节）',
  `file_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文件SHA256值',
  `feature_count` int NULL DEFAULT 0 COMMENT 'GeoJSON要素数量',
  `geometry_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '几何类型',
  `coordinate_sys` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'CRS84' COMMENT '坐标系统',
  `min_lng` decimal(11, 8) NULL DEFAULT NULL COMMENT '最小经度',
  `min_lat` decimal(10, 8) NULL DEFAULT NULL COMMENT '最小纬度',
  `max_lng` decimal(11, 8) NULL DEFAULT NULL COMMENT '最大经度',
  `max_lat` decimal(10, 8) NULL DEFAULT NULL COMMENT '最大纬度',
  `preview_color` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '#22c55e' COMMENT '边线颜色',
  `fill_color` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '#16a34a' COMMENT '填充颜色',
  `fill_opacity` decimal(3, 2) NULL DEFAULT 0.25 COMMENT '填充透明度',
  `style_json` json NULL COMMENT '扩展显示样式',
  `is_default` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否默认：0否，1是',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态：0正常，1停用',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志：0存在，2删除',
  PRIMARY KEY (`archive_id`) USING BTREE,
  UNIQUE INDEX `uk_dataset_version`(`dataset_id` ASC, `version_no` ASC) USING BTREE,
  INDEX `idx_dataset_id`(`dataset_id` ASC) USING BTREE,
  INDEX `idx_dataset_status`(`dataset_id` ASC, `status` ASC, `del_flag` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'GeoJSON存档表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of dxx_geojson_archive
-- ----------------------------

-- ----------------------------
-- Table structure for dxx_map_dataset
-- ----------------------------
DROP TABLE IF EXISTS `dxx_map_dataset`;
CREATE TABLE `dxx_map_dataset`  (
  `dataset_id` bigint NOT NULL AUTO_INCREMENT COMMENT '图层ID',
  `dataset_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '图层名称',
  `dataset_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '图层编码',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图层说明',
  `sort_num` int NULL DEFAULT 0 COMMENT '显示顺序',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态：0正常，1停用',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志：0存在，2删除',
  PRIMARY KEY (`dataset_id`) USING BTREE,
  UNIQUE INDEX `uk_dataset_code`(`dataset_code` ASC) USING BTREE,
  INDEX `idx_dataset_status`(`status` ASC, `del_flag` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '地图图层表' ROW_FORMAT = DYNAMIC;

