  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `location_id` int NULL DEFAULT NULL COMMENT '关联的位置',
  `creator_id` int NULL DEFAULT NULL COMMENT '创建者id',
  PRIMARY KEY (`device_id`) USING BTREE,
  UNIQUE INDEX `uk_device_sn`(`device_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9108 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '物联网设备表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of iot_device
-- ----------------------------

-- ----------------------------
-- Table structure for iot_device_log
-- ----------------------------
DROP TABLE IF EXISTS `iot_device_log`;
CREATE TABLE `iot_device_log`  (
  `log_id` bigint NOT NULL AUTO_INCREMENT,
  `device_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '设备编号',
  `log_type` tinyint(1) NULL DEFAULT 1 COMMENT '类型(1属性上报 2事件 3命令响应)',
  `payload` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '原始报文或JSON数据',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上报时间',
  PRIMARY KEY (`log_id`) USING BTREE,
  UNIQUE INDEX `uk_sn_time_payload`(`device_sn` ASC, `create_time` ASC, `payload`(100) ASC) USING BTREE,
  INDEX `idx_sn_time`(`device_sn` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1990 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '设备通信日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of iot_device_log
-- ----------------------------

-- ----------------------------
-- Table structure for iot_product
-- ----------------------------
DROP TABLE IF EXISTS `iot_product`;
CREATE TABLE `iot_product`  (
  `product_id` bigint NOT NULL AUTO_INCREMENT COMMENT '产品ID',
  `product_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '产品名称',
  `product_key` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '产品唯一标识',
  PRIMARY KEY (`product_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '产品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of iot_product
-- ----------------------------

-- ----------------------------
-- Table structure for iot_thing_model
-- ----------------------------
DROP TABLE IF EXISTS `iot_thing_model`;
CREATE TABLE `iot_thing_model`  (
  `model_id` bigint NOT NULL AUTO_INCREMENT COMMENT '模型ID',
  `product_id` bigint NOT NULL COMMENT '关联产品ID',
  `identifier` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '标识符(JSON中的Key)',
  `model_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '属性名称(显示用)',
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '数据类型(int, float, bool, string)',
  `specs` json NULL COMMENT '数据定义(单位、范围、枚举值)',
  `is_monitor` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否在列表展示',
  PRIMARY KEY (`model_id`) USING BTREE,
  UNIQUE INDEX `uk_product_identifier`(`product_id` ASC, `identifier` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '物模型定义表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of iot_thing_model
-- ----------------------------

-- ----------------------------
-- Table structure for iot_warn
-- ----------------------------
DROP TABLE IF EXISTS `iot_warn`;
CREATE TABLE `iot_warn`  (
  `warn_id` int NOT NULL AUTO_INCREMENT COMMENT '预警id',
  `log_id` int NOT NULL COMMENT '日志id',
  `grade` smallint NOT NULL COMMENT '预警等级',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注信息',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`warn_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of iot_warn
-- ----------------------------

-- ----------------------------
-- Table structure for knowledge
-- ----------------------------
DROP TABLE IF EXISTS `knowledge`;
CREATE TABLE `knowledge`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `plus_dsi_categoryfirst` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '一级分类',
  `plus_dsi_categorysecond` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '二级分类',
  `plus_dsi_categorythird` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '三级分类',
  `plus_dsi_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '病虫害名称',
  `dis_pest_type` int NULL DEFAULT 0 COMMENT '类别',
  `plus_dsi_nameeng` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '英文名称',
  `plus_dsi_synonyms` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '别名',
  `plus_dsi_introduction` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '简介',
  `plus_dsi_path` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '图片路径',
  `plus_dsi_damagesym` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '危害症状',
  `plus_dsi_pathogen` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '病源',
  `plus_dsi_cycle` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '侵染',
  `plus_dsi_ofactor` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '发生规律',
  `plus_dsi_morphology` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '形态',
  `plus_dsi_habits` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '习性',
  `plus_dsi_cmethod` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '防治方法',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `lastupdated_at` datetime NULL DEFAULT NULL,
  `lastupdated_by` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `deleted_at` datetime NULL DEFAULT NULL,
  `deleted_by` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `isdeleted` int NULL DEFAULT 0 COMMENT '默认0，1为删除',
  `timestamp` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `companyid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `organizeid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `provice` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '省名称',
  `provice_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '省编码',
  `city` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '市名称',
  `city_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '市编码',
  `district` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '县名称',
  `district_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '县编码',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3510 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of knowledge
-- ----------------------------

-- ----------------------------
-- Table structure for ld_agri_alert_record
-- ----------------------------
DROP TABLE IF EXISTS `ld_agri_alert_record`;
CREATE TABLE `ld_agri_alert_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识ID，唯一自增主键',
  `device_log_id` bigint NOT NULL COMMENT '设备日志ID，关联设备上报日志表或流水表的唯一ID',
  `level_config_id` bigint NOT NULL COMMENT '预警等级配置ID，关联 ld_agri_alert_level_config 表的 id',
  `actual_value` decimal(6, 2) NOT NULL COMMENT '报警时实际数值，触发报警时的传感器真实读数（如：40.2）',
  `alert_advice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '大模型防灾建议，联动大模型自动生成的针对该条预警的防灾应急实操建议文本',
  `handle_status` tinyint NOT NULL DEFAULT 0 COMMENT '人工处理状态，0:未处理；1:已处理/已确认；2:误报消除',
  `handler_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处理人ID，执行核销的系统用户或农艺专家ID',
  `handle_time` datetime NULL DEFAULT NULL COMMENT '处理时间，人工确认或核销的具体时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '报警触发时间，规则触发并生成预警记录的时间',
  `remark1` tinyint NOT NULL DEFAULT 1 COMMENT '预留状态扩展字段：处理优先级或后续跟进状态，默认1',
  `remark2` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预留文本扩展字段：人工处理备注或大模型追问历史JSON结构',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_device_log_id`(`device_log_id` ASC) USING BTREE COMMENT '普通索引一：优化基于设备日志/流水的查询速度',
  INDEX `idx_level_config_id`(`level_config_id` ASC) USING BTREE COMMENT '普通索引二：优化关联预警规则配置的联动查询',
  INDEX `idx_handle_status`(`handle_status` ASC) USING BTREE COMMENT '普通索引三：优化待处理/已处理状态的筛选与大屏滚动展示'
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '产品预警触发与历史处理记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ld_agri_alert_record
-- ----------------------------

-- ----------------------------
-- Table structure for ld_agri_crop_stage
-- ----------------------------
DROP TABLE IF EXISTS `ld_agri_crop_stage`;
CREATE TABLE `ld_agri_crop_stage`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识ID，唯一自增主键',
  `crop_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '作物名称（如：小麦、玉米）',
  `crop_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '作物编码（如：WHEAT、MAIZE）',
  `stage_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '物候期生育阶段名称（如：拔节期、抽雄期）',
  `stage_order` tinyint NOT NULL DEFAULT 1 COMMENT '生育期先后顺序序号（从1开始），便于前台按时间轴渲染',
  `standard_image` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物候期标准表型图像URL路径',
  `temp_min` decimal(4, 1) NULL DEFAULT NULL COMMENT '适宜生长最低温度（℃）',
  `temp_max` decimal(4, 1) NULL DEFAULT NULL COMMENT '适宜生长最高温度（℃）',
  `sunshine_hours` decimal(3, 1) NULL DEFAULT NULL COMMENT '每日所需标准光照预计时间（小时）',
  `water_fertilizer_std` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '水肥标准规范描述（可存储JSON或标准指导文本）',
  `agri_work_spec` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '该生育阶段关键农事作业规范及大模型研判底座文本',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `remark1` tinyint NULL DEFAULT 1 COMMENT '预留状态扩展字段：配置或状态类型，默认1',
  `remark2` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预留文本扩展字段：业务备注或扩展JSON配置',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_crop_code_order`(`crop_code` ASC, `stage_order` ASC) USING BTREE COMMENT '联合索引：优化基于作物编码快速拉取全生命周期生育期时间轴'
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '作物不同物候期种植标准与规范配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ld_agri_crop_stage
-- ----------------------------

-- ----------------------------
-- Table structure for ld_agri_product_alert_config
-- ----------------------------
DROP TABLE IF EXISTS `ld_agri_product_alert_config`;
CREATE TABLE `ld_agri_product_alert_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识ID',
  `model_id` bigint NOT NULL COMMENT '物模型ID，关联产品的物模型表，明确属于哪个产品的哪个字段',
  `alert_level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '预警级别，预警严重程度（如：蓝色、黄色、橙色、红色）',
  `threshold_min` decimal(6, 2) NULL DEFAULT NULL COMMENT '预警下限阈值，低于该值触发预警',
  `threshold_max` decimal(6, 2) NULL DEFAULT NULL COMMENT '预警上限阈值，高于该值触发预警',
  `rule_description` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预警规则描述，规则的文字描述',
  `is_enabled` tinyint NOT NULL DEFAULT 1 COMMENT '是否启用，0:禁用；1:启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间，规则配置创建时间',
  `creator` bigint NULL DEFAULT NULL COMMENT '创建人',
  `remark1` tinyint NULL DEFAULT 1 COMMENT '预留状态扩展字段：配置或状态扩展类型，默认1',
  `remark2` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预留文本扩展字段：业务备注或扩展JSON配置',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_model_id`(`model_id` ASC) USING BTREE COMMENT '普通索引一'
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物模型产品预警规则配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ld_agri_product_alert_config
-- ----------------------------

-- ----------------------------
-- Table structure for ld_agri_weather_alert_advice
-- ----------------------------
DROP TABLE IF EXISTS `ld_agri_weather_alert_advice`;
CREATE TABLE `ld_agri_weather_alert_advice`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识ID，唯一自增主键',
  `weather_id` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联实时天气表或者未来天气表id，是数组形式例如[2,5,8]',
  `anomaly_info` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '触发异常实况，触发大模型研判的异常天气数据（如：极端高温39.5℃持续）',
  `alert_level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '预警级别，大模型评估的风险等级（如：蓝色、黄色、橙色、红色）',
  `aqi_evaluation` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '空气综合评价，大模型对当前空气综合指标（负氧离子、PM2.5等）的评价文字',
  `alert_advice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '大模型防灾建议，大模型自动生成的针对性、个性化农事应急实操建议文本',
  `audit_status` tinyint NOT NULL DEFAULT 0 COMMENT '处理状态，0:未处理；1:专家确认并推送；2:人工核销/误报',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '预警生成时间，大模型生成预警建议的时间',
  `remark1` tinyint NULL DEFAULT 1 COMMENT '预留状态扩展字段：大模型预警推送渠道或紧急程度分类，默认1',
  `remark2` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预留文本扩展字段：专家人工核销原因或大模型推理链上下文快照',
  `type` tinyint NOT NULL COMMENT '预警类型，是实时还是预报 0代表实时，1代表未来天气',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_park_id`(`weather_id` ASC) USING BTREE COMMENT '普通索引：优化基于特定园区的预警建议查询',
  INDEX `idx_audit_status`(`audit_status` ASC) USING BTREE COMMENT '普通索引：优化待处理、已处理状态的筛选与流转速度'
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大模型极端天气突发预警与防灾建议表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ld_agri_weather_alert_advice
-- ----------------------------

-- ----------------------------
-- Table structure for ld_agri_weather_forecast
-- ----------------------------
DROP TABLE IF EXISTS `ld_agri_weather_forecast`;
CREATE TABLE `ld_agri_weather_forecast`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识ID，唯一自增主键',
  `park_id` bigint NOT NULL COMMENT '园区ID',
  `fetch_time` datetime NOT NULL COMMENT '数据抓取时间，接口数据拉取的具体时间点',
  `forecast_date` date NOT NULL COMMENT '预报目标日期，被预测的未来某一天日期（YYYY-MM-DD）',
  `temp_max` double NULL DEFAULT NULL COMMENT '最高温度，该日最高温度预测（℃）',
  `temp_min` double NULL DEFAULT NULL COMMENT '最低温度，该日最低温度预测（℃）',
  `humidity_avg` double NULL DEFAULT NULL COMMENT '平均湿度，该日平均相对湿度预测（%）',
  `wind_dir_day` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '白天风向，白天风向文字描述',
  `wind_scale_day` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '白天风力，白天风力等级描述',
  `precip_total` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '全天降水量，该日总降水量预测，单位：毫米（mm）',
  `precip_prob` tinyint NULL DEFAULT 0 COMMENT '降水概率，降水概率（%），范围 0-100',
  `weather_text_day` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '白天天气，白天天气现象（如：多云）',
  `weather_text_night` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '夜间天气，夜间天气现象（如：雷阵雨）',
  `forecast_type` tinyint NOT NULL DEFAULT 7 COMMENT '预报天数类型，预报类型：7表示7天预报，15表示15天预报',
  `remark1` tinyint NULL DEFAULT 1 COMMENT '预留状态扩展字段：数据有效性状态或气象局源头标识，默认1',
  `remark2` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '预留文本扩展字段：中长期趋势分析备注或扩展气象JSON参数',
  `day_code` int NULL DEFAULT NULL COMMENT '白天天气代码',
  `moon_code` int NULL DEFAULT NULL COMMENT '晚间天气代码',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_park_date_fetch`(`park_id` ASC, `forecast_date` ASC, `fetch_time` DESC) USING BTREE COMMENT '联合唯一索引：确保同一园区针对同一预报日在同一次抓取时的数据唯一性'
) ENGINE = InnoDB AUTO_INCREMENT = 232 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '园区未来7天与15天天气预报趋势表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ld_agri_weather_forecast
-- ----------------------------

-- ----------------------------
-- Table structure for ld_agri_weather_live
-- ----------------------------
DROP TABLE IF EXISTS `ld_agri_weather_live`;
CREATE TABLE `ld_agri_weather_live`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识ID，唯一自增主键',
  `park_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '园区ID，关联园区基础信息表',
  `fetch_time` datetime NOT NULL COMMENT '数据抓取时间，接口数据调用时间（精确到分）',
  `report_time` datetime NOT NULL COMMENT '气象发布时间，气象局官方数据发布或更新的时间',
  `temperature` decimal(4, 2) NULL DEFAULT NULL COMMENT '当前温度，单位：摄氏度（℃）',
  `humidity` tinyint NULL DEFAULT NULL COMMENT '当前湿度，相对湿度，单位：百分比（%），范围 0-100',
  `wind_direction` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '风向，风向文字描述（如：东北风、西南风）',
  `wind_speed` decimal(4, 2) NULL DEFAULT 0.00 COMMENT '风速，单位：米/秒（m/s）',
  `wind_scale` tinyint NULL DEFAULT NULL COMMENT '风力等级，风力级数（如：3级、4级）',
  `precipitation` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '降水量，当前或过去1小时累计降水量，单位：毫米（mm）',
  `air_pressure` decimal(6, 2) NULL DEFAULT NULL COMMENT '大气压强，单位：百帕（hPa）',
  `weather_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '天气现象代码，天气现象图标/代码（如：晴=100，雨=301）',
  `weather_text` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '天气现象文字，天气现象文字描述（如：晴、大雨、多云）',
  `remark1` tinyint NULL DEFAULT 1 COMMENT '预留状态扩展字段：数据有效性状态或气象来源类型，默认1',
  `remark2` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预留文本扩展字段：接口原始报文快照或额外气象评价描述',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_park_fetch`(`park_id` ASC, `fetch_time` DESC) USING BTREE COMMENT '联合索引：优化基于园区获取最新精细化天气曲线的查询速度'
) ENGINE = InnoDB AUTO_INCREMENT = 41 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '园区实时与当天天气实况记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ld_agri_weather_live
-- ----------------------------

-- ----------------------------
-- Table structure for ld_crop_variety
-- ----------------------------
DROP TABLE IF EXISTS `ld_crop_variety`;
CREATE TABLE `ld_crop_variety`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `category_id` bigint NOT NULL COMMENT '作物种类ID',
  `variety_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '品种名称',
  `approval_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审定编号',
  `approval_year` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审定年份',
  `is_gmo` tinyint NULL DEFAULT 0 COMMENT '是否转基因(0否1是)',
  `approval_institution` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审定机构',
  `breeding_unit` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '选(引)育单位(人)',
  `variety_source` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '品种来源',
  `suitable_area` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '适宜种植区域',
  `characteristics` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '特征特性（标准象完整描述）',
  `cultivation_measures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '主要栽培措施',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态(0隐藏1正常)',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_category`(`category_id` ASC) USING BTREE,
  INDEX `idx_variety_name`(`variety_name` ASC) USING BTREE,
  INDEX `idx_approval_number`(`approval_number` ASC) USING BTREE,
  INDEX `idx_approval_year`(`approval_year` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  FULLTEXT INDEX `ft_search`(`variety_name`, `characteristics`),
  CONSTRAINT `ld_crop_variety_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `ld_crop_category` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 512 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '品种信息表' ROW_FORMAT = DYNAMIC;

