-- ----------------------------
-- Table structure for ld_unified_knowledge_relations
-- ----------------------------
DROP TABLE IF EXISTS `ld_unified_knowledge_relations`;
CREATE TABLE `ld_unified_knowledge_relations`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `source_node_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '源节点ID',
  `target_node_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标节点ID',
  `relation_type` enum('包含','具有','相似','属于','抗性','易感','防治','引起','影响') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关系类型',
  `relation_label` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关系标签',
  `relation_strength` decimal(3, 2) NULL DEFAULT 1.00 COMMENT '关系强度(0-1)',
  `direction` enum('directed','undirected') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'directed' COMMENT '关系方向',
  `properties` json NULL COMMENT '关系属性',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态：0-禁用 1-启用',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_relation`(`source_node_id` ASC, `target_node_id` ASC, `relation_type` ASC) USING BTREE,
  INDEX `idx_source`(`source_node_id` ASC) USING BTREE,
  INDEX `idx_target`(`target_node_id` ASC) USING BTREE,
  INDEX `idx_relation_type`(`relation_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9198 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '统一知识图谱关系表' ROW_FORMAT = DYNAMIC;

