-- ----------------------------
-- Table structure for location
-- ----------------------------
DROP TABLE IF EXISTS `location`;
CREATE TABLE `location`  (
  `location_id` bigint NOT NULL AUTO_INCREMENT COMMENT '位置ID，主键',
  `area_id` bigint NOT NULL COMMENT '关联区域ID，外键',
  `location_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '位置名称（如XX车间-XX设备位）',
  `location_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '位置编码（唯一，物联网设备唯一绑定）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `coordinate` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '坐标，里面是经纬度数组，例如[[26,72],[35,68]]',
  PRIMARY KEY (`location_id`) USING BTREE,
  INDEX `idx_area_id`(`area_id` ASC) USING BTREE COMMENT '区域外键索引，提升层级查询效率',
  CONSTRAINT `fk_location_area` FOREIGN KEY (`area_id`) REFERENCES `area` (`area_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '物联网园区管理-位置表' ROW_FORMAT = DYNAMIC;

