DROP TABLE IF EXISTS `park`;
CREATE TABLE `park`  (
  `park_id` bigint NOT NULL AUTO_INCREMENT COMMENT '园区ID，主键',
  `park_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '园区名称（唯一）',
