-- ----------------------------
-- Table structure for qrtz_triggers
-- ----------------------------
DROP TABLE IF EXISTS `qrtz_triggers`;
CREATE TABLE `qrtz_triggers`  (
  `sched_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '调度名称',
  `trigger_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '触发器的名字',
  `trigger_group` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '触发器所属组的名字',
  `job_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'qrtz_job_details表job_name的外键',
  `job_group` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'qrtz_job_details表job_group的外键',
  `description` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '相关介绍',
  `next_fire_time` bigint NULL DEFAULT NULL COMMENT '上一次触发时间（毫秒）',
  `prev_fire_time` bigint NULL DEFAULT NULL COMMENT '下一次触发时间（默认为-1表示不触发）',
  `priority` int NULL DEFAULT NULL COMMENT '优先级',
  `trigger_state` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '触发器状态',
  `trigger_type` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '触发器的类型',
  `start_time` bigint NOT NULL COMMENT '开始时间',
  `end_time` bigint NULL DEFAULT NULL COMMENT '结束时间',
  `calendar_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '日程表名称',
  `misfire_instr` smallint NULL DEFAULT NULL COMMENT '补偿执行的策略',
  `job_data` blob NULL COMMENT '存放持久化job对象',
  PRIMARY KEY (`sched_name`, `trigger_name`, `trigger_group`) USING BTREE,
  INDEX `sched_name`(`sched_name` ASC, `job_name` ASC, `job_group` ASC) USING BTREE,
  CONSTRAINT `qrtz_triggers_ibfk_1` FOREIGN KEY (`sched_name`, `job_name`, `job_group`) REFERENCES `qrtz_job_details` (`sched_name`, `job_name`, `job_group`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '触发器详细信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of qrtz_triggers
-- ----------------------------

-- ----------------------------
-- Table structure for sxz_disease_auto_task
-- ----------------------------
DROP TABLE IF EXISTS `sxz_disease_auto_task`;
CREATE TABLE `sxz_disease_auto_task`  (
  `task_id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务主键ID',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务名称',
  `park_id` bigint NULL DEFAULT NULL COMMENT '园区ID，关联park.park_id',
  `device_id` bigint NOT NULL COMMENT '摄像头设备ID，关联iot_device.device_id',
  `model_id` bigint NOT NULL COMMENT '病虫害识别模型ID，关联xwq_ai_model.model_id',
  `crop_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '枣树' COMMENT '作物类型',
  `schedule_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '调度方式：fixed固定时刻，interval间隔执行',
  `fixed_times` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '每日固定执行时刻，英文逗号分隔，如08:00,14:00,20:00',
  `interval_minutes` int NULL DEFAULT NULL COMMENT '间隔执行分钟数，schedule_type为interval时使用',
  `active_start_time` time NULL DEFAULT NULL COMMENT '每日允许执行开始时间',
  `active_end_time` time NULL DEFAULT NULL COMMENT '每日允许执行结束时间',
  `batch_limit` int NOT NULL DEFAULT 20 COMMENT '单次最多识别图片数量，范围1至100',
  `task_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '任务状态：0启用，1停用',
  `run_state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'IDLE' COMMENT '运行状态：IDLE空闲，RUNNING执行中',
  `execution_token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任务执行锁令牌，防止并发重复执行',
  `execution_lock_time` datetime NULL DEFAULT NULL COMMENT '任务执行锁定时间',
  `last_run_time` datetime NULL DEFAULT NULL COMMENT '最近一次执行结束时间',
  `next_run_time` datetime NULL DEFAULT NULL COMMENT '下一次计划执行时间',
  `last_run_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最近执行状态：SUCCESS、PARTIAL、FAILED、SKIPPED',
  `last_run_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最近执行结果或失败原因',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '删除标志：0正常，2已删除',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任务备注',
  `reserve_a` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段A',
  `reserve_b` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段B',
  `reserve_c` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段C',
  `reserve_d` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段D',
  `reserve_e` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段E',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`task_id`) USING BTREE,
  INDEX `idx_auto_task_status_next`(`task_status` ASC, `del_flag` ASC, `next_run_time` ASC) USING BTREE,
  INDEX `idx_auto_task_park_device`(`park_id` ASC, `device_id` ASC) USING BTREE,
  INDEX `idx_auto_task_model`(`model_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '病虫害自动识别任务配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sxz_disease_auto_task
-- ----------------------------

-- ----------------------------
-- Table structure for sxz_disease_auto_task_item
-- ----------------------------
DROP TABLE IF EXISTS `sxz_disease_auto_task_item`;
CREATE TABLE `sxz_disease_auto_task_item`  (
  `item_id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务图片明细主键ID',
  `task_id` bigint NOT NULL COMMENT '任务ID，逻辑关联sxz_disease_auto_task.task_id',
  `run_id` bigint NOT NULL COMMENT '执行批次ID，逻辑关联sxz_disease_auto_task_run.run_id',
  `source_image_id` bigint NOT NULL COMMENT '设备原始图片ID，关联image_record.id',
  `ai_image_id` bigint NULL DEFAULT NULL COMMENT 'AI图片ID，关联xwq_ai_image.image_id',
  `record_id` bigint NULL DEFAULT NULL COMMENT '识别主记录ID，关联xwq_ai_record.record_id',
  `disease_id` bigint NULL DEFAULT NULL COMMENT '病害结果ID，关联xwq_ai_disease.disease_id',
  `item_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '处理状态：PENDING、RUNNING、SUCCESS、FAILED、SKIPPED',
  `attempt_count` int NOT NULL DEFAULT 0 COMMENT '模型调用尝试次数',
  `start_time` datetime NULL DEFAULT NULL COMMENT '单图识别开始时间',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '单图识别完成时间',
  `error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '单图识别失败原因',
  `reserve_a` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段A',
  `reserve_b` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段B',
  `reserve_c` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段C',
  `reserve_d` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段D',
  `reserve_e` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段E',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间',
  PRIMARY KEY (`item_id`) USING BTREE,
  UNIQUE INDEX `uk_auto_item_task_source`(`task_id` ASC, `source_image_id` ASC) USING BTREE,
  INDEX `idx_auto_item_run_status`(`run_id` ASC, `item_status` ASC) USING BTREE,
  INDEX `idx_auto_item_record`(`record_id` ASC) USING BTREE,
  INDEX `idx_auto_item_disease`(`disease_id` ASC) USING BTREE,
  INDEX `idx_auto_item_ai_image`(`ai_image_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '病虫害自动识别任务图片明细表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sxz_disease_auto_task_item
-- ----------------------------

-- ----------------------------
-- Table structure for sxz_disease_auto_task_run
-- ----------------------------
DROP TABLE IF EXISTS `sxz_disease_auto_task_run`;
CREATE TABLE `sxz_disease_auto_task_run`  (
  `run_id` bigint NOT NULL AUTO_INCREMENT COMMENT '执行批次主键ID',
  `task_id` bigint NOT NULL COMMENT '任务ID，逻辑关联sxz_disease_auto_task.task_id',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '执行时任务名称快照',
  `trigger_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '触发方式：AUTO自动调度，MANUAL手动触发',
  `run_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '执行状态：RUNNING、SUCCESS、PARTIAL、FAILED、SKIPPED、INTERRUPTED',
  `start_time` datetime NOT NULL COMMENT '执行开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '执行结束时间',
  `source_count` int NOT NULL DEFAULT 0 COMMENT '本次发现的设备图片数量',
  `recognize_count` int NOT NULL DEFAULT 0 COMMENT '本次实际发起识别数量',
  `success_count` int NOT NULL DEFAULT 0 COMMENT '识别成功数量',
  `fail_count` int NOT NULL DEFAULT 0 COMMENT '识别失败数量',
  `skip_count` int NOT NULL DEFAULT 0 COMMENT '跳过数量',
  `error_message` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '批次失败或异常摘要',
  `reserve_a` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段A',
  `reserve_b` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段B',
  `reserve_c` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段C',
  `reserve_d` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段D',
  `reserve_e` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段E',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '触发人，自动调度时为system',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间',
  PRIMARY KEY (`run_id`) USING BTREE,
  INDEX `idx_auto_run_task_time`(`task_id` ASC, `start_time` ASC) USING BTREE,
  INDEX `idx_auto_run_status_time`(`run_status` ASC, `start_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '病虫害自动识别任务执行批次表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sxz_disease_auto_task_run
-- ----------------------------

