-- ----------------------------
-- Table structure for wr_warning_record
-- ----------------------------
DROP TABLE IF EXISTS `wr_warning_record`;
CREATE TABLE `wr_warning_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '预警记录唯一标识',
  `task_id` bigint NOT NULL COMMENT '关联预警任务ID',
  `device_id` bigint NULL DEFAULT NULL COMMENT '触发设备ID',
  `responsible_user_id` bigint NULL DEFAULT NULL COMMENT '预警负责人ID',
  `warning_type` tinyint NOT NULL COMMENT '预警类型：气象、土壤、水肥、病虫害等',
  `warning_level` tinyint NOT NULL DEFAULT 3 COMMENT '预警等级：1紧急、2较重、3一般、4提示',
  `indicator_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '触发预警的监测指标编码',
  `current_value` decimal(18, 4) NULL DEFAULT NULL COMMENT '触发时监测值',
  `ai_suggestion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'AI生成处置建议',
  `ai_result_json` json NULL COMMENT 'AI分析结果',
  `warning_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '预警发生时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '记录更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_task_id`(`task_id` ASC) USING BTREE,
  INDEX `idx_device_id`(`device_id` ASC) USING BTREE,
  INDEX `idx_responsible_user_id`(`responsible_user_id` ASC) USING BTREE,
  INDEX `idx_warning_type`(`warning_type` ASC) USING BTREE,
  INDEX `idx_warning_level`(`warning_level` ASC) USING BTREE,
  INDEX `idx_indicator_code`(`indicator_code` ASC) USING BTREE,
  INDEX `idx_warning_time`(`warning_time` ASC) USING BTREE,
  INDEX `idx_created_at`(`create_time` ASC) USING BTREE,
  CONSTRAINT `fk_device_id` FOREIGN KEY (`device_id`) REFERENCES `iot_device` (`device_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_role` FOREIGN KEY (`responsible_user_id`) REFERENCES `sys_role` (`role_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_warning_record_task` FOREIGN KEY (`task_id`) REFERENCES `wr_warning_task` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 6835 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预警记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wr_warning_record
-- ----------------------------

-- ----------------------------
-- Table structure for wr_warning_task
-- ----------------------------
DROP TABLE IF EXISTS `wr_warning_task`;
CREATE TABLE `wr_warning_task`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '预警任务唯一标识',
  `task_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预警任务名称',
  `template_id` bigint NOT NULL COMMENT '关联预警模板ID',
  `cron_expression` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '定时任务表达式',
  `monitor_start_time` time NULL DEFAULT NULL COMMENT '每日监控开始时间',
  `monitor_end_time` time NULL DEFAULT NULL COMMENT '每日监控结束时间',
  `data_source_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '数据源类型：传感器数据、第三方数据、虫情数据、长势数据等',
  `data_source_id` bigint NULL DEFAULT NULL COMMENT '关联数据源ID',
  `query_config_json` json NULL COMMENT '数据查询条件配置，注意做好安全校验',
  `rule_source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'rule' COMMENT '规则类型：rule基于规则库、nlp基于自然语言、mixed混合',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'running' COMMENT '任务状态：running、paused、stopped、error',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '创建该任务的用户ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '记录更新时间',
  `reserved_field1` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务扩展字段1',
  `reserved_field2` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务扩展字段2',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_task_name`(`task_name` ASC) USING BTREE,
  INDEX `idx_template_id`(`template_id` ASC) USING BTREE,
  INDEX `idx_data_source_id`(`data_source_id` ASC) USING BTREE,
  INDEX `idx_rule_source_type`(`rule_source_type` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_created_by`(`create_by` ASC) USING BTREE,
  INDEX `idx_created_at`(`create_time` ASC) USING BTREE,
  CONSTRAINT `fk_warning_task_template` FOREIGN KEY (`template_id`) REFERENCES `wr_warning_template` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预警任务表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wr_warning_task
-- ----------------------------

-- ----------------------------
-- Table structure for wr_warning_template
-- ----------------------------
DROP TABLE IF EXISTS `wr_warning_template`;
CREATE TABLE `wr_warning_template`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '预警模板唯一标识',
  `template_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预警模板名称',
  `warning_type` tinyint NOT NULL COMMENT '预警类型：如气象、土壤墒情、水肥异常、病虫害等',
  `park_id` bigint NULL DEFAULT NULL COMMENT '关联园区park表ID',
  `area_id` bigint NULL DEFAULT NULL COMMENT '关联片区area表主键ID',
  `location_id` bigint NULL DEFAULT NULL COMMENT '关联地块location表主键ID',
  `cropName` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '适用作物名称',
  `description` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模板适用场景及说明',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：0禁用，1启用，2作废',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '创建该模板的用户ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_template_name`(`template_name` ASC) USING BTREE,
  INDEX `idx_warning_type`(`warning_type` ASC) USING BTREE,
  INDEX `idx_applicable_area_id`(`park_id` ASC) USING BTREE,
  INDEX `idx_crop_id`(`cropName` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_created_by`(`create_by` ASC) USING BTREE,
  INDEX `idx_created_at`(`create_time` ASC) USING BTREE,
  INDEX `fk_warn_template_area`(`area_id` ASC) USING BTREE,
  INDEX `fk_warn_template_location`(`location_id` ASC) USING BTREE,
  CONSTRAINT `fk_warn_template_area` FOREIGN KEY (`area_id`) REFERENCES `area` (`area_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_warn_template_location` FOREIGN KEY (`location_id`) REFERENCES `location` (`location_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_warn_template_park` FOREIGN KEY (`park_id`) REFERENCES `park` (`park_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预警模板表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wr_warning_template
-- ----------------------------

-- ----------------------------
-- Table structure for wr_warning_template_rule
-- ----------------------------
DROP TABLE IF EXISTS `wr_warning_template_rule`;
CREATE TABLE `wr_warning_template_rule`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '模板规则唯一标识',
  `template_id` bigint NOT NULL COMMENT '关联预警模板ID',
  `indicator_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '监测指标编码，如温度、湿度、PH、EC等',
  `operator` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '比较操作符：>、<、>=、<=、between等',
  `single_threshold` decimal(10, 2) NULL DEFAULT NULL COMMENT '单阈值',
  `threshold_min` decimal(18, 4) NULL DEFAULT NULL COMMENT '阈值下限',
  `threshold_max` decimal(18, 4) NULL DEFAULT NULL COMMENT '阈值上限',
  `level` tinyint NOT NULL DEFAULT 3 COMMENT '预警等级：1一级、2二级、3三级、4四级',
  `duration_seconds` int NULL DEFAULT 0 COMMENT '持续多少秒后触发',
  `trigger_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'instant' COMMENT '触发类型：instant瞬时、duration持续、combined组合',
  `logic_group` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '逻辑分组，多指标组合时使用',
  `logic_operator` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'AND' COMMENT '逻辑运算符：AND或OR',
  `sort_order` int NULL DEFAULT 0 COMMENT '规则执行或展示顺序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_template_id`(`template_id` ASC) USING BTREE,
  INDEX `idx_indicator_code`(`indicator_code` ASC) USING BTREE,
  INDEX `idx_level`(`level` ASC) USING BTREE,
  INDEX `idx_trigger_type`(`trigger_type` ASC) USING BTREE,
  INDEX `idx_logic_group`(`logic_group` ASC) USING BTREE,
  CONSTRAINT `fk_warning_template_rule_template` FOREIGN KEY (`template_id`) REFERENCES `wr_warning_template` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 56 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预警模板规则表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wr_warning_template_rule
-- ----------------------------

-- ----------------------------
-- Table structure for xwq_ai_disease
-- ----------------------------
DROP TABLE IF EXISTS `xwq_ai_disease`;
CREATE TABLE `xwq_ai_disease`  (
  `disease_id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识一条病虫害识别结果',
  `record_id` bigint NOT NULL COMMENT '关联识别记录表 record_id',
  `image_id` bigint NOT NULL COMMENT '关联图片信息表 image_id',
  `disease_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '病虫害名称，如条锈病、白粉病、叶枯病等',
  `disease_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '病虫害标准编码',
  `disease_crop` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '作物类型，如小麦、玉米、水稻',
  `disease_confidence` decimal(6, 5) NULL DEFAULT NULL COMMENT '模型预测置信度',
  `disease_result` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模型给出的诊断结论',
  `disease_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '识别到的症状表现',
  `disease_advice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '药剂防治、农艺措施等建议',
  `disease_result_img_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '识别后的标注图、打框图',
  `is_warning` tinyint NOT NULL DEFAULT 0 COMMENT '是否触发预警：0 否，1 是',
  `warning_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '生成的预警等级',
  `disease_a` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建时间',
  `disease_b` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `disease_c` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段3',
  `disease_d` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段4',
  `disease_e` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段5',
  `disease_f` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段6',
  `disease_g` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段7',
  `disease_h` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段8',
  `disease_i` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段9',
  `disease_j` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段10',
  PRIMARY KEY (`disease_id`) USING BTREE,
  INDEX `idx_disease_record_id`(`record_id` ASC) USING BTREE,
  INDEX `idx_disease_image_id`(`image_id` ASC) USING BTREE,
  INDEX `idx_disease_name`(`disease_name` ASC) USING BTREE,
  INDEX `idx_disease_crop`(`disease_crop` ASC) USING BTREE,
  INDEX `idx_disease_warning`(`is_warning` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9185 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '病虫害识别结果表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of xwq_ai_disease
-- ----------------------------

-- ----------------------------
-- Table structure for xwq_ai_image
-- ----------------------------
DROP TABLE IF EXISTS `xwq_ai_image`;
CREATE TABLE `xwq_ai_image`  (
  `image_id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识一张图片',
  `image_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '图片原始名称',
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '图片存储地址',
  `image_result_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模型识别后的打框图、标注图地址',
  `image_mask_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分割 mask 图片地址',
  `image_ai_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '识别业务类型：disease 病虫害，pest 虫情，phenology 物候期，unknown 未知',
  `image_source` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '图片来源：手动上传、摄像头、虫情设备、无人机、手机端',
  `image_source_id` bigint NULL DEFAULT NULL COMMENT '来源设备 ID、摄像头 ID、任务 ID 等',
  `image_width` int NULL DEFAULT NULL COMMENT '图片宽度，单位像素',
  `image_height` int NULL DEFAULT NULL COMMENT '图片高度，单位像素',
  `image_size` bigint NULL DEFAULT NULL COMMENT '图片大小，单位字节',
  `image_format` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '图片格式，如 jpg、png、jpeg',
  `park_id` bigint NULL DEFAULT NULL COMMENT '园区 ID',
  `plot_id` bigint NULL DEFAULT NULL COMMENT '地块 ID',
  `device_id` bigint NULL DEFAULT NULL COMMENT '设备 ID，关联摄像头、虫情测报仪等设备',
  `longitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '图片采集位置经度',
  `latitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '图片采集位置纬度',
  `image_status` tinyint NOT NULL DEFAULT 0 COMMENT '图片状态：0 待识别，1 已识别，2 识别失败',
  `image_a` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段1',
  `image_b` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段2',
  `image_c` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段3',
  `image_d` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段4',
  `image_e` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段5',
  `image_f` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段6',
  `image_g` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段7',
  `image_h` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段8',
  `image_i` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段9',
  `image_j` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段10',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`image_id`) USING BTREE,
  INDEX `idx_image_ai_type`(`image_ai_type` ASC) USING BTREE,
  INDEX `idx_image_source`(`image_source` ASC) USING BTREE,
  INDEX `idx_image_source_id`(`image_source_id` ASC) USING BTREE,
  INDEX `idx_image_park_id`(`park_id` ASC) USING BTREE,
  INDEX `idx_image_plot_id`(`plot_id` ASC) USING BTREE,
  INDEX `idx_image_device_id`(`device_id` ASC) USING BTREE,
  INDEX `idx_image_status`(`image_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 97356 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '图片信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of xwq_ai_image
-- ----------------------------

