DROP TABLE IF EXISTS `xwq_ai_pest`;
CREATE TABLE `xwq_ai_pest`  (
  `pest_id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识一条虫情识别结果',
  `record_id` bigint NOT NULL COMMENT '关联识别记录表 record_id',
  `image_id` bigint NOT NULL COMMENT '关联图片信息表 image_id',
  `pest_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '虫害名称，如蚜虫、飞虱、蓟马等',
  `pest_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '虫害标准编码',
  `pest_crop` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '作物类型，如小麦、玉米、水稻',
  `pest_confidence` decimal(6, 5) NULL DEFAULT NULL COMMENT '当前虫害类型的识别置信度',
  `pest_count` int NOT NULL DEFAULT 0 COMMENT '当前虫害类型的数量',
  `pest_total_count` int NOT NULL DEFAULT 0 COMMENT '当前图片中识别到的虫体总数',
  `pest_result` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '虫情识别结论，类型-数量',
  `pest_advice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '虫害防治建议',
  `pest_result_img_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '存放虫体检测框结果图片',
  `bbox_json` json NULL COMMENT '存放虫体检测框坐标、类别和置信度',
  `is_warning` tinyint NOT NULL DEFAULT 0 COMMENT '是否触发预警：0 否，1 是',
  `warning_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '根据虫口数量或密度生成的预警等级',
  `pest_a` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段1',
  `pest_b` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段2',
  `pest_c` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段3',
  `pest_d` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段4',
  `pest_e` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段5',
  `pest_f` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段6',
  `pest_g` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段7',
  `pest_h` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段8',
  `pest_i` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段9',
  `pest_j` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段10',
  PRIMARY KEY (`pest_id`) USING BTREE,
  INDEX `idx_pest_record_id`(`record_id` ASC) USING BTREE,
  INDEX `idx_pest_image_id`(`image_id` ASC) USING BTREE,
  INDEX `idx_pest_name`(`pest_name` ASC) USING BTREE,
  INDEX `idx_pest_crop`(`pest_crop` ASC) USING BTREE,
  INDEX `idx_pest_warning`(`is_warning` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 99062 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '虫情识别结果表' ROW_FORMAT = DYNAMIC;

