-- ----------------------------
-- Table structure for ylm_agri_task
-- ----------------------------
DROP TABLE IF EXISTS `ylm_agri_task`;
CREATE TABLE `ylm_agri_task`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务编码',
  `work_type_id` bigint NOT NULL COMMENT '农事类型（字典ID）',
  `work_method_id` bigint NOT NULL COMMENT '作业方式（字典ID）',
  `area_id` bigint NOT NULL COMMENT '区域ID',
  `location_id` bigint NULL DEFAULT NULL COMMENT '位置ID，关联location表',
  `description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任务描述',
  `photo_urls` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '照片地址',
  `create_by_id` bigint NOT NULL COMMENT '任务创建人ID',
  `operator_id` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作人ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `agri_task_a` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段A',
  `agri_task_b` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段B',
  `agri_task_c` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段C',
  `agri_task_d` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备用字段D',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_task_no`(`task_no` ASC) USING BTREE,
  INDEX `idx_work_type_id`(`work_type_id` ASC) USING BTREE,
  INDEX `idx_work_method_id`(`work_method_id` ASC) USING BTREE,
  INDEX `idx_area_id`(`area_id` ASC) USING BTREE,
  INDEX `idx_create_by_id`(`create_by_id` ASC) USING BTREE,
  INDEX `idx_ylm_agri_task_location_id`(`location_id` ASC) USING BTREE,
  CONSTRAINT `任务创建人ID` FOREIGN KEY (`create_by_id`) REFERENCES `sys_user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '农事任务表' ROW_FORMAT = DYNAMIC;

